#[derive(Clone, Debug, PartialEq, Eq, Hash)]
struct RemoteImageClientKey {
    scheme: String,
    host: String,
    port: u16,
    resolved: Vec<SocketAddr>,
}

#[derive(Clone)]
struct RemoteImageClientCacheEntry {
    client: HttpClient,
    expires_at: StdInstant,
    last_used: u64,
}

struct RemoteImageClientCache {
    entries: HashMap<RemoteImageClientKey, RemoteImageClientCacheEntry>,
    max_entries: usize,
    ttl: StdDuration,
    clock: u64,
}

impl RemoteImageClientCache {
    fn new(max_entries: usize, ttl: StdDuration) -> Self {
        Self {
            entries: HashMap::new(),
            max_entries,
            ttl,
            clock: 0,
        }
    }

    fn prune_expired(&mut self, now: StdInstant) {
        self.entries.retain(|_, entry| entry.expires_at > now);
    }

    fn get(&mut self, scheme: &str, host: &str, port: u16, now: StdInstant) -> Option<HttpClient> {
        self.prune_expired(now);
        self.clock = self.clock.saturating_add(1);
        let clock = self.clock;
        let entry = self.entries.iter_mut().find_map(|(key, entry)| {
            (key.scheme == scheme && key.host == host && key.port == port).then_some(entry)
        })?;
        entry.last_used = clock;
        Some(entry.client.clone())
    }

    fn insert(
        &mut self,
        key: RemoteImageClientKey,
        client: HttpClient,
        now: StdInstant,
    ) -> HttpClient {
        self.prune_expired(now);
        if let Some(existing) = self.get(&key.scheme, &key.host, key.port, now) {
            return existing;
        }
        if self.max_entries == 0 {
            return client;
        }
        while self.entries.len() >= self.max_entries {
            let Some(oldest) = self
                .entries
                .iter()
                .min_by_key(|(_, entry)| entry.last_used)
                .map(|(key, _)| key.clone())
            else {
                break;
            };
            self.entries.remove(&oldest);
        }
        self.clock = self.clock.saturating_add(1);
        self.entries.insert(
            key,
            RemoteImageClientCacheEntry {
                client: client.clone(),
                expires_at: now + self.ttl,
                last_used: self.clock,
            },
        );
        client
    }

    fn len(&mut self, now: StdInstant) -> usize {
        self.prune_expired(now);
        self.entries.len()
    }
}

