const ADMISSION_WAIT_BUCKET_UPPER_MILLIS: [u64; 4] = [1, 10, 100, 1_000];

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
struct AdmissionMetricsSnapshot {
    admitted_immediate: u64,
    admitted_queued: u64,
    rejected: u64,
    timed_out: u64,
    wait_buckets: [u64; 5],
}

struct AdmissionMetrics {
    admitted_immediate: AtomicU64,
    admitted_queued: AtomicU64,
    rejected: AtomicU64,
    timed_out: AtomicU64,
    wait_buckets: [AtomicU64; 5],
}

impl AdmissionMetrics {
    fn new() -> Self {
        Self {
            admitted_immediate: AtomicU64::new(0),
            admitted_queued: AtomicU64::new(0),
            rejected: AtomicU64::new(0),
            timed_out: AtomicU64::new(0),
            wait_buckets: [const { AtomicU64::new(0) }; 5],
        }
    }

    fn record_immediate(&self) {
        self.admitted_immediate
            .fetch_add(1, AtomicOrdering::Relaxed);
    }

    fn record_queued(&self, elapsed: StdDuration) {
        self.admitted_queued.fetch_add(1, AtomicOrdering::Relaxed);
        self.record_wait(elapsed);
    }

    fn record_rejected(&self) {
        self.rejected.fetch_add(1, AtomicOrdering::Relaxed);
    }

    fn record_timeout(&self, elapsed: StdDuration) {
        self.timed_out.fetch_add(1, AtomicOrdering::Relaxed);
        self.record_wait(elapsed);
    }

    fn record_wait(&self, elapsed: StdDuration) {
        let elapsed_millis = u64::try_from(elapsed.as_millis()).unwrap_or(u64::MAX);
        let bucket = ADMISSION_WAIT_BUCKET_UPPER_MILLIS
            .iter()
            .position(|upper| elapsed_millis <= *upper)
            .unwrap_or(4);
        self.wait_buckets[bucket].fetch_add(1, AtomicOrdering::Relaxed);
    }

    fn snapshot(&self) -> AdmissionMetricsSnapshot {
        AdmissionMetricsSnapshot {
            admitted_immediate: self.admitted_immediate.load(AtomicOrdering::Relaxed),
            admitted_queued: self.admitted_queued.load(AtomicOrdering::Relaxed),
            rejected: self.rejected.load(AtomicOrdering::Relaxed),
            timed_out: self.timed_out.load(AtomicOrdering::Relaxed),
            wait_buckets: std::array::from_fn(|index| {
                self.wait_buckets[index].load(AtomicOrdering::Relaxed)
            }),
        }
    }
}

fn ffmpeg_admission_metrics() -> &'static AdmissionMetrics {
    FFMPEG_ADMISSION_METRICS.get_or_init(AdmissionMetrics::new)
}

fn admission_metrics_json(snapshot: AdmissionMetricsSnapshot) -> serde_json::Value {
    serde_json::json!({
        "AdmittedImmediate": snapshot.admitted_immediate,
        "AdmittedQueued": snapshot.admitted_queued,
        "Rejected": snapshot.rejected,
        "TimedOut": snapshot.timed_out,
        "WaitMilliseconds": {
            "Le1": snapshot.wait_buckets[0],
            "Le10": snapshot.wait_buckets[1],
            "Le100": snapshot.wait_buckets[2],
            "Le1000": snapshot.wait_buckets[3],
            "Gt1000": snapshot.wait_buckets[4],
        },
    })
}

async fn acquire_ffmpeg_capacity_with_queue(
    coordinator: &TranscodeCoordinator,
    wait_queue: Arc<Semaphore>,
    queue_limit: usize,
    timeout: StdDuration,
    job_kind: TranscodeJobKind,
) -> Result<TranscodeJobPermit, String> {
    let metrics = ffmpeg_admission_metrics();
    match coordinator.try_acquire(job_kind) {
        Ok(permit) => {
            metrics.record_immediate();
            return Ok(permit);
        }
        Err(tokio::sync::TryAcquireError::Closed) => {
            metrics.record_rejected();
            return Err("FFmpeg coordinator closed".to_string());
        }
        Err(tokio::sync::TryAcquireError::NoPermits) => {}
    }

    let queue_permit = match wait_queue.clone().try_acquire_owned() {
        Ok(permit) => permit,
        Err(tokio::sync::TryAcquireError::Closed) => {
            metrics.record_rejected();
            return Err("FFmpeg wait queue closed".to_string());
        }
        Err(tokio::sync::TryAcquireError::NoPermits) => {
            // Capacity may have become available between the first fast-path
            // attempt and queue admission. Retry once before rejecting.
            return match coordinator.try_acquire(job_kind) {
                Ok(permit) => {
                    metrics.record_immediate();
                    Ok(permit)
                }
                Err(tokio::sync::TryAcquireError::Closed) => {
                    metrics.record_rejected();
                    Err("FFmpeg coordinator closed".to_string())
                }
                Err(tokio::sync::TryAcquireError::NoPermits) => {
                    metrics.record_rejected();
                    Err(format!("FFmpeg wait queue is full (limit {queue_limit})"))
                }
            };
        }
    };

    let started = StdInstant::now();
    let result = match tokio::time::timeout(timeout, coordinator.acquire(job_kind)).await {
        Ok(Ok(permit)) => {
            metrics.record_queued(started.elapsed());
            Ok(permit)
        }
        Ok(Err(error)) => {
            metrics.record_rejected();
            Err(format!("FFmpeg coordinator closed: {error}"))
        }
        Err(_) => {
            metrics.record_timeout(started.elapsed());
            Err(format!("timed out waiting for {job_kind:?} capacity"))
        }
    };
    // Queue admission protects only waiters. Active FFmpeg jobs retain solely
    // their coordinator permit and never consume a wait-queue slot.
    drop(queue_permit);
    result
}

fn remote_vod_readrate() -> (Option<u16>, Option<u16>) {
    static REMOTE_VOD_READRATE: OnceLock<(Option<u16>, Option<u16>)> = OnceLock::new();
    *REMOTE_VOD_READRATE.get_or_init(|| {
        let percent = match std::env::var("JELLYRIN_REMOTE_VOD_READRATE") {
            Ok(value) if matches!(value.trim().to_ascii_lowercase().as_str(), "0" | "off") => None,
            Ok(value) => value
                .parse::<f64>()
                .ok()
                .map(|value| (value * 100.0).round() as i64)
                .filter(|value| (1..=1000).contains(value))
                .map(|value| value as u16)
                .or(Some(110)),
            Err(_) => Some(110),
        };
        let burst = std::env::var("JELLYRIN_REMOTE_VOD_READRATE_INITIAL_BURST_SECONDS")
            .ok()
            .and_then(|value| value.parse::<u16>().ok())
            .filter(|value| *value > 0)
            .or(Some(15));
        (percent, burst)
    })
}

