async fn reserve_transcode_disk_capacity() -> Result<TranscodeDiskReservation, ApiError> {
    transcode_disk_quota()
        .reserve()
        .await
        .map_err(|error| match error {
            TranscodeDiskQuotaError::Io(error) => ApiError::from(error),
            TranscodeDiskQuotaError::Exhausted { .. } => {
                ApiError::service_unavailable("transcode storage quota is exhausted")
            }
        })
}

fn transcode_idle_timeout(is_live: bool) -> StdDuration {
    static VOD_TIMEOUT: OnceLock<StdDuration> = OnceLock::new();
    static LIVE_TIMEOUT: OnceLock<StdDuration> = OnceLock::new();
    let (cell, name, default) = if is_live {
        (
            &LIVE_TIMEOUT,
            "JELLYRIN_LIVE_TRANSCODE_IDLE_TIMEOUT_SECONDS",
            180,
        )
    } else {
        (&VOD_TIMEOUT, "JELLYRIN_TRANSCODE_IDLE_TIMEOUT_SECONDS", 60)
    };
    *cell.get_or_init(|| {
        let seconds = std::env::var(name)
            .ok()
            .and_then(|value| value.parse::<u64>().ok())
            .filter(|value| (10..=3600).contains(value))
            .unwrap_or(default);
        StdDuration::from_secs(seconds)
    })
}

fn live_hls_window() -> (u32, Option<u32>) {
    static WINDOW: OnceLock<(u32, Option<u32>)> = OnceLock::new();
    *WINDOW.get_or_init(|| {
        let list_size = std::env::var("JELLYRIN_LIVE_HLS_LIST_SIZE")
            .ok()
            .and_then(|value| value.parse::<u32>().ok())
            .filter(|value| *value == 0 || (3..=10_000).contains(value))
            .unwrap_or(20);
        let delete_threshold = (list_size > 0).then(|| {
            std::env::var("JELLYRIN_LIVE_HLS_DELETE_THRESHOLD")
                .ok()
                .and_then(|value| value.parse::<u32>().ok())
                .filter(|value| (1..=100).contains(value))
                .unwrap_or(2)
        });
        (list_size, delete_threshold)
    })
}

fn transcode_last_access_registry() -> &'static Mutex<HashMap<String, tokio::time::Instant>> {
    TRANSCODE_LAST_ACCESS.get_or_init(|| Mutex::new(HashMap::new()))
}

async fn touch_transcode_session(play_session_id: &str) {
    transcode_last_access_registry()
        .lock()
        .await
        .insert(play_session_id.to_string(), tokio::time::Instant::now());
    if let Some(registry) = LIVE_HLS_SESSIONS.get()
        && let Some(entry) = registry.lock().await.get_mut(play_session_id)
    {
        entry.updated_at = OffsetDateTime::now_utc();
    }
}

async fn forget_transcode_session_access(play_session_id: &str) {
    transcode_last_access_registry()
        .lock()
        .await
        .remove(play_session_id);
}

async fn wait_for_transcode_idle(play_session_id: &str, timeout: StdDuration) {
    let poll_interval = timeout.min(StdDuration::from_secs(5));
    loop {
        tokio::time::sleep(poll_interval).await;
        let last_access = transcode_last_access_registry()
            .lock()
            .await
            .get(play_session_id)
            .copied();
        if last_access.is_none_or(|last_access| last_access.elapsed() >= timeout) {
            return;
        }
    }
}

async fn acquire_transcode_job(
    command: &jellyrin_core::FfmpegCommandSpec,
) -> Result<TranscodeJobPermit, String> {
    let job_kind = classify_transcode_command(command);
    ensure_ffmpeg_job_allowed(job_kind)?;
    acquire_ffmpeg_capacity_with_queue(
        transcode_coordinator(),
        transcode_wait_queue().clone(),
        max_queued_ffmpeg_jobs(),
        transcode_queue_timeout(),
        job_kind,
    )
    .await
}

fn ensure_ffmpeg_job_allowed(job_kind: TranscodeJobKind) -> Result<(), String> {
    ffmpeg_job_allowed_for_mode(configured_ffmpeg_mode(), job_kind)
}

fn ffmpeg_job_allowed_for_mode(mode: FfmpegMode, job_kind: TranscodeJobKind) -> Result<(), String> {
    match mode {
        FfmpegMode::Enabled => Ok(()),
        FfmpegMode::RemuxOnly if job_kind == TranscodeJobKind::Remux => Ok(()),
        FfmpegMode::RemuxOnly => Err(format!(
            "{job_kind:?} is blocked by JELLYRIN_FFMPEG_MODE=remux-only"
        )),
        FfmpegMode::Disabled => Err(format!(
            "{job_kind:?} is blocked by JELLYRIN_FFMPEG_MODE=disabled"
        )),
    }
}

async fn acquire_auxiliary_ffmpeg_job() -> Result<TranscodeJobPermit, ApiError> {
    ensure_ffmpeg_job_allowed(TranscodeJobKind::Auxiliary)
        .map_err(ApiError::service_unavailable)?;
    acquire_ffmpeg_capacity_with_queue(
        transcode_coordinator(),
        transcode_wait_queue().clone(),
        max_queued_ffmpeg_jobs(),
        transcode_queue_timeout(),
        TranscodeJobKind::Auxiliary,
    )
    .await
    .map_err(ApiError::service_unavailable)
}

async fn run_auxiliary_ffmpeg_output(
    command: Command,
    timeout: StdDuration,
) -> Result<Output, ApiError> {
    let attempt = auxiliary_ffmpeg_telemetry().start();
    let _permit = match acquire_auxiliary_ffmpeg_job().await {
        Ok(permit) => permit,
        Err(error) => {
            attempt.finish(AuxiliaryFfmpegOutcome::CapacityUnavailable);
            return Err(error);
        }
    };
    let output = match run_bounded_command_output(
        command,
        BoundedCommandOutputOptions::new(
            timeout,
            AUXILIARY_COMMAND_STDOUT_MAX_BYTES,
            AUXILIARY_COMMAND_STDERR_MAX_BYTES,
        ),
    )
    .await
    {
        Ok(output) => output,
        Err(error) => {
            let outcome = match &error {
                BoundedCommandOutputError::TimedOut => AuxiliaryFfmpegOutcome::TimedOut,
                BoundedCommandOutputError::OutputLimitExceeded { .. } => {
                    AuxiliaryFfmpegOutcome::OutputLimited
                }
                BoundedCommandOutputError::Io(_) => AuxiliaryFfmpegOutcome::IoFailed,
            };
            attempt.finish(outcome);
            tracing::warn!(%error, "auxiliary FFmpeg command failed");
            return Err(ApiError::service_unavailable(match error {
                BoundedCommandOutputError::TimedOut => "Auxiliary FFmpeg operation timed out",
                BoundedCommandOutputError::Io(_)
                | BoundedCommandOutputError::OutputLimitExceeded { .. } => {
                    "Auxiliary FFmpeg operation failed"
                }
            }));
        }
    };
    attempt.finish(if output.status.success() {
        AuxiliaryFfmpegOutcome::Succeeded
    } else {
        AuxiliaryFfmpegOutcome::NonZeroExit
    });
    Ok(output)
}

async fn run_startup_command_output(
    command: Command,
    timeout: StdDuration,
    timeout_message: &'static str,
) -> anyhow::Result<Output> {
    run_bounded_command_output(
        command,
        BoundedCommandOutputOptions::new(
            timeout,
            STARTUP_COMMAND_STDOUT_MAX_BYTES,
            STARTUP_COMMAND_STDERR_MAX_BYTES,
        ),
    )
    .await
    .map_err(|error| match error {
        BoundedCommandOutputError::TimedOut => anyhow::anyhow!(timeout_message),
        error => anyhow::Error::new(error),
    })
}

// Registry of live HDHomeRun stream handles keyed by the resolved stream URL (/auto/vN).
// One outgoing connection is shared by N consumers of the same channel (refcount pattern).
// When refcount drops to 0 the producer task is cancelled and the handle is removed.
static LIVE_STREAM_REGISTRY: OnceLock<Mutex<HashMap<String, SharedLiveStreamHandle>>> =
    OnceLock::new();

// Monotonic counter that assigns a unique identity to each handle inserted into the registry.
// Guards carry the generation of the handle they were issued from; a stale guard from a
// previous generation is a no-op when it fires against a newer-generation handle.
static LIVE_STREAM_GENERATION: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(1);

// Broadcast capacity: enough buffering so a slow consumer doesn't cause the fast path to block.
const LIVE_STREAM_BROADCAST_CAPACITY: usize = 256;
/// Global safety cap across distinct active Live TV upstream producers. Per-tuner
/// `TunerCount` remains an additional, usually lower limit.
const LIVE_TV_MAX_DISTINCT_PRODUCERS: usize = 64;
const LIVE_TUNER_UNASSIGNED_HOST_ID: &str = "jellyrin:unassigned";
use jellyrin_core::{LIVE_TV_REMOTE_USER_AGENT, LIVE_TV_XTREAM_MAX_IMPORT_LIMIT};

// In-memory registry for live TV HLS transcode sessions.
// Keyed by play_session_id; mirrors the VOD transcode session lifecycle but without
// requiring a media_items DB row (live TV channels are not in the media_items table).
static LIVE_HLS_SESSIONS: OnceLock<Mutex<HashMap<String, LiveHlsSessionEntry>>> = OnceLock::new();
static LIVE_TV_USER_DATA_WRITE_LOCK: OnceLock<Mutex<()>> = OnceLock::new();

// Longer readiness timeout for live TV HLS (compared to VOD 5s) because an HTTP live
// stream source may need a few extra seconds for ffmpeg to buffer the first segment.
// Only applied to live TV sessions; VOD keeps the original 5s limit.
const LIVE_HLS_READINESS_TIMEOUT_SECS: u64 = 15;

// Registry of active live TV recordings keyed by timer_id.
// Stores the cancel sender and the recording file path so callers can cancel in-progress
// recordings and resolve the path for streaming. Mirrors LIVE_STREAM_REGISTRY layout.
static LIVE_TV_RECORDING_REGISTRY: OnceLock<Mutex<HashMap<String, LiveTvRecordingHandle>>> =
    OnceLock::new();

static LIVE_TV_RECORDING_STARTING: OnceLock<StdMutex<HashMap<String, LiveTvRecordingStartEntry>>> =
    OnceLock::new();
static LIVE_TV_RECORDING_START_GENERATION: std::sync::atomic::AtomicU64 =
    std::sync::atomic::AtomicU64::new(1);

// Shared Live TV tuner-slot accounting across direct TS, live HLS and recordings. Reusable
// upstreams key leases by tuner host + channel identity; unshared provider proxies use a unique
// per-response identity so every independently opened upstream honors TunerCount.
static LIVE_TUNER_LEASES: OnceLock<StdMutex<HashMap<LiveTunerLeaseKey, LiveTunerLease>>> =
    OnceLock::new();
#[cfg(test)]
static TEST_RUST_WASI_HOST_BINARY_PATH: OnceLock<StdMutex<Option<PathBuf>>> = OnceLock::new();
#[cfg(test)]
static TEST_DOTNET_HOST_BINARY_PATH: OnceLock<StdMutex<Option<PathBuf>>> = OnceLock::new();
#[cfg(test)]
static TEST_PROVIDER_EGRESS_PROXY: OnceLock<StdMutex<Option<String>>> = OnceLock::new();

#[derive(Debug, Clone, Eq, PartialEq, Hash)]
struct LiveTunerLeaseKey {
    tuner_host_id: String,
    channel_url: String,
}

#[derive(Debug)]
struct LiveTunerLease {
    refcount: usize,
}

struct LiveTunerLeaseGuard {
    key: LiveTunerLeaseKey,
}

impl Drop for LiveTunerLeaseGuard {
    fn drop(&mut self) {
        release_live_tuner_lease(&self.key);
    }
}

fn release_live_tuner_lease(key: &LiveTunerLeaseKey) {
    let Ok(mut leases) = live_tuner_lease_registry().lock() else {
        tracing::error!("live tuner lease registry lock poisoned while releasing lease");
        return;
    };
    if let Some(lease) = leases.get_mut(key) {
        lease.refcount = lease.refcount.saturating_sub(1);
        if lease.refcount == 0 {
            leases.remove(key);
        }
    }
}

fn live_tuner_lease_registry() -> &'static StdMutex<HashMap<LiveTunerLeaseKey, LiveTunerLease>> {
    LIVE_TUNER_LEASES.get_or_init(|| StdMutex::new(HashMap::new()))
}

fn with_live_tuner_leases<R>(
    f: impl FnOnce(&mut HashMap<LiveTunerLeaseKey, LiveTunerLease>) -> R,
) -> Result<R, ApiError> {
    match live_tuner_lease_registry().lock() {
        Ok(mut leases) => Ok(f(&mut leases)),
        Err(_) => {
            tracing::error!("live tuner lease registry lock poisoned");
            Err(ApiError::internal(
                "live tuner lease registry lock poisoned",
            ))
        }
    }
}

struct LiveTvRecordingHandle {
    // Dropping or sending cancels the in-progress recording task.
    _cancel: oneshot::Sender<()>,
    // Path of the in-progress recording file; retained for potential InProgress stream lookup.
    #[allow(dead_code)]
    path: String,
}

struct LiveTvRecordingStartGuard {
    timer_id: String,
    generation: u64,
    cancellation: tokio::sync::watch::Receiver<bool>,
}

struct LiveTvRecordingStartEntry {
    generation: u64,
    cancellation: tokio::sync::watch::Sender<bool>,
    task: Option<tokio::task::JoinHandle<()>>,
}

impl LiveTvRecordingStartGuard {
    fn cancelled(&self) -> bool {
        *self.cancellation.borrow() || runtime_shutdown_started()
    }
}

impl Drop for LiveTvRecordingStartGuard {
    fn drop(&mut self) {
        let Ok(mut starting) = live_tv_recording_starting_registry().lock() else {
            tracing::error!("live TV recording starting registry lock poisoned while releasing");
            return;
        };
        if starting
            .get(&self.timer_id)
            .is_some_and(|entry| entry.generation == self.generation)
        {
            starting.remove(&self.timer_id);
        }
    }
}

fn live_tv_recording_starting_registry()
-> &'static StdMutex<HashMap<String, LiveTvRecordingStartEntry>> {
    LIVE_TV_RECORDING_STARTING.get_or_init(|| StdMutex::new(HashMap::new()))
}

fn reserve_live_tv_recording_start(timer_id: &str) -> Option<LiveTvRecordingStartGuard> {
    if runtime_shutdown_started() {
        return None;
    }
    let normalized = timer_id.to_ascii_lowercase();
    let Ok(mut starting) = live_tv_recording_starting_registry().lock() else {
        tracing::error!("live TV recording starting registry lock poisoned");
        return None;
    };
    // The second terminal-state check closes the race between the first load and this mutex.
    // Once shutdown stores `true`, its sweep either observes this entry or this insertion fails.
    if runtime_shutdown_started() || starting.contains_key(&normalized) {
        return None;
    }
    let generation =
        LIVE_TV_RECORDING_START_GENERATION.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    let (cancellation, cancellation_rx) = tokio::sync::watch::channel(false);
    starting.insert(
        normalized.clone(),
        LiveTvRecordingStartEntry {
            generation,
            cancellation,
            task: None,
        },
    );
    Some(LiveTvRecordingStartGuard {
        timer_id: normalized,
        generation,
        cancellation: cancellation_rx,
    })
}

fn retain_live_tv_recording_start_task(
    timer_id: &str,
    generation: u64,
    task: tokio::task::JoinHandle<()>,
) -> Result<(), tokio::task::JoinHandle<()>> {
    let Ok(mut starting) = live_tv_recording_starting_registry().lock() else {
        tracing::error!("live TV recording starting registry lock poisoned while retaining task");
        return Err(task);
    };
    let Some(entry) = starting.get_mut(timer_id) else {
        return Err(task);
    };
    if entry.generation != generation || entry.task.is_some() || runtime_shutdown_started() {
        return Err(task);
    }
    entry.task = Some(task);
    Ok(())
}

fn live_tv_recording_registry() -> &'static Mutex<HashMap<String, LiveTvRecordingHandle>> {
    LIVE_TV_RECORDING_REGISTRY.get_or_init(|| Mutex::new(HashMap::new()))
}

async fn active_live_tv_recording_timer_ids() -> Vec<String> {
    let registry = live_tv_recording_registry().lock().await;
    registry.keys().cloned().collect()
}

async fn live_tv_recording_is_active(timer_id: &str) -> bool {
    let registry = live_tv_recording_registry().lock().await;
    registry
        .keys()
        .any(|active| active.eq_ignore_ascii_case(timer_id))
}

struct SharedLiveStreamHandle {
    refcount: usize,
    // Unique identity for this handle; incremented each time a new handle is inserted.
    // Guards must match this generation before they may decrement or remove the entry.
    generation: u64,
    sender: broadcast::Sender<Bytes>,
    // Dropping this cancels the producer task via the oneshot channel.
    _cancel: oneshot::Sender<()>,
    _tuner_lease: Option<LiveTunerLeaseGuard>,
}

fn live_stream_registry() -> &'static Mutex<HashMap<String, SharedLiveStreamHandle>> {
    LIVE_STREAM_REGISTRY.get_or_init(|| Mutex::new(HashMap::new()))
}

fn ensure_live_stream_producer_capacity(
    registry: &HashMap<String, SharedLiveStreamHandle>,
    stream_key: &str,
) -> Result<(), ApiError> {
    if registry.contains_key(stream_key) || registry.len() < LIVE_TV_MAX_DISTINCT_PRODUCERS {
        Ok(())
    } else {
        Err(ApiError::service_unavailable(
            "Global Live TV producer limit has been reached",
        ))
    }
}

