#[derive(Debug, Clone)]
struct AuthFailureState {
    failures: u32,
    locked_until_epoch: Option<u64>,
    last_failure_epoch: u64,
}

#[derive(Default)]
struct AuthFailureRegistry {
    entries: HashMap<String, AuthFailureState>,
    operations_since_prune: usize,
}

/// A bounded registry that keeps only weak references to per-key async locks.
///
/// Live callers retain the strong references, so the same key is serialized while work is in
/// flight. Dead entries are pruned periodically. If every bounded slot is live, new keys share
/// the overflow lock until it becomes idle; this preserves correctness at the cost of temporarily
/// serializing unrelated work instead of allowing the registry to grow without limit.
struct WeakKeyedLockRegistry<K> {
    entries: HashMap<K, Weak<Mutex<()>>>,
    overflow: Arc<Mutex<()>>,
    operations_since_prune: usize,
    max_entries: usize,
}

impl<K> WeakKeyedLockRegistry<K>
where
    K: Eq + std::hash::Hash,
{
    fn new(max_entries: usize) -> Self {
        Self {
            entries: HashMap::new(),
            overflow: Arc::new(Mutex::new(())),
            operations_since_prune: 0,
            max_entries,
        }
    }

    fn lock_for(&mut self, key: K) -> Arc<Mutex<()>> {
        if let Some(lock) = self.entries.get(&key).and_then(Weak::upgrade) {
            return lock;
        }
        self.entries.remove(&key);

        // While an overflow borrower is alive, every unregistered key must keep using the same
        // lock. Creating a keyed lock early could let identical keys execute concurrently.
        if Arc::strong_count(&self.overflow) > 1 {
            return Arc::clone(&self.overflow);
        }

        self.operations_since_prune = self.operations_since_prune.saturating_add(1);
        if self.operations_since_prune >= KEYED_LOCK_PRUNE_INTERVAL
            || self.entries.len() >= self.max_entries
        {
            self.prune_dead();
        }

        if self.entries.len() >= self.max_entries {
            return Arc::clone(&self.overflow);
        }

        let lock = Arc::new(Mutex::new(()));
        self.entries.insert(key, Arc::downgrade(&lock));
        lock
    }

    fn prune_dead(&mut self) {
        self.entries.retain(|_, lock| lock.strong_count() > 0);
        self.operations_since_prune = 0;
    }

    #[cfg(test)]
    fn entry_count(&self) -> usize {
        self.entries.len()
    }
}

