/// Never compress a byte-range response.
///
/// Gzipping a `206 Partial Content` body leaves its `Content-Range` describing the original bytes
/// rather than the bytes on the wire, so a client seeking inside a stream reads the wrong offsets.
#[derive(Clone, Copy)]
struct NotForByteRanges;

impl tower_http::compression::predicate::Predicate for NotForByteRanges {
    fn should_compress<B>(&self, response: &axum::http::Response<B>) -> bool
    where
        B: http_body::Body,
    {
        response.status() != StatusCode::PARTIAL_CONTENT
            && !response.headers().contains_key(header::CONTENT_RANGE)
    }
}

/// Which responses the public router may gzip.
///
/// tower-http's default predicate skips only gRPC, images and server-sent events. Media is neither,
/// so the default would spend CPU recompressing already compressed audio and video on every byte
/// served, and would corrupt byte-range responses. Exclude both, and keep the default size and
/// content-encoding rules for everything else.
fn response_compression_predicate() -> impl tower_http::compression::predicate::Predicate {
    use tower_http::compression::predicate::{DefaultPredicate, NotForContentType, Predicate};

    DefaultPredicate::new()
        .and(NotForByteRanges)
        .and(NotForContentType::const_new("video/"))
        .and(NotForContentType::const_new("audio/"))
        .and(NotForContentType::const_new(
            "application/vnd.apple.mpegurl",
        ))
        .and(NotForContentType::const_new("application/x-mpegurl"))
}

fn safe_http_request_trace_span<B>(request: &axum::http::Request<B>) -> tracing::Span {
    // Jellyfin clients commonly authenticate stream and image requests with `api_key` in the
    // query string. Never hand the complete URI to tracing: span fields are inherited by every
    // request/response event and would otherwise turn access logs into a durable token store.
    tracing::info_span!(
        "http_request",
        method = %request.method(),
        path = %safe_http_request_trace_path(request.uri())
    )
}

fn safe_http_request_trace_path(uri: &Uri) -> &str {
    uri.path()
}

pub async fn reconcile_transcode_sessions_on_startup(db: &Database) -> anyhow::Result<usize> {
    let sessions = db.stale_transcode_sessions_on_startup().await?;
    let count = sessions.len();
    for session in sessions {
        SessionService::new(db)
            .update_transcode_status(&session.play_session_id, "stopped")
            .await?;
        cleanup_hls_transcode_files(&session.output_path).await;
    }
    Ok(count)
}

#[derive(Debug, Default, Clone, Copy, Eq, PartialEq)]
pub struct RuntimeShutdownReport {
    pub external_plugin_hosts: usize,
    pub streaming_bodies_signalled: usize,
    pub transcodes_signalled: usize,
    pub live_streams_cancelled: usize,
    pub recordings_cancelled: usize,
    pub live_hls_sessions_cleared: usize,
    pub recording_start_reservations_cleared: usize,
    pub tuner_leases_cleared: usize,
    pub timed_out: bool,
}

/// Stops process-backed runtime work before the HTTP server finishes draining.
///
/// This operation is terminal for the current process. It is deliberately
/// idempotent so the server can call it once from Axum's graceful-shutdown
/// future and once more after `serve` returns to catch work that raced with the
/// first sweep.
pub async fn shutdown_runtime_resources() -> RuntimeShutdownReport {
    let mut report = RuntimeShutdownReport {
        streaming_bodies_signalled: signal_runtime_shutdown(),
        ..RuntimeShutdownReport::default()
    };
    if tokio::time::timeout(RUNTIME_RESOURCE_SHUTDOWN_TIMEOUT, async {
        shutdown_runtime_resources_inner(&mut report).await;
        // Catch one last registration after the bounded drain, then clear
        // terminal bookkeeping while still inside the global budget.
        cancel_registered_runtime_work(&mut report).await;
        let late_hosts = take_external_plugin_host_slots().await;
        report.external_plugin_hosts = report
            .external_plugin_hosts
            .saturating_add(late_hosts.len());
        drop(late_hosts);
        clear_terminal_runtime_registries(&mut report).await;
    })
    .await
    .is_err()
    {
        report.timed_out = true;
        tracing::warn!(
            timeout_seconds = RUNTIME_RESOURCE_SHUTDOWN_TIMEOUT.as_secs(),
            "runtime resource shutdown reached its global timeout"
        );
        // Never await another potentially contended lock after the global
        // deadline. A try-lock sweep still cancels everything immediately
        // available and preserves the hard shutdown bound.
        try_cancel_registered_runtime_work(&mut report);
        try_clear_terminal_runtime_registries(&mut report);
    }

    tracing::info!(
        external_plugin_hosts = report.external_plugin_hosts,
        streaming_bodies_signalled = report.streaming_bodies_signalled,
        transcodes_signalled = report.transcodes_signalled,
        live_streams_cancelled = report.live_streams_cancelled,
        recordings_cancelled = report.recordings_cancelled,
        timed_out = report.timed_out,
        "runtime resources stopped"
    );
    report
}

fn runtime_shutdown_signal() -> &'static tokio::sync::watch::Sender<bool> {
    RUNTIME_SHUTDOWN_SIGNAL.get_or_init(|| {
        let (sender, _receiver) = tokio::sync::watch::channel(false);
        sender
    })
}

fn subscribe_runtime_shutdown() -> tokio::sync::watch::Receiver<bool> {
    runtime_shutdown_signal().subscribe()
}

fn runtime_shutdown_started() -> bool {
    RUNTIME_SHUTDOWN_STARTED.load(AtomicOrdering::SeqCst)
}

fn signal_runtime_shutdown() -> usize {
    // This terminal barrier is published before any registry sweep. Recording tasks check it
    // while holding the active-recording mutex, so an insertion either precedes (and is observed
    // by) the sweep or is rejected.
    RUNTIME_SHUTDOWN_STARTED.store(true, AtomicOrdering::SeqCst);
    let signal = runtime_shutdown_signal();
    let receivers = signal.receiver_count();
    signal.send_replace(true);
    receivers
}

async fn shutdown_runtime_resources_inner(report: &mut RuntimeShutdownReport) {
    cancel_registered_runtime_work(report).await;

    let host_slots = take_external_plugin_host_slots().await;
    report.external_plugin_hosts = report
        .external_plugin_hosts
        .saturating_add(host_slots.len());
    shutdown_external_plugin_host_slots(host_slots).await;

    let deadline = tokio::time::Instant::now() + RUNTIME_RESOURCE_DRAIN_GRACE;
    loop {
        // Catch registrations that were already in flight when shutdown began.
        cancel_registered_runtime_work(report).await;
        let late_hosts = take_external_plugin_host_slots().await;
        report.external_plugin_hosts = report
            .external_plugin_hosts
            .saturating_add(late_hosts.len());
        shutdown_external_plugin_host_slots(late_hosts).await;
        if !registered_runtime_work_pending().await {
            break;
        }
        if tokio::time::Instant::now() >= deadline {
            report.timed_out = true;
            break;
        }
        tokio::time::sleep(RUNTIME_RESOURCE_DRAIN_POLL_INTERVAL).await;
    }
}

async fn take_external_plugin_host_slots() -> Vec<Arc<Mutex<Option<ExternalPluginHost>>>> {
    let Some(hosts) = EXTERNAL_PLUGIN_HOSTS.get() else {
        return Vec::new();
    };
    hosts.lock().await.drain().map(|(_, slot)| slot).collect()
}

async fn shutdown_external_plugin_host_slots(slots: Vec<Arc<Mutex<Option<ExternalPluginHost>>>>) {
    for slot in slots {
        let mut guard = slot.lock_owned().await;
        stop_locked_external_plugin_host(&mut guard).await;
    }
}

fn signal_transcode_stops(stops: HashMap<String, oneshot::Sender<()>>) -> usize {
    let count = stops.len();
    for (_, stop) in stops {
        let _ = stop.send(());
    }
    count
}

fn drain_live_stream_handles(
    registry: &mut HashMap<String, SharedLiveStreamHandle>,
) -> Vec<SharedLiveStreamHandle> {
    registry.drain().map(|(_, handle)| handle).collect()
}

fn drain_recording_handles(
    registry: &mut HashMap<String, LiveTvRecordingHandle>,
) -> Vec<LiveTvRecordingHandle> {
    registry.drain().map(|(_, handle)| handle).collect()
}

fn drain_recording_start_tasks(
    registry: &mut HashMap<String, LiveTvRecordingStartEntry>,
) -> (usize, Vec<tokio::task::JoinHandle<()>>) {
    let entries = registry.drain().map(|(_, entry)| entry).collect::<Vec<_>>();
    let count = entries.len();
    let mut tasks = Vec::with_capacity(count);
    for mut entry in entries {
        entry.cancellation.send_replace(true);
        if let Some(task) = entry.task.take() {
            tasks.push(task);
        }
    }
    (count, tasks)
}

async fn cancel_recording_start_tasks(report: &mut RuntimeShutdownReport) {
    let (count, tasks) = match LIVE_TV_RECORDING_STARTING.get() {
        Some(registry) => match registry.lock() {
            Ok(mut registry) => drain_recording_start_tasks(&mut registry),
            Err(_) => {
                tracing::warn!("live TV recording start registry is poisoned at shutdown");
                return;
            }
        },
        None => return,
    };
    report.recording_start_reservations_cleared = report
        .recording_start_reservations_cleared
        .saturating_add(count);
    // Signal every task first, then abort and join retained tasks. Awaiting an aborted Tokio task
    // is bounded by the outer runtime-resource deadline and prevents detached STARTING work.
    for task in &tasks {
        task.abort();
    }
    for task in tasks {
        let _ = task.await;
    }
}

async fn cancel_registered_runtime_work(report: &mut RuntimeShutdownReport) {
    cancel_recording_start_tasks(report).await;

    if let Some(registry) = TRANSCODE_STOPS.get() {
        let stops = std::mem::take(&mut *registry.lock().await);
        report.transcodes_signalled = report
            .transcodes_signalled
            .saturating_add(signal_transcode_stops(stops));
    }

    if let Some(registry) = LIVE_STREAM_REGISTRY.get() {
        let handles = {
            let mut registry = registry.lock().await;
            drain_live_stream_handles(&mut registry)
        };
        report.live_streams_cancelled = report.live_streams_cancelled.saturating_add(handles.len());
        drop(handles);
    }

    if let Some(registry) = LIVE_TV_RECORDING_REGISTRY.get() {
        let handles = {
            let mut registry = registry.lock().await;
            drain_recording_handles(&mut registry)
        };
        report.recordings_cancelled = report.recordings_cancelled.saturating_add(handles.len());
        drop(handles);
    }
}

async fn registered_runtime_work_pending() -> bool {
    if let Some(registry) = TRANSCODE_STOPS.get()
        && !registry.lock().await.is_empty()
    {
        return true;
    }
    if let Some(registry) = LIVE_STREAM_REGISTRY.get()
        && !registry.lock().await.is_empty()
    {
        return true;
    }
    if let Some(registry) = LIVE_TV_RECORDING_REGISTRY.get()
        && !registry.lock().await.is_empty()
    {
        return true;
    }
    if let Some(registry) = EXTERNAL_PLUGIN_HOSTS.get()
        && !registry.lock().await.is_empty()
    {
        return true;
    }
    if let Some(registry) = LIVE_HLS_SESSIONS.get()
        && registry
            .lock()
            .await
            .values()
            .any(live_hls_session_is_active)
    {
        return true;
    }
    if let Some(registry) = LIVE_TV_RECORDING_STARTING.get() {
        return registry
            .lock()
            .map(|starting| !starting.is_empty())
            .unwrap_or(false);
    }
    false
}

async fn clear_terminal_runtime_registries(report: &mut RuntimeShutdownReport) {
    if let Some(registry) = LIVE_HLS_SESSIONS.get() {
        let mut registry = registry.lock().await;
        report.live_hls_sessions_cleared = report
            .live_hls_sessions_cleared
            .saturating_add(registry.len());
        registry.clear();
    }
    if let Some(registry) = TRANSCODE_LAST_ACCESS.get() {
        registry.lock().await.clear();
    }
    cancel_recording_start_tasks(report).await;
    if let Some(registry) = LIVE_TUNER_LEASES.get() {
        match registry.lock() {
            Ok(mut leases) => {
                report.tuner_leases_cleared =
                    report.tuner_leases_cleared.saturating_add(leases.len());
                leases.clear();
            }
            Err(_) => tracing::warn!("live tuner lease registry is poisoned at shutdown"),
        }
    }
}

fn try_cancel_registered_runtime_work(report: &mut RuntimeShutdownReport) {
    if let Some(registry) = LIVE_TV_RECORDING_STARTING.get()
        && let Ok(mut registry) = registry.try_lock()
    {
        let (count, tasks) = drain_recording_start_tasks(&mut registry);
        report.recording_start_reservations_cleared = report
            .recording_start_reservations_cleared
            .saturating_add(count);
        for task in tasks {
            task.abort();
        }
    }
    if let Some(registry) = TRANSCODE_STOPS.get()
        && let Ok(mut registry) = registry.try_lock()
    {
        let stops = std::mem::take(&mut *registry);
        report.transcodes_signalled = report
            .transcodes_signalled
            .saturating_add(signal_transcode_stops(stops));
    }
    if let Some(registry) = LIVE_STREAM_REGISTRY.get()
        && let Ok(mut registry) = registry.try_lock()
    {
        let handles = drain_live_stream_handles(&mut registry);
        report.live_streams_cancelled = report.live_streams_cancelled.saturating_add(handles.len());
        drop(handles);
    }
    if let Some(registry) = LIVE_TV_RECORDING_REGISTRY.get()
        && let Ok(mut registry) = registry.try_lock()
    {
        let handles = drain_recording_handles(&mut registry);
        report.recordings_cancelled = report.recordings_cancelled.saturating_add(handles.len());
        drop(handles);
    }
    if let Some(hosts) = EXTERNAL_PLUGIN_HOSTS.get()
        && let Ok(mut hosts) = hosts.try_lock()
    {
        let slots = hosts.drain().map(|(_, slot)| slot).collect::<Vec<_>>();
        report.external_plugin_hosts = report.external_plugin_hosts.saturating_add(slots.len());
        drop(slots);
    }
}

fn try_clear_terminal_runtime_registries(report: &mut RuntimeShutdownReport) {
    if let Some(registry) = LIVE_HLS_SESSIONS.get()
        && let Ok(mut registry) = registry.try_lock()
    {
        report.live_hls_sessions_cleared = report
            .live_hls_sessions_cleared
            .saturating_add(registry.len());
        registry.clear();
    }
    if let Some(registry) = TRANSCODE_LAST_ACCESS.get()
        && let Ok(mut registry) = registry.try_lock()
    {
        registry.clear();
    }
    if let Some(registry) = LIVE_TV_RECORDING_STARTING.get()
        && let Ok(mut registry) = registry.try_lock()
    {
        let (count, tasks) = drain_recording_start_tasks(&mut registry);
        report.recording_start_reservations_cleared = report
            .recording_start_reservations_cleared
            .saturating_add(count);
        for task in tasks {
            task.abort();
        }
    }
    if let Some(registry) = LIVE_TUNER_LEASES.get()
        && let Ok(mut leases) = registry.try_lock()
    {
        report.tuner_leases_cleared = report.tuner_leases_cleared.saturating_add(leases.len());
        leases.clear();
    }
}

#[derive(Debug, Default, Clone, Copy, Eq, PartialEq)]
pub struct LiveTvRecordingStartupRecovery {
    pub removed_stale_recordings: usize,
    pub removed_expired_timers: usize,
    pub restarted_recordings: usize,
}

#[derive(Debug, Default, Clone, Copy, Eq, PartialEq)]
pub struct LiveTvTimerSchedulerRun {
    pub removed_expired_timers: usize,
    pub started_recordings: usize,
}

pub async fn reconcile_live_tv_recordings_on_startup(
    db: &Database,
    log_dir: &std::path::Path,
) -> anyhow::Result<LiveTvRecordingStartupRecovery> {
    let Some(mut config) = ConfigurationService::new(db).get("livetv").await? else {
        return Ok(LiveTvRecordingStartupRecovery::default());
    };

    let active_timer_ids: Vec<String> = {
        let registry = live_tv_recording_registry().lock().await;
        registry.keys().cloned().collect()
    };
    let now = OffsetDateTime::now_utc();
    let mut recovery = LiveTvRecordingStartupRecovery::default();
    let mut changed = false;
    let mut stale_recording_paths = Vec::new();

    if let Some(recordings) = config
        .get("Recordings")
        .and_then(serde_json::Value::as_array)
        .cloned()
    {
        let mut kept_recordings = Vec::new();
        for recording in recordings {
            let in_progress = json_string_field(&recording, "Status")
                .is_some_and(|status| status.eq_ignore_ascii_case("InProgress"));
            let timer_id = json_string_field(&recording, "TimerId");
            let has_active_task = timer_id.as_deref().is_some_and(|timer_id| {
                active_timer_ids
                    .iter()
                    .any(|active| active.eq_ignore_ascii_case(timer_id))
            });

            if in_progress && !has_active_task {
                recovery.removed_stale_recordings += 1;
                changed = true;
                if let Ok(path) = live_tv_recording_path(&recording) {
                    stale_recording_paths.push(path);
                }
                continue;
            }

            kept_recordings.push(recording);
        }
        config["Recordings"] = serde_json::json!(kept_recordings);
    }

    let mut timers_to_restart = Vec::new();
    if let Some(timers) = config
        .get("Timers")
        .and_then(serde_json::Value::as_array)
        .cloned()
    {
        let mut kept_timers = Vec::new();
        for timer in timers {
            if live_tv_timer_is_terminal(&timer) {
                kept_timers.push(timer);
                continue;
            }

            let recording_end = live_tv_timer_recording_end(&timer);
            if recording_end.is_some_and(|end| end <= now) {
                recovery.removed_expired_timers += 1;
                changed = true;
                continue;
            }

            if live_tv_timer_start_date(&timer).is_some_and(|start| start <= now)
                && recording_end.is_some_and(|end| end > now)
            {
                let timer_id = json_string_field(&timer, "Id").unwrap_or_default();
                let has_active_task = active_timer_ids
                    .iter()
                    .any(|active| active.eq_ignore_ascii_case(&timer_id));
                if !has_active_task {
                    timers_to_restart.push(timer.clone());
                }
            }

            kept_timers.push(timer);
        }
        config["Timers"] = serde_json::json!(kept_timers);
    }

    for path in stale_recording_paths {
        match tokio::fs::remove_file(&path).await {
            Ok(()) => {}
            Err(err) if err.kind() == std::io::ErrorKind::NotFound => {}
            Err(err) => {
                tracing::warn!(path = %path.display(), "failed to delete stale Live TV recording: {err}");
            }
        }
    }

    if changed {
        ConfigurationService::new(db)
            .set("livetv", live_tv_configuration_json(config))
            .await?;
    }

    for timer in timers_to_restart {
        let Some(channel_id) = json_string_field(&timer, "ChannelId").filter(|id| !id.is_empty())
        else {
            continue;
        };
        let Ok(channel) = live_tv_channel_by_id(db, &channel_id).await else {
            continue;
        };
        let channel_url = if live_tv_channel_uses_opaque_provider(&channel) {
            format!(
                "opaque:{}",
                stable_entity_id("livetv-recording", &channel_id)
            )
        } else {
            let Ok(channel_path) = live_tv_channel_path(&channel) else {
                continue;
            };
            if !live_tv_channel_is_remote(&channel_path) {
                continue;
            }
            channel_path.to_string_lossy().into_owned()
        };
        let (tuner_host_id, tuner_count) = live_tv_channel_tuner_limit(db, &channel).await;
        let timer_id = json_string_field(&timer, "Id").unwrap_or_default();
        let Some(start_guard) = reserve_live_tv_recording_start(&timer_id) else {
            continue;
        };

        spawn_live_tv_recording(
            db.clone(),
            log_dir.to_path_buf(),
            timer,
            channel_url,
            tuner_host_id,
            tuner_count,
            start_guard,
        );
        recovery.restarted_recordings += 1;
    }

    Ok(recovery)
}

pub async fn run_due_live_tv_timers(state: &AppState) -> anyhow::Result<LiveTvTimerSchedulerRun> {
    let Some(mut config) = ConfigurationService::new(&state.db).get("livetv").await? else {
        return Ok(LiveTvTimerSchedulerRun::default());
    };

    let active_timer_ids = active_live_tv_recording_timer_ids().await;
    let now = OffsetDateTime::now_utc();
    let mut result = LiveTvTimerSchedulerRun::default();
    let mut changed = false;
    let mut timers_to_start = Vec::new();

    if let Some(timers) = config
        .get("Timers")
        .and_then(serde_json::Value::as_array)
        .cloned()
    {
        let mut kept_timers = Vec::new();
        for timer in timers {
            if live_tv_timer_is_terminal(&timer) {
                kept_timers.push(timer);
                continue;
            }

            let recording_end = live_tv_timer_recording_end(&timer);
            if recording_end.is_some_and(|end| end <= now) {
                result.removed_expired_timers += 1;
                changed = true;
                continue;
            }

            if live_tv_timer_start_date(&timer).is_some_and(|start| start <= now)
                && recording_end.is_some_and(|end| end > now)
            {
                let timer_id = json_string_field(&timer, "Id").unwrap_or_default();
                let has_active_task = active_timer_ids
                    .iter()
                    .any(|active| active.eq_ignore_ascii_case(&timer_id));
                if !has_active_task {
                    timers_to_start.push(timer.clone());
                }
            }

            kept_timers.push(timer);
        }
        config["Timers"] = serde_json::json!(kept_timers);
    }

    if changed {
        state
            .db
            .update_named_configuration("livetv", live_tv_configuration_json(config))
            .await?;
    }

    for timer in timers_to_start {
        if maybe_spawn_live_tv_recording(state, &timer).await {
            result.started_recordings += 1;
        }
    }

    Ok(result)
}

pub fn spawn_periodic_live_tv_timer_scheduler(state: AppState) -> tokio::task::JoinHandle<()> {
    tokio::spawn(async move {
        loop {
            match run_due_live_tv_timers(&state).await {
                Ok(run) if run.removed_expired_timers > 0 || run.started_recordings > 0 => {
                    tracing::info!(
                        removed_expired_timers = run.removed_expired_timers,
                        started_recordings = run.started_recordings,
                        "processed due Live TV timers"
                    );
                }
                Ok(_) => {}
                Err(error) => {
                    tracing::warn!(%error, "failed to process due Live TV timers");
                }
            }
            tokio::time::sleep(std::time::Duration::from_secs(
                LIVE_TV_TIMER_SCHEDULER_INTERVAL_SECONDS,
            ))
            .await;
        }
    })
}

pub fn spawn_periodic_xtream_media_sync_scheduler(state: AppState) -> tokio::task::JoinHandle<()> {
    tokio::spawn(async move {
        loop {
            match maybe_run_due_xtream_media_sync(&state.db).await {
                Ok(true) => tracing::info!("started scheduled Xtream media sync"),
                Ok(false) => {}
                Err(error) => {
                    tracing::warn!(?error, "failed to evaluate Xtream media sync schedule")
                }
            }
            tokio::time::sleep(std::time::Duration::from_secs(60)).await;
        }
    })
}

/// Spawn the file watcher and its scan consumer.
/// Returns the watcher handle (must be kept alive) and the consumer task handle.
pub async fn spawn_file_watcher_with_consumer(
    state: AppState,
) -> Option<(
    notify_debouncer_mini::Debouncer<notify::RecommendedWatcher>,
    tokio::task::JoinHandle<()>,
)> {
    let (watcher, mut rx) = match file_watcher::start_file_watcher(&state.db).await {
        Ok(result) => result,
        Err(error) => {
            tracing::warn!(?error, "failed to start file watcher");
            return None;
        }
    };
    let consumer = tokio::spawn(async move {
        while let Some(events) = rx.recv().await {
            let changes = file_watcher::deduplicate_changes(events);
            if changes.is_empty() {
                continue;
            }
            tracing::info!(count = changes.len(), "file watcher detected changes");
            let mut scanned = 0usize;
            for change in &changes {
                match change.change_type {
                    file_watcher::FileChangeType::Created
                    | file_watcher::FileChangeType::Modified => {
                        match FileService::new(&state.db)
                            .scan_single_file(&change.path)
                            .await
                        {
                            Ok(true) => scanned += 1,
                            Ok(false) => {}
                            Err(error) => {
                                tracing::warn!(
                                    ?error,
                                    path = ?change.path,
                                    "failed to scan changed file"
                                );
                            }
                        }
                    }
                    file_watcher::FileChangeType::Deleted => {
                        let path_str = change.path.to_string_lossy().to_string();
                        match FileService::new(&state.db).mark_missing(&path_str).await {
                            Ok(true) => scanned += 1,
                            Ok(false) => {}
                            Err(error) => {
                                tracing::warn!(
                                    ?error,
                                    path = ?change.path,
                                    "failed to mark file as missing"
                                );
                            }
                        }
                    }
                }
            }
            if scanned > 0 {
                tracing::info!(scanned, "incremental scan completed");
                let _ = populate_image_tags_for_library(&state.db).await;
                let _ = dlna::notify_dlna_content_directory_changed(&state.db).await;
            }
        }
    });
    Some((watcher, consumer))
}

async fn maybe_run_due_xtream_media_sync(db: &Database) -> Result<bool, ApiError> {
    // Skip if the xtream plugin is not active
    if let Ok(Some(plugin)) = db.installed_plugin_json(BUILTIN_XTREAM_PLUGIN_ID).await {
        let status = json_string_field(&plugin, "Status").unwrap_or_default();
        if !status.eq_ignore_ascii_case("Active") {
            return Ok(false);
        }
    } else {
        return Ok(false);
    }
    recover_stale_xtream_media_sync_runs(db).await?;
    if db
        .current_task_run(XTREAM_MEDIA_SYNC_TASK_KEY)
        .await?
        .is_some()
    {
        return Ok(false);
    }
    let triggers = xtream_media_sync_triggers_json(db).await?;
    let last_result = TaskService::new(db)
        .last_result(XTREAM_MEDIA_SYNC_TASK_KEY)
        .await?;
    if !scheduled_task_due(&triggers, last_result.as_ref()) {
        return Ok(false);
    }
    start_xtream_media_sync_task(db.clone(), None).await?;
    Ok(true)
}

fn scheduled_task_due(triggers: &serde_json::Value, last_result: Option<&TaskRun>) -> bool {
    let now = OffsetDateTime::now_utc();
    let Some(triggers) = triggers.as_array() else {
        return false;
    };
    triggers
        .iter()
        .any(|trigger| scheduled_trigger_due(trigger, last_result, now))
}

fn scheduled_trigger_due(
    trigger: &serde_json::Value,
    last_result: Option<&TaskRun>,
    now: OffsetDateTime,
) -> bool {
    let trigger_type = json_string_field(trigger, "Type")
        .unwrap_or_default()
        .to_ascii_lowercase();
    if trigger_type.contains("interval") {
        let interval_ticks = trigger
            .get("IntervalTicks")
            .and_then(json_value_i64)
            .unwrap_or(864_000_000_000_i64)
            .max(600_000_000);
        let interval = Duration::seconds(interval_ticks / 10_000_000);
        let last_time = last_result
            .and_then(|run| run.completed_at)
            .unwrap_or(now - interval - Duration::seconds(1));
        return now - last_time >= interval;
    }
    if trigger_type.contains("weekly") {
        // WeeklyTrigger: { Type, DayOfWeek: "Monday", TimeOfDayTicks }
        let Some(target_weekday) =
            json_string_field(trigger, "DayOfWeek").and_then(|day| weekday_from_name(&day))
        else {
            return false;
        };
        if now.weekday() != target_weekday {
            return false;
        }
        let time_of_day_ticks = trigger
            .get("TimeOfDayTicks")
            .and_then(json_value_i64)
            .unwrap_or(3 * 60 * 60 * 10_000_000)
            .clamp(0, 86_399 * 10_000_000);
        let now_seconds =
            i64::from(now.hour()) * 3600 + i64::from(now.minute()) * 60 + i64::from(now.second());
        let due_seconds = time_of_day_ticks / 10_000_000;
        if now_seconds < due_seconds {
            return false;
        }
        let Some(last_time) = last_result.and_then(|run| run.completed_at) else {
            return true;
        };
        // Only run once on the target day: skip if already run today.
        return last_time.date() < now.date();
    }
    if trigger_type.contains("daily") {
        let time_of_day_ticks = trigger
            .get("TimeOfDayTicks")
            .and_then(json_value_i64)
            .unwrap_or(3 * 60 * 60 * 10_000_000)
            .clamp(0, 86_399 * 10_000_000);
        let now_seconds =
            i64::from(now.hour()) * 3600 + i64::from(now.minute()) * 60 + i64::from(now.second());
        let due_seconds = time_of_day_ticks / 10_000_000;
        if now_seconds < due_seconds {
            return false;
        }
        let Some(last_time) = last_result.and_then(|run| run.completed_at) else {
            return true;
        };
        return last_time.date() < now.date();
    }
    false
}

/// Parse a Jellyfin `DayOfWeek` name into a `time::Weekday` (case-insensitive).
fn weekday_from_name(name: &str) -> Option<time::Weekday> {
    use time::Weekday::*;
    match name.trim().to_ascii_lowercase().as_str() {
        "monday" => Some(Monday),
        "tuesday" => Some(Tuesday),
        "wednesday" => Some(Wednesday),
        "thursday" => Some(Thursday),
        "friday" => Some(Friday),
        "saturday" => Some(Saturday),
        "sunday" => Some(Sunday),
        _ => None,
    }
}

pub fn spawn_periodic_transcode_cleanup(db: Database) -> tokio::task::JoinHandle<()> {
    tokio::spawn(async move {
        loop {
            match cleanup_stale_hls_transcodes(&db).await {
                Ok(cleaned_count) if cleaned_count > 0 => {
                    tracing::info!(count = cleaned_count, "cleaned stale HLS transcode outputs");
                }
                Ok(_) => {}
                Err(error) => {
                    tracing::warn!(%error, "failed to clean stale HLS transcode outputs");
                }
            }
            tokio::time::sleep(std::time::Duration::from_secs(
                TERMINAL_TRANSCODE_CLEANUP_INTERVAL_SECONDS,
            ))
            .await;
        }
    })
}

pub async fn validate_ffmpeg_runtime() -> anyhow::Result<()> {
    let configured_mode = std::env::var("JELLYRIN_FFMPEG_MODE").ok();
    let mode = parse_ffmpeg_mode(configured_mode.as_deref()).map_err(anyhow::Error::msg)?;
    let mut ffprobe_version_command = Command::new("ffprobe");
    ffprobe_version_command.arg("-version").stdin(Stdio::null());
    let ffprobe_version = run_startup_command_output(
        ffprobe_version_command,
        StdDuration::from_secs(10),
        "ffprobe version check timed out",
    )
    .await?;
    if !ffprobe_version.status.success() {
        anyhow::bail!("ffprobe executable is not usable");
    }

    if mode == FfmpegMode::Disabled {
        tracing::info!("FFmpeg execution is disabled; validated ffprobe only");
        return Ok(());
    }

    let mut ffmpeg_version_command = Command::new("ffmpeg");
    ffmpeg_version_command.arg("-version").stdin(Stdio::null());
    let ffmpeg_version = run_startup_command_output(
        ffmpeg_version_command,
        StdDuration::from_secs(10),
        "ffmpeg version check timed out",
    )
    .await?;
    if !ffmpeg_version.status.success() {
        anyhow::bail!("ffmpeg executable is not usable");
    }

    if mode == FfmpegMode::Enabled {
        let mut encoder_command = Command::new("ffmpeg");
        encoder_command
            .args(["-hide_banner", "-encoders"])
            .stdin(Stdio::null());
        let encoders = run_startup_command_output(
            encoder_command,
            StdDuration::from_secs(10),
            "ffmpeg encoder capability check timed out",
        )
        .await?;
        let encoder_text = String::from_utf8_lossy(&encoders.stdout);
        if !encoders.status.success()
            || !encoder_text.contains("libx264")
            || !encoder_text.lines().any(|line| line.contains(" aac "))
        {
            anyhow::bail!("ffmpeg must provide libx264 and AAC encoders");
        }
    }

    let mut muxer_command = Command::new("ffmpeg");
    muxer_command
        .args(["-hide_banner", "-muxers"])
        .stdin(Stdio::null());
    let muxers = run_startup_command_output(
        muxer_command,
        StdDuration::from_secs(10),
        "ffmpeg muxer capability check timed out",
    )
    .await?;
    let muxer_text = String::from_utf8_lossy(&muxers.stdout);
    if !muxers.status.success() || !muxer_text.lines().any(|line| line.contains(" hls ")) {
        anyhow::bail!("ffmpeg must provide the HLS muxer");
    }

    validate_ffmpeg_component_listing(
        "-protocols",
        "protocol",
        &[
            "file", "pipe", "http", "https", "tcp", "tls", "udp", "crypto",
        ],
    )
    .await?;
    validate_ffmpeg_component_listing(
        "-demuxers",
        "demuxer",
        &[
            "mpegts", "mov", "matroska", "avi", "asf", "mp3", "flac", "aac", "ac3", "eac3", "ogg",
            "wav", "flv", "hls",
        ],
    )
    .await?;
    validate_ffmpeg_component_listing(
        "-muxers",
        "muxer",
        &["adts", "hls", "latm", "mov", "mp4", "mpegts", "webvtt"],
    )
    .await?;
    validate_ffmpeg_component_listing("-decoders", "decoder", &["aac"]).await?;
    validate_ffmpeg_component_listing(
        "-bsfs",
        "bitstream filter",
        &[
            "h264_mp4toannexb",
            "hevc_mp4toannexb",
            "extract_extradata",
            "aac_adtstoasc",
            "vp9_superframe",
            "vvc_mp4toannexb",
        ],
    )
    .await?;

    tracing::info!(?mode, "validated configured FFmpeg runtime capabilities");
    Ok(())
}

async fn validate_ffmpeg_component_listing(
    listing_flag: &str,
    component_kind: &str,
    required: &[&str],
) -> anyhow::Result<()> {
    let mut command = Command::new("ffmpeg");
    command
        .args(["-hide_banner", listing_flag])
        .stdin(Stdio::null());
    let output = run_startup_command_output(
        command,
        StdDuration::from_secs(10),
        "ffmpeg capability listing timed out",
    )
    .await?;
    if !output.status.success() {
        anyhow::bail!("ffmpeg {component_kind} capability listing failed");
    }
    let listing = String::from_utf8_lossy(&output.stdout);
    let available = ffmpeg_listing_components(listing_flag, &listing);
    let missing = required
        .iter()
        .copied()
        .filter(|component| !available.contains(*component))
        .collect::<Vec<_>>();
    if !missing.is_empty() {
        anyhow::bail!(
            "ffmpeg is missing required {component_kind} capabilities: {}",
            missing.join(",")
        );
    }
    Ok(())
}

fn ffmpeg_listing_components<'a>(listing_flag: &str, listing: &'a str) -> HashSet<&'a str> {
    listing
        .lines()
        .filter_map(|line| {
            let columns = line.split_whitespace().collect::<Vec<_>>();
            match listing_flag {
                "-demuxers" | "-muxers" | "-decoders" | "-encoders" => columns.get(1).copied(),
                "-protocols" | "-parsers" | "-bsfs" if columns.len() == 1 => {
                    columns.first().copied()
                }
                _ => None,
            }
        })
        .flat_map(|token| token.split(','))
        .filter(|token| {
            !token.is_empty()
                && token
                    .bytes()
                    .all(|byte| byte.is_ascii_alphanumeric() || byte == b'_')
        })
        .collect()
}

/// Materializes the immutable FFmpeg process and encoder configuration before
/// the server accepts traffic. Request paths reuse these values and never need
/// to read their environment variables independently.
pub fn initialize_transcode_config() {
    jellyrin_core::configured_hls_encoding_config();
    configured_multimedia_process_config();
}

pub async fn cleanup_stale_hls_transcodes(db: &Database) -> anyhow::Result<usize> {
    let retention = terminal_transcode_cleanup_retention();
    let terminal_count = cleanup_terminal_hls_transcodes(db, retention).await?;
    let live_terminal_count = cleanup_terminal_live_hls_sessions(retention).await;
    let orphan_count =
        cleanup_orphan_hls_transcode_dirs(db, transcode_temp_root(), retention).await?;
    Ok(terminal_count + live_terminal_count + orphan_count)
}

async fn cleanup_terminal_live_hls_sessions(older_than: Duration) -> usize {
    let cutoff = OffsetDateTime::now_utc() - older_than;
    let stale_entries = {
        let mut registry = live_hls_session_registry().lock().await;
        let mut candidates = registry
            .values()
            .filter(|entry| {
                matches!(entry.status.as_str(), "completed" | "failed" | "stopped")
                    && entry.updated_at <= cutoff
            })
            .map(|entry| (entry.updated_at, entry.play_session_id.clone()))
            .collect::<Vec<_>>();
        candidates.sort_by_key(|(updated_at, _)| *updated_at);
        candidates
            .into_iter()
            .filter_map(|(_, play_session_id)| registry.remove(&play_session_id))
            .collect::<Vec<_>>()
    };

    let stale_count = stale_entries.len();
    for entry in stale_entries {
        if let Some(output_path) = quarantine_live_hls_session_output(&entry).await {
            cleanup_hls_transcode_files(&output_path).await;
        }
        forget_transcode_session_access(&entry.play_session_id).await;
    }
    stale_count
}

async fn quarantine_live_hls_session_output(entry: &LiveHlsSessionEntry) -> Option<String> {
    let layout = HlsTranscodeLayout::from_media_playlist_path(&entry.output_path);
    let session_dir =
        match validate_hls_cleanup_dir(&transcode_temp_root(), &layout.session_dir).await {
            HlsCleanupDirValidation::Safe(session_dir) => session_dir,
            HlsCleanupDirValidation::Missing => return None,
            HlsCleanupDirValidation::Unsafe => {
                tracing::warn!("refused unsafe HLS transcode directory quarantine");
                return None;
            }
        };
    let parent = session_dir.parent()?;
    let file_name = FsPath::new(&entry.output_path).file_name()?;
    let quarantine_dir = parent.join(format!(".jellyrin-evicted-{}", Uuid::new_v4().simple()));
    match tokio::fs::rename(&session_dir, &quarantine_dir).await {
        Ok(()) => Some(quarantine_dir.join(file_name).to_string_lossy().to_string()),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => None,
        Err(error) => {
            tracing::warn!(
                path = %session_dir.display(),
                %error,
                "failed to quarantine terminal live HLS output"
            );
            None
        }
    }
}

pub async fn cleanup_terminal_hls_transcodes(
    db: &Database,
    older_than: Duration,
) -> anyhow::Result<usize> {
    let sessions = db
        .terminal_transcode_sessions_older_than(older_than)
        .await?;
    let mut count = 0;
    for session in sessions {
        if cleanup_hls_transcode_files(&session.output_path).await {
            count += 1;
        }
    }
    Ok(count)
}

pub async fn cleanup_orphan_hls_transcode_dirs(
    db: &Database,
    root: impl AsRef<FsPath>,
    older_than: Duration,
) -> anyhow::Result<usize> {
    let root = root.as_ref();
    let mut known_session_dirs = HashSet::new();
    for output_path in db.transcode_session_output_paths().await? {
        known_session_dirs
            .insert(HlsTranscodeLayout::from_media_playlist_path(output_path).session_dir);
    }
    if let Some(registry) = LIVE_HLS_SESSIONS.get() {
        known_session_dirs.extend(registry.lock().await.values().map(|entry| {
            HlsTranscodeLayout::from_media_playlist_path(&entry.output_path).session_dir
        }));
    }

    let mut cleaned_count = 0;
    let mut entries = match tokio::fs::read_dir(root).await {
        Ok(entries) => entries,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(0),
        Err(error) => return Err(error.into()),
    };
    while let Some(entry) = entries.next_entry().await? {
        let path = entry.path();
        let file_type = entry.file_type().await?;
        if !file_type.is_dir() || known_session_dirs.contains(&path) {
            continue;
        }
        if !hls_transcode_dir_is_cleanup_candidate(&path).await {
            continue;
        }
        if !hls_transcode_dir_is_old_enough(&path, older_than).await {
            continue;
        }
        if cleanup_hls_transcode_dir_in_root(root, &path).await {
            cleaned_count += 1;
        }
    }
    Ok(cleaned_count)
}

async fn hls_transcode_dir_is_cleanup_candidate(path: &FsPath) -> bool {
    let mut entries = match tokio::fs::read_dir(path).await {
        Ok(entries) => entries,
        Err(_) => return false,
    };
    let mut is_empty = true;
    while let Ok(Some(entry)) = entries.next_entry().await {
        is_empty = false;
        let file_name = entry.file_name();
        let file_name = file_name.to_string_lossy();
        if file_name == HLS_MEDIA_PLAYLIST_NAME
            || (file_name.starts_with("segment_") && file_name.ends_with(".ts"))
        {
            return true;
        }
    }
    is_empty
}

async fn hls_transcode_dir_is_old_enough(path: &FsPath, older_than: Duration) -> bool {
    if older_than <= Duration::ZERO {
        return true;
    }
    let Ok(metadata) = tokio::fs::metadata(path).await else {
        return false;
    };
    let Ok(modified_at) = metadata.modified() else {
        return false;
    };
    SystemTime::now()
        .duration_since(modified_at)
        .is_ok_and(|age| age >= older_than.unsigned_abs())
}

async fn backup_restore_snapshot_json(db: &Database) -> Result<serde_json::Value, ApiError> {
    Ok(serde_json::json!({
        "Version": 1,
        "StartupConfig": db.startup_config().await?,
        "SystemConfigurationPayloads": system_configuration_payloads_backup_json(
            db.system_configuration_payloads().await?
        ),
        "NamedConfigurations": named_configurations_backup_json(
            ConfigurationService::new(db).all().await?,
        ),
        "BrandingConfiguration": branding_backup_json(db.branding_config().await?),
        "Users": backup_users_json(db.users().await?),
        "VirtualFolders": backup_virtual_folders_json(
            LibraryService::new(db).virtual_folders().await?,
        ),
        "MediaMetadata": backup_media_metadata_json(db).await?,
        "Files": backup_files_decision_json(),
        "Plugins": backup_plugins_snapshot_json(db).await?
    }))
}

async fn restore_backup_data(db: &Database, snapshot: &serde_json::Value) -> Result<(), ApiError> {
    let version = snapshot
        .get("Version")
        .and_then(serde_json::Value::as_i64)
        .ok_or_else(|| ApiError::bad_request("Backup snapshot version is missing"))?;
    if version != 1 {
        return Err(ApiError::bad_request(format!(
            "Unsupported backup snapshot version {version}"
        )));
    }
    let startup = snapshot.get("StartupConfig").ok_or_else(|| {
        ApiError::bad_request("Backup manifest does not contain startup configuration")
    })?;
    let system_payloads = snapshot.get("SystemConfigurationPayloads").ok_or_else(|| {
        ApiError::bad_request("Backup manifest does not contain system configuration")
    })?;
    let branding = snapshot.get("BrandingConfiguration").ok_or_else(|| {
        ApiError::bad_request("Backup manifest does not contain branding configuration")
    })?;

    let configuration = ConfigurationService::new(db);
    configuration
        .update_startup(startup_config_from_backup(startup)?)
        .await?;
    configuration
        .update_system(system_configuration_payloads_from_backup(system_payloads)?)
        .await?;
    restore_named_configurations_from_backup(db, snapshot.get("NamedConfigurations")).await?;
    configuration
        .update_branding(branding_from_backup(branding)?)
        .await?;
    restore_users_from_backup(db, snapshot.get("Users")).await?;
    restore_virtual_folders_from_backup(db, snapshot.get("VirtualFolders")).await?;
    restore_media_metadata_from_backup(db, snapshot.get("MediaMetadata")).await?;
    restore_plugins_from_backup(db, snapshot.get("Plugins")).await?;
    Ok(())
}

fn startup_config_from_backup(value: &serde_json::Value) -> Result<StartupConfig, ApiError> {
    serde_json::from_value(value.clone()).map_err(|error| {
        ApiError::bad_request(format!("Invalid backup startup configuration: {error}"))
    })
}

fn system_configuration_payloads_backup_json(
    payloads: SystemConfigurationPayloads,
) -> serde_json::Value {
    serde_json::json!({
        "ContentTypes": payloads.content_types,
        "MetadataOptions": payloads.metadata_options,
        "PathSubstitutions": payloads.path_substitutions,
        "PluginRepositories": payloads.plugin_repositories,
        "ServerOptions": payloads.server_options
    })
}

fn system_configuration_payloads_from_backup(
    value: &serde_json::Value,
) -> Result<SystemConfigurationPayloads, ApiError> {
    Ok(SystemConfigurationPayloads {
        content_types: required_backup_value(value, "ContentTypes")?,
        metadata_options: required_backup_value(value, "MetadataOptions")?,
        path_substitutions: required_backup_value(value, "PathSubstitutions")?,
        plugin_repositories: required_backup_value(value, "PluginRepositories")?,
        server_options: required_backup_value(value, "ServerOptions")?,
    })
}

fn named_configurations_backup_json(
    configurations: Vec<NamedConfigurationPayload>,
) -> serde_json::Value {
    serde_json::Value::Array(
        configurations
            .into_iter()
            .map(|configuration| {
                serde_json::json!({
                    "Key": configuration.key,
                    "Payload": configuration.payload
                })
            })
            .collect(),
    )
}

async fn restore_named_configurations_from_backup(
    db: &Database,
    value: Option<&serde_json::Value>,
) -> Result<(), ApiError> {
    let Some(value) = value else {
        return Ok(());
    };
    let configurations = value
        .as_array()
        .ok_or_else(|| ApiError::bad_request("Backup named configurations must be an array"))?;
    for configuration in configurations {
        let key = configuration
            .get("Key")
            .and_then(serde_json::Value::as_str)
            .ok_or_else(|| ApiError::bad_request("Backup named configuration key is missing"))?;
        if key.trim().is_empty() {
            return Err(ApiError::bad_request(
                "Backup named configuration key must not be empty",
            ));
        }
        let payload = configuration.get("Payload").cloned().ok_or_else(|| {
            ApiError::bad_request("Backup named configuration payload is missing")
        })?;
        ConfigurationService::new(db).set(key, payload).await?;
    }
    Ok(())
}

