async fn restore_users_from_backup(
    db: &Database,
    value: Option<&serde_json::Value>,
) -> Result<(), ApiError> {
    let Some(value) = value else {
        return Ok(());
    };
    let users = value
        .as_array()
        .ok_or_else(|| ApiError::bad_request("Backup users must be an array"))?;
    if users.is_empty() {
        return Err(ApiError::bad_request(
            "Backup users must contain at least one administrator",
        ));
    }
    let mut restored_profiles = Vec::new();
    for user in users {
        let object = user
            .as_object()
            .ok_or_else(|| ApiError::bad_request("Backup user entry must be an object"))?;
        let name = object
            .get("Name")
            .and_then(serde_json::Value::as_str)
            .map(str::trim)
            .filter(|name| !name.is_empty())
            .ok_or_else(|| ApiError::bad_request("Backup user entry is missing Name"))?;
        let is_administrator = object
            .get("IsAdministrator")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false);
        let is_disabled = object
            .get("IsDisabled")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false);
        restored_profiles.push((name.to_string(), is_administrator, is_disabled));
    }
    if !restored_profiles
        .iter()
        .any(|(_, is_administrator, is_disabled)| *is_administrator && !*is_disabled)
    {
        return Err(ApiError::bad_request(
            "Backup users must contain at least one enabled administrator",
        ));
    }

    let mut existing_by_name = db
        .users()
        .await?
        .into_iter()
        .map(|user| (user.name.to_lowercase(), user))
        .collect::<HashMap<_, _>>();
    for (name, is_administrator, is_disabled) in restored_profiles {
        let key = name.to_lowercase();
        let user = if let Some(existing) = existing_by_name.get(&key) {
            existing.clone()
        } else {
            let created = UserService::new(db).create(&name, None).await?;
            existing_by_name.insert(key, created.clone());
            created
        };
        UserService::new(db)
            .update_profile(
                user.id,
                &name,
                is_administrator,
                is_disabled,
                &user.sync_play_access,
            )
            .await?;
    }
    Ok(())
}

async fn restore_virtual_folders_from_backup(
    db: &Database,
    value: Option<&serde_json::Value>,
) -> Result<(), ApiError> {
    let Some(value) = value else {
        return Ok(());
    };
    let folders = value
        .as_array()
        .ok_or_else(|| ApiError::bad_request("Backup virtual folders must be an array"))?;
    for folder in folders {
        let object = folder.as_object().ok_or_else(|| {
            ApiError::bad_request("Backup virtual folder entry must be an object")
        })?;
        let name = object
            .get("Name")
            .and_then(serde_json::Value::as_str)
            .map(str::trim)
            .filter(|name| !name.is_empty())
            .ok_or_else(|| ApiError::bad_request("Backup virtual folder is missing Name"))?;
        let collection_type = object
            .get("CollectionType")
            .and_then(serde_json::Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty());
        let locations = object
            .get("Locations")
            .and_then(serde_json::Value::as_array)
            .ok_or_else(|| ApiError::bad_request("Backup virtual folder is missing Locations"))?;
        let mut restored_locations = Vec::new();
        for location in locations {
            let location = location
                .as_str()
                .map(str::trim)
                .filter(|location| !location.is_empty())
                .ok_or_else(|| {
                    ApiError::bad_request("Backup virtual folder location must be a string")
                })?;
            if !backup_restore_path_is_safe(location) {
                return Err(ApiError::bad_request(format!(
                    "Backup virtual folder location is not safe to restore: {location}"
                )));
            }
            restored_locations.push(location.to_string());
        }
        LibraryService::new(db)
            .upsert_virtual_folder(name, collection_type, restored_locations)
            .await?;
    }
    Ok(())
}

async fn restore_media_metadata_from_backup(
    db: &Database,
    value: Option<&serde_json::Value>,
) -> Result<(), ApiError> {
    let Some(value) = value else {
        return Ok(());
    };
    let entries = value
        .as_array()
        .ok_or_else(|| ApiError::bad_request("Backup media metadata must be an array"))?;
    if entries.is_empty() {
        return Ok(());
    }
    scan_all_library_items(db).await?;
    let items_by_path = db
        .media_items()
        .await?
        .into_iter()
        .map(|item| (item.path.clone(), item))
        .collect::<HashMap<_, _>>();
    for entry in entries {
        let object = entry.as_object().ok_or_else(|| {
            ApiError::bad_request("Backup media metadata entry must be an object")
        })?;
        let path = object
            .get("Path")
            .and_then(serde_json::Value::as_str)
            .map(str::trim)
            .filter(|path| !path.is_empty())
            .ok_or_else(|| ApiError::bad_request("Backup media metadata entry is missing Path"))?;
        if !backup_restore_path_is_safe(path) {
            return Err(ApiError::bad_request(format!(
                "Backup media metadata path is not safe to restore: {path}"
            )));
        }
        let metadata = object.get("Metadata").cloned().ok_or_else(|| {
            ApiError::bad_request("Backup media metadata entry is missing Metadata")
        })?;
        if let Some(item) = items_by_path.get(path) {
            MediaService::new(db)
                .update_metadata(item.id, metadata)
                .await?;
        }
    }
    Ok(())
}

async fn restore_plugins_from_backup(
    db: &Database,
    value: Option<&serde_json::Value>,
) -> Result<(), ApiError> {
    let Some(value) = value else {
        return Ok(());
    };
    if value
        .get("Supported")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false)
    {
        db.restore_plugin_platform_snapshot(value).await?;
    }
    Ok(())
}

fn backup_restore_path_is_safe(path: &str) -> bool {
    let path = FsPath::new(path);
    if !path.is_absolute() {
        return false;
    }
    if path
        .components()
        .any(|component| matches!(component, std::path::Component::ParentDir))
    {
        return false;
    }
    if path.parent().is_none() {
        return false;
    }
    let dangerous_roots = [
        FsPath::new("/bin"),
        FsPath::new("/boot"),
        FsPath::new("/dev"),
        FsPath::new("/etc"),
        FsPath::new("/proc"),
        FsPath::new("/root"),
        FsPath::new("/run"),
        FsPath::new("/sbin"),
        FsPath::new("/sys"),
        FsPath::new("/usr"),
        FsPath::new("/var"),
    ];
    !dangerous_roots
        .iter()
        .any(|dangerous_root| path.starts_with(dangerous_root))
}

fn required_backup_value(
    value: &serde_json::Value,
    field: &str,
) -> Result<serde_json::Value, ApiError> {
    value
        .get(field)
        .cloned()
        .ok_or_else(|| ApiError::bad_request(format!("Backup restore data is missing {field}")))
}

fn backup_manifest_json(manifest: &BackupManifest) -> serde_json::Value {
    serde_json::json!({
        "ServerVersion": manifest.server_version,
        "BackupEngineVersion": manifest.backup_engine_version,
        "DateCreated": format_time_for_json(manifest.created_at),
        "Path": manifest.path,
        "Options": manifest.options,
        "SnapshotSummary": backup_snapshot_summary_json(manifest.restore_snapshot.as_ref())
    })
}

fn backup_snapshot_summary_json(snapshot: Option<&serde_json::Value>) -> serde_json::Value {
    let Some(snapshot) = snapshot else {
        return serde_json::json!({
            "HasRestoreData": false
        });
    };
    serde_json::json!({
        "HasRestoreData": true,
        "Users": snapshot
            .get("Users")
            .and_then(serde_json::Value::as_array)
            .map_or(0, Vec::len),
        "VirtualFolders": snapshot
            .get("VirtualFolders")
            .and_then(serde_json::Value::as_array)
            .map_or(0, Vec::len),
        "MediaMetadata": snapshot
            .get("MediaMetadata")
            .and_then(serde_json::Value::as_array)
            .map_or(0, Vec::len),
        "NamedConfigurations": snapshot
            .get("NamedConfigurations")
            .and_then(serde_json::Value::as_array)
            .map_or(0, Vec::len),
        "FilesMode": snapshot
            .get("Files")
            .and_then(|files| files.get("Mode"))
            .and_then(serde_json::Value::as_str)
            .unwrap_or("unknown"),
        "PluginsMode": snapshot
            .get("Plugins")
            .and_then(|plugins| plugins.get("Mode"))
            .and_then(serde_json::Value::as_str)
            .unwrap_or("unknown"),
        "InstalledPlugins": snapshot
            .get("Plugins")
            .and_then(|plugins| plugins.get("InstalledPlugins"))
            .and_then(|installed| installed.get("Count"))
            .and_then(serde_json::Value::as_i64)
            .unwrap_or(0)
    })
}

#[derive(Debug, Default)]
struct JellyfinMigrationReport {
    source_name: String,
    applied: bool,
    users: usize,
    libraries: usize,
    media_metadata: usize,
    user_data: usize,
    playlists: usize,
    collections: usize,
    task_history: usize,
    scanned_items: usize,
    imported_users: usize,
    imported_libraries: usize,
    imported_media_metadata: usize,
    imported_user_data: usize,
    imported_lists: usize,
    imported_task_history: usize,
    unsupported: BTreeMap<&'static str, String>,
    warnings: Vec<String>,
}

impl JellyfinMigrationReport {
    fn json(&self, backup_path: Option<&str>) -> serde_json::Value {
        serde_json::json!({
            "SourcePolicy": {
                "Mode": "json-export",
                "OriginalDatabaseMutation": "never",
                "ReadOnly": true,
                "BackupRequired": true,
                "BackupPath": backup_path
            },
            "SourceName": self.source_name,
            "DryRun": !self.applied,
            "Applied": self.applied,
            "Rollback": {
                "Automatic": false,
                "Procedure": "Restore the BackupPath manifest created before import, or restore the exported Jellyfin source externally if the source was changed outside Jellyrin."
            },
            "Counts": {
                "Users": self.users,
                "Libraries": self.libraries,
                "MediaMetadata": self.media_metadata,
                "UserData": self.user_data,
                "Playlists": self.playlists,
                "Collections": self.collections,
                "TaskHistory": self.task_history,
                "ScannedItems": self.scanned_items
            },
            "Imported": {
                "Users": self.imported_users,
                "Libraries": self.imported_libraries,
                "MediaMetadata": self.imported_media_metadata,
                "UserData": self.imported_user_data,
                "Lists": self.imported_lists,
                "TaskHistory": self.imported_task_history
            },
            "Families": {
                "MediaHierarchy": "libraries-and-scanned-paths",
                "Ancestors": "derived-from-library-scan",
                "Streams": "derived-from-media-scan",
                "Chapters": "unsupported-decided",
                "Subtitles": "derived-from-media-scan",
                "Lyrics": "unsupported-decided",
                "KeyframesTrickplay": "unsupported-decided",
                "Playlists": "imported-by-name-and-item-path",
                "Collections": "imported-by-name-and-item-path",
                "UserData": "imported-by-user-and-item-path",
                "TaskHistory": "imported-as-terminal-task-runs",
                "Transcodes": "unsupported-runtime-state",
                "PackageState": "unsupported-decided"
            },
            "Unsupported": self.unsupported,
            "Warnings": self.warnings
        })
    }
}

async fn analyze_jellyfin_migration(
    db: &Database,
    payload: &JellyfinMigrationBody,
) -> Result<JellyfinMigrationReport, ApiError> {
    let data = migration_data_object(payload)?;
    let mut report = JellyfinMigrationReport {
        source_name: payload
            .source_name
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .unwrap_or("jellyfin-json-export")
            .to_string(),
        applied: false,
        users: migration_array(data, "Users").len(),
        libraries: migration_libraries(data).len(),
        media_metadata: migration_media_entries(data).len(),
        user_data: migration_array(data, "UserData").len(),
        playlists: migration_array(data, "Playlists").len(),
        collections: migration_array(data, "Collections").len(),
        task_history: migration_array(data, "TaskHistory").len(),
        ..Default::default()
    };
    report.unsupported = jellyfin_migration_unsupported_map(data);
    validate_migration_payload(data, &mut report)?;
    report.scanned_items = db.media_items().await?.len();
    Ok(report)
}

async fn apply_jellyfin_migration(
    db: &Database,
    payload: &JellyfinMigrationBody,
) -> Result<JellyfinMigrationReport, ApiError> {
    let mut report = analyze_jellyfin_migration(db, payload).await?;
    let data = migration_data_object(payload)?;

    report.imported_users = import_jellyfin_users(db, data).await?;
    report.imported_libraries = import_jellyfin_libraries(db, data).await?;
    report.scanned_items = scan_all_library_items(db).await?;
    report.imported_media_metadata = import_jellyfin_media_metadata(db, data).await?;
    report.imported_user_data = import_jellyfin_user_data(db, data).await?;
    report.imported_lists = import_jellyfin_lists(db, data).await?;
    report.imported_task_history = import_jellyfin_task_history(db, data).await?;
    Ok(report)
}

fn migration_data_object(
    payload: &JellyfinMigrationBody,
) -> Result<&serde_json::Map<String, serde_json::Value>, ApiError> {
    payload
        .data
        .as_object()
        .ok_or_else(|| ApiError::bad_request("Jellyfin migration Data must be an object"))
}

fn migration_array<'a>(
    data: &'a serde_json::Map<String, serde_json::Value>,
    field: &str,
) -> &'a [serde_json::Value] {
    data.get(field)
        .and_then(serde_json::Value::as_array)
        .map(Vec::as_slice)
        .unwrap_or(&[])
}

fn migration_libraries(data: &serde_json::Map<String, serde_json::Value>) -> &[serde_json::Value] {
    data.get("Libraries")
        .or_else(|| data.get("VirtualFolders"))
        .and_then(serde_json::Value::as_array)
        .map(Vec::as_slice)
        .unwrap_or(&[])
}

fn migration_media_entries(
    data: &serde_json::Map<String, serde_json::Value>,
) -> &[serde_json::Value] {
    data.get("Media")
        .or_else(|| data.get("MediaMetadata"))
        .and_then(serde_json::Value::as_array)
        .map(Vec::as_slice)
        .unwrap_or(&[])
}

fn validate_migration_payload(
    data: &serde_json::Map<String, serde_json::Value>,
    report: &mut JellyfinMigrationReport,
) -> Result<(), ApiError> {
    for library in migration_libraries(data) {
        let object = library
            .as_object()
            .ok_or_else(|| ApiError::bad_request("Jellyfin migration library must be an object"))?;
        let locations = object
            .get("Locations")
            .or_else(|| object.get("Paths"))
            .and_then(serde_json::Value::as_array)
            .ok_or_else(|| {
                ApiError::bad_request("Jellyfin migration library is missing Locations")
            })?;
        for location in locations {
            let location = location
                .as_str()
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .ok_or_else(|| {
                    ApiError::bad_request("Jellyfin migration library location must be a string")
                })?;
            if !backup_restore_path_is_safe(location) {
                return Err(ApiError::bad_request(format!(
                    "Jellyfin migration library location is not safe to import: {location}"
                )));
            }
        }
    }

    for media in migration_media_entries(data) {
        let object = media.as_object().ok_or_else(|| {
            ApiError::bad_request("Jellyfin migration media entry must be an object")
        })?;
        if let Some(path) = migration_string_field(object, &["Path", "FilePath"]) {
            if !backup_restore_path_is_safe(&path) {
                return Err(ApiError::bad_request(format!(
                    "Jellyfin migration media path is not safe to import: {path}"
                )));
            }
        } else {
            report
                .warnings
                .push("Media entry without Path/FilePath will be skipped.".to_string());
        }
    }
    Ok(())
}

fn jellyfin_migration_unsupported_map(
    data: &serde_json::Map<String, serde_json::Value>,
) -> BTreeMap<&'static str, String> {
    let mut unsupported = BTreeMap::new();
    for (field, reason) in [
        (
            "Chapters",
            "No chapter persistence importer is available yet.",
        ),
        (
            "Lyrics",
            "Lyrics files are not imported from Jellyfin exports yet.",
        ),
        (
            "Keyframes",
            "Trickplay/keyframe tiles are regenerated, not migrated.",
        ),
        (
            "Trickplay",
            "Trickplay/keyframe tiles are regenerated, not migrated.",
        ),
        (
            "Transcodes",
            "Transcode sessions are runtime state and are not migrated.",
        ),
        ("PackageState", "Plugin package binaries are not imported."),
    ] {
        if data.get(field).is_some() {
            unsupported.insert(field, reason.to_string());
        }
    }
    unsupported
}

async fn import_jellyfin_users(
    db: &Database,
    data: &serde_json::Map<String, serde_json::Value>,
) -> Result<usize, ApiError> {
    let mut imported = 0usize;
    let mut existing_by_name = db
        .users()
        .await?
        .into_iter()
        .map(|user| (user.name.to_lowercase(), user))
        .collect::<HashMap<_, _>>();
    for user in migration_array(data, "Users") {
        let object = user
            .as_object()
            .ok_or_else(|| ApiError::bad_request("Jellyfin migration user must be an object"))?;
        let Some(name) = migration_string_field(object, &["Name", "Username"]) else {
            continue;
        };
        let policy = object.get("Policy").and_then(serde_json::Value::as_object);
        let is_administrator = migration_bool_field(object, &["IsAdministrator"])
            .or_else(|| {
                policy.and_then(|policy| migration_bool_field(policy, &["IsAdministrator"]))
            })
            .unwrap_or(false);
        let is_disabled = migration_bool_field(object, &["IsDisabled"])
            .or_else(|| policy.and_then(|policy| migration_bool_field(policy, &["IsDisabled"])))
            .unwrap_or(false);
        let sync_play_access = policy
            .and_then(|policy| migration_string_field(policy, &["SyncPlayAccess"]))
            .and_then(|value| normalize_sync_play_access(&value))
            .unwrap_or_else(|| "CreateAndJoinGroups".to_string());
        let key = name.to_lowercase();
        let user = if let Some(existing) = existing_by_name.get(&key) {
            existing.clone()
        } else {
            let created = UserService::new(db).create(&name, None).await?;
            existing_by_name.insert(key, created.clone());
            created
        };
        UserService::new(db)
            .update_profile(
                user.id,
                &name,
                is_administrator,
                is_disabled,
                &sync_play_access,
            )
            .await?;
        imported += 1;
    }
    Ok(imported)
}

async fn import_jellyfin_libraries(
    db: &Database,
    data: &serde_json::Map<String, serde_json::Value>,
) -> Result<usize, ApiError> {
    let mut imported = 0usize;
    for library in migration_libraries(data) {
        let object = library
            .as_object()
            .ok_or_else(|| ApiError::bad_request("Jellyfin migration library must be an object"))?;
        let Some(name) = migration_string_field(object, &["Name", "DisplayName"]) else {
            continue;
        };
        let collection_type = migration_string_field(object, &["CollectionType", "ContentType"]);
        let locations = object
            .get("Locations")
            .or_else(|| object.get("Paths"))
            .and_then(serde_json::Value::as_array)
            .ok_or_else(|| {
                ApiError::bad_request("Jellyfin migration library is missing Locations")
            })?
            .iter()
            .filter_map(|location| location.as_str().map(str::trim))
            .filter(|location| !location.is_empty())
            .map(ToOwned::to_owned)
            .collect::<Vec<_>>();
        for location in &locations {
            if !backup_restore_path_is_safe(location) {
                return Err(ApiError::bad_request(format!(
                    "Jellyfin migration library location is not safe to import: {location}"
                )));
            }
        }
        LibraryService::new(db)
            .upsert_virtual_folder(&name, collection_type.as_deref(), locations)
            .await?;
        imported += 1;
    }
    Ok(imported)
}

async fn import_jellyfin_media_metadata(
    db: &Database,
    data: &serde_json::Map<String, serde_json::Value>,
) -> Result<usize, ApiError> {
    let items_by_path = db
        .media_items()
        .await?
        .into_iter()
        .map(|item| (item.path.clone(), item))
        .collect::<HashMap<_, _>>();
    let mut imported = 0usize;
    for media in migration_media_entries(data) {
        let object = media.as_object().ok_or_else(|| {
            ApiError::bad_request("Jellyfin migration media entry must be an object")
        })?;
        let Some(path) = migration_string_field(object, &["Path", "FilePath"]) else {
            continue;
        };
        if !backup_restore_path_is_safe(&path) {
            return Err(ApiError::bad_request(format!(
                "Jellyfin migration media path is not safe to import: {path}"
            )));
        }
        let Some(item) = items_by_path.get(&path) else {
            continue;
        };
        let metadata = object
            .get("Metadata")
            .cloned()
            .unwrap_or_else(|| media.clone());
        MediaService::new(db)
            .update_metadata(item.id, metadata)
            .await?;
        imported += 1;
    }
    Ok(imported)
}

async fn import_jellyfin_user_data(
    db: &Database,
    data: &serde_json::Map<String, serde_json::Value>,
) -> Result<usize, ApiError> {
    let users_by_name = db
        .users()
        .await?
        .into_iter()
        .map(|user| (user.name.to_lowercase(), user))
        .collect::<HashMap<_, _>>();
    let items_by_path = db
        .media_items()
        .await?
        .into_iter()
        .map(|item| (item.path.clone(), item))
        .collect::<HashMap<_, _>>();
    let mut imported = 0usize;
    for user_data in migration_array(data, "UserData") {
        let object = user_data.as_object().ok_or_else(|| {
            ApiError::bad_request("Jellyfin migration user data must be an object")
        })?;
        let Some(user_name) = migration_string_field(object, &["UserName", "Username", "User"])
        else {
            continue;
        };
        let Some(path) = migration_string_field(object, &["Path", "FilePath"]) else {
            continue;
        };
        if !backup_restore_path_is_safe(&path) {
            return Err(ApiError::bad_request(format!(
                "Jellyfin migration user data path is not safe to import: {path}"
            )));
        }
        let Some(user) = users_by_name.get(&user_name.to_lowercase()) else {
            continue;
        };
        let Some(item) = items_by_path.get(&path) else {
            continue;
        };
        SessionService::new(db)
            .upsert_playback_state(UpsertPlaybackState {
                user_id: user.id,
                item_id: item.id,
                media_source_id: None,
                audio_stream_index: None,
                subtitle_stream_index: None,
                position_ticks: migration_i64_field(
                    object,
                    &["PositionTicks", "PlaybackPositionTicks"],
                )
                .unwrap_or(0),
                is_paused: false,
                played: migration_bool_field(object, &["Played", "IsPlayed"]).unwrap_or(false),
            })
            .await?;
        if migration_bool_field(object, &["IsFavorite", "Favorite"]).unwrap_or(false) {
            SessionService::new(db)
                .set_item_favorite(user.id, item.id, true)
                .await?;
        }
        imported += 1;
    }
    Ok(imported)
}

async fn import_jellyfin_lists(
    db: &Database,
    data: &serde_json::Map<String, serde_json::Value>,
) -> Result<usize, ApiError> {
    let mut imported = 0usize;
    imported += import_jellyfin_list_family(db, data, "Playlists", "playlist", None).await?;
    imported +=
        import_jellyfin_list_family(db, data, "Collections", "collection", Some("boxsets")).await?;
    Ok(imported)
}

async fn import_jellyfin_list_family(
    db: &Database,
    data: &serde_json::Map<String, serde_json::Value>,
    field: &str,
    kind: &str,
    collection_type: Option<&str>,
) -> Result<usize, ApiError> {
    let existing_lists = db.media_lists(kind).await?;
    let existing_by_name = existing_lists
        .into_iter()
        .map(|list| (list.name.to_lowercase(), list))
        .collect::<HashMap<_, _>>();
    let items_by_path = db
        .media_items()
        .await?
        .into_iter()
        .map(|item| (item.path.clone(), item.id))
        .collect::<HashMap<_, _>>();
    let mut imported = 0usize;
    for list in migration_array(data, field) {
        let object = list.as_object().ok_or_else(|| {
            ApiError::bad_request(format!(
                "Jellyfin migration {field} entry must be an object"
            ))
        })?;
        let Some(name) = migration_string_field(object, &["Name"]) else {
            continue;
        };
        let item_ids = object
            .get("ItemPaths")
            .or_else(|| object.get("Paths"))
            .and_then(serde_json::Value::as_array)
            .map(|paths| {
                paths
                    .iter()
                    .filter_map(serde_json::Value::as_str)
                    .filter_map(|path| items_by_path.get(path).copied())
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        if let Some(existing) = existing_by_name.get(&name.to_lowercase()) {
            LibraryService::new(db)
                .add_media_list_items(existing.id, item_ids)
                .await?;
        } else {
            LibraryService::new(db)
                .create_media_list(kind, &name, collection_type, None, item_ids)
                .await?;
        }
        imported += 1;
    }
    Ok(imported)
}

async fn import_jellyfin_task_history(
    db: &Database,
    data: &serde_json::Map<String, serde_json::Value>,
) -> Result<usize, ApiError> {
    let mut imported = 0usize;
    for entry in migration_array(data, "TaskHistory") {
        let object = entry.as_object().ok_or_else(|| {
            ApiError::bad_request("Jellyfin migration TaskHistory entry must be an object")
        })?;
        let Some(task_key) = migration_string_field(object, &["Key", "TaskKey", "Name", "Id"])
        else {
            continue;
        };
        let status = migration_task_history_status(object);
        let started_at = migration_time_field(
            object,
            &["StartTimeUtc", "StartDate", "DateStarted", "StartedAt"],
        )
        .unwrap_or_else(OffsetDateTime::now_utc);
        let completed_at = migration_time_field(
            object,
            &["EndTimeUtc", "EndDate", "DateCompleted", "CompletedAt"],
        )
        .unwrap_or(started_at);
        let id = migration_string_field(object, &["RunId", "HistoryId"])
            .or_else(|| migration_string_field(object, &["Id"]).filter(|value| value.contains('-')))
            .and_then(|value| Uuid::parse_str(&value).ok())
            .unwrap_or_else(|| {
                migration_task_history_id(&task_key, status, started_at, completed_at)
            });
        let result = object
            .get("Result")
            .cloned()
            .unwrap_or_else(|| serde_json::json!({ "ImportedFrom": "Jellyfin" }));
        let error_message = migration_string_field(
            object,
            &["ErrorMessage", "Error", "Exception", "CancellationMessage"],
        );
        TaskService::new(db)
            .import_history(
                Some(id),
                &task_key,
                status,
                started_at,
                completed_at,
                result,
                error_message.as_deref(),
            )
            .await?;
        imported += 1;
    }
    Ok(imported)
}

fn migration_task_history_status(
    object: &serde_json::Map<String, serde_json::Value>,
) -> &'static str {
    match migration_string_field(object, &["Status", "State"])
        .unwrap_or_else(|| "Completed".to_string())
        .to_ascii_lowercase()
        .as_str()
    {
        "failed" | "cancelled" | "canceled" | "aborted" => "failed",
        _ => "completed",
    }
}

fn migration_time_field(
    object: &serde_json::Map<String, serde_json::Value>,
    fields: &[&str],
) -> Option<OffsetDateTime> {
    migration_string_field(object, fields)
        .and_then(|value| OffsetDateTime::parse(&value, &Rfc3339).ok())
}

fn migration_task_history_id(
    task_key: &str,
    status: &str,
    started_at: OffsetDateTime,
    completed_at: OffsetDateTime,
) -> Uuid {
    let mut hasher = Sha256::new();
    hasher.update(task_key.as_bytes());
    hasher.update([0]);
    hasher.update(status.as_bytes());
    hasher.update([0]);
    hasher.update(format_time_for_json(started_at).as_bytes());
    hasher.update([0]);
    hasher.update(format_time_for_json(completed_at).as_bytes());
    let digest = hasher.finalize();
    let mut bytes = [0u8; 16];
    bytes.copy_from_slice(&digest[..16]);
    Uuid::from_bytes(bytes)
}

fn migration_string_field(
    object: &serde_json::Map<String, serde_json::Value>,
    fields: &[&str],
) -> Option<String> {
    fields.iter().find_map(|field| {
        object
            .get(*field)
            .and_then(serde_json::Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(ToOwned::to_owned)
    })
}

fn migration_bool_field(
    object: &serde_json::Map<String, serde_json::Value>,
    fields: &[&str],
) -> Option<bool> {
    fields
        .iter()
        .find_map(|field| object.get(*field).and_then(serde_json::Value::as_bool))
}

fn migration_i64_field(
    object: &serde_json::Map<String, serde_json::Value>,
    fields: &[&str],
) -> Option<i64> {
    fields
        .iter()
        .find_map(|field| object.get(*field).and_then(serde_json::Value::as_i64))
}

async fn ping() -> &'static str {
    "Jellyfin Server"
}

async fn system_restart(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
) -> Result<StatusCode, ApiError> {
    require_admin(&state.db, &headers, query.api_key.as_deref()).await?;
    publish_system_lifecycle_command(SystemLifecycleCommand::Restart);
    Ok(StatusCode::NO_CONTENT)
}

async fn system_shutdown(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
) -> Result<StatusCode, ApiError> {
    require_admin(&state.db, &headers, query.api_key.as_deref()).await?;
    publish_system_lifecycle_command(SystemLifecycleCommand::Shutdown);
    Ok(StatusCode::NO_CONTENT)
}

pub fn subscribe_system_lifecycle_commands() -> broadcast::Receiver<SystemLifecycleCommand> {
    system_lifecycle_sender().subscribe()
}

pub fn last_system_lifecycle_command() -> Option<SystemLifecycleCommand> {
    match SYSTEM_LIFECYCLE_LAST.load(AtomicOrdering::SeqCst) {
        1 => Some(SystemLifecycleCommand::Restart),
        2 => Some(SystemLifecycleCommand::Shutdown),
        _ => None,
    }
}

pub fn publish_system_lifecycle_command(command: SystemLifecycleCommand) {
    SYSTEM_LIFECYCLE_LAST.store(
        match command {
            SystemLifecycleCommand::Restart => 1,
            SystemLifecycleCommand::Shutdown => 2,
        },
        AtomicOrdering::SeqCst,
    );
    let _ = system_lifecycle_sender().send(command);
}

fn system_lifecycle_sender() -> &'static broadcast::Sender<SystemLifecycleCommand> {
    SYSTEM_LIFECYCLE.get_or_init(|| {
        let (sender, _) = broadcast::channel(16);
        sender
    })
}

async fn system_storage(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
) -> Result<Json<serde_json::Value>, ApiError> {
    require_admin(&state.db, &headers, query.api_key.as_deref()).await?;
    let current_dir = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let temp_dir = std::env::temp_dir();
    let libraries = state
        .db
        .virtual_folders()
        .await?
        .iter()
        .map(|folder| {
            serde_json::json!({
                "Id": folder.id,
                "Name": folder.name,
                "Folders": folder
                    .locations
                    .iter()
                    .map(|path| folder_storage_json(PathBuf::from(path)))
                    .collect::<Vec<serde_json::Value>>()
            })
        })
        .collect::<Vec<serde_json::Value>>();

    Ok(Json(serde_json::json!({
        "ProgramDataFolder": folder_storage_json(current_dir.clone()),
        "WebFolder": folder_storage_json(state.web_dir),
        "ImageCacheFolder": folder_storage_json(temp_dir.join("jellyrin").join("images")),
        "CacheFolder": folder_storage_json(temp_dir.join("jellyrin").join("cache")),
        "LogFolder": folder_storage_json(state.log_dir),
        "InternalMetadataFolder": folder_storage_json(current_dir.join("metadata")),
        "TranscodingTempFolder": folder_storage_json(temp_dir.join("jellyrin").join("transcodes")),
        "Libraries": libraries
    })))
}

fn folder_storage_json(path: PathBuf) -> serde_json::Value {
    serde_json::json!({
        "Path": path.to_string_lossy(),
        "FreeSpace": null,
        "UsedSpace": null,
        "StorageType": null,
        "DeviceId": null
    })
}

async fn system_logs(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
) -> Result<Json<Vec<serde_json::Value>>, ApiError> {
    require_admin(&state.db, &headers, auth_query.api_key.as_deref()).await?;

    let mut read_dir = match tokio::fs::read_dir(&state.log_dir).await {
        Ok(read_dir) => read_dir,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(Json(Vec::new())),
        Err(error) => return Err(ApiError::from(error)),
    };

    let mut logs = Vec::new();
    while let Some(entry) = read_dir.next_entry().await.map_err(ApiError::from)? {
        let metadata = tokio::fs::symlink_metadata(entry.path())
            .await
            .map_err(ApiError::from)?;
        if metadata.file_type().is_symlink() || !metadata.is_file() {
            continue;
        }

        let name = entry.file_name().to_string_lossy().into_owned();
        if !is_server_log_file_name(&name) {
            continue;
        }

        let modified = metadata
            .modified()
            .ok()
            .map(OffsetDateTime::from)
            .unwrap_or_else(OffsetDateTime::now_utc);
        let created = metadata
            .created()
            .ok()
            .map(OffsetDateTime::from)
            .unwrap_or(modified);
        logs.push(serde_json::json!({
            "Name": name,
            "Size": metadata.len(),
            "DateCreated": format_time_for_json(created),
            "DateModified": format_time_for_json(modified)
        }));
    }

    logs.sort_by(|left, right| {
        right["DateModified"]
            .as_str()
            .cmp(&left["DateModified"].as_str())
            .then_with(|| left["Name"].as_str().cmp(&right["Name"].as_str()))
    });

    Ok(Json(logs))
}

fn is_server_log_file_name(name: &str) -> bool {
    FsPath::new(name)
        .extension()
        .and_then(|extension| extension.to_str())
        .map(|extension| matches!(extension.to_ascii_lowercase().as_str(), "log" | "txt"))
        .unwrap_or(false)
}

async fn system_diagnostics(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
) -> Result<Json<serde_json::Value>, ApiError> {
    require_admin(&state.db, &headers, auth_query.api_key.as_deref()).await?;
    Ok(Json(serde_json::json!({
        "GeneratedAt": format_time_for_json(OffsetDateTime::now_utc()),
        "Database": database_observability_summary(&state.db).await,
        "CatalogSync": catalog_sync_observability_summary(&state.db).await,
        "Plugins": plugin_observability_summary(&state.db).await?,
        "LiveTv": live_tv_observability_summary(&state.db).await?,
        "Transcoding": transcode_observability_summary(&state.db).await?,
        "RemoteMediaProbes": remote_media_probe_observability_summary(),
        "RemoteImages": remote_image_observability_summary().await,
        "Dlna": dlna_observability_summary(&state.db).await?,
        "SyncPlay": syncplay_observability_summary().await,
        "Logs": {
            "Directory": state.log_dir.to_string_lossy(),
            "Endpoints": [
                "/System/Logs",
                "/System/Logs/Log"
            ]
        }
    })))
}

async fn database_observability_summary(db: &Database) -> serde_json::Value {
    let runtime = db.runtime_diagnostics();
    let telemetry = db.telemetry_diagnostics();
    const HEALTH_TIMEOUT: StdDuration = StdDuration::from_secs(1);
    let healthy = matches!(
        tokio::time::timeout(HEALTH_TIMEOUT, db.health()).await,
        Ok(Ok(()))
    );
    let pool_json = |pool: &jellyrin_db::DatabasePoolDiagnostics| {
        serde_json::json!({
            "Enabled": true,
            "Max": pool.max_connections,
            "Size": pool.size,
            "Idle": pool.idle,
            "InUse": pool.in_use,
        })
    };
    let worker_pool = runtime
        .worker_pool
        .as_ref()
        .map_or_else(|| serde_json::json!({ "Enabled": false }), pool_json);
    let operations = telemetry
        .operations
        .iter()
        .map(database_operation_diagnostics_json)
        .collect::<Vec<_>>();
    serde_json::json!({
        "Driver": runtime.driver.as_str(),
        "Healthy": healthy,
        "HealthTimeoutMilliseconds": HEALTH_TIMEOUT.as_millis(),
        "Pools": {
            "Api": pool_json(&runtime.api_pool),
            "Worker": worker_pool,
        },
        "Telemetry": {
            "Coverage": telemetry.coverage.as_str(),
            "Acquire": {
                "Api": database_acquire_diagnostics_json(&telemetry.api_acquire),
                "Worker": telemetry.worker_acquire.as_ref().map(database_acquire_diagnostics_json),
            },
            "Operations": operations,
        },
    })
}

fn database_duration_histogram_json(
    histogram: &jellyrin_db::DatabaseDurationHistogramDiagnostics,
) -> serde_json::Value {
    let buckets = histogram
        .cumulative_buckets
        .iter()
        .enumerate()
        .map(|(index, count)| {
            serde_json::json!({
                "UpperMicroseconds": jellyrin_db::DATABASE_DURATION_BUCKET_UPPER_MICROSECONDS
                    .get(index),
                "CumulativeCount": count,
            })
        })
        .collect::<Vec<_>>();
    serde_json::json!({
        "Count": histogram.count,
        "SumMicroseconds": histogram.sum_microseconds,
        "MaxMicroseconds": histogram.max_microseconds,
        "Buckets": buckets,
    })
}

fn database_acquire_diagnostics_json(
    acquire: &jellyrin_db::DatabaseAcquireDiagnostics,
) -> serde_json::Value {
    serde_json::json!({
        "Attempts": acquire.attempts,
        "Succeeded": acquire.succeeded,
        "TimedOut": acquire.timed_out,
        "Errors": acquire.errors,
        "Cancelled": acquire.cancelled,
        "Waiting": acquire.waiting,
        "PeakWaiting": acquire.peak_waiting,
        "Wait": database_duration_histogram_json(&acquire.wait),
    })
}

fn database_operation_diagnostics_json(
    operation: &jellyrin_db::DatabaseOperationDiagnostics,
) -> serde_json::Value {
    serde_json::json!({
        "Name": operation.name,
        "Pool": operation.pool.as_str(),
        "Calls": operation.calls,
        "Succeeded": operation.succeeded,
        "Errors": operation.errors,
        "Cancelled": operation.cancelled,
        "Rows": {
            "Total": operation.rows.total,
            "Max": operation.rows.max,
        },
        "Duration": database_duration_histogram_json(&operation.duration),
        "ErrorsByClass": {
            "PoolTimeout": operation.errors_by_class.pool_timeout,
            "StatementTimeout": operation.errors_by_class.statement_timeout,
            "Conflict": operation.errors_by_class.conflict,
            "Constraint": operation.errors_by_class.constraint,
            "Connection": operation.errors_by_class.connection,
            "Database": operation.errors_by_class.database,
            "Other": operation.errors_by_class.other,
        },
    })
}

async fn catalog_sync_observability_summary(db: &Database) -> serde_json::Value {
    match db.catalog_sync_diagnostics().await {
        Ok(diagnostics) => {
            let last_run = diagnostics.last_run.map(|run| {
                serde_json::json!({
                    "Status": run.status,
                    "ItemCount": run.item_count,
                    "StartedAt": format_time_for_json(run.started_at),
                    "CompletedAt": run.completed_at.map(format_time_for_json),
                    "DurationMilliseconds": run.duration_millis,
                })
            });
            serde_json::json!({
                "Available": true,
                "Total": diagnostics.total,
                "Running": diagnostics.running,
                "Completed": diagnostics.completed,
                "Failed": diagnostics.failed,
                "LastRun": last_run,
            })
        }
        Err(_) => {
            tracing::warn!("catalog synchronization diagnostics unavailable");
            serde_json::json!({
                "Available": false,
                "Total": null,
                "Running": null,
                "Completed": null,
                "Failed": null,
                "LastRun": null,
            })
        }
    }
}

