async fn transcode_observability_summary(db: &Database) -> Result<serde_json::Value, ApiError> {
    let sessions = db.transcode_sessions().await?;
    let mut statuses: BTreeMap<String, usize> = BTreeMap::new();
    for session in &sessions {
        *statuses
            .entry(session.status.to_ascii_lowercase())
            .or_default() += 1;
    }
    let live_sessions = live_hls_session_registry().lock().await.len();
    let executions = transcode_execution_registry().lock().await;
    let mut execution_modes: BTreeMap<&'static str, usize> = BTreeMap::new();
    let mut execution_phases: BTreeMap<&'static str, usize> = BTreeMap::new();
    let mut fallback_used = 0usize;
    let mut running_observed = 0usize;
    let mut resource_samples_available = 0usize;
    let mut cpu_percent_total = 0.0f64;
    let mut cpu_time_millis_total = 0u64;
    let mut rss_bytes_total = 0u64;
    let mut max_cpu_percent = 0.0f64;
    let mut max_rss_bytes = 0u64;
    let mut stale_samples = 0usize;
    let mut progress_speed_samples = 0usize;
    let mut progress_speed_total = 0.0f64;
    let mut minimum_speed: Option<f64> = None;
    let mut maximum_speed: Option<f64> = None;
    let now = OffsetDateTime::now_utc();
    for observation in executions.values() {
        *execution_modes
            .entry(transcode_job_kind_name(observation.effective_mode))
            .or_default() += 1;
        *execution_phases.entry(observation.phase).or_default() += 1;
        fallback_used += usize::from(observation.fallback_used);
        if matches!(observation.phase, "running" | "fallback-running") {
            running_observed += 1;
            if observation.cpu_time_millis.is_some() || observation.rss_bytes.is_some() {
                resource_samples_available += 1;
                cpu_time_millis_total = cpu_time_millis_total
                    .saturating_add(observation.cpu_time_millis.unwrap_or_default());
                rss_bytes_total =
                    rss_bytes_total.saturating_add(observation.rss_bytes.unwrap_or_default());
                max_rss_bytes = max_rss_bytes.max(observation.rss_bytes.unwrap_or_default());
                if observation
                    .resource_updated_at
                    .is_none_or(|updated_at| now - updated_at > time::Duration::seconds(10))
                {
                    stale_samples += 1;
                }
            }
            if let Some(cpu_percent) = observation.cpu_percent {
                cpu_percent_total += cpu_percent;
                max_cpu_percent = max_cpu_percent.max(cpu_percent);
            }
            if let Some(speed) = observation.speed {
                progress_speed_samples += 1;
                progress_speed_total += speed;
                minimum_speed = Some(minimum_speed.map_or(speed, |current| current.min(speed)));
                maximum_speed = Some(maximum_speed.map_or(speed, |current| current.max(speed)));
            }
        }
    }
    let executions_observed = executions.len();
    let average_speed =
        (progress_speed_samples > 0).then(|| progress_speed_total / progress_speed_samples as f64);
    drop(executions);
    let tracked_accesses = transcode_last_access_registry().lock().await.len();
    let limits = *transcode_limits();
    let coordinator = transcode_coordinator();
    let total_available = coordinator.available_total_permits();
    let video_available = coordinator.available_permits(TranscodeJobKind::VideoEncode);
    let audio_available = coordinator.available_permits(TranscodeJobKind::AudioEncode);
    let remux_available = coordinator.available_permits(TranscodeJobKind::Remux);
    let auxiliary_available = coordinator.available_permits(TranscodeJobKind::Auxiliary);
    let probe_available = coordinator.available_permits(TranscodeJobKind::Probe);
    let wait_queue_limit = max_queued_ffmpeg_jobs();
    let wait_queue_available = transcode_wait_queue().available_permits();
    let disk_quota = transcode_disk_quota();
    let storage = match disk_quota.snapshot().await {
        Ok(storage) => storage,
        Err(error) => {
            tracing::warn!(%error, "failed to refresh transcode disk diagnostics");
            disk_quota.cached_snapshot()
        }
    };
    let auxiliary_executions = auxiliary_ffmpeg_telemetry().snapshot();

    Ok(serde_json::json!({
        "Directory": disk_quota.root().to_string_lossy(),
        "Admission": admission_metrics_json(ffmpeg_admission_metrics().snapshot()),
        "AuxiliaryExecutions": {
            "Active": auxiliary_executions.active,
            "PeakActive": auxiliary_executions.peak_active,
            "Started": auxiliary_executions.started,
            "Completed": auxiliary_executions.completed(),
            "Succeeded": auxiliary_executions.succeeded,
            "CapacityUnavailable": auxiliary_executions.capacity_unavailable,
            "TimedOut": auxiliary_executions.timed_out,
            "OutputLimited": auxiliary_executions.output_limited,
            "NonZeroExit": auxiliary_executions.non_zero_exit,
            "IoFailed": auxiliary_executions.io_failed,
            "Cancelled": auxiliary_executions.cancelled,
            "DurationMilliseconds": {
                "Le10": auxiliary_executions.duration_le_10_ms,
                "Le100": auxiliary_executions.duration_le_100_ms,
                "Le1000": auxiliary_executions.duration_le_1_000_ms,
                "Le5000": auxiliary_executions.duration_le_5_000_ms,
                "Le15000": auxiliary_executions.duration_le_15_000_ms,
                "Gt15000": auxiliary_executions.duration_gt_15_000_ms,
            },
        },
        "Storage": {
            "UsageBytes": storage.usage_bytes,
            "ReservedBytes": storage.reserved_bytes,
            "CommittedBytes": storage.committed_bytes,
            "AvailableBytes": storage.available_bytes,
            "QuotaBytes": disk_quota.config().quota_bytes,
            "ReservationBytes": disk_quota.config().reservation_bytes,
            "ActiveReservations": storage.active_reservations,
            "QuotaExceeded": storage.quota_exceeded,
            "MonitorRunning": storage.monitor_running,
            "SuccessfulScans": storage.successful_scans,
            "FailedScans": storage.failed_scans,
        },
        "Sessions": {
            "Persisted": sessions.len(),
            "Live": live_sessions,
            "TrackedAccesses": tracked_accesses,
            "Statuses": statuses,
            "ExecutionsObserved": executions_observed,
            "FallbacksUsed": fallback_used,
            "ByEffectiveMode": execution_modes,
            "ByExecutionPhase": execution_phases,
        },
        "Processes": {
            "ResourceMetricsSupported": jellyrin_transcode::process_resource_sampling_supported(),
            "RunningObserved": running_observed,
            "SamplesAvailable": resource_samples_available,
            "CpuPercentTotal": cpu_percent_total,
            "CpuTimeMillisecondsTotal": cpu_time_millis_total,
            "RssBytesTotal": rss_bytes_total,
            "MaxCpuPercent": max_cpu_percent,
            "MaxRssBytes": max_rss_bytes,
            "StaleSamples": stale_samples,
        },
        "Progress": {
            "SamplesAvailable": progress_speed_samples,
            "MinimumSpeed": minimum_speed,
            "AverageSpeed": average_speed,
            "MaximumSpeed": maximum_speed,
        },
        "Coordinator": {
            "Total": {
                "Limit": limits.max_total_jobs,
                "Active": limits.max_total_jobs.saturating_sub(total_available),
                "Available": total_available,
            },
            "VideoEncode": {
                "Limit": limits.max_video_encodes,
                "Active": limits.max_video_encodes.saturating_sub(video_available),
                "Available": video_available,
            },
            "AudioEncode": {
                "Limit": limits.max_audio_encodes,
                "Active": limits.max_audio_encodes.saturating_sub(audio_available),
                "Available": audio_available,
            },
            "Remux": {
                "Limit": limits.max_remuxes,
                "Active": limits.max_remuxes.saturating_sub(remux_available),
                "Available": remux_available,
            },
            "Auxiliary": {
                "Limit": limits.max_auxiliary,
                "Active": limits.max_auxiliary.saturating_sub(auxiliary_available),
                "Available": auxiliary_available,
            },
            "Probe": {
                "Limit": limits.max_probes,
                "Active": limits.max_probes.saturating_sub(probe_available),
                "Available": probe_available,
            },
            "WaitQueue": {
                "Limit": wait_queue_limit,
                "Waiting": wait_queue_limit.saturating_sub(wait_queue_available),
                "Available": wait_queue_available,
            }
        },
        "Scheduler": {
            "FfmpegNice": configured_ffmpeg_nice(),
        },
    }))
}

async fn plugin_observability_summary(db: &Database) -> Result<serde_json::Value, ApiError> {
    let plugins = db.installed_plugins_json().await?;
    let mut active = 0usize;
    let mut malfunctioned = 0usize;
    let mut runtime_instances = 0usize;
    let mut recent_events = 0usize;
    let mut runtimes: BTreeMap<String, usize> = BTreeMap::new();
    let mut statuses: BTreeMap<String, usize> = BTreeMap::new();

    for plugin in &plugins {
        let runtime = plugin
            .get("Runtime")
            .and_then(serde_json::Value::as_str)
            .unwrap_or("Unknown")
            .to_string();
        *runtimes.entry(runtime).or_default() += 1;

        let status = plugin
            .get("Status")
            .and_then(serde_json::Value::as_str)
            .unwrap_or("Unknown")
            .to_string();
        if status.eq_ignore_ascii_case("Active") {
            active += 1;
        }
        if status.eq_ignore_ascii_case("Malfunctioned") {
            malfunctioned += 1;
        }
        *statuses.entry(status).or_default() += 1;

        runtime_instances += plugin
            .get("RuntimeInstances")
            .and_then(serde_json::Value::as_array)
            .map_or(0, Vec::len);
        recent_events += plugin
            .get("RecentEvents")
            .and_then(serde_json::Value::as_array)
            .map_or(0, Vec::len);
    }

    Ok(serde_json::json!({
        "Installed": plugins.len(),
        "Active": active,
        "Malfunctioned": malfunctioned,
        "RuntimeInstances": runtime_instances,
        "RecentEvents": recent_events,
        "Runtimes": runtimes,
        "Statuses": statuses
    }))
}

async fn live_tv_observability_summary(db: &Database) -> Result<serde_json::Value, ApiError> {
    let config = db
        .named_configuration("livetv")
        .await?
        .unwrap_or_else(default_live_tv_configuration);
    let configured_tuners = config
        .get("TunerHosts")
        .and_then(serde_json::Value::as_array)
        .map_or(0, Vec::len);
    let configured_listing_providers = config
        .get("ListingProviders")
        .and_then(serde_json::Value::as_array)
        .map_or(0, Vec::len);
    let active_tuner_leases = live_tuner_lease_observability_summary()?;
    let (hls_sessions, active_hls_sessions, terminal_hls_sessions) =
        if let Some(sessions) = LIVE_HLS_SESSIONS.get() {
            let sessions = sessions.lock().await;
            let active = sessions
                .values()
                .filter(|entry| live_hls_session_is_active(entry))
                .count();
            (
                sessions.len(),
                active,
                sessions.len().saturating_sub(active),
            )
        } else {
            (0, 0, 0)
        };
    let shared_live_producers = if let Some(registry) = LIVE_STREAM_REGISTRY.get() {
        registry.lock().await.len()
    } else {
        0
    };
    let active_recordings = if let Some(recordings) = LIVE_TV_RECORDING_REGISTRY.get() {
        recordings.lock().await.len()
    } else {
        0
    };

    Ok(serde_json::json!({
        "ConfiguredTunerHosts": configured_tuners,
        "ConfiguredListingProviders": configured_listing_providers,
        "ActiveTunerLeases": active_tuner_leases,
        "ActiveHlsSessions": active_hls_sessions,
        "HlsSessions": {
            "Total": hls_sessions,
            "Active": active_hls_sessions,
            "Terminal": terminal_hls_sessions,
            "Limit": LIVE_HLS_SESSION_REGISTRY_MAX_ENTRIES,
        },
        "SharedStreamProducers": {
            "Active": shared_live_producers,
            "Limit": LIVE_TV_MAX_DISTINCT_PRODUCERS,
            "Available": LIVE_TV_MAX_DISTINCT_PRODUCERS.saturating_sub(shared_live_producers),
        },
        "RemoteHttp": {
            "ControlTimeoutSeconds": LIVE_TV_REMOTE_CONTROL_TIMEOUT.as_secs(),
            "ControlMaxBytes": LIVE_TV_REMOTE_CONTROL_RESPONSE_LIMIT_BYTES,
            "ControlMaxCategories": LIVE_TV_PROVIDER_CATALOG_MAX_CATEGORIES,
            "ConfigSourceTimeoutSeconds": LIVE_TV_CONFIG_SOURCE_TIMEOUT.as_secs(),
            "ConfigSourceMaxBytes": LIVE_TV_CONFIG_SOURCE_LIMIT_BYTES,
            "ConfigMaxChannels": LIVE_TV_PROVIDER_CATALOG_MAX_CHANNELS,
            "ConfigMaxPrograms": LIVE_TV_CONFIG_MAX_PROGRAMS,
            "Redirects": {
                "OpaqueStreams": true,
                "ConfigSources": false,
                "MaxHops": SENSITIVE_REMOTE_LIVE_MAX_REDIRECTS,
                "RevalidateEachHop": true,
                "BlockHttpsDowngrade": true,
            },
            "EnvironmentProxy": false,
        },
        "ActiveRecordings": active_recordings
    }))
}

fn live_tuner_lease_observability_summary() -> Result<serde_json::Value, ApiError> {
    let leases = live_tuner_lease_registry().lock().map_err(|_| {
        tracing::error!("live tuner lease registry lock poisoned while building diagnostics");
        ApiError::internal("live tuner lease registry lock poisoned")
    })?;
    let mut by_tuner_host: BTreeMap<String, usize> = BTreeMap::new();
    let total_refcount = leases.values().map(|lease| lease.refcount).sum::<usize>();
    for key in leases.keys() {
        *by_tuner_host.entry(key.tuner_host_id.clone()).or_default() += 1;
    }
    Ok(serde_json::json!({
        "Count": leases.len(),
        "Limit": LIVE_TV_MAX_DISTINCT_PRODUCERS,
        "Available": LIVE_TV_MAX_DISTINCT_PRODUCERS.saturating_sub(leases.len()),
        "TotalRefCount": total_refcount,
        "ByTunerHost": by_tuner_host
    }))
}

async fn dlna_observability_summary(db: &Database) -> Result<serde_json::Value, ApiError> {
    let mut diagnostics = dlna::dlna_diagnostics_json()?;
    diagnostics["UPnPEnabled"] = serde_json::Value::Bool(dlna::upnp_enabled(db).await?);
    Ok(diagnostics)
}

async fn syncplay_observability_summary() -> serde_json::Value {
    let groups = syncplay_groups().lock().await;
    let participant_count = groups
        .values()
        .map(|group| group.participants.len())
        .sum::<usize>();
    let ready_count = groups
        .values()
        .flat_map(|group| group.participants.values())
        .filter(|participant| participant.is_ready)
        .count();
    let buffering_count = groups
        .values()
        .flat_map(|group| group.participants.values())
        .filter(|participant| participant.is_buffering)
        .count();
    let command_sequence_max = groups
        .values()
        .map(|group| group.command_sequence)
        .max()
        .unwrap_or(0);
    serde_json::json!({
        "Groups": groups.len(),
        "Participants": participant_count,
        "ReadyParticipants": ready_count,
        "BufferingParticipants": buffering_count,
        "MaxCommandSequence": command_sequence_max
    })
}

#[derive(Debug, Deserialize)]
struct SystemLogFileQuery {
    #[serde(alias = "Name")]
    #[serde(alias = "file")]
    #[serde(alias = "File")]
    #[serde(alias = "filename")]
    #[serde(alias = "FileName")]
    #[serde(alias = "log")]
    #[serde(alias = "Log")]
    name: String,
}

async fn system_log_file(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    Query(query): Query<SystemLogFileQuery>,
) -> Result<impl IntoResponse, ApiError> {
    require_admin(&state.db, &headers, auth_query.api_key.as_deref()).await?;
    let Some(path) = safe_log_file_path(&state.log_dir, &query.name) else {
        return Err(ApiError::bad_request("invalid log file name"));
    };
    let metadata = tokio::fs::symlink_metadata(&path).await.map_err(|error| {
        if error.kind() == std::io::ErrorKind::NotFound {
            ApiError::not_found("Log file not found")
        } else {
            ApiError::from(error)
        }
    })?;
    if metadata.file_type().is_symlink() || !metadata.is_file() {
        return Err(ApiError::not_found("Log file not found"));
    }

    let contents = tokio::fs::read_to_string(path).await.map_err(|error| {
        if error.kind() == std::io::ErrorKind::NotFound {
            ApiError::not_found("Log file not found")
        } else {
            ApiError::from(error)
        }
    })?;

    Ok((
        [(header::CONTENT_TYPE, "text/plain; charset=utf-8")],
        contents,
    ))
}

async fn service_worker_stub() -> impl IntoResponse {
    (
        [(
            header::CONTENT_TYPE,
            "application/javascript; charset=utf-8",
        )],
        "self.addEventListener('install', event => self.skipWaiting());\n",
    )
}

fn safe_log_file_path(log_dir: &FsPath, name: &str) -> Option<PathBuf> {
    let name = name.trim();
    if name.is_empty() || name.contains('/') || name.contains('\\') {
        return None;
    }
    if !is_server_log_file_name(name) {
        return None;
    }

    let path = FsPath::new(name);
    if path.file_name().and_then(|file_name| file_name.to_str()) != Some(name) {
        return None;
    }

    Some(log_dir.join(name))
}

#[derive(Debug, Deserialize)]
struct ActivityLogQuery {
    #[serde(alias = "startIndex")]
    #[serde(alias = "StartIndex")]
    start_index: Option<i64>,
    #[serde(alias = "limit")]
    #[serde(alias = "Limit")]
    limit: Option<i64>,
    #[serde(alias = "hasUserId")]
    #[serde(alias = "HasUserId")]
    has_user_id: Option<bool>,
    #[serde(alias = "name")]
    #[serde(alias = "Name")]
    name: Option<String>,
    #[serde(alias = "overview")]
    #[serde(alias = "Overview")]
    overview: Option<String>,
    #[serde(alias = "shortOverview")]
    #[serde(alias = "ShortOverview")]
    short_overview: Option<String>,
    #[serde(alias = "type")]
    #[serde(alias = "Type")]
    entry_type: Option<String>,
    #[serde(alias = "itemId")]
    #[serde(alias = "ItemId")]
    item_id: Option<String>,
    #[serde(alias = "username")]
    #[serde(alias = "Username")]
    username: Option<String>,
    #[serde(alias = "severity")]
    #[serde(alias = "Severity")]
    severity: Option<String>,
    #[serde(default, deserialize_with = "deserialize_query_string_list")]
    #[serde(alias = "sortBy")]
    #[serde(alias = "SortBy")]
    sort_by: Vec<String>,
    #[serde(default, deserialize_with = "deserialize_query_string_list")]
    #[serde(alias = "sortOrder")]
    #[serde(alias = "SortOrder")]
    sort_order: Vec<String>,
    #[serde(alias = "minDate")]
    #[serde(alias = "MinDate")]
    min_date: Option<String>,
    #[serde(alias = "maxDate")]
    #[serde(alias = "MaxDate")]
    max_date: Option<String>,
}

fn deserialize_query_string_list<'de, D>(deserializer: D) -> Result<Vec<String>, D::Error>
where
    D: Deserializer<'de>,
{
    struct StringListVisitor;

    impl<'de> de::Visitor<'de> for StringListVisitor {
        type Value = Vec<String>;

        fn expecting(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            formatter.write_str("a string or a list of strings")
        }

        fn visit_str<E>(self, value: &str) -> Result<Self::Value, E>
        where
            E: de::Error,
        {
            Ok(vec![value.to_string()])
        }

        fn visit_string<E>(self, value: String) -> Result<Self::Value, E>
        where
            E: de::Error,
        {
            Ok(vec![value])
        }

        fn visit_seq<A>(self, mut seq: A) -> Result<Self::Value, A::Error>
        where
            A: de::SeqAccess<'de>,
        {
            let mut values = Vec::new();
            while let Some(value) = seq.next_element::<String>()? {
                values.push(value);
            }
            Ok(values)
        }
    }

    deserializer.deserialize_any(StringListVisitor)
}

async fn activity_log_entries(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    Query(query): Query<ActivityLogQuery>,
) -> Result<Json<serde_json::Value>, ApiError> {
    require_admin(&state.db, &headers, auth_query.api_key.as_deref()).await?;
    let start_index = query.start_index.unwrap_or_default().max(0);
    let limit = query.limit.unwrap_or(100).clamp(0, 1000);
    let filter = activity_log_filter_from_query(&query)?;
    let (entries, total) = state
        .db
        .activity_log_entries(start_index, limit, filter)
        .await?;
    Ok(Json(serde_json::json!({
        "Items": entries.iter().map(activity_log_entry_json).collect::<Vec<_>>(),
        "TotalRecordCount": total,
        "StartIndex": start_index
    })))
}

fn activity_log_filter_from_query(query: &ActivityLogQuery) -> Result<ActivityLogFilter, ApiError> {
    Ok(ActivityLogFilter {
        has_user_id: query.has_user_id,
        item_id: query
            .item_id
            .as_deref()
            .filter(|value| !value.trim().is_empty())
            .map(parse_jellyfin_uuid)
            .transpose()?,
        name: query.name.clone(),
        overview: query.overview.clone(),
        short_overview: query.short_overview.clone(),
        entry_type: query.entry_type.clone(),
        username: query.username.clone(),
        severity: query
            .severity
            .as_deref()
            .map(normalize_activity_log_severity)
            .transpose()?,
        min_date: query
            .min_date
            .as_deref()
            .map(parse_activity_log_date)
            .transpose()?,
        max_date: query
            .max_date
            .as_deref()
            .map(parse_activity_log_date)
            .transpose()?,
        sort: parse_activity_log_sort(&query.sort_by, &query.sort_order),
    })
}

fn normalize_activity_log_severity(value: &str) -> Result<String, ApiError> {
    let value = value.trim();
    let severity = match value.to_ascii_lowercase().as_str() {
        "trace" => "Trace",
        "debug" => "Debug",
        "information" => "Information",
        "warning" => "Warning",
        "error" => "Error",
        "critical" => "Critical",
        "none" => "None",
        _ => return Err(ApiError::bad_request("invalid activity log severity")),
    };
    Ok(severity.to_string())
}

fn parse_activity_log_date(value: &str) -> Result<OffsetDateTime, ApiError> {
    OffsetDateTime::parse(value.trim(), &Rfc3339)
        .map_err(|_| ApiError::bad_request("invalid activity log date"))
}

fn parse_activity_log_sort(
    sort_by: &[String],
    sort_order: &[String],
) -> Vec<(ActivityLogSortField, SortDirection)> {
    let fields = expand_query_values(sort_by);
    let orders = expand_query_values(sort_order);
    fields
        .iter()
        .enumerate()
        .filter_map(|(index, field)| {
            let field = parse_activity_log_sort_field(field)?;
            let direction = orders
                .get(index)
                .or_else(|| orders.first())
                .and_then(|order| parse_sort_direction(order))
                .unwrap_or(SortDirection::Ascending);
            Some((field, direction))
        })
        .collect()
}

fn expand_query_values(values: &[String]) -> Vec<String> {
    values
        .iter()
        .flat_map(|value| value.split(','))
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned)
        .collect()
}

fn parse_activity_log_sort_field(value: &str) -> Option<ActivityLogSortField> {
    match value.trim().to_ascii_lowercase().as_str() {
        "name" => Some(ActivityLogSortField::Name),
        "overview" | "overiew" => Some(ActivityLogSortField::Overview),
        "shortoverview" | "short_overview" => Some(ActivityLogSortField::ShortOverview),
        "type" => Some(ActivityLogSortField::Type),
        "datecreated" | "date" | "createdat" => Some(ActivityLogSortField::DateCreated),
        "username" | "user" => Some(ActivityLogSortField::Username),
        "logseverity" | "severity" => Some(ActivityLogSortField::LogSeverity),
        _ => None,
    }
}

fn parse_sort_direction(value: &str) -> Option<SortDirection> {
    match value.trim().to_ascii_lowercase().as_str() {
        "ascending" | "asc" => Some(SortDirection::Ascending),
        "descending" | "desc" => Some(SortDirection::Descending),
        _ => None,
    }
}

fn activity_log_entry_json(entry: &ActivityLogEntry) -> serde_json::Value {
    serde_json::json!({
        "Id": entry.id,
        "Name": entry.name,
        "Overview": entry.overview,
        "ShortOverview": entry.short_overview,
        "Type": entry.entry_type,
        "Severity": entry.severity,
        "Date": format_time_for_json(entry.created_at),
        "UserId": entry.user_id.map(|id| id.to_string()),
        "ItemId": entry.item_id.map(|id| id.to_string()),
        "UserPrimaryImageTag": null
    })
}

