/// Production entrypoint for an installed plugin capability. The canonical plugin record is
/// loaded only after acquiring the lifecycle reader, so a request that captured an older JSON
/// snapshot cannot recreate a host after disable, uninstall, upgrade, or permission revocation.
async fn invoke_installed_plugin_capability_via_runtime_host(
    db: &Database,
    plugin_hint: &serde_json::Value,
    capability: &str,
    arguments: serde_json::Value,
) -> Result<Option<CapabilityResult>, ApiError> {
    let Some(plugin_id) = json_string_field(plugin_hint, "Id") else {
        return Ok(None);
    };
    let _admission_guard = external_plugin_host_admission_slot(&plugin_id, "default")
        .await
        .acquire_owned()
        .await
        .map_err(|_| ApiError::service_unavailable("Plugin runtime is unavailable"))?;
    let security_slot = external_plugin_security_slot(&plugin_id).await;
    let _security_guard = security_slot.read_owned().await;
    let Some(plugin) = db.installed_plugin_json(&plugin_id).await? else {
        return Ok(None);
    };
    if !json_string_field(&plugin, "Status")
        .is_some_and(|status| status.eq_ignore_ascii_case("Active"))
        || !plugin_string_array(plugin.get("Capabilities"))
            .iter()
            .any(|candidate| candidate.eq_ignore_ascii_case(capability))
    {
        return Ok(None);
    }
    invoke_plugin_capability_via_runtime_host(&plugin, capability, arguments).await
}

/// Delegates per-user catalog visibility to plugins that explicitly advertise the optional
/// authorization capability. Plugins without it preserve the historical visible-to-all behavior.
/// A declared capability is fail-closed: malformed, unavailable or missing decisions deny access.
async fn plugin_user_may_access_tuner_catalog(
    db: &Database,
    plugin_id: &str,
    tuner_id: &str,
    user_context: jellyrin_plugin_sdk::PluginUserContext,
) -> Result<bool, ApiError> {
    let Some(plugin) = db.installed_plugin_json(plugin_id).await? else {
        return Ok(false);
    };
    if !json_string_field(&plugin, "Status")
        .is_some_and(|status| status.eq_ignore_ascii_case("Active"))
    {
        return Ok(false);
    }
    if !plugin_string_array(plugin.get("Capabilities"))
        .iter()
        .any(|capability| capability.eq_ignore_ascii_case(CAPABILITY_USER_CATALOG_AUTHORIZATION))
    {
        return Ok(true);
    }
    let Some(configuration) = db.live_tv_tuner_configuration_by_id(tuner_id).await? else {
        return Ok(false);
    };
    let provider_type = json_string_field(&configuration, "Type")
        .ok_or_else(|| ApiError::service_unavailable("Plugin tuner route is unavailable"))?;
    let Some(routed_plugin_id) = live_tv_plugin_id_from_payload(&configuration, &provider_type)
    else {
        return Ok(false);
    };
    if !routed_plugin_id.eq_ignore_ascii_case(plugin_id) {
        return Ok(false);
    }
    let provider_config = redacted_live_tv_plugin_tuner_config(configuration)?;
    let config_bytes = serde_json::to_vec(&provider_config)
        .map_err(|_| ApiError::internal("Invalid plugin tuner configuration"))?;
    let cache_key =
        plugin_catalog_authorization_cache_key(plugin_id, tuner_id, &user_context, &config_bytes);
    let now = StdInstant::now();
    {
        let mut cache = plugin_catalog_authorization_cache().lock().await;
        cache.retain(|_, entry| entry.expires_at > now);
        if let Some(entry) = cache.get(&cache_key) {
            return Ok(entry.allowed);
        }
    }
    let request = PluginUserAuthorizationRequest::authorize_catalog(provider_config, user_context);
    let arguments = serde_json::to_value(request)
        .map_err(|_| ApiError::internal("Invalid plugin catalog authorization request"))?;
    let Some(result) = invoke_installed_plugin_capability_via_runtime_host(
        db,
        &plugin,
        CAPABILITY_USER_CATALOG_AUTHORIZATION,
        arguments,
    )
    .await?
    else {
        return Ok(false);
    };
    let decision = serde_json::from_value::<PluginUserAuthorizationResult>(serde_json::json!({
        "Allowed": json_field_case_insensitive(&result.value, "Allowed")
            .cloned()
            .unwrap_or(serde_json::Value::Null)
    }))
    .map_err(|_| ApiError::service_unavailable("Plugin catalog authorization is invalid"))?;
    let mut cache = plugin_catalog_authorization_cache().lock().await;
    if cache.len() >= 4_096 {
        cache.clear();
    }
    cache.insert(
        cache_key,
        PluginCatalogAuthorizationCacheEntry {
            allowed: decision.allowed,
            expires_at: StdInstant::now() + StdDuration::from_secs(15),
        },
    );
    Ok(decision.allowed)
}

/// Cache key for one plugin catalogue authorization decision.
///
/// The decision is keyed by device as well as user: the request carries the device id and the
/// contract defines a `ReleaseDevice` action, so a plugin may legitimately answer differently per
/// device, and a user-only key would serve one device's verdict to another until the entry expires.
/// Both identifiers are length-prefixed because a client chooses its own device id, and a bare
/// separator would let one device craft an id that collides with another device's key.
fn plugin_catalog_authorization_cache_key(
    plugin_id: &str,
    tuner_id: &str,
    user_context: &PluginUserContext,
    config_bytes: &[u8],
) -> String {
    format!(
        "{}:{}:{}:{}:{}:{}:{}:{:016x}",
        plugin_id.to_ascii_lowercase(),
        tuner_id.to_ascii_lowercase(),
        user_context.user_id.len(),
        user_context.user_id,
        user_context.device_id.len(),
        user_context.device_id,
        user_context.is_administrator,
        fnv1a64(config_bytes, 0x82a2_b175_229d_6a5b),
    )
}

#[derive(Clone, Copy)]
struct PluginCatalogAuthorizationCacheEntry {
    allowed: bool,
    expires_at: StdInstant,
}

fn plugin_catalog_authorization_cache()
-> &'static tokio::sync::Mutex<HashMap<String, PluginCatalogAuthorizationCacheEntry>> {
    static CACHE: OnceLock<
        tokio::sync::Mutex<HashMap<String, PluginCatalogAuthorizationCacheEntry>>,
    > = OnceLock::new();
    CACHE.get_or_init(|| tokio::sync::Mutex::new(HashMap::new()))
}

async fn release_plugin_user_device_lease(
    db: &Database,
    plugin_id: &str,
    tuner_id: &str,
    user_context: jellyrin_plugin_sdk::PluginUserContext,
) -> Result<(), ApiError> {
    let Some(plugin) = db.installed_plugin_json(plugin_id).await? else {
        return Ok(());
    };
    if !json_string_field(&plugin, "Status")
        .is_some_and(|status| status.eq_ignore_ascii_case("Active"))
        || !plugin_string_array(plugin.get("Capabilities"))
            .iter()
            .any(|capability| {
                capability.eq_ignore_ascii_case(CAPABILITY_USER_CATALOG_AUTHORIZATION)
            })
    {
        return Ok(());
    }
    let Some(configuration) = db.live_tv_tuner_configuration_by_id(tuner_id).await? else {
        return Ok(());
    };
    let provider_type = json_string_field(&configuration, "Type")
        .ok_or_else(|| ApiError::service_unavailable("Plugin tuner route is unavailable"))?;
    if !live_tv_plugin_id_from_payload(&configuration, &provider_type)
        .is_some_and(|routed| routed.eq_ignore_ascii_case(plugin_id))
    {
        return Ok(());
    }
    let request = PluginUserAuthorizationRequest::release_device(
        redacted_live_tv_plugin_tuner_config(configuration)?,
        user_context,
    );
    let arguments = serde_json::to_value(request)
        .map_err(|_| ApiError::internal("Invalid plugin device release request"))?;
    let _ = invoke_installed_plugin_capability_via_runtime_host(
        db,
        &plugin,
        CAPABILITY_USER_CATALOG_AUTHORIZATION,
        arguments,
    )
    .await?;
    Ok(())
}

async fn authorized_live_tv_tuner_ids(
    db: &Database,
    user_context: &jellyrin_plugin_sdk::PluginUserContext,
) -> Result<Option<Vec<String>>, ApiError> {
    let configuration = db
        .named_configuration("livetv")
        .await?
        .unwrap_or_else(default_live_tv_configuration);
    let tuners = configuration
        .get("TunerHosts")
        .and_then(serde_json::Value::as_array)
        .cloned()
        .unwrap_or_default();
    let mut filtered = false;
    let mut allowed = Vec::new();
    for tuner in tuners {
        let Some(tuner_id) = json_string_field(&tuner, "Id") else {
            continue;
        };
        let Some(provider_type) = json_string_field(&tuner, "Type") else {
            allowed.push(tuner_id);
            continue;
        };
        let Some(plugin_id) = live_tv_plugin_id_from_payload(&tuner, &provider_type) else {
            allowed.push(tuner_id);
            continue;
        };
        let plugin = db.installed_plugin_json(&plugin_id).await?;
        let declares_authorization = plugin.as_ref().is_some_and(|plugin| {
            plugin_string_array(plugin.get("Capabilities"))
                .iter()
                .any(|capability| {
                    capability.eq_ignore_ascii_case(CAPABILITY_USER_CATALOG_AUTHORIZATION)
                })
        });
        if !declares_authorization {
            allowed.push(tuner_id);
            continue;
        }
        filtered = true;
        if plugin_user_may_access_tuner_catalog(db, &plugin_id, &tuner_id, user_context.clone())
            .await?
        {
            allowed.push(tuner_id);
        }
    }
    Ok(filtered.then_some(allowed))
}

async fn ensure_plugin_catalog_item_visible(
    db: &Database,
    metadata: &serde_json::Value,
    user_context: &jellyrin_plugin_sdk::PluginUserContext,
) -> Result<(), ApiError> {
    let Some(plugin_id) = json_string_field(metadata, "PluginProviderId") else {
        return Ok(());
    };
    let Some(tuner_id) = json_string_field(metadata, "TunerId") else {
        return Err(ApiError::not_found("Item not found"));
    };
    if plugin_user_may_access_tuner_catalog(db, &plugin_id, &tuner_id, user_context.clone()).await?
    {
        Ok(())
    } else {
        Err(ApiError::not_found("Item not found"))
    }
}

async fn scope_items_query_for_plugin_catalogs(
    db: &Database,
    query: &mut ItemsQuery,
    authenticated_user: &User,
    token: &DeviceToken,
    requested_user_id: Option<Uuid>,
) -> Result<(), ApiError> {
    let user_id = requested_user_id.unwrap_or(authenticated_user.id);
    query.allowed_plugin_tuner_ids = authorized_live_tv_tuner_ids(
        db,
        &jellyrin_plugin_sdk::PluginUserContext {
            user_id: user_id.to_string(),
            device_id: token.device_id.clone(),
            is_administrator: authenticated_user.is_administrator,
        },
    )
    .await?;
    Ok(())
}

async fn invoke_plugin_capability_via_runtime_host_path(
    plugin: &serde_json::Value,
    capability: &str,
    arguments: serde_json::Value,
    runtime: PluginRuntime,
    runtime_name: &str,
    error_prefix: &str,
    host_path: PathBuf,
) -> Result<Option<CapabilityResult>, ApiError> {
    invoke_plugin_capability_via_runtime_host_path_with_timeout(
        plugin,
        capability,
        arguments,
        runtime,
        runtime_name,
        error_prefix,
        host_path,
        StdDuration::from_secs(5),
    )
    .await
}

#[allow(clippy::too_many_arguments)]
async fn invoke_plugin_capability_via_runtime_host_path_with_timeout(
    plugin: &serde_json::Value,
    capability: &str,
    arguments: serde_json::Value,
    runtime: PluginRuntime,
    runtime_name: &str,
    error_prefix: &str,
    host_path: PathBuf,
    timeout: StdDuration,
) -> Result<Option<CapabilityResult>, ApiError> {
    let Some(plugin_id) = json_string_field(plugin, "Id") else {
        return Ok(None);
    };
    if runtime == PluginRuntime::ExternalProcess {
        let isolated_catalog_call = is_external_catalog_import_call(capability, &arguments);
        let contains_secret_grant =
            json_field_case_insensitive(&arguments, "SecretGrant").is_some();
        let reusable_provider_jit_lane = contains_secret_grant
            .then(|| external_provider_jit_lane_for_call(capability, &arguments))
            .flatten();
        let one_shot = isolated_catalog_call
            || (contains_secret_grant && reusable_provider_jit_lane.is_none());
        let lane = if isolated_catalog_call {
            EXTERNAL_PLUGIN_CATALOG_LANE
        } else if let Some(lane) = reusable_provider_jit_lane.as_deref() {
            lane
        } else if contains_secret_grant {
            EXTERNAL_PLUGIN_PROVIDER_SECRET_LANE
        } else {
            "default"
        };
        let guard = locked_external_plugin_host_in_lane(plugin, host_path, lane).await?;
        // Credentialed calls arm kill-on-drop until their complete response has been validated
        // and the request envelope has been scrubbed. This keeps cancellation one-shot even for
        // the normally persistent JIT lane.
        let mut host_lease = ExternalPluginHostLease::new(guard, one_shot || contains_secret_grant);
        let mut invoke = ZeroizingInvokeEnvelope(PluginRpcEnvelope::new(
            format!("{plugin_id}:capability:{capability}"),
            PluginRpcMethod::InvokeCapability,
            InvokeCapabilityRequest {
                plugin_id,
                capability: capability.to_string(),
                arguments,
                timeout_ms: u64::try_from(timeout.as_millis()).unwrap_or(u64::MAX),
            },
        ));
        let response = {
            let host = host_lease
                .host_mut()
                .ok_or_else(|| ApiError::internal("ExternalProcess host is unavailable"))?;
            host.client
                .call::<_, CapabilityResult>(&invoke.0, timeout)
                .await
        };
        let mut result = match response {
            Ok(response) if contains_secret_grant => provider_secret_rpc_result(response),
            Ok(response) => rpc_result(response),
            Err(error) if !contains_secret_grant => {
                host_lease.shutdown().await;
                Err(ApiError::internal(format!(
                    "ExternalProcess capability invoke failed: {error}"
                )))
            }
            Err(_) => {
                host_lease.shutdown().await;
                Err(ApiError::internal(
                    "ExternalProcess provider-secret invocation failed",
                ))
            }
        };
        let mut reflected_secret = false;
        if contains_secret_grant && let Ok(Some(capability_result)) = &mut result {
            let canaries = live_tv_provider_secret_canaries(&invoke.0.payload.arguments);
            if json_contains_sensitive_canary(&capability_result.value, &canaries) {
                zeroize_json_value_strings(&mut capability_result.value);
                reflected_secret = true;
                result = Err(ApiError::internal(
                    "ExternalProcess provider-secret response reflected credential material",
                ));
            }
        }
        // Scrub the core-owned grant before releasing a persistent lane to its next JIT action.
        // The process may retain its own provider session, but it never receives a durable core
        // grant: scope/revision is revalidated independently on every request.
        invoke.scrub();
        if one_shot || reflected_secret {
            host_lease.shutdown().await;
        } else {
            host_lease.retain_on_drop();
        }
        return result;
    }
    let Some((mut client, _version)) =
        load_plugin_runtime_host_with_path(plugin, runtime, runtime_name, error_prefix, host_path)
            .await?
    else {
        return Ok(None);
    };
    let invoke = PluginRpcEnvelope::new(
        format!("{plugin_id}:capability:{capability}"),
        PluginRpcMethod::InvokeCapability,
        InvokeCapabilityRequest {
            plugin_id,
            capability: capability.to_string(),
            arguments,
            timeout_ms: u64::try_from(timeout.as_millis()).unwrap_or(u64::MAX),
        },
    );
    let response = client
        .call::<_, CapabilityResult>(&invoke, timeout)
        .await
        .map_err(|error| {
            ApiError::internal(format!("Plugin host capability invoke failed: {error}"))
        })?;
    let result = rpc_result(response)?;
    let _ = client.shutdown().await;
    Ok(result)
}

#[derive(Debug)]
struct LiveTvPluginCatalogPages {
    channels: Vec<serde_json::Value>,
    categories: Vec<serde_json::Value>,
    programs: Vec<serde_json::Value>,
    continuation_tokens: HashSet<String>,
    page_count: usize,
    accumulated_bytes: usize,
    max_accumulated_bytes: usize,
}

impl Default for LiveTvPluginCatalogPages {
    fn default() -> Self {
        Self::with_max_accumulated_bytes(LIVE_TV_PROVIDER_CATALOG_MAX_ACCUMULATED_BYTES)
    }
}

impl LiveTvPluginCatalogPages {
    fn with_max_accumulated_bytes(max_accumulated_bytes: usize) -> Self {
        Self {
            channels: Vec::new(),
            categories: Vec::new(),
            programs: Vec::new(),
            continuation_tokens: HashSet::new(),
            page_count: 0,
            accumulated_bytes: 0,
            max_accumulated_bytes,
        }
    }
}

impl LiveTvPluginCatalogPages {
    fn push(&mut self, value: serde_json::Value) -> Result<Option<String>, ApiError> {
        if self.page_count >= LIVE_TV_PROVIDER_CATALOG_MAX_PAGES {
            return Err(ApiError::internal(
                "Live TV provider catalogue exceeded the page limit",
            ));
        }
        let remaining_bytes = self
            .max_accumulated_bytes
            .saturating_sub(self.accumulated_bytes);
        let page_bytes = live_tv_plugin_catalog_encoded_size(&value, remaining_bytes)?;

        self.page_count += 1;
        self.accumulated_bytes = self.accumulated_bytes.saturating_add(page_bytes);

        let channels = live_tv_plugin_catalog_array(&value, &["Channels", "Items"], "channels")?;
        if channels.len()
            > LIVE_TV_PROVIDER_CATALOG_MAX_CHANNELS.saturating_sub(self.channels.len())
        {
            return Err(ApiError::internal(
                "Live TV provider catalogue exceeded the channel limit",
            ));
        }
        let categories = live_tv_plugin_catalog_array(&value, &["Categories"], "categories")?;
        if categories.len()
            > LIVE_TV_PROVIDER_CATALOG_MAX_CATEGORIES.saturating_sub(self.categories.len())
        {
            return Err(ApiError::internal(
                "Live TV provider catalogue exceeded the category limit",
            ));
        }
        let programs = live_tv_plugin_catalog_array(&value, &["Programs"], "programs")?;
        if programs.len() > LIVE_TV_CONFIG_MAX_PROGRAMS.saturating_sub(self.programs.len()) {
            return Err(ApiError::internal(
                "Live TV provider catalogue exceeded the program limit",
            ));
        }
        self.channels.extend(channels);
        self.categories.extend(categories);
        self.programs.extend(programs);

        let continuation_token = live_tv_plugin_catalog_continuation_token(&value)?;
        let has_more = match json_field_case_insensitive(&value, "HasMore") {
            None | Some(serde_json::Value::Null) => None,
            Some(serde_json::Value::Bool(value)) => Some(*value),
            Some(_) => {
                return Err(ApiError::internal(
                    "Live TV provider catalogue returned an invalid continuation marker",
                ));
            }
        };
        if matches!(has_more, Some(true)) && continuation_token.is_none()
            || matches!(has_more, Some(false)) && continuation_token.is_some()
        {
            return Err(ApiError::internal(
                "Live TV provider catalogue returned inconsistent continuation state",
            ));
        }
        let Some(continuation_token) = continuation_token else {
            return Ok(None);
        };
        if self.page_count >= LIVE_TV_PROVIDER_CATALOG_MAX_PAGES {
            return Err(ApiError::internal(
                "Live TV provider catalogue exceeded the page limit",
            ));
        }
        if !self.continuation_tokens.insert(continuation_token.clone()) {
            return Err(ApiError::internal(
                "Live TV provider catalogue repeated a continuation token",
            ));
        }
        Ok(Some(continuation_token))
    }

    fn into_capability_result(self) -> CapabilityResult {
        CapabilityResult {
            value: serde_json::json!({
                "Channels": self.channels,
                "Categories": self.categories,
                "Programs": self.programs
            }),
        }
    }
}

struct LiveTvPluginCatalogSizeCounter {
    bytes: usize,
    max_bytes: usize,
    exceeded: bool,
}

impl std::io::Write for LiveTvPluginCatalogSizeCounter {
    fn write(&mut self, buffer: &[u8]) -> std::io::Result<usize> {
        if buffer.len() > self.max_bytes.saturating_sub(self.bytes) {
            self.exceeded = true;
            return Err(std::io::Error::other(
                "Live TV provider catalogue exceeded the accumulated byte limit",
            ));
        }
        self.bytes += buffer.len();
        Ok(buffer.len())
    }

    fn flush(&mut self) -> std::io::Result<()> {
        Ok(())
    }
}

fn live_tv_plugin_catalog_encoded_size(
    value: &serde_json::Value,
    max_bytes: usize,
) -> Result<usize, ApiError> {
    let mut counter = LiveTvPluginCatalogSizeCounter {
        bytes: 0,
        max_bytes,
        exceeded: false,
    };
    if serde_json::to_writer(&mut counter, value).is_err() {
        return Err(ApiError::internal(if counter.exceeded {
            "Live TV provider catalogue exceeded the accumulated byte limit"
        } else {
            "Live TV provider catalogue response could not be measured"
        }));
    }
    Ok(counter.bytes)
}

fn live_tv_plugin_catalog_array(
    value: &serde_json::Value,
    field_names: &[&str],
    label: &str,
) -> Result<Vec<serde_json::Value>, ApiError> {
    let Some(items) = field_names
        .iter()
        .find_map(|field| json_field_case_insensitive(value, field))
    else {
        return Ok(Vec::new());
    };
    items.as_array().cloned().ok_or_else(|| {
        ApiError::internal(format!(
            "Live TV provider catalogue returned invalid {label}"
        ))
    })
}

fn live_tv_plugin_catalog_continuation_token(
    value: &serde_json::Value,
) -> Result<Option<String>, ApiError> {
    let Some(token) = json_field_case_insensitive(value, "ContinuationToken") else {
        return Ok(None);
    };
    let token = match token {
        serde_json::Value::Null => return Ok(None),
        serde_json::Value::String(token) => token,
        _ => {
            return Err(ApiError::internal(
                "Live TV provider catalogue returned an invalid continuation token",
            ));
        }
    };
    if token.is_empty()
        || token.len() > LIVE_TV_PROVIDER_CONTINUATION_TOKEN_MAX_BYTES
        || token.chars().any(char::is_control)
    {
        return Err(ApiError::internal(
            "Live TV provider catalogue returned an invalid continuation token",
        ));
    }
    Ok(Some(token.clone()))
}

fn set_live_tv_provider_catalog_request_page(
    request: &mut serde_json::Value,
    continuation_token: Option<&str>,
) -> Result<(), ApiError> {
    let object = request
        .as_object_mut()
        .ok_or_else(|| ApiError::internal("invalid Live TV provider request"))?;
    let arguments = continuation_token.map_or_else(
        || serde_json::json!({}),
        |token| serde_json::json!({ "ContinuationToken": token }),
    );
    object.insert("Arguments".to_string(), arguments);
    Ok(())
}

struct ZeroizingJsonValue(serde_json::Value);

struct ZeroizingInvokeEnvelope(PluginRpcEnvelope<InvokeCapabilityRequest>);

impl ZeroizingInvokeEnvelope {
    fn scrub(&mut self) {
        zeroize_json_value_strings(&mut self.0.payload.arguments);
    }
}

fn zeroize_json_value_strings(value: &mut serde_json::Value) {
    match value {
        serde_json::Value::String(value) => value.zeroize(),
        serde_json::Value::Array(values) => {
            values.iter_mut().for_each(zeroize_json_value_strings);
        }
        serde_json::Value::Object(object) => {
            // `serde_json::Map` does not expose mutable keys. This value is being discarded, so
            // take the map apart and scrub both property names and values instead of rebuilding it.
            for (mut key, mut value) in std::mem::take(object) {
                key.zeroize();
                zeroize_json_value_strings(&mut value);
            }
        }
        _ => {}
    }
}

impl Drop for ZeroizingJsonValue {
    fn drop(&mut self) {
        zeroize_json_value_strings(&mut self.0);
    }
}

impl Drop for ZeroizingInvokeEnvelope {
    fn drop(&mut self) {
        self.scrub();
    }
}

fn live_tv_provider_catalog_remaining(
    deadline: tokio::time::Instant,
) -> Result<StdDuration, ApiError> {
    deadline
        .checked_duration_since(tokio::time::Instant::now())
        .filter(|remaining| !remaining.is_zero())
        .ok_or_else(|| ApiError::internal("Live TV provider catalogue import timed out"))
}

async fn collect_live_tv_provider_catalog_pages(
    client: &mut PluginHostStdioClient,
    plugin_id: &str,
    capability: &str,
    base_request: serde_json::Value,
    deadline: tokio::time::Instant,
) -> Result<Option<CapabilityResult>, ApiError> {
    let mut pages = LiveTvPluginCatalogPages::default();
    let mut continuation_token = None;
    let mut base_request = ZeroizingJsonValue(base_request);
    loop {
        set_live_tv_provider_catalog_request_page(
            &mut base_request.0,
            continuation_token.as_deref(),
        )?;
        let remaining = live_tv_provider_catalog_remaining(deadline)?;
        let timeout_ms = u64::try_from(remaining.as_millis())
            .unwrap_or(u64::MAX)
            .max(1);
        let mut invoke = ZeroizingInvokeEnvelope(PluginRpcEnvelope::new(
            format!(
                "{plugin_id}:capability:{capability}:page:{}",
                pages.page_count.saturating_add(1)
            ),
            PluginRpcMethod::InvokeCapability,
            InvokeCapabilityRequest {
                plugin_id: plugin_id.to_string(),
                capability: capability.to_string(),
                arguments: std::mem::take(&mut base_request.0),
                timeout_ms,
            },
        ));
        let response = client
            .call::<_, CapabilityResult>(&invoke.0, remaining)
            .await;
        // Restore ownership before inspecting the result so every return path scrubs the
        // one in-memory JSON copy that carried the short-lived provider grant.
        base_request.0 = std::mem::take(&mut invoke.0.payload.arguments);
        let response =
            response.map_err(|_| ApiError::internal("Live TV provider catalogue import failed"))?;
        let Some(mut result) = rpc_result(response)? else {
            return Ok(None);
        };
        let canaries = live_tv_provider_secret_canaries(&base_request.0);
        if json_contains_sensitive_canary(&result.value, &canaries) {
            zeroize_json_value_strings(&mut result.value);
            return Err(ApiError::internal(
                "Live TV plugin provider returned forbidden credential material",
            ));
        }
        continuation_token = pages.push(result.value)?;
        if continuation_token.is_none() {
            return Ok(Some(pages.into_capability_result()));
        }
    }
}

#[allow(clippy::too_many_arguments)]
async fn invoke_live_tv_provider_catalog_via_runtime_host_path(
    plugin: &serde_json::Value,
    capability: &str,
    base_request: serde_json::Value,
    runtime: PluginRuntime,
    runtime_name: &str,
    error_prefix: &str,
    host_path: PathBuf,
    timeout: StdDuration,
) -> Result<Option<CapabilityResult>, ApiError> {
    let Some(plugin_id) = json_string_field(plugin, "Id") else {
        return Ok(None);
    };
    let deadline = tokio::time::Instant::now() + timeout;
    if runtime == PluginRuntime::ExternalProcess {
        let remaining = live_tv_provider_catalog_remaining(deadline)?;
        let guard = tokio::time::timeout(
            remaining,
            locked_external_plugin_host_in_lane(plugin, host_path, "catalog-import"),
        )
        .await
        .map_err(|_| ApiError::internal("Live TV provider catalogue import timed out"))??;
        let mut host_lease = ExternalPluginHostLease::new(guard, true);
        let result = match host_lease.host_mut() {
            Some(host) => {
                collect_live_tv_provider_catalog_pages(
                    &mut host.client,
                    &plugin_id,
                    capability,
                    base_request,
                    deadline,
                )
                .await
            }
            None => Err(ApiError::internal("ExternalProcess host is unavailable")),
        };
        // The same isolated process serves every page, then releases all provider snapshot state.
        host_lease.shutdown().await;
        return result;
    }

    let remaining = live_tv_provider_catalog_remaining(deadline)?;
    let loaded = tokio::time::timeout(
        remaining,
        load_plugin_runtime_host_with_path(plugin, runtime, runtime_name, error_prefix, host_path),
    )
    .await
    .map_err(|_| ApiError::internal("Live TV provider catalogue import timed out"))??;
    let Some((mut client, _version)) = loaded else {
        return Ok(None);
    };
    let result = collect_live_tv_provider_catalog_pages(
        &mut client,
        &plugin_id,
        capability,
        base_request,
        deadline,
    )
    .await;
    let _ = client.shutdown().await;
    result
}

#[derive(Debug, Default)]
struct VodPluginCatalogPages {
    continuation_tokens: HashSet<String>,
    page_count: usize,
    media_item_count: usize,
    movie_count: Option<u64>,
    series_count: Option<u64>,
    episode_count: Option<u64>,
}

#[derive(Debug)]
struct VodPluginCatalogPage {
    media_items: Vec<serde_json::Value>,
    continuation_token: Option<String>,
}

impl VodPluginCatalogPages {
    fn push(&mut self, value: serde_json::Value) -> Result<VodPluginCatalogPage, ApiError> {
        if self.page_count >= VOD_LIBRARY_PROVIDER_CATALOG_MAX_PAGES {
            return Err(ApiError::internal(
                "VOD library provider catalogue exceeded the page limit",
            ));
        }

        let media_items = live_tv_plugin_catalog_array(&value, &["MediaItems"], "media items")?;
        if media_items.len()
            > VOD_LIBRARY_PROVIDER_CATALOG_MAX_ITEMS.saturating_sub(self.media_item_count)
        {
            return Err(ApiError::internal(
                "VOD library provider catalogue exceeded the media item limit",
            ));
        }
        let movie_count = vod_library_plugin_catalog_count(&value, "MovieCount")?;
        let series_count = vod_library_plugin_catalog_count(&value, "SeriesCount")?;
        let episode_count = vod_library_plugin_catalog_count(&value, "EpisodeCount")?;
        if [movie_count, series_count, episode_count]
            .into_iter()
            .flatten()
            .any(|count| count > VOD_LIBRARY_PROVIDER_CATALOG_MAX_ITEMS as u64)
        {
            return Err(ApiError::internal(
                "VOD library provider catalogue reported an item count above the limit",
            ));
        }

        let continuation_token = live_tv_plugin_catalog_continuation_token(&value)?;
        let has_more = match json_field_case_insensitive(&value, "HasMore") {
            None | Some(serde_json::Value::Null) => None,
            Some(serde_json::Value::Bool(value)) => Some(*value),
            Some(_) => {
                return Err(ApiError::internal(
                    "VOD library provider catalogue returned an invalid continuation marker",
                ));
            }
        };
        if matches!(has_more, Some(true)) && continuation_token.is_none()
            || matches!(has_more, Some(false)) && continuation_token.is_some()
        {
            return Err(ApiError::internal(
                "VOD library provider catalogue returned inconsistent continuation state",
            ));
        }
        if let Some(token) = continuation_token.as_ref() {
            if self.page_count.saturating_add(1) >= VOD_LIBRARY_PROVIDER_CATALOG_MAX_PAGES {
                return Err(ApiError::internal(
                    "VOD library provider catalogue exceeded the page limit",
                ));
            }
            if self.continuation_tokens.contains(token) {
                return Err(ApiError::internal(
                    "VOD library provider catalogue repeated a continuation token",
                ));
            }
        }

        self.page_count += 1;
        self.media_item_count = self.media_item_count.saturating_add(media_items.len());
        self.movie_count = movie_count.or(self.movie_count);
        self.series_count = series_count.or(self.series_count);
        self.episode_count = episode_count.or(self.episode_count);
        if let Some(token) = continuation_token.as_ref() {
            self.continuation_tokens.insert(token.clone());
        }
        Ok(VodPluginCatalogPage {
            media_items,
            continuation_token,
        })
    }
}

fn vod_library_plugin_catalog_count(
    value: &serde_json::Value,
    field: &str,
) -> Result<Option<u64>, ApiError> {
    let Some(count) = json_field_case_insensitive(value, field) else {
        return Ok(None);
    };
    match count {
        serde_json::Value::Null => Ok(None),
        serde_json::Value::Number(number) => number.as_u64().map(Some).ok_or_else(|| {
            ApiError::internal("VOD library provider catalogue returned an invalid item count")
        }),
        _ => Err(ApiError::internal(
            "VOD library provider catalogue returned an invalid item count",
        )),
    }
}

fn vod_library_provider_catalog_remaining(
    deadline: tokio::time::Instant,
) -> Result<StdDuration, ApiError> {
    deadline
        .checked_duration_since(tokio::time::Instant::now())
        .filter(|remaining| !remaining.is_zero())
        .ok_or_else(|| ApiError::internal("VOD library provider catalogue import timed out"))
}

fn vod_library_provider_catalog_timeout_seconds_from_value(value: Option<&str>) -> u64 {
    value
        .map(str::trim)
        .and_then(|value| value.parse::<u64>().ok())
        .filter(|seconds| *seconds > 0)
        .map(|seconds| {
            seconds.clamp(
                MIN_VOD_LIBRARY_PROVIDER_CATALOG_TIMEOUT_SECONDS,
                MAX_VOD_LIBRARY_PROVIDER_CATALOG_TIMEOUT_SECONDS,
            )
        })
        .unwrap_or(DEFAULT_VOD_LIBRARY_PROVIDER_CATALOG_TIMEOUT_SECONDS)
}

fn vod_library_provider_catalog_timeout() -> StdDuration {
    static TIMEOUT: OnceLock<StdDuration> = OnceLock::new();
    *TIMEOUT.get_or_init(|| {
        let seconds = vod_library_provider_catalog_timeout_seconds_from_value(
            std::env::var("JELLYRIN_VOD_LIBRARY_PROVIDER_CATALOG_TIMEOUT_SECONDS")
                .ok()
                .as_deref(),
        );
        tracing::info!(
            seconds,
            maximum_seconds = MAX_VOD_LIBRARY_PROVIDER_CATALOG_TIMEOUT_SECONDS,
            "configured VOD library provider catalogue deadline"
        );
        StdDuration::from_secs(seconds)
    })
}

async fn collect_vod_library_provider_pages(
    client: &mut PluginHostStdioClient,
    plugin_id: &str,
    capability: &str,
    base_request: serde_json::Value,
    deadline: tokio::time::Instant,
    writer: &mut VodPluginCatalogStageWriter<'_>,
) -> Result<Option<VodLibraryPluginImportCounts>, ApiError> {
    let mut pages = VodPluginCatalogPages::default();
    let mut continuation_token = None;
    let mut base_request = ZeroizingJsonValue(base_request);
    loop {
        set_live_tv_provider_catalog_request_page(
            &mut base_request.0,
            continuation_token.as_deref(),
        )?;
        let remaining = vod_library_provider_catalog_remaining(deadline)?;
        let timeout_ms = u64::try_from(remaining.as_millis())
            .unwrap_or(u64::MAX)
            .max(1);
        let mut invoke = ZeroizingInvokeEnvelope(PluginRpcEnvelope::new(
            format!(
                "{plugin_id}:capability:{capability}:page:{}",
                pages.page_count.saturating_add(1)
            ),
            PluginRpcMethod::InvokeCapability,
            InvokeCapabilityRequest {
                plugin_id: plugin_id.to_string(),
                capability: capability.to_string(),
                arguments: std::mem::take(&mut base_request.0),
                timeout_ms,
            },
        ));
        let response = client
            .call::<_, CapabilityResult>(&invoke.0, remaining)
            .await;
        // Restore ownership before inspecting the result so every return path scrubs the
        // one in-memory JSON copy that carried the short-lived provider grant.
        base_request.0 = std::mem::take(&mut invoke.0.payload.arguments);
        let response = response
            .map_err(|_| ApiError::internal("VOD library provider catalogue import failed"))?;
        let Some(mut result) = rpc_result(response)? else {
            return Ok(None);
        };
        let canaries = live_tv_provider_secret_canaries(&base_request.0);
        if json_contains_sensitive_canary(&result.value, &canaries) {
            zeroize_json_value_strings(&mut result.value);
            return Err(ApiError::internal(
                "VOD library plugin provider returned forbidden credential material",
            ));
        }
        let page = pages.push(result.value)?;
        continuation_token = page.continuation_token;
        writer.append_page(page.media_items).await?;
        if continuation_token.is_none() {
            return Ok(Some(writer.counts()));
        }
    }
}

#[allow(clippy::too_many_arguments)]
async fn invoke_vod_library_provider_via_runtime_host_path(
    plugin: &serde_json::Value,
    capability: &str,
    base_request: serde_json::Value,
    runtime: PluginRuntime,
    runtime_name: &str,
    error_prefix: &str,
    host_path: PathBuf,
    timeout: StdDuration,
    writer: &mut VodPluginCatalogStageWriter<'_>,
) -> Result<Option<VodLibraryPluginImportCounts>, ApiError> {
    let Some(plugin_id) = json_string_field(plugin, "Id") else {
        return Ok(None);
    };
    let deadline = tokio::time::Instant::now() + timeout;
    if runtime == PluginRuntime::ExternalProcess {
        let remaining = vod_library_provider_catalog_remaining(deadline)?;
        let guard = tokio::time::timeout(
            remaining,
            locked_external_plugin_host_in_lane(plugin, host_path, "catalog-import"),
        )
        .await
        .map_err(|_| ApiError::internal("VOD library provider catalogue import timed out"))??;
        let mut host_lease = ExternalPluginHostLease::new(guard, true);
        let result = match host_lease.host_mut() {
            Some(host) => {
                collect_vod_library_provider_pages(
                    &mut host.client,
                    &plugin_id,
                    capability,
                    base_request,
                    deadline,
                    writer,
                )
                .await
            }
            None => Err(ApiError::internal("ExternalProcess host is unavailable")),
        };
        // The same isolated process serves every page, then releases all provider snapshot state.
        host_lease.shutdown().await;
        return result;
    }

    let remaining = vod_library_provider_catalog_remaining(deadline)?;
    let loaded = tokio::time::timeout(
        remaining,
        load_plugin_runtime_host_with_path(plugin, runtime, runtime_name, error_prefix, host_path),
    )
    .await
    .map_err(|_| ApiError::internal("VOD library provider catalogue import timed out"))??;
    let Some((mut client, _version)) = loaded else {
        return Ok(None);
    };
    let result = collect_vod_library_provider_pages(
        &mut client,
        &plugin_id,
        capability,
        base_request,
        deadline,
        writer,
    )
    .await;
    let _ = client.shutdown().await;
    result
}

fn is_external_catalog_import_call(capability: &str, arguments: &serde_json::Value) -> bool {
    capability.eq_ignore_ascii_case(CAPABILITY_LIVE_TV_PROVIDER)
        && ["Action", "Operation"].iter().any(|field| {
            json_string_field(arguments, field)
                .is_some_and(|action| action.eq_ignore_ascii_case("ImportChannels"))
        })
}

fn is_external_provider_jit_call(capability: &str, arguments: &serde_json::Value) -> bool {
    let Some(action) = json_string_field(arguments, "Action") else {
        return false;
    };
    if capability.eq_ignore_ascii_case(CAPABILITY_LIVE_TV_PROVIDER) {
        return action.eq_ignore_ascii_case("ResolvePlayback");
    }
    capability.eq_ignore_ascii_case(CAPABILITY_VOD_LIBRARY_PROVIDER)
        && ["ResolveMetadata", "ResolvePlayback", "ResolveSubtitle"]
            .iter()
            .any(|candidate| action.eq_ignore_ascii_case(candidate))
}

fn external_provider_jit_lane(tuner_id: &str) -> Option<String> {
    let tuner_id = tuner_id.trim();
    (!tuner_id.is_empty()).then(|| {
        format!(
            "{EXTERNAL_PLUGIN_PROVIDER_JIT_LANE_PREFIX}:{}",
            tuner_id.to_ascii_lowercase()
        )
    })
}

fn external_provider_jit_lane_for_call(
    capability: &str,
    arguments: &serde_json::Value,
) -> Option<String> {
    if !is_external_provider_jit_call(capability, arguments) {
        return None;
    }
    ["TunerConfig", "ProviderConfig"]
        .iter()
        .find_map(|field| json_field_case_insensitive(arguments, field))
        .and_then(|config| json_string_field(config, "Id"))
        .and_then(|tuner_id| external_provider_jit_lane(&tuner_id))
}

#[derive(Debug, Default, Deserialize)]
struct PluginLogsQuery {
    #[serde(flatten)]
    auth: AuthQuery,
    #[serde(alias = "Limit")]
    limit: Option<i64>,
}

async fn plugin_health(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    Path(plugin_id): Path<String>,
) -> Result<Json<serde_json::Value>, ApiError> {
    require_admin(&state.db, &headers, query.api_key.as_deref()).await?;
    state
        .db
        .plugin_health_json(&plugin_id)
        .await?
        .map(Json)
        .ok_or_else(|| ApiError::not_found("Plugin not found"))
}

async fn plugin_logs(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<PluginLogsQuery>,
    Path(plugin_id): Path<String>,
) -> Result<Json<serde_json::Value>, ApiError> {
    require_admin(&state.db, &headers, query.auth.api_key.as_deref()).await?;
    state
        .db
        .plugin_host_events_json(&plugin_id, query.limit.unwrap_or(50))
        .await?
        .map(|items| {
            Json(serde_json::json!({
                "Items": items,
                "TotalRecordCount": items.len(),
                "StartIndex": 0
            }))
        })
        .ok_or_else(|| ApiError::not_found("Plugin not found"))
}

async fn refresh_vod_library_plugin(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    Path(plugin_id): Path<String>,
) -> Result<Json<serde_json::Value>, ApiError> {
    require_admin(&state.db, &headers, query.api_key.as_deref()).await?;
    let counts = vod_library_plugin_media_import(&state.db, &plugin_id)
        .await?
        .ok_or_else(|| ApiError::not_found("VOD library plugin has no configured Live TV tuner"))?;
    Ok(Json(serde_json::json!({
        "MovieCount": counts.movie_count,
        "SeriesCount": counts.series_count,
        "EpisodeCount": counts.episode_count,
    })))
}

