async fn load_plugin_runtime_host_with_path(
    plugin: &serde_json::Value,
    runtime: PluginRuntime,
    runtime_name: &str,
    error_prefix: &str,
    host_path: PathBuf,
) -> Result<Option<(PluginHostStdioClient, String)>, ApiError> {
    if runtime == PluginRuntime::ExternalProcess {
        return Err(ApiError::internal(
            "ExternalProcess plugins must use the supervised host registry",
        ));
    }
    let Some(plugin_id) = json_string_field(plugin, "Id") else {
        return Ok(None);
    };
    let version = json_string_field(plugin, "Version").unwrap_or_default();
    let manifest = plugin
        .get("Manifest")
        .cloned()
        .unwrap_or_else(|| serde_json::json!({}));
    let Some(install_path) = plugin_install_path(plugin).or_else(|| plugin_install_path(&manifest))
    else {
        return Ok(None);
    };

    let mut client =
        PluginHostStdioClient::spawn(&mut Command::new(&host_path)).map_err(|error| {
            ApiError::internal(format!("{error_prefix} host failed to start: {error}"))
        })?;
    let handshake = PluginRpcEnvelope::new(
        format!("{plugin_id}:host-handshake"),
        PluginRpcMethod::Handshake,
        HandshakeRequest {
            runtime: runtime.clone(),
            runtime_version: "0.1.0".to_string(),
            host_id: "jellyrin-api".to_string(),
            supported_protocol_versions: vec![PLUGIN_RPC_PROTOCOL_VERSION],
            capabilities: vec![
                "LoadPlugin".to_string(),
                "GetConfiguration".to_string(),
                "UpdateConfiguration".to_string(),
            ],
        },
    );
    let handshake_response = client
        .call::<_, HandshakeResponse>(&handshake, StdDuration::from_secs(5))
        .await
        .map_err(|error| {
            ApiError::internal(format!("{error_prefix} host handshake failed: {error}"))
        })?;
    if rpc_result(handshake_response)?.is_none() {
        let _ = client.shutdown().await;
        return Ok(None);
    }

    let load = PluginRpcEnvelope::new(
        format!("{plugin_id}:host-load"),
        PluginRpcMethod::LoadPlugin,
        LoadPluginRequest {
            plugin_id: plugin_id.clone(),
            name: json_string_field(plugin, "Name").unwrap_or_else(|| plugin_id.clone()),
            version: version.clone(),
            runtime,
            target_abi: json_string_field(plugin, "TargetAbi").unwrap_or_default(),
            install_path,
            manifest,
            permissions: plugin_string_array(plugin.get("Permissions")),
        },
    );
    let load_response = client
        .call::<_, LoadedPlugin>(&load, StdDuration::from_secs(5))
        .await
        .map_err(|error| ApiError::internal(format!("{error_prefix} host load failed: {error}")))?;
    if rpc_result(load_response)?.is_none() {
        let _ = client.shutdown().await;
        return Ok(None);
    }
    tracing::debug!(
        plugin_id,
        runtime = runtime_name,
        "loaded plugin runtime host"
    );
    Ok(Some((client, version)))
}

async fn activate_plugin_with_host_path(
    db: &Database,
    plugin: &serde_json::Value,
    actor_user_id: Option<Uuid>,
    host_path: PathBuf,
    runtime: PluginRuntime,
    runtime_name: &str,
    error_prefix: &str,
) -> Result<bool, ApiError> {
    let Some(plugin_id) = json_string_field(plugin, "Id") else {
        return Ok(false);
    };
    let version = json_string_field(plugin, "Version").unwrap_or_default();
    let manifest = plugin
        .get("Manifest")
        .cloned()
        .unwrap_or_else(|| serde_json::json!({}));
    let Some(install_path) = plugin_install_path(plugin).or_else(|| plugin_install_path(&manifest))
    else {
        return Ok(false);
    };

    let mut client =
        PluginHostStdioClient::spawn(&mut Command::new(&host_path)).map_err(|error| {
            ApiError::internal(format!("{error_prefix} host failed to start: {error}"))
        })?;
    let handshake = PluginRpcEnvelope::new(
        format!("{plugin_id}:handshake"),
        PluginRpcMethod::Handshake,
        HandshakeRequest {
            runtime: runtime.clone(),
            runtime_version: "0.1.0".to_string(),
            host_id: "jellyrin-api".to_string(),
            supported_protocol_versions: vec![PLUGIN_RPC_PROTOCOL_VERSION],
            capabilities: vec!["LoadPlugin".to_string(), "Health".to_string()],
        },
    );
    let handshake_response = client
        .call::<_, HandshakeResponse>(&handshake, StdDuration::from_secs(5))
        .await
        .map_err(|error| {
            ApiError::internal(format!("{error_prefix} host handshake failed: {error}"))
        })?;
    let Some(handshake_result) = rpc_result(handshake_response)? else {
        return Ok(false);
    };

    let load = PluginRpcEnvelope::new(
        format!("{plugin_id}:load"),
        PluginRpcMethod::LoadPlugin,
        LoadPluginRequest {
            plugin_id: plugin_id.clone(),
            name: json_string_field(plugin, "Name").unwrap_or_else(|| plugin_id.clone()),
            version: version.clone(),
            runtime: runtime.clone(),
            target_abi: json_string_field(plugin, "TargetAbi").unwrap_or_default(),
            install_path,
            manifest: manifest.clone(),
            permissions: plugin_string_array(plugin.get("Permissions")),
        },
    );
    let load_response = client
        .call::<_, LoadedPlugin>(&load, StdDuration::from_secs(5))
        .await
        .map_err(|error| ApiError::internal(format!("{error_prefix} host load failed: {error}")))?;
    let Some(loaded) = rpc_result(load_response)? else {
        return Ok(false);
    };

    let health = PluginRpcEnvelope::new(
        format!("{plugin_id}:health"),
        PluginRpcMethod::Health,
        PluginIdentity {
            plugin_id: plugin_id.clone(),
            version,
        },
    );
    let health_response = client
        .call::<_, PluginHealth>(&health, StdDuration::from_secs(5))
        .await
        .map_err(|error| {
            ApiError::internal(format!("{error_prefix} host health failed: {error}"))
        })?;
    let Some(health) = rpc_result(health_response)? else {
        return Ok(false);
    };

    PluginService::new(db)
        .upsert_runtime_instance(
            PluginRuntimeInstanceUpsert {
                plugin_id,
                runtime: runtime_name.to_string(),
                runtime_version: handshake_result.server_version,
                status: "Active".to_string(),
                process_id: None,
                endpoint: Some(host_path.to_string_lossy().to_string()),
                health: serde_json::to_value(health)?,
                capabilities: loaded.capabilities,
                last_error: None,
            },
            actor_user_id,
        )
        .await?;
    let _ = client.shutdown().await;
    Ok(true)
}

fn rpc_result<T>(
    response: jellyrin_plugin_rpc::PluginRpcResponse<T>,
) -> Result<Option<T>, ApiError> {
    if response.ok {
        return Ok(response.result);
    }
    // Plugin-provided messages and details are untrusted and may contain expiring source URLs,
    // credentials, or other provider secrets. Only surface the typed, bounded error code.
    let code = response
        .error
        .as_ref()
        .map(|error| plugin_rpc_error_code_label(&error.code))
        .unwrap_or("Unknown");
    Err(ApiError::internal(format!(
        "Plugin runtime request failed ({code})"
    )))
}

fn plugin_rpc_error_code_label(code: &PluginRpcErrorCode) -> &'static str {
    match code {
        PluginRpcErrorCode::InvalidRequest => "InvalidRequest",
        PluginRpcErrorCode::ProtocolVersionMismatch => "ProtocolVersionMismatch",
        PluginRpcErrorCode::UnsupportedMethod => "UnsupportedMethod",
        PluginRpcErrorCode::PluginNotFound => "PluginNotFound",
        PluginRpcErrorCode::PluginNotLoaded => "PluginNotLoaded",
        PluginRpcErrorCode::CapabilityNotFound => "CapabilityNotFound",
        PluginRpcErrorCode::PermissionDenied => "PermissionDenied",
        PluginRpcErrorCode::Timeout => "Timeout",
        PluginRpcErrorCode::HostUnavailable => "HostUnavailable",
        PluginRpcErrorCode::HostFailed => "HostFailed",
    }
}

fn provider_secret_rpc_result<T>(
    response: jellyrin_plugin_rpc::PluginRpcResponse<T>,
) -> Result<Option<T>, ApiError> {
    let code = response
        .error
        .as_ref()
        .map(|error| plugin_rpc_error_code_label(&error.code))
        .unwrap_or("Unknown");
    rpc_result(response).map_err(|_| {
        ApiError::internal(format!(
            "ExternalProcess provider-secret invocation failed ({code})"
        ))
    })
}

fn bounded_plugin_runtime_error_code(error: &ApiError) -> &'static str {
    let message = error.error.to_string();
    let code = [
        "Plugin runtime request failed (",
        "ExternalProcess provider-secret invocation failed (",
    ]
    .iter()
    .find_map(|prefix| {
        message
            .strip_prefix(prefix)
            .and_then(|value| value.strip_suffix(')'))
    })
    .map(|value| value.trim_matches('"'));
    match code {
        Some("InvalidRequest") => "InvalidRequest",
        Some("ProtocolVersionMismatch") => "ProtocolVersionMismatch",
        Some("UnsupportedMethod") => "UnsupportedMethod",
        Some("PluginNotFound") => "PluginNotFound",
        Some("PluginNotLoaded") => "PluginNotLoaded",
        Some("CapabilityNotFound") => "CapabilityNotFound",
        Some("PermissionDenied") => "PermissionDenied",
        Some("Timeout") => "Timeout",
        Some("HostUnavailable") => "HostUnavailable",
        Some("HostFailed") => "HostFailed",
        _ => "RuntimeFailure",
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct PluginRuntimeFailureTelemetry {
    action: &'static str,
    phase: &'static str,
    provider_error_code: &'static str,
}

fn plugin_vod_metadata_runtime_failure_telemetry(
    error: &ApiError,
) -> PluginRuntimeFailureTelemetry {
    PluginRuntimeFailureTelemetry {
        action: "ResolveMetadata",
        phase: "runtime_invoke",
        provider_error_code: bounded_plugin_runtime_error_code(error),
    }
}

fn map_plugin_vod_metadata_runtime_failure(error: ApiError) -> ApiError {
    let telemetry = plugin_vod_metadata_runtime_failure_telemetry(&error);
    tracing::warn!(
        action = telemetry.action,
        phase = telemetry.phase,
        provider_error_code = telemetry.provider_error_code,
        "VOD metadata plugin invocation failed"
    );
    ApiError::service_unavailable("VOD metadata resolution failed")
}

