async fn require_installed_plugin_version(
    db: &Database,
    plugin_id: &str,
    version: &str,
) -> Result<(), ApiError> {
    db.installed_plugins_json()
        .await?
        .into_iter()
        .find(|plugin| {
            json_string_field(plugin, "Id").is_some_and(|id| id.eq_ignore_ascii_case(plugin_id))
                && json_string_field(plugin, "Version")
                    .is_some_and(|candidate| candidate.eq_ignore_ascii_case(version.trim()))
        })
        .map(|_| ())
        .ok_or_else(|| ApiError::not_found("Plugin not found"))
}

async fn plugin_manifest(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    Path(plugin_id): Path<String>,
) -> Result<Json<serde_json::Value>, ApiError> {
    require_admin(&state.db, &headers, query.api_key.as_deref()).await?;
    if let Some(manifest) = state.db.installed_plugin_manifest(&plugin_id).await? {
        return Ok(Json(manifest));
    }
    if let Some(package) = package_infos_from_repositories(
        &state
            .db
            .system_configuration_payloads()
            .await?
            .plugin_repositories,
    )
    .into_iter()
    .find(|package| package_matches_plugin_id(package, &plugin_id))
    {
        return Ok(Json(plugin_manifest_from_package(package)));
    }
    Ok(Json(serde_json::json!({
        "Guid": plugin_id,
        "Name": plugin_id,
        "Overview": "Plugin manifests are not supported by Jellyrin yet.",
        "Description": "Plugin compatibility is intentionally disabled in this milestone.",
        "Owner": "Jellyrin",
        "Category": "General",
        "Versions": []
    })))
}

async fn plugin_manifest_post(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    Path(plugin_id): Path<String>,
) -> Result<Json<serde_json::Value>, ApiError> {
    plugin_manifest(State(state), headers, Query(query), Path(plugin_id)).await
}

fn package_matches_plugin_id(package: &serde_json::Value, plugin_id: &str) -> bool {
    let plugin_id = plugin_id.trim();
    json_string_field(package, "Guid").is_some_and(|guid| guid.eq_ignore_ascii_case(plugin_id))
        || json_string_field(package, "Name").is_some_and(|name| {
            name.eq_ignore_ascii_case(plugin_id)
                || name.replace(' ', "").eq_ignore_ascii_case(plugin_id)
        })
}

fn plugin_manifest_from_package(package: serde_json::Value) -> serde_json::Value {
    let name = json_string_field(&package, "Name").unwrap_or_else(|| "Plugin".to_string());
    let guid =
        json_string_field(&package, "Guid").unwrap_or_else(|| stable_entity_id("Plugin", &name));
    serde_json::json!({
        "Guid": guid,
        "Name": name,
        "Overview": json_string_field(&package, "Overview").unwrap_or_default(),
        "Description": json_string_field(&package, "Description").unwrap_or_default(),
        "Owner": json_string_field(&package, "Owner").unwrap_or_else(|| "Jellyrin".to_string()),
        "Category": json_string_field(&package, "Category").unwrap_or_else(|| "General".to_string()),
        "ImageUrl": json_string_field(&package, "ImageUrl"),
        "Versions": package_versions(&package)
    })
}

async fn plugin_image(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    Path((plugin_id, version)): Path<(String, String)>,
) -> Result<axum::response::Response, ApiError> {
    require_admin(&state.db, &headers, query.api_key.as_deref()).await?;
    if let Some((bytes, content_type)) =
        plugin_image_from_runtime_host(&state.db, &plugin_id, &version).await?
    {
        let mut headers = HeaderMap::new();
        headers.insert(header::CONTENT_TYPE, content_type.parse().unwrap());
        headers.insert(
            header::CACHE_CONTROL,
            "public, max-age=3600".parse().unwrap(),
        );
        return Ok((headers, bytes).into_response());
    }
    if let Some(path) = plugin_image_path_from_catalog(
        &state
            .db
            .system_configuration_payloads()
            .await?
            .plugin_repositories,
        &plugin_id,
        &version,
    ) && tokio::fs::metadata(&path)
        .await
        .map(|metadata| metadata.is_file())
        .unwrap_or(false)
    {
        let content_type = path
            .extension()
            .and_then(|extension| extension.to_str())
            .map(|extension| image_format_from_extension(extension).content_type)
            .unwrap_or("application/octet-stream")
            .to_string();
        return stream_path(path, content_type, &headers, true).await;
    }
    Ok(placeholder_png_response())
}

async fn plugin_web_page_content(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    Path((plugin_id, page_name)): Path<(String, String)>,
) -> Result<Response<Body>, ApiError> {
    require_admin(&state.db, &headers, query.api_key.as_deref()).await?;
    // Built-in plugin web pages
    if plugin_id.eq_ignore_ascii_case(BUILTIN_XTREAM_PLUGIN_ID)
        && page_name.eq_ignore_ascii_case("configuration.html")
    {
        return Ok(Response::builder()
            .header("content-type", "text/html; charset=utf-8")
            .body(Body::from(XTREAM_CONFIG_HTML))
            .unwrap());
    }
    if let Some(content) =
        installed_plugin_web_page(&state.db, &plugin_id, &page_name, false).await?
    {
        return Ok(plugin_web_page_response(content));
    }
    Err(ApiError::not_found("Web page not found"))
}

async fn plugin_image_from_runtime_host(
    db: &Database,
    plugin_id: &str,
    version: &str,
) -> Result<Option<(Vec<u8>, String)>, ApiError> {
    let _admission_guard = external_plugin_host_admission_slot(plugin_id, "default")
        .await
        .acquire_owned()
        .await
        .map_err(|_| ApiError::service_unavailable("Plugin runtime is unavailable"))?;
    let security_slot = external_plugin_security_slot(plugin_id).await;
    let _security_guard = security_slot.read_owned().await;
    let Some(plugin) = db.installed_plugin_json(plugin_id).await? else {
        return Ok(None);
    };
    if !json_string_field(&plugin, "Status")
        .is_some_and(|status| status.eq_ignore_ascii_case("Active"))
    {
        return Ok(None);
    }
    if !json_string_field(&plugin, "Version")
        .unwrap_or_default()
        .eq_ignore_ascii_case(version.trim())
    {
        return Ok(None);
    }
    let Some((runtime, runtime_name, error_prefix, host_path)) = plugin_runtime_host_path(&plugin)
    else {
        return Ok(None);
    };
    plugin_image_from_runtime_host_path(
        &plugin,
        version,
        "Primary",
        runtime,
        runtime_name,
        error_prefix,
        host_path,
    )
    .await
}

async fn plugin_image_from_runtime_host_path(
    plugin: &serde_json::Value,
    version: &str,
    image_type: &str,
    runtime: PluginRuntime,
    runtime_name: &str,
    error_prefix: &str,
    host_path: PathBuf,
) -> Result<Option<(Vec<u8>, String)>, ApiError> {
    // External packages use their catalog/package image. Starting their executable through the
    // generic loader would bypass env_clear, permission fingerprinting and lifecycle supervision.
    if runtime == PluginRuntime::ExternalProcess {
        return Ok(None);
    }
    let Some(plugin_id) = json_string_field(plugin, "Id") else {
        return Ok(None);
    };
    let Some((mut client, loaded_version)) =
        load_plugin_runtime_host_with_path(plugin, runtime, runtime_name, error_prefix, host_path)
            .await?
    else {
        return Ok(None);
    };
    let image = PluginRpcEnvelope::new(
        format!("{plugin_id}:embedded-image"),
        PluginRpcMethod::GetEmbeddedImage,
        EmbeddedImageRequest {
            plugin_id,
            version: if version.trim().is_empty() {
                loaded_version
            } else {
                version.to_string()
            },
            image_type: image_type.to_string(),
        },
    );
    let response = client
        .call::<_, serde_json::Value>(&image, StdDuration::from_secs(5))
        .await
        .map_err(|error| ApiError::internal(format!("Plugin host image read failed: {error}")))?;
    let Some(result) = rpc_result(response)? else {
        let _ = client.shutdown().await;
        return Ok(None);
    };
    let _ = client.shutdown().await;
    let Some(encoded) = json_string_field(&result, "Base64Data") else {
        return Ok(None);
    };
    let bytes = general_purpose::STANDARD.decode(encoded).map_err(|error| {
        ApiError::internal(format!("Plugin host image payload failed: {error}"))
    })?;
    let content_type = json_string_field(&result, "MimeType")
        .unwrap_or_else(|| "application/octet-stream".to_string());
    Ok(Some((bytes, content_type)))
}

fn plugin_image_path_from_catalog(
    repositories: &serde_json::Value,
    plugin_id: &str,
    version: &str,
) -> Option<PathBuf> {
    package_infos_from_repositories(repositories)
        .into_iter()
        .find(|package| package_matches_plugin_id(package, plugin_id))
        .and_then(|package| {
            let version_path = package_versions(&package)
                .into_iter()
                .find(|candidate| {
                    json_string_field(candidate, "Version")
                        .is_some_and(|candidate| candidate.eq_ignore_ascii_case(version.trim()))
                })
                .and_then(|candidate| json_string_field(&candidate, "ImagePath"));
            version_path
                .or_else(|| json_string_field(&package, "ImagePath"))
                .map(PathBuf::from)
        })
}

async fn device_info(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    Query(query): Query<DeviceOptionsQuery>,
) -> Result<Json<serde_json::Value>, ApiError> {
    require_admin(&state.db, &headers, auth_query.api_key.as_deref()).await?;
    let service = SessionService::new(&state.db);
    let device = match trimmed_optional(query.id) {
        Some(id) => service.device_by_id(&id).await?,
        None => None,
    };
    Ok(Json(
        device
            .as_ref()
            .map(device_to_json)
            .unwrap_or_else(empty_device_info_json),
    ))
}

fn empty_device_info_json() -> serde_json::Value {
    serde_json::json!({
        "Name": null,
        "Id": null,
        "LastUserName": null,
        "AppName": null,
        "AppVersion": null,
        "LastUserId": null,
        "DateLastActivity": null,
        "Capabilities": null
    })
}

fn device_to_json(device: &DeviceSession) -> serde_json::Value {
    serde_json::json!({
        "Name": device.device_name,
        "Id": device.device_id,
        "LastUserName": device.user_name,
        "AppName": device.client,
        "AppVersion": device.version,
        "LastUserId": device.user_id,
        "DateLastActivity": format_time_for_json(device.last_activity_at),
        "Capabilities": device.capabilities.clone()
    })
}

#[derive(Debug, Deserialize)]
struct DeviceOptionsQuery {
    #[serde(alias = "Id", alias = "id")]
    id: Option<String>,
}

#[derive(Debug, Deserialize)]
struct DeviceOptionsUpdate {
    #[serde(alias = "CustomName")]
    custom_name: Option<String>,
}

async fn device_options(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    Query(query): Query<DeviceOptionsQuery>,
) -> Result<Json<serde_json::Value>, ApiError> {
    require_admin(&state.db, &headers, auth_query.api_key.as_deref()).await?;
    let service = SessionService::new(&state.db);
    let custom_name = if let Some(id) = trimmed_optional(query.id) {
        service
            .device_by_id(&id)
            .await?
            .map(|session| session.device_name)
    } else {
        None
    };
    Ok(Json(serde_json::json!({
        "CustomName": custom_name
    })))
}

async fn update_device_options(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    Query(query): Query<DeviceOptionsQuery>,
    Json(payload): Json<DeviceOptionsUpdate>,
) -> Result<StatusCode, ApiError> {
    let user = require_admin(&state.db, &headers, auth_query.api_key.as_deref()).await?;
    let service = SessionService::new(&state.db);
    let Some(id) = trimmed_optional(query.id) else {
        return Err(ApiError::bad_request("Device id is required"));
    };
    let Some(custom_name) = trimmed_optional(payload.custom_name) else {
        return Err(ApiError::bad_request("CustomName is required"));
    };
    if service.device_by_id(&id).await?.is_none() {
        return Err(ApiError::not_found("Device not found"));
    }
    service.update_device_name(&id, &custom_name).await?;
    record_activity(
        &state.db,
        "Device options updated",
        Some("A device custom name was updated."),
        "Device",
        Some(user.id),
    )
    .await?;
    Ok(StatusCode::NO_CONTENT)
}

fn trimmed_optional(value: Option<String>) -> Option<String> {
    value
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
}

#[derive(Debug, Deserialize)]
struct DeleteDeviceQuery {
    #[serde(alias = "Id", alias = "id")]
    id: Option<String>,
}

async fn delete_device(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    Query(query): Query<DeleteDeviceQuery>,
) -> Result<StatusCode, ApiError> {
    let user = require_admin(&state.db, &headers, auth_query.api_key.as_deref()).await?;
    let service = SessionService::new(&state.db);
    if let Some(id) = query
        .id
        .as_deref()
        .map(str::trim)
        .filter(|id| !id.is_empty())
    {
        service.revoke_device(id).await?;
        record_activity(
            &state.db,
            "Device deleted",
            Some("A device was revoked."),
            "Device",
            Some(user.id),
        )
        .await?;
    }
    Ok(StatusCode::NO_CONTENT)
}

async fn system_configuration(
    State(state): State<AppState>,
) -> Result<Json<serde_json::Value>, ApiError> {
    let enable_upnp = dlna::upnp_enabled(&state.db).await?;
    Ok(Json(system_configuration_json(
        state.db.startup_config().await?,
        state.db.server_state().await?.startup_wizard_completed,
        state.db.system_configuration_payloads().await?,
        enable_upnp,
    )))
}

#[derive(Debug, Deserialize)]
