fn enrich_live_tv_configuration_local_sources(config: &mut serde_json::Value) {
    if let Some(tuners) = config
        .get_mut("TunerHosts")
        .and_then(serde_json::Value::as_array_mut)
    {
        for tuner in tuners {
            let has_channels = tuner
                .get("Channels")
                .and_then(serde_json::Value::as_array)
                .is_some_and(|channels| !channels.is_empty());
            if !has_channels
                && let Some(path) = live_tv_local_config_path(tuner)
                && let Some(contents) =
                    read_bounded_live_tv_config_file(&path, LIVE_TV_CONFIG_SOURCE_LIMIT_BYTES)
            {
                let channels = live_tv_array_within_limit(
                    parse_live_tv_m3u_channels(&contents),
                    LIVE_TV_PROVIDER_CATALOG_MAX_CHANNELS,
                );
                if let Some(channels) = channels.filter(|channels| !channels.is_empty()) {
                    tuner["Channels"] = serde_json::json!(channels);
                }
            }
        }
    }
    if let Some(providers) = config
        .get_mut("ListingProviders")
        .and_then(serde_json::Value::as_array_mut)
    {
        for provider in providers {
            let has_programs = provider
                .get("Programs")
                .and_then(serde_json::Value::as_array)
                .is_some_and(|programs| !programs.is_empty());
            if !has_programs
                && let Some(path) = live_tv_local_config_path(provider)
                && let Some(contents) =
                    read_bounded_live_tv_config_file(&path, LIVE_TV_CONFIG_SOURCE_LIMIT_BYTES)
            {
                let programs = live_tv_array_within_limit(
                    parse_live_tv_xmltv_programs(&contents),
                    LIVE_TV_CONFIG_MAX_PROGRAMS,
                );
                if let Some(programs) = programs.filter(|programs| !programs.is_empty()) {
                    provider["Programs"] = serde_json::json!(programs);
                }
            }
        }
    }
}

