fn task_run_result_json(run: &TaskRun) -> serde_json::Value {
    named_task_run_result_json(run, "Scan Media Library")
}

fn named_task_run_result_json(run: &TaskRun, name: &str) -> serde_json::Value {
    let status = match run.status.as_str() {
        "completed" => "Completed",
        "failed" => "Failed",
        _ => "Running",
    };

    let mut result = serde_json::json!({
        "Name": name,
        "Key": run.task_key.clone(),
        "Id": run.id.to_string(),
        "Status": status,
        "StartTimeUtc": format_time_for_json(run.started_at),
        "EndTimeUtc": run.completed_at.map(format_time_for_json)
            .unwrap_or_else(|| format_time_for_json(run.updated_at)),
    });
    if let Some(error_message) = &run.error_message
        && let Some(object) = result.as_object_mut()
    {
        object.insert(
            "ErrorMessage".to_string(),
            serde_json::Value::String(error_message.clone()),
        );
    }
    result
}

