#[derive(Debug, Deserialize)]
struct PathPlaybackReportQuery {
    #[serde(alias = "api_key", alias = "ApiKey")]
    api_key: Option<String>,
    #[serde(
        alias = "MediaSourceId",
        alias = "mediaSourceId",
        alias = "mediasourceid"
    )]
    media_source_id: Option<String>,
    #[serde(
        alias = "AudioStreamIndex",
        alias = "audioStreamIndex",
        alias = "audiostreamindex"
    )]
    audio_stream_index: Option<i64>,
    #[serde(
        alias = "SubtitleStreamIndex",
        alias = "subtitleStreamIndex",
        alias = "subtitlestreamindex"
    )]
    subtitle_stream_index: Option<i64>,
    #[serde(
        alias = "PositionTicks",
        alias = "positionTicks",
        alias = "positionticks"
    )]
    position_ticks: Option<i64>,
    #[serde(
        alias = "StartPositionTicks",
        alias = "startPositionTicks",
        alias = "startpositionticks"
    )]
    start_position_ticks: Option<i64>,
    #[serde(alias = "IsPaused", alias = "isPaused", alias = "ispaused")]
    is_paused: Option<bool>,
}

impl PathPlaybackReportQuery {
    fn auth_query(&self) -> AuthQuery {
        AuthQuery {
            api_key: self.api_key.clone(),
        }
    }

    fn playback_body(&self, item_id: String) -> PlaybackReportBody {
        PlaybackReportBody {
            item_id,
            media_source_id: self.media_source_id.clone(),
            play_session_id: None,
            play_method: None,
            _can_seek: None,
            audio_stream_index: self.audio_stream_index,
            subtitle_stream_index: self.subtitle_stream_index,
            _playlist_item_id: None,
            _session_id: None,
            _volume_level: None,
            _is_muted: None,
            position_ticks: self.position_ticks.or(self.start_position_ticks),
            playback_position_ticks: None,
            start_position_ticks: None,
            start_time_ticks: None,
            is_paused: self.is_paused,
        }
    }
}

