async fn report_playback(
    state: AppState,
    headers: HeaderMap,
    query: AuthQuery,
    payload: PlaybackReportBody,
    playback_active: bool,
) -> Result<StatusCode, ApiError> {
    let (user, token) = require_user(&state.db, &headers, query.api_key.as_deref()).await?;
    let service = SessionService::new(&state.db);
    if let Some(channel) =
        live_tv_channel_json_for_playable_item(&state.db, &payload.item_id).await?
    {
        if !playback_active {
            if let Some(play_session_id) = payload
                .play_session_id
                .as_deref()
                .map(str::trim)
                .filter(|value| !value.is_empty())
            {
                stop_live_hls_session_by_id(play_session_id).await;
            }
            service.clear_active_playback(&token.access_token).await?;
            if let (Some(plugin_id), Some(tuner_id)) = (
                json_string_field(&channel, "PluginProviderId"),
                json_string_field(&channel, "TunerHostId"),
            ) && release_plugin_user_device_lease(
                &state.db,
                &plugin_id,
                &tuner_id,
                plugin_user_context(&user, &token),
            )
            .await
            .is_err()
            {
                tracing::warn!("plugin device lease release was unavailable");
            }
        }
        broadcast_sessions_message(&state.db, &token.access_token, &user).await?;
        return Ok(StatusCode::NO_CONTENT);
    }
    let item = media_item_by_id(&state.db, &payload.item_id).await?;
    let reported_position_ticks = payload
        .position_ticks
        .or(payload.playback_position_ticks)
        .or(payload.start_position_ticks)
        .or(payload.start_time_ticks)
        .unwrap_or_default();
    let position_ticks = normalize_playback_report_position_ticks(
        &service,
        payload.play_method.as_deref(),
        payload.play_session_id.as_deref(),
        reported_position_ticks,
    )
    .await?;
    let playback_outcome =
        playback_report_outcome(item.runtime_ticks, position_ticks, playback_active);
    let is_paused = payload.is_paused.unwrap_or(false);
    service
        .upsert_playback_state(UpsertPlaybackState {
            user_id: user.id,
            item_id: item.id,
            media_source_id: payload.media_source_id.clone(),
            audio_stream_index: payload.audio_stream_index,
            subtitle_stream_index: payload.subtitle_stream_index,
            position_ticks: playback_outcome.position_ticks,
            is_paused,
            played: playback_outcome.played,
        })
        .await?;
    if playback_active {
        service
            .upsert_active_playback(UpsertActivePlaybackSession {
                session_id: token.access_token.clone(),
                user_id: user.id,
                item_id: item.id,
                media_source_id: payload.media_source_id,
                audio_stream_index: payload.audio_stream_index,
                subtitle_stream_index: payload.subtitle_stream_index,
                position_ticks: playback_outcome.position_ticks,
                is_paused,
            })
            .await?;
    } else {
        service.clear_active_playback(&token.access_token).await?;
        if is_plugin_vod_virtual_item(&item) {
            let metadata = media_metadata_by_item_id(&state.db, HashSet::from([item.id])).await?;
            if let Some(reference) = metadata.get(&item.id).and_then(plugin_vod_remote_reference)
                && release_plugin_user_device_lease(
                    &state.db,
                    &reference.plugin_id,
                    &reference.tuner_id,
                    plugin_user_context(&user, &token),
                )
                .await
                .is_err()
            {
                tracing::warn!("plugin device lease release was unavailable");
            }
        }
    }
    broadcast_sessions_message(&state.db, &token.access_token, &user).await?;
    Ok(StatusCode::NO_CONTENT)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct PlaybackReportOutcome {
    position_ticks: i64,
    played: bool,
}

fn playback_report_outcome(
    runtime_ticks: Option<i64>,
    position_ticks: i64,
    playback_active: bool,
) -> PlaybackReportOutcome {
    let position_ticks = position_ticks.max(0);
    if playback_active || !playback_position_reached_played_threshold(runtime_ticks, position_ticks)
    {
        return PlaybackReportOutcome {
            position_ticks,
            played: false,
        };
    }

    PlaybackReportOutcome {
        position_ticks: 0,
        played: true,
    }
}

fn playback_position_reached_played_threshold(
    runtime_ticks: Option<i64>,
    position_ticks: i64,
) -> bool {
    let Some(runtime_ticks) = runtime_ticks.filter(|runtime_ticks| *runtime_ticks > 0) else {
        return false;
    };
    (i128::from(position_ticks.max(0)) * 100) >= (i128::from(runtime_ticks) * 90)
}

async fn normalize_playback_report_position_ticks(
    service: &SessionService<'_>,
    play_method: Option<&str>,
    play_session_id: Option<&str>,
    position_ticks: i64,
) -> Result<i64, ApiError> {
    let Some(play_session_id) = play_session_id
        .map(str::trim)
        .filter(|play_session_id| !play_session_id.is_empty())
    else {
        return Ok(position_ticks.max(0));
    };
    let Some(play_method) = play_method else {
        return Ok(position_ticks.max(0));
    };
    if !play_method.eq_ignore_ascii_case("Transcode") {
        return Ok(position_ticks.max(0));
    }
    let Some(session) = service.transcode_by_play_session(play_session_id).await? else {
        return Ok(position_ticks.max(0));
    };
    Ok(session
        .start_position_ticks
        .saturating_add(position_ticks.max(0)))
}

#[derive(Debug, Default)]
struct SendPlayCommandQuery {
    play_command: Option<String>,
    item_ids: Option<String>,
    start_position_ticks: Option<i64>,
    media_source_id: Option<String>,
    audio_stream_index: Option<i64>,
    subtitle_stream_index: Option<i64>,
    start_index: Option<usize>,
}

async fn send_play_command(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    RawQuery(raw_query): RawQuery,
    Path(session_id): Path<String>,
) -> Result<StatusCode, ApiError> {
    let query = parse_send_play_command_query(raw_query.as_deref());
    let (auth_user, _) = require_user(&state.db, &headers, auth_query.api_key.as_deref()).await?;
    let service = SessionService::new(&state.db);
    let target_session = service
        .device_by_id(&session_id)
        .await?
        .ok_or_else(|| ApiError::not_found("Device session not found"))?;
    ensure_user_access(&auth_user, target_session.user_id)?;

    let play_command = query
        .play_command
        .as_deref()
        .filter(|command| !command.trim().is_empty())
        .ok_or_else(|| ApiError::bad_request("PlayCommand is required"))?;
    let item_ids = parse_play_command_item_ids(query.item_ids.as_deref())?;
    let start_index = query.start_index.unwrap_or_default();

    let (selected_item, event_item_ids, event_play_command) =
        match play_command.to_ascii_lowercase().as_str() {
            "playinstantmix" => {
                let mix_items = audio_instant_mix_items(&state.db, &item_ids[0]).await?;
                let selected_item = mix_items.get(start_index).cloned();
                let event_item_ids = mix_items
                    .iter()
                    .take(200)
                    .map(|item| item.id.simple().to_string())
                    .collect::<Vec<_>>();
                (selected_item, event_item_ids, "PlayNow")
            }
            "playnow" | "playnext" | "playlast" | "playshuffle" => {
                let selected_id = item_ids
                    .get(start_index)
                    .or_else(|| item_ids.first())
                    .ok_or_else(|| ApiError::bad_request("ItemIds is required"))?;
                (
                    Some(media_item_by_id(&state.db, selected_id).await?),
                    item_ids.clone(),
                    canonical_play_command(play_command),
                )
            }
            _ => return Err(ApiError::bad_request("Unsupported PlayCommand")),
        };

    if let Some(item) = selected_item {
        let media_source_id = query
            .media_source_id
            .clone()
            .unwrap_or_else(|| item.id.simple().to_string());
        service
            .upsert_active_playback(UpsertActivePlaybackSession {
                session_id: target_session.access_token.clone(),
                user_id: target_session.user_id,
                item_id: item.id,
                media_source_id: Some(media_source_id),
                audio_stream_index: query.audio_stream_index,
                subtitle_stream_index: query.subtitle_stream_index,
                position_ticks: query.start_position_ticks.unwrap_or_default(),
                is_paused: false,
            })
            .await?;
        broadcast_session_message(
            &target_session.access_token,
            serde_json::json!({
                "MessageType": "Play",
                "Data": {
                    "ItemIds": event_item_ids,
                    "StartPositionTicks": query.start_position_ticks,
                    "PlayCommand": event_play_command,
                    "MediaSourceId": query.media_source_id,
                    "AudioStreamIndex": query.audio_stream_index,
                    "SubtitleStreamIndex": query.subtitle_stream_index,
                    "StartIndex": query.start_index,
                }
            }),
        );
    } else {
        service
            .clear_active_playback(&target_session.access_token)
            .await?;
    }
    broadcast_sessions_message(&state.db, &target_session.access_token, &auth_user).await?;

    Ok(StatusCode::NO_CONTENT)
}

fn canonical_play_command(command: &str) -> &'static str {
    match command.to_ascii_lowercase().as_str() {
        "playnext" => "PlayNext",
        "playlast" => "PlayLast",
        "playshuffle" => "PlayShuffle",
        "playnow" => "PlayNow",
        _ => "PlayNow",
    }
}

fn parse_play_command_item_ids(value: Option<&str>) -> Result<Vec<String>, ApiError> {
    let item_ids = value
        .ok_or_else(|| ApiError::bad_request("ItemIds is required"))?
        .split(',')
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned)
        .collect::<Vec<_>>();
    if item_ids.is_empty() {
        Err(ApiError::bad_request("ItemIds is required"))
    } else {
        Ok(item_ids)
    }
}

fn parse_send_play_command_query(raw_query: Option<&str>) -> SendPlayCommandQuery {
    let mut query = SendPlayCommandQuery::default();
    let Some(raw_query) = raw_query else {
        return query;
    };

    for part in raw_query.split('&').filter(|part| !part.is_empty()) {
        let (key, value) = part.split_once('=').unwrap_or((part, ""));
        let key = percent_decode_query_component(key).to_ascii_lowercase();
        let value = percent_decode_query_component(value);
        match key.as_str() {
            "playcommand" => query.play_command = Some(value),
            "itemids" => set_query_scalar(&mut query.item_ids, value),
            "startpositionticks" => query.start_position_ticks = value.parse().ok(),
            "mediasourceid" => query.media_source_id = Some(value),
            "audiostreamindex" => query.audio_stream_index = value.parse().ok(),
            "subtitlestreamindex" => query.subtitle_stream_index = value.parse().ok(),
            "startindex" => query.start_index = value.parse().ok(),
            _ => {}
        }
    }

    query
}

#[derive(Debug, Default)]
struct SendPlaystateCommandQuery {
    seek_position_ticks: Option<i64>,
}

async fn send_playstate_command(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    RawQuery(raw_query): RawQuery,
    Path((session_id, command)): Path<(String, String)>,
) -> Result<StatusCode, ApiError> {
    let query = parse_send_playstate_command_query(raw_query.as_deref());
    let (auth_user, _) = require_user(&state.db, &headers, auth_query.api_key.as_deref()).await?;
    let service = SessionService::new(&state.db);
    let target_session = service
        .device_by_id(&session_id)
        .await?
        .ok_or_else(|| ApiError::not_found("Device session not found"))?;
    ensure_user_access(&auth_user, target_session.user_id)?;

    let current_playback = service
        .active_playback()
        .await?
        .into_iter()
        .find(|playback| playback.session_id == target_session.access_token);

    let canonical_command = canonical_playstate_command(&command)?;
    match canonical_command {
        "Stop" => {
            service
                .clear_active_playback(&target_session.access_token)
                .await?;
        }
        "Pause" | "Unpause" | "PlayPause" | "Seek" => {
            if let Some(playback) = current_playback {
                let is_paused = match canonical_command {
                    "Pause" => true,
                    "Unpause" => false,
                    "PlayPause" => !playback.is_paused,
                    _ => playback.is_paused,
                };
                service
                    .upsert_active_playback(UpsertActivePlaybackSession {
                        session_id: target_session.access_token.clone(),
                        user_id: target_session.user_id,
                        item_id: playback.item.id,
                        media_source_id: playback.media_source_id,
                        audio_stream_index: playback.audio_stream_index,
                        subtitle_stream_index: playback.subtitle_stream_index,
                        position_ticks: query
                            .seek_position_ticks
                            .unwrap_or(playback.position_ticks),
                        is_paused,
                    })
                    .await?;
            }
        }
        "NextTrack" | "PreviousTrack" | "Rewind" | "FastForward" => {}
        _ => unreachable!("canonical playstate command must be exhaustive"),
    }
    broadcast_session_message(
        &target_session.access_token,
        serde_json::json!({
            "MessageType": "Playstate",
            "Data": {
                "Command": canonical_command,
                "SeekPositionTicks": query.seek_position_ticks,
            }
        }),
    );
    broadcast_sessions_message(&state.db, &target_session.access_token, &auth_user).await?;

    Ok(StatusCode::NO_CONTENT)
}

async fn command_target_session(
    state: &AppState,
    headers: &HeaderMap,
    auth_query: &AuthQuery,
    session_id: &str,
) -> Result<(User, DeviceSession), ApiError> {
    let (auth_user, _) = require_user(&state.db, headers, auth_query.api_key.as_deref()).await?;
    let service = SessionService::new(&state.db);
    let target_session = service
        .device_by_id(session_id)
        .await?
        .ok_or_else(|| ApiError::not_found("Device session not found"))?;
    ensure_user_access(&auth_user, target_session.user_id)?;
    Ok((auth_user, target_session))
}

async fn send_general_command(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    Path((session_id, command)): Path<(String, String)>,
    body: Option<Json<serde_json::Value>>,
) -> Result<StatusCode, ApiError> {
    let (auth_user, target_session) =
        command_target_session(&state, &headers, &auth_query, &session_id).await?;
    ensure_session_supports_command(&target_session, &command)?;
    let arguments = body
        .map(|Json(value)| value)
        .as_ref()
        .and_then(serde_json::Value::as_object)
        .cloned()
        .unwrap_or_default();
    broadcast_general_command(&target_session, &auth_user, &command, arguments.clone());
    apply_general_command_side_effect(&state.db, &target_session, &auth_user, &command, &arguments)
        .await?;
    Ok(StatusCode::NO_CONTENT)
}

async fn send_system_command(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    Path((session_id, command)): Path<(String, String)>,
) -> Result<StatusCode, ApiError> {
    let (auth_user, target_session) =
        command_target_session(&state, &headers, &auth_query, &session_id).await?;
    let command = canonical_general_command_type(&command)?;
    ensure_session_supports_command(&target_session, command)?;
    broadcast_general_command(&target_session, &auth_user, command, serde_json::Map::new());
    Ok(StatusCode::NO_CONTENT)
}

async fn send_full_general_command(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    Path(session_id): Path<String>,
    body: Option<Json<serde_json::Value>>,
) -> Result<StatusCode, ApiError> {
    let (auth_user, target_session) =
        command_target_session(&state, &headers, &auth_query, &session_id).await?;
    let payload = body
        .map(|Json(value)| value)
        .unwrap_or_else(|| serde_json::Value::Object(serde_json::Map::new()));
    let object = payload
        .as_object()
        .ok_or_else(|| ApiError::bad_request("Command body must be an object"))?;
    let command = json_object_string_field(object, &["Name", "Command"])
        .ok_or_else(|| ApiError::bad_request("Name is required"))?;
    ensure_session_supports_command(&target_session, &command)?;
    let arguments = object
        .get("Arguments")
        .or_else(|| object.get("arguments"))
        .and_then(|value| value.as_object())
        .cloned()
        .unwrap_or_default();

    broadcast_general_command(&target_session, &auth_user, &command, arguments.clone());
    apply_general_command_side_effect(&state.db, &target_session, &auth_user, &command, &arguments)
        .await?;
    Ok(StatusCode::NO_CONTENT)
}

fn ensure_session_supports_command(
    target_session: &DeviceSession,
    command: &str,
) -> Result<(), ApiError> {
    let Some(capabilities) = target_session.capabilities.as_ref() else {
        return Ok(());
    };
    let Some(commands) = capabilities
        .get("SupportedCommands")
        .and_then(serde_json::Value::as_array)
    else {
        return Ok(());
    };
    if commands.iter().any(|value| {
        value
            .as_str()
            .is_some_and(|supported| supported.eq_ignore_ascii_case(command))
    }) {
        Ok(())
    } else {
        Err(ApiError::bad_request("Command is not supported by session"))
    }
}

fn canonical_general_command_type(command: &str) -> Result<&'static str, ApiError> {
    match command.to_ascii_lowercase().as_str() {
        "back" => Ok("Back"),
        "channeldown" => Ok("ChannelDown"),
        "channelup" => Ok("ChannelUp"),
        "displaycontent" => Ok("DisplayContent"),
        "displaymessage" => Ok("DisplayMessage"),
        "gohome" => Ok("GoHome"),
        "gotosearch" => Ok("GoToSearch"),
        "gotosettings" => Ok("GoToSettings"),
        "guide" => Ok("Guide"),
        "movedown" => Ok("MoveDown"),
        "moveleft" => Ok("MoveLeft"),
        "moveright" => Ok("MoveRight"),
        "moveup" => Ok("MoveUp"),
        "mute" => Ok("Mute"),
        "nextletter" => Ok("NextLetter"),
        "pagedown" => Ok("PageDown"),
        "pageup" => Ok("PageUp"),
        "play" => Ok("Play"),
        "playmediasource" => Ok("PlayMediaSource"),
        "playnext" => Ok("PlayNext"),
        "playstate" => Ok("PlayState"),
        "playtrailers" => Ok("PlayTrailers"),
        "previousletter" => Ok("PreviousLetter"),
        "select" => Ok("Select"),
        "sendkey" => Ok("SendKey"),
        "sendstring" => Ok("SendString"),
        "setaudiostreamindex" => Ok("SetAudioStreamIndex"),
        "setmaxstreamingbitrate" => Ok("SetMaxStreamingBitrate"),
        "setplaybackorder" => Ok("SetPlaybackOrder"),
        "setrepeatmode" => Ok("SetRepeatMode"),
        "setshufflequeue" => Ok("SetShuffleQueue"),
        "setsubtitlestreamindex" => Ok("SetSubtitleStreamIndex"),
        "setvolume" => Ok("SetVolume"),
        "takescreenshot" => Ok("TakeScreenshot"),
        "togglecontextmenu" => Ok("ToggleContextMenu"),
        "togglefullscreen" => Ok("ToggleFullscreen"),
        "togglemute" => Ok("ToggleMute"),
        "toggleosd" => Ok("ToggleOsd"),
        "toggleosdmenu" => Ok("ToggleOsdMenu"),
        "togglestats" => Ok("ToggleStats"),
        "unmute" => Ok("Unmute"),
        "volumedown" => Ok("VolumeDown"),
        "volumeup" => Ok("VolumeUp"),
        _ => Err(ApiError::bad_request("Unsupported GeneralCommandType")),
    }
}

fn broadcast_general_command(
    target_session: &DeviceSession,
    auth_user: &User,
    command: &str,
    arguments: serde_json::Map<String, serde_json::Value>,
) {
    let mut data = serde_json::Map::new();
    data.insert(
        "Name".to_string(),
        serde_json::Value::String(command.to_string()),
    );
    data.insert(
        "ControllingUserId".to_string(),
        serde_json::Value::String(auth_user.id.simple().to_string()),
    );
    data.insert(
        "Arguments".to_string(),
        serde_json::Value::Object(arguments),
    );
    broadcast_session_message(
        &target_session.access_token,
        serde_json::json!({
            "MessageType": "GeneralCommand",
            "Data": data
        }),
    );
}

async fn apply_general_command_side_effect(
    db: &Database,
    target_session: &DeviceSession,
    auth_user: &User,
    command: &str,
    arguments: &serde_json::Map<String, serde_json::Value>,
) -> Result<(), ApiError> {
    let command = canonical_general_command_type(command)?;
    if matches!(command, "SetAudioStreamIndex" | "SetSubtitleStreamIndex") {
        return apply_stream_index_command_side_effect(
            db,
            target_session,
            auth_user,
            command,
            arguments,
        )
        .await;
    }
    if command != "DisplayContent" {
        return Ok(());
    }
    let payload = display_content_payload(
        db,
        DisplayContentQuery::default(),
        Some(serde_json::Value::Object(arguments.clone())),
    )
    .await?;
    let service = SessionService::new(db);
    persist_session_viewing(&service, target_session, &payload).await?;
    broadcast_session_message(
        &target_session.access_token,
        serde_json::json!({
            "MessageType": "Browse",
            "Data": {
                "ItemId": payload.item_id,
                "ItemName": payload.item_name,
                "ItemType": payload.item_type,
                "ControllingUserId": auth_user.id.simple().to_string()
            }
        }),
    );
    broadcast_sessions_message(db, &target_session.access_token, auth_user).await
}

async fn apply_stream_index_command_side_effect(
    db: &Database,
    target_session: &DeviceSession,
    auth_user: &User,
    command: &str,
    arguments: &serde_json::Map<String, serde_json::Value>,
) -> Result<(), ApiError> {
    let service = SessionService::new(db);
    let stream_index = general_command_stream_index(command, arguments)
        .ok_or_else(|| ApiError::bad_request("Stream index is required"))?;
    let Some(playback) = service
        .active_playback()
        .await?
        .into_iter()
        .find(|session| session.session_id == target_session.access_token)
    else {
        return Ok(());
    };

    let (audio_stream_index, subtitle_stream_index) = match command {
        "SetAudioStreamIndex" => {
            if stream_index < 0
                || !media_item_has_stream_index(&playback.item, "Audio", stream_index)
            {
                return Err(ApiError::bad_request("Audio stream index is invalid"));
            }
            (Some(stream_index), playback.subtitle_stream_index)
        }
        "SetSubtitleStreamIndex" => {
            if stream_index >= 0
                && !media_item_has_stream_index(&playback.item, "Subtitle", stream_index)
            {
                return Err(ApiError::bad_request("Subtitle stream index is invalid"));
            }
            (playback.audio_stream_index, Some(stream_index))
        }
        _ => return Ok(()),
    };

    service
        .upsert_playback_state(UpsertPlaybackState {
            user_id: target_session.user_id,
            item_id: playback.item.id,
            media_source_id: playback.media_source_id.clone(),
            audio_stream_index,
            subtitle_stream_index,
            position_ticks: playback.position_ticks,
            is_paused: playback.is_paused,
            played: false,
        })
        .await?;
    service
        .upsert_active_playback(UpsertActivePlaybackSession {
            session_id: target_session.access_token.clone(),
            user_id: target_session.user_id,
            item_id: playback.item.id,
            media_source_id: playback.media_source_id,
            audio_stream_index,
            subtitle_stream_index,
            position_ticks: playback.position_ticks,
            is_paused: playback.is_paused,
        })
        .await?;
    broadcast_sessions_message(db, &target_session.access_token, auth_user).await
}

fn general_command_stream_index(
    command: &str,
    arguments: &serde_json::Map<String, serde_json::Value>,
) -> Option<i64> {
    let command_specific_names = match command {
        "SetAudioStreamIndex" => &["AudioStreamIndex", "audioStreamIndex", "audiostreamindex"][..],
        "SetSubtitleStreamIndex" => &[
            "SubtitleStreamIndex",
            "subtitleStreamIndex",
            "subtitlestreamindex",
        ][..],
        _ => &[][..],
    };
    [
        "Index",
        "index",
        "StreamIndex",
        "streamIndex",
        "streamindex",
    ]
    .iter()
    .chain(command_specific_names.iter())
    .find_map(|name| arguments.get(*name).and_then(json_value_i64))
}

#[derive(Debug, Default, Deserialize)]
struct DisplayContentQuery {
    #[serde(flatten)]
    auth: AuthQuery,
    #[serde(alias = "ItemId", alias = "itemId")]
    item_id: Option<String>,
    #[serde(alias = "ItemName", alias = "itemName")]
    item_name: Option<String>,
    #[serde(alias = "ItemType", alias = "itemType")]
    item_type: Option<String>,
}

async fn display_content(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<DisplayContentQuery>,
    Path(session_id): Path<String>,
    body: Option<Json<serde_json::Value>>,
) -> Result<StatusCode, ApiError> {
    let (auth_user, target_session) =
        command_target_session(&state, &headers, &query.auth, &session_id).await?;
    let body = body.map(|Json(value)| value);
    let payload = display_content_payload(&state.db, query, body).await?;
    let service = SessionService::new(&state.db);
    persist_session_viewing(&service, &target_session, &payload).await?;
    broadcast_session_message(
        &target_session.access_token,
        serde_json::json!({
            "MessageType": "Browse",
            "Data": {
                "ItemId": payload.item_id,
                "ItemName": payload.item_name,
                "ItemType": payload.item_type,
                "ControllingUserId": auth_user.id.simple().to_string()
            }
        }),
    );
    broadcast_sessions_message(&state.db, &target_session.access_token, &auth_user).await?;
    Ok(StatusCode::NO_CONTENT)
}

#[derive(Debug, Default, Deserialize)]
struct ReportViewingQuery {
    #[serde(flatten)]
    auth: AuthQuery,
    #[serde(alias = "SessionId", alias = "sessionId")]
    session_id: Option<String>,
    #[serde(alias = "ItemId", alias = "itemId")]
    item_id: Option<String>,
    #[serde(alias = "ItemName", alias = "itemName")]
    item_name: Option<String>,
    #[serde(alias = "ItemType", alias = "itemType")]
    item_type: Option<String>,
}

async fn report_viewing(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<ReportViewingQuery>,
    body: Option<Json<serde_json::Value>>,
) -> Result<StatusCode, ApiError> {
    let (auth_user, token) =
        require_user(&state.db, &headers, query.auth.api_key.as_deref()).await?;
    let target_session_id = query
        .session_id
        .clone()
        .unwrap_or_else(|| token.access_token.clone());
    let target_session = state
        .db
        .device_session_by_id(&target_session_id)
        .await?
        .ok_or_else(|| ApiError::not_found("Device session not found"))?;
    ensure_user_access(&auth_user, target_session.user_id)?;

    let body = body.map(|Json(value)| value);
    let payload = display_content_payload(
        &state.db,
        DisplayContentQuery {
            auth: AuthQuery::default(),
            item_id: query.item_id,
            item_name: query.item_name,
            item_type: query.item_type,
        },
        body,
    )
    .await?;
    let service = SessionService::new(&state.db);
    persist_session_viewing(&service, &target_session, &payload).await?;
    broadcast_session_message(
        &target_session.access_token,
        serde_json::json!({
            "MessageType": "Browse",
            "Data": {
                "ItemId": payload.item_id,
                "ItemName": payload.item_name,
                "ItemType": payload.item_type,
                "ControllingUserId": auth_user.id.simple().to_string()
            }
        }),
    );
    broadcast_sessions_message(&state.db, &target_session.access_token, &auth_user).await?;
    Ok(StatusCode::NO_CONTENT)
}

async fn persist_session_viewing(
    service: &SessionService<'_>,
    target_session: &DeviceSession,
    payload: &DisplayContentPayload,
) -> Result<(), ApiError> {
    let Some(item_id) = payload.item_id.as_deref() else {
        service
            .clear_active_viewing(&target_session.access_token)
            .await?;
        return Ok(());
    };
    service
        .upsert_active_viewing(UpsertActiveViewingSession {
            session_id: target_session.access_token.clone(),
            user_id: target_session.user_id,
            item_id: parse_jellyfin_uuid(item_id)?,
        })
        .await?;
    Ok(())
}

#[derive(Debug, Default)]
struct DisplayContentPayload {
    item_id: Option<String>,
    item_name: Option<String>,
    item_type: Option<String>,
}

async fn display_content_payload(
    db: &Database,
    query: DisplayContentQuery,
    body: Option<serde_json::Value>,
) -> Result<DisplayContentPayload, ApiError> {
    let body_object = body.as_ref().and_then(|value| value.as_object());
    let item_id = query.item_id.or_else(|| {
        body_object.and_then(|object| json_object_string_field(object, &["ItemId", "itemId"]))
    });
    let mut item_name = query.item_name.or_else(|| {
        body_object.and_then(|object| json_object_string_field(object, &["ItemName", "itemName"]))
    });
    let mut item_type = query.item_type.or_else(|| {
        body_object.and_then(|object| json_object_string_field(object, &["ItemType", "itemType"]))
    });

    if let Some(item_id) = item_id.as_deref() {
        let item = media_item_by_id(db, item_id).await?;
        if item_name.as_deref().is_none_or(str::is_empty) {
            item_name = Some(item.name.clone());
        }
        if item_type.as_deref().is_none_or(str::is_empty) {
            item_type = Some(media_item_type(&item).to_string());
        }
    }

    Ok(DisplayContentPayload {
        item_id,
        item_name,
        item_type,
    })
}

fn json_object_string_field(
    object: &serde_json::Map<String, serde_json::Value>,
    names: &[&str],
) -> Option<String> {
    names.iter().find_map(|name| {
        object
            .get(*name)
            .and_then(|value| value.as_str())
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(ToOwned::to_owned)
    })
}

async fn send_message_command(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    Path(session_id): Path<String>,
    body: Option<Json<serde_json::Value>>,
) -> Result<StatusCode, ApiError> {
    let (auth_user, target_session) =
        command_target_session(&state, &headers, &auth_query, &session_id).await?;
    ensure_session_supports_command(&target_session, "DisplayMessage")?;
    let payload = body
        .map(|Json(value)| value)
        .unwrap_or_else(|| serde_json::Value::Object(serde_json::Map::new()));
    let object = payload
        .as_object()
        .ok_or_else(|| ApiError::bad_request("Message body must be an object"))?;
    let message = message_command_payload(object)?;
    let mut data = serde_json::Map::new();
    data.insert(
        "Header".to_string(),
        message
            .header
            .map(serde_json::Value::String)
            .unwrap_or(serde_json::Value::Null),
    );
    data.insert("Text".to_string(), serde_json::Value::String(message.text));
    data.insert(
        "TimeoutMs".to_string(),
        message
            .timeout_ms
            .map(serde_json::Value::Number)
            .unwrap_or(serde_json::Value::Null),
    );
    data.insert(
        "ControllingUserId".to_string(),
        serde_json::Value::String(auth_user.id.simple().to_string()),
    );
    broadcast_session_message(
        &target_session.access_token,
        serde_json::json!({
            "MessageType": "MessageCommand",
            "Data": data
        }),
    );
    Ok(StatusCode::NO_CONTENT)
}

struct MessageCommandPayload {
    header: Option<String>,
    text: String,
    timeout_ms: Option<serde_json::Number>,
}

fn message_command_payload(
    object: &serde_json::Map<String, serde_json::Value>,
) -> Result<MessageCommandPayload, ApiError> {
    let header = json_object_string_field(object, &["Header", "header"]);
    let text = json_object_string_field(object, &["Text", "text"])
        .ok_or_else(|| ApiError::bad_request("Text is required"))?;
    let timeout_ms = object
        .get("TimeoutMs")
        .or_else(|| object.get("timeoutMs"))
        .or_else(|| object.get("Timeout"))
        .or_else(|| object.get("timeout"))
        .map(json_value_non_negative_i64)
        .transpose()?
        .map(serde_json::Number::from);
    Ok(MessageCommandPayload {
        header,
        text,
        timeout_ms,
    })
}

fn json_value_non_negative_i64(value: &serde_json::Value) -> Result<i64, ApiError> {
    let parsed = if let Some(value) = value.as_i64() {
        Some(value)
    } else if let Some(value) = value.as_str() {
        value.trim().parse::<i64>().ok()
    } else {
        None
    };
    match parsed {
        Some(value) if value >= 0 => Ok(value),
        _ => Err(ApiError::bad_request(
            "TimeoutMs must be a non-negative integer",
        )),
    }
}

async fn add_user_to_session(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    Path((session_id, user_id)): Path<(String, String)>,
) -> Result<StatusCode, ApiError> {
    modify_session_user(state, headers, auth_query, session_id, user_id, true).await
}

async fn remove_user_from_session(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    Path((session_id, user_id)): Path<(String, String)>,
) -> Result<StatusCode, ApiError> {
    modify_session_user(state, headers, auth_query, session_id, user_id, false).await
}

async fn modify_session_user(
    state: AppState,
    headers: HeaderMap,
    auth_query: AuthQuery,
    session_id: String,
    user_id: String,
    add_user: bool,
) -> Result<StatusCode, ApiError> {
    let (auth_user, target_session) =
        command_target_session(&state, &headers, &auth_query, &session_id).await?;
    let requested_user_id = Uuid::parse_str(&user_id)
        .or_else(|_| Uuid::parse_str(&hyphenate_uuid(&user_id)))
        .map_err(|_| ApiError::bad_request("Invalid user id"))?;
    let requested_user = state
        .db
        .user_by_id(requested_user_id)
        .await
        .map_err(|_| ApiError::not_found("User not found"))?;
    if add_user {
        state
            .db
            .add_session_user(&target_session.access_token, requested_user_id)
            .await?;
    } else {
        state
            .db
            .remove_session_user(&target_session.access_token, requested_user_id)
            .await?;
    }
    broadcast_sessions_message(&state.db, &target_session.access_token, &auth_user).await?;
    broadcast_sessions_message_to_user_owned_sessions(
        &state.db,
        &requested_user,
        Some(&target_session.access_token),
    )
    .await?;
    Ok(StatusCode::NO_CONTENT)
}

fn canonical_playstate_command(command: &str) -> Result<&'static str, ApiError> {
    match command.to_ascii_lowercase().as_str() {
        "stop" => Ok("Stop"),
        "pause" => Ok("Pause"),
        "unpause" => Ok("Unpause"),
        "playpause" => Ok("PlayPause"),
        "seek" => Ok("Seek"),
        "nexttrack" => Ok("NextTrack"),
        "previoustrack" => Ok("PreviousTrack"),
        "rewind" => Ok("Rewind"),
        "fastforward" => Ok("FastForward"),
        _ => Err(ApiError::bad_request("Unsupported PlaystateCommand")),
    }
}

fn parse_send_playstate_command_query(raw_query: Option<&str>) -> SendPlaystateCommandQuery {
    let mut query = SendPlaystateCommandQuery::default();
    let Some(raw_query) = raw_query else {
        return query;
    };

    for part in raw_query.split('&').filter(|part| !part.is_empty()) {
        let (key, value) = part.split_once('=').unwrap_or((part, ""));
        let key = percent_decode_query_component(key).to_ascii_lowercase();
        let value = percent_decode_query_component(value);
        if key == "seekpositionticks" {
            query.seek_position_ticks = value.parse().ok();
        }
    }

    query
}

async fn quick_connect_enabled(State(state): State<AppState>) -> Result<Json<bool>, ApiError> {
    Ok(Json(quick_connect_available(&state.db).await?))
}

async fn quick_connect_available(db: &Database) -> Result<bool, ApiError> {
    let mut server_options = default_server_configuration_options();
    if let serde_json::Value::Object(current) =
        db.system_configuration_payloads().await?.server_options
    {
        for (key, value) in current {
            server_options[key] = value;
        }
    }
    Ok(server_options["QuickConnectAvailable"]
        .as_bool()
        .unwrap_or(true))
}

async fn require_quick_connect_available(db: &Database) -> Result<(), ApiError> {
    if quick_connect_available(db).await? {
        Ok(())
    } else {
        Err(ApiError::forbidden("QuickConnect is disabled"))
    }
}

async fn initiate_quick_connect(
    State(state): State<AppState>,
    headers: HeaderMap,
) -> Result<Json<serde_json::Value>, ApiError> {
    require_quick_connect_available(&state.db).await?;
    let auth = client_auth_from_headers(&headers);
    let session = state
        .db
        .initiate_quick_connect(&auth.device_id, &auth.device, &auth.client, &auth.version)
        .await?;
    Ok(Json(quick_connect_json(&session)))
}

