struct QuickConnectSecretQuery {
    #[serde(alias = "Secret", alias = "secret")]
    secret: String,
}

async fn get_quick_connect_state(
    State(state): State<AppState>,
    Query(query): Query<QuickConnectSecretQuery>,
) -> Result<Json<serde_json::Value>, ApiError> {
    let session = state
        .db
        .quick_connect_by_secret(&query.secret)
        .await
        .map_err(|_| ApiError::not_found("QuickConnect session not found"))?;
    Ok(Json(quick_connect_json(&session)))
}

#[derive(Debug, Deserialize, Default)]
struct QuickConnectCodePayload {
    #[serde(alias = "Code", alias = "code")]
    code: Option<String>,
}

#[derive(Debug, Deserialize)]
struct QuickConnectAuthorizeQuery {
    #[serde(flatten)]
    auth: AuthQuery,
    #[serde(alias = "Code", alias = "code")]
    code: Option<String>,
}

async fn authorize_quick_connect(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<QuickConnectAuthorizeQuery>,
    body: Option<Json<QuickConnectCodePayload>>,
) -> Result<Json<bool>, ApiError> {
    require_quick_connect_available(&state.db).await?;
    let user = require_request_user(&state.db, &headers, query.auth.api_key.as_deref()).await?;
    let code = query
        .code
        .as_deref()
        .or_else(|| body.as_ref().and_then(|body| body.code.as_deref()))
        .map(str::trim)
        .filter(|code| !code.is_empty())
        .ok_or_else(|| ApiError::bad_request("Code must not be empty"))?;
    state
        .db
        .authorize_quick_connect(code, user.id)
        .await
        .map_err(|_| ApiError::not_found("QuickConnect code not found"))?;
    Ok(Json(true))
}

#[derive(Debug, Deserialize)]
struct AuthenticateQuickConnectBody {
    #[serde(alias = "Secret", alias = "secret")]
    secret: String,
}

async fn authenticate_with_quick_connect(
    State(state): State<AppState>,
    Json(payload): Json<AuthenticateQuickConnectBody>,
) -> Result<Json<AuthenticationResultDto>, ApiError> {
    require_quick_connect_available(&state.db).await?;
    let session = state
        .db
        .quick_connect_by_secret(&payload.secret)
        .await
        .map_err(|_| ApiError::unauthorized("QuickConnect authorization is not complete"))?;
    if !session.authorized || session.expires_at <= OffsetDateTime::now_utc() {
        return Err(ApiError::unauthorized(
            "QuickConnect authorization is not complete",
        ));
    }
    let user_id = session
        .user_id
        .ok_or_else(|| ApiError::unauthorized("QuickConnect authorization is not complete"))?;
    let (user, token) = state
        .db
        .issue_device_token_for_user(
            user_id,
            &session.device_id,
            &session.device_name,
            &session.client,
            &session.version,
        )
        .await
        .map_err(|_| ApiError::unauthorized("QuickConnect authorization is not complete"))?;
    state
        .db
        .delete_quick_connect_session(&session.secret)
        .await?;
    let server = state.db.server_state().await?;
    Ok(Json(
        authentication_result_to_dto(&state.db, &user, &token, server.server_id).await?,
    ))
}

fn quick_connect_json(session: &QuickConnectSession) -> serde_json::Value {
    serde_json::json!({
        "Secret": session.secret,
        "Code": session.code,
        "DeviceId": session.device_id,
        "DeviceName": session.device_name,
        "AppName": session.client,
        "AppVersion": session.version,
        "DateAdded": format_time_for_json(session.created_at),
        "DateUpdated": format_time_for_json(session.updated_at),
        "DateExpires": format_time_for_json(session.expires_at),
        "Authenticated": session.authorized,
        "UserId": session.user_id.map(|id| id.simple().to_string())
    })
}

fn syncplay_groups() -> &'static Mutex<HashMap<String, SyncPlayGroup>> {
    SYNCPLAY_GROUPS.get_or_init(|| Mutex::new(HashMap::new()))
}

async fn optional_json_body(body: Body) -> Result<serde_json::Value, ApiError> {
    let bytes = to_bytes(body, SYNCPLAY_REQUEST_LIMIT_BYTES).await?;
    if bytes.is_empty() {
        return Ok(serde_json::json!({}));
    }
    serde_json::from_slice(&bytes).map_err(|_| ApiError::bad_request("Invalid JSON body"))
}

fn json_string_any_field(payload: &serde_json::Value, keys: &[&str]) -> Option<String> {
    keys.iter().find_map(|key| {
        payload
            .get(*key)
            .and_then(serde_json::Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(ToOwned::to_owned)
    })
}

fn json_i64_any_field(payload: &serde_json::Value, keys: &[&str]) -> Option<i64> {
    keys.iter()
        .find_map(|key| payload.get(*key).and_then(serde_json::Value::as_i64))
}

fn syncplay_participant(user: &User, token: &DeviceToken) -> SyncPlayParticipant {
    SyncPlayParticipant {
        user_id: user.id,
        user_name: user.name.clone(),
        session_id: token.access_token.clone(),
        device_id: token.device_id.clone(),
        is_ready: false,
        is_buffering: false,
        last_seen_at: OffsetDateTime::now_utc(),
    }
}

fn user_can_create_syncplay_group(user: &User) -> bool {
    user.sync_play_access
        .eq_ignore_ascii_case("CreateAndJoinGroups")
}

fn user_can_join_syncplay_group(user: &User) -> bool {
    matches!(
        user.sync_play_access.to_ascii_lowercase().as_str(),
        "createandjoingroups" | "joingroups"
    )
}

fn require_syncplay_create_access(user: &User) -> Result<(), ApiError> {
    if user_can_create_syncplay_group(user) {
        Ok(())
    } else {
        Err(ApiError::forbidden("User cannot create SyncPlay groups"))
    }
}

fn require_syncplay_join_access(user: &User) -> Result<(), ApiError> {
    if user_can_join_syncplay_group(user) {
        Ok(())
    } else {
        Err(ApiError::forbidden("User cannot join SyncPlay groups"))
    }
}

fn syncplay_insert_participant(
    participants: &mut BTreeMap<String, SyncPlayParticipant>,
    participant: SyncPlayParticipant,
) {
    participants.retain(|session_id, existing| {
        session_id == &participant.session_id
            || existing.user_id != participant.user_id
            || existing.device_id != participant.device_id
    });
    participants.insert(participant.session_id.clone(), participant);
}

fn syncplay_stale_timeout() -> Duration {
    std::env::var("JELLYRIN_SYNCPLAY_STALE_TIMEOUT_MS")
        .ok()
        .and_then(|value| value.trim().parse::<i64>().ok())
        .filter(|value| *value > 0)
        .map(Duration::milliseconds)
        .unwrap_or_else(|| Duration::milliseconds(SYNCPLAY_STALE_TIMEOUT_MS))
}

fn syncplay_group_json(group: &SyncPlayGroup) -> serde_json::Value {
    let participants = group
        .participants
        .values()
        .map(|participant| {
            serde_json::json!({
                "UserId": participant.user_id,
                "UserName": participant.user_name,
                "SessionId": participant.session_id,
                "DeviceId": participant.device_id,
                "IsGroupOwner": participant.user_id == group.owner_user_id,
                "IsReady": participant.is_ready,
                "IsBuffering": participant.is_buffering,
                "LastSeenDate": format_time_for_json(participant.last_seen_at)
            })
        })
        .collect::<Vec<_>>();
    serde_json::json!({
        "GroupId": group.id,
        "Id": group.id,
        "GroupName": group.name,
        "Name": group.name,
        "Participants": participants,
        "State": group.state,
        "CommandSequence": group.command_sequence,
        "LastActivityDate": format_time_for_json(group.updated_at)
    })
}

async fn syncplay_list(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
) -> Result<Json<Vec<serde_json::Value>>, ApiError> {
    require_request_user(&state.db, &headers, query.api_key.as_deref()).await?;
    syncplay_cleanup_stale_participants("Stale").await;
    let groups = syncplay_groups().lock().await;
    Ok(Json(groups.values().map(syncplay_group_json).collect()))
}

async fn syncplay_group(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    Path(id): Path<String>,
) -> Result<Json<serde_json::Value>, ApiError> {
    require_request_user(&state.db, &headers, query.api_key.as_deref()).await?;
    syncplay_cleanup_stale_participants("Stale").await;
    let groups = syncplay_groups().lock().await;
    let group = groups
        .get(id.trim())
        .ok_or_else(|| ApiError::not_found("SyncPlay group not found"))?;
    Ok(Json(syncplay_group_json(group)))
}

async fn syncplay_new(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    body: Body,
) -> Result<Json<serde_json::Value>, ApiError> {
    let (user, token) = require_user(&state.db, &headers, query.api_key.as_deref()).await?;
    require_syncplay_create_access(&user)?;
    syncplay_cleanup_stale_participants("Stale").await;
    let payload = optional_json_body(body).await?;
    let group_id = json_string_any_field(&payload, &["GroupId", "Id"])
        .unwrap_or_else(|| Uuid::new_v4().to_string());
    let name = json_string_any_field(&payload, &["Name", "GroupName"])
        .unwrap_or_else(|| format!("{}'s group", user.name));
    let participant = syncplay_participant(&user, &token);
    let mut participants = BTreeMap::new();
    syncplay_insert_participant(&mut participants, participant);
    let group = SyncPlayGroup {
        id: group_id.clone(),
        name,
        owner_user_id: user.id,
        participants,
        state: serde_json::json!({
            "PlayState": "Idle",
            "PositionTicks": 0,
            "IsPaused": false,
            "CommandSequence": 0,
            "Queue": []
        }),
        command_sequence: 0,
        updated_at: OffsetDateTime::now_utc(),
    };
    let (response, previous_group_updates) = {
        let mut groups = syncplay_groups().lock().await;
        let previous_group_updates =
            syncplay_detach_session_from_groups(&mut groups, &token.access_token, None);
        let response = syncplay_group_json(&group);
        groups.insert(group_id, group);
        (response, previous_group_updates)
    };
    broadcast_syncplay_group_updates(previous_group_updates, "Leave");
    Ok(Json(response))
}

async fn syncplay_join(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    body: Body,
) -> Result<Json<serde_json::Value>, ApiError> {
    let (user, token) = require_user(&state.db, &headers, query.api_key.as_deref()).await?;
    require_syncplay_join_access(&user)?;
    syncplay_cleanup_stale_participants("Stale").await;
    let payload = optional_json_body(body).await?;
    let group_id = json_string_any_field(&payload, &["GroupId", "Id"])
        .ok_or_else(|| ApiError::bad_request("SyncPlay group id is required"))?;
    let (group_json, participant_session_ids, previous_group_updates) = {
        let mut groups = syncplay_groups().lock().await;
        if !groups.contains_key(group_id.trim()) {
            return Err(ApiError::not_found("SyncPlay group not found"));
        }
        let previous_group_updates = syncplay_detach_session_from_groups(
            &mut groups,
            &token.access_token,
            Some(group_id.trim()),
        );
        let group = groups
            .get_mut(group_id.trim())
            .expect("SyncPlay target group checked before detaching session");
        let participant = syncplay_participant(&user, &token);
        syncplay_insert_participant(&mut group.participants, participant);
        group.updated_at = OffsetDateTime::now_utc();
        (
            syncplay_group_json(group),
            group.participants.keys().cloned().collect::<Vec<_>>(),
            previous_group_updates,
        )
    };
    broadcast_syncplay_group_updates(previous_group_updates, "Leave");
    broadcast_syncplay_group_update(&participant_session_ids, &group_json, "Join");
    Ok(Json(group_json))
}

async fn syncplay_leave(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
) -> Result<StatusCode, ApiError> {
    let (_user, token) = require_user(&state.db, &headers, query.api_key.as_deref()).await?;
    syncplay_remove_session(&token.access_token, "Leave").await;
    Ok(StatusCode::NO_CONTENT)
}

async fn syncplay_remove_session(session_id: &str, reason: &str) {
    let updates = {
        let mut groups = syncplay_groups().lock().await;
        syncplay_detach_session_from_groups(&mut groups, session_id, None)
    };
    broadcast_syncplay_group_updates(updates, reason);
}

/// Enforces Jellyfin's one-active-SyncPlay-group-per-session invariant while the caller holds
/// the global group lock. Joining the current group uses `except_group_id` to refresh in place.
fn syncplay_detach_session_from_groups(
    groups: &mut HashMap<String, SyncPlayGroup>,
    session_id: &str,
    except_group_id: Option<&str>,
) -> Vec<(serde_json::Value, Vec<String>)> {
    let mut updates = Vec::new();
    let mut empty_groups = Vec::new();
    for group in groups.values_mut() {
        if except_group_id.is_some_and(|group_id| group.id == group_id) {
            continue;
        }
        let Some(removed) = group.participants.remove(session_id) else {
            continue;
        };
        group.updated_at = OffsetDateTime::now_utc();
        if group.participants.is_empty() {
            empty_groups.push(group.id.clone());
            continue;
        }
        if removed.user_id == group.owner_user_id
            && let Some(next_owner) = group.participants.values().next()
        {
            group.owner_user_id = next_owner.user_id;
        }
        updates.push((
            syncplay_group_json(group),
            group.participants.keys().cloned().collect::<Vec<_>>(),
        ));
    }
    for group_id in empty_groups {
        groups.remove(&group_id);
    }
    updates
}

fn broadcast_syncplay_group_updates(updates: Vec<(serde_json::Value, Vec<String>)>, reason: &str) {
    for (group_json, participant_session_ids) in updates {
        broadcast_syncplay_group_update(&participant_session_ids, &group_json, reason);
    }
}

async fn syncplay_cleanup_stale_participants(reason: &str) {
    let now = OffsetDateTime::now_utc();
    let timeout = syncplay_stale_timeout();
    let mut updates = Vec::new();
    {
        let mut groups = syncplay_groups().lock().await;
        let mut empty_groups = Vec::new();
        for group in groups.values_mut() {
            let stale_session_ids = group
                .participants
                .iter()
                .filter(|(_, participant)| now - participant.last_seen_at > timeout)
                .map(|(session_id, _)| session_id.clone())
                .collect::<Vec<_>>();
            if stale_session_ids.is_empty() {
                continue;
            }
            let owner_removed = stale_session_ids.iter().any(|session_id| {
                group
                    .participants
                    .get(session_id)
                    .is_some_and(|participant| participant.user_id == group.owner_user_id)
            });
            for session_id in stale_session_ids {
                group.participants.remove(&session_id);
            }
            group.updated_at = now;
            if group.participants.is_empty() {
                empty_groups.push(group.id.clone());
                continue;
            }
            if owner_removed && let Some(next_owner) = group.participants.values().next() {
                group.owner_user_id = next_owner.user_id;
            }
            updates.push((
                syncplay_group_json(group),
                group.participants.keys().cloned().collect::<Vec<_>>(),
            ));
        }
        for group_id in empty_groups {
            groups.remove(&group_id);
        }
    }
    for (group_json, participant_session_ids) in updates {
        broadcast_syncplay_group_update(&participant_session_ids, &group_json, reason);
    }
}

async fn syncplay_ping(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
) -> Result<StatusCode, ApiError> {
    let (_user, token) = require_user(&state.db, &headers, query.api_key.as_deref()).await?;
    let now = OffsetDateTime::now_utc();
    let mut updates = Vec::new();
    {
        let mut groups = syncplay_groups().lock().await;
        for group in groups.values_mut() {
            if let Some(participant) = group.participants.get_mut(&token.access_token) {
                participant.last_seen_at = now;
                group.updated_at = now;
                updates.push((
                    syncplay_group_json(group),
                    group.participants.keys().cloned().collect::<Vec<_>>(),
                ));
            }
        }
    }
    for (group_json, participant_session_ids) in updates {
        broadcast_syncplay_group_update(&participant_session_ids, &group_json, "Ping");
    }
    syncplay_cleanup_stale_participants("Stale").await;
    Ok(StatusCode::NO_CONTENT)
}

async fn syncplay_group_command(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    uri: Uri,
    body: Body,
) -> Result<StatusCode, ApiError> {
    let (_user, token) = require_user(&state.db, &headers, query.api_key.as_deref()).await?;
    let payload = optional_json_body(body).await?;
    let command = syncplay_command_from_uri(&uri);
    let now = OffsetDateTime::now_utc();
    let (group_id, group_json, participant_session_ids, command_sequence) = {
        let mut groups = syncplay_groups().lock().await;
        let group = groups
            .values_mut()
            .find(|group| group.participants.contains_key(&token.access_token))
            .ok_or_else(|| ApiError::not_found("SyncPlay group not found"))?;
        if let Some(participant) = group.participants.get_mut(&token.access_token) {
            participant.last_seen_at = now;
        }
        syncplay_apply_participant_command(group, &token.access_token, &command, &payload, now);
        group.command_sequence = group.command_sequence.saturating_add(1);
        let command_sequence = group.command_sequence;
        syncplay_apply_command_to_state(
            &mut group.state,
            &command,
            &payload,
            now,
            command_sequence,
        );
        group.updated_at = now;
        (
            group.id.clone(),
            syncplay_group_json(group),
            group.participants.keys().cloned().collect::<Vec<_>>(),
            command_sequence,
        )
    };
    for session_id in participant_session_ids {
        let command_payload = syncplay_command_message_payload(
            &group_id,
            &command,
            &payload,
            &group_json,
            now,
            command_sequence,
        );
        broadcast_session_message(
            &session_id,
            serde_json::json!({
                "MessageType": "SyncPlayCommand",
                "Data": command_payload
            }),
        );
    }
    syncplay_cleanup_stale_participants("Stale").await;
    Ok(StatusCode::NO_CONTENT)
}

fn syncplay_command_message_payload(
    group_id: &str,
    command: &str,
    payload: &serde_json::Value,
    group_json: &serde_json::Value,
    now: OffsetDateTime,
    command_sequence: u64,
) -> serde_json::Value {
    let position_ticks = syncplay_position_ticks_from_payload(payload);
    let emitted_at = format_time_for_json(now);
    let when =
        json_string_any_field(payload, &["When", "when"]).unwrap_or_else(|| emitted_at.clone());
    let playlist_item_id = json_string_any_field(payload, &["PlaylistItemId", "ItemId"])
        .unwrap_or_else(|| {
            group_json["State"]["PlaylistItemId"]
                .as_str()
                .unwrap_or("")
                .to_string()
        });
    serde_json::json!({
        "GroupId": group_id,
        "Command": command,
        "Payload": payload,
        "Group": group_json,
        "When": when,
        "EmittedAt": emitted_at,
        "CommandSequence": command_sequence,
        "Timeline": group_json["State"]["Timeline"].clone(),
        "DriftTicks": group_json["State"]["DriftTicks"].clone(),
        "CorrectionPositionTicks": group_json["State"]["CorrectionPositionTicks"].clone(),
        "PositionTicks": position_ticks,
        "PlaylistItemId": playlist_item_id
    })
}

fn syncplay_apply_participant_command(
    group: &mut SyncPlayGroup,
    session_id: &str,
    command: &str,
    payload: &serde_json::Value,
    now: OffsetDateTime,
) {
    let Some(participant) = group.participants.get_mut(session_id) else {
        return;
    };
    participant.last_seen_at = now;
    match command.to_ascii_lowercase().as_str() {
        "ready" => {
            participant.is_ready = payload
                .get("IsReady")
                .or_else(|| payload.get("Ready"))
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(true);
            participant.is_buffering = false;
        }
        "buffering" => {
            participant.is_buffering = payload
                .get("IsBuffering")
                .or_else(|| payload.get("Buffering"))
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(true);
            if participant.is_buffering {
                participant.is_ready = false;
            }
        }
        "pause" | "unpause" | "seek" | "stop" => {
            participant.is_buffering = false;
        }
        _ => {}
    }
}

fn syncplay_apply_command_to_state(
    state: &mut serde_json::Value,
    command: &str,
    payload: &serde_json::Value,
    now: OffsetDateTime,
    command_sequence: u64,
) {
    if !state.is_object() {
        *state = serde_json::json!({});
    }
    let timeline_drift = syncplay_timeline_drift_json(state, payload, now);
    let object = state.as_object_mut().expect("syncplay state object");
    object.insert("LastCommand".to_string(), payload.clone());
    object.insert(
        "LastCommandName".to_string(),
        serde_json::Value::String(command.to_string()),
    );
    object.insert(
        "LastCommandDate".to_string(),
        serde_json::Value::String(format_time_for_json(now)),
    );
    object.insert(
        "CommandSequence".to_string(),
        serde_json::json!(command_sequence),
    );
    object.insert(
        "LastCommandSequence".to_string(),
        serde_json::json!(command_sequence),
    );

    if let Some(position_ticks) = syncplay_position_ticks_from_payload(payload) {
        object.insert(
            "PositionTicks".to_string(),
            serde_json::json!(position_ticks),
        );
    }
    if let Some(when) = json_string_any_field(payload, &["When", "when"]) {
        object.insert("LastClientWhen".to_string(), serde_json::json!(when));
    }
    if let Some(item_id) = json_string_any_field(payload, &["PlaylistItemId", "ItemId"]) {
        object.insert("PlaylistItemId".to_string(), serde_json::json!(item_id));
    }
    if let Some(timeline) = timeline_drift {
        object.insert("Timeline".to_string(), timeline.clone());
        object.insert("DriftTicks".to_string(), timeline["DriftTicks"].clone());
        object.insert(
            "CorrectionPositionTicks".to_string(),
            timeline["CorrectionPositionTicks"].clone(),
        );
        object.insert(
            "IsDriftCorrectionRequired".to_string(),
            timeline["IsCorrectionRequired"].clone(),
        );
    }

    match command.to_ascii_lowercase().as_str() {
        "play" => {
            object.insert("IsPaused".to_string(), serde_json::json!(false));
            object.insert("PlayState".to_string(), serde_json::json!("Playing"));
            if let Some(queue) = payload
                .get("Queue")
                .or_else(|| payload.get("Items"))
                .or_else(|| payload.get("ItemIds"))
                .filter(|value| value.is_array())
            {
                object.insert("Queue".to_string(), queue.clone());
                object.insert(
                    "QueueVersion".to_string(),
                    serde_json::json!(now.unix_timestamp_nanos().to_string()),
                );
            }
        }
        "pause" => {
            object.insert("IsPaused".to_string(), serde_json::json!(true));
            object.insert("PlayState".to_string(), serde_json::json!("Paused"));
        }
        "unpause" => {
            object.insert("IsPaused".to_string(), serde_json::json!(false));
            object.insert("PlayState".to_string(), serde_json::json!("Playing"));
        }
        "seek" => {
            object.insert("PlayState".to_string(), serde_json::json!("Seeking"));
        }
        "buffering" => {
            object.insert("PlayState".to_string(), serde_json::json!("Buffering"));
        }
        "stop" => {
            object.insert("IsPaused".to_string(), serde_json::json!(false));
            object.insert("PlayState".to_string(), serde_json::json!("Stopped"));
        }
        "queue" | "setnewqueue" => {
            if let Some(queue) = payload
                .get("Queue")
                .or_else(|| payload.get("Items"))
                .or_else(|| payload.get("ItemIds"))
                .filter(|value| value.is_array())
            {
                object.insert("Queue".to_string(), queue.clone());
                object.insert(
                    "QueueVersion".to_string(),
                    serde_json::json!(now.unix_timestamp_nanos().to_string()),
                );
            }
            object.insert("PlayState".to_string(), serde_json::json!("Queued"));
        }
        "removefromplaylist" => {
            if let Some(queue) = object
                .get_mut("Queue")
                .and_then(serde_json::Value::as_array_mut)
            {
                if let Some(index) = json_i64_any_field(payload, &["PlaylistItemIndex", "Index"]) {
                    if index >= 0 && (index as usize) < queue.len() {
                        queue.remove(index as usize);
                    }
                } else if let Some(item_id) =
                    json_string_any_field(payload, &["PlaylistItemId", "ItemId"])
                {
                    queue.retain(|item| !syncplay_queue_item_matches(item, &item_id));
                }
            }
        }
        "moveplaylistitem" => {
            let from = json_i64_any_field(payload, &["PlaylistItemIndex", "OldIndex", "FromIndex"]);
            let to = json_i64_any_field(payload, &["NewIndex", "ToIndex"]);
            if let (Some(from), Some(to), Some(queue)) = (
                from,
                to,
                object
                    .get_mut("Queue")
                    .and_then(serde_json::Value::as_array_mut),
            ) && from >= 0
                && to >= 0
                && (from as usize) < queue.len()
                && (to as usize) < queue.len()
            {
                let item = queue.remove(from as usize);
                queue.insert(to as usize, item);
            }
        }
        "nextitem" => {
            let index = object
                .get("PlaylistItemIndex")
                .and_then(serde_json::Value::as_i64)
                .unwrap_or(0)
                + 1;
            object.insert("PlaylistItemIndex".to_string(), serde_json::json!(index));
        }
        "previousitem" => {
            let index = object
                .get("PlaylistItemIndex")
                .and_then(serde_json::Value::as_i64)
                .unwrap_or(0)
                .saturating_sub(1);
            object.insert("PlaylistItemIndex".to_string(), serde_json::json!(index));
        }
        "setplaylistitem" => {
            if let Some(item_id) = json_string_any_field(payload, &["PlaylistItemId", "ItemId"]) {
                object.insert("PlaylistItemId".to_string(), serde_json::json!(item_id));
            }
            if let Some(index) = json_i64_any_field(payload, &["PlaylistItemIndex", "Index"]) {
                object.insert("PlaylistItemIndex".to_string(), serde_json::json!(index));
            }
        }
        "setrepeatmode" => {
            if let Some(mode) = json_string_any_field(payload, &["RepeatMode", "Mode"]) {
                object.insert("RepeatMode".to_string(), serde_json::json!(mode));
            }
        }
        "setshufflemode" => {
            if let Some(enabled) = payload
                .get("ShuffleMode")
                .or_else(|| payload.get("Shuffle"))
                .and_then(serde_json::Value::as_bool)
            {
                object.insert("ShuffleMode".to_string(), serde_json::json!(enabled));
            }
        }
        "setignorewait" => {
            if let Some(enabled) = payload
                .get("IgnoreWait")
                .or_else(|| payload.get("IgnoreWaitEnabled"))
                .and_then(serde_json::Value::as_bool)
            {
                object.insert("IgnoreWait".to_string(), serde_json::json!(enabled));
            }
        }
        "ready" => {
            object.insert("IsReady".to_string(), serde_json::json!(true));
        }
        _ => {}
    }
}

fn syncplay_timeline_drift_json(
    state: &serde_json::Value,
    payload: &serde_json::Value,
    now: OffsetDateTime,
) -> Option<serde_json::Value> {
    let client_position_ticks = syncplay_position_ticks_from_payload(payload)?;
    let client_when = json_string_any_field(payload, &["When", "when"])?;
    let parsed_client_when = OffsetDateTime::parse(&client_when, &Rfc3339).ok()?;
    let elapsed_ticks = syncplay_duration_to_ticks(now - parsed_client_when);
    let estimated_server_position_ticks = client_position_ticks.saturating_add(elapsed_ticks);
    let server_position_ticks = state
        .get("PositionTicks")
        .and_then(serde_json::Value::as_i64)
        .unwrap_or(client_position_ticks);
    let drift_ticks = estimated_server_position_ticks.saturating_sub(server_position_ticks);
    let correction_position_ticks = (drift_ticks.abs() >= SYNCPLAY_DRIFT_THRESHOLD_TICKS)
        .then_some(estimated_server_position_ticks);

    Some(serde_json::json!({
        "ClientWhen": client_when,
        "ServerReceivedAt": format_time_for_json(now),
        "ClientPositionTicks": client_position_ticks,
        "ClientElapsedTicks": elapsed_ticks,
        "ServerPositionTicks": server_position_ticks,
        "EstimatedServerPositionTicks": estimated_server_position_ticks,
        "DriftTicks": drift_ticks,
        "DriftThresholdTicks": SYNCPLAY_DRIFT_THRESHOLD_TICKS,
        "IsCorrectionRequired": correction_position_ticks.is_some(),
        "CorrectionPositionTicks": correction_position_ticks
    }))
}

fn syncplay_duration_to_ticks(duration: Duration) -> i64 {
    let ticks =
        duration.whole_nanoseconds() * i128::from(SYNCPLAY_TICKS_PER_SECOND) / 1_000_000_000_i128;
    ticks.clamp(i64::MIN as i128, i64::MAX as i128) as i64
}

fn syncplay_position_ticks_from_payload(payload: &serde_json::Value) -> Option<i64> {
    json_i64_any_field(
        payload,
        &[
            "PositionTicks",
            "SeekPositionTicks",
            "NewPositionTicks",
            "StartPositionTicks",
        ],
    )
}

fn syncplay_queue_item_matches(item: &serde_json::Value, item_id: &str) -> bool {
    item.as_str().is_some_and(|value| value == item_id)
        || item
            .get("Id")
            .or_else(|| item.get("ItemId"))
            .and_then(serde_json::Value::as_str)
            .is_some_and(|value| value == item_id)
}

fn broadcast_syncplay_group_update(
    participant_session_ids: &[String],
    group: &serde_json::Value,
    reason: &str,
) {
    for session_id in participant_session_ids {
        broadcast_session_message(
            session_id,
            serde_json::json!({
                "MessageType": "SyncPlayGroupUpdate",
                "Data": {
                    "Reason": reason,
                    "Command": reason,
                    "Payload": {},
                    "GroupId": group["GroupId"].clone(),
                    "Group": group.clone()
                }
            }),
        );
    }
}

fn syncplay_command_from_uri(uri: &Uri) -> String {
    uri.path()
        .trim_matches('/')
        .rsplit('/')
        .next()
        .filter(|segment| !segment.is_empty())
        .map(ToOwned::to_owned)
        .unwrap_or_else(|| "Command".to_string())
}

async fn live_tv_info(State(state): State<AppState>) -> Result<Json<serde_json::Value>, ApiError> {
    let tuners = configured_live_tv_tuner_views(&state.db).await?;
    let persisted_channel_count = state
        .db
        .live_tv_channel_count(&LiveTvChannelQuery::default())
        .await?;
    let channel_count =
        persisted_channel_count.max(tuners.iter().map(|tuner| tuner.child_count).sum::<usize>());
    let config = state
        .db
        .named_configuration("livetv")
        .await?
        .unwrap_or_else(default_live_tv_configuration);
    let listing_providers = config
        .get("ListingProviders")
        .and_then(serde_json::Value::as_array)
        .into_iter()
        .flatten()
        .map(|provider| {
            serde_json::json!({
                "Id": json_string_field(provider, "Id"),
                "Name": json_string_field(provider, "FriendlyName")
                    .or_else(|| json_string_field(provider, "Name")),
                "Type": json_string_field(provider, "Type")
            })
        })
        .collect::<Vec<_>>();
    let tuner_hosts = tuners
        .iter()
        .map(|tuner| {
            serde_json::json!({
                "Id": tuner.tuner_id,
                "Name": tuner.name,
                "FriendlyName": tuner.name,
                "Type": tuner.provider_type,
                "ChannelCount": tuner.child_count,
                "IsEnabled": true
            })
        })
        .collect::<Vec<_>>();
    Ok(Json(serde_json::json!({
        "Services": [],
        "IsEnabled": channel_count > 0,
        "EnabledUsers": [],
        "TunerHosts": tuner_hosts,
        "ListingsProviders": listing_providers,
        "ChannelCount": channel_count
    })))
}

async fn live_tv_guide_info() -> Json<serde_json::Value> {
    let now = OffsetDateTime::now_utc();
    Json(serde_json::json!({
        // Jellyfin Web parses both values unconditionally before loading the
        // channel/program pages. Null dates leave Android's WebView on an
        // infinite spinner (`Cannot read property 'match' of null`). Keep the
        // advertised window aligned with the fallback EPG generated for
        // providers that expose channels but no programme guide.
        "StartDate": format_time_for_json(now - Duration::hours(12)),
        "EndDate": format_time_for_json(now + Duration::hours(12))
    }))
}

#[derive(Debug, Deserialize)]
struct LiveTvChannelMappingOptionsQuery {
    #[serde(alias = "providerId", alias = "ProviderId")]
    provider_id: Option<String>,
    #[serde(alias = "api_key", alias = "ApiKey")]
    api_key: Option<String>,
}

async fn live_tv_channel_mapping_options(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<LiveTvChannelMappingOptionsQuery>,
) -> Result<Json<serde_json::Value>, ApiError> {
    require_admin(&state.db, &headers, query.api_key.as_deref()).await?;
    let provider_id = query
        .provider_id
        .as_deref()
        .map(str::trim)
        .filter(|id| !id.is_empty())
        .ok_or_else(|| ApiError::bad_request("Provider id is required"))?;
    let config = state
        .db
        .named_configuration("livetv")
        .await?
        .unwrap_or_else(default_live_tv_configuration);
    let provider = live_tv_listing_provider(&config, provider_id)
        .ok_or_else(|| ApiError::not_found("Listing provider not found"))?;
    let mappings = provider
        .get("ChannelMappings")
        .and_then(serde_json::Value::as_array)
        .cloned()
        .unwrap_or_default();
    let server_id = state.db.server_state().await?.server_id.to_string();
    let tuner_channels = live_tv_channel_items(&config, &server_id)
        .into_iter()
        .map(live_tv_channel_mapping_option)
        .collect::<Vec<_>>();
    let provider_channels = live_tv_provider_channels(provider);
    Ok(Json(serde_json::json!({
        "TunerChannels": tuner_channels,
        "ProviderChannels": provider_channels,
        "Mappings": mappings,
        "ProviderName": live_tv_provider_name(provider)
    })))
}

#[derive(Debug, Deserialize)]
struct SetLiveTvChannelMappingBody {
    #[serde(alias = "ProviderId")]
    provider_id: String,
    #[serde(alias = "TunerChannelId")]
    tuner_channel_id: String,
    #[serde(alias = "ProviderChannelId")]
    provider_channel_id: String,
}

async fn set_live_tv_channel_mapping(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    Json(payload): Json<SetLiveTvChannelMappingBody>,
) -> Result<Json<serde_json::Value>, ApiError> {
    require_admin(&state.db, &headers, query.api_key.as_deref()).await?;
    let provider_id = payload.provider_id.trim();
    let tuner_channel_id = payload.tuner_channel_id.trim();
    let provider_channel_id = payload.provider_channel_id.trim();
    if provider_id.is_empty() || tuner_channel_id.is_empty() || provider_channel_id.is_empty() {
        return Err(ApiError::bad_request(
            "Provider, tuner channel and provider channel ids are required",
        ));
    }

    let mut config = state
        .db
        .named_configuration("livetv")
        .await?
        .unwrap_or_else(default_live_tv_configuration);
    let mut listing_providers = config
        .get("ListingProviders")
        .and_then(serde_json::Value::as_array)
        .cloned()
        .unwrap_or_default();
    let provider = listing_providers
        .iter_mut()
        .find(|provider| {
            provider
                .get("Id")
                .and_then(serde_json::Value::as_str)
                .is_some_and(|id| id.eq_ignore_ascii_case(provider_id))
        })
        .ok_or_else(|| ApiError::not_found("Listing provider not found"))?;
    let mut mappings = provider
        .get("ChannelMappings")
        .and_then(serde_json::Value::as_array)
        .cloned()
        .unwrap_or_default();
    mappings.retain(|mapping| {
        mapping
            .get("Name")
            .and_then(serde_json::Value::as_str)
            .is_none_or(|name| !name.eq_ignore_ascii_case(tuner_channel_id))
    });
    if !tuner_channel_id.eq_ignore_ascii_case(provider_channel_id) {
        mappings.push(serde_json::json!({
            "Name": tuner_channel_id,
            "Value": provider_channel_id
        }));
    }
    provider["ChannelMappings"] = serde_json::json!(mappings);
    config["ListingProviders"] = serde_json::json!(listing_providers);
    state
        .db
        .update_named_configuration("livetv", live_tv_configuration_json(config))
        .await?;
    Ok(Json(serde_json::json!({
        "Id": tuner_channel_id,
        "Name": tuner_channel_id,
        "ProviderChannelId": provider_channel_id,
        "ProviderChannelName": provider_channel_id
    })))
}

fn live_tv_listing_provider<'a>(
    config: &'a serde_json::Value,
    provider_id: &str,
) -> Option<&'a serde_json::Value> {
    config
        .get("ListingProviders")
        .and_then(serde_json::Value::as_array)
        .and_then(|providers| {
            providers.iter().find(|provider| {
                provider
                    .get("Id")
                    .and_then(serde_json::Value::as_str)
                    .is_some_and(|id| id.eq_ignore_ascii_case(provider_id))
            })
        })
}

fn live_tv_provider_name(provider: &serde_json::Value) -> String {
    for key in ["Name", "ListingsId", "Type", "Id"] {
        if let Some(value) = provider
            .get(key)
            .and_then(serde_json::Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
        {
            return value.to_string();
        }
    }
    String::new()
}

async fn live_tv_m3u_channels_from_payload(
    payload: &serde_json::Value,
) -> Option<Vec<serde_json::Value>> {
    let contents = live_tv_config_source_contents(payload).await?;
    let channels = live_tv_array_within_limit(
        parse_live_tv_m3u_channels(&contents),
        LIVE_TV_PROVIDER_CATALOG_MAX_CHANNELS,
    )?;
    (!channels.is_empty()).then_some(channels)
}

type LiveTvProviderImportFuture<'a> =
    Pin<Box<dyn Future<Output = Result<Option<LiveTvProviderImport>, ApiError>> + Send + 'a>>;
type LiveTvProviderProgramsFuture<'a> =
    Pin<Box<dyn Future<Output = Result<Option<Vec<serde_json::Value>>, ApiError>> + Send + 'a>>;

struct LiveTvProviderImport {
    channels: Vec<serde_json::Value>,
    categories: Vec<serde_json::Value>,
    programs: Vec<serde_json::Value>,
    channel_upserts: Vec<LiveTvChannelUpsert>,
    category_upserts: Vec<LiveTvCategoryUpsert>,
}

struct PostImportActions {
    trigger_media_sync: bool,
}

impl PostImportActions {
    fn none() -> Self {
        Self {
            trigger_media_sync: false,
        }
    }
}

trait LiveTvProvider: Send + Sync {
    fn provider_type(&self) -> &'static str;

    fn import_channels<'a>(
        &'a self,
        payload: &'a serde_json::Value,
    ) -> LiveTvProviderImportFuture<'a>;

    fn import_programs<'a>(
        &'a self,
        payload: &'a serde_json::Value,
    ) -> LiveTvProviderProgramsFuture<'a>;

    fn post_import_actions(&self) -> PostImportActions {
        PostImportActions::none()
    }
}

struct XtreamLiveTvProvider;

impl LiveTvProvider for XtreamLiveTvProvider {
    fn provider_type(&self) -> &'static str {
        "xtream"
    }

    fn import_channels<'a>(
        &'a self,
        payload: &'a serde_json::Value,
    ) -> LiveTvProviderImportFuture<'a> {
        Box::pin(async move {
            Ok(live_tv_xtream::import_from_payload(payload)
                .await
                .map(|import| LiveTvProviderImport {
                    channels: import.channels,
                    categories: import.categories,
                    programs: Vec::new(),
                    channel_upserts: Vec::new(),
                    category_upserts: Vec::new(),
                }))
        })
    }

    fn import_programs<'a>(
        &'a self,
        payload: &'a serde_json::Value,
    ) -> LiveTvProviderProgramsFuture<'a> {
        Box::pin(async move { Ok(live_tv_xtream::programs_from_payload(payload).await) })
    }

    fn post_import_actions(&self) -> PostImportActions {
        PostImportActions {
            trigger_media_sync: true,
        }
    }
}

static XTREAM_LIVE_TV_PROVIDER: XtreamLiveTvProvider = XtreamLiveTvProvider;

static LIVE_TV_PROVIDER_REGISTRY: std::sync::OnceLock<
    tokio::sync::RwLock<Vec<&'static dyn LiveTvProvider>>,
> = std::sync::OnceLock::new();

fn live_tv_provider_registry() -> &'static tokio::sync::RwLock<Vec<&'static dyn LiveTvProvider>> {
    LIVE_TV_PROVIDER_REGISTRY.get_or_init(|| tokio::sync::RwLock::new(Vec::new()))
}

async fn live_tv_provider_for_type(provider_type: &str) -> Option<&'static dyn LiveTvProvider> {
    let provider_type = provider_type.trim();
    let registry = live_tv_provider_registry().read().await;
    registry
        .iter()
        .copied()
        .find(|provider| provider.provider_type().eq_ignore_ascii_case(provider_type))
}

async fn live_tv_provider_types() -> Vec<&'static str> {
    let registry = live_tv_provider_registry().read().await;
    registry.iter().map(|p| p.provider_type()).collect()
}

async fn register_live_tv_provider(provider: &'static dyn LiveTvProvider) {
    let mut registry = live_tv_provider_registry().write().await;
    if !registry.iter().any(|p| {
        p.provider_type()
            .eq_ignore_ascii_case(provider.provider_type())
    }) {
        registry.push(provider);
    }
}

async fn unregister_live_tv_provider(provider_type: &str) {
    let mut registry = live_tv_provider_registry().write().await;
    registry.retain(|p| !p.provider_type().eq_ignore_ascii_case(provider_type));
}

