pub async fn ensure_builtin_xtream_plugin(db: &Database) -> Result<(), ApiError> {
    let manifest = serde_json::json!({
        "Guid": "a1b2c3d4-e5f6-7890-abcd-ef1234567890",
        "Name": "Xtream Codes Provider",
        "Version": "1.0.0",
        "Runtime": "Builtin",
        "Capabilities": ["LiveTvProvider", "ScheduledTask"],
        "Description": "Built-in Xtream Codes IPTV provider for live TV, VOD, and series.",
        "WebPages": [{
            "Name": "xtream-config",
            "Path": "configuration.html",
            "DisplayName": "Xtream Codes Configuration",
            "EnableInMainMenu": false
        }],
        "Configuration": {
            "Url": "",
            "Username": "",
            "Password": "",
            "LiveCategoryIds": [],
            "VodCategoryIds": [],
            "SeriesCategoryIds": [],
            "ChannelLimit": 0,
            "MovieLimit": 0,
            "SeriesLimit": 0
        }
    });

    let existing_status = db
        .installed_plugin_json(BUILTIN_XTREAM_PLUGIN_ID)
        .await?
        .and_then(|plugin| json_string_field(&plugin, "Status"))
        .filter(|status| !status.is_empty())
        .unwrap_or_else(|| "Active".to_string());
    PluginService::new(db)
        .ensure_builtin(
            BUILTIN_XTREAM_PLUGIN_ID,
            "Xtream Codes Provider",
            "1.0.0",
            &manifest,
            &["LiveTvProvider", "ScheduledTask"],
        )
        .await?;

    // Register in the live TV provider registry if active
    if existing_status.eq_ignore_ascii_case("Active") {
        register_live_tv_provider(&XTREAM_LIVE_TV_PROVIDER).await;
    }
    Ok(())
}

async fn live_tv_provider_import_from_payload(
    state: &AppState,
    payload: &serde_json::Value,
    provider_type: &str,
) -> Result<Option<LiveTvProviderImportLease>, ApiError> {
    if let Some(provider) = live_tv_provider_for_type(provider_type).await {
        return Ok(provider.import_channels(payload).await?.map(|import| {
            LiveTvProviderImportLease {
                import,
                plugin_security_guard: None,
                plugin_admission_guard: None,
                plugin_provider_session_guard: None,
            }
        }));
    }
    live_tv_plugin_channel_provider_import(&state.db, payload, provider_type).await
}

/// Keeps a plugin lifecycle read lock alive until an imported snapshot and its public tuner
/// configuration have both committed. Built-in providers do not need the guard.
struct LiveTvProviderImportLease {
    import: LiveTvProviderImport,
    plugin_security_guard: Option<tokio::sync::OwnedRwLockReadGuard<()>>,
    plugin_admission_guard: Option<tokio::sync::OwnedSemaphorePermit>,
    plugin_provider_session_guard: Option<tokio::sync::OwnedRwLockWriteGuard<()>>,
}

async fn live_tv_provider_programs_from_payload(
    payload: &serde_json::Value,
    provider_type: &str,
) -> Result<Option<Vec<serde_json::Value>>, ApiError> {
    if let Some(provider) = live_tv_provider_for_type(provider_type).await {
        return provider.import_programs(payload).await;
    }
    Ok(None)
}

fn live_tv_plugin_id_from_payload(
    payload: &serde_json::Value,
    provider_type: &str,
) -> Option<String> {
    let provider_type = provider_type.trim();
    if let Some((route, plugin_id)) = provider_type.split_once(':')
        && ["plugin", "channelprovider", "plugin-channelprovider"]
            .iter()
            .any(|candidate| route.eq_ignore_ascii_case(candidate))
    {
        return (!plugin_id.trim().is_empty()).then(|| plugin_id.trim().to_string());
    }
    if ["plugin", "channelprovider", "plugin-channelprovider"]
        .iter()
        .any(|candidate| provider_type.eq_ignore_ascii_case(candidate))
    {
        json_string_any_field(payload, &["PluginId", "ProviderId", "ChannelProviderId"])
    } else {
        None
    }
}

fn live_tv_plugin_ids_from_configuration(configuration: &serde_json::Value) -> Vec<String> {
    let mut plugin_ids = configuration
        .get("TunerHosts")
        .and_then(serde_json::Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(|tuner| {
            let tuner_type = json_string_field(tuner, "Type")?;
            live_tv_plugin_id_from_payload(tuner, &tuner_type)
        })
        .map(|plugin_id| plugin_id.to_ascii_lowercase())
        .collect::<Vec<_>>();
    plugin_ids.sort_unstable();
    plugin_ids.dedup();
    plugin_ids
}

fn plugin_manifest_requests_permission(plugin: &serde_json::Value, permission: &str) -> bool {
    plugin
        .get("Manifest")
        .and_then(|manifest| json_field_case_insensitive(manifest, "Permissions"))
        .and_then(serde_json::Value::as_array)
        .is_some_and(|permissions| {
            permissions.iter().any(|candidate| {
                candidate
                    .as_str()
                    .is_some_and(|candidate| candidate.eq_ignore_ascii_case(permission))
                    || json_string_field(candidate, "Name")
                        .is_some_and(|candidate| candidate.eq_ignore_ascii_case(permission))
            })
        })
}

fn plugin_has_granted_permission(plugin: &serde_json::Value, permission: &str) -> bool {
    plugin_string_array(json_field_case_insensitive(plugin, "Permissions"))
        .iter()
        .any(|candidate| candidate.eq_ignore_ascii_case(permission))
}

fn plugin_may_receive_provider_secrets(plugin: &serde_json::Value) -> bool {
    plugin_manifest_requests_permission(plugin, PERMISSION_PROVIDER_SECRETS)
        && plugin_has_granted_permission(plugin, PERMISSION_PROVIDER_SECRETS)
}

/// Classifies external plugins whose capability contracts can receive provider credentials
/// anchored to a `plugin:<id>` Live TV tuner. `VodLibraryProvider` shares that exact boundary:
/// its imports reuse the tuner secret grant, so lanes, lifecycle locks and one-shot processes
/// must apply identically even when the manifest omits `ProviderSecrets`.
fn plugin_uses_live_tv_tuner_secret_boundary(plugin: &serde_json::Value) -> bool {
    json_string_field(plugin, "Runtime")
        .or_else(|| {
            plugin
                .get("Manifest")
                .and_then(|manifest| json_string_field(manifest, "Runtime"))
        })
        .is_some_and(|runtime| runtime.eq_ignore_ascii_case("ExternalProcess"))
        && [Some(plugin), plugin.get("Manifest")]
            .into_iter()
            .flatten()
            .any(|source| {
                plugin_string_array(json_field_case_insensitive(source, "Capabilities"))
                    .iter()
                    .any(|capability| {
                        capability.eq_ignore_ascii_case(CAPABILITY_LIVE_TV_PROVIDER)
                            || capability.eq_ignore_ascii_case(CAPABILITY_VOD_LIBRARY_PROVIDER)
                    })
            })
}

fn plugin_configuration_contains_tuner_secret_material(value: &serde_json::Value) -> bool {
    contains_plaintext_provider_secret(value)
        || json_field_case_insensitive(value, PROVIDER_SECRET_REFERENCE_FIELD).is_some()
}

fn submitted_provider_credential_component<'a>(
    configuration: &'a serde_json::Value,
    names: &[&str],
    trim: bool,
) -> Result<Option<&'a str>, ApiError> {
    let Some(object) = configuration.as_object() else {
        return Err(ApiError::bad_request(
            "Live TV tuner configuration must be an object",
        ));
    };
    let mut selected: Option<&str> = None;
    for (key, value) in object {
        if !names.iter().any(|name| key.eq_ignore_ascii_case(name)) {
            continue;
        }
        let value = match value {
            serde_json::Value::Null => continue,
            serde_json::Value::String(value) => {
                let value = if trim { value.trim() } else { value.as_str() };
                if value.is_empty() || value == "********" {
                    continue;
                }
                value
            }
            _ => {
                return Err(ApiError::bad_request(
                    "Provider credentials must be strings",
                ));
            }
        };
        if selected.is_some_and(|current| current != value) {
            return Err(ApiError::bad_request(
                "Provider credential aliases contain conflicting values",
            ));
        }
        selected = Some(value);
    }
    Ok(selected)
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct SubmittedProviderCredentials {
    has_username: bool,
    has_password: bool,
}

impl SubmittedProviderCredentials {
    fn is_complete(self) -> bool {
        self.has_username && self.has_password
    }
}

fn submitted_provider_credentials(
    configuration: &serde_json::Value,
) -> Result<Option<SubmittedProviderCredentials>, ApiError> {
    let username =
        submitted_provider_credential_component(configuration, &["Username", "UserName"], true)?;
    let password = submitted_provider_credential_component(configuration, &["Password"], false)?;
    Ok(
        (username.is_some() || password.is_some()).then_some(SubmittedProviderCredentials {
            has_username: username.is_some(),
            has_password: password.is_some(),
        }),
    )
}

fn explicit_provider_secret_reference(
    configuration: &serde_json::Value,
) -> Result<Option<ProviderSecretReference>, ApiError> {
    let Some(object) = configuration.as_object() else {
        return Ok(None);
    };
    let Some((field, _)) = object
        .iter()
        .find(|(field, _)| field.eq_ignore_ascii_case(PROVIDER_SECRET_REFERENCE_FIELD))
    else {
        return Ok(None);
    };
    if field != PROVIDER_SECRET_REFERENCE_FIELD {
        return Err(ApiError::bad_request(
            "Provider secret reference field has invalid casing",
        ));
    }
    ProviderSecretReference::from_configuration(configuration)
        .map(Some)
        .ok_or_else(|| ApiError::bad_request("Provider secret reference is invalid"))
}

fn redacted_live_tv_plugin_tuner_config(
    mut configuration: serde_json::Value,
) -> Result<serde_json::Value, ApiError> {
    let object = configuration
        .as_object_mut()
        .ok_or_else(|| ApiError::bad_request("Live TV tuner configuration must be an object"))?;
    object.retain(|field, _| {
        !field.eq_ignore_ascii_case("Username")
            && !field.eq_ignore_ascii_case("UserName")
            && !field.eq_ignore_ascii_case("Password")
            && !field.eq_ignore_ascii_case(PROVIDER_SECRET_REFERENCE_FIELD)
            && !field.eq_ignore_ascii_case("CredentialsConfigured")
            && !field.eq_ignore_ascii_case("JellyrinConfigurationRevision")
    });
    if contains_plaintext_provider_secret(&configuration) {
        return Err(ApiError::bad_request(
            "Live TV plugin configuration contains unsupported plaintext secrets",
        ));
    }
    Ok(configuration)
}

fn validate_live_tv_plugin_route_binding(
    configuration: &serde_json::Value,
    provider_type: &str,
    expected_plugin_id: &str,
) -> Result<(), ApiError> {
    let (route, inline_plugin_id) = provider_type
        .trim()
        .split_once(':')
        .map_or((provider_type.trim(), None), |(route, plugin_id)| {
            (route, Some(plugin_id.trim()))
        });
    if !["plugin", "channelprovider", "plugin-channelprovider"]
        .iter()
        .any(|candidate| route.eq_ignore_ascii_case(candidate))
    {
        return Err(ApiError::bad_request("Live TV plugin route is invalid"));
    }
    if inline_plugin_id.is_some_and(|plugin_id| {
        plugin_id.is_empty() || !plugin_id.eq_ignore_ascii_case(expected_plugin_id)
    }) {
        return Err(ApiError::bad_request(
            "Live TV tuner Type identifies a different plugin",
        ));
    }
    let Some(object) = configuration.as_object() else {
        return Err(ApiError::bad_request(
            "Live TV tuner configuration must be an object",
        ));
    };
    let mut has_plugin_id = inline_plugin_id.is_some();
    for (field, value) in object {
        if !["PluginId", "ProviderId", "ChannelProviderId"]
            .iter()
            .any(|candidate| field.eq_ignore_ascii_case(candidate))
        {
            continue;
        }
        let plugin_id = value
            .as_str()
            .map(str::trim)
            .filter(|plugin_id| !plugin_id.is_empty())
            .ok_or_else(|| ApiError::bad_request("Live TV plugin id must be a string"))?;
        if !plugin_id.eq_ignore_ascii_case(expected_plugin_id) {
            return Err(ApiError::bad_request(
                "Live TV tuner contains conflicting plugin identities",
            ));
        }
        has_plugin_id = true;
    }
    if !has_plugin_id {
        return Err(ApiError::bad_request("Live TV plugin id is required"));
    }
    Ok(())
}

fn live_tv_tuner_from_named_configuration<'a>(
    configuration: &'a serde_json::Value,
    tuner_id: &str,
) -> Option<&'a serde_json::Value> {
    configuration
        .get("TunerHosts")
        .and_then(serde_json::Value::as_array)?
        .iter()
        .find(|tuner| {
            json_string_field(tuner, "Id")
                .is_some_and(|candidate| candidate.eq_ignore_ascii_case(tuner_id))
        })
}

async fn persisted_live_tv_tuner_configuration(
    db: &Database,
    tuner_id: &str,
) -> Result<Option<serde_json::Value>, ApiError> {
    if let Some(configuration) = db.named_configuration("livetv").await?
        && let Some(tuner) = live_tv_tuner_from_named_configuration(&configuration, tuner_id)
    {
        return Ok(Some(tuner.clone()));
    }
    db.live_tv_tuner_configuration_by_id(tuner_id)
        .await
        .map_err(Into::into)
}

fn merge_live_tv_plugin_tuner_configuration(
    existing: Option<serde_json::Value>,
    mut submitted: serde_json::Value,
    existing_reference: Option<&ProviderSecretReference>,
) -> Result<serde_json::Value, ApiError> {
    let mut staged = existing.unwrap_or_else(|| serde_json::json!({}));
    let staged_object = staged
        .as_object_mut()
        .ok_or_else(|| ApiError::internal("Persisted Live TV tuner is invalid"))?;
    let submitted_fields =
        std::mem::take(submitted.as_object_mut().ok_or_else(|| {
            ApiError::bad_request("Live TV tuner configuration must be an object")
        })?);
    for (field, value) in submitted_fields {
        staged_object.insert(field, value);
    }
    if let Some(reference) = existing_reference {
        staged_object.insert(
            PROVIDER_SECRET_REFERENCE_FIELD.to_string(),
            reference.to_json(),
        );
    }
    Ok(staged)
}

fn inherit_live_tv_tuner_route_fields(
    submitted: &mut serde_json::Value,
    existing: &serde_json::Value,
) -> Result<(), ApiError> {
    let submitted_object = submitted
        .as_object_mut()
        .ok_or_else(|| ApiError::bad_request("Live TV tuner configuration must be an object"))?;
    for field in ["Type", "PluginId", "ProviderId", "ChannelProviderId"] {
        if submitted_object
            .keys()
            .any(|candidate| candidate.eq_ignore_ascii_case(field))
        {
            continue;
        }
        if let Some(value) = json_field_case_insensitive(existing, field) {
            submitted_object.insert(field.to_string(), value.clone());
        }
    }
    Ok(())
}

async fn stage_live_tv_plugin_tuner_credentials(
    db: &Database,
    configuration: serde_json::Value,
    provider_type: &str,
) -> Result<serde_json::Value, ApiError> {
    let Some(plugin_id) = live_tv_plugin_id_from_payload(&configuration, provider_type) else {
        return Ok(configuration);
    };
    let security_slot = external_plugin_security_slot(&plugin_id).await;
    let _security_guard = security_slot.write_owned().await;
    validate_live_tv_plugin_route_binding(&configuration, provider_type, &plugin_id)?;
    let tuner_id = json_string_field(&configuration, "Id")
        .ok_or_else(|| ApiError::bad_request("Live TV tuner Id is required"))?;
    let submitted = submitted_provider_credentials(&configuration)?;
    let submitted_reference = explicit_provider_secret_reference(&configuration)?;
    let existing = persisted_live_tv_tuner_configuration(db, &tuner_id).await?;
    let existing_reference = existing
        .as_ref()
        .map(explicit_provider_secret_reference)
        .transpose()?
        .flatten();

    match (&submitted_reference, &existing_reference) {
        (Some(_), None) => {
            return Err(ApiError::forbidden(
                "A client cannot attach an existing provider secret to a new tuner",
            ));
        }
        (Some(submitted), Some(existing)) if submitted != existing => {
            return Err(ApiError::forbidden(
                "A client cannot replace the tuner provider secret reference",
            ));
        }
        _ => {}
    }
    if submitted.is_none() && existing_reference.is_none() {
        return Ok(configuration);
    }
    if !provider_type
        .split_once(':')
        .map_or(provider_type, |(route, _)| route)
        .eq_ignore_ascii_case("plugin")
    {
        return Err(ApiError::bad_request(
            "Provider credentials require a plugin:<id> Live TV tuner Type",
        ));
    }
    if existing_reference.is_none()
        && submitted.is_some_and(|credentials| !credentials.is_complete())
    {
        return Err(ApiError::bad_request(
            "Provider Username and Password are required for a new tuner",
        ));
    }

    let plugin = db
        .installed_plugin_json(&plugin_id)
        .await?
        .filter(|plugin| {
            json_string_field(plugin, "Status").as_deref() == Some("Active")
                && plugin_string_array(plugin.get("Capabilities"))
                    .iter()
                    .any(|capability| capability.eq_ignore_ascii_case(CAPABILITY_LIVE_TV_PROVIDER))
        })
        .ok_or_else(|| ApiError::bad_request("Live TV plugin provider is unavailable"))?;
    if !json_string_field(&plugin, "Runtime")
        .is_some_and(|runtime| runtime.eq_ignore_ascii_case("ExternalProcess"))
    {
        return Err(ApiError::forbidden(
            "Provider secret grants require an ExternalProcess plugin runtime",
        ));
    }
    if !plugin_may_receive_provider_secrets(&plugin) {
        return Err(ApiError::forbidden(
            "Live TV plugin has not requested and received ProviderSecrets permission",
        ));
    }
    if submitted.is_some() {
        db.validate_provider_secret_write_readiness().map_err(|_| {
            ApiError::service_unavailable("Provider credential encryption is not configured")
        })?;
    }

    let staged = merge_live_tv_plugin_tuner_configuration(
        existing,
        configuration,
        existing_reference.as_ref(),
    )?;
    let mut live_tv = db
        .named_configuration("livetv")
        .await?
        .unwrap_or_else(default_live_tv_configuration);
    let mut tuners = live_tv
        .get("TunerHosts")
        .and_then(serde_json::Value::as_array)
        .cloned()
        .unwrap_or_default();
    if let Some(current) = tuners.iter_mut().find(|tuner| {
        json_string_field(tuner, "Id")
            .is_some_and(|candidate| candidate.eq_ignore_ascii_case(&tuner_id))
    }) {
        *current = staged;
    } else {
        tuners.push(staged);
    }
    live_tv["TunerHosts"] = serde_json::Value::Array(tuners);
    db.update_named_configuration("livetv", live_tv_configuration_json(live_tv))
        .await?;
    stop_external_plugin_host(&plugin_id).await;
    let persisted = db
        .named_configuration("livetv")
        .await?
        .and_then(|configuration| {
            live_tv_tuner_from_named_configuration(&configuration, &tuner_id).cloned()
        })
        .ok_or_else(|| ApiError::internal("Staged Live TV tuner configuration is unavailable"))?;
    if contains_plaintext_provider_secret(&persisted) {
        return Err(ApiError::internal(
            "Staged Live TV tuner configuration retained plaintext credentials",
        ));
    }
    Ok(persisted)
}

async fn live_tv_plugin_provider_request(
    db: &Database,
    plugin: &serde_json::Value,
    configuration: &serde_json::Value,
    action: &str,
    arguments: serde_json::Value,
) -> Result<LiveTvProviderRequest, ApiError> {
    let plugin_id = json_string_field(plugin, "Id")
        .ok_or_else(|| ApiError::service_unavailable("Live TV plugin identity is unavailable"))?;
    let provider_type = json_string_field(configuration, "Type")
        .ok_or_else(|| ApiError::bad_request("Live TV plugin Type is required"))?;
    let routed_plugin_id = live_tv_plugin_id_from_payload(configuration, &provider_type)
        .ok_or_else(|| ApiError::bad_request("Live TV plugin route is invalid"))?;
    if !routed_plugin_id.eq_ignore_ascii_case(&plugin_id) {
        return Err(ApiError::bad_request(
            "Live TV tuner route identifies a different plugin",
        ));
    }
    validate_live_tv_plugin_route_binding(configuration, &provider_type, &plugin_id)?;
    let tuner_id = json_string_field(configuration, "Id")
        .ok_or_else(|| ApiError::bad_request("Live TV tuner Id is required"))?;
    let submitted = submitted_provider_credentials(configuration)?;
    if submitted.is_some() {
        return Err(ApiError::bad_request(
            "Provider credentials must be persisted before invoking a Live TV plugin",
        ));
    }
    let explicit_reference = explicit_provider_secret_reference(configuration)?;
    let existing_configuration = persisted_live_tv_tuner_configuration(db, &tuner_id).await?;
    let existing_reference = existing_configuration
        .as_ref()
        .map(explicit_provider_secret_reference)
        .transpose()?
        .flatten();
    let reference = match (explicit_reference, existing_reference) {
        (Some(submitted), Some(existing)) if submitted == existing => Some(existing),
        (Some(_), Some(_)) => {
            return Err(ApiError::forbidden(
                "Live TV tuner provider secret reference does not match persisted state",
            ));
        }
        (Some(_), None) => {
            return Err(ApiError::forbidden(
                "Unpersisted provider secret references cannot be granted to plugins",
            ));
        }
        (None, existing) => existing,
    };
    let canonical_configuration = existing_configuration.as_ref().unwrap_or(configuration);
    let canonical_provider_type = json_string_field(canonical_configuration, "Type")
        .ok_or_else(|| ApiError::bad_request("Persisted Live TV plugin Type is required"))?;
    if !json_string_field(canonical_configuration, "Id")
        .is_some_and(|persisted_id| persisted_id.eq_ignore_ascii_case(&tuner_id))
    {
        return Err(ApiError::forbidden(
            "Live TV tuner identity does not match persisted state",
        ));
    }
    validate_live_tv_plugin_route_binding(
        canonical_configuration,
        &canonical_provider_type,
        &plugin_id,
    )?;

    if reference.is_some() {
        if !json_string_field(plugin, "Runtime")
            .is_some_and(|runtime| runtime.eq_ignore_ascii_case("ExternalProcess"))
        {
            return Err(ApiError::forbidden(
                "Provider secret grants require an ExternalProcess plugin runtime",
            ));
        }
        if !plugin_may_receive_provider_secrets(plugin) {
            return Err(ApiError::forbidden(
                "Live TV plugin has not requested and received ProviderSecrets permission",
            ));
        }
        let expected_namespace = provider_secret_namespace_for_configuration(
            &canonical_provider_type,
            canonical_configuration,
        )
        .map_err(|_| ApiError::bad_request("Live TV plugin secret namespace is invalid"))?;
        if reference.as_ref().is_some_and(|reference| {
            !reference
                .provider_type
                .eq_ignore_ascii_case(&expected_namespace)
        }) {
            return Err(ApiError::forbidden(
                "Provider secret reference belongs to a different plugin",
            ));
        }
    }

    let previous = if reference.is_some() {
        db.provider_credentials_for_configuration(canonical_configuration)
            .await
            .map_err(|_| {
                ApiError::service_unavailable("Live TV tuner credentials are unavailable")
            })?
    } else {
        None
    };

    let tuner_config = redacted_live_tv_plugin_tuner_config(canonical_configuration.clone())?;
    let mut request = LiveTvProviderRequest {
        action: action.to_string(),
        tuner_config,
        arguments,
        secret_grant: None,
        user_context: None,
    };
    if let Some((reference, credentials)) = previous {
        let (username, password) = credentials.into_parts();
        let mut grant = LiveTvProviderSecretGrant::new(
            &plugin_id,
            tuner_id,
            action,
            SensitiveString::new(username),
            SensitiveString::new(password),
        );
        grant = grant.secret_reference(reference.id, reference.revision);
        request = request.with_secret_grant(grant);
    }
    Ok(request)
}

/// Builds a `VodLibraryProviderRequest` for one `plugin:<id>` tuner. VOD provider credentials
/// anchor to the same tuner as the live TV flow, so the binding, persisted configuration,
/// namespace, permission and scoped grant validation are exactly the live TV builder's; only
/// the wire type changes.
async fn vod_library_plugin_provider_request(
    db: &Database,
    plugin: &serde_json::Value,
    tuner_configuration: &serde_json::Value,
    action: &str,
    arguments: serde_json::Value,
) -> Result<VodLibraryProviderRequest, ApiError> {
    let request =
        live_tv_plugin_provider_request(db, plugin, tuner_configuration, action, arguments).await?;
    Ok(VodLibraryProviderRequest {
        action: request.action,
        provider_config: request.tuner_config,
        arguments: request.arguments,
        secret_grant: request.secret_grant,
        user_context: request.user_context,
    })
}

async fn live_tv_plugin_channel_provider_import(
    db: &Database,
    payload: &serde_json::Value,
    provider_type: &str,
) -> Result<Option<LiveTvProviderImportLease>, ApiError> {
    let Some(plugin_id) = live_tv_plugin_id_from_payload(payload, provider_type) else {
        return Ok(None);
    };
    let tuner_id = json_string_field(payload, "Id")
        .ok_or_else(|| ApiError::bad_request("Live TV tuner Id is required"))?;
    let jit_lane = external_provider_jit_lane(&tuner_id)
        .ok_or_else(|| ApiError::bad_request("Live TV tuner Id is required"))?;
    let admission_guard =
        external_plugin_host_admission_slot(&plugin_id, EXTERNAL_PLUGIN_CATALOG_LANE)
            .await
            .acquire_owned()
            .await
            .map_err(|_| ApiError::service_unavailable("Live TV provider is unavailable"))?;
    let provider_session_guard = external_provider_session_slot(&plugin_id, &tuner_id)
        .await
        .write_owned()
        .await;
    let security_slot = external_plugin_security_slot(&plugin_id).await;
    let security_guard = security_slot.read_owned().await;
    stop_external_plugin_host_in_lane(&plugin_id, &jit_lane).await;
    let Some(plugin) = db.installed_plugin_json(&plugin_id).await? else {
        return Err(ApiError::not_found("Live TV plugin provider not found"));
    };
    let capabilities = plugin_string_array(plugin.get("Capabilities"));
    let uses_live_tv_provider = capabilities
        .iter()
        .any(|capability| capability.eq_ignore_ascii_case(CAPABILITY_LIVE_TV_PROVIDER));
    let uses_legacy_channel_provider = capabilities
        .iter()
        .any(|capability| capability.eq_ignore_ascii_case("ChannelProvider"));
    if json_string_field(&plugin, "Status").as_deref() != Some("Active")
        || (!uses_live_tv_provider && !uses_legacy_channel_provider)
    {
        return Err(ApiError::bad_request(
            "Live TV plugin provider must be active and expose LiveTvProvider",
        ));
    }
    let (capability, arguments) = if uses_live_tv_provider {
        let persisted = persisted_live_tv_tuner_configuration(db, &tuner_id).await?;
        let request_configuration = persisted.as_ref().unwrap_or(payload);
        let request = live_tv_plugin_provider_request(
            db,
            &plugin,
            request_configuration,
            "ImportChannels",
            serde_json::json!({}),
        )
        .await?;
        (
            CAPABILITY_LIVE_TV_PROVIDER,
            serde_json::to_value(request)
                .map_err(|_| ApiError::internal("invalid Live TV provider request"))?,
        )
    } else {
        if submitted_provider_credentials(payload)?.is_some()
            || explicit_provider_secret_reference(payload)?.is_some()
        {
            return Err(ApiError::bad_request(
                "Legacy ChannelProvider plugins cannot receive provider credentials",
            ));
        }
        (
            "ChannelProvider",
            serde_json::json!({
                "Operation": "GetItems",
                "TunerHost": payload
            }),
        )
    };
    let Some((runtime, runtime_name, error_prefix, host_path)) = plugin_runtime_host_path(&plugin)
    else {
        return Err(ApiError::internal(
            "Live TV plugin provider runtime is unavailable",
        ));
    };
    // A catalogue import may paginate a remote portal and legitimately outlive the generic
    // five-second RPC budget. All pages share one deadline and one host process; playback
    // resolution keeps its separate, much tighter deadline.
    let result = if uses_live_tv_provider {
        invoke_live_tv_provider_catalog_via_runtime_host_path(
            &plugin,
            capability,
            arguments,
            runtime.clone(),
            runtime_name,
            error_prefix,
            host_path.clone(),
            LIVE_TV_PROVIDER_CATALOG_TIMEOUT,
        )
        .await?
    } else {
        invoke_plugin_capability_via_runtime_host_path_with_timeout(
            &plugin,
            capability,
            arguments,
            runtime.clone(),
            runtime_name,
            error_prefix,
            host_path.clone(),
            LIVE_TV_PROVIDER_CATALOG_TIMEOUT,
        )
        .await?
    };
    let Some(result) = result else {
        return Err(ApiError::internal(
            "Live TV plugin provider runtime is unavailable",
        ));
    };
    let program_result = if uses_live_tv_provider && json_string_field(payload, "EpgUrl").is_some()
    {
        let persisted = persisted_live_tv_tuner_configuration(db, &tuner_id).await?;
        let request_configuration = persisted.as_ref().unwrap_or(payload);
        let request = live_tv_plugin_provider_request(
            db,
            &plugin,
            request_configuration,
            "ImportPrograms",
            serde_json::json!({}),
        )
        .await?;
        let arguments = serde_json::to_value(request)
            .map_err(|_| ApiError::internal("invalid Live TV provider request"))?;
        invoke_live_tv_provider_catalog_via_runtime_host_path(
            &plugin,
            CAPABILITY_LIVE_TV_PROVIDER,
            arguments,
            runtime,
            runtime_name,
            error_prefix,
            host_path,
            LIVE_TV_PROVIDER_CATALOG_TIMEOUT,
        )
        .await?
    } else {
        None
    };
    let channels = result
        .value
        .get(if uses_live_tv_provider {
            "Channels"
        } else {
            "Items"
        })
        .or_else(|| result.value.get("Items"))
        .and_then(serde_json::Value::as_array)
        .into_iter()
        .flatten()
        .enumerate()
        .filter_map(|(index, item)| {
            live_tv_channel_from_plugin_item(&plugin_id, index, item, uses_live_tv_provider)
        })
        .collect::<Vec<_>>();
    let categories = result
        .value
        .get("Categories")
        .and_then(serde_json::Value::as_array)
        .map(|categories| {
            categories
                .iter()
                .filter_map(safe_live_tv_plugin_category)
                .collect()
        })
        .unwrap_or_default();
    let mut programs: Vec<serde_json::Value> = program_result
        .as_ref()
        .and_then(|result| result.value.get("Programs"))
        .and_then(serde_json::Value::as_array)
        .map(|programs| {
            programs
                .iter()
                .filter_map(safe_live_tv_plugin_program)
                .collect()
        })
        .unwrap_or_default();
    // Resolve the remote channel id through a map rather than scanning the channel list for every
    // program: a provider shipping a full guide sends hundreds of thousands of programs, and the
    // scan made the import quadratic in channels times programs. `or_insert` keeps the first
    // matching channel, which is what the scan returned.
    let channel_ids_by_remote_id = channels
        .iter()
        .filter_map(|channel| {
            let remote_id = json_string_field(channel, "RemoteId")?;
            let id = json_string_field(channel, "Id")?;
            Some((remote_id.to_ascii_lowercase(), id))
        })
        .fold(HashMap::new(), |mut ids, (remote_id, id)| {
            ids.entry(remote_id).or_insert(id);
            ids
        });
    programs.retain_mut(|program| {
        let Some(remote_channel_id) = json_string_field(program, "ChannelId") else {
            return false;
        };
        let Some(channel_id) =
            channel_ids_by_remote_id.get(&remote_channel_id.to_ascii_lowercase())
        else {
            return false;
        };
        program["ChannelId"] = serde_json::Value::String(channel_id.clone());
        true
    });
    Ok((!channels.is_empty()).then_some(LiveTvProviderImportLease {
        import: LiveTvProviderImport {
            channels,
            categories,
            programs,
            channel_upserts: Vec::new(),
            category_upserts: Vec::new(),
        },
        plugin_security_guard: Some(security_guard),
        plugin_admission_guard: Some(admission_guard),
        plugin_provider_session_guard: Some(provider_session_guard),
    }))
}

fn safe_live_tv_plugin_program(program: &serde_json::Value) -> Option<serde_json::Value> {
    if contains_plaintext_provider_secret(program) {
        return None;
    }
    let id = safe_live_tv_plugin_string_field(program, "Id", 1_024).ok()??;
    let name = safe_live_tv_plugin_string_field(program, "Name", 4 * 1_024).ok()??;
    let channel_id = safe_live_tv_plugin_string_field(program, "ChannelId", 1_024).ok()??;
    let start = safe_live_tv_plugin_string_field(program, "StartDate", 128).ok()??;
    let end = safe_live_tv_plugin_string_field(program, "EndDate", 128).ok()??;
    if OffsetDateTime::parse(&start, &Rfc3339).is_err()
        || OffsetDateTime::parse(&end, &Rfc3339).is_err()
    {
        return None;
    }
    let mut safe = serde_json::json!({
        "Id": id,
        "Name": name,
        "ChannelId": channel_id,
        "StartDate": start,
        "EndDate": end,
    });
    if let Ok(Some(overview)) = safe_live_tv_plugin_string_field(program, "Overview", 16 * 1_024) {
        safe["Overview"] = serde_json::Value::String(overview);
    }
    if let Some(genres) = json_string_list_field(program, "Genres") {
        safe["Genres"] = serde_json::json!(
            genres
                .into_iter()
                .filter_map(|genre| safe_live_tv_plugin_text(&genre, 1_024))
                .take(32)
                .collect::<Vec<_>>()
        );
    }
    if let Some(image_url) = json_string_field(program, "ImageUrl")
        && reqwest::Url::parse(&image_url).is_ok_and(|url| {
            matches!(url.scheme(), "http" | "https")
                && url.username().is_empty()
                && url.password().is_none()
        })
    {
        safe["ImageUrl"] = serde_json::Value::String(image_url);
    }
    Some(safe)
}

fn safe_live_tv_plugin_category(category: &serde_json::Value) -> Option<serde_json::Value> {
    if contains_plaintext_provider_secret(category) {
        return None;
    }
    let id = safe_live_tv_plugin_string_field(category, "Id", 1_024).ok()??;
    let name = safe_live_tv_plugin_string_field(category, "Name", 1_024)
        .ok()?
        .unwrap_or_else(|| id.clone());
    Some(serde_json::json!({ "Id": id, "Name": name }))
}

fn safe_live_tv_plugin_text(value: &str, max_bytes: usize) -> Option<String> {
    let value = value.trim();
    if value.is_empty()
        || value.len() > max_bytes
        || value.chars().any(char::is_control)
        || reqwest::Url::parse(value).is_ok_and(|url| matches!(url.scheme(), "http" | "https"))
    {
        return None;
    }
    Some(value.to_string())
}

fn safe_live_tv_plugin_string_field(
    value: &serde_json::Value,
    field: &str,
    max_bytes: usize,
) -> Result<Option<String>, ()> {
    let Some(value) = json_field_case_insensitive(value, field) else {
        return Ok(None);
    };
    value
        .as_str()
        .and_then(|value| safe_live_tv_plugin_text(value, max_bytes))
        .map(Some)
        .ok_or(())
}

fn live_tv_channel_from_plugin_item(
    plugin_id: &str,
    index: usize,
    item: &serde_json::Value,
    requires_opaque_reference: bool,
) -> Option<serde_json::Value> {
    if contains_plaintext_provider_secret(item) {
        return None;
    }
    let remote_id = safe_live_tv_plugin_string_field(item, "Id", 1_024)
        .ok()?
        .unwrap_or_else(|| format!("{plugin_id}-item-{index}"));
    let provider_reference = match json_field_case_insensitive(item, "ProviderReference") {
        Some(value) => Some(value.as_str()?.to_string()),
        None => None,
    };
    if provider_reference
        .as_deref()
        .is_some_and(|reference| !valid_live_tv_provider_reference(reference))
    {
        return None;
    }
    // LiveTvProvider is the provider-secret-aware contract. Its catalogue must remain an opaque
    // index and cannot fall back to a durable source URL when a provider omits its reference.
    // Legacy ChannelProvider packages receive no secret grant and retain their historical path
    // contract until that ABI is retired.
    if requires_opaque_reference && provider_reference.is_none() {
        return None;
    }
    let path = json_string_any_field(item, &["Path", "Url", "DirectStreamUrl", "MediaPath"]);
    if provider_reference.is_none() && path.is_none() {
        return None;
    }
    let name = safe_live_tv_plugin_string_field(item, "Name", 1_024)
        .ok()?
        .unwrap_or_else(|| remote_id.clone());
    let sort_name = safe_live_tv_plugin_string_field(item, "SortName", 1_024)
        .ok()?
        .unwrap_or_else(|| name.clone());
    let number = safe_live_tv_plugin_string_field(item, "Number", 128)
        .ok()?
        .unwrap_or_else(|| (index + 1).to_string());
    let channel_type = safe_live_tv_plugin_string_field(item, "ChannelType", 64)
        .ok()?
        .unwrap_or_else(|| "TV".to_string());
    let category_id = safe_live_tv_plugin_string_field(item, "CategoryId", 1_024).ok()?;
    let provider_ids = match json_field_case_insensitive(item, "ProviderIds") {
        Some(value) => Some(safe_live_tv_plugin_provider_ids(value)?),
        None => None,
    };
    let id = live_tv_stable_id("livetv-plugin-channel", &format!("{plugin_id}-{remote_id}"));
    let mut channel = if provider_reference.is_some() {
        // Opaque providers get a deliberately narrow catalog schema. Do not preserve arbitrary
        // provider output: a misspelled or nested source field must not turn into durable data.
        let mut safe = serde_json::Map::new();
        if let Some(category_id) = category_id.as_ref() {
            safe.insert(
                "CategoryId".to_string(),
                serde_json::Value::String(category_id.clone()),
            );
        }
        if let Some(provider_ids) = provider_ids.as_ref() {
            safe.insert("ProviderIds".to_string(), provider_ids.clone());
        }
        serde_json::Value::Object(safe)
    } else if item.is_object() {
        item.clone()
    } else {
        serde_json::json!({})
    };
    if let Some(object) = channel.as_object_mut() {
        object.insert("Id".to_string(), serde_json::json!(id));
        object.insert("RemoteId".to_string(), serde_json::json!(remote_id));
        object.insert("Name".to_string(), serde_json::json!(name.clone()));
        object.insert("SortName".to_string(), serde_json::Value::String(sort_name));
        if let Some(provider_reference) = provider_reference {
            // The provider reference is a signed opaque routing token, not a source URL. Strip
            // every known URL alias so snapshots and database backups cannot capture ephemeral
            // credentials even if a provider accidentally returns both forms.
            object.insert(
                "ProviderReference".to_string(),
                serde_json::Value::String(provider_reference),
            );
            object.insert(
                "ProviderType".to_string(),
                serde_json::json!(format!("plugin:{plugin_id}")),
            );
        } else if let Some(path) = path {
            object.insert("Path".to_string(), serde_json::json!(path));
            object.insert(
                "MediaPath".to_string(),
                json_string_any_field(item, &["MediaPath", "Path", "Url", "DirectStreamUrl"])
                    .map(serde_json::Value::String)
                    .unwrap_or(serde_json::Value::Null),
            );
        }
        object.insert("Number".to_string(), serde_json::Value::String(number));
        object.insert(
            "ChannelType".to_string(),
            serde_json::Value::String(channel_type),
        );
        object.insert(
            "ProviderIds".to_string(),
            provider_ids.unwrap_or_else(|| serde_json::json!({ "JellyrinPlugin": plugin_id })),
        );
        object.insert(
            "PluginProviderId".to_string(),
            serde_json::json!(plugin_id.to_string()),
        );
        object.insert("PluginItemId".to_string(), serde_json::json!(remote_id));
    }
    Some(channel)
}

fn safe_live_tv_plugin_provider_ids(value: &serde_json::Value) -> Option<serde_json::Value> {
    let object = value.as_object()?;
    if object.len() > 64 {
        return None;
    }
    let mut safe = serde_json::Map::new();
    for (key, value) in object {
        let value = value.as_str()?;
        if key.is_empty()
            || key.len() > 128
            || value.is_empty()
            || value.len() > 1_024
            || key.chars().any(char::is_control)
            || value.chars().any(char::is_control)
            || reqwest::Url::parse(value).is_ok_and(|url| matches!(url.scheme(), "http" | "https"))
        {
            return None;
        }
        safe.insert(key.clone(), serde_json::Value::String(value.to_string()));
    }
    Some(serde_json::Value::Object(safe))
}

fn valid_live_tv_provider_reference(reference: &str) -> bool {
    let reference = reference.trim();
    let lower = reference.to_ascii_lowercase();
    !reference.is_empty()
        && reference.len() <= 4 * 1024
        && !reference.chars().any(char::is_control)
        && !lower.starts_with("http://")
        && !lower.starts_with("https://")
}

async fn persist_live_tv_provider_import(
    db: &Database,
    tuner: &serde_json::Value,
    import: &LiveTvProviderImport,
) -> Result<serde_json::Value, ApiError> {
    let uses_external_opaque_provider_references = import.channels.iter().any(|channel| {
        json_string_field(channel, "ProviderReference").is_some()
            && !json_string_field(channel, "ProviderType")
                .is_some_and(|provider| provider.eq_ignore_ascii_case("xtream"))
    });
    if uses_external_opaque_provider_references && contains_plaintext_provider_secret(tuner) {
        return Err(ApiError::bad_request(
            "Opaque Live TV providers must use external secret references",
        ));
    }
    let tuner_id = json_string_field(tuner, "Id")
        .ok_or_else(|| ApiError::bad_request("Live TV tuner id is required"))?;
    let tuner_name = json_string_field(tuner, "FriendlyName")
        .or_else(|| json_string_field(tuner, "Name"))
        .or_else(|| json_string_field(tuner, "Url"))
        .unwrap_or_else(|| "Live TV Provider".to_string());
    let source_url = json_string_field(tuner, "Url");
    let provider_type = json_string_field(tuner, "Type").unwrap_or_else(|| "unknown".to_string());
    let existing_configuration = db.live_tv_tuner_configuration_by_id(&tuner_id).await?;

    let categories = if !import.category_upserts.is_empty() {
        import.category_upserts.clone()
    } else {
        import
            .categories
            .iter()
            .filter_map(|category| {
                let remote_id = json_string_field(category, "Id")?;
                let name = json_string_field(category, "Name").unwrap_or_else(|| remote_id.clone());
                Some(LiveTvCategoryUpsert {
                    category_id: live_tv_xtream::category_db_id(&tuner_id, &remote_id),
                    tuner_id: tuner_id.clone(),
                    remote_id,
                    name,
                })
            })
            .collect::<Vec<_>>()
    };

    let channels = if !import.channel_upserts.is_empty() {
        import.channel_upserts.clone()
    } else {
        import
            .channels
            .iter()
            .filter_map(|channel| live_tv_xtream::channel_upsert_from_json(&tuner_id, channel))
            .collect::<Vec<_>>()
    };

    let mut configuration = tuner.clone();
    let object = configuration
        .as_object_mut()
        .ok_or_else(|| ApiError::bad_request("Live TV tuner configuration must be an object"))?;
    object.remove("Channels");
    object.remove("Categories");
    if import.programs.is_empty() {
        object.remove("Programs");
    } else {
        object.insert(
            "Programs".to_string(),
            serde_json::Value::Array(import.programs.clone()),
        );
    }
    object.insert(
        "PersistedChannelCount".to_string(),
        serde_json::json!(channels.len()),
    );
    object.insert(
        "PersistedCategoryCount".to_string(),
        serde_json::json!(categories.len()),
    );
    let configuration_revision = existing_configuration
        .as_ref()
        .filter(|existing| {
            live_tv_source_configuration(existing) == live_tv_source_configuration(&configuration)
        })
        .and_then(|existing| json_string_field(existing, "JellyrinConfigurationRevision"))
        .unwrap_or_else(|| Uuid::new_v4().simple().to_string());
    configuration["JellyrinConfigurationRevision"] = serde_json::json!(configuration_revision);

    let persisted = LiveTvService::new(db)
        .replace_tuner_snapshot(
            LiveTvTunerUpsert {
                tuner_id,
                provider_type,
                name: tuner_name,
                source_url,
                configuration,
            },
            categories,
            channels,
        )
        .await
        .map_err(ApiError::from)?;
    if uses_external_opaque_provider_references && contains_plaintext_provider_secret(&persisted) {
        return Err(ApiError::internal(
            "Persisted opaque Live TV tuner retained plaintext credentials",
        ));
    }
    Ok(persisted)
}

fn vod_library_plugin_image_url_field(
    value: &serde_json::Value,
    field: &str,
) -> Result<Option<String>, ()> {
    let Some(value) = json_field_case_insensitive(value, field) else {
        return Ok(None);
    };
    if value.is_null() {
        return Ok(None);
    }
    let value = value.as_str().map(str::trim).ok_or(())?;
    if value.is_empty() || value.len() > 2_048 || value.chars().any(char::is_control) {
        return Err(());
    }
    let url = reqwest::Url::parse(value).map_err(|_| ())?;
    if !matches!(url.scheme(), "http" | "https")
        || !url.username().is_empty()
        || url.password().is_some()
    {
        return Err(());
    }
    Ok(Some(value.to_string()))
}

fn vod_library_plugin_i32_field(
    value: &serde_json::Value,
    field: &str,
    range: std::ops::RangeInclusive<i32>,
) -> Result<Option<i32>, ()> {
    let Some(value) = json_field_case_insensitive(value, field) else {
        return Ok(None);
    };
    if value.is_null() {
        return Ok(None);
    }
    value
        .as_i64()
        .and_then(|number| i32::try_from(number).ok())
        .filter(|number| range.contains(number))
        .map(Some)
        .ok_or(())
}

fn vod_library_plugin_runtime_ticks(value: &serde_json::Value) -> Result<Option<i64>, ()> {
    let Some(value) = json_field_case_insensitive(value, "RuntimeTicks") else {
        return Ok(None);
    };
    if value.is_null() {
        return Ok(None);
    }
    value
        .as_i64()
        .filter(|ticks| *ticks >= 0)
        .map(Some)
        .ok_or(())
}

fn vod_library_plugin_rating_field(value: &serde_json::Value) -> Result<Option<f64>, ()> {
    let Some(value) = json_field_case_insensitive(value, "CommunityRating") else {
        return Ok(None);
    };
    if value.is_null() {
        return Ok(None);
    }
    value
        .as_f64()
        .filter(|rating| rating.is_finite() && (0.0..=10.0).contains(rating))
        .map(Some)
        .ok_or(())
}

fn vod_library_plugin_genres(value: &serde_json::Value) -> Result<Vec<String>, ()> {
    let Some(value) = json_field_case_insensitive(value, "Genres") else {
        return Ok(Vec::new());
    };
    if value.is_null() {
        return Ok(Vec::new());
    }
    let values = value.as_array().ok_or(())?;
    if values.len() > 32 {
        return Err(());
    }
    values
        .iter()
        .map(|genre| {
            genre
                .as_str()
                .and_then(|genre| safe_live_tv_plugin_text(genre, 256))
                .ok_or(())
        })
        .collect()
}

/// Projects one untrusted provider item onto the bounded `VodMediaItem` contract. Arbitrary
/// provider fields never reach persistence, and any item carrying credential-shaped material is
/// dropped instead of sanitized in place.
fn vod_library_media_item_from_plugin(
    plugin_id: &str,
    tuner_id: &str,
    index: usize,
    item: &serde_json::Value,
) -> Option<VodMediaItem> {
    fn rejected(
        plugin_id: &str,
        tuner_id: &str,
        index: usize,
        reason: &str,
    ) -> Option<VodMediaItem> {
        tracing::debug!(
            plugin_id,
            tuner_id,
            index,
            reason,
            "dropped VOD library provider media item"
        );
        None
    }

    if contains_plaintext_provider_secret(item) {
        return rejected(plugin_id, tuner_id, index, "plaintext provider secret");
    }
    let item_type = json_field_case_insensitive(item, "ItemType")
        .and_then(|value| value.as_str())
        .map(str::trim)?;
    let item_type = if item_type.eq_ignore_ascii_case(VOD_ITEM_TYPE_MOVIE) {
        VOD_ITEM_TYPE_MOVIE
    } else if item_type.eq_ignore_ascii_case(VOD_ITEM_TYPE_SERIES) {
        VOD_ITEM_TYPE_SERIES
    } else if item_type.eq_ignore_ascii_case(VOD_ITEM_TYPE_EPISODE) {
        VOD_ITEM_TYPE_EPISODE
    } else {
        return rejected(plugin_id, tuner_id, index, "unknown item type");
    };
    let provider_reference = json_field_case_insensitive(item, "ProviderReference")
        .and_then(|value| value.as_str())?
        .to_string();
    if !valid_live_tv_provider_reference(&provider_reference) {
        return rejected(plugin_id, tuner_id, index, "invalid provider reference");
    }
    let name = safe_live_tv_plugin_string_field(item, "Name", 1_024).ok()??;
    let overview = safe_live_tv_plugin_string_field(item, "Overview", 1_024).ok()?;
    let image_url = vod_library_plugin_image_url_field(item, "ImageUrl").ok()?;
    let production_year = vod_library_plugin_i32_field(item, "ProductionYear", 0..=9_999).ok()?;
    let runtime_ticks = vod_library_plugin_runtime_ticks(item).ok()?;
    let community_rating = vod_library_plugin_rating_field(item).ok()?;
    let genres = vod_library_plugin_genres(item).ok()?;

    let mut media_item = match item_type {
        VOD_ITEM_TYPE_MOVIE => VodMediaItem::movie(provider_reference, name),
        VOD_ITEM_TYPE_SERIES => VodMediaItem::series(provider_reference, name),
        _ => VodMediaItem {
            item_type: VOD_ITEM_TYPE_EPISODE.to_string(),
            ..VodMediaItem::movie(provider_reference, name)
        },
    };
    media_item.overview = overview;
    media_item.image_url = image_url;
    media_item.production_year = production_year;
    media_item.runtime_ticks = runtime_ticks;
    media_item.community_rating = community_rating;
    media_item.genres = genres;
    if media_item.item_type == VOD_ITEM_TYPE_EPISODE {
        let series_reference = json_field_case_insensitive(item, "SeriesReference")
            .and_then(|value| value.as_str())?;
        if !valid_live_tv_provider_reference(series_reference) {
            return rejected(plugin_id, tuner_id, index, "invalid series reference");
        }
        media_item.series_reference = Some(series_reference.to_string());
        media_item.series_name =
            safe_live_tv_plugin_string_field(item, "SeriesName", 1_024).ok()?;
        media_item.season_number =
            vod_library_plugin_i32_field(item, "SeasonNumber", 0..=10_000).ok()?;
        media_item.episode_number =
            vod_library_plugin_i32_field(item, "EpisodeNumber", 0..=1_000_000).ok()?;
    }
    Some(media_item)
}

#[derive(Debug, Clone, Copy, Default, Eq, PartialEq)]
struct VodLibraryPluginImportCounts {
    movie_count: usize,
    series_count: usize,
    episode_count: usize,
}

fn vod_library_plugin_library_scope(plugin_name: &str) -> String {
    let name = plugin_name.trim();
    if name.is_empty() || name.len() > 128 || name.chars().any(char::is_control) {
        "Plugin".to_string()
    } else {
        name.to_string()
    }
}

