fn plugin_vod_series_id(plugin_id: &str, tuner_id: &str, series_reference: &str) -> String {
    stable_entity_id(
        "plugin-vod-series",
        &format!("{plugin_id}:{tuner_id}:{series_reference}"),
    )
}

fn vod_library_media_item_upsert(
    plugin_id: &str,
    tuner_id: &str,
    item: &VodMediaItem,
    series_name: Option<&str>,
    series_overview: Option<&str>,
    series_image_url: Option<&str>,
) -> RemoteMediaItemUpsert {
    let kind = match item.item_type.as_str() {
        VOD_ITEM_TYPE_MOVIE => "movie",
        VOD_ITEM_TYPE_EPISODE => "episode",
        _ => "series",
    };
    let collection_type = if item.item_type == VOD_ITEM_TYPE_MOVIE {
        "movies"
    } else {
        "tvshows"
    };
    let stable_key = format!("{plugin_id}:{tuner_id}:{kind}:{}", item.provider_reference);
    // The persisted path is an opaque, non-URL routing token. Playback is resolved just-in-time
    // from the ProviderReference, so no provider URL or credential ever becomes durable.
    let path = format!(
        "plugin-vod://{plugin_id}/{}",
        stable_entity_id("plugin-vod-path", &stable_key)
    );
    let mut metadata = serde_json::json!({
        "Provider": format!("plugin:{plugin_id}"),
        "TunerId": tuner_id,
        "ProviderReference": item.provider_reference,
        "PluginVodKind": kind,
        "Name": item.name,
        "Genres": item.genres,
    });
    if let Some(overview) = item.overview.as_deref() {
        metadata["Overview"] = serde_json::json!(overview);
    }
    if let Some(image_url) = item.image_url.as_deref() {
        metadata["ImageUrl"] = serde_json::json!(image_url);
        metadata["PrimaryImageUrl"] = serde_json::json!(image_url);
    }
    if let Some(year) = item.production_year {
        metadata["ProductionYear"] = serde_json::json!(year);
    }
    if let Some(rating) = item.community_rating {
        metadata["CommunityRating"] = serde_json::json!(rating);
    }
    if item.item_type == VOD_ITEM_TYPE_SERIES {
        let series_reference = item.provider_reference.as_str();
        metadata["SeriesReference"] = serde_json::json!(series_reference);
        metadata["SeriesId"] =
            serde_json::json!(plugin_vod_series_id(plugin_id, tuner_id, series_reference));
        metadata["SeriesName"] = serde_json::json!(item.name);
        if let Some(overview) = item.overview.as_deref() {
            metadata["SeriesOverview"] = serde_json::json!(overview);
        }
        if let Some(image_url) = item.image_url.as_deref() {
            metadata["SeriesPrimaryImageUrl"] = serde_json::json!(image_url);
        }
        if let Some(year) = item.production_year {
            metadata["SeriesProductionYear"] = serde_json::json!(year);
        }
        if let Some(rating) = item.community_rating {
            metadata["SeriesCommunityRating"] = serde_json::json!(rating);
        }
        if !item.genres.is_empty() {
            metadata["SeriesGenres"] = serde_json::json!(item.genres);
        }
    } else if item.item_type == VOD_ITEM_TYPE_EPISODE {
        let series_reference = item.series_reference.as_deref().unwrap_or_default();
        let series_key = format!("{plugin_id}:{tuner_id}:{series_reference}");
        metadata["SeriesReference"] = serde_json::json!(series_reference);
        metadata["SeriesId"] =
            serde_json::json!(plugin_vod_series_id(plugin_id, tuner_id, series_reference));
        metadata["SeriesName"] = serde_json::json!(
            item.series_name
                .as_deref()
                .or(series_name)
                .unwrap_or(series_reference)
        );
        if let Some(season_number) = item.season_number {
            metadata["SeasonId"] = serde_json::json!(stable_entity_id(
                "plugin-vod-season",
                &format!("{series_key}:{season_number}")
            ));
            metadata["ParentIndexNumber"] = serde_json::json!(season_number);
        }
        if let Some(episode_number) = item.episode_number {
            metadata["IndexNumber"] = serde_json::json!(episode_number);
        }
        if let Some(series_image_url) = series_image_url {
            metadata["SeriesImageUrl"] = serde_json::json!(series_image_url);
        }
        if let Some(series_overview) = series_overview {
            metadata["SeriesOverview"] = serde_json::json!(series_overview);
            // MAGSTV exposes one series synopsis rather than distinct season copy. Reusing it is
            // preferable to a blank synthetic Season detail and remains safe plain metadata.
            metadata["SeasonOverview"] = serde_json::json!(series_overview);
        }
    }
    let is_series = item.item_type == VOD_ITEM_TYPE_SERIES;
    RemoteMediaItemUpsert {
        id: stable_entity_id("plugin-vod-item", &stable_key),
        name: item.name.clone(),
        path,
        media_type: if is_series { "Series" } else { "Video" }.to_string(),
        collection_type: collection_type.to_string(),
        runtime_ticks: item.runtime_ticks,
        bitrate: None,
        width: None,
        height: None,
        media_streams: if is_series {
            Vec::new()
        } else {
            default_plugin_vod_media_streams()
        },
        metadata,
    }
}

fn vod_library_plugin_stage_specs(
    plugin_name: &str,
    plugin_id: &str,
) -> Vec<RemoteMediaLibraryStageSpec> {
    let scope = vod_library_plugin_library_scope(plugin_name);
    vec![
        RemoteMediaLibraryStageSpec {
            key: "movies".to_string(),
            library_name: format!("{scope} Movies"),
            collection_type: "movies".to_string(),
            source_location: format!("plugin-vod://{plugin_id}/movies"),
        },
        RemoteMediaLibraryStageSpec {
            key: "series".to_string(),
            library_name: format!("{scope} Series"),
            collection_type: "tvshows".to_string(),
            source_location: format!("plugin-vod://{plugin_id}/series"),
        },
    ]
}

/// Streams one validated provider page into a durable, not-yet-visible catalogue generation.
/// Only the series lookup survives between pages; movies and episodes are projected and appended
/// in database-sized batches before the next provider RPC is issued. MAGSTV emits movies, then
/// series, then episodes, so retaining that compact index preserves enrichment across page-kind
/// boundaries without retaining the movie or episode catalogue.
struct VodPluginCatalogStageWriter<'a> {
    db: &'a Database,
    stage: &'a RemoteMediaCatalogStage,
    plugin_id: &'a str,
    tuner_id: &'a str,
    series_index: HashMap<String, VodPluginSeriesMetadata>,
    counts: VodLibraryPluginImportCounts,
    seen_remote_items: usize,
}

#[derive(Clone)]
struct VodPluginSeriesMetadata {
    name: String,
    overview: Option<String>,
    image_url: Option<String>,
}

impl<'a> VodPluginCatalogStageWriter<'a> {
    fn new(
        db: &'a Database,
        stage: &'a RemoteMediaCatalogStage,
        plugin_id: &'a str,
        tuner_id: &'a str,
    ) -> Self {
        Self {
            db,
            stage,
            plugin_id,
            tuner_id,
            series_index: HashMap::new(),
            counts: VodLibraryPluginImportCounts::default(),
            seen_remote_items: 0,
        }
    }

    fn counts(&self) -> VodLibraryPluginImportCounts {
        self.counts
    }

    async fn append_page(&mut self, media_items: Vec<serde_json::Value>) -> Result<(), ApiError> {
        // Project one RPC page at a time. Invalid provider items retain the existing contract of
        // being dropped, but never remain resident after this call returns.
        let mut items = Vec::with_capacity(media_items.len());
        for item in media_items {
            let index = self.seen_remote_items;
            self.seen_remote_items = self.seen_remote_items.saturating_add(1);
            if let Some(item) =
                vod_library_media_item_from_plugin(self.plugin_id, self.tuner_id, index, &item)
            {
                items.push(item);
            }
        }

        // Index every series in this page before projecting its episodes. This preserves series
        // enrichment even when a provider emits a series row after its first episode in a page.
        let mut new_series = Vec::new();
        for item in &items {
            if item.item_type == VOD_ITEM_TYPE_SERIES {
                match self.series_index.entry(item.provider_reference.clone()) {
                    std::collections::hash_map::Entry::Vacant(entry) => {
                        entry.insert(VodPluginSeriesMetadata {
                            name: item.name.clone(),
                            overview: item.overview.clone(),
                            image_url: item.image_url.clone(),
                        });
                        new_series.push(item.clone());
                    }
                    std::collections::hash_map::Entry::Occupied(_) => {}
                }
            }
        }

        let mut movies = Vec::new();
        let mut series_items = new_series
            .iter()
            .map(|item| {
                vod_library_media_item_upsert(self.plugin_id, self.tuner_id, item, None, None, None)
            })
            .collect::<Vec<_>>();
        let mut episode_count = 0usize;
        for item in items {
            match item.item_type.as_str() {
                VOD_ITEM_TYPE_MOVIE => {
                    movies.push(vod_library_media_item_upsert(
                        self.plugin_id,
                        self.tuner_id,
                        &item,
                        None,
                        None,
                        None,
                    ));
                }
                VOD_ITEM_TYPE_EPISODE => {
                    let series_entry = item
                        .series_reference
                        .as_deref()
                        .and_then(|reference| self.series_index.get(reference));
                    series_items.push(vod_library_media_item_upsert(
                        self.plugin_id,
                        self.tuner_id,
                        &item,
                        series_entry.map(|series| series.name.as_str()),
                        series_entry.and_then(|series| series.overview.as_deref()),
                        series_entry.and_then(|series| series.image_url.as_deref()),
                    ));
                    episode_count = episode_count.saturating_add(1);
                }
                _ => {}
            }
        }

        let movie_count = movies.len();
        append_vod_library_stage_items(self.db, self.stage, "movies", movies).await?;
        append_vod_library_stage_items(self.db, self.stage, "series", series_items).await?;
        self.counts.movie_count = self.counts.movie_count.saturating_add(movie_count);
        self.counts.series_count = self.series_index.len();
        self.counts.episode_count = self.counts.episode_count.saturating_add(episode_count);
        Ok(())
    }
}

async fn append_vod_library_stage_items(
    db: &Database,
    stage: &RemoteMediaCatalogStage,
    library_key: &str,
    items: Vec<RemoteMediaItemUpsert>,
) -> Result<(), ApiError> {
    let mut items = items.into_iter();
    loop {
        let chunk = items
            .by_ref()
            .take(REMOTE_MEDIA_CATALOG_STAGE_MAX_APPEND_ITEMS)
            .collect::<Vec<_>>();
        if chunk.is_empty() {
            return Ok(());
        }
        db.append_remote_media_catalog_stage(stage, library_key, chunk)
            .await
            .map_err(ApiError::from)?;
    }
}

/// Cancelling an HTTP request drops its import future. Keep the durable stage from becoming an
/// abandoned partial generation by scheduling an abort from `Drop`; ordinary error paths await
/// the same abort explicitly before returning.
struct VodPluginCatalogStageAbortGuard {
    db: Database,
    stage: Option<RemoteMediaCatalogStage>,
}

impl VodPluginCatalogStageAbortGuard {
    fn new(db: Database, stage: RemoteMediaCatalogStage) -> Self {
        Self {
            db,
            stage: Some(stage),
        }
    }

    fn disarm(&mut self) {
        self.stage = None;
    }

    async fn abort(&mut self) {
        let Some(stage) = self.stage.clone() else {
            return;
        };
        match self.db.abort_remote_media_catalog_stage(&stage).await {
            Ok(()) => self.stage = None,
            Err(error) => {
                tracing::warn!(stage_id = stage.id(), %error, "failed to abort VOD catalogue stage");
            }
        }
    }
}

impl Drop for VodPluginCatalogStageAbortGuard {
    fn drop(&mut self) {
        let Some(stage) = self.stage.take() else {
            return;
        };
        let db = self.db.clone();
        let Ok(runtime) = tokio::runtime::Handle::try_current() else {
            tracing::warn!(
                stage_id = stage.id(),
                "could not schedule cancellation cleanup for VOD catalogue stage"
            );
            return;
        };
        runtime.spawn(async move {
            if let Err(error) = db.abort_remote_media_catalog_stage(&stage).await {
                tracing::warn!(
                    stage_id = stage.id(),
                    %error,
                    "failed to abort cancelled VOD catalogue stage"
                );
            }
        });
    }
}

async fn vod_library_plugin_tuner_configurations(
    db: &Database,
    plugin_id: &str,
) -> Result<Vec<serde_json::Value>, ApiError> {
    let Some(configuration) = db.named_configuration("livetv").await? else {
        return Ok(Vec::new());
    };
    let mut tuners = configuration
        .get("TunerHosts")
        .and_then(serde_json::Value::as_array)
        .into_iter()
        .flatten()
        .filter(|tuner| {
            json_string_field(tuner, "Type").is_some_and(|tuner_type| {
                live_tv_plugin_id_from_payload(tuner, &tuner_type)
                    .is_some_and(|candidate| candidate.eq_ignore_ascii_case(plugin_id))
            })
        })
        .cloned()
        .collect::<Vec<_>>();
    tuners.sort_by(|left, right| {
        json_string_field(left, "Id")
            .unwrap_or_default()
            .to_ascii_lowercase()
            .cmp(
                &json_string_field(right, "Id")
                    .unwrap_or_default()
                    .to_ascii_lowercase(),
            )
    });
    Ok(tuners)
}

/// Runs one complete `ImportMedia` exchange against an active `VodLibraryProvider` plugin and
/// atomically republishes its two library snapshots. Returns `None` when the plugin has no
/// configured `plugin:<id>` tuner yet.
async fn vod_library_plugin_media_import(
    db: &Database,
    plugin_id: &str,
) -> Result<Option<VodLibraryPluginImportCounts>, ApiError> {
    let _admission_guard =
        external_plugin_host_admission_slot(plugin_id, EXTERNAL_PLUGIN_CATALOG_LANE)
            .await
            .acquire_owned()
            .await
            .map_err(|_| ApiError::service_unavailable("VOD library provider is unavailable"))?;
    vod_library_plugin_media_import_admitted(db, plugin_id).await
}

/// Runs an import after its caller has acquired the shared `catalog-import` admission slot.
/// Automatic tuner-triggered refreshes use this seam with `try_acquire_owned` so they never queue
/// a duplicate generation behind an import that is already running.
async fn vod_library_plugin_media_import_admitted(
    db: &Database,
    plugin_id: &str,
) -> Result<Option<VodLibraryPluginImportCounts>, ApiError> {
    let preflight_tuners = vod_library_plugin_tuner_configurations(db, plugin_id).await?;
    if preflight_tuners.is_empty() {
        return Ok(None);
    }
    let preflight_tuner_ids = preflight_tuners
        .iter()
        .map(|tuner| {
            json_string_field(tuner, "Id")
                .filter(|id| !id.is_empty())
                .ok_or_else(|| ApiError::bad_request("Live TV tuner Id is required"))
        })
        .collect::<Result<Vec<_>, _>>()?;
    if preflight_tuner_ids
        .windows(2)
        .any(|pair| pair[0].eq_ignore_ascii_case(&pair[1]))
    {
        return Err(ApiError::bad_request(
            "VOD provider tuner Ids must be unique",
        ));
    }
    let mut provider_session_guards = Vec::with_capacity(preflight_tuner_ids.len());
    for tuner_id in &preflight_tuner_ids {
        provider_session_guards.push(
            external_provider_session_slot(plugin_id, tuner_id)
                .await
                .write_owned()
                .await,
        );
    }
    let security_slot = external_plugin_security_slot(plugin_id).await;
    let _security_guard = security_slot.read_owned().await;
    let Some(plugin) = db.installed_plugin_json(plugin_id).await? else {
        return Err(ApiError::not_found("VOD library plugin not found"));
    };
    let uses_vod_library_provider = plugin_string_array(plugin.get("Capabilities"))
        .iter()
        .any(|capability| capability.eq_ignore_ascii_case(CAPABILITY_VOD_LIBRARY_PROVIDER));
    if json_string_field(&plugin, "Status").as_deref() != Some("Active")
        || !uses_vod_library_provider
    {
        return Err(ApiError::bad_request(
            "VOD library plugin must be active and expose VodLibraryProvider",
        ));
    }
    let tuners = vod_library_plugin_tuner_configurations(db, plugin_id).await?;
    let tuner_ids = tuners
        .iter()
        .map(|tuner| {
            json_string_field(tuner, "Id")
                .filter(|id| !id.is_empty())
                .ok_or_else(|| ApiError::bad_request("Live TV tuner Id is required"))
        })
        .collect::<Result<Vec<_>, _>>()?;
    if tuner_ids != preflight_tuner_ids {
        return Err(ApiError::service_unavailable(
            "VOD provider tuners changed before catalogue synchronization",
        ));
    }
    for tuner_id in &tuner_ids {
        let jit_lane = external_provider_jit_lane(tuner_id)
            .ok_or_else(|| ApiError::bad_request("Live TV tuner Id is required"))?;
        stop_external_plugin_host_in_lane(plugin_id, &jit_lane).await;
    }
    let Some((runtime, runtime_name, error_prefix, host_path)) = plugin_runtime_host_path(&plugin)
    else {
        return Err(ApiError::internal(
            "VOD library plugin runtime is unavailable",
        ));
    };
    let plugin_name = json_string_field(&plugin, "Name").unwrap_or_else(|| plugin_id.to_string());
    let stage = db
        .begin_remote_media_catalog_stage(vod_library_plugin_stage_specs(&plugin_name, plugin_id))
        .await
        .map_err(ApiError::from)?;
    let mut abort_guard = VodPluginCatalogStageAbortGuard::new(db.clone(), stage.clone());

    // One isolated runtime process owns all provider-instance snapshots while each validated
    // page is projected into the shared durable stage. The old visible libraries remain
    // untouched until every tuner is complete and both libraries publish in one transaction.
    let import_result = async {
        let mut counts = VodLibraryPluginImportCounts::default();
        for (tuner, tuner_id) in tuners.iter().zip(&tuner_ids) {
            let request = vod_library_plugin_provider_request(
                db,
                &plugin,
                tuner,
                "ImportMedia",
                serde_json::json!({}),
            )
            .await?;
            let arguments = serde_json::to_value(request)
                .map_err(|_| ApiError::internal("invalid VOD library provider request"))?;
            let mut writer = VodPluginCatalogStageWriter::new(db, &stage, plugin_id, tuner_id);
            let tuner_counts = invoke_vod_library_provider_via_runtime_host_path(
                &plugin,
                CAPABILITY_VOD_LIBRARY_PROVIDER,
                arguments,
                runtime.clone(),
                runtime_name,
                error_prefix,
                host_path.clone(),
                vod_library_provider_catalog_timeout(),
                &mut writer,
            )
            .await?
            .ok_or_else(|| ApiError::internal("VOD library plugin runtime is unavailable"))?;
            counts.movie_count = counts.movie_count.saturating_add(tuner_counts.movie_count);
            counts.series_count = counts
                .series_count
                .saturating_add(tuner_counts.series_count);
            counts.episode_count = counts
                .episode_count
                .saturating_add(tuner_counts.episode_count);
        }
        db.complete_remote_media_catalog_stage(&stage)
            .await
            .map_err(ApiError::from)?;
        db.publish_remote_media_catalog_stage(&stage)
            .await
            .map_err(ApiError::from)?;
        Ok::<_, ApiError>(counts)
    }
    .await;

    match import_result {
        Ok(counts) => {
            abort_guard.disarm();
            drop(provider_session_guards);
            Ok(Some(counts))
        }
        Err(error) => {
            abort_guard.abort().await;
            Err(error)
        }
    }
}

/// Schedules a VOD library refresh after a successful `plugin:<id>` tuner write. The tuner POST
/// never waits for a potentially two-hour provider import, and a second automatic refresh is
/// skipped while the shared catalogue lane is occupied. The explicit admin refresh remains
/// synchronous and can report its final counts.
fn maybe_refresh_vod_library_for_tuner(state: &AppState, tuner: &serde_json::Value) {
    let Some(tuner_type) = json_string_field(tuner, "Type") else {
        return;
    };
    let Some(plugin_id) = live_tv_plugin_id_from_payload(tuner, &tuner_type) else {
        return;
    };
    let db = state.db.clone();
    tokio::spawn(async move {
        let declares_vod_library = match db.installed_plugin_json(&plugin_id).await {
            Ok(Some(plugin)) => plugin_string_array(plugin.get("Capabilities"))
                .iter()
                .any(|capability| capability.eq_ignore_ascii_case(CAPABILITY_VOD_LIBRARY_PROVIDER)),
            _ => false,
        };
        if !declares_vod_library {
            return;
        }
        let admission = external_plugin_host_admission_slot(&plugin_id, "catalog-import").await;
        let Ok(_admission_guard) = admission.try_acquire_owned() else {
            tracing::debug!(plugin_id, "skipped duplicate automatic VOD library refresh");
            return;
        };
        match vod_library_plugin_media_import_admitted(&db, &plugin_id).await {
            Ok(Some(counts)) => tracing::info!(
                plugin_id,
                movie_count = counts.movie_count,
                series_count = counts.series_count,
                episode_count = counts.episode_count,
                "VOD library import completed after Live TV tuner refresh"
            ),
            Ok(None) => {}
            Err(error) => tracing::warn!(
                plugin_id,
                ?error,
                "VOD library import failed after Live TV tuner refresh"
            ),
        }
    });
}

fn live_tv_source_configuration(value: &serde_json::Value) -> serde_json::Value {
    let mut normalized = value.clone();
    if let Some(object) = normalized.as_object_mut() {
        for key in [
            "Channels",
            "Categories",
            "PersistedChannelCount",
            "PersistedCategoryCount",
            "JellyrinConfigurationRevision",
        ] {
            object.remove(key);
        }
    }
    normalized
}

async fn sync_all_configured_xtream_media(
    db: &Database,
    cancellation: watch::Receiver<bool>,
) -> Result<serde_json::Value, ApiError> {
    live_tv_xtream::sync_all_configured_xtream_media_with_cancellation(db, Some(cancellation))
        .await
        .map_err(|error| ApiError::internal(format!("Xtream media sync failed: {error}")))
}

async fn start_xtream_media_sync_task(
    db: Database,
    session_id: Option<String>,
) -> Result<(), ApiError> {
    let run = match TaskService::new(&db)
        .start(XTREAM_MEDIA_SYNC_TASK_KEY)
        .await
    {
        Ok(run) => run,
        Err(error) if format!("{error:#}").contains("task is already running") => {
            return Ok(());
        }
        Err(error)
            if db
                .current_task_run(XTREAM_MEDIA_SYNC_TASK_KEY)
                .await?
                .is_some() =>
        {
            let _ = error;
            return Ok(());
        }
        Err(error) => return Err(error.into()),
    };
    if let Some(session_id) = session_id.as_deref() {
        broadcast_scheduled_tasks_update(&db, session_id).await?;
    }
    let (cancellation_sender, cancellation_receiver) = watch::channel(false);
    {
        let mut cancellation = xtream_media_sync_cancellation()
            .lock()
            .map_err(|_| ApiError::internal("Xtream media sync cancellation lock poisoned"))?;
        *cancellation = Some(XtreamMediaSyncCancellation {
            run_id: run.id,
            sender: cancellation_sender,
        });
    }
    tokio::spawn(async move {
        let sync = sync_all_configured_xtream_media(&db, cancellation_receiver);
        tokio::pin!(sync);
        let started = std::time::Instant::now();
        let mut heartbeat = tokio::time::interval(std::time::Duration::from_secs(
            XTREAM_MEDIA_SYNC_HEARTBEAT_SECONDS,
        ));
        heartbeat.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
        let result = loop {
            tokio::select! {
                result = &mut sync => break result,
                _ = heartbeat.tick() => {
                    let _ = TaskService::new(&db)
                        .update_progress(
                            run.id,
                            serde_json::json!({
                                "Phase": "Synchronizing Xtream media",
                                "ElapsedSeconds": started.elapsed().as_secs(),
                            }),
                        )
                        .await;
                }
            }
        };
        match result {
            Ok(result) => {
                let _ = TaskService::new(&db).complete(run.id, result).await;
            }
            Err(error) => {
                let message = format!("{error:?}");
                let _ = TaskService::new(&db).fail(run.id, &message).await;
            }
        }
        if let Ok(mut cancellation) = xtream_media_sync_cancellation().lock()
            && cancellation
                .as_ref()
                .is_some_and(|active| active.run_id == run.id)
        {
            *cancellation = None;
        }
        if let Some(session_id) = session_id.as_deref() {
            let _ = broadcast_scheduled_tasks_update(&db, session_id).await;
        }
    });
    Ok(())
}

fn live_tv_channel_record_to_json(
    record: &LiveTvChannelRecord,
    server_id: &str,
) -> serde_json::Value {
    let mut base = record.metadata.clone();
    let raw_channel_id = record.channel_id.clone();
    let public_channel_id = live_tv_channel_public_id(&raw_channel_id);
    base["Id"] = serde_json::json!(public_channel_id);
    base["ChannelId"] = base["Id"].clone();
    base["JellyrinChannelId"] = serde_json::json!(raw_channel_id);
    base["RemoteId"] = serde_json::json!(record.remote_id);
    base["ServerId"] = serde_json::json!(server_id);
    base["Name"] = serde_json::json!(record.name);
    base["SortName"] = serde_json::json!(record.sort_name);
    base["Number"] = record
        .number
        .clone()
        .map(serde_json::Value::String)
        .unwrap_or(serde_json::Value::Null);
    if record.stream_url.trim().is_empty() {
        if let Some(object) = base.as_object_mut() {
            object.remove("Path");
            object.remove("MediaPath");
            object.remove("Url");
            object.remove("DirectStreamUrl");
        }
    } else {
        base["Path"] = serde_json::json!(record.stream_url);
    }
    base["TunerHostId"] = serde_json::json!(record.tuner_id);
    base["Type"] = serde_json::json!("TvChannel");
    base["MediaType"] = serde_json::json!("Video");
    base["ChannelType"] = serde_json::json!(record.channel_type);
    base["IsFolder"] = serde_json::json!(false);
    base["IsLive"] = serde_json::json!(true);
    base["CanDelete"] = serde_json::json!(false);
    base["CanDownload"] = serde_json::json!(false);
    base["EnableMediaSourceDisplay"] = serde_json::json!(true);
    base["PlayAccess"] = serde_json::json!("Full");
    base["LocationType"] = serde_json::json!("Remote");
    base["RunTimeTicks"] = serde_json::Value::Null;
    base["UserData"] = serde_json::json!({
        "PlaybackPositionTicks": 0,
        "PlayCount": 0,
        "IsFavorite": false,
        "Played": false,
        "Key": public_channel_id,
        "ItemId": public_channel_id
    });
    base["CurrentProgram"] = serde_json::Value::Null;
    if let Some(category_name) = record.category_name.as_deref() {
        base["Genres"] = serde_json::json!([category_name]);
        base["Tags"] = serde_json::json!([category_name]);
        base["GenreItems"] = serde_json::json!([{
            "Id": stable_entity_id("LiveTvGenre", category_name),
            "Name": category_name
        }]);
    }
    apply_live_tv_category_flags(&mut base);
    if let Some(logo_url) = record.logo_url.as_deref() {
        base["ImageUrl"] = serde_json::json!(logo_url);
    }
    apply_live_tv_image_metadata(&mut base);
    if (live_tv_channel_path(&base).is_ok() || live_tv_channel_provider_reference(&base).is_some())
        && let Ok(mut media_source) = live_tv_channel_media_source(&base)
    {
        suppress_remote_live_tv_direct_stream_for_item_detail(&mut media_source);
        base["MediaSources"] = serde_json::json!([media_source]);
    }
    base
}

async fn live_tv_channel_record_by_any_id(
    db: &Database,
    channel_id: &str,
) -> Result<Option<LiveTvChannelRecord>, ApiError> {
    let service = LiveTvService::new(db);
    let channel_id = channel_id.trim();
    if let Some(channel) = service.channel_by_id(channel_id).await? {
        return Ok(Some(channel));
    }
    if parse_jellyfin_uuid(channel_id).is_err() {
        return Ok(None);
    }
    let total = service
        .channel_count(&LiveTvChannelQuery::default())
        .await?;
    if total == 0 {
        return Ok(None);
    }
    let page = service
        .channel_page(LiveTvChannelQuery {
            start_index: 0,
            limit: Some(total.min(LIVE_TV_XTREAM_MAX_IMPORT_LIMIT)),
            search_term: None,
            tuner_ids: Vec::new(),
            category_ids: Vec::new(),
        })
        .await?;
    Ok(page.items.into_iter().find(|record| {
        jellyfin_id_matches(&live_tv_channel_public_id(&record.channel_id), channel_id)
            || jellyfin_id_matches(
                &live_tv_playback_channel_public_id(&record.channel_id),
                channel_id,
            )
    }))
}

async fn live_tv_channel_records_by_any_ids(
    db: &Database,
    channel_ids: &[String],
) -> Result<Vec<LiveTvChannelRecord>, ApiError> {
    let requested = channel_ids
        .iter()
        .map(|channel_id| channel_id.trim())
        .filter(|channel_id| !channel_id.is_empty() && !channel_id.eq_ignore_ascii_case("null"))
        .collect::<Vec<_>>();
    if requested.is_empty() {
        return Ok(Vec::new());
    }

    // Android's guide requests programmes for up to 500 channel UUIDs at
    // once. Resolving each UUID through `live_tv_channel_record_by_any_id`
    // would fetch and scan the complete catalogue once per channel. Build one
    // bounded catalogue snapshot and an O(1) lookup index instead.
    let service = LiveTvService::new(db);
    let total = service
        .channel_count(&LiveTvChannelQuery::default())
        .await?;
    if total == 0 {
        return Ok(Vec::new());
    }
    let page = service
        .channel_page(LiveTvChannelQuery {
            start_index: 0,
            limit: Some(total.min(LIVE_TV_XTREAM_MAX_IMPORT_LIMIT)),
            search_term: None,
            tuner_ids: Vec::new(),
            category_ids: Vec::new(),
        })
        .await?;
    let mut index = HashMap::<String, usize>::with_capacity(page.items.len() * 3);
    for (position, record) in page.items.iter().enumerate() {
        let public_id = live_tv_channel_public_id(&record.channel_id);
        for id in [
            record.channel_id.as_str(),
            record.remote_id.as_str(),
            public_id.as_str(),
        ] {
            index.insert(live_tv_lookup_id(id), position);
        }
    }

    Ok(requested
        .into_iter()
        .filter_map(|channel_id| index.get(&live_tv_lookup_id(channel_id)).copied())
        .map(|position| page.items[position].clone())
        .collect())
}

fn live_tv_lookup_id(value: &str) -> String {
    parse_jellyfin_uuid(value.trim()).map_or_else(
        |_| value.trim().to_ascii_lowercase(),
        |id| id.simple().to_string(),
    )
}

async fn live_tv_channel_json_by_id(
    db: &Database,
    channel_id: &str,
) -> Result<Option<serde_json::Value>, ApiError> {
    let server_id = db.server_state().await?.server_id.to_string();
    Ok(live_tv_channel_record_by_any_id(db, channel_id)
        .await?
        .map(|record| live_tv_channel_record_to_json(&record, &server_id)))
}

async fn live_tv_playback_channel_json_by_id(
    db: &Database,
    channel_id: &str,
) -> Result<Option<serde_json::Value>, ApiError> {
    if parse_jellyfin_uuid(channel_id).is_err() {
        return Ok(None);
    }
    let server_id = db.server_state().await?.server_id.to_string();
    Ok(live_tv_channel_record_by_any_id(db, channel_id)
        .await?
        .filter(|record| {
            jellyfin_id_matches(
                &live_tv_playback_channel_public_id(&record.channel_id),
                channel_id,
            )
        })
        .map(|record| live_tv_channel_record_to_json(&record, &server_id)))
}

async fn live_tv_channel_json_for_playable_item(
    db: &Database,
    item_id: &str,
) -> Result<Option<serde_json::Value>, ApiError> {
    if let Some(channel) = live_tv_channel_json_by_id(db, item_id).await? {
        return Ok(Some(channel));
    }
    if let Some(program) = live_tv_program_by_id(db, item_id).await?
        && let Some(channel_id) = json_string_field(&program, "ChannelId")
    {
        return live_tv_channel_json_by_id(db, &channel_id).await;
    }
    Ok(None)
}

async fn live_tv_hdhomerun_channels_from_payload(
    payload: &mut serde_json::Value,
) -> Option<Vec<serde_json::Value>> {
    let base_url = payload
        .get("Url")
        .and_then(serde_json::Value::as_str)
        .map(|url| {
            let url = if url.starts_with("http://") || url.starts_with("https://") {
                url.to_string()
            } else {
                format!("http://{url}")
            };
            url.trim_end_matches('/').to_string()
        })?;

    let discover_url = format!("{base_url}/discover.json");
    let (discover_status, discover_body) = fetch_bounded_validated_live_tv_get(
        &discover_url,
        LIVE_TV_REMOTE_CONTROL_TIMEOUT,
        LIVE_TV_REMOTE_CONTROL_RESPONSE_LIMIT_BYTES,
    )
    .await
    .ok()?;
    if !discover_status.is_success() {
        return None;
    }
    let discover: serde_json::Value = serde_json::from_slice(&discover_body).ok()?;

    if let Some(device_id) = discover.get("DeviceID").and_then(serde_json::Value::as_str) {
        payload["DeviceId"] = serde_json::json!(device_id);
    }
    if let Some(friendly_name) = discover
        .get("FriendlyName")
        .and_then(serde_json::Value::as_str)
    {
        payload["FriendlyName"] = serde_json::json!(friendly_name);
    }
    if let Some(tuner_count) = discover
        .get("TunerCount")
        .and_then(serde_json::Value::as_u64)
    {
        payload["TunerCount"] = serde_json::json!(tuner_count);
    }

    let discover_url_parsed = reqwest::Url::parse(&discover_url).ok()?;
    let lineup_url = match discover
        .get("LineupURL")
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .filter(|url| !url.is_empty())
    {
        Some(lineup_url) => reqwest::Url::parse(lineup_url)
            .or_else(|_| discover_url_parsed.join(lineup_url))
            .ok()?
            .to_string(),
        None => format!("{base_url}/lineup.json"),
    };
    let (lineup_status, lineup_body) = fetch_bounded_validated_live_tv_get(
        &lineup_url,
        LIVE_TV_REMOTE_CONTROL_TIMEOUT,
        LIVE_TV_REMOTE_CONTROL_RESPONSE_LIMIT_BYTES,
    )
    .await
    .ok()?;
    if !lineup_status.is_success() {
        return None;
    }
    let lineup: Vec<serde_json::Value> = live_tv_array_within_limit(
        serde_json::from_slice(&lineup_body).ok()?,
        LIVE_TV_PROVIDER_CATALOG_MAX_CHANNELS,
    )?;

    let channels = parse_live_tv_hdhomerun_channels(&lineup);
    (!channels.is_empty()).then_some(channels)
}

async fn live_tv_hdhomerun_tuner_info_from_base_url(
    base_url: &str,
    deadline: tokio::time::Instant,
) -> Option<serde_json::Value> {
    let base_url = if base_url.starts_with("http://") || base_url.starts_with("https://") {
        base_url.to_string()
    } else {
        format!("http://{base_url}")
    }
    .trim_end_matches('/')
    .to_string();

    let discover_url = format!("{base_url}/discover.json");
    let remaining = deadline.checked_duration_since(tokio::time::Instant::now())?;
    let (status, body) = fetch_bounded_validated_live_tv_get(
        &discover_url,
        remaining,
        LIVE_TV_REMOTE_CONTROL_RESPONSE_LIMIT_BYTES,
    )
    .await
    .ok()?;
    let discover: serde_json::Value = if status == reqwest::StatusCode::NOT_FOUND {
        serde_json::json!({ "ModelNumber": "HDHR" })
    } else {
        if !status.is_success() {
            return None;
        }
        serde_json::from_slice(&body).ok()?
    };

    let device_id = json_string_field(&discover, "DeviceID").unwrap_or_default();
    let friendly_name = json_string_field(&discover, "FriendlyName").unwrap_or_default();
    let tuner_count = discover
        .get("TunerCount")
        .and_then(serde_json::Value::as_u64)
        .unwrap_or_default();
    let name = if friendly_name.is_empty() {
        base_url.clone()
    } else {
        friendly_name.clone()
    };

    let mut tuner = serde_json::json!({
        "Id": null,
        "Name": name,
        "Type": "hdhomerun",
        "Url": base_url,
        "DeviceId": device_id,
        "FriendlyName": friendly_name,
        "TunerCount": tuner_count,
        "ImportFavoritesOnly": false,
        "AllowHWTranscoding": true,
        "AllowFmp4TranscodingContainer": false,
        "AllowStreamSharing": true,
        "FallbackMaxStreamingBitrate": 30000000,
        "EnableStreamLooping": false,
        "Source": null,
        "UserAgent": null,
        "IgnoreDts": true,
        "ReadAtNativeFramerate": false,
        "IsConfigured": false
    });
    for key in [
        "ModelNumber",
        "FirmwareName",
        "FirmwareVersion",
        "BaseURL",
        "LineupURL",
    ] {
        if let Some(value) = discover.get(key) {
            tuner[key] = value.clone();
        }
    }
    Some(tuner)
}

async fn live_tv_discover_hdhomerun_tuners_udp() -> Vec<serde_json::Value> {
    let socket = match StdUdpSocket::bind(SocketAddrV4::new(Ipv4Addr::UNSPECIFIED, 0)) {
        Ok(socket) => socket,
        Err(error) => {
            tracing::warn!("failed to bind HDHomeRun discovery UDP socket: {error}");
            return Vec::new();
        }
    };
    if let Err(error) = socket.set_broadcast(true) {
        tracing::warn!("failed to enable HDHomeRun discovery broadcast: {error}");
        return Vec::new();
    }
    if let Err(error) = socket.set_nonblocking(true) {
        tracing::warn!("failed to configure HDHomeRun discovery socket nonblocking: {error}");
        return Vec::new();
    }
    let socket = match tokio::net::UdpSocket::from_std(socket) {
        Ok(socket) => socket,
        Err(error) => {
            tracing::warn!("failed to create Tokio HDHomeRun discovery socket: {error}");
            return Vec::new();
        }
    };
    live_tv_discover_hdhomerun_tuners_with_socket(
        socket,
        SocketAddr::V4(SocketAddrV4::new(
            Ipv4Addr::BROADCAST,
            HDHOMERUN_DISCOVERY_PORT,
        )),
        StdDuration::from_millis(HDHOMERUN_DISCOVERY_DURATION_MS),
        None,
    )
    .await
}

async fn live_tv_discover_hdhomerun_tuners_with_socket(
    socket: tokio::net::UdpSocket,
    discovery_target: SocketAddr,
    discovery_duration: StdDuration,
    base_url_override: Option<String>,
) -> Vec<serde_json::Value> {
    let mut discovered = Vec::new();
    let mut seen = HashSet::<String>::new();
    if let Err(error) = socket
        .send_to(&HDHOMERUN_DISCOVERY_MESSAGE, discovery_target)
        .await
    {
        tracing::warn!("failed to send HDHomeRun discovery packet: {error}");
        return discovered;
    }

    let deadline = tokio::time::Instant::now() + discovery_duration;
    let mut buffer = [0u8; 8192];
    while let Some(remaining) = deadline.checked_duration_since(tokio::time::Instant::now()) {
        match tokio::time::timeout(remaining, socket.recv_from(&mut buffer)).await {
            Ok(Ok((received, remote))) => {
                if received <= 13 || buffer[1] != 3 {
                    continue;
                }
                let base_url = base_url_override
                    .clone()
                    .unwrap_or_else(|| format!("http://{}", remote.ip()));
                let Some(mut tuner) =
                    live_tv_hdhomerun_tuner_info_from_base_url(&base_url, deadline).await
                else {
                    continue;
                };
                let dedupe_key = json_string_field(&tuner, "DeviceId")
                    .filter(|id| !id.is_empty())
                    .or_else(|| json_string_field(&tuner, "Url"))
                    .unwrap_or_else(|| base_url.clone())
                    .to_ascii_lowercase();
                if seen.insert(dedupe_key) {
                    tuner["IsConfigured"] = serde_json::json!(false);
                    discovered.push(tuner);
                }
            }
            Ok(Err(error)) => {
                tracing::warn!("failed to receive HDHomeRun discovery reply: {error}");
                break;
            }
            Err(_) => break,
        }
    }
    discovered
}

fn live_tv_channel_is_legacy_hdhomerun_path(path: &FsPath) -> bool {
    path.to_string_lossy()
        .to_ascii_lowercase()
        .starts_with("hdhomerun")
}

fn parse_legacy_hdhomerun_channel_commands(url: &str) -> Vec<(String, String)> {
    let lower = url.to_ascii_lowercase();
    let Some(start) = lower.find("/ch") else {
        return Vec::new();
    };
    let mut rest = url[start + 3..].chars().peekable();
    let mut channel = String::new();
    while let Some(ch) = rest.peek().copied() {
        if ch.is_ascii_digit() {
            channel.push(ch);
            rest.next();
        } else {
            break;
        }
    }
    if channel.is_empty() {
        return Vec::new();
    }

    let mut commands = vec![("channel".to_string(), channel)];
    if rest.peek() == Some(&'-') {
        rest.next();
        let mut program = String::new();
        while let Some(ch) = rest.peek().copied() {
            if ch.is_ascii_digit() {
                program.push(ch);
                rest.next();
            } else {
                break;
            }
        }
        if !program.is_empty() {
            commands.push(("program".to_string(), program));
        }
    }
    commands
}

fn hdhomerun_crc32(bytes: &[u8]) -> u32 {
    let mut crc = 0xffff_ffffu32;
    for byte in bytes {
        let mut entry = (crc ^ u32::from(*byte)) & 0xff;
        for _ in 0..8 {
            if entry & 1 == 1 {
                entry = (entry >> 1) ^ 0xedb8_8320;
            } else {
                entry >>= 1;
            }
        }
        crc = (crc >> 8) ^ entry;
    }
    !crc
}

fn hdhomerun_push_null_terminated_string(
    packet: &mut Vec<u8>,
    value: &str,
) -> Result<(), ApiError> {
    let value_bytes = value.as_bytes();
    let len = value_bytes.len() + 1;
    if len > u8::MAX as usize {
        return Err(ApiError::bad_request(
            "HDHomeRun control value is too long for legacy packet encoding",
        ));
    }
    packet.push(len as u8);
    packet.extend_from_slice(value_bytes);
    packet.push(0);
    Ok(())
}

fn hdhomerun_finish_packet(packet: &mut Vec<u8>) {
    let payload_len = (packet.len() - 4) as u16;
    packet[2..4].copy_from_slice(&payload_len.to_be_bytes());
    let crc = hdhomerun_crc32(packet);
    packet.extend_from_slice(&crc.to_le_bytes());
}

fn hdhomerun_write_get_message(tuner: usize, name: &str) -> Result<Vec<u8>, ApiError> {
    let mut packet = Vec::with_capacity(64);
    packet.extend_from_slice(&HDHOMERUN_LEGACY_GETSET_REQUEST.to_be_bytes());
    packet.extend_from_slice(&0u16.to_be_bytes());
    packet.push(HDHOMERUN_LEGACY_GETSET_NAME);
    hdhomerun_push_null_terminated_string(&mut packet, &format!("/tuner{tuner}/{name}"))?;
    hdhomerun_finish_packet(&mut packet);
    Ok(packet)
}

fn hdhomerun_write_set_message(
    tuner: usize,
    name: &str,
    value: &str,
    lockkey: Option<u32>,
) -> Result<Vec<u8>, ApiError> {
    let mut packet = Vec::with_capacity(96);
    packet.extend_from_slice(&HDHOMERUN_LEGACY_GETSET_REQUEST.to_be_bytes());
    packet.extend_from_slice(&0u16.to_be_bytes());
    packet.push(HDHOMERUN_LEGACY_GETSET_NAME);
    hdhomerun_push_null_terminated_string(&mut packet, &format!("/tuner{tuner}/{name}"))?;
    packet.push(HDHOMERUN_LEGACY_GETSET_VALUE);
    hdhomerun_push_null_terminated_string(&mut packet, value)?;
    if let Some(lockkey) = lockkey {
        packet.push(HDHOMERUN_LEGACY_GETSET_LOCKKEY);
        packet.push(4);
        packet.extend_from_slice(&lockkey.to_be_bytes());
    }
    hdhomerun_finish_packet(&mut packet);
    Ok(packet)
}

#[cfg(test)]
fn hdhomerun_write_getset_reply(name: &str, value: &str) -> Result<Vec<u8>, ApiError> {
    let mut packet = Vec::with_capacity(96);
    packet.extend_from_slice(&HDHOMERUN_LEGACY_GETSET_REPLY.to_be_bytes());
    packet.extend_from_slice(&0u16.to_be_bytes());
    packet.push(HDHOMERUN_LEGACY_GETSET_NAME);
    hdhomerun_push_null_terminated_string(&mut packet, name)?;
    packet.push(HDHOMERUN_LEGACY_GETSET_VALUE);
    hdhomerun_push_null_terminated_string(&mut packet, value)?;
    hdhomerun_finish_packet(&mut packet);
    Ok(packet)
}

fn hdhomerun_try_get_return_value(buffer: &[u8]) -> Option<&[u8]> {
    if buffer.len() < 8 {
        return None;
    }
    let expected_crc = u32::from_le_bytes(buffer[buffer.len() - 4..].try_into().ok()?);
    if expected_crc != hdhomerun_crc32(&buffer[..buffer.len() - 4]) {
        return None;
    }
    if u16::from_be_bytes(buffer[0..2].try_into().ok()?) != HDHOMERUN_LEGACY_GETSET_REPLY {
        return None;
    }
    let msg_len = u16::from_be_bytes(buffer[2..4].try_into().ok()?) as usize;
    if buffer.len() != 4 + msg_len + 4 {
        return None;
    }

    let mut offset = 4;
    if buffer.get(offset).copied()? != HDHOMERUN_LEGACY_GETSET_NAME {
        return None;
    }
    offset += 1;
    let name_len = *buffer.get(offset)? as usize;
    offset += 1 + name_len;
    if buffer.get(offset).copied()? != HDHOMERUN_LEGACY_GETSET_VALUE {
        return None;
    }
    offset += 1;
    let value_len = *buffer.get(offset)? as usize;
    offset += 1;
    if value_len == 0 || offset + value_len > buffer.len().saturating_sub(4) {
        return None;
    }
    Some(&buffer[offset..offset + value_len - 1])
}

async fn hdhomerun_send_control_packet(
    stream: &mut tokio::net::TcpStream,
    packet: Vec<u8>,
) -> Result<Vec<u8>, ApiError> {
    tokio::time::timeout(HDHOMERUN_LEGACY_CONTROL_TIMEOUT, stream.write_all(&packet))
        .await
        .map_err(|_| ApiError::internal("HDHomeRun control write timed out"))?
        .map_err(|error| ApiError::internal(format!("HDHomeRun control write failed: {error}")))?;

    let mut header = [0u8; 4];
    tokio::time::timeout(
        HDHOMERUN_LEGACY_CONTROL_TIMEOUT,
        stream.read_exact(&mut header),
    )
    .await
    .map_err(|_| ApiError::internal("HDHomeRun control read timed out"))?
    .map_err(|error| ApiError::internal(format!("HDHomeRun control read failed: {error}")))?;

    let msg_len = u16::from_be_bytes([header[2], header[3]]) as usize;
    let mut rest = vec![0u8; msg_len + 4];
    tokio::time::timeout(
        HDHOMERUN_LEGACY_CONTROL_TIMEOUT,
        stream.read_exact(&mut rest),
    )
    .await
    .map_err(|_| ApiError::internal("HDHomeRun control read timed out"))?
    .map_err(|error| ApiError::internal(format!("HDHomeRun control read failed: {error}")))?;

    let mut response = header.to_vec();
    response.extend_from_slice(&rest);
    Ok(response)
}

async fn hdhomerun_get_control_value(
    stream: &mut tokio::net::TcpStream,
    tuner: usize,
    name: &str,
) -> Result<Option<String>, ApiError> {
    let packet = hdhomerun_write_get_message(tuner, name)?;
    let response = hdhomerun_send_control_packet(stream, packet).await?;
    Ok(hdhomerun_try_get_return_value(&response)
        .map(|value| String::from_utf8_lossy(value).to_string()))
}

async fn hdhomerun_set_control_value(
    stream: &mut tokio::net::TcpStream,
    tuner: usize,
    name: &str,
    value: &str,
    lockkey: Option<u32>,
) -> Result<bool, ApiError> {
    let packet = hdhomerun_write_set_message(tuner, name, value, lockkey)?;
    let response = hdhomerun_send_control_packet(stream, packet).await?;
    Ok(hdhomerun_try_get_return_value(&response).is_some())
}

struct LegacyHdhomerunControl {
    stream: tokio::net::TcpStream,
    active_tuner: usize,
    lockkey: u32,
}

impl LegacyHdhomerunControl {
    async fn stop(&mut self) {
        let _ = hdhomerun_set_control_value(
            &mut self.stream,
            self.active_tuner,
            "target",
            "none",
            Some(self.lockkey),
        )
        .await;
        let _ = hdhomerun_set_control_value(
            &mut self.stream,
            self.active_tuner,
            "lockkey",
            "none",
            Some(self.lockkey),
        )
        .await;
    }
}

async fn legacy_hdhomerun_release_tuner(
    stream: &mut tokio::net::TcpStream,
    tuner: usize,
    lockkey: u32,
) {
    let _ = hdhomerun_set_control_value(stream, tuner, "target", "none", Some(lockkey)).await;
    let _ = hdhomerun_set_control_value(stream, tuner, "lockkey", "none", Some(lockkey)).await;
}

fn ipv4_for_hdhomerun_target(addr: SocketAddr) -> Result<Ipv4Addr, ApiError> {
    match addr.ip() {
        IpAddr::V4(ip) => Ok(ip),
        IpAddr::V6(ip) => ip.to_ipv4_mapped().ok_or_else(|| {
            ApiError::internal("HDHomeRun legacy UDP streaming requires an IPv4 local address")
        }),
    }
}

async fn open_legacy_hdhomerun_udp_source(
    channel_url: &str,
    control_addr: SocketAddr,
    num_tuners: usize,
) -> Result<(tokio::net::UdpSocket, LegacyHdhomerunControl), ApiError> {
    let udp_socket = tokio::net::UdpSocket::bind(SocketAddrV4::new(Ipv4Addr::UNSPECIFIED, 0))
        .await
        .map_err(|error| {
            ApiError::internal(format!("failed to bind HDHomeRun UDP socket: {error}"))
        })?;
    let local_port = udp_socket
        .local_addr()
        .map_err(|error| ApiError::internal(format!("failed to read HDHomeRun UDP port: {error}")))?
        .port();

    let mut stream = tokio::time::timeout(
        HDHOMERUN_LEGACY_CONTROL_TIMEOUT,
        tokio::net::TcpStream::connect(control_addr),
    )
    .await
    .map_err(|_| ApiError::internal("HDHomeRun legacy control connect timed out"))?
    .map_err(|error| {
        ApiError::internal(format!("HDHomeRun legacy control connect failed: {error}"))
    })?;
    let local_ip = ipv4_for_hdhomerun_target(stream.local_addr().map_err(|error| {
        ApiError::internal(format!("failed to read HDHomeRun local address: {error}"))
    })?)?;

    let mut lockkey_bytes = [0u8; 4];
    OsRng.fill_bytes(&mut lockkey_bytes);
    let lockkey = u32::from_be_bytes(lockkey_bytes);
    let commands = parse_legacy_hdhomerun_channel_commands(channel_url);
    let target = format!("rtp://{local_ip}:{local_port}");

    for tuner in 0..num_tuners.max(1) {
        let Some(lockkey_value) =
            hdhomerun_get_control_value(&mut stream, tuner, "lockkey").await?
        else {
            continue;
        };
        if !lockkey_value.eq_ignore_ascii_case("none") {
            continue;
        }
        if !hdhomerun_set_control_value(&mut stream, tuner, "lockkey", &lockkey.to_string(), None)
            .await?
        {
            continue;
        }

        let mut commands_ok = true;
        for (name, value) in &commands {
            if !hdhomerun_set_control_value(&mut stream, tuner, name, value, Some(lockkey)).await? {
                commands_ok = false;
                break;
            }
        }
        if !commands_ok {
            legacy_hdhomerun_release_tuner(&mut stream, tuner, lockkey).await;
            continue;
        }

        if hdhomerun_set_control_value(&mut stream, tuner, "target", &target, Some(lockkey)).await?
        {
            return Ok((
                udp_socket,
                LegacyHdhomerunControl {
                    stream,
                    active_tuner: tuner,
                    lockkey,
                },
            ));
        }
        legacy_hdhomerun_release_tuner(&mut stream, tuner, lockkey).await;
    }

    Err(ApiError::conflict("No HDHomeRun legacy tuners available"))
}

fn live_tv_u64_field(value: &serde_json::Value, key: &str) -> Option<u64> {
    match value.get(key)? {
        serde_json::Value::Number(number) => number.as_u64(),
        serde_json::Value::String(value) => value.parse::<u64>().ok(),
        _ => None,
    }
}

fn legacy_hdhomerun_scan_tuner_count(tuner_host: &serde_json::Value) -> usize {
    let count = live_tv_u64_field(tuner_host, "TunerCount")
        .filter(|count| *count > 0)
        .unwrap_or(HDHOMERUN_LEGACY_DEFAULT_TUNERS as u64);
    usize::try_from(count.min(32)).unwrap_or(HDHOMERUN_LEGACY_DEFAULT_TUNERS)
}

fn legacy_hdhomerun_control_port(tuner_host: &serde_json::Value) -> u16 {
    live_tv_u64_field(tuner_host, "LegacyControlPort")
        .or_else(|| live_tv_u64_field(tuner_host, "ControlPort"))
        .and_then(|port| u16::try_from(port).ok())
        .filter(|port| *port > 0)
        .unwrap_or(HDHOMERUN_DISCOVERY_PORT)
}

struct LegacyHdhomerunStreamParams {
    tuner_host_url: String,
    control_port: u16,
    num_tuners: usize,
}

async fn legacy_hdhomerun_stream_params_for_host(
    db: &Database,
    tuner_host_id: Option<&str>,
) -> Result<LegacyHdhomerunStreamParams, ApiError> {
    let Some(tuner_host_id) = tuner_host_id else {
        return Err(ApiError::not_found("HDHomeRun tuner host not found"));
    };
    let tuner_host = live_tv_tuner_host_by_id(db, tuner_host_id)
        .await
        .ok_or_else(|| ApiError::not_found("HDHomeRun tuner host not found"))?;
    let tuner_host_url = json_string_field(&tuner_host, "Url")
        .ok_or_else(|| ApiError::bad_request("HDHomeRun tuner host URL is required"))?;
    Ok(LegacyHdhomerunStreamParams {
        tuner_host_url,
        control_port: legacy_hdhomerun_control_port(&tuner_host),
        num_tuners: legacy_hdhomerun_scan_tuner_count(&tuner_host),
    })
}

async fn legacy_hdhomerun_control_addr(
    tuner_url: &str,
    control_port: u16,
) -> Result<SocketAddr, ApiError> {
    if tuner_url.len() > 16 * 1024 || tuner_url.chars().any(char::is_control) {
        return Err(ApiError::bad_request("Invalid HDHomeRun tuner URL"));
    }
    let normalized_url = if tuner_url.contains("://") {
        tuner_url.to_owned()
    } else {
        format!("http://{tuner_url}")
    };
    let url = reqwest::Url::parse(&normalized_url)
        .map_err(|_| ApiError::bad_request("Invalid HDHomeRun tuner URL"))?;
    if !matches!(url.scheme(), "http" | "https")
        || !url.username().is_empty()
        || url.password().is_some()
        || url.query().is_some()
        || url.fragment().is_some()
    {
        return Err(ApiError::bad_request("Invalid HDHomeRun tuner URL"));
    }
    let host = url
        .host_str()
        .ok_or_else(|| ApiError::bad_request("HDHomeRun tuner URL is missing a host"))?;
    let allow_private = cfg!(test) || remote_private_provider_networks_allowed();
    let resolved = tokio::time::timeout(
        LIVE_TV_REMOTE_CONTROL_TIMEOUT,
        tokio::net::lookup_host((host, control_port)),
    )
    .await
    .map_err(|_| ApiError::service_unavailable("HDHomeRun host resolution timed out"))?
    .map_err(|_| ApiError::service_unavailable("HDHomeRun host resolution failed"))?;
    let mut addrs = resolved
        .filter(|address| remote_provider_address_allowed(address.ip(), allow_private))
        .collect::<Vec<_>>();
    addrs.sort_unstable_by_key(|address| (!address.is_ipv4(), address.ip(), address.port()));
    addrs.dedup();
    addrs
        .into_iter()
        .next()
        .ok_or_else(|| ApiError::forbidden("HDHomeRun tuner address is not allowed"))
}

async fn live_tv_xmltv_programs_from_payload(
    payload: &serde_json::Value,
) -> Option<Vec<serde_json::Value>> {
    let contents = live_tv_config_source_contents(payload).await?;
    let programs = live_tv_array_within_limit(
        parse_live_tv_xmltv_programs(&contents),
        LIVE_TV_CONFIG_MAX_PROGRAMS,
    )?;
    (!programs.is_empty()).then_some(programs)
}

fn live_tv_local_config_path(payload: &serde_json::Value) -> Option<PathBuf> {
    json_string_field(payload, "Path")
        .or_else(|| json_string_field(payload, "Url"))
        .map(PathBuf::from)
        .filter(|path| {
            !path.as_os_str().is_empty() && path.is_absolute() && path.extension().is_some()
        })
}

fn live_tv_array_within_limit<Value>(values: Vec<Value>, max_items: usize) -> Option<Vec<Value>> {
    (values.len() <= max_items).then_some(values)
}

fn read_bounded_live_tv_config_file(path: &FsPath, max_bytes: usize) -> Option<String> {
    use std::io::Read as _;
    #[cfg(unix)]
    use std::os::unix::fs::OpenOptionsExt as _;

    let metadata = fs::symlink_metadata(path).ok()?;
    if metadata.file_type().is_symlink() || !metadata.is_file() || metadata.len() > max_bytes as u64
    {
        return None;
    }
    let mut options = fs::OpenOptions::new();
    options.read(true);
    #[cfg(unix)]
    options.custom_flags(libc::O_NOFOLLOW);
    let file = options.open(path).ok()?;
    let metadata = file.metadata().ok()?;
    if !metadata.is_file() || metadata.len() > max_bytes as u64 {
        return None;
    }
    let mut bytes = Vec::new();
    let mut limited = file.take(max_bytes.saturating_add(1) as u64);
    limited.read_to_end(&mut bytes).ok()?;
    if bytes.len() > max_bytes {
        return None;
    }
    String::from_utf8(bytes).ok()
}

async fn read_bounded_live_tv_config_file_async(path: &FsPath, max_bytes: usize) -> Option<String> {
    let metadata = tokio::fs::symlink_metadata(path).await.ok()?;
    if metadata.file_type().is_symlink() || !metadata.is_file() || metadata.len() > max_bytes as u64
    {
        return None;
    }
    let mut options = tokio::fs::OpenOptions::new();
    options.read(true);
    #[cfg(unix)]
    options.custom_flags(libc::O_NOFOLLOW);
    let file = options.open(path).await.ok()?;
    let metadata = file.metadata().await.ok()?;
    if !metadata.is_file() || metadata.len() > max_bytes as u64 {
        return None;
    }
    let mut bytes = Vec::new();
    let mut limited = file.take(max_bytes.saturating_add(1) as u64);
    limited.read_to_end(&mut bytes).await.ok()?;
    if bytes.len() > max_bytes {
        return None;
    }
    String::from_utf8(bytes).ok()
}

async fn live_tv_config_source_contents(payload: &serde_json::Value) -> Option<String> {
    if let Some(url) = json_string_field(payload, "Url")
        .map(|url| url.trim().to_string())
        .filter(|url| url.starts_with("http://") || url.starts_with("https://"))
    {
        let (status, body) = fetch_bounded_validated_live_tv_get(
            &url,
            LIVE_TV_CONFIG_SOURCE_TIMEOUT,
            LIVE_TV_CONFIG_SOURCE_LIMIT_BYTES,
        )
        .await
        .ok()?;
        if !status.is_success() {
            return None;
        }
        return Some(String::from_utf8_lossy(&body).into_owned());
    }
    let path = live_tv_local_config_path(payload)?;
    read_bounded_live_tv_config_file_async(&path, LIVE_TV_CONFIG_SOURCE_LIMIT_BYTES).await
}

fn live_tv_channel_public_id(channel_id: &str) -> String {
    stable_jellyfin_uuid("LiveTvChannel", channel_id)
}

fn live_tv_playback_channel_public_id(channel_id: &str) -> String {
    live_tv_channel_public_id(channel_id)
}

fn live_tv_fallback_program_public_id(channel_id: &str) -> String {
    stable_jellyfin_uuid("LiveTvFallbackProgram", channel_id)
}

fn stable_jellyfin_uuid(kind: &str, value: &str) -> String {
    let hex = stable_entity_id(kind, value);
    Uuid::parse_str(&hex)
        .expect("stable entity IDs are valid UUID hex")
        .to_string()
}

async fn live_tv_tuner_host_types(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
) -> Result<Json<Vec<serde_json::Value>>, ApiError> {
    require_user(&state.db, &headers, query.api_key.as_deref()).await?;
    let mut types = vec![
        serde_json::json!({ "Id": "hdhomerun", "Name": "HDHomeRun" }),
        serde_json::json!({ "Id": "m3u", "Name": "M3U Tuner" }),
    ];
    for provider_type in live_tv_provider_types().await {
        if provider_type.eq_ignore_ascii_case("hdhomerun")
            || provider_type.eq_ignore_ascii_case("m3u")
        {
            continue;
        }
        types.push(serde_json::json!({
            "Id": provider_type,
            "Name": format!("{} Tuner", provider_type),
        }));
    }
    for plugin in state.db.installed_plugins_json().await? {
        if !plugin_is_active_channel_provider(&plugin) {
            continue;
        }
        let Some(plugin_id) = json_string_field(&plugin, "Id") else {
            continue;
        };
        let plugin_name = json_string_field(&plugin, "Name").unwrap_or_else(|| plugin_id.clone());
        types.push(serde_json::json!({
            "Id": format!("plugin:{plugin_id}"),
            "Name": format!("{plugin_name} (Plugin)"),
            "PluginId": plugin_id,
            "Type": "plugin"
        }));
    }
    Ok(Json(types))
}

/// Test Xtream credentials and return available categories.
/// POST /LiveTv/Xtream/Test
/// Body: { "Url": "...", "Username": "...", "Password": "..." }
fn xtream_test_categories_url(
    base_url: &str,
    username: &str,
    password: &str,
    action: &str,
) -> Result<String, ApiError> {
    let mut url = reqwest::Url::parse(base_url)
        .map_err(|_| ApiError::bad_request("Invalid Xtream server URL"))?;
    url.set_path("player_api.php");
    url.set_query(None);
    url.query_pairs_mut()
        .append_pair("username", username)
        .append_pair("password", password)
        .append_pair("action", action);
    Ok(url.to_string())
}

async fn fetch_xtream_test_categories(url: &str) -> Result<Vec<serde_json::Value>, ApiError> {
    let (status, body) = fetch_bounded_validated_live_tv_get(
        url,
        LIVE_TV_REMOTE_CONTROL_TIMEOUT,
        LIVE_TV_REMOTE_CONTROL_RESPONSE_LIMIT_BYTES,
    )
    .await
    .map_err(|error| match error {
        LiveTvRemoteFetchError::BodyTooLarge => {
            ApiError::bad_request("Xtream category response is too large")
        }
        LiveTvRemoteFetchError::Validation(_) => {
            ApiError::bad_request("Xtream server URL is not allowed")
        }
        LiveTvRemoteFetchError::Request { .. } => {
            ApiError::bad_request("Xtream server connection failed")
        }
    })?;
    if !status.is_success() {
        return Err(ApiError::bad_request(format!(
            "Xtream server returned HTTP {status}"
        )));
    }
    let categories: Vec<serde_json::Value> = serde_json::from_slice(&body)
        .map_err(|_| ApiError::bad_request("Invalid response from Xtream server"))?;
    live_tv_array_within_limit(categories, LIVE_TV_PROVIDER_CATALOG_MAX_CATEGORIES)
        .ok_or_else(|| ApiError::bad_request("Xtream category response has too many items"))
}

async fn test_xtream_credentials(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    Json(payload): Json<serde_json::Value>,
) -> Result<Json<serde_json::Value>, ApiError> {
    require_admin(&state.db, &headers, query.api_key.as_deref()).await?;
    let url = json_string_field(&payload, "Url")
        .ok_or_else(|| ApiError::bad_request("Url is required"))?;
    let username = json_string_field(&payload, "Username")
        .or_else(|| json_string_field(&payload, "UserName"))
        .ok_or_else(|| ApiError::bad_request("Username is required"))?;
    let password = json_string_field(&payload, "Password")
        .ok_or_else(|| ApiError::bad_request("Password is required"))?;

    let categories_url =
        xtream_test_categories_url(&url, &username, &password, "get_live_categories")?;
    let categories = fetch_xtream_test_categories(&categories_url).await?;
    let vod_url = xtream_test_categories_url(&url, &username, &password, "get_vod_categories")?;
    let vod_categories = fetch_xtream_test_categories(&vod_url)
        .await
        .unwrap_or_default();
    let series_url =
        xtream_test_categories_url(&url, &username, &password, "get_series_categories")?;
    let series_categories = fetch_xtream_test_categories(&series_url)
        .await
        .unwrap_or_default();

    let format_category = |cat: &serde_json::Value| -> serde_json::Value {
        let id = json_string_field(cat, "category_id")
            .or_else(|| live_tv_u64_field(cat, "category_id").map(|v| v.to_string()))
            .unwrap_or_default();
        let name = json_string_field(cat, "category_name")
            .or_else(|| json_string_field(cat, "name"))
            .unwrap_or_else(|| id.clone());
        serde_json::json!({ "Id": id, "Name": name })
    };

    Ok(Json(serde_json::json!({
        "Success": true,
        "LiveCategories": categories.iter().map(format_category).collect::<Vec<_>>(),
        "VodCategories": vod_categories.iter().map(format_category).collect::<Vec<_>>(),
        "SeriesCategories": series_categories.iter().map(format_category).collect::<Vec<_>>(),
    })))
}

async fn add_live_tv_tuner_host(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    Json(mut payload): Json<serde_json::Value>,
) -> Result<Json<serde_json::Value>, ApiError> {
    require_admin(&state.db, &headers, query.api_key.as_deref()).await?;
    if !payload.is_object() {
        return Err(ApiError::bad_request("Tuner host must be an object"));
    }

    let tuner_id = payload
        .get("Id")
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .filter(|id| !id.is_empty())
        .map(ToOwned::to_owned)
        .unwrap_or_else(|| Uuid::new_v4().simple().to_string());
    payload["Id"] = serde_json::json!(tuner_id);

    if let Some(existing) = persisted_live_tv_tuner_configuration(&state.db, &tuner_id).await? {
        inherit_live_tv_tuner_route_fields(&mut payload, &existing)?;
    }

    let tuner_type = payload
        .get("Type")
        .and_then(serde_json::Value::as_str)
        .unwrap_or("")
        .to_ascii_lowercase();
    let plugin_tuner_id = live_tv_plugin_id_from_payload(&payload, &tuner_type);
    if plugin_configuration_contains_tuner_secret_material(&payload)
        && !tuner_type.eq_ignore_ascii_case("xtream")
        && plugin_tuner_id.is_none()
    {
        return Err(ApiError::bad_request(
            "Provider credentials require an xtream or plugin:<id> tuner Type",
        ));
    }
    if plugin_tuner_id.is_some() {
        payload = stage_live_tv_plugin_tuner_credentials(&state.db, payload, &tuner_type).await?;
    }
    // A plugin import lease carries its lifecycle read lock through both the snapshot commit and
    // the final public `livetv` update below. This prevents a concurrent credential rotation or
    // tuner deletion from being overwritten by an import that started with older state.
    let mut provider_import_security_guard = None;
    let mut provider_import_admission_guard = None;
    let mut provider_import_session_guard = None;
    if tuner_type == "hdhomerun" {
        if let Some(channels) = live_tv_hdhomerun_channels_from_payload(&mut payload).await {
            payload["Channels"] = serde_json::json!(channels);
        }
    } else if let Some(import_lease) =
        live_tv_provider_import_from_payload(&state, &payload, &tuner_type).await?
    {
        let LiveTvProviderImportLease {
            import,
            plugin_security_guard,
            plugin_admission_guard,
            plugin_provider_session_guard,
        } = import_lease;
        provider_import_security_guard = plugin_security_guard;
        provider_import_admission_guard = plugin_admission_guard;
        provider_import_session_guard = plugin_provider_session_guard;
        payload = persist_live_tv_provider_import(&state.db, &payload, &import).await?;
        // Warm the channel-logo disk cache in the background.
        spawn_live_tv_logo_precache(state.clone());
        // Check provider's post-import actions (e.g., media sync)
        if let Some(provider) = live_tv_provider_for_type(&tuner_type).await {
            let actions = provider.post_import_actions();
            if actions.trigger_media_sync {
                start_xtream_media_sync_task(state.db.clone(), None).await?;
                payload["MediaSync"] = serde_json::json!("scheduled");
            }
        }
        payload["Channels"] = serde_json::json!([]);
        payload["Categories"] = serde_json::json!([]);
        payload["PersistedChannelCount"] = serde_json::json!(import.channels.len());
        payload["PersistedCategoryCount"] = serde_json::json!(import.categories.len());
        payload["Storage"] = serde_json::json!("postgresql");
    } else if tuner_type == "m3u"
        && payload
            .get("Channels")
            .and_then(serde_json::Value::as_array)
            .is_none_or(|channels| channels.is_empty())
        && let Some(channels) = live_tv_m3u_channels_from_payload(&payload).await
    {
        payload["Channels"] = serde_json::json!(channels);
    }

    let mut config = state
        .db
        .named_configuration("livetv")
        .await?
        .unwrap_or_else(default_live_tv_configuration);
    let mut tuner_hosts = config
        .get("TunerHosts")
        .and_then(serde_json::Value::as_array)
        .cloned()
        .unwrap_or_default();
    if let Some(existing) = tuner_hosts.iter_mut().find(|tuner| {
        tuner.get("Id").and_then(serde_json::Value::as_str)
            == payload.get("Id").and_then(serde_json::Value::as_str)
    }) {
        *existing = payload.clone();
    } else {
        tuner_hosts.push(payload.clone());
    }
    config["TunerHosts"] = serde_json::json!(tuner_hosts);
    state
        .db
        .update_named_configuration("livetv", live_tv_configuration_json(config))
        .await?;
    drop(provider_import_security_guard);
    drop(provider_import_admission_guard);
    drop(provider_import_session_guard);
    // A plugin tuner may also expose the VOD library capability; chain its import after the
    // channel snapshot and public configuration have both committed. The import re-acquires its
    // own lane permit and lifecycle read lock, so it must run after the lease guards above are
    // dropped.
    maybe_refresh_vod_library_for_tuner(&state, &payload);
    Ok(Json(payload))
}

#[derive(Debug, Deserialize)]
struct LiveTvTunerHostQuery {
    #[serde(alias = "Id")]
    id: Option<String>,
    #[serde(alias = "api_key", alias = "ApiKey")]
    api_key: Option<String>,
}

async fn delete_live_tv_tuner_host(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<LiveTvTunerHostQuery>,
) -> Result<StatusCode, ApiError> {
    require_admin(&state.db, &headers, query.api_key.as_deref()).await?;
    let tuner_id = query.id.as_deref().unwrap_or_default();
    let mut config = state
        .db
        .named_configuration("livetv")
        .await?
        .unwrap_or_else(default_live_tv_configuration);
    let plugin_id = config
        .get("TunerHosts")
        .and_then(serde_json::Value::as_array)
        .and_then(|hosts| {
            hosts.iter().find(|tuner| {
                json_string_field(tuner, "Id")
                    .is_some_and(|candidate| candidate.eq_ignore_ascii_case(tuner_id))
            })
        })
        .and_then(|tuner| {
            let tuner_type = json_string_field(tuner, "Type")?;
            live_tv_plugin_id_from_payload(tuner, &tuner_type)
        });
    let _security_guard = if let Some(plugin_id) = plugin_id.as_deref() {
        Some(
            external_plugin_security_slot(plugin_id)
                .await
                .write_owned()
                .await,
        )
    } else {
        None
    };
    let tuner_hosts = config
        .get("TunerHosts")
        .and_then(serde_json::Value::as_array)
        .map(|hosts| {
            hosts
                .iter()
                .filter(|tuner| {
                    tuner.get("Id").and_then(serde_json::Value::as_str) != Some(tuner_id)
                })
                .cloned()
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    config["TunerHosts"] = serde_json::json!(tuner_hosts);
    state
        .db
        .update_named_configuration("livetv", live_tv_configuration_json(config))
        .await?;
    if let Some(plugin_id) = plugin_id {
        stop_external_plugin_host(&plugin_id).await;
    }
    LiveTvService::new(&state.db)
        .delete_tuner_state(tuner_id)
        .await?;
    Ok(StatusCode::NO_CONTENT)
}

