fn live_tv_favorite_filter(query: &LiveTvChannelsQuery) -> Option<bool> {
    query.is_favorite.or_else(|| {
        query
            .filters
            .iter()
            .any(|filter| filter.eq_ignore_ascii_case("IsFavorite"))
            .then_some(true)
    })
}

async fn live_tv_channels(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<LiveTvChannelsQuery>,
) -> Result<Json<serde_json::Value>, ApiError> {
    let service = LiveTvService::new(&state.db);
    let (user, token) = require_user(&state.db, &headers, query.auth.api_key.as_deref()).await?;
    let user_context = jellyrin_plugin_sdk::PluginUserContext {
        user_id: user.id.to_string(),
        device_id: token.device_id,
        is_administrator: user.is_administrator,
    };
    let authorized_tuner_ids = authorized_live_tv_tuner_ids(&state.db, &user_context).await?;
    let favorite_ids = live_tv_favorite_ids(&state.db, user.id).await?;
    let favorite_filter = live_tv_favorite_filter(&query);
    // Cap explicit limits at 500, and apply a sane default page size when the
    // client omits Limit — otherwise a large channel list (thousands of items)
    // is returned and rendered in one shot, which is slow and floods the image
    // endpoint with concurrent logo fetches.
    let limit = query
        .limit
        .map(|limit| limit.min(LIVE_TV_CHANNELS_MAX_LIMIT))
        .unwrap_or(LIVE_TV_CHANNELS_DEFAULT_LIMIT);
    let tuner_id = match query.parent_id.as_deref() {
        Some(parent_id) => live_tv_tuner_view_by_id(&state.db, parent_id)
            .await?
            .map(|view| view.tuner_id),
        None => None,
    };
    let category_ids = live_tv_channel_category_filter(&state.db, &query).await?;
    let requested_start_index = query.start_index.unwrap_or(0);
    let tuner_ids = match (&authorized_tuner_ids, tuner_id.as_ref()) {
        (Some(allowed), Some(requested))
            if !allowed.iter().any(|id| id.eq_ignore_ascii_case(requested)) =>
        {
            return Ok(Json(query_result_with_total(Vec::new(), 0, 0)));
        }
        (Some(allowed), Some(requested)) => allowed
            .iter()
            .find(|id| id.eq_ignore_ascii_case(requested))
            .cloned()
            .into_iter()
            .collect(),
        (Some(allowed), None) if allowed.is_empty() => {
            return Ok(Json(query_result_with_total(Vec::new(), 0, 0)));
        }
        (Some(allowed), None) => allowed.clone(),
        (None, Some(requested)) => vec![requested.clone()],
        (None, None) => Vec::new(),
    };
    let db_query = LiveTvChannelQuery {
        start_index: favorite_filter.map_or(requested_start_index, |_| 0),
        limit: if favorite_filter.is_some() {
            None
        } else {
            Some(limit)
        },
        search_term: query.search_term.clone(),
        tuner_ids,
        category_ids,
    };
    let page = service.channel_page(db_query).await?;
    if page.total_record_count > 0 {
        let server_id = state.db.server_state().await?.server_id.to_string();
        let mut items = page
            .items
            .iter()
            .map(|record| live_tv_channel_record_to_json(record, &server_id))
            .collect::<Vec<_>>();
        for item in &mut items {
            apply_live_tv_favorite_state(item, &favorite_ids);
        }
        if let Some(is_favorite) = favorite_filter {
            items.retain(|item| {
                item.get("UserData")
                    .and_then(|user_data| json_bool_field(user_data, "IsFavorite"))
                    == Some(is_favorite)
            });
            let total = items.len();
            let start_index = requested_start_index.min(total);
            let items = items.into_iter().skip(start_index).take(limit).collect();
            return Ok(Json(query_result_with_total(items, total, start_index)));
        }
        return Ok(Json(query_result_with_total(
            items,
            page.total_record_count,
            page.start_index,
        )));
    }
    let config = state
        .db
        .named_configuration("livetv")
        .await?
        .unwrap_or_else(default_live_tv_configuration);
    let server_id = state.db.server_state().await?.server_id.to_string();
    let mut channels = live_tv_channel_items(&config, &server_id);
    if let Some(allowed) = authorized_tuner_ids.as_ref() {
        channels.retain(|channel| {
            json_string_field(channel, "TunerHostId").is_some_and(|id| {
                allowed
                    .iter()
                    .any(|allowed| allowed.eq_ignore_ascii_case(&id))
            })
        });
    }
    if let Some(tuner_id) = tuner_id.as_deref() {
        channels.retain(|channel| {
            json_string_field(channel, "TunerHostId")
                .is_some_and(|id| id.eq_ignore_ascii_case(tuner_id))
        });
    }
    filter_channel_items_by_search(&mut channels, query.search_term.as_deref());
    filter_channel_items_by_category(&mut channels, &query);
    for channel in &mut channels {
        apply_live_tv_favorite_state(channel, &favorite_ids);
    }
    if let Some(is_favorite) = favorite_filter {
        channels.retain(|channel| {
            channel
                .get("UserData")
                .and_then(|user_data| json_bool_field(user_data, "IsFavorite"))
                == Some(is_favorite)
        });
    }
    let total = channels.len();
    let start_index = query.start_index.unwrap_or(0).min(total);
    let items = channels.into_iter().skip(start_index).take(limit).collect();
    Ok(Json(query_result_with_total(items, total, start_index)))
}

async fn live_tv_channel_category_filter(
    db: &Database,
    query: &LiveTvChannelsQuery,
) -> Result<Vec<String>, ApiError> {
    // Collect every requested category/genre/tag selector (multi-select).
    let requested = query
        .category_id
        .iter()
        .map(String::as_str)
        .chain(query.genre_ids.iter().map(String::as_str))
        .chain(query.genres.iter().map(String::as_str))
        .chain(query.tags.iter().map(String::as_str))
        .map(str::trim)
        .filter(|value| !value.is_empty() && !value.eq_ignore_ascii_case("null"))
        .map(ToOwned::to_owned)
        .collect::<Vec<_>>();
    resolve_live_tv_category_ids(db, &requested).await
}

/// Resolve raw category selectors (category_id / remote_id / name / the FNV
/// "LiveTvGenre" hash that channels expose as GenreItems[].Id) into real stored
/// category ids. Unmatched values are passed through unchanged. Shared by the
/// channels and programs endpoints so both honor the same selectors.
async fn resolve_live_tv_category_ids(
    db: &Database,
    requested: &[String],
) -> Result<Vec<String>, ApiError> {
    let requested = requested
        .iter()
        .map(|value| value.trim())
        .filter(|value| !value.is_empty() && !value.eq_ignore_ascii_case("null"))
        .collect::<Vec<_>>();
    if requested.is_empty() {
        return Ok(Vec::new());
    }
    let categories = LiveTvService::new(db).categories().await?;
    let mut resolved = Vec::new();
    for value in requested {
        let matched = categories.iter().find(|category| {
            value.eq_ignore_ascii_case(&category.category_id)
                || value.eq_ignore_ascii_case(&category.name)
                || value.eq_ignore_ascii_case(&category.remote_id)
                || value.eq_ignore_ascii_case(&stable_entity_id("LiveTvGenre", &category.name))
        });
        let id = matched
            .map(|category| category.category_id.clone())
            .unwrap_or_else(|| value.to_string());
        if !resolved.contains(&id) {
            resolved.push(id);
        }
    }
    Ok(resolved)
}

fn filter_channel_items_by_category(
    channels: &mut Vec<serde_json::Value>,
    query: &LiveTvChannelsQuery,
) {
    let requested = query
        .category_id
        .iter()
        .map(String::as_str)
        .chain(query.genre_ids.iter().map(String::as_str))
        .chain(query.genres.iter().map(String::as_str))
        .chain(query.tags.iter().map(String::as_str))
        .map(str::trim)
        .filter(|value| !value.is_empty() && !value.eq_ignore_ascii_case("null"))
        .map(str::to_ascii_lowercase)
        .collect::<HashSet<_>>();
    if requested.is_empty() {
        return;
    }
    // A channel matches if its CategoryId, any Genre, any Tag, or the FNV
    // "LiveTvGenre" hash of any Genre is in the requested set (so a funnel built
    // from GenreItems[].Id matches here too).
    let matches = |value: &str| -> bool {
        let lower = value.to_ascii_lowercase();
        requested.contains(&lower)
            || requested.contains(&stable_entity_id("LiveTvGenre", value).to_ascii_lowercase())
    };
    channels.retain(|channel| {
        json_string_field(channel, "CategoryId").is_some_and(|value| matches(&value))
            || json_string_list_field(channel, "Genres")
                .unwrap_or_default()
                .iter()
                .any(|value| matches(value))
            || json_string_list_field(channel, "Tags")
                .unwrap_or_default()
                .iter()
                .any(|value| matches(value))
    });
}

async fn live_tv_channel(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    Path(channel_id): Path<String>,
) -> Result<Json<serde_json::Value>, ApiError> {
    let (user, token) = require_user(&state.db, &headers, query.api_key.as_deref()).await?;
    let allowed_tuners = authorized_live_tv_tuner_ids(
        &state.db,
        &jellyrin_plugin_sdk::PluginUserContext {
            user_id: user.id.to_string(),
            device_id: token.device_id,
            is_administrator: user.is_administrator,
        },
    )
    .await?;
    let favorite_ids = live_tv_favorite_ids(&state.db, user.id).await?;
    if let Some(mut channel) = live_tv_channel_json_by_id(&state.db, &channel_id).await? {
        if !live_tv_item_is_visible_to_tuners(&channel, allowed_tuners.as_deref()) {
            return Err(ApiError::not_found("Live TV item not found"));
        }
        apply_live_tv_favorite_state(&mut channel, &favorite_ids);
        return Ok(Json(channel));
    }
    let config = state
        .db
        .named_configuration("livetv")
        .await?
        .unwrap_or_else(default_live_tv_configuration);
    let server_id = state.db.server_state().await?.server_id.to_string();
    let mut channel = live_tv_channel_items(&config, &server_id)
        .into_iter()
        .find(|channel| {
            json_string_field(channel, "Id")
                .into_iter()
                .chain(json_string_field(channel, "JellyrinChannelId"))
                .any(|id| jellyfin_id_matches(&id, channel_id.trim()))
        })
        .ok_or_else(|| ApiError::not_found("Live TV item not found"))?;
    if !live_tv_item_is_visible_to_tuners(&channel, allowed_tuners.as_deref()) {
        return Err(ApiError::not_found("Live TV item not found"));
    }
    apply_live_tv_favorite_state(&mut channel, &favorite_ids);
    Ok(Json(channel))
}

fn live_tv_item_is_visible_to_tuners(
    item: &serde_json::Value,
    allowed_tuner_ids: Option<&[String]>,
) -> bool {
    allowed_tuner_ids.is_none_or(|allowed| {
        json_string_field(item, "TunerHostId").is_some_and(|tuner_id| {
            allowed
                .iter()
                .any(|allowed| allowed.eq_ignore_ascii_case(&tuner_id))
        })
    })
}

async fn live_tv_channel_by_id(
    db: &Database,
    channel_id: &str,
) -> Result<serde_json::Value, ApiError> {
    live_tv_channel_optional_by_id(db, channel_id)
        .await?
        .ok_or_else(|| ApiError::not_found("Live TV item not found"))
}

async fn live_tv_channel_optional_by_id(
    db: &Database,
    channel_id: &str,
) -> Result<Option<serde_json::Value>, ApiError> {
    if let Some(channel) = live_tv_channel_json_by_id(db, channel_id).await? {
        return Ok(Some(channel));
    }
    let config = db
        .named_configuration("livetv")
        .await?
        .unwrap_or_else(default_live_tv_configuration);
    let server_id = db.server_state().await?.server_id.to_string();
    Ok(live_tv_channel_items(&config, &server_id)
        .into_iter()
        .find(|channel| {
            json_string_field(channel, "Id")
                .into_iter()
                .chain(json_string_field(channel, "JellyrinChannelId"))
                .any(|id| jellyfin_id_matches(&id, channel_id.trim()))
        }))
}

fn live_tv_user_data_write_lock() -> &'static Mutex<()> {
    LIVE_TV_USER_DATA_WRITE_LOCK.get_or_init(|| Mutex::new(()))
}

async fn live_tv_favorite_ids(db: &Database, user_id: Uuid) -> Result<HashSet<String>, ApiError> {
    let config = db
        .named_configuration(LIVE_TV_USER_DATA_CONFIGURATION_KEY)
        .await?
        .unwrap_or_default();
    Ok(config
        .get("Favorites")
        .and_then(serde_json::Value::as_object)
        .and_then(|favorites| favorites.get(&user_id.to_string()))
        .and_then(serde_json::Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(serde_json::Value::as_str)
        .map(live_tv_lookup_id)
        .collect())
}

fn live_tv_channel_favorite_key(channel: &serde_json::Value) -> Option<String> {
    json_string_field(channel, "Id").map(|id| live_tv_lookup_id(&id))
}

fn apply_live_tv_favorite_state(channel: &mut serde_json::Value, favorite_ids: &HashSet<String>) {
    let is_favorite =
        live_tv_channel_favorite_key(channel).is_some_and(|key| favorite_ids.contains(&key));
    channel["IsFavorite"] = serde_json::json!(is_favorite);
    if channel
        .get("UserData")
        .is_none_or(|value| !value.is_object())
    {
        channel["UserData"] = serde_json::json!({});
    }
    channel["UserData"]["IsFavorite"] = serde_json::json!(is_favorite);
}

fn live_tv_channel_user_data_json(
    channel: &serde_json::Value,
    is_favorite: bool,
) -> Result<serde_json::Value, ApiError> {
    let item_id = json_string_field(channel, "Id")
        .ok_or_else(|| ApiError::not_found("Live TV item not found"))?;
    Ok(serde_json::json!({
        "PlaybackPositionTicks": 0,
        "PlayCount": 0,
        "IsFavorite": is_favorite,
        "Likes": null,
        "Played": false,
        "Key": item_id,
        "ItemId": item_id,
        "PlayedPercentage": null,
        "LastPlayedDate": null,
        "UnplayedItemCount": null,
        "Rating": null
    }))
}

async fn set_live_tv_channel_favorite_if_present(
    db: &Database,
    user_id: Uuid,
    item_id: &str,
    is_favorite: bool,
) -> Result<Option<serde_json::Value>, ApiError> {
    let Some(channel) = live_tv_channel_optional_by_id(db, item_id).await? else {
        return Ok(None);
    };
    let favorite_key = live_tv_channel_favorite_key(&channel)
        .ok_or_else(|| ApiError::not_found("Live TV item not found"))?;
    let _guard = live_tv_user_data_write_lock().lock().await;
    let mut config = db
        .named_configuration(LIVE_TV_USER_DATA_CONFIGURATION_KEY)
        .await?
        .unwrap_or_else(|| serde_json::json!({ "Favorites": {} }));
    if config
        .get("Favorites")
        .is_none_or(|value| !value.is_object())
    {
        config["Favorites"] = serde_json::json!({});
    }
    let user_key = user_id.to_string();
    let mut favorites = config["Favorites"]
        .get(&user_key)
        .and_then(serde_json::Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(serde_json::Value::as_str)
        .map(live_tv_lookup_id)
        .collect::<HashSet<_>>();
    if is_favorite {
        favorites.insert(favorite_key);
    } else {
        favorites.remove(&favorite_key);
    }
    let mut favorites = favorites.into_iter().collect::<Vec<_>>();
    favorites.sort_unstable();
    config["Favorites"][user_key.as_str()] = serde_json::json!(favorites);
    db.update_named_configuration(LIVE_TV_USER_DATA_CONFIGURATION_KEY, config)
        .await?;
    live_tv_channel_user_data_json(&channel, is_favorite).map(Some)
}

async fn live_tv_channel_user_data_if_present(
    db: &Database,
    user_id: Uuid,
    item_id: &str,
) -> Result<Option<serde_json::Value>, ApiError> {
    let Some(channel) = live_tv_channel_optional_by_id(db, item_id).await? else {
        return Ok(None);
    };
    let favorite_ids = live_tv_favorite_ids(db, user_id).await?;
    let is_favorite =
        live_tv_channel_favorite_key(&channel).is_some_and(|key| favorite_ids.contains(&key));
    live_tv_channel_user_data_json(&channel, is_favorite).map(Some)
}

async fn live_tv_programs(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    RawQuery(raw_query): RawQuery,
) -> Result<Json<serde_json::Value>, ApiError> {
    let (user, token) = require_user(&state.db, &headers, auth_query.api_key.as_deref()).await?;
    let allowed_tuners = authorized_live_tv_tuner_ids(
        &state.db,
        &jellyrin_plugin_sdk::PluginUserContext {
            user_id: user.id.to_string(),
            device_id: token.device_id,
            is_administrator: user.is_administrator,
        },
    )
    .await?;
    let query = parse_live_tv_programs_query(raw_query.as_deref());
    let channel_ids = query.channel_ids;
    let requested =
        live_tv_category_filter_values(query.genre_ids.as_deref(), query.tags.as_deref());
    // Resolve genre-hash / name selectors to real category ids (same as channels).
    let category_ids = resolve_live_tv_category_ids(&state.db, &requested).await?;
    let series_scope = live_tv_series_scope(&state.db, query.library_series_id.as_deref()).await?;
    live_tv_program_result(
        &state.db,
        &channel_ids,
        &category_ids,
        query.start_index,
        query.limit,
        LiveTvProgramScope {
            filters: query.filters,
            allowed_tuner_ids: allowed_tuners.as_deref(),
            series: &series_scope,
        },
    )
    .await
}

#[derive(Debug, Default)]
struct ParsedLiveTvProgramsQuery {
    channel_ids: Vec<String>,
    genre_ids: Option<String>,
    tags: Option<String>,
    library_series_id: Option<String>,
    start_index: Option<usize>,
    limit: Option<usize>,
    filters: LiveTvProgramFilters,
}

/// Scope requested by Jellyfin's `LibrarySeriesId`, which asks for the upcoming broadcasts of one
/// library series. Ignoring it made the series detail page show unrelated channels under
/// "Upcoming on TV", because the client only reveals that section when the response is non-empty.
enum LiveTvSeriesScope {
    /// No `LibrarySeriesId` was requested.
    Unscoped,
    /// A series was requested that has no electronic-programme-guide identity, so no broadcast can
    /// belong to it. An imported on-demand series is always this case.
    NoBroadcasts,
    /// Retain only programmes belonging to this guide series identity.
    ExternalSeriesId(String),
}

#[derive(Debug, Default, Clone, Copy)]
struct LiveTvProgramFilters {
    is_airing: Option<bool>,
    has_aired: Option<bool>,
    is_movie: Option<bool>,
    is_series: Option<bool>,
    is_sports: Option<bool>,
    is_kids: Option<bool>,
    is_news: Option<bool>,
}

impl LiveTvProgramFilters {
    fn has_category_filters(self) -> bool {
        self.is_movie.is_some()
            || self.is_series.is_some()
            || self.is_sports.is_some()
            || self.is_kids.is_some()
            || self.is_news.is_some()
    }

    fn is_empty(self) -> bool {
        self.is_airing.is_none() && self.has_aired.is_none() && !self.has_category_filters()
    }
}

fn parse_live_tv_programs_query(raw_query: Option<&str>) -> ParsedLiveTvProgramsQuery {
    let mut query = ParsedLiveTvProgramsQuery::default();
    let Some(raw_query) = raw_query else {
        return query;
    };

    for part in raw_query.split('&').filter(|part| !part.is_empty()) {
        let (key, value) = part.split_once('=').unwrap_or((part, ""));
        let key = percent_decode_query_component(key).to_ascii_lowercase();
        let value = percent_decode_query_component(value);
        match key.as_str() {
            "channelids" | "channelid" => query.channel_ids.extend(comma_delimited_values(&value)),
            "genreids" | "genreid" => set_query_scalar(&mut query.genre_ids, value),
            "tags" | "tag" => set_query_scalar(&mut query.tags, value),
            "libraryseriesid" => set_query_scalar(&mut query.library_series_id, value),
            "startindex" => query.start_index = value.parse().ok(),
            "limit" => query.limit = value.parse().ok(),
            "isairing" => query.filters.is_airing = parse_bool_query_value(&value),
            "hasaired" => query.filters.has_aired = parse_bool_query_value(&value),
            "ismovie" => query.filters.is_movie = parse_bool_query_value(&value),
            "isseries" => query.filters.is_series = parse_bool_query_value(&value),
            "issports" => query.filters.is_sports = parse_bool_query_value(&value),
            "iskids" => query.filters.is_kids = parse_bool_query_value(&value),
            "isnews" => query.filters.is_news = parse_bool_query_value(&value),
            _ => {}
        }
    }
    query
}

async fn live_tv_programs_post(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    body: Body,
) -> Result<Json<serde_json::Value>, ApiError> {
    let (user, token) = require_user(&state.db, &headers, query.api_key.as_deref()).await?;
    let allowed_tuners = authorized_live_tv_tuner_ids(
        &state.db,
        &jellyrin_plugin_sdk::PluginUserContext {
            user_id: user.id.to_string(),
            device_id: token.device_id,
            is_administrator: user.is_administrator,
        },
    )
    .await?;
    let payload = optional_json_body(body).await?;
    let channel_ids = json_string_list_field(&payload, "ChannelIds").unwrap_or_default();
    let requested = json_string_list_field(&payload, "GenreIds")
        .or_else(|| json_string_list_field(&payload, "Tags"))
        .unwrap_or_default();
    // Resolve genre-hash / name selectors to real category ids (same as channels).
    let category_ids = resolve_live_tv_category_ids(&state.db, &requested).await?;
    let start_index = live_tv_u64_field(&payload, "StartIndex").map(|value| value as usize);
    let limit = live_tv_u64_field(&payload, "Limit").map(|value| value as usize);
    let filters = live_tv_program_filters_from_body(&payload);
    let series_scope = live_tv_series_scope(
        &state.db,
        json_string_field(&payload, "LibrarySeriesId").as_deref(),
    )
    .await?;
    live_tv_program_result(
        &state.db,
        &channel_ids,
        &category_ids,
        start_index,
        limit,
        LiveTvProgramScope {
            filters,
            allowed_tuner_ids: allowed_tuners.as_deref(),
            series: &series_scope,
        },
    )
    .await
}

/// Resolves Jellyfin's `LibrarySeriesId` into the scope its upcoming-broadcast section expects.
///
/// A guide series is identified by `ExternalSeriesId`. A library series that has none — every
/// series imported from an on-demand provider — can have no upcoming broadcast, so the correct
/// answer is an empty page, which is what keeps the client's section hidden.
async fn live_tv_series_scope(
    db: &Database,
    library_series_id: Option<&str>,
) -> Result<LiveTvSeriesScope, ApiError> {
    let Some(library_series_id) = library_series_id
        .map(str::trim)
        .filter(|value| !value.is_empty() && !value.eq_ignore_ascii_case("null"))
    else {
        return Ok(LiveTvSeriesScope::Unscoped);
    };
    let Ok(series_uuid) = parse_jellyfin_uuid(library_series_id) else {
        return Ok(LiveTvSeriesScope::NoBroadcasts);
    };
    let metadata = metadata_payload_for_item(db, series_uuid).await?;
    let external_series_id = first_metadata_value_from_json(&metadata, &["ExternalSeriesId"])
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty());
    Ok(match external_series_id {
        Some(external_series_id) => LiveTvSeriesScope::ExternalSeriesId(external_series_id),
        None => LiveTvSeriesScope::NoBroadcasts,
    })
}

fn live_tv_program_filters_from_body(payload: &serde_json::Value) -> LiveTvProgramFilters {
    LiveTvProgramFilters {
        is_airing: json_bool_field(payload, "IsAiring"),
        has_aired: json_bool_field(payload, "HasAired"),
        is_movie: json_bool_field(payload, "IsMovie"),
        is_series: json_bool_field(payload, "IsSeries"),
        is_sports: json_bool_field(payload, "IsSports"),
        is_kids: json_bool_field(payload, "IsKids"),
        is_news: json_bool_field(payload, "IsNews"),
    }
}

fn live_tv_category_filter_values(genre_ids: Option<&str>, tags: Option<&str>) -> Vec<String> {
    genre_ids
        .into_iter()
        .chain(tags)
        .flat_map(comma_delimited_values)
        .filter(|value| !value.eq_ignore_ascii_case("null"))
        .collect()
}

async fn live_tv_program(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    Path(program_id): Path<String>,
) -> Result<Json<serde_json::Value>, ApiError> {
    let (user, token) = require_user(&state.db, &headers, query.api_key.as_deref()).await?;
    let allowed_tuners = authorized_live_tv_tuner_ids(
        &state.db,
        &jellyrin_plugin_sdk::PluginUserContext {
            user_id: user.id.to_string(),
            device_id: token.device_id,
            is_administrator: user.is_administrator,
        },
    )
    .await?;
    let program = live_tv_program_by_id(&state.db, &program_id)
        .await?
        .ok_or_else(|| ApiError::not_found("Live TV item not found"))?;
    if !live_tv_item_is_visible_to_tuners(&program, allowed_tuners.as_deref()) {
        return Err(ApiError::not_found("Live TV item not found"));
    }
    Ok(Json(program))
}

async fn live_tv_program_by_id(
    db: &Database,
    program_id: &str,
) -> Result<Option<serde_json::Value>, ApiError> {
    let config = db
        .named_configuration("livetv")
        .await?
        .unwrap_or_else(default_live_tv_configuration);
    let server_id = db.server_state().await?.server_id.to_string();
    let programs = live_tv_program_items(&config, &server_id);
    if programs.is_empty() {
        let start = OffsetDateTime::now_utc() - Duration::hours(12);
        let end = OffsetDateTime::now_utc() + Duration::hours(12);
        let start_date = format_time_for_json(start);
        let end_date = format_time_for_json(end);
        let persisted_count = db
            .live_tv_channel_count(&LiveTvChannelQuery::default())
            .await?;
        if persisted_count > 0 {
            let prefix = "fallback-program-";
            if let Some(normalized_channel_id) = program_id.trim().strip_prefix(prefix) {
                let mut candidates = vec![normalized_channel_id.to_string()];
                if let Some(remote_id) = normalized_channel_id.strip_prefix("xtream-") {
                    candidates.push(format!("xtream_{remote_id}"));
                }
                for channel_id in candidates {
                    if let Some(record) = live_tv_channel_record_by_any_id(db, &channel_id).await? {
                        let channel = live_tv_channel_record_to_json(&record, &server_id);
                        return Ok(live_tv_fallback_program_item(
                            &channel,
                            &server_id,
                            &start_date,
                            &end_date,
                        ));
                    }
                }
            }
            if parse_jellyfin_uuid(program_id).is_ok() {
                let page = db
                    .live_tv_channel_page(LiveTvChannelQuery {
                        start_index: 0,
                        limit: Some(persisted_count.min(LIVE_TV_XTREAM_MAX_IMPORT_LIMIT)),
                        search_term: None,
                        tuner_ids: Vec::new(),
                        category_ids: Vec::new(),
                    })
                    .await?;
                for record in page.items {
                    let channel_id = live_tv_channel_public_id(&record.channel_id);
                    if jellyfin_id_matches(
                        &live_tv_fallback_program_public_id(&channel_id),
                        program_id.trim(),
                    ) {
                        let channel = live_tv_channel_record_to_json(&record, &server_id);
                        return Ok(live_tv_fallback_program_item(
                            &channel,
                            &server_id,
                            &start_date,
                            &end_date,
                        ));
                    }
                }
            }
        }
        let channels = live_tv_channel_items(&config, &server_id);
        return Ok(channels.iter().find_map(|channel| {
            let channel_id = json_string_field(channel, "Id")?;
            (live_tv_fallback_program_public_id(&channel_id)
                .eq_ignore_ascii_case(program_id.trim())
                || live_tv_stable_id("fallback-program", &channel_id)
                    .eq_ignore_ascii_case(program_id.trim()))
            .then(|| live_tv_fallback_program_item(channel, &server_id, &start_date, &end_date))
            .flatten()
        }));
    }
    Ok(programs.into_iter().find(|program| {
        json_string_field(program, "Id")
            .into_iter()
            .chain(json_string_field(program, "JellyrinProgramId"))
            .any(|id| jellyfin_id_matches(&id, program_id.trim()))
    }))
}

fn looks_like_live_tv_program_id(item_id: &str) -> bool {
    let item_id = item_id.trim().to_ascii_lowercase();
    item_id.starts_with("program-")
        || item_id.starts_with("xtream-program-")
        || item_id.starts_with("fallback-program-")
}

/// Everything that narrows a programme page beyond channel, category and paging.
struct LiveTvProgramScope<'a> {
    filters: LiveTvProgramFilters,
    allowed_tuner_ids: Option<&'a [String]>,
    series: &'a LiveTvSeriesScope,
}

async fn live_tv_program_result(
    db: &Database,
    channel_ids: &[String],
    category_ids: &[String],
    start_index: Option<usize>,
    limit: Option<usize>,
    scope: LiveTvProgramScope<'_>,
) -> Result<Json<serde_json::Value>, ApiError> {
    let LiveTvProgramScope {
        filters,
        allowed_tuner_ids,
        series: series_scope,
    } = scope;
    if matches!(series_scope, LiveTvSeriesScope::NoBroadcasts) {
        return Ok(Json(query_result_with_total(Vec::new(), 0, 0)));
    }
    let config = db
        .named_configuration("livetv")
        .await?
        .unwrap_or_else(default_live_tv_configuration);
    let server_id = db.server_state().await?.server_id.to_string();
    let mut programs = live_tv_program_items(&config, &server_id);
    if let LiveTvSeriesScope::ExternalSeriesId(series_id) = series_scope {
        programs.retain(|program| {
            ["ExternalSeriesId", "SeriesId"].iter().any(|key| {
                json_string_field(program, key)
                    .is_some_and(|value| value.eq_ignore_ascii_case(series_id))
            })
        });
    }
    if let Some(allowed) = allowed_tuner_ids {
        retain_authorized_live_tv_programs(
            &mut programs,
            &live_tv_channel_items(&config, &server_id),
            allowed,
        );
    }
    if !channel_ids.is_empty() {
        let channel_ids = channel_ids
            .iter()
            .filter(|id| !id.eq_ignore_ascii_case("null"))
            .collect::<Vec<_>>();
        if !channel_ids.is_empty() {
            programs.retain(|program| {
                json_string_field(program, "ChannelId")
                    .into_iter()
                    .chain(json_string_field(program, "JellyrinChannelId"))
                    .any(|channel_id| {
                        channel_ids
                            .iter()
                            .any(|requested| jellyfin_id_matches(requested, &channel_id))
                    })
            });
        }
    }
    if !category_ids.is_empty() {
        let categories = LiveTvService::new(db).categories().await?;
        let category_names = categories
            .iter()
            .filter(|category| {
                category_ids.iter().any(|requested| {
                    requested.eq_ignore_ascii_case(&category.category_id)
                        || requested.eq_ignore_ascii_case(&category.name)
                })
            })
            .map(|category| category.name.to_ascii_lowercase())
            .collect::<HashSet<_>>();
        if !category_names.is_empty() {
            programs.retain(|program| {
                json_string_list_field(program, "Genres")
                    .unwrap_or_default()
                    .iter()
                    .any(|genre| category_names.contains(&genre.to_ascii_lowercase()))
                    || json_string_list_field(program, "Tags")
                        .unwrap_or_default()
                        .iter()
                        .any(|tag| category_names.contains(&tag.to_ascii_lowercase()))
            });
        }
    }
    let had_config_programs = !programs.is_empty();
    programs = filter_live_tv_programs(programs, filters);
    if had_config_programs && programs.is_empty() {
        return Ok(Json(query_result_with_total(
            Vec::<serde_json::Value>::new(),
            0,
            start_index.unwrap_or(0),
        )));
    }
    if programs.is_empty() {
        if !channel_ids.is_empty() {
            let channels = live_tv_channel_records_by_any_ids(db, channel_ids)
                .await?
                .into_iter()
                .filter(|record| {
                    allowed_tuner_ids.is_none_or(|allowed| {
                        allowed
                            .iter()
                            .any(|id| id.eq_ignore_ascii_case(&record.tuner_id))
                    })
                })
                .map(|record| live_tv_channel_record_to_json(&record, &server_id))
                .collect::<Vec<_>>();
            if !channels.is_empty() {
                programs = live_tv_fallback_program_items(&channels, &[], &server_id);
                programs = filter_live_tv_programs(programs, filters);
                let total_record_count = programs.len();
                let start_index = start_index.unwrap_or(0).min(total_record_count);
                let limit = limit.unwrap_or(total_record_count.saturating_sub(start_index));
                let items = programs
                    .into_iter()
                    .skip(start_index)
                    .take(limit)
                    .collect::<Vec<_>>();
                return Ok(Json(query_result_with_total(
                    items,
                    total_record_count,
                    start_index,
                )));
            }
        }
        let tuner_ids = allowed_tuner_ids
            .map(<[String]>::to_vec)
            .unwrap_or_default();
        let persisted_count = db
            .live_tv_channel_count(&LiveTvChannelQuery {
                tuner_ids: tuner_ids.clone(),
                ..LiveTvChannelQuery::default()
            })
            .await?;
        if persisted_count > 0 {
            let category_ids_filter = category_ids.to_vec();
            let persisted_count = db
                .live_tv_channel_count(&LiveTvChannelQuery {
                    start_index: 0,
                    limit: None,
                    search_term: None,
                    tuner_ids: tuner_ids.clone(),
                    category_ids: category_ids_filter.clone(),
                })
                .await?;
            if filters.has_category_filters() {
                let page = db
                    .live_tv_channel_page(LiveTvChannelQuery {
                        start_index: 0,
                        limit: Some(persisted_count.min(LIVE_TV_XTREAM_MAX_IMPORT_LIMIT)),
                        search_term: None,
                        tuner_ids: tuner_ids.clone(),
                        category_ids: category_ids_filter,
                    })
                    .await?;
                let channels = page
                    .items
                    .iter()
                    .map(|record| live_tv_channel_record_to_json(record, &server_id))
                    .collect::<Vec<_>>();
                let programs = filter_live_tv_programs(
                    live_tv_fallback_program_items(&channels, &[], &server_id),
                    filters,
                );
                let total_record_count = programs.len();
                let start_index = start_index.unwrap_or(0).min(total_record_count);
                let limit = limit.unwrap_or(total_record_count.saturating_sub(start_index));
                let items = programs
                    .into_iter()
                    .skip(start_index)
                    .take(limit)
                    .collect::<Vec<_>>();
                return Ok(Json(query_result_with_total(
                    items,
                    total_record_count,
                    start_index,
                )));
            }
            let start_index = start_index.unwrap_or(0).min(persisted_count);
            let limit = limit
                .unwrap_or(persisted_count.saturating_sub(start_index))
                .min(500);
            let page = db
                .live_tv_channel_page(LiveTvChannelQuery {
                    start_index,
                    limit: Some(limit),
                    search_term: None,
                    tuner_ids,
                    category_ids: category_ids.to_vec(),
                })
                .await?;
            let channels = page
                .items
                .iter()
                .map(|record| live_tv_channel_record_to_json(record, &server_id))
                .collect::<Vec<_>>();
            let items = live_tv_fallback_program_items(&channels, &[], &server_id);
            return Ok(Json(query_result_with_total(
                items,
                persisted_count,
                start_index,
            )));
        }
        let channels = live_tv_channel_items(&config, &server_id);
        programs = live_tv_fallback_program_items(&channels, channel_ids, &server_id);
        programs = filter_live_tv_programs(programs, filters);
    }
    let total_record_count = programs.len();
    let start_index = start_index.unwrap_or(0).min(total_record_count);
    let limit = limit.unwrap_or(total_record_count.saturating_sub(start_index));
    let items = programs
        .into_iter()
        .skip(start_index)
        .take(limit)
        .collect::<Vec<_>>();
    Ok(Json(query_result_with_total(
        items,
        total_record_count,
        start_index,
    )))
}

fn filter_live_tv_programs(
    programs: Vec<serde_json::Value>,
    filters: LiveTvProgramFilters,
) -> Vec<serde_json::Value> {
    if filters.is_empty() {
        return programs;
    }
    programs
        .into_iter()
        .filter(|program| live_tv_program_matches_filters(program, filters))
        .collect()
}

fn live_tv_program_matches_filters(
    program: &serde_json::Value,
    filters: LiveTvProgramFilters,
) -> bool {
    if !live_tv_program_bool_matches(program, "IsMovie", filters.is_movie)
        || !live_tv_program_bool_matches(program, "IsSeries", filters.is_series)
        || !live_tv_program_bool_matches(program, "IsSports", filters.is_sports)
        || !live_tv_program_bool_matches(program, "IsKids", filters.is_kids)
        || !live_tv_program_bool_matches(program, "IsNews", filters.is_news)
    {
        return false;
    }

    let now = OffsetDateTime::now_utc();
    if let Some(is_airing) = filters.is_airing {
        let program_is_airing = json_bool_field(program, "IsLive").unwrap_or(false)
            || live_tv_program_airing_at(program, now);
        if program_is_airing != is_airing {
            return false;
        }
    }
    if let Some(has_aired) = filters.has_aired
        && live_tv_program_has_aired(program, now) != has_aired
    {
        return false;
    }
    true
}

fn live_tv_program_bool_matches(
    program: &serde_json::Value,
    field: &str,
    expected: Option<bool>,
) -> bool {
    expected.is_none_or(|expected| json_bool_field(program, field).unwrap_or(false) == expected)
}

fn live_tv_program_airing_at(program: &serde_json::Value, now: OffsetDateTime) -> bool {
    let Some(start) = live_tv_program_datetime(program, "StartDate") else {
        return false;
    };
    let Some(end) = live_tv_program_datetime(program, "EndDate") else {
        return false;
    };
    start <= now && now < end
}

fn live_tv_program_has_aired(program: &serde_json::Value, now: OffsetDateTime) -> bool {
    live_tv_program_datetime(program, "EndDate").is_some_and(|end| end <= now)
}

fn live_tv_program_datetime(program: &serde_json::Value, field: &str) -> Option<OffsetDateTime> {
    json_string_field(program, field).and_then(|value| OffsetDateTime::parse(&value, &Rfc3339).ok())
}

fn apply_live_tv_program_runtime_ticks(program: &mut serde_json::Value) {
    if json_i64_field(program, "RunTimeTicks").is_some_and(|ticks| ticks >= 0) {
        return;
    }
    let Some(start) = live_tv_program_datetime(program, "StartDate") else {
        return;
    };
    let Some(end) = live_tv_program_datetime(program, "EndDate") else {
        return;
    };
    let ticks = (end - start).whole_nanoseconds().max(0) / 100;
    if let Ok(ticks) = i64::try_from(ticks) {
        program["RunTimeTicks"] = serde_json::json!(ticks);
    }
}

async fn live_tv_recording_stream(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    Path(recording_id): Path<String>,
) -> Result<axum::response::Response, ApiError> {
    require_request_user(&state.db, &headers, query.api_key.as_deref()).await?;
    let recording = live_tv_recording_by_id(&state.db, &recording_id).await?;
    stream_live_tv_recording(recording, &headers).await
}

async fn live_tv_stream_file(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    Path((stream_id, container)): Path<(String, String)>,
) -> Result<axum::response::Response, ApiError> {
    let (user, token) = require_user(&state.db, &headers, query.api_key.as_deref()).await?;
    let user_context = Some(plugin_user_context(&user, &token));
    if let Ok(recording) = live_tv_recording_by_id(&state.db, &stream_id).await {
        let path = live_tv_recording_path(&recording)?;
        let path_container = path
            .extension()
            .and_then(|extension| extension.to_str())
            .unwrap_or_default();
        if !path_container.eq_ignore_ascii_case(container.trim()) {
            return Err(ApiError::not_found("Live TV stream not found"));
        }
        return stream_live_tv_recording(recording, &headers).await;
    }
    let channel = live_tv_channel_by_id(&state.db, &stream_id).await?;
    if live_tv_channel_uses_opaque_provider(&channel) {
        if !matches!(
            container.trim().to_ascii_lowercase().as_str(),
            "ts" | "mpegts" | "mpeg-ts" | "mpeg2ts"
        ) {
            return Err(ApiError::not_found("Live TV stream not found"));
        }
        return stream_live_tv_channel(channel, &headers, &state.db, user_context).await;
    }
    let path = live_tv_channel_path(&channel)?;
    if !live_tv_channel_is_remote(&path) && !live_tv_channel_is_legacy_hdhomerun_path(&path) {
        let path_container = path
            .extension()
            .and_then(|extension| extension.to_str())
            .unwrap_or_default();
        if !path_container.eq_ignore_ascii_case(container.trim()) {
            return Err(ApiError::not_found("Live TV stream not found"));
        }
    }
    stream_live_tv_channel(channel, &headers, &state.db, user_context).await
}

async fn live_tv_recordings(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
) -> Result<Json<serde_json::Value>, ApiError> {
    require_request_user(&state.db, &headers, query.api_key.as_deref()).await?;
    let config = state
        .db
        .named_configuration("livetv")
        .await?
        .unwrap_or_else(default_live_tv_configuration);
    let server_id = state.db.server_state().await?.server_id.to_string();
    Ok(Json(query_result(live_tv_recording_items(
        &config, &server_id,
    ))))
}

async fn live_tv_recording(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    Path(recording_id): Path<String>,
) -> Result<Json<serde_json::Value>, ApiError> {
    require_request_user(&state.db, &headers, query.api_key.as_deref()).await?;
    let config = state
        .db
        .named_configuration("livetv")
        .await?
        .unwrap_or_else(default_live_tv_configuration);
    let server_id = state.db.server_state().await?.server_id.to_string();
    let recording = live_tv_recording_items(&config, &server_id)
        .into_iter()
        .find(|recording| {
            json_string_field(recording, "Id")
                .is_some_and(|id| id.eq_ignore_ascii_case(recording_id.trim()))
        })
        .ok_or_else(|| ApiError::not_found("Live TV recording not found"))?;
    Ok(Json(recording))
}

async fn live_tv_recording_by_id(
    db: &Database,
    recording_id: &str,
) -> Result<serde_json::Value, ApiError> {
    let config = db
        .named_configuration("livetv")
        .await?
        .unwrap_or_else(default_live_tv_configuration);
    let server_id = db.server_state().await?.server_id.to_string();
    live_tv_recording_items(&config, &server_id)
        .into_iter()
        .find(|recording| {
            json_string_field(recording, "Id")
                .is_some_and(|id| id.eq_ignore_ascii_case(recording_id.trim()))
                || json_string_field(recording, "TimerId")
                    .is_some_and(|id| id.eq_ignore_ascii_case(recording_id.trim()))
        })
        .ok_or_else(|| ApiError::not_found("Live TV recording not found"))
}

async fn stream_live_tv_recording(
    recording: serde_json::Value,
    headers: &HeaderMap,
) -> Result<axum::response::Response, ApiError> {
    let path = live_tv_recording_path(&recording)?;
    let content_type = live_tv_recording_content_type(&path).to_string();
    stream_path(path, content_type, headers, true).await
}

async fn live_tv_tuner_host_by_id(db: &Database, tuner_host_id: &str) -> Option<serde_json::Value> {
    let config = ConfigurationService::new(db).get("livetv").await.ok()??;
    config
        .get("TunerHosts")
        .and_then(serde_json::Value::as_array)?
        .iter()
        .find(|host| {
            host.get("Id")
                .and_then(serde_json::Value::as_str)
                .is_some_and(|id| id.eq_ignore_ascii_case(tuner_host_id))
        })
        .cloned()
}

// Resolve the TunerCount for a given tuner host ID from the livetv named configuration.
// Returns None if the host is not found, TunerCount is absent, or is zero (no per-host cap).
// The global distinct-producer cap is enforced independently in all cases.
async fn tuner_count_for_host(db: &Database, tuner_host_id: &str) -> Option<u64> {
    let tuner_host = live_tv_tuner_host_by_id(db, tuner_host_id).await?;
    let tuner_count = live_tv_u64_field(&tuner_host, "TunerCount")?;
    // TunerCount == 0 disables only this tuner's per-host limit.
    if tuner_count == 0 {
        None
    } else {
        Some(tuner_count)
    }
}

async fn live_tv_channel_tuner_limit(
    db: &Database,
    channel: &serde_json::Value,
) -> (Option<String>, Option<u64>) {
    let tuner_host_id = json_string_field(channel, "TunerHostId");
    let tuner_count = match &tuner_host_id {
        Some(host_id) => tuner_count_for_host(db, host_id).await,
        None => None,
    };
    (tuner_host_id, tuner_count)
}

fn acquire_live_tuner_lease(
    tuner_host_id: Option<String>,
    channel_url: &str,
    tuner_count: Option<u64>,
) -> Result<Option<LiveTunerLeaseGuard>, ApiError> {
    let key = LiveTunerLeaseKey {
        tuner_host_id: tuner_host_id
            .unwrap_or_else(|| LIVE_TUNER_UNASSIGNED_HOST_ID.to_string())
            .to_ascii_lowercase(),
        channel_url: channel_url.to_string(),
    };

    with_live_tuner_leases(|leases| {
        if let Some(lease) = leases.get_mut(&key) {
            lease.refcount = lease.refcount.saturating_add(1);
            return Ok(Some(LiveTunerLeaseGuard { key }));
        }

        ensure_live_tuner_lease_capacity(leases, &key, tuner_count)?;

        leases.insert(key.clone(), LiveTunerLease { refcount: 1 });
        Ok(Some(LiveTunerLeaseGuard { key }))
    })?
}

fn ensure_live_tuner_lease_capacity(
    leases: &HashMap<LiveTunerLeaseKey, LiveTunerLease>,
    key: &LiveTunerLeaseKey,
    tuner_count: Option<u64>,
) -> Result<(), ApiError> {
    if leases.contains_key(key) {
        return Ok(());
    }
    if leases.len() >= LIVE_TV_MAX_DISTINCT_PRODUCERS {
        return Err(ApiError::service_unavailable(
            "Global Live TV producer limit has been reached",
        ));
    }
    if let Some(limit) = tuner_count {
        let active_distinct_channels = leases
            .keys()
            .filter(|lease_key| {
                lease_key
                    .tuner_host_id
                    .eq_ignore_ascii_case(&key.tuner_host_id)
            })
            .count() as u64;
        if active_distinct_channels >= limit {
            return Err(ApiError::service_unavailable(format!(
                "Live TV simultaneous stream limit has been reached (TunerCount={limit})"
            )));
        }
    }
    Ok(())
}

fn acquire_unshared_live_tuner_lease(
    tuner_host_id: Option<String>,
    channel_id: &str,
    tuner_count: Option<u64>,
) -> Result<Option<LiveTunerLeaseGuard>, ApiError> {
    // Opaque direct proxies open one upstream connection per HTTP response. They cannot reuse the
    // shared-channel identity used by HDHomeRun, so every response consumes its own tuner slot.
    // The registry key contains only a hashed internal channel id plus a random request id: never
    // a provider reference or the short-lived signed playback URL.
    let stream_identity = format!(
        "unshared:{}:{}",
        stable_entity_id("livetv-unshared-lease", channel_id),
        Uuid::new_v4().simple()
    );
    acquire_live_tuner_lease(tuner_host_id, &stream_identity, tuner_count)
}

async fn stream_live_tv_channel(
    channel: serde_json::Value,
    headers: &HeaderMap,
    db: &Database,
    user_context: Option<jellyrin_plugin_sdk::PluginUserContext>,
) -> Result<axum::response::Response, ApiError> {
    if live_tv_channel_uses_opaque_provider(&channel) {
        let channel_id = live_tv_channel_playback_id(&channel).ok_or_else(|| {
            ApiError::service_unavailable("Live TV provider channel identity is unavailable")
        })?;
        let (tuner_host_id, tuner_count) = live_tv_channel_tuner_limit(db, &channel).await;
        let tuner_lease =
            acquire_unshared_live_tuner_lease(tuner_host_id, &channel_id, tuner_count)?;
        let playback = resolve_opaque_live_tv_playback(db, &channel, user_context).await?;
        if !opaque_live_tv_delivery_is_safe_for_direct_proxy(&playback) {
            return Err(ApiError::service_unavailable(
                "Live TV provider did not authorize a safe direct stream",
            ));
        }
        return stream_sensitive_remote_live(
            playback.source_url,
            headers,
            playback.delivery.requires_provider_egress,
            tuner_lease,
        )
        .await;
    }
    let path = live_tv_channel_path(&channel)?;
    if live_tv_channel_is_legacy_hdhomerun_path(&path) {
        let tuner_host_id = json_string_field(&channel, "TunerHostId");
        let params = legacy_hdhomerun_stream_params_for_host(db, tuner_host_id.as_deref()).await?;
        let tuner_count = match &tuner_host_id {
            Some(host_id) => tuner_count_for_host(db, host_id).await,
            None => None,
        };
        return proxy_live_tv_legacy_hdhomerun_url(
            path.to_string_lossy().into_owned(),
            params.tuner_host_url,
            params.control_port,
            params.num_tuners,
            tuner_host_id,
            tuner_count,
        )
        .await;
    }
    if live_tv_channel_is_remote(&path) {
        let (tuner_host_id, tuner_count) = live_tv_channel_tuner_limit(db, &channel).await;
        return proxy_live_tv_channel_url(
            path.to_string_lossy().into_owned(),
            tuner_host_id,
            tuner_count,
        )
        .await;
    }
    let content_type = live_tv_recording_content_type(&path).to_string();
    stream_path(path, content_type, headers, true).await
}

fn opaque_live_tv_delivery_is_safe_for_direct_proxy(playback: &LiveTvPlaybackResult) -> bool {
    let direct_proxy = playback
        .delivery
        .preferred
        .eq_ignore_ascii_case("DirectProxy");
    let mpeg_ts = matches!(
        playback
            .delivery
            .container
            .trim()
            .to_ascii_lowercase()
            .as_str(),
        "mpegts" | "mpeg-ts" | "ts" | "mpeg2ts"
    );
    direct_proxy && mpeg_ts
}

async fn resolve_opaque_live_tv_playback(
    db: &Database,
    channel: &serde_json::Value,
    user_context: Option<jellyrin_plugin_sdk::PluginUserContext>,
) -> Result<LiveTvPlaybackResult, ApiError> {
    let provider_reference = live_tv_channel_provider_reference(channel).ok_or_else(|| {
        ApiError::service_unavailable("Live TV provider reference is unavailable")
    })?;
    if !valid_live_tv_provider_reference(&provider_reference) {
        return Err(ApiError::service_unavailable(
            "Live TV provider reference is invalid",
        ));
    }
    let tuner_id = json_string_field(channel, "TunerHostId")
        .ok_or_else(|| ApiError::service_unavailable("Live TV tuner route is unavailable"))?;
    let persisted_tuner_config = db
        .live_tv_tuner_configuration_by_id(&tuner_id)
        .await?
        .ok_or_else(|| ApiError::service_unavailable("Live TV tuner is unavailable"))?;
    if json_string_field(channel, "ProviderType")
        .is_some_and(|provider| provider.eq_ignore_ascii_case("xtream"))
    {
        let tuner_config = db
            .resolve_provider_configuration(&persisted_tuner_config)
            .await
            .map_err(|_| {
                ApiError::service_unavailable("Live TV tuner credentials are unavailable")
            })?;
        let source_url =
            live_tv_xtream::resolve_live_provider_reference(&tuner_config, &provider_reference)
                .ok_or_else(|| {
                    ApiError::service_unavailable(
                        "Xtream Live TV provider reference is unavailable",
                    )
                })?;
        return Ok(LiveTvPlaybackResult {
            source_url: SensitiveUrl::new(source_url),
            expires_at: None,
            delivery: LiveTvPlaybackDelivery {
                container: "mpegts".to_string(),
                preferred: "DirectProxy".to_string(),
                requires_provider_egress: false,
                fallback: Some("HlsRemux".to_string()),
                video_codec: None,
                audio_codec: None,
            },
            media_streams: channel
                .get("MediaStreams")
                .and_then(serde_json::Value::as_array)
                .cloned()
                .unwrap_or_default(),
        });
    }
    if contains_plaintext_provider_secret(&persisted_tuner_config) {
        return Err(ApiError::service_unavailable(
            "Live TV tuner must use an external secret reference",
        ));
    }

    let plugin_id = json_string_field(channel, "PluginProviderId")
        .ok_or_else(|| ApiError::service_unavailable("Live TV provider route is unavailable"))?;
    if !json_string_field(channel, "ProviderType")
        .is_some_and(|provider| provider.eq_ignore_ascii_case(&format!("plugin:{plugin_id}")))
    {
        return Err(ApiError::service_unavailable(
            "Live TV channel provider binding is invalid",
        ));
    }
    let jit_lane = external_provider_jit_lane(&tuner_id)
        .ok_or_else(|| ApiError::service_unavailable("Live TV tuner is unavailable"))?;
    let _admission_guard = external_plugin_host_admission_slot(&plugin_id, &jit_lane)
        .await
        .acquire_owned()
        .await
        .map_err(|_| ApiError::service_unavailable("Live TV provider is unavailable"))?;
    let _provider_session_guard = try_external_provider_jit_session(&plugin_id, &tuner_id).await?;
    let security_slot = external_plugin_security_slot(&plugin_id).await;
    let _security_guard = security_slot.read_owned().await;
    let persisted_tuner_config = db
        .live_tv_tuner_configuration_by_id(&tuner_id)
        .await?
        .ok_or_else(|| ApiError::service_unavailable("Live TV tuner is unavailable"))?;
    if contains_plaintext_provider_secret(&persisted_tuner_config) {
        return Err(ApiError::service_unavailable(
            "Live TV tuner must use an external secret reference",
        ));
    }

    let plugin = db
        .installed_plugin_json(&plugin_id)
        .await?
        .filter(|plugin| {
            json_string_field(plugin, "Status").as_deref() == Some("Active")
                && plugin_string_array(plugin.get("Capabilities"))
                    .iter()
                    .any(|capability| capability.eq_ignore_ascii_case(CAPABILITY_LIVE_TV_PROVIDER))
        })
        .ok_or_else(|| ApiError::service_unavailable("Live TV provider is unavailable"))?;
    let Some((runtime, runtime_name, error_prefix, host_path)) = plugin_runtime_host_path(&plugin)
    else {
        return Err(ApiError::service_unavailable(
            "Live TV provider runtime is unavailable",
        ));
    };
    let context = LiveTvPlaybackContext {
        // This value belongs to the provider/sidecar configuration. Never substitute the
        // viewer's ConnectInfo address: providers may sign against the outbound egress address.
        egress_ip: json_string_field(&persisted_tuner_config, "EgressIp"),
        delivery_capabilities: LiveTvDeliveryCapabilities {
            direct_proxy: true,
            hls_remux: true,
        },
    };
    let mut request_arguments = serde_json::to_value(context)
        .map_err(|_| ApiError::internal("invalid Live TV playback context"))?;
    request_arguments["ProviderReference"] = serde_json::Value::String(provider_reference);
    let mut request = live_tv_plugin_provider_request(
        db,
        &plugin,
        &persisted_tuner_config,
        "ResolvePlayback",
        request_arguments,
    )
    .await
    .map_err(|_| ApiError::service_unavailable("Live TV provider credentials are unavailable"))?;
    if let Some(user_context) = user_context {
        request = request.with_user_context(user_context);
    }
    let arguments = serde_json::to_value(request)
        .map_err(|_| ApiError::internal("invalid Live TV playback request"))?;
    let result = invoke_plugin_capability_via_runtime_host_path_with_timeout(
        &plugin,
        CAPABILITY_LIVE_TV_PROVIDER,
        arguments,
        runtime,
        runtime_name,
        error_prefix,
        host_path,
        StdDuration::from_secs(15),
    )
    .await
    .map_err(|error| {
        let provider_error_code = bounded_plugin_runtime_error_code(&error);
        tracing::warn!(
            provider_error_code,
            "Live TV plugin playback resolution failed"
        );
        ApiError::service_unavailable("Live TV provider resolution failed")
    })?
    .ok_or_else(|| ApiError::service_unavailable("Live TV provider runtime is unavailable"))?;
    let result = ZeroizingJsonValue(result.value);

    if result
        .0
        .get("Status")
        .and_then(serde_json::Value::as_str)
        .is_some_and(|status| !status.eq_ignore_ascii_case("Executed"))
    {
        return Err(ApiError::service_unavailable(
            "Live TV provider rejected playback resolution",
        ));
    }
    let playback_value = result
        .0
        .get("Playback")
        .or_else(|| result.0.get("Result"))
        .unwrap_or(&result.0);
    let mut playback = LiveTvPlaybackResult::deserialize(playback_value)
        .map_err(|_| ApiError::service_unavailable("Live TV provider response is invalid"))?;
    // Opaque playback only needs the signed upstream URL and delivery contract. Never retain an
    // arbitrary plugin-controlled media-stream object after deserialization; it is not used by
    // the direct proxy and could otherwise become a second carrier for URLs or credentials.
    playback
        .media_streams
        .iter_mut()
        .for_each(zeroize_json_value_strings);
    playback.media_streams.clear();
    if let Some(expires_at) = playback.expires_at.as_deref() {
        let expires_at = OffsetDateTime::parse(expires_at, &Rfc3339)
            .map_err(|_| ApiError::service_unavailable("Live TV provider expiry is invalid"))?;
        if expires_at <= OffsetDateTime::now_utc() + Duration::seconds(2) {
            return Err(ApiError::service_unavailable(
                "Live TV provider source has expired",
            ));
        }
    }
    Ok(playback)
}

/// Playback routing triple parsed from one persisted plugin-VOD metadata payload.
struct PluginVodRemoteReference {
    plugin_id: String,
    tuner_id: String,
    provider_reference: String,
}

/// Extracts the plugin-VOD routing triple from persisted item metadata. Returns `None` unless the
/// metadata carries a `plugin:<id>` Provider, a tuner id and an opaque, URL-free provider
/// reference. A payload carrying anything that looks like a plaintext provider secret is rejected
/// outright so persisted metadata can never smuggle credentials into the playback path.
fn plugin_vod_remote_reference(metadata: &serde_json::Value) -> Option<PluginVodRemoteReference> {
    if contains_plaintext_provider_secret(metadata) {
        return None;
    }
    let provider = json_string_field(metadata, "Provider")?;
    let (route, plugin_id) = provider.split_once(':')?;
    if !route.eq_ignore_ascii_case("plugin") || plugin_id.trim().is_empty() {
        return None;
    }
    let tuner_id = json_string_field(metadata, "TunerId").filter(|id| !id.trim().is_empty())?;
    let provider_reference = json_string_field(metadata, "ProviderReference")
        .filter(|reference| valid_live_tv_provider_reference(reference))?;
    Some(PluginVodRemoteReference {
        plugin_id: plugin_id.trim().to_string(),
        tuner_id,
        provider_reference,
    })
}

fn is_plugin_vod_remote_media(metadata: Option<&serde_json::Value>) -> bool {
    metadata.and_then(plugin_vod_remote_reference).is_some()
}

/// Cheap path-prefix pre-filter for persisted plugin-VOD items; the metadata triple still has to
/// parse before playback is attempted.
fn is_plugin_vod_virtual_item(item: &MediaItem) -> bool {
    item.path.starts_with("plugin-vod://")
}

const PLUGIN_VOD_MAX_MEDIA_STREAMS: usize = 64;
const PLUGIN_VOD_MAX_STREAM_INDEX: i64 = 4_096;

/// Copies one plugin-provided media descriptor into the API boundary's deliberately small,
/// provider-neutral schema.  In particular, URL/path/header/token/licence fields are not merely
/// hidden from the response: an object carrying any unrecognised field is rejected in full. This
/// keeps track labels useful to clients without turning `MediaStreams` into a second channel for
/// the signed source URL or provider credentials.
fn sanitize_plugin_vod_media_stream(
    stream: &serde_json::Value,
) -> Result<serde_json::Value, ApiError> {
    let object = stream.as_object().ok_or_else(|| {
        ApiError::service_unavailable("VOD provider returned an invalid media stream")
    })?;
    const ALLOWED_FIELDS: &[&str] = &[
        "Index",
        "Type",
        "Codec",
        "Language",
        "Title",
        "DisplayTitle",
        "IsInterlaced",
        "IsDefault",
        "IsForced",
        "IsExternal",
        "IsTextSubtitleStream",
        "SupportsExternalStream",
        "Channels",
        "MagstvVariantContentId",
        "MagstvSubtitleLanguage",
    ];
    if object
        .keys()
        .any(|field| !ALLOWED_FIELDS.contains(&field.as_str()))
    {
        return Err(ApiError::service_unavailable(
            "VOD provider returned an unsafe media stream",
        ));
    }

    let index = object
        .get("Index")
        .and_then(json_value_i64)
        .filter(|index| (0..=PLUGIN_VOD_MAX_STREAM_INDEX).contains(index))
        .ok_or_else(|| {
            ApiError::service_unavailable("VOD provider returned an invalid media stream index")
        })?;
    let stream_type = object
        .get("Type")
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .and_then(|stream_type| {
            if stream_type.eq_ignore_ascii_case("Video") {
                Some("Video")
            } else if stream_type.eq_ignore_ascii_case("Audio") {
                Some("Audio")
            } else if stream_type.eq_ignore_ascii_case("Subtitle") {
                Some("Subtitle")
            } else {
                None
            }
        })
        .ok_or_else(|| {
            ApiError::service_unavailable("VOD provider returned an invalid media stream type")
        })?;

    let codec = object
        .get("Codec")
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .filter(|codec| {
            !codec.is_empty()
                && codec.len() <= 32
                && codec
                    .bytes()
                    .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'_' | b'-'))
        })
        .ok_or_else(|| {
            ApiError::service_unavailable("VOD provider returned an invalid media stream codec")
        })?;

    let safe_text = |field: &str, maximum: usize| -> Result<Option<String>, ApiError> {
        let Some(value) = object.get(field) else {
            return Ok(None);
        };
        let value = value.as_str().map(str::trim).ok_or_else(|| {
            ApiError::service_unavailable("VOD provider returned invalid media stream metadata")
        })?;
        if value.is_empty() || value.len() > maximum || value.chars().any(char::is_control) {
            return Err(ApiError::service_unavailable(
                "VOD provider returned invalid media stream metadata",
            ));
        }
        Ok(Some(value.to_string()))
    };
    let language = safe_text("Language", 64)?;
    let title = safe_text("Title", 256)?;
    let display_title = safe_text("DisplayTitle", 256)?;
    let subtitle_language = safe_text("MagstvSubtitleLanguage", 64)?;
    if subtitle_language.is_some() && stream_type != "Subtitle"
        || subtitle_language
            .as_deref()
            .is_some_and(|subtitle_language| {
                language
                    .as_deref()
                    .is_some_and(|language| !subtitle_language.eq_ignore_ascii_case(language))
            })
    {
        return Err(ApiError::service_unavailable(
            "VOD provider returned inconsistent subtitle metadata",
        ));
    }
    if let Some(content_id) = safe_text("MagstvVariantContentId", 512)?
        && (stream_type == "Subtitle" || !valid_live_tv_provider_reference(&content_id))
    {
        return Err(ApiError::service_unavailable(
            "VOD provider returned invalid variant metadata",
        ));
    }

    let safe_bool = |field: &str| -> Result<Option<bool>, ApiError> {
        object
            .get(field)
            .map(|value| {
                value.as_bool().ok_or_else(|| {
                    ApiError::service_unavailable(
                        "VOD provider returned invalid media stream metadata",
                    )
                })
            })
            .transpose()
    };
    let mut sanitized = serde_json::Map::new();
    sanitized.insert("Index".to_string(), serde_json::json!(index));
    sanitized.insert("Type".to_string(), serde_json::json!(stream_type));
    sanitized.insert("Codec".to_string(), serde_json::json!(codec));
    for (field, value) in [
        ("Language", language),
        ("Title", title),
        ("DisplayTitle", display_title),
        ("MagstvSubtitleLanguage", subtitle_language),
    ] {
        if let Some(value) = value {
            sanitized.insert(field.to_string(), serde_json::json!(value));
        }
    }
    for field in [
        "IsInterlaced",
        "IsDefault",
        "IsForced",
        "IsExternal",
        "IsTextSubtitleStream",
        "SupportsExternalStream",
    ] {
        if let Some(value) = safe_bool(field)? {
            sanitized.insert(field.to_string(), serde_json::json!(value));
        }
    }
    if let Some(channels) = object.get("Channels") {
        let channels = channels
            .as_i64()
            .filter(|channels| (1..=32).contains(channels))
            .ok_or_else(|| {
                ApiError::service_unavailable(
                    "VOD provider returned invalid audio channel metadata",
                )
            })?;
        if stream_type != "Audio" {
            return Err(ApiError::service_unavailable(
                "VOD provider returned inconsistent audio metadata",
            ));
        }
        sanitized.insert("Channels".to_string(), serde_json::json!(channels));
    }
    Ok(serde_json::Value::Object(sanitized))
}

fn sanitize_plugin_vod_media_streams(
    streams: &[serde_json::Value],
) -> Result<Vec<serde_json::Value>, ApiError> {
    if streams.len() > PLUGIN_VOD_MAX_MEDIA_STREAMS {
        return Err(ApiError::service_unavailable(
            "VOD provider returned too many media streams",
        ));
    }
    let mut indices = HashSet::with_capacity(streams.len());
    let mut video_count = 0usize;
    let mut sanitized = Vec::with_capacity(streams.len());
    for stream in streams {
        let stream = sanitize_plugin_vod_media_stream(stream)?;
        let index = stream
            .get("Index")
            .and_then(json_value_i64)
            .ok_or_else(|| {
                ApiError::service_unavailable("VOD provider returned an invalid media stream")
            })?;
        if !indices.insert(index) {
            return Err(ApiError::service_unavailable(
                "VOD provider returned duplicate media stream indices",
            ));
        }
        if json_string_field(&stream, "Type").as_deref() == Some("Video") {
            video_count = video_count.saturating_add(1);
            if video_count > 1 {
                return Err(ApiError::service_unavailable(
                    "VOD provider returned multiple selected video variants",
                ));
            }
        }
        sanitized.push(stream);
    }
    Ok(sanitized)
}

/// Returns codec evidence that can participate in client-profile matching. Some providers expose
/// the MPEG-TS container in a field named `videoFormat` and use `unknown` when no audio codec was
/// supplied. Those values are safe strings, but treating them as elementary-stream codecs makes
/// both native TS discovery and browser HLS negotiation fail with `NoCompatibleStream`.
fn usable_plugin_vod_codec_hint(value: Option<&str>, stream_type: &str) -> Option<String> {
    let value = value?.trim();
    if value.is_empty()
        || value.len() > 32
        || !value
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'_' | b'-'))
    {
        return None;
    }
    let normalized = match value.to_ascii_lowercase().as_str() {
        // Jellyfin device profiles use FFmpeg's canonical decoder name.
        "h265" => "hevc".to_string(),
        value => value.to_string(),
    };
    if normalized == "unknown"
        || normalized == "unspecified"
        || normalized == "none"
        || ((stream_type.eq_ignore_ascii_case("Video")
            || stream_type.eq_ignore_ascii_case("Audio"))
            && matches!(
                normalized.as_str(),
                "ts" | "mpegts" | "mpeg-ts" | "mpeg2ts" | "mp2t" | "hls" | "m3u8"
            ))
    {
        return None;
    }
    Some(normalized)
}

fn repair_plugin_vod_placeholder_codecs(
    streams: &mut [serde_json::Value],
    playback: &VodPlaybackResult,
) {
    let video_hint =
        usable_plugin_vod_codec_hint(playback.delivery.video_codec.as_deref(), "Video");
    let audio_hint =
        usable_plugin_vod_codec_hint(playback.delivery.audio_codec.as_deref(), "Audio");

    for stream in streams {
        let Some(object) = stream.as_object_mut() else {
            continue;
        };
        let Some(stream_type) = object
            .get("Type")
            .and_then(serde_json::Value::as_str)
            .map(str::to_string)
        else {
            continue;
        };
        let delivery_hint = if stream_type.eq_ignore_ascii_case("Video") {
            video_hint.as_ref()
        } else if stream_type.eq_ignore_ascii_case("Audio") {
            audio_hint.as_ref()
        } else {
            continue;
        };
        let current_codec = object.get("Codec").and_then(serde_json::Value::as_str);
        if let Some(codec) = usable_plugin_vod_codec_hint(current_codec, &stream_type) {
            object.insert("Codec".to_string(), serde_json::json!(codec));
            continue;
        }
        if let Some(delivery_hint) = delivery_hint {
            object.insert("Codec".to_string(), serde_json::json!(delivery_hint));
        } else {
            // Absence is honest codec evidence. Keeping `unknown` or the container alias would
            // instead turn it into a definite mismatch against every ordinary device profile.
            object.remove("Codec");
        }
    }
}

fn apply_plugin_vod_playback_descriptor(
    item: &mut MediaItem,
    playback: &VodPlaybackResult,
) -> Result<(), ApiError> {
    if !opaque_live_tv_delivery_is_safe_for_direct_proxy(playback) {
        return Err(ApiError::service_unavailable(
            "VOD provider did not authorize a safe direct stream",
        ));
    }
    // This path remains an opaque routing token. Appending a safe filename is enough for the
    // normal Jellyfin media-source serializer to advertise `Container=ts` and for clients which
    // synthesize their own stream URL to request `/stream.ts`; no provider URL becomes durable.
    let path = item.path.trim_end_matches('/');
    item.path = format!("{path}/stream.ts");
    let mut media_streams = playback.media_streams.clone();
    // Prefer fresh provider track descriptors so language/subtitle selection remains exact, but
    // do not let container aliases or explicit placeholders masquerade as elementary-stream
    // codecs. Valid fresh codecs always win, as do valid delivery hints when a provider supplies
    // them separately. We deliberately do not restore the catalogue's provisional h264/aac
    // descriptors: playback resolution may reveal a different codec and must remain authoritative.
    repair_plugin_vod_placeholder_codecs(&mut media_streams, playback);
    item.media_streams = media_streams;
    Ok(())
}

async fn invoke_plugin_vod_provider_action(
    db: &Database,
    plugin_id: &str,
    tuner_id: &str,
    action: &str,
    mut request_arguments: serde_json::Value,
    user_context: Option<jellyrin_plugin_sdk::PluginUserContext>,
) -> Result<ZeroizingJsonValue, ApiError> {
    let jit_lane = external_provider_jit_lane(tuner_id)
        .ok_or_else(|| ApiError::service_unavailable("VOD provider tuner is unavailable"))?;
    let _admission_guard = external_plugin_host_admission_slot(plugin_id, &jit_lane)
        .await
        .acquire_owned()
        .await
        .map_err(|_| ApiError::service_unavailable("VOD library provider is unavailable"))?;
    let _provider_session_guard = try_external_provider_jit_session(plugin_id, tuner_id).await?;
    let security_slot = external_plugin_security_slot(plugin_id).await;
    let _security_guard = security_slot.read_owned().await;
    let persisted_tuner_config = db
        .live_tv_tuner_configuration_by_id(tuner_id)
        .await?
        .ok_or_else(|| ApiError::service_unavailable("VOD provider tuner is unavailable"))?;
    if contains_plaintext_provider_secret(&persisted_tuner_config) {
        return Err(ApiError::service_unavailable(
            "VOD provider tuner must use an external secret reference",
        ));
    }
    let tuner_type = json_string_field(&persisted_tuner_config, "Type")
        .ok_or_else(|| ApiError::service_unavailable("VOD provider tuner route is unavailable"))?;
    if !live_tv_plugin_id_from_payload(&persisted_tuner_config, &tuner_type)
        .is_some_and(|routed| routed.eq_ignore_ascii_case(plugin_id))
    {
        return Err(ApiError::service_unavailable(
            "VOD provider tuner binding is invalid",
        ));
    }
    let plugin = db
        .installed_plugin_json(plugin_id)
        .await?
        .filter(|plugin| {
            json_string_field(plugin, "Status").as_deref() == Some("Active")
                && plugin_string_array(plugin.get("Capabilities"))
                    .iter()
                    .any(|capability| {
                        capability.eq_ignore_ascii_case(CAPABILITY_VOD_LIBRARY_PROVIDER)
                    })
        })
        .ok_or_else(|| ApiError::service_unavailable("VOD library provider is unavailable"))?;
    let Some((runtime, runtime_name, error_prefix, host_path)) = plugin_runtime_host_path(&plugin)
    else {
        return Err(ApiError::service_unavailable(
            "VOD library provider runtime is unavailable",
        ));
    };
    let context = VodPlaybackContext {
        // This value belongs to the provider/sidecar configuration. Never substitute the
        // viewer's ConnectInfo address: providers may sign against the outbound egress address.
        egress_ip: json_string_field(&persisted_tuner_config, "EgressIp"),
        delivery_capabilities: LiveTvDeliveryCapabilities {
            direct_proxy: true,
            hls_remux: false,
        },
    };
    let context = serde_json::to_value(context)
        .map_err(|_| ApiError::internal("invalid VOD provider context"))?;
    let request_object = request_arguments
        .as_object_mut()
        .ok_or_else(|| ApiError::internal("invalid VOD provider action arguments"))?;
    for (field, value) in context.as_object().into_iter().flatten() {
        request_object.insert(field.clone(), value.clone());
    }
    let mut request = vod_library_plugin_provider_request(
        db,
        &plugin,
        &persisted_tuner_config,
        action,
        request_arguments,
    )
    .await
    .map_err(|_| ApiError::service_unavailable("VOD provider credentials are unavailable"))?;
    if let Some(user_context) = user_context {
        request = request.with_user_context(user_context);
    }
    let arguments = serde_json::to_value(request)
        .map_err(|_| ApiError::internal("invalid VOD provider request"))?;
    let result = invoke_plugin_capability_via_runtime_host_path_with_timeout(
        &plugin,
        CAPABILITY_VOD_LIBRARY_PROVIDER,
        arguments,
        runtime,
        runtime_name,
        error_prefix,
        host_path,
        StdDuration::from_secs(15),
    )
    .await
    .map_err(|_| ApiError::service_unavailable("VOD provider resolution failed"))?
    .ok_or_else(|| ApiError::service_unavailable("VOD library provider runtime is unavailable"))?;
    Ok(ZeroizingJsonValue(result.value))
}

/// Resolves playback for one persisted plugin-VOD media item just-in-time. The `plugin-vod://`
/// path and its metadata only carry the opaque provider reference, so every stream asks the
/// provider plugin for a fresh signed URL through a fresh grant on the persistent, serial JIT
/// lane shared with metadata and subtitles for this tuner. The grant is scrubbed after the call;
/// the signed URL is never logged or persisted and returns as a `SensitiveUrl` that only
/// the internal proxy may expose. The provider contract remains direct-proxy MPEG-TS; Jellyrin may
/// feed those bytes to FFmpeg through its unguessable loopback relay when a browser requires HLS.
/// Callers must enforce `opaque_live_tv_delivery_is_safe_for_direct_proxy` before either path.
async fn resolve_plugin_vod_playback(
    db: &Database,
    plugin_id: &str,
    tuner_id: &str,
    provider_reference: &str,
    user_context: Option<jellyrin_plugin_sdk::PluginUserContext>,
) -> Result<VodPlaybackResult, ApiError> {
    let result = invoke_plugin_vod_provider_action(
        db,
        plugin_id,
        tuner_id,
        "ResolvePlayback",
        serde_json::json!({ "ProviderReference": provider_reference }),
        user_context,
    )
    .await?;

    if result
        .0
        .get("Status")
        .and_then(serde_json::Value::as_str)
        .is_some_and(|status| !status.eq_ignore_ascii_case("Executed"))
    {
        return Err(ApiError::service_unavailable(
            "VOD provider rejected playback resolution",
        ));
    }
    let playback_value = result
        .0
        .get("Playback")
        .or_else(|| result.0.get("Result"))
        .unwrap_or(&result.0);
    let mut playback = VodPlaybackResult::deserialize(playback_value)
        .map_err(|_| ApiError::service_unavailable("VOD provider response is invalid"))?;
    // The URL remains a `SensitiveUrl`, while track descriptors cross a strict allowlist so Web
    // can offer the provider's actual audio/subtitle choices. Unknown fields reject the whole
    // response instead of being silently copied or becoming a covert URL/token carrier.
    let sanitized_streams = sanitize_plugin_vod_media_streams(&playback.media_streams)?;
    playback
        .media_streams
        .iter_mut()
        .for_each(zeroize_json_value_strings);
    playback.media_streams = sanitized_streams;
    if let Some(expires_at) = playback.expires_at.as_deref() {
        let expires_at = OffsetDateTime::parse(expires_at, &Rfc3339)
            .map_err(|_| ApiError::service_unavailable("VOD provider expiry is invalid"))?;
        if expires_at <= OffsetDateTime::now_utc() + Duration::seconds(2) {
            return Err(ApiError::service_unavailable(
                "VOD provider source has expired",
            ));
        }
    }
    Ok(playback)
}

fn plugin_user_context(user: &User, token: &DeviceToken) -> jellyrin_plugin_sdk::PluginUserContext {
    jellyrin_plugin_sdk::PluginUserContext {
        user_id: user.id.to_string(),
        device_id: token.device_id.clone(),
        is_administrator: user.is_administrator,
    }
}

struct PluginVodSubtitleResolution {
    source_url: jellyrin_plugin_sdk::SensitiveUrl,
    format: String,
    _language: Option<String>,
    requires_provider_egress: bool,
}

/// Resolves one external subtitle by the public stream index returned by `ResolvePlayback`.
/// This is intentionally a separate scoped grant/action: the plugin may retrieve its runtime
/// subtitle URL, but neither that URL nor its provider-language selector is persisted in the
/// catalogue or returned by PlaybackInfo.
async fn resolve_plugin_vod_subtitle(
    db: &Database,
    plugin_id: &str,
    tuner_id: &str,
    provider_reference: &str,
    stream_index: i64,
    user_context: Option<jellyrin_plugin_sdk::PluginUserContext>,
) -> Result<PluginVodSubtitleResolution, ApiError> {
    if !(0..=PLUGIN_VOD_MAX_STREAM_INDEX).contains(&stream_index) {
        return Err(ApiError::not_found("Subtitle stream not found"));
    }
    let result = invoke_plugin_vod_provider_action(
        db,
        plugin_id,
        tuner_id,
        "ResolveSubtitle",
        serde_json::json!({
            "ProviderReference": provider_reference,
            "SubtitleStreamIndex": stream_index,
        }),
        user_context,
    )
    .await?;
    if !result
        .0
        .get("Status")
        .and_then(serde_json::Value::as_str)
        .is_some_and(|status| status.eq_ignore_ascii_case("Executed"))
    {
        return Err(ApiError::not_found("Subtitle stream not found"));
    }
    let subtitle = result
        .0
        .get("Subtitle")
        .or_else(|| result.0.get("Result"))
        .unwrap_or(&result.0)
        .as_object()
        .ok_or_else(|| ApiError::service_unavailable("VOD subtitle response is invalid"))?;
    const ALLOWED_FIELDS: &[&str] = &[
        "SourceUrl",
        "Format",
        "Language",
        "StreamIndex",
        "RequiresProviderEgress",
        "ExpiresAt",
    ];
    if subtitle
        .keys()
        .any(|field| !ALLOWED_FIELDS.contains(&field.as_str()))
    {
        return Err(ApiError::service_unavailable(
            "VOD provider returned an unsafe subtitle response",
        ));
    }
    if subtitle.get("StreamIndex").and_then(json_value_i64) != Some(stream_index) {
        return Err(ApiError::service_unavailable(
            "VOD provider returned a mismatched subtitle stream",
        ));
    }
    let source_url = subtitle
        .get("SourceUrl")
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| ApiError::service_unavailable("VOD subtitle source is unavailable"))?;
    // Validate the complete URL shape before wrapping it. DNS, redirect and egress-policy checks
    // are repeated when the bytes are fetched.
    validated_remote_media_url(source_url)?;
    let format = subtitle
        .get("Format")
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .map(str::to_ascii_lowercase)
        .filter(|format| matches!(format.as_str(), "vtt" | "webvtt" | "srt" | "ass" | "ssa"))
        .ok_or_else(|| ApiError::service_unavailable("VOD subtitle format is invalid"))?;
    let language = subtitle
        .get("Language")
        .map(|value| {
            value
                .as_str()
                .map(str::trim)
                .filter(|language| {
                    !language.is_empty()
                        && language.len() <= 64
                        && !language.chars().any(char::is_control)
                })
                .map(str::to_string)
                .ok_or_else(|| ApiError::service_unavailable("VOD subtitle language is invalid"))
        })
        .transpose()?;
    let requires_provider_egress = subtitle
        .get("RequiresProviderEgress")
        .and_then(serde_json::Value::as_bool)
        .ok_or_else(|| {
            ApiError::service_unavailable("VOD subtitle delivery contract is invalid")
        })?;
    if let Some(expires_at) = subtitle.get("ExpiresAt") {
        let expires_at = expires_at
            .as_str()
            .and_then(|expires_at| OffsetDateTime::parse(expires_at, &Rfc3339).ok())
            .ok_or_else(|| ApiError::service_unavailable("VOD subtitle expiry is invalid"))?;
        if expires_at <= OffsetDateTime::now_utc() + Duration::seconds(2) {
            return Err(ApiError::service_unavailable(
                "VOD subtitle source has expired",
            ));
        }
    }
    Ok(PluginVodSubtitleResolution {
        source_url: jellyrin_plugin_sdk::SensitiveUrl::new(source_url.to_string()),
        format,
        _language: language,
        requires_provider_egress,
    })
}

struct PluginVodResolvedMetadata {
    overview: Option<String>,
    image_url: Option<Zeroizing<String>>,
    runtime_ticks: Option<i64>,
}

const PLUGIN_VOD_METADATA_CACHE_TTL_SECONDS: i64 = 24 * 60 * 60;
const PLUGIN_VOD_MAX_RUNTIME_TICKS: i64 = 7 * 24 * 60 * 60 * 10_000_000;
const PLUGIN_VOD_RUNTIME_RESOLVED_AT_FIELD: &str = "PluginVodRuntimeResolvedAt";
const PLUGIN_VOD_MEDIA_RUNTIME_PROBE_VERSION: i64 = 1;
const PLUGIN_VOD_MEDIA_RUNTIME_MISSING_TTL_SECONDS: i64 = 6 * 60 * 60;
const PLUGIN_VOD_MEDIA_RUNTIME_FAILED_TTL_SECONDS: i64 = 5 * 60;

fn bounded_plugin_vod_runtime_ticks(runtime_ticks: Option<i64>) -> Option<i64> {
    runtime_ticks.filter(|ticks| (1..=PLUGIN_VOD_MAX_RUNTIME_TICKS).contains(ticks))
}

fn plugin_vod_media_runtime_probe_is_fresh(metadata: &serde_json::Value) -> bool {
    let Some(marker) = json_field_case_insensitive(metadata, PLUGIN_VOD_MEDIA_RUNTIME_PROBE_FIELD)
        .and_then(serde_json::Value::as_object)
    else {
        return false;
    };
    if marker
        .iter()
        .find(|(key, _)| key.eq_ignore_ascii_case("Version"))
        .and_then(|(_, value)| value.as_i64())
        != Some(PLUGIN_VOD_MEDIA_RUNTIME_PROBE_VERSION)
    {
        return false;
    }
    let Some(outcome) = marker
        .iter()
        .find(|(key, _)| key.eq_ignore_ascii_case("Outcome"))
        .and_then(|(_, value)| value.as_str())
    else {
        return false;
    };
    let Some(resolved_at) = marker
        .iter()
        .find(|(key, _)| key.eq_ignore_ascii_case("ResolvedAt"))
        .and_then(|(_, value)| value.as_i64())
    else {
        return false;
    };
    let ttl = if outcome.eq_ignore_ascii_case("Missing") {
        PLUGIN_VOD_MEDIA_RUNTIME_MISSING_TTL_SECONDS
    } else if outcome.eq_ignore_ascii_case("Failed") {
        PLUGIN_VOD_MEDIA_RUNTIME_FAILED_TTL_SECONDS
    } else {
        return false;
    };
    let age = OffsetDateTime::now_utc()
        .unix_timestamp()
        .saturating_sub(resolved_at);
    (0..ttl).contains(&age)
}

#[cfg(test)]
fn set_plugin_vod_media_runtime_probe_marker(
    metadata: &mut serde_json::Value,
    outcome: &'static str,
    resolved_at: i64,
) {
    metadata[PLUGIN_VOD_MEDIA_RUNTIME_PROBE_FIELD] =
        plugin_vod_media_runtime_probe_marker(outcome, resolved_at);
}

fn plugin_vod_media_runtime_probe_marker(
    outcome: &'static str,
    resolved_at: i64,
) -> serde_json::Value {
    serde_json::json!({
        "Version": PLUGIN_VOD_MEDIA_RUNTIME_PROBE_VERSION,
        "Outcome": outcome,
        "ResolvedAt": resolved_at,
    })
}

#[derive(Default)]
struct PluginVodSafeMetadata {
    overview: Option<String>,
    runtime_ticks: Option<i64>,
}

#[derive(Clone)]
struct PluginVodMetadataTarget {
    owner_id: String,
    source_item_id: Uuid,
    scope: &'static str,
    overview_field: &'static str,
    resolved_at_field: &'static str,
    image_available_field: &'static str,
}

fn plugin_vod_metadata_resolution_is_fresh(
    metadata: &serde_json::Value,
    target: &PluginVodMetadataTarget,
) -> bool {
    plugin_vod_resolution_marker_is_fresh(metadata, target.resolved_at_field)
}

fn plugin_vod_resolution_marker_is_fresh(metadata: &serde_json::Value, field: &str) -> bool {
    json_field_case_insensitive(metadata, field)
        .and_then(serde_json::Value::as_i64)
        .is_some_and(|resolved_at| {
            let age = OffsetDateTime::now_utc()
                .unix_timestamp()
                .saturating_sub(resolved_at);
            (0..PLUGIN_VOD_METADATA_CACHE_TTL_SECONDS).contains(&age)
        })
}

fn plugin_vod_metadata_overview(
    metadata: &serde_json::Value,
    target: &PluginVodMetadataTarget,
) -> Option<String> {
    json_field_case_insensitive(metadata, target.overview_field)
        .and_then(serde_json::Value::as_str)
        .and_then(|overview| safe_live_tv_plugin_text(overview, 16 * 1024))
}

fn plugin_vod_image_resolution_complete(
    metadata: &serde_json::Value,
    target: &PluginVodMetadataTarget,
    cached_image_present: bool,
) -> bool {
    match json_field_case_insensitive(metadata, target.image_available_field)
        .and_then(serde_json::Value::as_bool)
    {
        Some(true) => cached_image_present,
        Some(false) => true,
        None => false,
    }
}

fn apply_safe_plugin_vod_resolution(
    metadata: &mut serde_json::Value,
    target: &PluginVodMetadataTarget,
    overview: Option<&str>,
    image_available: bool,
    resolved_at: i64,
) {
    remove_plugin_vod_external_image_fields(metadata);
    if let Some(overview) = overview {
        metadata[target.overview_field] = serde_json::Value::String(overview.to_string());
    }
    metadata[target.image_available_field] = serde_json::Value::Bool(image_available);
    metadata[target.resolved_at_field] = serde_json::json!(resolved_at);
}

fn remove_plugin_vod_external_image_fields(metadata: &mut serde_json::Value) -> bool {
    let Some(object) = metadata.as_object_mut() else {
        return false;
    };
    let previous_len = object.len();
    object.retain(|key, _| {
        let normalized = key
            .chars()
            .filter(|character| character.is_ascii_alphanumeric())
            .flat_map(char::to_lowercase)
            .collect::<String>();
        !matches!(
            normalized.as_str(),
            "imageurl"
                | "primaryimageurl"
                | "seriesimageurl"
                | "seriesprimaryimageurl"
                | "backdropimageurl"
                | "parentbackdropimageurl"
        )
    });
    object.len() != previous_len
}

async fn fetch_plugin_vod_remote_image(source_url: &str) -> Result<Vec<u8>, ApiError> {
    if let Err(error) = validated_remote_media_url(source_url) {
        log_plugin_vod_artwork_failure(PluginVodArtworkFailure::InvalidSource);
        return Err(error);
    }
    let proxy = match configured_provider_egress_proxy() {
        Ok(proxy) => proxy,
        Err(_) => {
            log_plugin_vod_artwork_failure(PluginVodArtworkFailure::MissingProxy);
            return Err(ApiError::service_unavailable(
                "VOD provider egress proxy is not configured",
            ));
        }
    };
    let response = match send_sensitive_remote_live_request_with_proxy(
        source_url,
        true,
        Some(&proxy),
        StdDuration::from_secs(15),
    )
    .await
    {
        Ok(response) => response,
        Err(error) => {
            log_plugin_vod_artwork_failure(plugin_vod_artwork_request_failure(&error));
            return Err(error);
        }
    };
    if !response.status().is_success() {
        let failure = if response.status().is_client_error() {
            PluginVodArtworkFailure::UpstreamClientError
        } else if response.status().is_server_error() {
            PluginVodArtworkFailure::UpstreamServerError
        } else {
            PluginVodArtworkFailure::UpstreamOtherStatus
        };
        log_plugin_vod_artwork_failure(failure);
        return Err(ApiError::service_unavailable(
            "VOD provider artwork is unavailable",
        ));
    }
    let nonstandard_content_type = plugin_vod_artwork_content_type_is_nonstandard(
        response
            .headers()
            .get(header::CONTENT_TYPE)
            .and_then(|value| value.to_str().ok()),
    );
    let bytes = match read_bounded_remote_image_body(response, IMAGE_UPLOAD_LIMIT_BYTES).await {
        Ok(bytes) => bytes,
        Err(error) => {
            let failure = if error.status() == StatusCode::BAD_REQUEST {
                PluginVodArtworkFailure::BodyTooLarge
            } else {
                PluginVodArtworkFailure::BodyInterrupted
            };
            log_plugin_vod_artwork_failure(failure);
            return Err(error);
        }
    };
    validate_plugin_vod_image_payload(&bytes, nonstandard_content_type)?;
    Ok(bytes)
}

fn configured_provider_egress_proxy() -> Result<String, std::env::VarError> {
    #[cfg(test)]
    if let Some(proxy) = TEST_PROVIDER_EGRESS_PROXY
        .get_or_init(|| StdMutex::new(None))
        .lock()
        .expect("test provider egress proxy lock poisoned")
        .clone()
    {
        return Ok(proxy);
    }
    std::env::var("JELLYRIN_PROVIDER_EGRESS_PROXY")
}

fn plugin_vod_image_payload_len_is_allowed(length: usize) -> bool {
    length <= IMAGE_UPLOAD_LIMIT_BYTES
}

fn plugin_vod_artwork_content_type_is_nonstandard(value: Option<&str>) -> bool {
    value
        .and_then(|value| value.split(';').next())
        .map(str::trim)
        .is_some_and(|value| {
            ![
                "image/jpeg",
                "image/jpg",
                "image/png",
                "image/webp",
                "image/gif",
                "application/octet-stream",
            ]
            .iter()
            .any(|candidate| value.eq_ignore_ascii_case(candidate))
        })
}

fn complete_plugin_vod_raster_payload(bytes: &[u8], extension: &str) -> bool {
    match extension {
        "png" => complete_plugin_vod_png(bytes),
        "jpg" => complete_plugin_vod_jpeg(bytes),
        "gif" => complete_plugin_vod_gif(bytes),
        "webp" => complete_plugin_vod_webp(bytes),
        _ => false,
    }
}

fn complete_plugin_vod_png(bytes: &[u8]) -> bool {
    const SIGNATURE: &[u8] = &[137, 80, 78, 71, 13, 10, 26, 10];
    if !bytes.starts_with(SIGNATURE) {
        return false;
    }
    let mut offset = SIGNATURE.len();
    let mut chunk_index = 0_usize;
    let mut seen_idat = false;
    let mut idat_finished = false;
    while offset < bytes.len() {
        let Some(type_end) = offset.checked_add(8) else {
            return false;
        };
        if type_end > bytes.len() {
            return false;
        }
        let length = u32::from_be_bytes(bytes[offset..offset + 4].try_into().unwrap()) as usize;
        let Some(data_end) = type_end.checked_add(length) else {
            return false;
        };
        let Some(chunk_end) = data_end.checked_add(4) else {
            return false;
        };
        if chunk_end > bytes.len() {
            return false;
        }
        let chunk_type = &bytes[offset + 4..type_end];
        let chunk_data = &bytes[type_end..data_end];
        if !chunk_type.iter().all(u8::is_ascii_alphabetic) {
            return false;
        }
        if chunk_index == 0 {
            if chunk_type != b"IHDR" || length != 13 {
                return false;
            }
            let valid_depth = matches!(
                (chunk_data[9], chunk_data[8]),
                (0, 1 | 2 | 4 | 8 | 16)
                    | (2, 8 | 16)
                    | (3, 1 | 2 | 4 | 8)
                    | (4, 8 | 16)
                    | (6, 8 | 16)
            );
            if !valid_depth
                || chunk_data[10] != 0
                || chunk_data[11] != 0
                || !matches!(chunk_data[12], 0 | 1)
            {
                return false;
            }
        } else if chunk_type == b"IHDR" {
            return false;
        }
        if chunk_type == b"IDAT" {
            if chunk_index == 0 || idat_finished || chunk_data.is_empty() {
                return false;
            }
            seen_idat = true;
        } else if seen_idat {
            idat_finished = true;
        }
        if chunk_type == b"IEND" {
            return length == 0 && seen_idat && chunk_end == bytes.len();
        }
        offset = chunk_end;
        chunk_index = chunk_index.saturating_add(1);
    }
    false
}

fn complete_plugin_vod_jpeg(bytes: &[u8]) -> bool {
    if bytes.len() < 4 || !bytes.starts_with(&[0xff, 0xd8]) {
        return false;
    }
    let mut offset = 2_usize;
    let mut in_scan = false;
    let mut seen_sof = false;
    let mut seen_sos = false;
    let mut seen_entropy = false;
    let mut seen_quantization_table = false;
    let mut seen_coding_table = false;
    loop {
        let marker = if in_scan {
            loop {
                let Some(&byte) = bytes.get(offset) else {
                    return false;
                };
                offset = offset.saturating_add(1);
                if byte != 0xff {
                    seen_entropy = true;
                    continue;
                }
                while bytes.get(offset) == Some(&0xff) {
                    offset = offset.saturating_add(1);
                }
                let Some(&marker) = bytes.get(offset) else {
                    return false;
                };
                offset = offset.saturating_add(1);
                if marker == 0x00 {
                    seen_entropy = true;
                    continue;
                }
                if (0xd0..=0xd7).contains(&marker) {
                    continue;
                }
                in_scan = false;
                break marker;
            }
        } else {
            if bytes.get(offset) != Some(&0xff) {
                return false;
            }
            while bytes.get(offset) == Some(&0xff) {
                offset = offset.saturating_add(1);
            }
            let Some(&marker) = bytes.get(offset) else {
                return false;
            };
            offset = offset.saturating_add(1);
            marker
        };
        match marker {
            0xd9 => return seen_sof && seen_sos && seen_entropy && offset == bytes.len(),
            0x00 | 0x01 | 0xd0..=0xd8 => return false,
            _ => {}
        }
        let Some(length_end) = offset.checked_add(2) else {
            return false;
        };
        if length_end > bytes.len() {
            return false;
        }
        let segment_length = usize::from(u16::from_be_bytes(
            bytes[offset..length_end].try_into().unwrap(),
        ));
        if segment_length < 2 {
            return false;
        }
        let Some(segment_end) = offset.checked_add(segment_length) else {
            return false;
        };
        if segment_end > bytes.len() {
            return false;
        }
        let segment = &bytes[length_end..segment_end];
        if matches!(
            marker,
            0xc0 | 0xc1
                | 0xc2
                | 0xc3
                | 0xc5
                | 0xc6
                | 0xc7
                | 0xc9
                | 0xca
                | 0xcb
                | 0xcd
                | 0xce
                | 0xcf
        ) {
            if seen_sof || segment.len() < 6 {
                return false;
            }
            let components = usize::from(segment[5]);
            if components == 0
                || segment.len() != 6_usize.saturating_add(components.saturating_mul(3))
                || !matches!(segment[0], 8 | 12 | 16)
            {
                return false;
            }
            seen_sof = true;
        } else if marker == 0xdb {
            seen_quantization_table = !segment.is_empty();
        } else if matches!(marker, 0xc4 | 0xcc) {
            seen_coding_table = !segment.is_empty();
        } else if marker == 0xda {
            if !seen_sof || !seen_quantization_table || !seen_coding_table || segment.is_empty() {
                return false;
            }
            let components = usize::from(segment[0]);
            if components == 0
                || segment.len() != 4_usize.saturating_add(components.saturating_mul(2))
            {
                return false;
            }
            seen_sos = true;
            in_scan = true;
        }
        offset = segment_end;
    }
}

fn plugin_vod_gif_sub_blocks_end(bytes: &[u8], mut offset: usize) -> Option<usize> {
    loop {
        let length = usize::from(*bytes.get(offset)?);
        offset = offset.checked_add(1)?;
        if length == 0 {
            return Some(offset);
        }
        offset = offset.checked_add(length)?;
        if offset > bytes.len() {
            return None;
        }
    }
}

fn complete_plugin_vod_gif(bytes: &[u8]) -> bool {
    if bytes.len() < 14 || !(bytes.starts_with(b"GIF87a") || bytes.starts_with(b"GIF89a")) {
        return false;
    }
    let packed = bytes[10];
    let mut offset = 13_usize;
    if packed & 0x80 != 0 {
        let entries = 1_usize << (usize::from(packed & 0x07) + 1);
        let Some(color_table_bytes) = entries.checked_mul(3) else {
            return false;
        };
        let Some(next) = offset.checked_add(color_table_bytes) else {
            return false;
        };
        if next > bytes.len() {
            return false;
        }
        offset = next;
    }
    let mut seen_image = false;
    loop {
        let Some(&introducer) = bytes.get(offset) else {
            return false;
        };
        offset = offset.saturating_add(1);
        match introducer {
            0x3b => return seen_image && offset == bytes.len(),
            0x21 => {
                if bytes.get(offset).is_none() {
                    return false;
                }
                offset = offset.saturating_add(1);
                let Some(next) = plugin_vod_gif_sub_blocks_end(bytes, offset) else {
                    return false;
                };
                offset = next;
            }
            0x2c => {
                let Some(descriptor_end) = offset.checked_add(9) else {
                    return false;
                };
                if descriptor_end > bytes.len() {
                    return false;
                }
                let image_packed = bytes[offset + 8];
                offset = descriptor_end;
                if image_packed & 0x80 != 0 {
                    let entries = 1_usize << (usize::from(image_packed & 0x07) + 1);
                    let Some(color_table_bytes) = entries.checked_mul(3) else {
                        return false;
                    };
                    let Some(next) = offset.checked_add(color_table_bytes) else {
                        return false;
                    };
                    if next > bytes.len() {
                        return false;
                    }
                    offset = next;
                }
                let Some(&minimum_code_size) = bytes.get(offset) else {
                    return false;
                };
                if !(2..=8).contains(&minimum_code_size) {
                    return false;
                }
                offset = offset.saturating_add(1);
                let Some(next) = plugin_vod_gif_sub_blocks_end(bytes, offset) else {
                    return false;
                };
                offset = next;
                seen_image = true;
            }
            _ => return false,
        }
    }
}

fn complete_plugin_vod_webp(bytes: &[u8]) -> bool {
    if bytes.len() < 20 || &bytes[..4] != b"RIFF" || &bytes[8..12] != b"WEBP" {
        return false;
    }
    let declared_size = u32::from_le_bytes(bytes[4..8].try_into().unwrap()) as usize;
    if declared_size.checked_add(8) != Some(bytes.len()) {
        return false;
    }
    let mut offset = 12_usize;
    let mut seen_image_payload = false;
    while offset < bytes.len() {
        let Some(header_end) = offset.checked_add(8) else {
            return false;
        };
        if header_end > bytes.len() {
            return false;
        }
        let chunk_type = &bytes[offset..offset + 4];
        if !matches!(
            chunk_type,
            b"VP8 " | b"VP8L" | b"VP8X" | b"ALPH" | b"ANIM" | b"ANMF" | b"ICCP" | b"EXIF" | b"XMP "
        ) {
            return false;
        }
        let chunk_length =
            u32::from_le_bytes(bytes[offset + 4..header_end].try_into().unwrap()) as usize;
        let Some(data_end) = header_end.checked_add(chunk_length) else {
            return false;
        };
        let Some(chunk_end) = data_end.checked_add(chunk_length & 1) else {
            return false;
        };
        if chunk_end > bytes.len() || (chunk_length & 1 == 1 && bytes[data_end] != 0) {
            return false;
        }
        if matches!(chunk_type, b"VP8 " | b"VP8L" | b"ANMF") && chunk_length > 0 {
            seen_image_payload = true;
        }
        offset = chunk_end;
    }
    offset == bytes.len() && seen_image_payload
}

fn validate_plugin_vod_image_payload(
    bytes: &[u8],
    nonstandard_content_type: bool,
) -> Result<(), ApiError> {
    if !plugin_vod_image_payload_len_is_allowed(bytes.len()) {
        log_plugin_vod_artwork_failure(PluginVodArtworkFailure::BodyTooLarge);
        return Err(ApiError::bad_request("Remote image file is too large"));
    }
    if bytes.is_empty() {
        log_plugin_vod_artwork_failure(PluginVodArtworkFailure::EmptyBody);
        return Err(ApiError::service_unavailable(
            "VOD provider artwork payload is invalid",
        ));
    }
    let format = image_format_from_bytes(bytes);
    if format.extension == "bin" {
        log_plugin_vod_artwork_failure(PluginVodArtworkFailure::UnknownFormat);
        return Err(ApiError::service_unavailable(
            "VOD provider artwork payload is invalid",
        ));
    }
    if !complete_plugin_vod_raster_payload(bytes, format.extension) {
        log_plugin_vod_artwork_failure(PluginVodArtworkFailure::MalformedRaster);
        return Err(ApiError::service_unavailable(
            "VOD provider artwork payload is invalid",
        ));
    }
    if !safe_remote_image_dimensions(bytes) {
        log_plugin_vod_artwork_failure(PluginVodArtworkFailure::InvalidDimensions);
        return Err(ApiError::service_unavailable(
            "VOD provider artwork payload is invalid",
        ));
    }
    if nonstandard_content_type {
        tracing::info!(
            action = "ResolveArtwork",
            phase = "content_type",
            reason = "nonstandard_but_valid",
            "VOD artwork accepted by payload signature"
        );
    }
    Ok(())
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PluginVodArtworkFailure {
    InvalidSource,
    MissingProxy,
    InvalidRequest,
    RequestDenied,
    RequestUnavailable,
    RequestFailed,
    UpstreamClientError,
    UpstreamServerError,
    UpstreamOtherStatus,
    BodyTooLarge,
    BodyInterrupted,
    EmptyBody,
    UnknownFormat,
    MalformedRaster,
    InvalidDimensions,
    CacheWriteFailed,
}

impl PluginVodArtworkFailure {
    const fn labels(self) -> (&'static str, &'static str) {
        match self {
            Self::InvalidSource => ("source_validation", "invalid_source"),
            Self::MissingProxy => ("egress_configuration", "missing_proxy"),
            Self::InvalidRequest => ("egress_request", "invalid_request"),
            Self::RequestDenied => ("egress_request", "request_denied"),
            Self::RequestUnavailable => ("egress_request", "request_unavailable"),
            Self::RequestFailed => ("egress_request", "request_failed"),
            Self::UpstreamClientError => ("upstream_status", "upstream_client_error"),
            Self::UpstreamServerError => ("upstream_status", "upstream_server_error"),
            Self::UpstreamOtherStatus => ("upstream_status", "upstream_other_status"),
            Self::BodyTooLarge => ("body", "body_too_large"),
            Self::BodyInterrupted => ("body", "body_interrupted"),
            Self::EmptyBody => ("payload", "empty_body"),
            Self::UnknownFormat => ("payload", "unknown_format"),
            Self::MalformedRaster => ("payload", "malformed_raster"),
            Self::InvalidDimensions => ("payload", "invalid_dimensions"),
            Self::CacheWriteFailed => ("cache_write", "cache_write_failed"),
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct PluginVodArtworkFailureTelemetry {
    action: &'static str,
    phase: &'static str,
    reason: &'static str,
}

fn plugin_vod_artwork_failure_telemetry(
    failure: PluginVodArtworkFailure,
) -> PluginVodArtworkFailureTelemetry {
    let (phase, reason) = failure.labels();
    PluginVodArtworkFailureTelemetry {
        action: "ResolveArtwork",
        phase,
        reason,
    }
}

fn plugin_vod_artwork_request_failure(error: &ApiError) -> PluginVodArtworkFailure {
    match error.status() {
        StatusCode::BAD_REQUEST => PluginVodArtworkFailure::InvalidRequest,
        StatusCode::FORBIDDEN => PluginVodArtworkFailure::RequestDenied,
        StatusCode::SERVICE_UNAVAILABLE | StatusCode::GATEWAY_TIMEOUT => {
            PluginVodArtworkFailure::RequestUnavailable
        }
        _ => PluginVodArtworkFailure::RequestFailed,
    }
}

fn log_plugin_vod_artwork_failure(failure: PluginVodArtworkFailure) {
    let telemetry = plugin_vod_artwork_failure_telemetry(failure);
    tracing::warn!(
        action = telemetry.action,
        phase = telemetry.phase,
        reason = telemetry.reason,
        "VOD artwork pipeline failed"
    );
}

fn safe_remote_image_dimensions(bytes: &[u8]) -> bool {
    const MAX_DIMENSION: u32 = 16_384;
    const MAX_PIXELS: u64 = 100_000_000;
    image_dimensions_from_bytes(bytes).is_some_and(|(width, height)| {
        width > 0
            && height > 0
            && width <= MAX_DIMENSION
            && height <= MAX_DIMENSION
            && u64::from(width).saturating_mul(u64::from(height)) <= MAX_PIXELS
    })
}

fn image_dimensions_from_bytes(bytes: &[u8]) -> Option<(u32, u32)> {
    if bytes.starts_with(&[137, 80, 78, 71, 13, 10, 26, 10]) && bytes.len() >= 24 {
        return Some((
            u32::from_be_bytes(bytes[16..20].try_into().ok()?),
            u32::from_be_bytes(bytes[20..24].try_into().ok()?),
        ));
    }
    if (bytes.starts_with(b"GIF87a") || bytes.starts_with(b"GIF89a")) && bytes.len() >= 10 {
        return Some((
            u16::from_le_bytes(bytes[6..8].try_into().ok()?).into(),
            u16::from_le_bytes(bytes[8..10].try_into().ok()?).into(),
        ));
    }
    if bytes.len() >= 30 && &bytes[0..4] == b"RIFF" && &bytes[8..12] == b"WEBP" {
        if &bytes[12..16] == b"VP8X" {
            let width = 1 + u32::from_le_bytes([bytes[24], bytes[25], bytes[26], 0]);
            let height = 1 + u32::from_le_bytes([bytes[27], bytes[28], bytes[29], 0]);
            return Some((width, height));
        }
        if &bytes[12..16] == b"VP8 " && bytes.len() >= 30 && bytes[23..26] == [0x9d, 0x01, 0x2a] {
            let width = u16::from_le_bytes(bytes[26..28].try_into().ok()?) & 0x3fff;
            let height = u16::from_le_bytes(bytes[28..30].try_into().ok()?) & 0x3fff;
            return Some((width.into(), height.into()));
        }
        if &bytes[12..16] == b"VP8L" && bytes.len() >= 25 && bytes[20] == 0x2f {
            let bits = u32::from_le_bytes(bytes[21..25].try_into().ok()?);
            return Some(((bits & 0x3fff) + 1, ((bits >> 14) & 0x3fff) + 1));
        }
    }
    if bytes.starts_with(&[0xff, 0xd8, 0xff]) {
        let mut offset = 2_usize;
        while offset.saturating_add(4) <= bytes.len() {
            if bytes[offset] != 0xff {
                offset = offset.saturating_add(1);
                continue;
            }
            let marker = bytes[offset + 1];
            offset = offset.saturating_add(2);
            if matches!(marker, 0xd8 | 0xd9) || (0xd0..=0xd7).contains(&marker) {
                continue;
            }
            if offset.saturating_add(2) > bytes.len() {
                return None;
            }
            let segment_len = usize::from(u16::from_be_bytes(
                bytes[offset..offset + 2].try_into().ok()?,
            ));
            if segment_len < 2 || offset.saturating_add(segment_len) > bytes.len() {
                return None;
            }
            if matches!(
                marker,
                0xc0 | 0xc1
                    | 0xc2
                    | 0xc3
                    | 0xc5
                    | 0xc6
                    | 0xc7
                    | 0xc9
                    | 0xca
                    | 0xcb
                    | 0xcd
                    | 0xce
                    | 0xcf
            ) && segment_len >= 7
            {
                let height = u16::from_be_bytes(bytes[offset + 3..offset + 5].try_into().ok()?);
                let width = u16::from_be_bytes(bytes[offset + 5..offset + 7].try_into().ok()?);
                return Some((width.into(), height.into()));
            }
            offset = offset.saturating_add(segment_len);
        }
    }
    None
}

/// Resolves safe copy, runtime and artwork together. The only durable values are the synopsis, a
/// bounded runtime, a resolution timestamp and cached image bytes; the provider URL remains in
/// zeroizing memory.
async fn ensure_plugin_vod_metadata(
    state: &AppState,
    target: &PluginVodMetadataTarget,
) -> Result<PluginVodSafeMetadata, ApiError> {
    let lock_path = stored_image_owner_dir(state, ImageOwner::Item(&target.owner_id))
        .join(".plugin-vod-metadata");
    let lock = trickplay_tile_lock(&lock_path).await;
    let _guard = lock.lock().await;

    let mut metadata = metadata_payload_for_item(&state.db, target.source_item_id).await?;
    if plugin_vod_remote_reference(&metadata).is_none() {
        return Ok(PluginVodSafeMetadata::default());
    }
    let persisted_runtime_ticks = if target.scope == "Item" {
        bounded_plugin_vod_runtime_ticks(
            state
                .db
                .media_item_by_id_visible(target.source_item_id)
                .await
                .map_err(ApiError::from)?
                .and_then(|item| item.runtime_ticks),
        )
    } else {
        None
    };
    let removed_external_image_fields = remove_plugin_vod_external_image_fields(&mut metadata);
    let overview = plugin_vod_metadata_overview(&metadata, target);
    let cached_image =
        find_stored_image(state, ImageOwner::Item(&target.owner_id), "Primary", 0).await?;
    let image_resolution_complete =
        plugin_vod_image_resolution_complete(&metadata, target, cached_image.is_some());
    let metadata_resolution_fresh = plugin_vod_metadata_resolution_is_fresh(&metadata, target);
    let runtime_resolution_complete = target.scope != "Item"
        || persisted_runtime_ticks.is_some()
        || plugin_vod_resolution_marker_is_fresh(&metadata, PLUGIN_VOD_RUNTIME_RESOLVED_AT_FIELD);
    if metadata_resolution_fresh && image_resolution_complete && runtime_resolution_complete {
        if removed_external_image_fields {
            state
                .db
                .update_media_item_metadata(target.source_item_id, metadata)
                .await
                .map_err(ApiError::from)?;
        }
        return Ok(PluginVodSafeMetadata {
            overview,
            runtime_ticks: persisted_runtime_ticks,
        });
    }

    // Existing installations can have a fresh synopsis/image marker written by an older core
    // while the media-info runtime is still NULL. Resolve that missing Item field once, but keep
    // the already-complete image decision so an upgrade neither re-fetches artwork nor turns a
    // cached positive/negative result into the provider's latest response by accident.
    let preserve_cached_presentation = metadata_resolution_fresh && image_resolution_complete;
    let preserved_image_available = preserve_cached_presentation
        .then(|| {
            json_field_case_insensitive(&metadata, target.image_available_field)
                .and_then(serde_json::Value::as_bool)
        })
        .flatten();

    let resolved = resolve_plugin_vod_metadata(&state.db, &metadata, target.scope).await?;
    let resolved_overview = if preserve_cached_presentation {
        overview
    } else {
        resolved.overview.or(overview)
    };
    let runtime_ticks =
        bounded_plugin_vod_runtime_ticks(resolved.runtime_ticks.or(persisted_runtime_ticks));
    if let Some(overview) = resolved_overview.as_deref() {
        metadata[target.overview_field] = serde_json::Value::String(overview.to_string());
    }

    let image_available = if let Some(image_available) = preserved_image_available {
        image_available
    } else if let Some(image_url) = resolved.image_url.as_deref() {
        let bytes = match fetch_plugin_vod_remote_image(image_url).await {
            Ok(bytes) => bytes,
            Err(error) => {
                // Synopsis resolution remains useful even when artwork egress/cache is
                // unavailable. Persist only that safe field; omitting the success marker allows a
                // later image request to retry without another login once the cache is writable.
                persist_plugin_vod_metadata(state, target, metadata, runtime_ticks).await?;
                return Err(error);
            }
        };
        // Validate and fetch before touching the cache. A read-only/misconfigured cache is a
        // recoverable presentation failure at the caller and must never expose the source URL.
        let bytes = bounded_provider_artwork_bytes(bytes).await;
        if let Err(error) = store_image_bytes(
            state,
            ImageOwner::Item(&target.owner_id),
            "Primary",
            0,
            bytes,
        )
        .await
        {
            log_plugin_vod_artwork_failure(PluginVodArtworkFailure::CacheWriteFailed);
            persist_plugin_vod_metadata(state, target, metadata, runtime_ticks).await?;
            return Err(error);
        }
        true
    } else {
        false
    };
    let resolved_at = OffsetDateTime::now_utc().unix_timestamp();
    apply_safe_plugin_vod_resolution(
        &mut metadata,
        target,
        resolved_overview.as_deref(),
        image_available,
        resolved_at,
    );
    if target.scope == "Item" {
        metadata[PLUGIN_VOD_RUNTIME_RESOLVED_AT_FIELD] = serde_json::json!(resolved_at);
    }
    persist_plugin_vod_metadata(state, target, metadata, runtime_ticks).await?;
    Ok(PluginVodSafeMetadata {
        overview: resolved_overview,
        runtime_ticks,
    })
}

/// Persists only bounded, provider-neutral values. The remote image URL is
/// consumed before this boundary and is deliberately not an argument, so a
/// signed provider address cannot become durable metadata or media info.
async fn persist_plugin_vod_metadata(
    state: &AppState,
    target: &PluginVodMetadataTarget,
    metadata: serde_json::Value,
    runtime_ticks: Option<i64>,
) -> Result<(), ApiError> {
    if target.scope != "Item" {
        return state
            .db
            .update_media_item_metadata(target.source_item_id, metadata)
            .await
            .map_err(ApiError::from);
    }
    let runtime_ticks = bounded_plugin_vod_runtime_ticks(runtime_ticks);
    let item = state
        .db
        .media_item_by_id_visible(target.source_item_id)
        .await
        .map_err(ApiError::from)?
        .ok_or_else(|| ApiError::not_found("VOD metadata item is unavailable"))?;
    state
        .db
        .update_media_item_media_info_and_metadata(
            target.source_item_id,
            runtime_ticks,
            item.bitrate,
            item.width,
            item.height,
            item.media_streams,
            metadata,
        )
        .await
        .map_err(ApiError::from)
}

fn plugin_vod_item_metadata_target(
    item: &MediaItem,
    metadata: &serde_json::Value,
) -> Option<PluginVodMetadataTarget> {
    plugin_vod_remote_reference(metadata)?;
    Some(PluginVodMetadataTarget {
        owner_id: item.id.simple().to_string(),
        source_item_id: item.id,
        scope: "Item",
        overview_field: "Overview",
        resolved_at_field: "PluginVodMetadataResolvedAt",
        image_available_field: "PluginVodImageAvailable",
    })
}

async fn plugin_vod_virtual_metadata_target(
    db: &Database,
    owner_id: &str,
    season: bool,
) -> Result<Option<PluginVodMetadataTarget>, ApiError> {
    // New catalogues persist a provider-backed Series anchor even when the series has no
    // episodes. Prefer that authoritative reference; the episode snapshot below remains the
    // compatibility path for catalogues created before anchors were introduced.
    if !season
        && let Ok(owner_uuid) = Uuid::parse_str(owner_id)
        && let Some(anchor) = db
            .media_item_by_id_visible(owner_uuid)
            .await
            .map_err(ApiError::from)?
    {
        let metadata = metadata_payload_for_item(db, anchor.id).await?;
        let is_series = json_field_case_insensitive(&metadata, "PluginVodKind")
            .and_then(serde_json::Value::as_str)
            .is_some_and(|kind| kind.eq_ignore_ascii_case("series"));
        if is_series && plugin_vod_remote_reference(&metadata).is_some() {
            return Ok(Some(PluginVodMetadataTarget {
                owner_id: owner_id.to_string(),
                source_item_id: anchor.id,
                scope: "Series",
                overview_field: "SeriesOverview",
                resolved_at_field: "SeriesPluginVodMetadataResolvedAt",
                image_available_field: "SeriesPluginVodImageAvailable",
            }));
        }
    }
    let snapshot = if season {
        tv_episode_catalog_snapshot_for_season(db, owner_id).await?
    } else {
        tv_episode_catalog_snapshot_for_series(db, owner_id).await?
    };
    let Some(snapshot) = snapshot else {
        return Ok(None);
    };
    let Some(source_item_id) = snapshot.items.iter().find_map(|item| {
        snapshot
            .metadata_by_item
            .get(&item.id)
            .and_then(plugin_vod_remote_reference)
            .map(|_| item.id)
    }) else {
        return Ok(None);
    };
    Ok(Some(if season {
        PluginVodMetadataTarget {
            owner_id: owner_id.to_string(),
            source_item_id,
            scope: "Series",
            overview_field: "SeasonOverview",
            resolved_at_field: "SeasonPluginVodMetadataResolvedAt",
            image_available_field: "SeasonPluginVodImageAvailable",
        }
    } else {
        PluginVodMetadataTarget {
            owner_id: owner_id.to_string(),
            source_item_id,
            scope: "Series",
            overview_field: "SeriesOverview",
            resolved_at_field: "SeriesPluginVodMetadataResolvedAt",
            image_available_field: "SeriesPluginVodImageAvailable",
        }
    }))
}

async fn enrich_plugin_vod_item_metadata(
    state: &AppState,
    item: &mut MediaItem,
    metadata: &mut serde_json::Value,
) {
    let Some(target) = plugin_vod_item_metadata_target(item, metadata) else {
        return;
    };
    item.runtime_ticks = bounded_plugin_vod_runtime_ticks(item.runtime_ticks);
    remove_plugin_vod_external_image_fields(metadata);
    match ensure_plugin_vod_metadata(state, &target).await {
        Ok(resolved) => {
            if let Some(overview) = resolved.overview {
                metadata["Overview"] = serde_json::Value::String(overview);
            }
            item.runtime_ticks = resolved.runtime_ticks;
        }
        Err(error) => {
            tracing::warn!(
                status = %error.status(),
                "VOD metadata enrichment was unavailable"
            );
        }
    }
}

const PLUGIN_VOD_DETAIL_TRACK_CACHE_TTL: StdDuration = StdDuration::from_secs(5 * 60);
const PLUGIN_VOD_DETAIL_TRACK_CACHE_MAX_ENTRIES: usize = 512;
const PLUGIN_VOD_DETAIL_TRACK_RESOLUTION_TIMEOUT: StdDuration = StdDuration::from_secs(8);

#[derive(Clone)]
struct PluginVodDetailTrackCacheEntry {
    expires_at: StdInstant,
    media_streams: Vec<serde_json::Value>,
}

fn plugin_vod_detail_track_cache() -> &'static Mutex<HashMap<String, PluginVodDetailTrackCacheEntry>>
{
    static CACHE: OnceLock<Mutex<HashMap<String, PluginVodDetailTrackCacheEntry>>> =
        OnceLock::new();
    CACHE.get_or_init(|| Mutex::new(HashMap::new()))
}

/// Adds the provider's safe track labels to an item detail response.
///
/// MAGSTV only reveals the authoritative audio/subtitle layout during playback resolution. The
/// signed source URL remains inside the short-lived provider result and is dropped here; only the
/// already-allowlisted descriptors are cached briefly in memory and exposed to clients. A failed
/// or slow provider call degrades to the catalogue placeholders instead of failing the detail page.
async fn enrich_plugin_vod_item_media_streams(
    state: &AppState,
    item: &mut MediaItem,
    metadata: &serde_json::Value,
    user_context: jellyrin_plugin_sdk::PluginUserContext,
) {
    if !is_plugin_vod_virtual_item(item) {
        return;
    }
    let Some(reference) = plugin_vod_remote_reference(metadata) else {
        return;
    };
    let cache_key = stable_entity_id(
        "plugin-vod-detail-tracks",
        &format!(
            "{}:{}:{}",
            item.id, user_context.user_id, user_context.device_id
        ),
    );
    let now = StdInstant::now();
    {
        let mut cache = plugin_vod_detail_track_cache().lock().await;
        cache.retain(|_, entry| entry.expires_at > now);
        if let Some(entry) = cache.get(&cache_key) {
            item.media_streams = entry.media_streams.clone();
            return;
        }
    }

    let resolved = tokio::time::timeout(
        PLUGIN_VOD_DETAIL_TRACK_RESOLUTION_TIMEOUT,
        resolve_plugin_vod_playback(
            &state.db,
            &reference.plugin_id,
            &reference.tuner_id,
            &reference.provider_reference,
            Some(user_context),
        ),
    )
    .await;
    let playback = match resolved {
        Ok(Ok(playback)) => playback,
        Ok(Err(error)) => {
            tracing::warn!(
                status = %error.status(),
                "VOD track enrichment was unavailable"
            );
            return;
        }
        Err(_) => {
            tracing::warn!("VOD track enrichment timed out");
            return;
        }
    };
    if !opaque_live_tv_delivery_is_safe_for_direct_proxy(&playback) {
        tracing::warn!("VOD track enrichment rejected an unsafe delivery contract");
        return;
    }
    let mut media_streams = playback.media_streams.clone();
    repair_plugin_vod_placeholder_codecs(&mut media_streams, &playback);
    if media_streams.is_empty() {
        return;
    }
    item.media_streams = media_streams.clone();
    let mut cache = plugin_vod_detail_track_cache().lock().await;
    if cache.len() < PLUGIN_VOD_DETAIL_TRACK_CACHE_MAX_ENTRIES {
        cache.insert(
            cache_key,
            PluginVodDetailTrackCacheEntry {
                expires_at: StdInstant::now() + PLUGIN_VOD_DETAIL_TRACK_CACHE_TTL,
                media_streams,
            },
        );
    }
}

async fn enrich_plugin_vod_virtual_metadata(
    state: &AppState,
    item_id: &str,
    season: bool,
    metadata: &mut serde_json::Value,
) {
    remove_plugin_vod_external_image_fields(metadata);
    let target = match plugin_vod_virtual_metadata_target(&state.db, item_id, season).await {
        Ok(Some(target)) => target,
        Ok(None) => return,
        Err(error) => {
            tracing::warn!(status = %error.status(), "VOD virtual metadata lookup failed");
            return;
        }
    };
    match ensure_plugin_vod_metadata(state, &target).await {
        Ok(resolved) => {
            if let Some(overview) = resolved.overview {
                metadata["Overview"] = serde_json::Value::String(overview);
            }
        }
        Err(error) => {
            tracing::warn!(
                status = %error.status(),
                "VOD virtual metadata enrichment was unavailable"
            );
        }
    }
}

async fn resolve_plugin_vod_metadata(
    db: &Database,
    metadata: &serde_json::Value,
    scope: &str,
) -> Result<PluginVodResolvedMetadata, ApiError> {
    if !matches!(scope, "Item" | "Series") {
        return Err(ApiError::bad_request("VOD metadata scope is invalid"));
    }
    let reference = plugin_vod_remote_reference(metadata)
        .ok_or_else(|| ApiError::service_unavailable("VOD metadata route is unavailable"))?;
    let jit_lane = external_provider_jit_lane(&reference.tuner_id)
        .ok_or_else(|| ApiError::service_unavailable("VOD metadata tuner is unavailable"))?;
    let _admission_guard = external_plugin_host_admission_slot(&reference.plugin_id, &jit_lane)
        .await
        .acquire_owned()
        .await
        .map_err(|_| ApiError::service_unavailable("VOD metadata provider is unavailable"))?;
    let _provider_session_guard =
        try_external_provider_jit_session(&reference.plugin_id, &reference.tuner_id).await?;
    let security_slot = external_plugin_security_slot(&reference.plugin_id).await;
    let _security_guard = security_slot.read_owned().await;
    let tuner = db
        .live_tv_tuner_configuration_by_id(&reference.tuner_id)
        .await?
        .ok_or_else(|| ApiError::service_unavailable("VOD metadata tuner is unavailable"))?;
    if contains_plaintext_provider_secret(&tuner) {
        return Err(ApiError::service_unavailable(
            "VOD metadata tuner must use an external secret reference",
        ));
    }
    let tuner_type = json_string_field(&tuner, "Type")
        .ok_or_else(|| ApiError::service_unavailable("VOD metadata tuner route is unavailable"))?;
    if !live_tv_plugin_id_from_payload(&tuner, &tuner_type)
        .is_some_and(|plugin_id| plugin_id.eq_ignore_ascii_case(&reference.plugin_id))
    {
        return Err(ApiError::service_unavailable(
            "VOD metadata tuner binding is invalid",
        ));
    }
    let plugin = db
        .installed_plugin_json(&reference.plugin_id)
        .await?
        .filter(|plugin| {
            json_string_field(plugin, "Status").as_deref() == Some("Active")
                && plugin_string_array(plugin.get("Capabilities"))
                    .iter()
                    .any(|capability| {
                        capability.eq_ignore_ascii_case(CAPABILITY_VOD_LIBRARY_PROVIDER)
                    })
        })
        .ok_or_else(|| ApiError::service_unavailable("VOD metadata provider is unavailable"))?;
    let Some((runtime, runtime_name, error_prefix, host_path)) = plugin_runtime_host_path(&plugin)
    else {
        return Err(ApiError::service_unavailable(
            "VOD metadata runtime is unavailable",
        ));
    };
    let request = vod_library_plugin_provider_request(
        db,
        &plugin,
        &tuner,
        "ResolveMetadata",
        serde_json::json!({
            "ProviderReference": reference.provider_reference,
            "Scope": scope,
        }),
    )
    .await
    .map_err(|_| ApiError::service_unavailable("VOD metadata credentials are unavailable"))?;
    let arguments = serde_json::to_value(request)
        .map_err(|_| ApiError::internal("invalid VOD metadata request"))?;
    let result = invoke_plugin_capability_via_runtime_host_path_with_timeout(
        &plugin,
        CAPABILITY_VOD_LIBRARY_PROVIDER,
        arguments,
        runtime,
        runtime_name,
        error_prefix,
        host_path,
        StdDuration::from_secs(15),
    )
    .await
    .map_err(map_plugin_vod_metadata_runtime_failure)?
    .ok_or_else(|| ApiError::service_unavailable("VOD metadata runtime is unavailable"))?;
    let result = ZeroizingJsonValue(result.value);
    if result
        .0
        .get("Status")
        .and_then(serde_json::Value::as_str)
        .is_some_and(|status| !status.eq_ignore_ascii_case("Executed"))
    {
        return Err(ApiError::service_unavailable(
            "VOD metadata provider rejected resolution",
        ));
    }
    let payload = result
        .0
        .get("Metadata")
        .or_else(|| result.0.get("Result"))
        .unwrap_or(&result.0);
    let overview = safe_live_tv_plugin_string_field(payload, "Overview", 16 * 1024)
        .map_err(|_| ApiError::service_unavailable("VOD metadata response is invalid"))?;
    let image_url = json_field_case_insensitive(payload, "ImageUrl")
        .map(|value| {
            let value = value
                .as_str()
                .ok_or_else(|| ApiError::service_unavailable("VOD metadata response is invalid"))?;
            validated_remote_media_url(value)?;
            Ok::<_, ApiError>(Zeroizing::new(value.to_string()))
        })
        .transpose()?;
    let runtime_ticks = plugin_vod_resolved_runtime_ticks(payload)
        .map_err(|_| ApiError::service_unavailable("VOD metadata response is invalid"))?;
    Ok(PluginVodResolvedMetadata {
        overview,
        image_url,
        runtime_ticks,
    })
}

fn plugin_vod_resolved_runtime_ticks(value: &serde_json::Value) -> Result<Option<i64>, ()> {
    let Some(value) = json_field_case_insensitive(value, "RuntimeTicks") else {
        return Ok(None);
    };
    if value.is_null() {
        return Ok(None);
    }
    bounded_plugin_vod_runtime_ticks(value.as_i64())
        .map(Some)
        .ok_or(())
}

fn contains_plaintext_provider_secret(value: &serde_json::Value) -> bool {
    match value {
        serde_json::Value::Array(values) => values.iter().any(contains_plaintext_provider_secret),
        serde_json::Value::Object(object) => object.iter().any(|(key, value)| {
            let normalized = key
                .chars()
                .filter(|character| character.is_ascii_alphanumeric())
                .flat_map(char::to_lowercase)
                .collect::<String>();
            let is_reference = matches!(
                normalized.as_str(),
                "providerreference"
                    | "secretreference"
                    | "tokenref"
                    | "credentialsreference"
                    | "jellyrinprovidersecretref"
            );
            let secret_key = normalized == "username"
                || [
                    "password",
                    "passwd",
                    "passphrase",
                    "secret",
                    "token",
                    "apikey",
                    "authorization",
                    "authheader",
                    "cookie",
                    "credential",
                    "privatekey",
                ]
                .iter()
                .any(|marker| normalized.contains(marker));
            let safe_server_marker = normalized == "credentialsconfigured" && value.is_boolean();
            let url_contains_credentials = value.as_str().is_some_and(|value| {
                reqwest::Url::parse(value).is_ok_and(|url| {
                    !url.username().is_empty()
                        || url.password().is_some()
                        || url.query_pairs().any(|(key, _)| {
                            let key = key
                                .chars()
                                .filter(|character| character.is_ascii_alphanumeric())
                                .flat_map(char::to_lowercase)
                                .collect::<String>();
                            key == "username"
                                || [
                                    "password",
                                    "passwd",
                                    "passphrase",
                                    "secret",
                                    "token",
                                    "apikey",
                                    "authorization",
                                    "authheader",
                                    "cookie",
                                    "credential",
                                    "privatekey",
                                ]
                                .iter()
                                .any(|marker| key.contains(marker))
                        })
                })
            });
            (!is_reference && !safe_server_marker && secret_key && !value.is_null())
                || url_contains_credentials
                || contains_plaintext_provider_secret(value)
        }),
        _ => false,
    }
}

fn live_tv_provider_secret_canaries(request: &serde_json::Value) -> Vec<&str> {
    let Some(grant) = json_field_case_insensitive(request, "SecretGrant") else {
        return Vec::new();
    };
    let mut canaries = ["Username", "Password"]
        .into_iter()
        .filter_map(|field| {
            json_field_case_insensitive(grant, field).and_then(serde_json::Value::as_str)
        })
        .filter(|secret| !secret.is_empty())
        .collect::<Vec<_>>();
    canaries.extend(
        json_field_case_insensitive(grant, "Fields")
            .and_then(serde_json::Value::as_object)
            .into_iter()
            .flat_map(|fields| fields.values())
            .filter_map(serde_json::Value::as_str)
            .filter(|secret| !secret.is_empty()),
    );
    canaries
}

fn json_contains_sensitive_canary(value: &serde_json::Value, canaries: &[&str]) -> bool {
    match value {
        serde_json::Value::String(value) => string_contains_sensitive_canary(value, canaries),
        serde_json::Value::Array(values) => values
            .iter()
            .any(|value| json_contains_sensitive_canary(value, canaries)),
        serde_json::Value::Object(object) => object.iter().any(|(key, value)| {
            string_contains_sensitive_canary(key, canaries)
                || json_contains_sensitive_canary(value, canaries)
        }),
        _ => false,
    }
}

fn string_contains_sensitive_canary(value: &str, canaries: &[&str]) -> bool {
    canaries.iter().any(|secret| {
        !secret.is_empty() && (value == *secret || (secret.len() >= 8 && value.contains(*secret)))
    })
}

fn validated_sensitive_remote_live_redirect(
    current: &reqwest::Url,
    location: &str,
) -> Result<reqwest::Url, ApiError> {
    let target = current.join(location).map_err(|_| {
        ApiError::service_unavailable("Live TV provider source returned invalid redirect")
    })?;
    let target = validated_remote_media_url(target.as_str())?;
    if current.scheme() == "https" && target.scheme() != "https" {
        return Err(ApiError::service_unavailable(
            "Live TV provider source redirected to an insecure destination",
        ));
    }
    Ok(target)
}

async fn send_sensitive_remote_live_request_with_proxy(
    source_url: &str,
    requires_provider_egress: bool,
    configured_proxy: Option<&str>,
    header_timeout: StdDuration,
) -> Result<reqwest::Response, ApiError> {
    send_sensitive_remote_request_with_proxy(
        source_url,
        requires_provider_egress,
        configured_proxy,
        header_timeout,
        None,
        true,
        None,
    )
    .await
}

/// Opens one provider URL through the SSRF-filtered direct path or the explicitly configured
/// provider-egress boundary. Only byte-seeking validators may cross from the client-facing
/// request, and callers opt into those headers explicitly; opaque live streams continue to fetch
/// from byte zero so their manifest guard cannot be bypassed.
async fn send_sensitive_remote_request_with_proxy(
    source_url: &str,
    requires_provider_egress: bool,
    configured_proxy: Option<&str>,
    header_timeout: StdDuration,
    request_headers: Option<&HeaderMap>,
    include_body: bool,
    range_override: Option<&str>,
) -> Result<reqwest::Response, ApiError> {
    let open = async {
        let mut target = validated_remote_media_url(source_url)?;
        for redirect_count in 0..=SENSITIVE_REMOTE_LIVE_MAX_REDIRECTS {
            // Rebuild the client for every hop. Direct sources are resolved and pinned again so a
            // redirect cannot bypass the SSRF filter or exploit DNS rebinding. Provider-egress
            // sources deliberately delegate origin DNS to the configured boundary, whose own
            // endpoint is resolved, filtered and pinned again for every redirected request.
            let (url, client) = if requires_provider_egress {
                let configured_proxy = configured_proxy.ok_or_else(|| {
                    ApiError::service_unavailable("Live TV provider egress proxy is not configured")
                })?;
                validated_provider_egress_client(target.as_str(), configured_proxy).await?
            } else {
                // This client disables environment proxies and pins every allowed origin address.
                validated_remote_media_client(target.as_str()).await?
            };
            let mut request = if include_body {
                client.get(url.clone())
            } else {
                client.head(url.clone())
            };
            request = request.header(header::ACCEPT_ENCODING, "identity");
            if let Some(request_headers) = request_headers {
                for name in [header::RANGE, header::IF_RANGE, header::IF_NONE_MATCH] {
                    if name == header::RANGE
                        && let Some(range) = range_override
                    {
                        request = request.header(header::RANGE, range);
                        continue;
                    }
                    if let Some(value) = request_headers.get(&name) {
                        request = request.header(name, value);
                    }
                }
            }
            let response = request.send().await.map_err(|error| {
                // reqwest errors contain their URL. Never include the error itself because these
                // URLs carry short-lived provider authorization in their path or query.
                tracing::warn!(
                    timeout = error.is_timeout(),
                    connect = error.is_connect(),
                    provider_egress = requires_provider_egress,
                    "sensitive provider proxy request failed"
                );
                ApiError::service_unavailable("provider source is unavailable")
            })?;
            if !matches!(response.status().as_u16(), 301 | 302 | 303 | 307 | 308) {
                return Ok(response);
            }
            if redirect_count == SENSITIVE_REMOTE_LIVE_MAX_REDIRECTS {
                return Err(ApiError::service_unavailable(
                    "Live TV provider source exceeded redirect limit",
                ));
            }
            let location = response
                .headers()
                .get(header::LOCATION)
                .and_then(|value| value.to_str().ok())
                .ok_or_else(|| {
                    ApiError::service_unavailable(
                        "Live TV provider source returned invalid redirect",
                    )
                })?;
            // Reject credentials, fragments, non-HTTP schemes and oversized/control-byte URLs
            // and HTTPS downgrades before any DNS lookup. Opaque paths and query tokens are
            // intentionally never logged.
            target = validated_sensitive_remote_live_redirect(&url, location)?;
        }
        unreachable!("bounded redirect loop always returns")
    };
    tokio::time::timeout(header_timeout, open)
        .await
        .map_err(|_| {
            tracing::warn!(
                timeout = true,
                provider_egress = requires_provider_egress,
                "sensitive provider proxy request timed out before response headers"
            );
            ApiError::service_unavailable("provider source timed out")
        })?
}

async fn send_sensitive_remote_vod_request_with_proxy(
    source_url: &str,
    requires_provider_egress: bool,
    configured_proxy: Option<&str>,
    request_headers: &HeaderMap,
    include_body: bool,
    range_override: Option<&str>,
) -> Result<reqwest::Response, ApiError> {
    send_sensitive_remote_request_with_proxy(
        source_url,
        requires_provider_egress,
        configured_proxy,
        LIVE_TV_REMOTE_CONTROL_TIMEOUT,
        Some(request_headers),
        include_body,
        range_override,
    )
    .await
}

async fn stream_sensitive_remote_live(
    source_url: jellyrin_plugin_sdk::SensitiveUrl,
    _headers: &HeaderMap,
    requires_provider_egress: bool,
    tuner_lease: Option<LiveTunerLeaseGuard>,
) -> Result<axum::response::Response, ApiError> {
    let configured_proxy = if requires_provider_egress {
        Some(
            std::env::var("JELLYRIN_PROVIDER_EGRESS_PROXY").map_err(|_| {
                ApiError::service_unavailable("Live TV provider egress proxy is not configured")
            })?,
        )
    } else {
        None
    };
    let mut upstream = send_sensitive_remote_live_request_with_proxy(
        source_url.expose_secret(),
        requires_provider_egress,
        configured_proxy.as_deref(),
        LIVE_TV_REMOTE_CONTROL_TIMEOUT,
    )
    .await?;
    let status = StatusCode::from_u16(upstream.status().as_u16())
        .map_err(|_| ApiError::service_unavailable("invalid Live TV provider response"))?;
    if !matches!(
        status,
        StatusCode::OK | StatusCode::PARTIAL_CONTENT | StatusCode::RANGE_NOT_SATISFIABLE
    ) {
        tracing::warn!(%status, "opaque Live TV direct proxy rejected upstream status");
        return Err(ApiError::service_unavailable(
            "Live TV provider source is unavailable",
        ));
    }

    if upstream
        .headers()
        .get(header::CONTENT_TYPE)
        .and_then(|value| value.to_str().ok())
        .is_some_and(is_hls_manifest_content_type)
    {
        return Err(ApiError::service_unavailable(
            "Live TV provider returned an unsupported manifest",
        ));
    }

    let mut response = Response::builder().status(status);
    for response_header in [
        header::CONTENT_TYPE,
        header::CONTENT_LENGTH,
        header::CONTENT_RANGE,
        header::ACCEPT_RANGES,
        header::ETAG,
        header::LAST_MODIFIED,
        header::CACHE_CONTROL,
    ] {
        if let Some(value) = upstream.headers().get(&response_header) {
            response = response.header(response_header, value);
        }
    }
    if upstream.headers().get(header::CONTENT_TYPE).is_none() {
        response = response.header(header::CONTENT_TYPE, "video/mp2t");
    }
    let body = if status != StatusCode::RANGE_NOT_SATISFIABLE {
        use futures_util::StreamExt;

        let first_byte_deadline = tokio::time::Instant::now() + LIVE_TV_REMOTE_FIRST_BYTE_TIMEOUT;
        let mut prefix = bytes::BytesMut::new();
        let mut reached_eof = false;
        while hls_manifest_prefix_classification(&prefix).is_none() && prefix.len() < 64 {
            let chunk = tokio::time::timeout_at(first_byte_deadline, upstream.chunk())
                .await
                .map_err(|_| ApiError::service_unavailable("Live TV provider source timed out"))?
                .map_err(|_| {
                    ApiError::service_unavailable("Live TV provider stream interrupted")
                })?;
            let Some(chunk) = chunk else {
                reached_eof = true;
                break;
            };
            prefix.extend_from_slice(&chunk);
        }
        let classification = hls_manifest_prefix_classification(&prefix);
        if classification == Some(true)
            || (classification.is_none() && !reached_eof && prefix.len() >= 64)
        {
            return Err(ApiError::service_unavailable(
                "Live TV provider returned an unsupported manifest",
            ));
        }
        let first = futures_util::stream::iter(
            (!prefix.is_empty()).then(|| Ok::<Bytes, std::io::Error>(prefix.freeze())),
        );
        let remaining = live_tv_chunk_idle_timeout_stream(
            upstream.bytes_stream(),
            LIVE_TV_REMOTE_CHUNK_IDLE_TIMEOUT,
        );
        guarded_live_tv_body(first.chain(remaining), tuner_lease)
    } else {
        Body::empty()
    };
    response
        .body(body)
        .map_err(|_| ApiError::internal("failed to build Live TV provider response"))
}

fn guarded_live_tv_body<S>(stream: S, tuner_lease: Option<LiveTunerLeaseGuard>) -> Body
where
    S: futures_util::Stream<Item = Result<Bytes, std::io::Error>> + Send + 'static,
{
    runtime_guarded_stream_body(stream, tuner_lease, subscribe_runtime_shutdown())
}

fn live_tv_chunk_idle_timeout_stream<S, E>(
    stream: S,
    idle_timeout: StdDuration,
) -> impl futures_util::Stream<Item = Result<Bytes, std::io::Error>> + Send
where
    S: futures_util::Stream<Item = Result<Bytes, E>> + Send + 'static,
    E: Send + 'static,
{
    use futures_util::StreamExt as _;

    futures_util::stream::unfold(Some(Box::pin(stream)), move |state| async move {
        let mut stream = state?;
        match tokio::time::timeout(idle_timeout, stream.next()).await {
            Ok(Some(Ok(chunk))) => Some((Ok(chunk), Some(stream))),
            Ok(Some(Err(_))) => Some((
                Err(std::io::Error::other("Live TV provider stream interrupted")),
                None,
            )),
            Ok(None) => None,
            Err(_) => Some((
                Err(std::io::Error::new(
                    std::io::ErrorKind::TimedOut,
                    "Live TV provider stream idle timeout",
                )),
                None,
            )),
        }
    })
}

fn runtime_guarded_stream_body<S, T>(
    stream: S,
    retained: T,
    shutdown: tokio::sync::watch::Receiver<bool>,
) -> Body
where
    S: futures_util::Stream<Item = Result<Bytes, std::io::Error>> + Send + 'static,
    T: Send + 'static,
{
    use futures_util::StreamExt as _;

    let stream = Box::pin(stream);
    let guarded = futures_util::stream::unfold(
        (stream, retained, shutdown),
        |(mut stream, retained, mut shutdown)| async move {
            let item = tokio::select! {
                biased;
                _ = wait_for_runtime_shutdown(&mut shutdown) => return None,
                item = stream.next() => item,
            }?;
            Some((item, (stream, retained, shutdown)))
        },
    );
    Body::from_stream(guarded)
}

async fn wait_for_runtime_shutdown(shutdown: &mut tokio::sync::watch::Receiver<bool>) {
    if *shutdown.borrow_and_update() {
        return;
    }
    while shutdown.changed().await.is_ok() {
        if *shutdown.borrow_and_update() {
            return;
        }
    }
}

fn is_hls_manifest_content_type(value: &str) -> bool {
    matches!(
        value
            .split(';')
            .next()
            .unwrap_or_default()
            .trim()
            .to_ascii_lowercase()
            .as_str(),
        "application/vnd.apple.mpegurl"
            | "application/x-mpegurl"
            | "audio/mpegurl"
            | "audio/x-mpegurl"
    )
}

#[cfg(test)]
fn looks_like_hls_manifest(chunk: &[u8]) -> bool {
    hls_manifest_prefix_classification(chunk) == Some(true)
}

fn hls_manifest_prefix_classification(chunk: &[u8]) -> Option<bool> {
    let chunk = chunk.strip_prefix(&[0xef, 0xbb, 0xbf]).unwrap_or(chunk);
    let prefix = chunk
        .iter()
        .copied()
        .skip_while(u8::is_ascii_whitespace)
        .take(7)
        .collect::<Vec<_>>();
    (prefix.len() == 7).then(|| prefix == b"#EXTM3U")
}

async fn validated_provider_egress_client(
    source_url: &str,
    configured_proxy: &str,
) -> Result<(reqwest::Url, HttpClient), ApiError> {
    // The provider origin belongs to the configured egress trust boundary: validate its syntax,
    // but do not resolve or connect to it directly from Jellyrin. Pin the proxy endpoint instead.
    let url = validated_remote_media_url(source_url)?;
    if configured_proxy.len() > 16 * 1024 || configured_proxy.chars().any(char::is_control) {
        return Err(ApiError::service_unavailable(
            "Live TV provider egress proxy is invalid",
        ));
    }
    let proxy_url = reqwest::Url::parse(configured_proxy.trim())
        .map_err(|_| ApiError::service_unavailable("Live TV provider egress proxy is invalid"))?;
    if !matches!(proxy_url.scheme(), "http" | "https")
        || proxy_url.host_str().is_none()
        || !matches!(proxy_url.path(), "" | "/")
        || proxy_url.query().is_some()
        || proxy_url.fragment().is_some()
    {
        return Err(ApiError::service_unavailable(
            "Live TV provider egress proxy is invalid",
        ));
    }
    let proxy_host = proxy_url
        .host_str()
        .ok_or_else(|| ApiError::service_unavailable("Live TV provider egress proxy is invalid"))?;
    let proxy_port = proxy_url
        .port_or_known_default()
        .ok_or_else(|| ApiError::service_unavailable("Live TV provider egress proxy is invalid"))?;
    let mut resolved = tokio::net::lookup_host((proxy_host, proxy_port))
        .await
        .map_err(|_| ApiError::service_unavailable("Live TV provider egress proxy DNS failed"))?
        // This endpoint is an explicit operator setting, so RFC1918/ULA/loopback proxies are
        // allowed. Technical, multicast, link-local and otherwise unusable ranges stay blocked.
        .filter(|address| remote_provider_address_allowed(address.ip(), true))
        .collect::<Vec<_>>();
    resolved.sort_unstable();
    resolved.dedup();
    if resolved.is_empty() {
        return Err(ApiError::forbidden(
            "Live TV provider egress proxy address is not allowed",
        ));
    }
    let proxy = reqwest::Proxy::all(proxy_url.as_str())
        .map_err(|_| ApiError::service_unavailable("Live TV provider egress proxy is invalid"))?;
    let client = HttpClient::builder()
        .proxy(proxy)
        .redirect(reqwest::redirect::Policy::none())
        .connect_timeout(LIVE_TV_REMOTE_CONTROL_TIMEOUT)
        .pool_max_idle_per_host(2)
        .user_agent("Jellyrin/0.1 provider-egress")
        .resolve_to_addrs(proxy_host, &resolved)
        .build()
        .map_err(|_| ApiError::internal("failed to initialize Live TV provider egress"))?;
    Ok((url, client))
}

// Guard that decrements the refcount for a shared live stream when dropped.
// Carries the generation of the handle it was issued from; if the registry entry
// for the URL has been replaced by a newer generation (a new open after prior close),
// this guard is a no-op and does NOT touch the new handle.
struct LiveStreamRefGuard {
    url: String,
    generation: u64,
    _tuner_lease: Option<LiveTunerLeaseGuard>,
}

impl Drop for LiveStreamRefGuard {
    fn drop(&mut self) {
        let url = self.url.clone();
        let generation = self.generation;
        // Acquire the mutex inside a spawned task to avoid blocking in drop.
        tokio::spawn(async move {
            let mut registry = live_stream_registry().lock().await;
            if let Some(handle) = registry.get_mut(&url) {
                // Only act if this guard belongs to the current handle's generation.
                if handle.generation != generation {
                    return;
                }
                handle.refcount = handle.refcount.saturating_sub(1);
                if handle.refcount == 0 {
                    registry.remove(&url);
                    // _cancel sender is dropped here, which cancels the producer task.
                }
            }
        });
    }
}

struct LiveTvBroadcastSubscription {
    key: String,
    generation: u64,
    receiver: broadcast::Receiver<Bytes>,
    consumer_tuner_lease: Option<LiveTunerLeaseGuard>,
}

struct LiveTvBroadcastConsumer {
    receiver: broadcast::Receiver<Bytes>,
    guard: LiveStreamRefGuard,
}

impl LiveTvBroadcastSubscription {
    fn into_consumer(self) -> LiveTvBroadcastConsumer {
        LiveTvBroadcastConsumer {
            receiver: self.receiver,
            guard: LiveStreamRefGuard {
                url: self.key,
                generation: self.generation,
                _tuner_lease: self.consumer_tuner_lease,
            },
        }
    }
}

fn live_tv_broadcast_stream_response(
    subscription: LiveTvBroadcastSubscription,
) -> axum::response::Response {
    let consumer = subscription.into_consumer();
    let body_stream = futures_util::stream::unfold(
        consumer,
        |mut consumer: LiveTvBroadcastConsumer| async move {
            loop {
                match consumer.receiver.recv().await {
                    Ok(chunk) => {
                        return Some((Ok::<Bytes, std::convert::Infallible>(chunk), consumer));
                    }
                    Err(broadcast::error::RecvError::Lagged(n)) => {
                        tracing::warn!("live stream consumer lagged, dropped {n} chunks");
                        continue;
                    }
                    // Producer closed: end stream. State (including guard) is dropped here,
                    // which decrements refcount and cancels the producer if it was last consumer.
                    Err(broadcast::error::RecvError::Closed) => {
                        let _ = consumer;
                        return None;
                    }
                }
            }
        },
    );

    (
        StatusCode::OK,
        [(header::CONTENT_TYPE, "video/mp2t")],
        Body::from_stream(body_stream),
    )
        .into_response()
}

async fn proxy_live_tv_channel_url(
    url: String,
    tuner_host_id: Option<String>,
    tuner_count: Option<u64>,
) -> Result<axum::response::Response, ApiError> {
    // Look up or create a shared handle for this stream URL.
    // The lock is never held across network I/O to avoid serialising concurrent clients.
    let (receiver, generation, consumer_tuner_lease) = {
        // Phase 1: check for an existing live handle under the lock.
        {
            let mut registry = live_stream_registry().lock().await;
            if let Some(handle) = registry.get_mut(&url) {
                let consumer_tuner_lease =
                    acquire_live_tuner_lease(tuner_host_id.clone(), &url, tuner_count)?;
                // Existing producer for this URL (same channel): subscribe a new consumer and
                // increment refcount. This is the sharing path — 2 consumers of the SAME channel
                // share the same tuner lease (same stream, no new tuner slot needed).
                handle.refcount += 1;
                let handle_gen = handle.generation;
                let rx = handle.sender.subscribe();
                // Lock is released here (end of block).
                (rx, handle_gen, consumer_tuner_lease)
            } else {
                // No existing handle: this is a NEW channel stream (different URL).
                ensure_live_stream_producer_capacity(&registry, &url)?;
                // Before opening a new upstream connection, acquire a shared tuner lease.
                // The lease registry is global across direct TS, live HLS and recordings.
                let tuner_lease =
                    acquire_live_tuner_lease(tuner_host_id.clone(), &url, tuner_count)?;
                let consumer_tuner_lease =
                    acquire_live_tuner_lease(tuner_host_id.clone(), &url, tuner_count)?;

                // No existing handle. Create the broadcast channel and INSERT the handle into the
                // registry BEFORE opening the upstream connection. This prevents a concurrent
                // request from also entering Phase 2 and opening a duplicate simulator connection
                // (which would briefly inflate maxConcurrentByChannel). Any request arriving
                // while the connection is being established will find this entry and subscribe.
                let handle_gen =
                    LIVE_STREAM_GENERATION.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                let (cancel_tx, cancel_rx) = oneshot::channel::<()>();
                let (tx, rx) = broadcast::channel::<Bytes>(LIVE_STREAM_BROADCAST_CAPACITY);
                let sender_clone = tx.clone();
                let url_clone = url.clone();
                registry.insert(
                    url.clone(),
                    SharedLiveStreamHandle {
                        refcount: 1,
                        generation: handle_gen,
                        sender: tx,
                        _cancel: cancel_tx,
                        _tuner_lease: tuner_lease,
                    },
                );
                // Release the registry lock before doing network I/O.
                drop(registry);

                // Phase 2: open the outgoing connection WITHOUT holding the registry lock.
                // If it fails, clean up the pre-inserted entry and return an error.
                //
                // Known edge case: if consumer 2 subscribes (Phase 1, finds the pre-inserted
                // entry, increments refcount, receives a broadcast::Receiver) between Phase 1
                // and the connection failure below, it will receive RecvError::Closed when the
                // producer never sends — yielding a 200 response with an empty body. This is
                // an uncommon timing window (connection attempt is typically fast). Fixing it
                // would require either (a) not pre-inserting until after the connection is
                // established (reverting the duplicate-prevention property), or (b) marking the
                // handle as "connecting" and having late consumers await a separate ready signal.
                // Documented as a known limitation; the test suite does not exercise this window.
                let upstream =
                    match open_validated_live_tv_stream(&url, LIVE_TV_REMOTE_CONTROL_TIMEOUT).await
                    {
                        Ok(resp) if resp.status().is_success() => resp,
                        Ok(resp) => {
                            let mut registry = live_stream_registry().lock().await;
                            if registry
                                .get(&url)
                                .is_some_and(|h| h.generation == handle_gen)
                            {
                                registry.remove(&url);
                            }
                            return Err(ApiError::internal(format!(
                                "HDHomeRun upstream returned HTTP {}",
                                resp.status()
                            )));
                        }
                        Err(LiveTvRemoteFetchError::Validation(status)) => {
                            let mut registry = live_stream_registry().lock().await;
                            if registry
                                .get(&url)
                                .is_some_and(|h| h.generation == handle_gen)
                            {
                                registry.remove(&url);
                            }
                            tracing::warn!(
                                %status,
                                "HDHomeRun upstream failed strict URL validation"
                            );
                            return Err(ApiError::service_unavailable(
                                "HDHomeRun upstream URL is not allowed",
                            ));
                        }
                        Err(LiveTvRemoteFetchError::Request { timeout, connect }) => {
                            let mut registry = live_stream_registry().lock().await;
                            if registry
                                .get(&url)
                                .is_some_and(|h| h.generation == handle_gen)
                            {
                                registry.remove(&url);
                            }
                            tracing::warn!(
                                timeout,
                                connect,
                                "HDHomeRun upstream connection failed"
                            );
                            return Err(ApiError::service_unavailable(
                                "HDHomeRun upstream connection failed",
                            ));
                        }
                        Err(LiveTvRemoteFetchError::BodyTooLarge) => unreachable!(
                            "stream open does not materialize the upstream response body"
                        ),
                    };

                // Phase 3: start the producer task. The registry entry already exists.
                // Producer task: reads chunks from the outgoing connection and broadcasts them.
                // Terminates when the cancel signal arrives (all consumers gone) or source closes.
                tokio::spawn(async move {
                    use futures_util::StreamExt;
                    let mut byte_stream = upstream.bytes_stream();
                    tokio::pin!(cancel_rx);
                    loop {
                        tokio::select! {
                            _ = &mut cancel_rx => break,
                            chunk = byte_stream.next() => {
                                match chunk {
                                    Some(Ok(bytes)) => {
                                        // No active receivers means all consumers dropped.
                                        if sender_clone.send(bytes).is_err() {
                                            break;
                                        }
                                    }
                                    _ => break,
                                }
                            }
                        }
                    }
                    // Remove registry entry when producer exits, but only if this is still
                    // the same generation (a new handle may have been inserted already).
                    let mut registry = live_stream_registry().lock().await;
                    if registry
                        .get(&url_clone)
                        .is_some_and(|h| h.generation == handle_gen)
                    {
                        registry.remove(&url_clone);
                    }
                });

                (rx, handle_gen, consumer_tuner_lease)
            }
        }
    };

    Ok(live_tv_broadcast_stream_response(
        LiveTvBroadcastSubscription {
            key: url,
            generation,
            receiver,
            consumer_tuner_lease,
        },
    ))
}

async fn subscribe_legacy_hdhomerun_stream(
    channel_url: String,
    tuner_host_url: String,
    control_port: u16,
    num_tuners: usize,
    tuner_host_id: Option<String>,
    tuner_count: Option<u64>,
) -> Result<LiveTvBroadcastSubscription, ApiError> {
    let control_addr = legacy_hdhomerun_control_addr(&tuner_host_url, control_port).await?;
    let stream_key = format!("legacy-hdhomerun:{control_addr}:{channel_url}");

    let (receiver, generation, consumer_tuner_lease) = {
        {
            let mut registry = live_stream_registry().lock().await;
            if let Some(handle) = registry.get_mut(&stream_key) {
                let consumer_tuner_lease =
                    acquire_live_tuner_lease(tuner_host_id.clone(), &channel_url, tuner_count)?;
                handle.refcount += 1;
                let handle_gen = handle.generation;
                let rx = handle.sender.subscribe();
                (rx, handle_gen, consumer_tuner_lease)
            } else {
                ensure_live_stream_producer_capacity(&registry, &stream_key)?;
                let tuner_lease =
                    acquire_live_tuner_lease(tuner_host_id.clone(), &channel_url, tuner_count)?;
                let consumer_tuner_lease =
                    acquire_live_tuner_lease(tuner_host_id.clone(), &channel_url, tuner_count)?;

                let handle_gen =
                    LIVE_STREAM_GENERATION.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                let (cancel_tx, cancel_rx) = oneshot::channel::<()>();
                let (tx, rx) = broadcast::channel::<Bytes>(LIVE_STREAM_BROADCAST_CAPACITY);
                let sender_clone = tx.clone();
                let stream_key_clone = stream_key.clone();
                registry.insert(
                    stream_key.clone(),
                    SharedLiveStreamHandle {
                        refcount: 1,
                        generation: handle_gen,
                        sender: tx,
                        _cancel: cancel_tx,
                        _tuner_lease: tuner_lease,
                    },
                );
                drop(registry);

                let (udp_socket, control) =
                    match open_legacy_hdhomerun_udp_source(&channel_url, control_addr, num_tuners)
                        .await
                    {
                        Ok(opened) => opened,
                        Err(error) => {
                            let mut registry = live_stream_registry().lock().await;
                            if registry
                                .get(&stream_key)
                                .is_some_and(|h| h.generation == handle_gen)
                            {
                                registry.remove(&stream_key);
                            }
                            return Err(error);
                        }
                    };

                tokio::spawn(async move {
                    let mut control = control;
                    let mut buffer = vec![0u8; 65_536];
                    tokio::pin!(cancel_rx);
                    loop {
                        tokio::select! {
                            _ = &mut cancel_rx => break,
                            received = udp_socket.recv_from(&mut buffer) => {
                                match received {
                                    Ok((len, _peer)) if len > HDHOMERUN_LEGACY_RTP_HEADER_BYTES => {
                                        let payload = Bytes::copy_from_slice(&buffer[HDHOMERUN_LEGACY_RTP_HEADER_BYTES..len]);
                                        if sender_clone.send(payload).is_err() {
                                            break;
                                        }
                                    }
                                    Ok(_) => continue,
                                    Err(error) => {
                                        tracing::warn!(error_kind = ?error.kind(), "HDHomeRun legacy UDP receive failed");
                                        break;
                                    }
                                }
                            }
                        }
                    }
                    control.stop().await;
                    let mut registry = live_stream_registry().lock().await;
                    if registry
                        .get(&stream_key_clone)
                        .is_some_and(|h| h.generation == handle_gen)
                    {
                        registry.remove(&stream_key_clone);
                    }
                });

                (rx, handle_gen, consumer_tuner_lease)
            }
        }
    };

    Ok(LiveTvBroadcastSubscription {
        key: stream_key,
        generation,
        receiver,
        consumer_tuner_lease,
    })
}

async fn proxy_live_tv_legacy_hdhomerun_url(
    channel_url: String,
    tuner_host_url: String,
    control_port: u16,
    num_tuners: usize,
    tuner_host_id: Option<String>,
    tuner_count: Option<u64>,
) -> Result<axum::response::Response, ApiError> {
    let subscription = subscribe_legacy_hdhomerun_stream(
        channel_url,
        tuner_host_url,
        control_port,
        num_tuners,
        tuner_host_id,
        tuner_count,
    )
    .await?;
    Ok(live_tv_broadcast_stream_response(subscription))
}

