fn comma_delimited_values(value: &str) -> Vec<String> {
    value
        .split(',')
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned)
        .collect()
}

fn json_string_list_field(value: &serde_json::Value, field: &str) -> Option<Vec<String>> {
    let value = json_field_case_insensitive(value, field)?;
    match value {
        serde_json::Value::Array(values) => Some(
            values
                .iter()
                .filter_map(serde_json::Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(ToOwned::to_owned)
                .collect(),
        ),
        serde_json::Value::String(value) => Some(comma_delimited_values(value)),
        _ => None,
    }
}

fn live_tv_channel_items(config: &serde_json::Value, server_id: &str) -> Vec<serde_json::Value> {
    let mut channels = Vec::new();
    let Some(tuner_hosts) = config
        .get("TunerHosts")
        .and_then(serde_json::Value::as_array)
    else {
        return channels;
    };

    for (tuner_index, tuner) in tuner_hosts.iter().enumerate() {
        let tuner_id =
            json_string_field(tuner, "Id").unwrap_or_else(|| format!("tuner-{tuner_index}"));
        let tuner_name = json_string_field(tuner, "FriendlyName")
            .or_else(|| json_string_field(tuner, "Name"))
            .or_else(|| json_string_field(tuner, "Url"))
            .unwrap_or_else(|| tuner_id.clone());
        let Some(tuner_channels) = tuner.get("Channels").and_then(serde_json::Value::as_array)
        else {
            continue;
        };
        for (channel_index, channel) in tuner_channels.iter().enumerate() {
            if let Some(channel) =
                live_tv_channel_item(&tuner_id, &tuner_name, channel, channel_index, server_id)
            {
                channels.push(channel);
            }
        }
    }
    channels.sort_by(|left, right| {
        let left_sort = json_string_field(left, "SortName")
            .or_else(|| json_string_field(left, "Name"))
            .unwrap_or_default();
        let right_sort = json_string_field(right, "SortName")
            .or_else(|| json_string_field(right, "Name"))
            .unwrap_or_default();
        left_sort
            .to_ascii_lowercase()
            .cmp(&right_sort.to_ascii_lowercase())
    });
    channels
}

fn live_tv_channel_item(
    tuner_id: &str,
    tuner_name: &str,
    channel: &serde_json::Value,
    index: usize,
    server_id: &str,
) -> Option<serde_json::Value> {
    let (mut base, raw_name) = match channel {
        serde_json::Value::Object(fields) => (serde_json::Value::Object(fields.clone()), None),
        serde_json::Value::String(name) => (serde_json::json!({}), Some(name.trim().to_string())),
        _ => return None,
    };
    let name = json_string_field(&base, "Name")
        .or_else(|| json_string_field(&base, "DisplayName"))
        .or(raw_name)
        .filter(|name| !name.is_empty())
        .unwrap_or_else(|| format!("Channel {}", index + 1));
    let number = json_string_field(&base, "Number")
        .or_else(|| json_string_field(&base, "ChannelNumber"))
        .or_else(|| json_string_field(&base, "GuideNumber"));
    let raw_id = json_string_field(&base, "Id")
        .or_else(|| json_string_field(&base, "ChannelId"))
        .or_else(|| number.clone())
        .unwrap_or_else(|| format!("{tuner_id}-{}", index + 1));
    let id = live_tv_channel_public_id(&raw_id);

    base["Id"] = serde_json::json!(id);
    base["ChannelId"] = base["Id"].clone();
    base["JellyrinChannelId"] = serde_json::json!(raw_id);
    base["ServerId"] = serde_json::json!(server_id);
    base["Name"] = serde_json::json!(name);
    base["SortName"] = serde_json::json!(
        number
            .clone()
            .unwrap_or_else(|| { base["Name"].as_str().unwrap_or_default().to_string() })
    );
    base["Number"] = number
        .map(serde_json::Value::String)
        .unwrap_or(serde_json::Value::Null);
    base["TunerHostId"] = serde_json::json!(tuner_id);
    base["TunerHostName"] = serde_json::json!(tuner_name);
    base["Type"] = serde_json::json!("TvChannel");
    base["MediaType"] = serde_json::json!("Video");
    base["ChannelType"] = base
        .get("ChannelType")
        .cloned()
        .unwrap_or_else(|| serde_json::json!("TV"));
    base["IsFolder"] = serde_json::json!(false);
    base["IsLive"] = serde_json::json!(true);
    base["CanDelete"] = serde_json::json!(false);
    base["CanDownload"] = serde_json::json!(false);
    base["EnableMediaSourceDisplay"] = serde_json::json!(true);
    base["PlayAccess"] = serde_json::json!("Full");
    base["LocationType"] = serde_json::json!("Remote");
    base["RunTimeTicks"] = serde_json::Value::Null;
    base["UserData"] = serde_json::json!({
        "PlaybackPositionTicks": 0,
        "PlayCount": 0,
        "IsFavorite": false,
        "Played": false,
        "Key": base["Id"].clone(),
        "ItemId": base["Id"].clone()
    });
    base["CurrentProgram"] = serde_json::Value::Null;
    apply_live_tv_image_metadata(&mut base);
    if live_tv_channel_path(&base).is_ok()
        && let Ok(mut media_source) = live_tv_channel_media_source(&base)
    {
        suppress_remote_live_tv_direct_stream_for_item_detail(&mut media_source);
        base["MediaSources"] = serde_json::json!([media_source]);
    }
    Some(base)
}

fn suppress_remote_live_tv_direct_stream_for_item_detail(media_source: &mut serde_json::Value) {
    let Some(media_source) = media_source.as_object_mut() else {
        return;
    };
    if !media_source
        .get("IsRemote")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false)
    {
        return;
    }
    // Jellyfin Web makes its initial play-method choice from the media source embedded in the
    // item detail before it applies PlaybackInfo. Advertising raw MPEG-TS here makes the browser
    // synthesize /Videos/{id}/stream.ts even when PlaybackInfo correctly selects HLS. Keep the
    // raw TS capability private to PlaybackInfo's explicit native-client fallback.
    media_source.insert("SupportsDirectStream".to_string(), serde_json::json!(false));
    media_source.remove("DirectStreamUrl");
}

fn live_tv_channel_path(channel: &serde_json::Value) -> Result<PathBuf, ApiError> {
    json_string_field(channel, "Path")
        .or_else(|| json_string_field(channel, "MediaPath"))
        .map(PathBuf::from)
        .filter(|path| !path.as_os_str().is_empty())
        .ok_or_else(|| ApiError::not_found("Live TV stream not found"))
}

fn live_tv_channel_provider_reference(channel: &serde_json::Value) -> Option<String> {
    json_string_field(channel, "ProviderReference")
}

fn live_tv_channel_uses_opaque_provider(channel: &serde_json::Value) -> bool {
    live_tv_channel_provider_reference(channel).is_some()
        && (json_string_field(channel, "PluginProviderId").is_some()
            || json_string_field(channel, "ProviderType")
                .is_some_and(|provider| provider.eq_ignore_ascii_case("xtream")))
}

fn live_tv_channel_is_remote(path: &FsPath) -> bool {
    let s = path.to_string_lossy();
    s.starts_with("http://") || s.starts_with("https://")
}

// Returns a stable play_session_id for a live TV channel used in the HLS TranscodingUrl.
// Deterministic so clients can predict it from the channel_id; changes only when channel_id
// changes.
fn live_tv_channel_hls_play_session_id(channel_id: &str) -> String {
    live_tv_channel_hls_play_session_id_for_selection(channel_id, None)
}

fn live_tv_channel_hls_play_session_id_for_selection(
    channel_id: &str,
    subtitle_stream_index: Option<i64>,
) -> String {
    stable_entity_id(
        "LiveTvHls",
        &format!(
            "{channel_id}:subtitle:{}",
            subtitle_stream_index.map_or_else(|| "off".to_string(), |index| index.to_string())
        ),
    )
}

fn live_tv_channel_hls_dedupe_key_for_selection(
    channel_id: &str,
    subtitle_stream_index: Option<i64>,
) -> String {
    format!(
        "livetv:hls:{channel_id}:subtitle:{}",
        subtitle_stream_index.map_or_else(|| "off".to_string(), |index| index.to_string())
    )
}

fn live_tv_channel_playback_id(channel: &serde_json::Value) -> Option<String> {
    json_string_field(channel, "JellyrinChannelId").or_else(|| json_string_field(channel, "Id"))
}

// Returns a stable UUID for a live TV channel, used as the item_id when registering a
// transcode session in the database (which requires a Uuid, not a raw channel string).
fn live_tv_channel_stable_uuid(channel_id: &str) -> Option<Uuid> {
    Uuid::parse_str(&live_tv_channel_public_id(channel_id)).ok()
}

// Returns true when a channel_id looks like an HDHomeRun channel (starts with "hdhr_") or
// when it fails parse_jellyfin_uuid, indicating it may be a live TV channel identifier.
fn is_live_tv_channel_id(channel_id: &str) -> bool {
    channel_id.starts_with("hdhr_") || parse_jellyfin_uuid(channel_id).is_err()
}

fn live_tv_image_url(item: &serde_json::Value) -> Option<String> {
    json_string_any_field(
        item,
        &[
            "LiveTvOriginalImageUrl",
            "OriginalImageUrl",
            "ExternalImageUrl",
            "PrimaryImageUrl",
            "LogoUrl",
            "IconUrl",
            "ChannelLogoUrl",
            "ImageUrl",
        ],
    )
    .filter(|url| !url.starts_with("/Items/") && !url.starts_with("/Image/"))
}

fn live_tv_image_tag(item_id: &str, image_url: &str) -> String {
    stable_entity_id("LiveTvImage", &format!("{item_id}:{image_url}"))
}

fn apply_live_tv_image_metadata(item: &mut serde_json::Value) {
    let Some(item_id) = json_string_field(item, "Id") else {
        return;
    };
    let Some(image_url) = live_tv_image_url(item) else {
        return;
    };
    let tag = live_tv_image_tag(&item_id, &image_url);
    item["LiveTvOriginalImageUrl"] = serde_json::json!(image_url);
    item["ImageUrl"] = serde_json::json!(format!("/Items/{item_id}/Images/Primary?tag={tag}"));
    item["ImageTags"] = serde_json::json!({ "Primary": tag });
    item["PrimaryImageTag"] = item["ImageTags"]["Primary"].clone();
    if item
        .get("PrimaryImageAspectRatio")
        .is_none_or(serde_json::Value::is_null)
    {
        item["PrimaryImageAspectRatio"] = serde_json::json!(1.0);
    }
    if item
        .get("BackdropImageTags")
        .is_none_or(serde_json::Value::is_null)
    {
        item["BackdropImageTags"] = serde_json::json!([]);
    }
}

fn live_tv_channel_media_source(
    channel: &serde_json::Value,
) -> Result<serde_json::Value, ApiError> {
    let detected_streams = channel
        .get("MediaStreams")
        .and_then(serde_json::Value::as_array)
        .cloned()
        .unwrap_or_default();
    live_tv_channel_media_source_with_streams(channel, &detected_streams)
}

fn live_tv_channel_media_source_with_streams(
    channel: &serde_json::Value,
    detected_streams: &[serde_json::Value],
) -> Result<serde_json::Value, ApiError> {
    let public_channel_id = json_string_field(channel, "Id")
        .ok_or_else(|| ApiError::not_found("Live TV item not found"))?;
    let playback_channel_id =
        live_tv_channel_playback_id(channel).unwrap_or_else(|| public_channel_id.clone());
    let name = json_string_field(channel, "Name").unwrap_or_else(|| public_channel_id.clone());
    let opaque_provider = live_tv_channel_uses_opaque_provider(channel);
    let path = live_tv_channel_path(channel).ok();
    if path.is_none() && !opaque_provider {
        return Err(ApiError::not_found("Live TV stream not found"));
    }
    let is_legacy_hdhomerun = path
        .as_deref()
        .is_some_and(live_tv_channel_is_legacy_hdhomerun_path);
    let is_http_remote = path.as_deref().is_some_and(live_tv_channel_is_remote);
    let is_remote = opaque_provider || is_http_remote || is_legacy_hdhomerun;
    let container = if is_remote {
        "ts".to_string()
    } else {
        path.as_deref()
            .and_then(FsPath::extension)
            .and_then(|extension| extension.to_str())
            .map(str::to_ascii_lowercase)
            .unwrap_or_else(|| "ts".to_string())
    };
    let protocol = if opaque_provider || is_http_remote {
        "Http"
    } else if is_legacy_hdhomerun {
        "Udp"
    } else {
        "File"
    };

    // Every remote channel supports HLS remux in addition to direct TS stream. Opaque
    // providers resolve their source JIT inside the loopback relay, so exposing this local
    // route does not disclose provider credentials or signed URLs.
    // The stable play_session_id is embedded in the TranscodingUrl so clients can reuse it
    // across channel-detail fetches without starting a new session each time.
    let (supports_transcoding, transcoding_sub_protocol, transcoding_container, transcoding_url) =
        if is_remote {
            let play_session_id = live_tv_channel_hls_play_session_id(&playback_channel_id);
            let url =
                format!("/Videos/{public_channel_id}/master.m3u8?PlaySessionId={play_session_id}");
            (
                serde_json::json!(true),
                serde_json::json!("hls"),
                serde_json::json!("ts"),
                serde_json::Value::String(url),
            )
        } else {
            (
                serde_json::json!(false),
                serde_json::Value::Null,
                serde_json::Value::Null,
                serde_json::Value::Null,
            )
        };
    let supports_direct_stream = true;
    let supports_direct_play = !is_remote;

    let mut media_streams = detected_streams
        .iter()
        .cloned()
        .map(normalize_media_stream)
        .collect::<Vec<_>>();
    if media_streams.is_empty() {
        media_streams = vec![
            normalize_media_stream(serde_json::json!({
                "Codec": container,
                "Type": "Video",
                "Index": 0,
                "IsDefault": true,
                "IsForced": false,
                "IsInterlaced": false,
                "IsExternal": false
            })),
            normalize_media_stream(serde_json::json!({
                "Codec": "aac",
                "Type": "Audio",
                "Index": 1,
                "Channels": 2,
                "ChannelLayout": "stereo",
                "BitRate": 192000,
                "IsDefault": true,
                "IsForced": false,
                "IsExternal": false
            })),
        ];
    }
    for stream in &mut media_streams {
        let Some(stream) = stream.as_object_mut() else {
            continue;
        };
        if stream
            .get("Type")
            .and_then(serde_json::Value::as_str)
            .is_some_and(|stream_type| stream_type.eq_ignore_ascii_case("Subtitle"))
        {
            // Web's playback manager restarts PlaybackInfo for Encode tracks, which lets the
            // server select exactly one sparse teletext service in the shared A/V FFmpeg process.
            stream.insert("DeliveryMethod".to_string(), serde_json::json!("Encode"));
            stream.insert("IsExternal".to_string(), serde_json::json!(false));
            stream.insert(
                "SupportsExternalStream".to_string(),
                serde_json::json!(false),
            );
        }
    }
    let default_audio_stream_index = default_audio_stream_index(&media_streams).unwrap_or(1);

    Ok(serde_json::json!({
        "Protocol": protocol,
        "Id": playback_channel_id,
        "Path": path.map(|path| path.to_string_lossy().to_string()),
        "Type": "Default",
        "Container": container,
        "Name": name,
        "IsRemote": is_remote,
        "DirectStreamUrl": format!("/LiveTv/LiveStreamFiles/{public_channel_id}/stream.{container}"),
        "ETag": null,
        "RunTimeTicks": null,
        "ReadAtNativeFramerate": true,
        "IgnoreDts": false,
        "IgnoreIndex": false,
        "GenPtsInput": false,
        "SupportsTranscoding": supports_transcoding,
        "TranscodingSubProtocol": transcoding_sub_protocol,
        "TranscodingContainer": transcoding_container,
        "TranscodingUrl": transcoding_url,
        "SupportsDirectStream": supports_direct_stream,
        "SupportsDirectPlay": supports_direct_play,
        "IsInfiniteStream": true,
        "CanSeek": false,
        "UseMostCompatibleTranscodingProfile": false,
        // Opaque providers resolve their source lazily when the selected direct/HLS URL is
        // requested. Marking them RequiresOpening makes Jellyfin Web call /LiveStreams/Open;
        // that legacy endpoint has no DeviceProfile and replaces the negotiated HLS source with
        // the raw TS base source. Only legacy HDHomeRun needs an explicit open lifecycle.
        "RequiresOpening": is_legacy_hdhomerun,
        "RequiresClosing": true,
        "RequiresLooping": false,
        "SupportsProbing": false,
        "VideoType": "VideoFile",
        "MediaStreams": media_streams,
        "DefaultAudioStreamIndex": default_audio_stream_index,
        "MediaAttachments": [],
        "Formats": [],
        "RequiredHttpHeaders": {},
        "HasSegments": false,
        "Bitrate": null
    }))
}

fn live_tv_subtitle_source_index(
    media_streams: &[serde_json::Value],
    public_index: Option<i64>,
) -> Option<i64> {
    let public_index = public_index.filter(|index| *index >= 0)?;
    media_streams.iter().find_map(|stream| {
        let stream = stream.as_object()?;
        let is_subtitle = stream
            .get("Type")
            .and_then(serde_json::Value::as_str)
            .is_some_and(|kind| kind.eq_ignore_ascii_case("Subtitle"));
        (is_subtitle && stream.get("Index").and_then(json_value_i64) == Some(public_index)).then(
            || {
                stream
                    .get("JellyrinSourceStreamIndex")
                    .and_then(json_value_i64)
                    .unwrap_or(public_index)
            },
        )
    })
}

fn live_tv_subtitle_teletext_page(
    media_streams: &[serde_json::Value],
    public_index: Option<i64>,
) -> Option<u16> {
    let public_index = public_index.filter(|index| *index >= 0)?;
    media_streams.iter().find_map(|stream| {
        (json_string_field(stream, "Type")
            .is_some_and(|kind| kind.eq_ignore_ascii_case("Subtitle"))
            && json_i64_field(stream, "Index") == Some(public_index))
        .then(|| json_i64_field(stream, "JellyrinTeletextPage"))
        .flatten()
        .and_then(|page| u16::try_from(page).ok())
        .filter(|page| (100..=899).contains(page))
    })
}

/// Keep only the guide rows this user's authorized tuners account for.
///
/// A program's `TunerHostId` is the id of the configuration entry that supplied it, so rows imported
/// from a `ListingProviders` entry never name a tuner: comparing them against the authorized tuners
/// emptied the guide for everyone, administrators included. Authorize those through the channel they
/// belong to, and keep denying a program whose channel this user cannot see -- including one that
/// matches no channel at all.
fn retain_authorized_live_tv_programs(
    programs: &mut Vec<serde_json::Value>,
    channels: &[serde_json::Value],
    allowed_tuner_ids: &[String],
) {
    let tuner_is_allowed = |id: &str| {
        allowed_tuner_ids
            .iter()
            .any(|allowed| allowed.eq_ignore_ascii_case(id))
    };
    let allowed_channel_ids = channels
        .iter()
        .filter(|channel| {
            json_string_field(channel, "TunerHostId").is_some_and(|id| tuner_is_allowed(&id))
        })
        .flat_map(|channel| {
            json_string_field(channel, "Id")
                .into_iter()
                .chain(json_string_field(channel, "JellyrinChannelId"))
        })
        .collect::<Vec<_>>();
    programs.retain(|program| {
        if json_string_field(program, "TunerHostId").is_some_and(|id| tuner_is_allowed(&id)) {
            return true;
        }
        json_string_field(program, "ChannelId")
            .into_iter()
            .chain(json_string_field(program, "JellyrinChannelId"))
            .any(|channel_id| {
                allowed_channel_ids
                    .iter()
                    .any(|allowed| jellyfin_id_matches(allowed, &channel_id))
            })
    });
}

fn live_tv_program_items(config: &serde_json::Value, server_id: &str) -> Vec<serde_json::Value> {
    let channels = live_tv_channel_items(config, server_id);
    let mut programs = Vec::new();
    collect_live_tv_programs(
        config,
        "ListingProviders",
        &channels,
        &mut programs,
        server_id,
    );
    collect_live_tv_programs(config, "TunerHosts", &channels, &mut programs, server_id);
    programs.sort_by(|left, right| {
        let left_start = json_string_field(left, "StartDate").unwrap_or_default();
        let right_start = json_string_field(right, "StartDate").unwrap_or_default();
        left_start.cmp(&right_start).then_with(|| {
            json_string_field(left, "Name")
                .unwrap_or_default()
                .to_ascii_lowercase()
                .cmp(
                    &json_string_field(right, "Name")
                        .unwrap_or_default()
                        .to_ascii_lowercase(),
                )
        })
    });
    programs
}

fn live_tv_fallback_program_items(
    channels: &[serde_json::Value],
    channel_ids: &[String],
    server_id: &str,
) -> Vec<serde_json::Value> {
    let now = OffsetDateTime::now_utc();
    let start = now - Duration::hours(12);
    let end = now + Duration::hours(12);
    let start_date = format_time_for_json(start);
    let end_date = format_time_for_json(end);
    channels
        .iter()
        .filter(|channel| {
            channel_ids.is_empty()
                || json_string_field(channel, "Id").is_some_and(|channel_id| {
                    channel_ids
                        .iter()
                        .any(|requested| requested.eq_ignore_ascii_case(&channel_id))
                })
        })
        .filter_map(|channel| {
            live_tv_fallback_program_item(channel, server_id, &start_date, &end_date)
        })
        .collect()
}

fn live_tv_fallback_program_item(
    channel: &serde_json::Value,
    server_id: &str,
    start_date: &str,
    end_date: &str,
) -> Option<serde_json::Value> {
    let channel_id = json_string_field(channel, "Id")?;
    let raw_channel_id =
        json_string_field(channel, "JellyrinChannelId").unwrap_or_else(|| channel_id.clone());
    let channel_name = json_string_field(channel, "Name").unwrap_or_else(|| channel_id.clone());
    let channel_number = json_string_field(channel, "Number");
    let playback_channel_id = live_tv_playback_channel_public_id(&raw_channel_id);
    let program_id = live_tv_fallback_program_public_id(&channel_id);
    let mut program = serde_json::json!({
        "Id": program_id,
        "Name": channel_name,
        "SortName": channel_name,
        "Type": "Program",
        "ServerId": server_id,
        "MediaType": "Video",
        "ParentId": playback_channel_id,
        "ChannelId": channel_id,
        "ChannelName": channel_name,
        "ChannelNumber": channel_number,
        "IsFolder": false,
        "IsLive": true,
        "CanDelete": false,
        "CanDownload": false,
        "EnableMediaSourceDisplay": true,
        "PlayAccess": "Full",
        "LocationType": "Remote",
        "StartDate": start_date,
        "EndDate": end_date,
        "Overview": "",
        "RunTimeTicks": null,
        "BackdropImageTags": [],
        "CurrentProgram": null,
        "UserData": {
            "PlaybackPositionTicks": 0,
            "PlayCount": 0,
            "IsFavorite": false,
            "Played": false,
            "Key": program_id,
            "ItemId": program_id
        }
    });
    if let Some(image_url) = live_tv_image_url(channel) {
        program["ImageUrl"] = serde_json::json!(image_url);
    }
    apply_live_tv_program_runtime_ticks(&mut program);
    apply_live_tv_image_metadata(&mut program);
    for key in [
        "Genres",
        "Tags",
        "GenreItems",
        "JellyrinChannelId",
        "Path",
        "MediaSources",
        "TunerHostId",
    ] {
        if let Some(value) = json_field_case_insensitive(channel, key) {
            program[key] = value.clone();
        }
    }
    apply_live_tv_category_flags(&mut program);
    Some(program)
}

fn apply_live_tv_category_flags(item: &mut serde_json::Value) {
    let mut terms = Vec::new();
    for key in ["Name", "ChannelName"] {
        if let Some(value) = json_string_field(item, key) {
            terms.push(value);
        }
    }
    for key in ["Genres", "Tags"] {
        terms.extend(json_string_list_field(item, key).unwrap_or_default());
    }
    let haystack = terms.join(" ").to_ascii_lowercase();
    let has_any = |needles: &[&str]| needles.iter().any(|needle| haystack.contains(needle));

    let is_sports = has_any(&[
        "sport", "sports", "football", "futbol", "fútbol", "soccer", "liga", "laliga", "nba",
        "nfl", "mlb", "nhl", "tennis", "golf", "f1", "formula", "racing", "motogp", "ufc",
        "boxing", "wwe",
    ]);
    let is_kids = has_any(&[
        "kid",
        "kids",
        "niños",
        "ninos",
        "infantil",
        "cartoon",
        "disney",
        "nick",
        "junior",
        "boomerang",
        "baby",
        "children",
    ]);
    let is_news = has_any(&[
        "news",
        "noticias",
        "noticia",
        "cnn",
        "bbc",
        "sky news",
        "euronews",
        "al jazeera",
        "fox news",
        "france 24",
        "24h",
        "24 horas",
    ]);
    let is_series = has_any(&[
        "series",
        "serie",
        "show",
        "shows",
        "episod",
        "drama",
        "novela",
        "telenovela",
    ]);
    let is_movie = has_any(&[
        "movie",
        "movies",
        "film",
        "films",
        "cine",
        "cinema",
        "pelicula",
        "película",
        "vod",
        "ppv",
        "box office",
        "premiere",
    ]);

    item["IsSports"] = serde_json::json!(is_sports);
    item["IsKids"] = serde_json::json!(is_kids);
    item["IsNews"] = serde_json::json!(is_news);
    item["IsSeries"] = serde_json::json!(is_series);
    item["IsMovie"] = serde_json::json!(is_movie);
    item["IsPremiere"] = serde_json::json!(has_any(&["premiere", "estreno", "new"]));
    item["IsRepeat"] = serde_json::json!(false);
}

fn collect_live_tv_programs(
    config: &serde_json::Value,
    collection_key: &str,
    channels: &[serde_json::Value],
    programs: &mut Vec<serde_json::Value>,
    server_id: &str,
) {
    let Some(sources) = config
        .get(collection_key)
        .and_then(serde_json::Value::as_array)
    else {
        return;
    };
    for (source_index, source) in sources.iter().enumerate() {
        let source_id = json_string_field(source, "Id")
            .unwrap_or_else(|| format!("{collection_key}-{source_index}"));
        let Some(source_programs) = source.get("Programs").and_then(serde_json::Value::as_array)
        else {
            continue;
        };
        for (program_index, program) in source_programs.iter().enumerate() {
            if let Some(program) =
                live_tv_program_item(&source_id, channels, program, program_index, server_id)
            {
                programs.push(program);
            }
        }
    }
}

fn live_tv_program_item(
    source_id: &str,
    channels: &[serde_json::Value],
    program: &serde_json::Value,
    index: usize,
    server_id: &str,
) -> Option<serde_json::Value> {
    let (mut base, raw_name) = match program {
        serde_json::Value::Object(fields) => (serde_json::Value::Object(fields.clone()), None),
        serde_json::Value::String(name) => (serde_json::json!({}), Some(name.trim().to_string())),
        _ => return None,
    };
    let name = json_string_field(&base, "Name")
        .or_else(|| json_string_field(&base, "Title"))
        .or(raw_name)
        .filter(|name| !name.is_empty())
        .unwrap_or_else(|| format!("Program {}", index + 1));
    let raw_channel_id = json_string_field(&base, "ChannelId")
        .or_else(|| json_string_field(&base, "Channel"))
        .or_else(|| {
            channels.first().and_then(|channel| {
                json_string_field(channel, "JellyrinChannelId")
                    .or_else(|| json_string_field(channel, "Id"))
            })
        })
        .unwrap_or_default();
    let matched_channel = channels.iter().find(|channel| {
        json_string_field(channel, "Id")
            .into_iter()
            .chain(json_string_field(channel, "JellyrinChannelId"))
            .any(|id| jellyfin_id_matches(&id, &raw_channel_id))
    });
    let channel_id = matched_channel
        .and_then(|channel| json_string_field(channel, "Id"))
        .unwrap_or_else(|| live_tv_channel_public_id(&raw_channel_id));
    let channel_name = matched_channel.and_then(|channel| json_string_field(channel, "Name"));
    let raw_id = json_string_field(&base, "Id")
        .or_else(|| json_string_field(&base, "ProgramId"))
        .unwrap_or_else(|| format!("{source_id}-program-{}", index + 1));
    let id = stable_jellyfin_uuid("LiveTvProgram", &raw_id);

    base["Id"] = serde_json::json!(id);
    base["JellyrinProgramId"] = serde_json::json!(raw_id);
    base["Name"] = serde_json::json!(name.clone());
    base["SortName"] = serde_json::json!(name);
    base["Type"] = serde_json::json!("Program");
    base["ServerId"] = serde_json::json!(server_id);
    base["MediaType"] = serde_json::json!("Video");
    base["TunerHostId"] = serde_json::json!(source_id);
    base["ChannelId"] = serde_json::json!(channel_id);
    base["JellyrinChannelId"] = serde_json::json!(raw_channel_id);
    base["ChannelName"] = channel_name
        .map(serde_json::Value::String)
        .unwrap_or(serde_json::Value::Null);
    base["IsFolder"] = serde_json::json!(false);
    base["IsLive"] = base
        .get("IsLive")
        .cloned()
        .unwrap_or(serde_json::Value::Bool(false));
    base["StartDate"] = base
        .get("StartDate")
        .cloned()
        .or_else(|| base.get("Start").cloned())
        .unwrap_or(serde_json::Value::Null);
    base["EndDate"] = base
        .get("EndDate")
        .cloned()
        .or_else(|| base.get("End").cloned())
        .unwrap_or(serde_json::Value::Null);
    base["Overview"] = base
        .get("Overview")
        .cloned()
        .or_else(|| base.get("Description").cloned())
        .unwrap_or_else(|| serde_json::json!(""));
    apply_live_tv_program_runtime_ticks(&mut base);
    if live_tv_image_url(&base).is_none()
        && let Some(channel_image_url) = channels
            .iter()
            .find(|channel| {
                json_string_field(channel, "Id")
                    .is_some_and(|id| jellyfin_id_matches(&id, &channel_id))
            })
            .and_then(live_tv_image_url)
    {
        base["ImageUrl"] = serde_json::json!(channel_image_url);
    }
    apply_live_tv_image_metadata(&mut base);
    apply_live_tv_category_flags(&mut base);
    Some(base)
}

fn live_tv_recording_items(config: &serde_json::Value, server_id: &str) -> Vec<serde_json::Value> {
    let channels = live_tv_channel_items(config, server_id);
    let mut recordings = config
        .get("Recordings")
        .and_then(serde_json::Value::as_array)
        .map(|recordings| {
            recordings
                .iter()
                .enumerate()
                .filter_map(|(index, recording)| {
                    live_tv_recording_item(recording, index, &channels, server_id)
                })
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    recordings.sort_by(|left, right| {
        json_string_field(right, "DateCreated")
            .unwrap_or_default()
            .cmp(&json_string_field(left, "DateCreated").unwrap_or_default())
            .then_with(|| {
                json_string_field(left, "Name")
                    .unwrap_or_default()
                    .to_ascii_lowercase()
                    .cmp(
                        &json_string_field(right, "Name")
                            .unwrap_or_default()
                            .to_ascii_lowercase(),
                    )
            })
    });
    recordings
}

fn live_tv_recording_item(
    recording: &serde_json::Value,
    index: usize,
    channels: &[serde_json::Value],
    server_id: &str,
) -> Option<serde_json::Value> {
    let serde_json::Value::Object(fields) = recording else {
        return None;
    };
    let mut item = serde_json::Value::Object(fields.clone());
    let name = json_string_field(&item, "Name")
        .or_else(|| json_string_field(&item, "Title"))
        .unwrap_or_else(|| format!("Recording {}", index + 1));
    let id = json_string_field(&item, "Id")
        .or_else(|| json_string_field(&item, "RecordingId"))
        .unwrap_or_else(|| format!("recording-{}", index + 1));
    let raw_channel_id = json_string_field(&item, "ChannelId").unwrap_or_default();
    let matched_channel = channels.iter().find(|channel| {
        json_string_field(channel, "Id")
            .into_iter()
            .chain(json_string_field(channel, "JellyrinChannelId"))
            .any(|id| jellyfin_id_matches(&id, &raw_channel_id))
    });
    let channel_id = matched_channel
        .and_then(|channel| json_string_field(channel, "Id"))
        .unwrap_or_else(|| live_tv_channel_public_id(&raw_channel_id));
    let channel_name = matched_channel.and_then(|channel| json_string_field(channel, "Name"));

    item["Id"] = serde_json::json!(id);
    item["Name"] = serde_json::json!(name.clone());
    item["SortName"] = serde_json::json!(name);
    item["Type"] = serde_json::json!("Recording");
    item["ServerId"] = serde_json::json!(server_id);
    item["MediaType"] = serde_json::json!("Video");
    item["ChannelId"] = serde_json::json!(channel_id);
    item["JellyrinChannelId"] = serde_json::json!(raw_channel_id);
    item["ChannelName"] = channel_name
        .map(serde_json::Value::String)
        .unwrap_or(serde_json::Value::Null);
    item["IsFolder"] = serde_json::json!(false);
    item["IsLive"] = serde_json::json!(false);
    item["Status"] = item
        .get("Status")
        .cloned()
        .unwrap_or_else(|| serde_json::json!("Completed"));
    item["DateCreated"] = item
        .get("DateCreated")
        .cloned()
        .or_else(|| item.get("StartDate").cloned())
        .unwrap_or(serde_json::Value::Null);
    item["SeriesName"] = item
        .get("SeriesName")
        .cloned()
        .or_else(|| item.get("Series").cloned())
        .unwrap_or(serde_json::Value::Null);
    item["RecordingType"] = item
        .get("RecordingType")
        .cloned()
        .unwrap_or_else(|| serde_json::json!("Manual"));
    Some(item)
}

fn live_tv_recording_path(recording: &serde_json::Value) -> Result<PathBuf, ApiError> {
    json_string_field(recording, "Path")
        .or_else(|| json_string_field(recording, "MediaPath"))
        .map(PathBuf::from)
        .filter(|path| !path.as_os_str().is_empty())
        .ok_or_else(|| ApiError::not_found("Live TV stream not found"))
}

fn live_tv_recording_content_type(path: &FsPath) -> &'static str {
    match path
        .extension()
        .and_then(|extension| extension.to_str())
        .map(str::to_ascii_lowercase)
        .as_deref()
    {
        Some("ts") => "video/mp2t",
        Some("mp4" | "m4v") => "video/mp4",
        Some("mkv") => "video/x-matroska",
        Some("webm") => "video/webm",
        _ => "application/octet-stream",
    }
}

// Replace characters that are invalid in most filesystem paths with underscores.
// Parses the same set as .NET's Path.GetInvalidFileNameChars() on Linux (/ and \0 are the
// primary culprits; we also strip the Windows-invalid set for cross-platform compatibility).
fn get_valid_filename(s: &str) -> String {
    s.chars()
        .map(|c| match c {
            '/' | '\\' | ':' | '*' | '?' | '"' | '<' | '>' | '|' | '\0' => '_',
            c => c,
        })
        .collect()
}

// Build the recording file name matching RecordingHelper.GetRecordingName (non-series path):
//   name + " " + StartDate.ToString("yyyy_MM_dd_HH_mm_ss")
// The time crate's local-offset feature is not enabled; we format in UTC (close enough for
// file naming, which is only used internally and not exposed in comparisons).
fn live_tv_recording_name(name: &str, start_date: OffsetDateTime) -> String {
    let date_str = format!(
        "{:04}_{:02}_{:02}_{:02}_{:02}_{:02}",
        start_date.year(),
        start_date.month() as u8,
        start_date.day(),
        start_date.hour(),
        start_date.minute(),
        start_date.second(),
    );
    format!("{name} {date_str}")
}

// Returns the recordings directory: DataPath/livetv/recordings.
// DataPath mirrors system_info's data_root = log_dir.parent() (fallback to log_dir itself).
fn live_tv_recordings_dir(log_dir: &FsPath) -> PathBuf {
    let data_root = log_dir.parent().unwrap_or(log_dir).to_path_buf();
    data_root.join("livetv").join("recordings")
}

fn live_tv_timer_start_date(timer: &serde_json::Value) -> Option<OffsetDateTime> {
    json_string_field(timer, "StartDate")
        .and_then(|value| OffsetDateTime::parse(&value, &Rfc3339).ok())
}

fn live_tv_timer_post_padding_seconds(timer: &serde_json::Value) -> i64 {
    json_string_field(timer, "PostPaddingSeconds")
        .and_then(|value| value.parse::<i64>().ok())
        .or_else(|| {
            timer
                .get("PostPaddingSeconds")
                .and_then(serde_json::Value::as_i64)
        })
        .unwrap_or(0)
}

fn live_tv_timer_recording_end(timer: &serde_json::Value) -> Option<OffsetDateTime> {
    json_string_field(timer, "EndDate")
        .and_then(|value| OffsetDateTime::parse(&value, &Rfc3339).ok())
        .map(|end| end + Duration::seconds(live_tv_timer_post_padding_seconds(timer)))
}

fn live_tv_timer_is_terminal(timer: &serde_json::Value) -> bool {
    json_string_field(timer, "Status").is_some_and(|status| {
        status.eq_ignore_ascii_case("Completed") || status.eq_ignore_ascii_case("Cancelled")
    })
}

// Compute a stable, deterministic Id for a timer generated from a series timer.
// Paridad: DefaultLiveTvService.CreateTimer Id=MD5(seriesTimerId+program.ExternalId).
// We use the same FNV-based stable_entity_id pattern used elsewhere in Jellyrin.
fn series_timer_child_id(series_timer_id: &str, program_id: &str) -> String {
    stable_entity_id(
        "SeriesTimerChild",
        &format!("{series_timer_id}+{program_id}"),
    )
}

// Generate child timers in config["Timers"] for programs that match this series timer.
// Paridad: DefaultLiveTvService.UpdateTimersForSeriesTimer + GetTimersForSeries.
// Match rules (DS2 subset):
//   - Name case-insensitive match OR SeriesId match.
//   - Scope: ChannelId must match unless RecordAnyChannel==true.
//   - Window: program EndDate >= now (expired programs skip).
// Each matched program gets a child timer (IsSeries=false, SeriesTimerId set, Id stable).
// maybe_spawn_live_tv_recording is called for each child timer so in-window programs
// start recording immediately (paridad TimerManager.AddOrUpdateSystemTimer fire-on-create).
async fn materialize_series_timer_timers(state: &AppState, series_timer: &serde_json::Value) {
    let series_timer_id = match json_string_field(series_timer, "Id") {
        Some(id) if !id.is_empty() => id,
        _ => return,
    };
    let series_name = json_string_field(series_timer, "Name")
        .unwrap_or_default()
        .to_ascii_lowercase();
    let series_series_id = json_string_field(series_timer, "SeriesId");
    let record_any_channel = series_timer
        .get("RecordAnyChannel")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let series_channel_id = json_string_field(series_timer, "ChannelId");

    let now = OffsetDateTime::now_utc();

    let config = match ConfigurationService::new(&state.db).get("livetv").await {
        Ok(Some(c)) => c,
        Ok(None) => default_live_tv_configuration(),
        Err(_) => return,
    };

    let server_id = match state.db.server_state().await {
        Ok(state) => state.server_id.to_string(),
        Err(error) => {
            tracing::warn!("failed to resolve server id for series timer materialisation: {error}");
            String::new()
        }
    };
    let programs = live_tv_program_items(&config, &server_id);

    let mut new_timers: Vec<serde_json::Value> = Vec::new();

    for program in &programs {
        let program_id = match json_string_field(program, "Id") {
            Some(id) if !id.is_empty() => id,
            _ => continue,
        };
        let raw_program_id =
            json_string_field(program, "JellyrinProgramId").unwrap_or_else(|| program_id.clone());

        // Window check: program EndDate must be >= now.
        let end_date = match json_string_field(program, "EndDate")
            .and_then(|s| OffsetDateTime::parse(&s, &Rfc3339).ok())
        {
            Some(dt) => dt,
            None => continue,
        };
        if end_date < now {
            continue;
        }

        // Name / SeriesId match.
        let program_name = json_string_field(program, "Name")
            .unwrap_or_default()
            .to_ascii_lowercase();
        let program_series_id = json_string_field(program, "SeriesId");
        let name_match = !series_name.is_empty() && program_name == series_name;
        let series_id_match = series_series_id.is_some() && series_series_id == program_series_id;
        if !name_match && !series_id_match {
            continue;
        }

        // Channel scope check.
        // Program ChannelId may be an XMLTV guide number (e.g. "4.1") while the series timer
        // ChannelId is the Jellyrin channel Id (e.g. "hdhr_4.1"). Accept both forms.
        let program_channel_id = json_string_field(program, "JellyrinChannelId")
            .or_else(|| json_string_field(program, "ChannelId"))
            .unwrap_or_default();
        // Resolve the effective channel Id for the child timer: prefer the series timer's
        // channel Id if it matches (so maybe_spawn can find the channel), else use the program's.
        let effective_channel_id = if let Some(ref scid) = series_channel_id {
            let guide_from_series = scid.strip_prefix("hdhr_").unwrap_or(scid.as_str());
            let guide_from_program = program_channel_id
                .strip_prefix("hdhr_")
                .unwrap_or(program_channel_id.as_str());
            if guide_from_series.eq_ignore_ascii_case(guide_from_program)
                || scid.eq_ignore_ascii_case(&program_channel_id)
            {
                scid.clone()
            } else {
                program_channel_id.clone()
            }
        } else {
            program_channel_id.clone()
        };
        if !record_any_channel && let Some(ref scid) = series_channel_id {
            let guide_from_series = scid.strip_prefix("hdhr_").unwrap_or(scid.as_str());
            let guide_from_program = program_channel_id
                .strip_prefix("hdhr_")
                .unwrap_or(program_channel_id.as_str());
            let channel_matches = scid.eq_ignore_ascii_case(&program_channel_id)
                || guide_from_series.eq_ignore_ascii_case(guide_from_program);
            if !channel_matches {
                continue;
            }
        }

        let child_id = series_timer_child_id(&series_timer_id, &raw_program_id);
        let start_date_val = program
            .get("StartDate")
            .cloned()
            .unwrap_or(serde_json::Value::Null);
        let end_date_val = program
            .get("EndDate")
            .cloned()
            .unwrap_or(serde_json::Value::Null);
        let channel_id_val = serde_json::json!(effective_channel_id);
        let name_val = program
            .get("Name")
            .cloned()
            .unwrap_or_else(|| serde_json::json!(""));

        let child_timer = serde_json::json!({
            "Id": child_id,
            "SeriesTimerId": series_timer_id,
            "ProgramId": program_id,
            "JellyrinProgramId": raw_program_id,
            "ChannelId": channel_id_val,
            "Name": name_val,
            "StartDate": start_date_val,
            "EndDate": end_date_val,
            "PrePaddingSeconds": 0,
            "PostPaddingSeconds": 0,
            "Priority": 0,
            "IsPrePaddingRequired": false,
            "IsPostPaddingRequired": false,
            "KeepUntil": "UntilDeleted",
            "RecordAnyTime": false,
            "SkipEpisodesInLibrary": false,
            "RecordAnyChannel": false,
            "NewOnly": false,
            "Days": [],
            "IsSeries": false,
        });
        new_timers.push(child_timer);
    }

    if new_timers.is_empty() {
        return;
    }

    // Upsert all child timers into config["Timers"].
    let mut config = match ConfigurationService::new(&state.db).get("livetv").await {
        Ok(Some(c)) => c,
        Ok(None) => default_live_tv_configuration(),
        Err(_) => return,
    };
    let mut timers = config
        .get("Timers")
        .and_then(serde_json::Value::as_array)
        .cloned()
        .unwrap_or_default();

    for child in &new_timers {
        let child_id = json_string_field(child, "Id").unwrap_or_default();
        // Idempotent: skip if timer already exists (same Id).
        if timers.iter().any(|t| {
            json_string_field(t, "Id").is_some_and(|id| id.eq_ignore_ascii_case(&child_id))
        }) {
            continue;
        }
        timers.push(child.clone());
    }
    config["Timers"] = serde_json::json!(timers);
    if let Err(err) = state
        .db
        .update_named_configuration("livetv", live_tv_configuration_json(config))
        .await
    {
        tracing::error!("failed to persist series timer child timers: {err}");
        return;
    }

    // Fire recordings for timers that are in-window.
    for child in &new_timers {
        maybe_spawn_live_tv_recording(state, child).await;
    }
}

// Cascade-delete timers in config["Timers"] that belong to the given series timer
// and are not currently being recorded (not in LIVE_TV_RECORDING_REGISTRY).
// Paridad: DefaultLiveTvService.CancelSeriesTimer (cancels pending child timers).
async fn cascade_delete_series_timer_timers(db: &Database, series_timer_id: &str) {
    let active_timer_ids: Vec<String> = {
        let registry = live_tv_recording_registry().lock().await;
        registry.keys().cloned().collect()
    };

    let mut config = match ConfigurationService::new(db).get("livetv").await {
        Ok(Some(c)) => c,
        Ok(None) => return,
        Err(_) => return,
    };

    let timers = match config
        .get("Timers")
        .and_then(serde_json::Value::as_array)
        .cloned()
    {
        Some(t) => t,
        None => return,
    };

    let kept: Vec<serde_json::Value> = timers
        .into_iter()
        .filter(|timer| {
            let belongs = json_string_field(timer, "SeriesTimerId")
                .is_some_and(|stid| stid.eq_ignore_ascii_case(series_timer_id));
            if !belongs {
                return true;
            }
            // Keep if currently recording (in active registry).
            let timer_id = json_string_field(timer, "Id").unwrap_or_default();
            active_timer_ids
                .iter()
                .any(|active| active.eq_ignore_ascii_case(&timer_id))
        })
        .collect();

    config["Timers"] = serde_json::json!(kept);
    let _ = db
        .update_named_configuration("livetv", live_tv_configuration_json(config))
        .await;
}

// Check whether the timer should trigger an immediate recording and, if so, spawn the task.
// Trigger condition (paridad TimerManager.AddOrUpdateSystemTimer :101-104):
//   StartDate <= now && EndDate+PostPaddingSeconds > now && key == "Timers" && !is_series.
// Channel must be a known remote (HDHomeRun) channel; local channels are left to the
// normal recording path (out of scope for this subgate).
async fn maybe_spawn_live_tv_recording(state: &AppState, timer: &serde_json::Value) -> bool {
    // Only manual (non-series) timers in the Timers key trigger immediate recording.
    if timer
        .get("IsSeries")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false)
    {
        return false;
    }
    if live_tv_timer_is_terminal(timer) {
        return false;
    }
    let timer_id = match json_string_field(timer, "Id") {
        Some(id) if !id.is_empty() => id,
        _ => return false,
    };
    {
        let registry = live_tv_recording_registry().lock().await;
        if registry
            .keys()
            .any(|active| active.eq_ignore_ascii_case(&timer_id))
        {
            return false;
        }
    }

    let now = OffsetDateTime::now_utc();

    // Parse StartDate — timer must have already started.
    let start_date = match json_string_field(timer, "StartDate")
        .and_then(|s| OffsetDateTime::parse(&s, &Rfc3339).ok())
    {
        Some(dt) => dt,
        None => return false,
    };
    if start_date > now {
        return false;
    }

    // Parse EndDate + PostPaddingSeconds — window must still be open.
    let end_date = match json_string_field(timer, "EndDate")
        .and_then(|s| OffsetDateTime::parse(&s, &Rfc3339).ok())
    {
        Some(dt) => dt,
        None => return false,
    };
    let post_padding = timer
        .get("PostPaddingSeconds")
        .and_then(|v| v.as_i64())
        .unwrap_or(0);
    let recording_end = end_date + Duration::seconds(post_padding);
    if recording_end <= now {
        // Window already expired — nothing to record.
        return false;
    }

    // Resolve the channel URL.
    let channel_id = match json_string_field(timer, "ChannelId") {
        Some(id) if !id.is_empty() => id,
        _ => return false,
    };
    let channel = match live_tv_channel_by_id(&state.db, &channel_id).await {
        Ok(ch) => ch,
        Err(_) => return false,
    };
    let channel_url = if live_tv_channel_uses_opaque_provider(&channel) {
        format!(
            "opaque:{}",
            stable_entity_id("livetv-recording", &channel_id)
        )
    } else {
        let channel_path = match live_tv_channel_path(&channel) {
            Ok(path) => path,
            Err(_) => return false,
        };
        if !live_tv_channel_is_remote(&channel_path)
            && !live_tv_channel_is_legacy_hdhomerun_path(&channel_path)
        {
            // Local channel — not supported in this subgate.
            return false;
        }
        channel_path.to_string_lossy().into_owned()
    };
    let (tuner_host_id, tuner_count) = live_tv_channel_tuner_limit(&state.db, &channel).await;

    if live_tv_recording_is_active(&timer_id).await {
        return false;
    }
    let Some(start_guard) = reserve_live_tv_recording_start(&timer_id) else {
        return false;
    };

    spawn_live_tv_recording(
        state.db.clone(),
        state.log_dir.clone(),
        timer.clone(),
        channel_url,
        tuner_host_id,
        tuner_count,
        start_guard,
    );
    true
}

// Spawn a recording task for the given timer onto the given channel.
// Returns immediately; the actual copy runs in a background tokio task.
// Paridad: DirectRecorder.RecordFromMediaSource + RecordingsManager.RecordStream lifecycle.
fn spawn_live_tv_recording(
    db: Database,
    log_dir: PathBuf,
    timer: serde_json::Value,
    channel_url: String,
    tuner_host_id: Option<String>,
    tuner_count: Option<u64>,
    start_guard: LiveTvRecordingStartGuard,
) {
    let timer_id = start_guard.timer_id.clone();
    let generation = start_guard.generation;
    let (launch, launched) = oneshot::channel::<()>();
    let task = tokio::spawn(async move {
        if launched.await.is_err() {
            return;
        }
        record_channel_to_file(
            db,
            log_dir,
            timer,
            channel_url,
            tuner_host_id,
            tuner_count,
            Some(start_guard),
        )
        .await;
    });
    match retain_live_tv_recording_start_task(&timer_id, generation, task) {
        Ok(()) => {
            let _ = launch.send(());
        }
        Err(task) => {
            task.abort();
            drop(launch);
        }
    }
}

async fn open_opaque_live_tv_recording_stream(
    db: &Database,
    channel_id: &str,
) -> Result<reqwest::Response, ApiError> {
    let channel = live_tv_channel_by_id(db, channel_id).await?;
    let playback = resolve_opaque_live_tv_playback(db, &channel, None).await?;
    if !opaque_live_tv_delivery_is_safe_for_direct_proxy(&playback) {
        return Err(ApiError::service_unavailable(
            "Live TV provider did not authorize a safe recording stream",
        ));
    }
    let configured_proxy = if playback.delivery.requires_provider_egress {
        Some(
            std::env::var("JELLYRIN_PROVIDER_EGRESS_PROXY").map_err(|_| {
                ApiError::service_unavailable("Live TV provider egress proxy is not configured")
            })?,
        )
    } else {
        None
    };
    let response = send_sensitive_remote_live_request_with_proxy(
        playback.source_url.expose_secret(),
        playback.delivery.requires_provider_egress,
        configured_proxy.as_deref(),
        LIVE_TV_REMOTE_CONTROL_TIMEOUT,
    )
    .await?;
    if response
        .headers()
        .get(header::CONTENT_TYPE)
        .and_then(|value| value.to_str().ok())
        .is_some_and(is_hls_manifest_content_type)
    {
        return Err(ApiError::service_unavailable(
            "Live TV provider returned an unsupported recording manifest",
        ));
    }
    Ok(response)
}

async fn record_channel_to_file(
    db: Database,
    log_dir: PathBuf,
    timer: serde_json::Value,
    channel_url: String,
    tuner_host_id: Option<String>,
    tuner_count: Option<u64>,
    start_guard: Option<LiveTvRecordingStartGuard>,
) {
    let start_guard = start_guard;
    let timer_id = json_string_field(&timer, "Id").unwrap_or_default();
    let name = json_string_field(&timer, "Name").unwrap_or_else(|| "Recording".to_string());
    let channel_id = json_string_field(&timer, "ChannelId").unwrap_or_default();

    // Parse StartDate and EndDate from the timer (RFC3339 strings).
    let start_date = json_string_field(&timer, "StartDate")
        .and_then(|s| OffsetDateTime::parse(&s, &Rfc3339).ok())
        .unwrap_or_else(OffsetDateTime::now_utc);
    let end_date = json_string_field(&timer, "EndDate")
        .and_then(|s| OffsetDateTime::parse(&s, &Rfc3339).ok())
        .unwrap_or_else(OffsetDateTime::now_utc);
    let post_padding_secs = json_string_field(&timer, "PostPaddingSeconds")
        .and_then(|s| s.parse::<i64>().ok())
        .or_else(|| timer.get("PostPaddingSeconds").and_then(|v| v.as_i64()))
        .unwrap_or(0);
    let recording_end = end_date + Duration::seconds(post_padding_secs);
    let now = OffsetDateTime::now_utc();
    if recording_end <= now {
        // Window already expired; skip.
        return;
    }
    let duration = recording_end - now;
    let is_legacy_hdhomerun = channel_url.to_ascii_lowercase().starts_with("hdhomerun");
    let is_opaque_provider = channel_url.starts_with("opaque:");
    if runtime_shutdown_started() || start_guard.as_ref().is_some_and(|guard| guard.cancelled()) {
        return;
    }

    let legacy_source = if is_legacy_hdhomerun {
        let params =
            match legacy_hdhomerun_stream_params_for_host(&db, tuner_host_id.as_deref()).await {
                Ok(params) => params,
                Err(error) => {
                    tracing::warn!("skipping legacy HDHomeRun recording: {error:?}");
                    return;
                }
            };
        match subscribe_legacy_hdhomerun_stream(
            channel_url.clone(),
            params.tuner_host_url,
            params.control_port,
            params.num_tuners,
            tuner_host_id.clone(),
            tuner_count,
        )
        .await
        {
            Ok(subscription) => Some(subscription),
            Err(error) => {
                tracing::warn!(
                    "skipping legacy HDHomeRun recording because stream open failed: {error:?}"
                );
                return;
            }
        }
    } else {
        None
    }
    .map(|subscription| {
        let consumer = subscription.into_consumer();
        (consumer.receiver, consumer.guard)
    });

    let _tuner_lease = if is_legacy_hdhomerun {
        None
    } else if is_opaque_provider {
        match acquire_unshared_live_tuner_lease(tuner_host_id, &channel_id, tuner_count) {
            Ok(lease) => lease,
            Err(error) => {
                tracing::warn!(
                    "skipping opaque Live TV recording because tuner limit was reached: {error:?}"
                );
                return;
            }
        }
    } else {
        match acquire_live_tuner_lease(tuner_host_id, &channel_url, tuner_count) {
            Ok(lease) => lease,
            Err(error) => {
                tracing::warn!(
                    "skipping Live TV recording because tuner limit was reached: {error:?}"
                );
                return;
            }
        }
    };

    // Build the file path: DataPath/livetv/recordings/<ValidFilename(Name+" "+StartDate
    // yyyy_MM_dd_HH_mm_ss)>.ts
    let recording_file_name = get_valid_filename(&live_tv_recording_name(&name, start_date));
    let recordings_dir = live_tv_recordings_dir(&log_dir);
    let recording_path = recordings_dir.join(format!("{recording_file_name}.ts"));
    let recording_id = Uuid::new_v4().simple().to_string();
    let path_str = recording_path.to_string_lossy().to_string();

    // Promote STARTING to an externally cancellable active handle before creating files or
    // persisting InProgress state. The terminal flag is checked while holding this mutex: if a
    // task wins the race, shutdown necessarily observes the inserted handle in its later sweep.
    let (cancel_tx, mut cancel_rx) = oneshot::channel::<()>();
    {
        let mut registry = live_tv_recording_registry().lock().await;
        if runtime_shutdown_started() || start_guard.as_ref().is_some_and(|guard| guard.cancelled())
        {
            return;
        }
        registry.insert(
            timer_id.clone(),
            LiveTvRecordingHandle {
                _cancel: cancel_tx,
                path: path_str.clone(),
            },
        );
    }
    // Removing the STARTING entry drops this task's retained JoinHandle only after the active
    // cancellation handle is visible.
    drop(start_guard);

    // Ensure directory exists.
    let create_directory = tokio::select! {
        biased;
        _ = &mut cancel_rx => {
            live_tv_recording_registry().lock().await.remove(&timer_id);
            return;
        }
        result = tokio::fs::create_dir_all(&recordings_dir) => result,
    };
    if let Err(err) = create_directory {
        tracing::error!(path = %recordings_dir.display(), "failed to create recordings dir: {err}");
        live_tv_recording_registry().lock().await.remove(&timer_id);
        return;
    }

    // Create the output file (CreateNew = fail if exists, paridad upstream FileMode.CreateNew).
    let mut open_options = tokio::fs::OpenOptions::new();
    open_options.write(true).create_new(true);
    let open_file = open_options.open(&recording_path);
    let open_file = tokio::select! {
        biased;
        _ = &mut cancel_rx => {
            live_tv_recording_registry().lock().await.remove(&timer_id);
            return;
        }
        result = open_file => result,
    };
    let mut file = match open_file {
        Ok(f) => f,
        Err(err) => {
            tracing::error!(path = %recording_path.display(), "failed to create recording file: {err}");
            live_tv_recording_registry().lock().await.remove(&timer_id);
            return;
        }
    };

    // Persist InProgress status before opening the upstream connection.
    {
        let configuration_service = ConfigurationService::new(&db);
        let load_config = configuration_service.get("livetv");
        let load_config = tokio::select! {
            biased;
            _ = &mut cancel_rx => {
                cleanup_failed_recording(&db, &timer_id, &recording_id, &recording_path).await;
                return;
            }
            result = load_config => result,
        };
        let mut config = match load_config {
            Ok(c) => c.unwrap_or_else(default_live_tv_configuration),
            Err(err) => {
                tracing::error!("failed to load livetv config for recording: {err}");
                cleanup_failed_recording(&db, &timer_id, &recording_id, &recording_path).await;
                return;
            }
        };
        let mut recordings = config
            .get("Recordings")
            .and_then(serde_json::Value::as_array)
            .cloned()
            .unwrap_or_default();
        recordings.push(serde_json::json!({
            "Id": recording_id,
            "TimerId": timer_id,
            "ProgramId": timer.get("ProgramId").cloned().unwrap_or(serde_json::Value::Null),
            "SeriesTimerId": timer.get("SeriesTimerId").cloned().unwrap_or(serde_json::Value::Null),
            "Name": name,
            "ChannelId": channel_id,
            "Path": path_str,
            "Status": "InProgress",
            "StartDate": format_time_for_json(start_date),
            "EndDate": format_time_for_json(end_date),
            "DateCreated": format_time_for_json(now),
        }));
        config["Recordings"] = serde_json::json!(recordings);
        let persist = db.update_named_configuration("livetv", live_tv_configuration_json(config));
        let persist = tokio::select! {
            biased;
            _ = &mut cancel_rx => {
                cleanup_failed_recording(&db, &timer_id, &recording_id, &recording_path).await;
                return;
            }
            result = persist => result,
        };
        if let Err(err) = persist {
            tracing::error!("failed to persist InProgress recording: {err}");
        }
    }

    // Copy bytes from the channel stream to the file until duration expires or cancel fires.
    let duration_std = std::time::Duration::from_secs_f64(duration.as_seconds_f64().max(0.0));
    let sleep_fut = tokio::time::sleep(duration_std);
    tokio::pin!(sleep_fut);
    tokio::pin!(cancel_rx);

    use futures_util::StreamExt;
    use tokio::io::AsyncWriteExt;

    let mut bytes_written: u64 = 0;
    if let Some((mut receiver, _stream_guard)) = legacy_source {
        loop {
            tokio::select! {
                _ = &mut sleep_fut => {
                    // Duration expired — stop recording normally.
                    break;
                }
                _ = &mut cancel_rx => {
                    // External cancel (e.g. server shutdown).
                    break;
                }
                chunk = receiver.recv() => {
                    match chunk {
                        Ok(bytes) => {
                            if let Err(err) = file.write_all(&bytes).await {
                                tracing::error!(path = %recording_path.display(), "write error during recording: {err}");
                                break;
                            }
                            bytes_written += bytes.len() as u64;
                        }
                        Err(broadcast::error::RecvError::Lagged(n)) => {
                            tracing::warn!("legacy HDHomeRun recording lagged, dropped {n} chunks");
                            continue;
                        }
                        Err(broadcast::error::RecvError::Closed) => {
                            break;
                        }
                    }
                }
            }
        }
    } else {
        // Open the upstream HTTP stream (paridad DirectRecorder.RecordFromMediaSource).
        let open_upstream = async {
            if is_opaque_provider {
                open_opaque_live_tv_recording_stream(&db, &channel_id).await
            } else {
                open_validated_live_tv_stream(&channel_url, LIVE_TV_REMOTE_CONTROL_TIMEOUT)
                    .await
                    .map_err(|error| match error {
                        LiveTvRemoteFetchError::Validation(_) => ApiError::service_unavailable(
                            "recording source failed strict validation",
                        ),
                        LiveTvRemoteFetchError::Request { .. } => {
                            ApiError::service_unavailable("recording source could not be opened")
                        }
                        LiveTvRemoteFetchError::BodyTooLarge => {
                            ApiError::service_unavailable("recording source response is invalid")
                        }
                    })
            }
        };
        let open_upstream = tokio::select! {
            biased;
            _ = &mut cancel_rx => {
                cleanup_failed_recording(&db, &timer_id, &recording_id, &recording_path).await;
                return;
            }
            result = open_upstream => result,
        };
        let upstream_resp = match open_upstream {
            Ok(resp) if resp.status().is_success() => resp,
            Ok(resp) => {
                tracing::error!(
                    %timer_id,
                    %channel_id,
                    status = %resp.status(),
                    "upstream channel returned non-2xx for recording"
                );
                cleanup_failed_recording(&db, &timer_id, &recording_id, &recording_path).await;
                return;
            }
            Err(error) => {
                tracing::error!(
                    %timer_id,
                    %channel_id,
                    status = %error.status(),
                    "failed to open channel stream for recording"
                );
                cleanup_failed_recording(&db, &timer_id, &recording_id, &recording_path).await;
                return;
            }
        };
        let mut byte_stream = upstream_resp.bytes_stream();
        loop {
            tokio::select! {
                _ = &mut sleep_fut => {
                    // Duration expired — stop recording normally.
                    break;
                }
                _ = &mut cancel_rx => {
                    // External cancel (e.g. server shutdown).
                    break;
                }
                chunk = byte_stream.next() => {
                    match chunk {
                        Some(Ok(bytes)) => {
                            if let Err(err) = file.write_all(&bytes).await {
                                tracing::error!(path = %recording_path.display(), "write error during recording: {err}");
                                break;
                            }
                            bytes_written += bytes.len() as u64;
                        }
                        Some(Err(err)) => {
                            tracing::warn!(
                                %timer_id,
                                %channel_id,
                                timeout = err.is_timeout(),
                                connect = err.is_connect(),
                                "stream error during recording"
                            );
                            break;
                        }
                        None => {
                            // Stream ended (source closed).
                            break;
                        }
                    }
                }
            }
        }
    }

    // Flush and close the file before checking size.
    drop(file);

    // Remove from active registry.
    {
        let mut registry = live_tv_recording_registry().lock().await;
        registry.remove(&timer_id);
    }

    // Post-recording: check file size (paridad RecordingsManager: DeleteFileIfEmpty + status).
    let file_exists_and_nonempty = tokio::fs::metadata(&recording_path)
        .await
        .map(|m| m.len() > 0)
        .unwrap_or(false);

    if file_exists_and_nonempty {
        // Completed with real bytes: update recording to Completed + set timer RecordingPath.
        tracing::info!(path = %recording_path.display(), bytes = bytes_written, "recording completed");
        let mut config = match ConfigurationService::new(&db).get("livetv").await {
            Ok(c) => c.unwrap_or_else(default_live_tv_configuration),
            Err(_) => return,
        };
        // Update recording status.
        if let Some(recordings) = config.get_mut("Recordings").and_then(|v| v.as_array_mut()) {
            for rec in recordings.iter_mut() {
                if json_string_field(rec, "Id")
                    .is_some_and(|id| id.eq_ignore_ascii_case(&recording_id))
                {
                    rec["Status"] = serde_json::json!("Completed");
                    break;
                }
            }
        }
        // Update the timer status and RecordingPath (paridad upstream timer.RecordingPath +
        // Status=Completed).
        if let Some(timers) = config.get_mut("Timers").and_then(|v| v.as_array_mut()) {
            for t in timers.iter_mut() {
                if json_string_field(t, "Id").is_some_and(|id| id.eq_ignore_ascii_case(&timer_id)) {
                    t["Status"] = serde_json::json!("Completed");
                    t["RecordingPath"] = serde_json::json!(path_str);
                    break;
                }
            }
        }
        let _ = db
            .update_named_configuration("livetv", live_tv_configuration_json(config))
            .await;
    } else {
        // Zero-byte file: delete it and the timer (paridad upstream: delete timer if !File.Exists).
        tracing::warn!(path = %recording_path.display(), "recording produced 0 bytes; removing");
        let _ = tokio::fs::remove_file(&recording_path).await;
        let mut config = match ConfigurationService::new(&db).get("livetv").await {
            Ok(c) => c.unwrap_or_else(default_live_tv_configuration),
            Err(_) => return,
        };
        // Remove the InProgress recording entry.
        if let Some(recordings) = config.get("Recordings").and_then(|v| v.as_array()) {
            let kept: Vec<_> = recordings
                .iter()
                .filter(|rec| {
                    !json_string_field(rec, "Id")
                        .is_some_and(|id| id.eq_ignore_ascii_case(&recording_id))
                })
                .cloned()
                .collect();
            config["Recordings"] = serde_json::json!(kept);
        }
        // Remove the timer.
        if let Some(timers) = config.get("Timers").and_then(|v| v.as_array()) {
            let kept: Vec<_> = timers
                .iter()
                .filter(|t| {
                    !json_string_field(t, "Id").is_some_and(|id| id.eq_ignore_ascii_case(&timer_id))
                })
                .cloned()
                .collect();
            config["Timers"] = serde_json::json!(kept);
        }
        let _ = db
            .update_named_configuration("livetv", live_tv_configuration_json(config))
            .await;
    }
}

async fn cleanup_failed_recording(
    db: &Database,
    timer_id: &str,
    recording_id: &str,
    recording_path: &FsPath,
) {
    let _ = tokio::fs::remove_file(recording_path).await;
    let mut registry = live_tv_recording_registry().lock().await;
    registry.remove(timer_id);
    drop(registry);
    let mut config = match ConfigurationService::new(db).get("livetv").await {
        Ok(c) => c.unwrap_or_else(default_live_tv_configuration),
        Err(_) => return,
    };
    if let Some(recordings) = config.get("Recordings").and_then(|v| v.as_array()) {
        let kept: Vec<_> = recordings
            .iter()
            .filter(|rec| {
                !json_string_field(rec, "Id")
                    .is_some_and(|id| id.eq_ignore_ascii_case(recording_id))
            })
            .cloned()
            .collect();
        config["Recordings"] = serde_json::json!(kept);
    }
    let _ = db
        .update_named_configuration("livetv", live_tv_configuration_json(config))
        .await;
}

fn live_tv_recording_group_items(
    config: &serde_json::Value,
    server_id: &str,
    group_type: &'static str,
) -> Vec<serde_json::Value> {
    let mut groups: BTreeMap<String, usize> = BTreeMap::new();
    for recording in live_tv_recording_items(config, server_id) {
        let key = match group_type {
            "Folder" => json_string_field(&recording, "FolderName")
                .or_else(|| json_string_field(&recording, "Category"))
                .unwrap_or_else(|| "Recordings".to_string()),
            "Series" => json_string_field(&recording, "SeriesName")
                .or_else(|| json_string_field(&recording, "Name"))
                .unwrap_or_else(|| "Recordings".to_string()),
            _ => json_string_field(&recording, "GroupName")
                .or_else(|| json_string_field(&recording, "SeriesName"))
                .or_else(|| json_string_field(&recording, "Name"))
                .unwrap_or_else(|| "Recordings".to_string()),
        };
        *groups.entry(key).or_insert(0) += 1;
    }
    groups
        .into_iter()
        .map(|(name, count)| {
            serde_json::json!({
                "Id": sanitize_live_tv_group_id(&name),
                "Name": name,
                "Type": format!("Recording{group_type}"),
                "IsFolder": true,
                "ChildCount": count,
                "RecordingCount": count
            })
        })
        .collect()
}

fn sanitize_live_tv_group_id(name: &str) -> String {
    name.to_ascii_lowercase()
        .chars()
        .map(|character| {
            if character.is_ascii_alphanumeric() {
                character
            } else {
                '-'
            }
        })
        .collect::<String>()
        .trim_matches('-')
        .to_string()
}

async fn delete_persisted_live_tv_recording(
    db: &Database,
    recording_id: &str,
) -> Result<StatusCode, ApiError> {
    let service = LiveTvService::new(db);
    let mut config = service
        .configuration()
        .await?
        .unwrap_or_else(default_live_tv_configuration);
    let mut recordings = config
        .get("Recordings")
        .and_then(serde_json::Value::as_array)
        .cloned()
        .unwrap_or_default();
    let before = recordings.len();
    recordings.retain(|recording| {
        json_string_field(recording, "Id")
            .or_else(|| json_string_field(recording, "RecordingId"))
            .is_none_or(|id| !id.eq_ignore_ascii_case(recording_id))
    });
    if recordings.len() == before {
        return Err(ApiError::not_found("Live TV recording not found"));
    }
    config["Recordings"] = serde_json::json!(recordings);
    service
        .update_configuration(live_tv_configuration_json(config))
        .await?;
    Ok(StatusCode::NO_CONTENT)
}

fn live_tv_channel_mapping_option(channel: serde_json::Value) -> serde_json::Value {
    serde_json::json!({
        "Id": json_string_field(&channel, "Id").unwrap_or_default(),
        "Name": json_string_field(&channel, "Name").unwrap_or_default(),
        "Number": json_string_field(&channel, "Number"),
        "ChannelId": json_string_field(&channel, "ChannelId").unwrap_or_default()
    })
}

fn live_tv_provider_channels(provider: &serde_json::Value) -> Vec<serde_json::Value> {
    if let Some(channels) = provider
        .get("Channels")
        .and_then(serde_json::Value::as_array)
    {
        return channels
            .iter()
            .enumerate()
            .filter_map(|channel| live_tv_provider_channel(channel.1, channel.0))
            .collect();
    }
    provider
        .get("ChannelMappings")
        .and_then(serde_json::Value::as_array)
        .map(|mappings| {
            mappings
                .iter()
                .filter_map(|mapping| {
                    let value = json_string_field(mapping, "Value")?;
                    Some(serde_json::json!({
                        "Id": value,
                        "Name": value,
                        "Number": null
                    }))
                })
                .collect()
        })
        .unwrap_or_default()
}

fn live_tv_provider_channel(
    channel: &serde_json::Value,
    index: usize,
) -> Option<serde_json::Value> {
    match channel {
        serde_json::Value::Object(_) => {
            let name = json_string_field(channel, "Name")
                .or_else(|| json_string_field(channel, "DisplayName"))
                .unwrap_or_else(|| format!("Provider Channel {}", index + 1));
            let id = json_string_field(channel, "Id")
                .or_else(|| json_string_field(channel, "ChannelId"))
                .unwrap_or_else(|| name.clone());
            Some(serde_json::json!({
                "Id": id,
                "Name": name,
                "Number": json_string_field(channel, "Number").or_else(|| json_string_field(channel, "ChannelNumber"))
            }))
        }
        serde_json::Value::String(name) if !name.trim().is_empty() => Some(serde_json::json!({
            "Id": name.trim(),
            "Name": name.trim(),
            "Number": null
        })),
        _ => None,
    }
}

