const CLIENT_LOG_DOCUMENT_LIMIT_BYTES: usize = 1024 * 1024;

async fn client_log_document(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    body: Body,
) -> Result<Json<serde_json::Value>, ApiError> {
    let user = require_request_user(&state.db, &headers, query.api_key.as_deref()).await?;
    let content_type = headers
        .get(header::CONTENT_TYPE)
        .and_then(|value| value.to_str().ok())
        .map(str::to_string);
    let file_name = headers
        .get(header::CONTENT_DISPOSITION)
        .and_then(|value| value.to_str().ok())
        .and_then(content_disposition_filename);
    let body = to_bytes(body, CLIENT_LOG_DOCUMENT_LIMIT_BYTES)
        .await
        .map_err(|_| ApiError::bad_request("Invalid client log document body"))?;
    tokio::fs::create_dir_all(&state.log_dir).await?;
    let path = state.log_dir.join("clientlog.log");
    let timestamp = OffsetDateTime::now_utc().format(&Rfc3339)?;
    let message = redact_sensitive_log_text(&String::from_utf8_lossy(&body).replace('\0', ""));
    let line = serde_json::json!({
        "Timestamp": timestamp,
        "UserId": user.id.simple().to_string(),
        "UserName": user.name,
        "Document": message,
        "ContentType": content_type,
        "FileName": file_name
    })
    .to_string();
    let mut file = tokio::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(path)
        .await?;
    use tokio::io::AsyncWriteExt;
    file.write_all(line.as_bytes()).await?;
    file.write_all(b"\n").await?;
    Ok(Json(serde_json::json!({ "FileName": "clientlog.log" })))
}

fn content_disposition_filename(value: &str) -> Option<String> {
    value.split(';').find_map(|part| {
        let (name, raw_value) = part.trim().split_once('=')?;
        if !name.trim().eq_ignore_ascii_case("filename") {
            return None;
        }
        let file_name = raw_value.trim().trim_matches('"').replace('\0', "");
        let file_name = std::path::Path::new(&file_name)
            .file_name()?
            .to_str()?
            .trim();
        (!file_name.is_empty()).then(|| file_name.to_string())
    })
}

fn redact_sensitive_log_text(input: &str) -> String {
    let mut output = input.to_string();
    for marker in [
        "api_key=",
        "apiKey=",
        "ApiKey=",
        "AccessToken=",
        "access_token=",
        "Token=\"",
        "token=",
        "X-Emby-Token:",
        "Authorization:",
        "\"AccessToken\":\"",
        "\"Token\":\"",
    ] {
        output = redact_marker_value(&output, marker);
    }
    output
}

fn redact_marker_value(input: &str, marker: &str) -> String {
    let mut output = String::with_capacity(input.len());
    let mut remaining = input;
    while let Some(index) = remaining.find(marker) {
        let (prefix, after_prefix) = remaining.split_at(index + marker.len());
        output.push_str(prefix);
        output.push_str("[REDACTED]");
        let mut end = after_prefix.len();
        let redact_until_line_end = matches!(marker, "Authorization:" | "X-Emby-Token:");
        for (char_index, character) in after_prefix.char_indices() {
            let is_stop = if redact_until_line_end {
                matches!(character, '\n' | '\r')
            } else {
                matches!(
                    character,
                    '&' | ' ' | '\n' | '\r' | '\t' | '"' | '\'' | ',' | ';' | '}'
                )
            };
            if is_stop {
                end = char_index;
                break;
            }
        }
        remaining = &after_prefix[end..];
    }
    output.push_str(remaining);
    output
}

