#[derive(Debug, Deserialize)]
struct DirectoryQuery {
    #[serde(alias = "Path", alias = "path")]
    path: Option<PathBuf>,
    #[serde(alias = "IncludeFiles")]
    include_files: Option<bool>,
}

async fn environment_directory_contents(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    Query(query): Query<DirectoryQuery>,
) -> Result<Json<Vec<serde_json::Value>>, ApiError> {
    require_admin_or_startup_incomplete(&state.db, &headers, auth_query.api_key.as_deref()).await?;
    let path = query.path.unwrap_or_else(|| PathBuf::from("/"));
    let include_files = query.include_files.unwrap_or(false);

    let entries = fs::read_dir(path)
        .map(|read_dir| {
            read_dir
                .filter_map(Result::ok)
                .filter_map(|entry| {
                    let metadata = entry.metadata().ok()?;
                    if metadata.is_file() && !include_files {
                        return None;
                    }

                    let path = entry.path();
                    let name = entry.file_name().to_string_lossy().into_owned();
                    Some(serde_json::json!({
                        "Name": name,
                        "Path": path,
                        "Type": if metadata.is_dir() { "Directory" } else { "File" },
                    }))
                })
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();

    Ok(Json(entries))
}

#[derive(Debug, Deserialize)]
struct PathQuery {
    #[serde(alias = "Path", alias = "path")]
    path: Option<PathBuf>,
}

async fn environment_parent_path(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    Query(query): Query<PathQuery>,
) -> Result<Json<Option<String>>, ApiError> {
    require_admin_or_startup_incomplete(&state.db, &headers, auth_query.api_key.as_deref()).await?;
    let parent = query
        .path
        .as_deref()
        .and_then(|path| path.parent())
        .map(|path| path.to_string_lossy().into_owned());
    Ok(Json(parent))
}

#[derive(Debug, Deserialize)]
struct ValidatePathRequest {
    #[serde(alias = "Path", alias = "path")]
    path: Option<PathBuf>,
}

async fn environment_validate_path(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    Json(payload): Json<ValidatePathRequest>,
) -> Result<StatusCode, ApiError> {
    require_admin_or_startup_incomplete(&state.db, &headers, query.api_key.as_deref()).await?;
    if payload.path.as_deref().is_some_and(|path| path.exists()) {
        Ok(StatusCode::NO_CONTENT)
    } else {
        Ok(StatusCode::BAD_REQUEST)
    }
}

async fn user_views_result(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<UserViewsQuery>,
) -> Result<Json<serde_json::Value>, ApiError> {
    let (auth_user, token) =
        require_user(&state.db, &headers, query.auth.api_key.as_deref()).await?;
    let requested_user_id = query.user_id.as_deref().map(resolve_user_id).transpose()?;
    if let Some(user_id) = requested_user_id {
        ensure_user_access(&auth_user, user_id)?;
    }
    let folders = state.db.virtual_folders().await?;
    let server_id = state.db.server_state().await?.server_id.to_string();
    let item_counts = catalog_cache::cached_media_item_counts_by_virtual_folder(&state.db).await?;
    let allowed = authorized_live_tv_tuner_ids(
        &state.db,
        &jellyrin_plugin_sdk::PluginUserContext {
            user_id: requested_user_id.unwrap_or(auth_user.id).to_string(),
            device_id: token.device_id,
            is_administrator: auth_user.is_administrator,
        },
    )
    .await?;
    let mut live_tv_tuners = configured_live_tv_tuner_views(&state.db).await?;
    if let Some(allowed) = allowed {
        live_tv_tuners.retain(|tuner| {
            allowed
                .iter()
                .any(|allowed| allowed.eq_ignore_ascii_case(&tuner.tuner_id))
        });
    }
    let items = user_views_for_query(&folders, &item_counts, &live_tv_tuners, &server_id, &query);
    Ok(Json(query_result(items)))
}

