#[derive(Debug, Deserialize, Default)]
struct UserViewsQuery {
    #[serde(flatten)]
    auth: AuthQuery,
    #[serde(alias = "UserId", alias = "userId")]
    user_id: Option<String>,
    #[serde(
        default,
        deserialize_with = "deserialize_csv_values",
        alias = "PresetViews",
        alias = "presetViews",
        alias = "presetviews",
        alias = "preset_views"
    )]
    preset_views: Vec<String>,
    #[serde(alias = "IncludeExternalContent", alias = "includeExternalContent")]
    _include_external_content: Option<bool>,
    #[serde(alias = "IncludeHidden", alias = "includeHidden")]
    _include_hidden: Option<bool>,
}

fn user_views_for_query(
    folders: &[VirtualFolder],
    item_counts: &HashMap<Uuid, usize>,
    live_tv_tuners: &[LiveTvTunerView],
    server_id: &str,
    query: &UserViewsQuery,
) -> Vec<serde_json::Value> {
    let preset_views = csv_values_lowercase(&query.preset_views);
    let mut items = folders
        .iter()
        .filter(|folder| {
            preset_views.as_ref().is_none_or(|presets| {
                folder
                    .collection_type
                    .as_deref()
                    .is_some_and(|collection_type| {
                        presets
                            .iter()
                            .any(|preset| preset.eq_ignore_ascii_case(collection_type))
                    })
            })
        })
        .map(|folder| {
            let child_count = virtual_folder_recursive_count(folder, folders, item_counts);
            user_view_to_json_with_count(folder, server_id, child_count)
        })
        .collect::<Vec<_>>();
    items.extend(special_user_views(server_id).into_iter().filter(|view| {
        preset_views.as_ref().is_none_or(|presets| {
            view.get("CollectionType")
                .and_then(serde_json::Value::as_str)
                .is_some_and(|collection_type| {
                    presets
                        .iter()
                        .any(|preset| preset.eq_ignore_ascii_case(collection_type))
                })
        })
    }));
    items.extend(
        live_tv_tuners
            .iter()
            .filter(|_| {
                preset_views.as_ref().is_none_or(|presets| {
                    presets
                        .iter()
                        .any(|preset| preset.eq_ignore_ascii_case("livetv"))
                })
            })
            .map(|tuner| live_tv_tuner_view_to_json(tuner, server_id)),
    );
    items
}

fn virtual_folder_recursive_count(
    folder: &VirtualFolder,
    folders: &[VirtualFolder],
    item_counts: &HashMap<Uuid, usize>,
) -> usize {
    let mut count = item_counts.get(&folder.id).copied().unwrap_or_default();
    for child in child_virtual_folders(folder, folders) {
        count += item_counts.get(&child.id).copied().unwrap_or_default();
    }
    count
}

fn grouping_options_for_folders(folders: &[VirtualFolder]) -> Vec<serde_json::Value> {
    let mut options = BTreeMap::<String, serde_json::Value>::new();
    for folder in folders {
        let Some(collection_type) = folder.collection_type.as_deref() else {
            continue;
        };
        options
            .entry(collection_type.to_ascii_lowercase())
            .or_insert_with(|| {
                serde_json::json!({
                    "Name": special_view_option_name(collection_type),
                    "Id": collection_type
                })
            });
    }
    for (_, collection_type) in SPECIAL_USER_VIEWS {
        options
            .entry(collection_type.to_ascii_lowercase())
            .or_insert_with(|| {
                serde_json::json!({
                    "Name": special_view_option_name(collection_type),
                    "Id": collection_type
                })
            });
    }
    options.into_values().collect()
}

fn special_view_option_name(collection_type: &str) -> String {
    match collection_type.to_ascii_lowercase().as_str() {
        "movies" => "Movies".to_string(),
        "tvshows" => "Shows".to_string(),
        "music" => "Music".to_string(),
        "books" => "Books".to_string(),
        "photos" => "Photos".to_string(),
        "homevideos" => "Home Videos".to_string(),
        "boxsets" => "Collections".to_string(),
        value => canonical_image_type(value),
    }
}

const SPECIAL_USER_VIEWS: &[(&str, &str)] = &[
    ("Collections", "boxsets"),
    ("Live TV", "livetv"),
    ("Playlists", "playlists"),
];

#[derive(Debug, Clone, PartialEq, Eq)]
struct LiveTvTunerView {
    tuner_id: String,
    name: String,
    provider_type: Option<String>,
    view_id: String,
    child_count: usize,
}

fn live_tv_tuner_view_id(tuner_id: &str) -> String {
    stable_entity_id("LiveTvTunerView", &tuner_id.trim().to_ascii_lowercase())
}

async fn configured_live_tv_tuner_views(db: &Database) -> Result<Vec<LiveTvTunerView>, ApiError> {
    let config = db
        .named_configuration("livetv")
        .await?
        .unwrap_or_else(default_live_tv_configuration);
    let mut seen = HashSet::new();
    let mut views = Vec::new();
    for tuner in config
        .get("TunerHosts")
        .and_then(serde_json::Value::as_array)
        .into_iter()
        .flatten()
    {
        if tuner.get("Enabled").and_then(serde_json::Value::as_bool) == Some(false) {
            continue;
        }
        let Some(tuner_id) = json_string_field(tuner, "Id")
            .map(|id| id.trim().to_string())
            .filter(|id| !id.is_empty())
        else {
            continue;
        };
        if !seen.insert(tuner_id.to_ascii_lowercase()) {
            continue;
        }
        let name = json_string_field(tuner, "FriendlyName")
            .or_else(|| json_string_field(tuner, "Name"))
            .filter(|name| !name.trim().is_empty())
            .unwrap_or_else(|| tuner_id.clone());
        let provider_type = json_string_field(tuner, "Type");
        let persisted_count = db
            .live_tv_channel_count(&LiveTvChannelQuery {
                tuner_ids: vec![tuner_id.clone()],
                ..LiveTvChannelQuery::default()
            })
            .await?;
        let configured_count = tuner
            .get("Channels")
            .and_then(serde_json::Value::as_array)
            .map_or(0, Vec::len);
        views.push(LiveTvTunerView {
            view_id: live_tv_tuner_view_id(&tuner_id),
            tuner_id,
            name,
            provider_type,
            child_count: persisted_count.max(configured_count),
        });
    }
    views.sort_by(|left, right| {
        left.name
            .to_ascii_lowercase()
            .cmp(&right.name.to_ascii_lowercase())
            .then_with(|| left.tuner_id.cmp(&right.tuner_id))
    });
    Ok(views)
}

async fn live_tv_tuner_view_by_id(
    db: &Database,
    view_id: &str,
) -> Result<Option<LiveTvTunerView>, ApiError> {
    Ok(configured_live_tv_tuner_views(db)
        .await?
        .into_iter()
        .find(|view| view.view_id.eq_ignore_ascii_case(view_id.trim())))
}

fn live_tv_tuner_view_to_json(tuner: &LiveTvTunerView, server_id: &str) -> serde_json::Value {
    let mut view = special_user_view_to_json(&tuner.name, "livetv", server_id);
    view["Id"] = serde_json::json!(tuner.view_id);
    // Generated Jellyfin Web clients discard the non-schema `url` extension before routing and
    // hard-code every `CollectionType=livetv` view to the global Live TV page. Advertise a
    // per-tuner view as an ordinary collection folder so every client takes the standard list
    // route and preserves this view id as ParentId. The global Live TV view keeps its canonical
    // collection type and behaviour.
    view.as_object_mut()
        .expect("special user view must be an object")
        .remove("CollectionType");
    view["url"] = serde_json::json!(format!(
        "#/list?serverId={server_id}&parentId={}",
        tuner.view_id
    ));
    view["ChildCount"] = serde_json::json!(tuner.child_count);
    view["RecursiveItemCount"] = serde_json::json!(tuner.child_count);
    view["TunerHostId"] = serde_json::json!(tuner.tuner_id);
    view["UserData"]["Key"] = serde_json::json!(tuner.view_id);
    view["UserData"]["ItemId"] = serde_json::json!(tuner.view_id);
    view
}

fn special_user_views(server_id: &str) -> Vec<serde_json::Value> {
    SPECIAL_USER_VIEWS
        .iter()
        .map(|(name, collection_type)| special_user_view_to_json(name, collection_type, server_id))
        .collect()
}

fn special_user_view_by_id(item_id: &str, server_id: &str) -> Option<serde_json::Value> {
    SPECIAL_USER_VIEWS
        .iter()
        .find_map(|(name, collection_type)| {
            special_user_view_id(collection_type)
                .eq_ignore_ascii_case(item_id)
                .then(|| special_user_view_to_json(name, collection_type, server_id))
        })
}

fn special_user_view_to_json(
    name: &str,
    collection_type: &str,
    server_id: &str,
) -> serde_json::Value {
    let id = special_user_view_id(collection_type);
    serde_json::json!({
        "Name": name,
        "ServerId": server_id,
        "Id": id,
        "Etag": null,
        "DateCreated": null,
        "CanDelete": false,
        "CanDownload": false,
        "SortName": name,
        "ExternalUrls": [],
        "Path": null,
        "EnableMediaSourceDisplay": true,
        "ChannelId": null,
        "Taglines": [],
        "Genres": [],
        "PlayAccess": "Full",
        "RemoteTrailers": [],
        "ProviderIds": {},
        "IsFolder": true,
        "ParentId": null,
        "Type": "CollectionFolder",
        "CollectionType": collection_type,
        "UserData": { "PlaybackPositionTicks": 0, "PlayCount": 0, "IsFavorite": false, "Played": false, "Key": id, "ItemId": id },
        "ImageTags": { "Primary": generated_folder_primary_image_tag(&id) },
        "PrimaryImageAspectRatio": 1.0,
        "BackdropImageTags": [],
        "LocationType": "Virtual",
        "MediaType": null,
    })
}

fn special_user_view_id(collection_type: &str) -> String {
    stable_entity_id("UserView", collection_type)
}

fn special_user_view_collection_type_for_parent(parent_id: Option<&str>) -> Option<&'static str> {
    let parent_id = parent_id?;
    SPECIAL_USER_VIEWS.iter().find_map(|(_, collection_type)| {
        (special_user_view_id(collection_type).eq_ignore_ascii_case(parent_id))
            .then_some(*collection_type)
    })
}

