fn parse_items_query(raw_query: Option<&str>) -> ItemsQuery {
    let mut query = ItemsQuery::default();
    let Some(raw_query) = raw_query else {
        return query;
    };

    for part in raw_query.split('&').filter(|part| !part.is_empty()) {
        let (key, value) = part.split_once('=').unwrap_or((part, ""));
        let key = percent_decode_query_component(key).to_ascii_lowercase();
        let value = percent_decode_query_component(value);
        match key.as_str() {
            "userid" => query.user_id = Some(value),
            "ids" => set_query_scalar(&mut query.ids, value),
            "parentid" => query.parent_id = Some(value),
            "seasonid" => query.season_id = Some(value),
            "seriesid" => query.series_id = Some(value),
            "includeitemtypes" => query.include_item_types.push(value),
            "excludeitemtypes" => query.exclude_item_types.push(value),
            "mediatypes" => query.media_types.push(value),
            "containers" => query.containers.push(value),
            "container" => query.containers.push(value),
            "videotypes" => query.video_types.push(value),
            "videotype" => query.video_types.push(value),
            "audiolanguages" => query.audio_languages.push(value),
            "audiolanguage" => query.audio_languages.push(value),
            "subtitlelanguages" => query.subtitle_languages.push(value),
            "subtitlelanguage" => query.subtitle_languages.push(value),
            "personids" => query.person_ids.push(value),
            "personid" => query.person_ids.push(value),
            "persons" => query.person_ids.push(value),
            "person" => query.person_ids.push(value),
            "genreids" => query.genre_ids.push(value),
            "genreid" => query.genre_ids.push(value),
            "genres" => query.genre_ids.push(value),
            "genre" => query.genre_ids.push(value),
            "studioids" => query.studio_ids.push(value),
            "studioid" => query.studio_ids.push(value),
            "studios" => query.studio_ids.push(value),
            "studio" => query.studio_ids.push(value),
            "officialratings" => query.official_ratings.push(value),
            "officialrating" => query.official_ratings.push(value),
            "tags" => query.tags.push(value),
            "tag" => query.tags.push(value),
            "seriesstatus" => query.series_status.push(value),
            "seriesstatuses" => query.series_status.push(value),
            "years" => query.years.push(value),
            "year" => query.years.push(value),
            "productionyear" => query.years.push(value),
            "searchterm" => query.search_term = Some(value),
            "isplayed" => query.is_played = parse_query_bool(&value),
            "isfavorite" => query.is_favorite = parse_query_bool(&value),
            "isairing" => query.is_airing = parse_query_bool(&value),
            "isfolder" => query.is_folder = parse_query_bool(&value),
            "hassubtitles" => query.has_subtitles = parse_query_bool(&value),
            "hastrailer" => query.has_trailer = parse_query_bool(&value),
            "hasoverview" => query.has_overview = parse_query_bool(&value),
            "hasimdbid" => query.has_imdb_id = parse_query_bool(&value),
            "hastmdbid" => query.has_tmdb_id = parse_query_bool(&value),
            "hastvdbid" => query.has_tvdb_id = parse_query_bool(&value),
            "ishd" => query.is_hd = parse_query_bool(&value),
            "is4k" => query.is_4k = parse_query_bool(&value),
            "minwidth" => query.min_width = value.parse().ok(),
            "maxwidth" => query.max_width = value.parse().ok(),
            "minheight" => query.min_height = value.parse().ok(),
            "maxheight" => query.max_height = value.parse().ok(),
            "ismissing" => query.is_missing = parse_query_bool(&value),
            "isunaired" => query.is_unaired = parse_query_bool(&value),
            "hasofficialrating" => query.has_official_rating = parse_query_bool(&value),
            "islocked" => query.is_locked = parse_query_bool(&value),
            "mincommunityrating" => query.min_community_rating = value.parse().ok(),
            "maxcommunityrating" => query.max_community_rating = value.parse().ok(),
            "mincriticrating" => query.min_critic_rating = value.parse().ok(),
            "maxcriticrating" => query.max_critic_rating = value.parse().ok(),
            "minpremieredate" => query.min_premiere_date = Some(value),
            "maxpremieredate" => query.max_premiere_date = Some(value),
            "mindatecreated" => query.min_date_created = Some(value),
            "maxdatecreated" => query.max_date_created = Some(value),
            "mindatelastsaved" => query.min_date_last_saved = Some(value),
            "maxdatelastsaved" => query.max_date_last_saved = Some(value),
            "filters" => query.filters.push(value),
            "namestartswith" => query.name_starts_with = Some(value),
            "namestartswithorgreater" => query.name_starts_with_or_greater = Some(value),
            "namelessthan" => query.name_less_than = Some(value),
            "recursive" => query.recursive = parse_query_bool(&value),
            "startindex" => query.start_index = value.parse().ok(),
            "limit" => query.limit = value.parse().ok(),
            "sortby" => set_query_scalar(&mut query.sort_by, value),
            "sortorder" => set_query_scalar(&mut query.sort_order, value),
            "fields" => set_query_scalar(&mut query.fields, value),
            "enableimages" => query._enable_images = Some(value),
            "enableuserdata" => query._enable_user_data = Some(value),
            "enabletotalrecordcount" => query._enable_total_record_count = Some(value),
            "locationtypes" => query.location_types.push(value),
            "locationtype" => query.location_types.push(value),
            "excludelocationtypes" => query.exclude_location_types.push(value),
            "excludelocationtype" => query.exclude_location_types.push(value),
            _ => {}
        }
    }

    query
}

fn set_query_scalar(target: &mut Option<String>, value: String) {
    if let Some(existing) = target {
        existing.push(',');
        existing.push_str(&value);
    } else {
        *target = Some(value);
    }
}

fn parse_query_bool(value: &str) -> Option<bool> {
    match value.to_ascii_lowercase().as_str() {
        "true" => Some(true),
        "false" => Some(false),
        _ => None,
    }
}

fn query_flag(value: &Option<String>) -> Option<bool> {
    value.as_deref().and_then(parse_query_bool)
}

fn shape_catalog_item_for_query(
    mut item: serde_json::Value,
    query: &ItemsQuery,
) -> serde_json::Value {
    let Some(object) = item.as_object_mut() else {
        return item;
    };
    if query_flag(&query._enable_images) == Some(false) {
        for key in [
            "ImageTags",
            "ImageBlurHashes",
            "BackdropImageTags",
            "ParentBackdropImageTags",
            "PrimaryImageAspectRatio",
        ] {
            object.remove(key);
        }
    }
    if query_flag(&query._enable_user_data) == Some(false) {
        object.remove("UserData");
    }
    let Some(fields) = query.fields.as_deref() else {
        return item;
    };
    let requested = fields
        .split(',')
        .map(|field| field.trim().to_ascii_lowercase())
        .filter(|field| !field.is_empty())
        .collect::<HashSet<_>>();
    for key in [
        "Overview",
        "MediaSources",
        "MediaStreams",
        "Path",
        "People",
        "Studios",
        "Genres",
        "Tags",
        "Taglines",
        "ProviderIds",
        "DateCreated",
        "PremiereDate",
        "ProductionYear",
        "OfficialRating",
        "CommunityRating",
        "CriticRating",
        "PrimaryImageAspectRatio",
    ] {
        if !requested.contains(&key.to_ascii_lowercase()) {
            object.remove(key);
        }
    }
    item
}

fn percent_decode_query_component(value: &str) -> String {
    let bytes = value.as_bytes();
    let mut output = Vec::with_capacity(bytes.len());
    let mut index = 0;
    while index < bytes.len() {
        match bytes[index] {
            b'+' => {
                output.push(b' ');
                index += 1;
            }
            b'%' if index + 2 < bytes.len() => {
                if let (Some(high), Some(low)) =
                    (hex_value(bytes[index + 1]), hex_value(bytes[index + 2]))
                {
                    output.push((high << 4) | low);
                    index += 3;
                } else {
                    output.push(bytes[index]);
                    index += 1;
                }
            }
            byte => {
                output.push(byte);
                index += 1;
            }
        }
    }
    String::from_utf8_lossy(&output).into_owned()
}

fn hex_value(byte: u8) -> Option<u8> {
    match byte {
        b'0'..=b'9' => Some(byte - b'0'),
        b'a'..=b'f' => Some(byte - b'a' + 10),
        b'A'..=b'F' => Some(byte - b'A' + 10),
        _ => None,
    }
}

/// Normalize and bound metadata selectors before any path can choose the O(N) legacy fallback.
fn normalized_catalog_filter_values(
    values: &[String],
    field: &str,
) -> Result<Vec<String>, ApiError> {
    let mut selectors = csv_values_lowercase(values).unwrap_or_default();
    selectors.sort_unstable();
    selectors.dedup();
    if selectors.len() > MEDIA_ITEM_CATALOG_MAX_FACET_SELECTORS {
        return Err(ApiError::bad_request(format!(
            "{field} accepts at most {MEDIA_ITEM_CATALOG_MAX_FACET_SELECTORS} distinct values"
        )));
    }
    Ok(selectors)
}

fn normalized_genre_ids_for_catalog(query: &ItemsQuery) -> Result<Vec<String>, ApiError> {
    normalized_catalog_filter_values(&query.genre_ids, "GenreIds")
}

/// Build the dialect-neutral database query for the bounded `/Items` hot path.
///
/// The fallback is intentional: unresolved parent/virtual hierarchies and metadata-only filters
/// still have application-level semantics that the catalog repository does not model. Keeping
/// the gate narrow prevents a performance optimization from changing those results.
fn media_catalog_query_for_items(
    query: &ItemsQuery,
    user_id: Option<Uuid>,
) -> Result<Option<MediaItemCatalogQuery>, ApiError> {
    let genre_ids = normalized_genre_ids_for_catalog(query)?;
    let person_ids = normalized_catalog_filter_values(&query.person_ids, "PersonIds")?;
    let studio_ids = normalized_catalog_filter_values(&query.studio_ids, "StudioIds")?;
    let tags = normalized_catalog_filter_values(&query.tags, "Tags")?;
    let Some(limit) = query.limit else {
        // The repository is deliberately bounded. Preserve the legacy unbounded response until
        // clients have supplied an explicit page size.
        return Ok(None);
    };
    if query.parent_id.is_some()
        || query.season_id.is_some()
        || query.series_id.is_some()
        || query
            .start_index
            .is_some_and(|index| i64::try_from(index).is_err())
        || query.is_airing.is_some()
    {
        return Ok(None);
    }
    let include_item_types = csv_values_lowercase(&query.include_item_types).unwrap_or_default();
    if include_item_types.iter().any(|item_type| {
        matches!(item_type.as_str(), "tvchannel" | "livetvchannel")
            || (item_type == "series" && query.allowed_plugin_tuner_ids.is_none())
    }) {
        return Ok(None);
    }
    if !person_ids.is_empty()
        && !include_item_types.is_empty()
        && include_item_types
            .iter()
            .all(|item_type| item_type == "episode")
    {
        // The legacy PersonIds episode shape overrides ordinary sorting with series/season/index.
        return Ok(None);
    }

    let filters = csv_values_lowercase(&query.filters).unwrap_or_default();
    if filters.iter().any(|filter| {
        !matches!(
            filter.as_str(),
            "isfolder"
                | "isnotfolder"
                | "isplayed"
                | "isunplayed"
                | "isfavorite"
                | "isfavoriteorlikes"
                | "likes"
                | "isresumable"
                | "hassubtitles"
                | "hastrailer"
        )
    }) {
        return Ok(None);
    }

    let sort_directions = query
        .sort_order
        .as_deref()
        .unwrap_or_default()
        .split(',')
        .map(|order| {
            if order.trim().eq_ignore_ascii_case("Descending") {
                SortDirection::Descending
            } else {
                SortDirection::Ascending
            }
        })
        .collect::<Vec<_>>();
    let default_sort_direction = sort_directions
        .first()
        .copied()
        .unwrap_or(SortDirection::Ascending);
    let sort = query
        .sort_by
        .as_deref()
        .unwrap_or("SortName")
        .split(',')
        .filter_map(|field| match field.trim().to_ascii_lowercase().as_str() {
            "sortname" | "name" => Some(MediaItemCatalogSortField::SortName),
            "datecreated" => Some(MediaItemCatalogSortField::DateCreated),
            "datelastmediaadded" => Some(MediaItemCatalogSortField::DateLastMediaAdded),
            "premieredate" => Some(MediaItemCatalogSortField::PremiereDate),
            "communityrating" => Some(MediaItemCatalogSortField::CommunityRating),
            "dateplayed" => Some(MediaItemCatalogSortField::DatePlayed),
            _ => None,
        })
        .collect::<Vec<_>>();
    let sort = if sort.is_empty() {
        vec![MediaItemCatalogSortField::SortName]
    } else {
        sort
    };
    if sort.len() > 3 {
        return Ok(None);
    }

    let ids = query.ids.as_deref().map(parse_uuid_list).transpose()?;
    let is_folder = query.is_folder.or_else(|| folder_filter_value(&filters));
    let is_played = query.is_played.or_else(|| played_filter_value(&filters));
    let favorite = match query.is_favorite {
        Some(value) => Some(MediaItemFavoriteFilter::Favorite(value)),
        None => favorite_filter_value(&filters).map(|mode| match mode {
            FavoriteFilterMode::FavoriteOnly => MediaItemFavoriteFilter::Favorite(true),
            FavoriteFilterMode::FavoriteOrLikes => MediaItemFavoriteFilter::FavoriteOrLiked,
        }),
    };
    let has_subtitles = query.has_subtitles.or_else(|| {
        filters
            .iter()
            .any(|filter| filter == "hassubtitles")
            .then_some(true)
    });
    let has_trailer = query.has_trailer.or_else(|| {
        filters
            .iter()
            .any(|filter| filter == "hastrailer")
            .then_some(true)
    });

    Ok(Some(MediaItemCatalogQuery {
        start_index: query.start_index.unwrap_or(0),
        limit: limit.min(MEDIA_ITEM_CATALOG_MAX_PAGE_SIZE),
        include_total_record_count: query_flag(&query._enable_total_record_count).unwrap_or(true),
        ids: ids.unwrap_or_default(),
        allowed_plugin_tuner_ids: query.allowed_plugin_tuner_ids.clone(),
        include_item_types: query.include_item_types.clone(),
        exclude_item_types: query.exclude_item_types.clone(),
        media_types: query.media_types.clone(),
        containers: query.containers.clone(),
        video_types: query.video_types.clone(),
        audio_languages: query.audio_languages.clone(),
        subtitle_languages: query.subtitle_languages.clone(),
        genre_ids,
        person_ids,
        studio_ids,
        tags,
        official_ratings: query.official_ratings.clone(),
        series_statuses: query.series_status.clone(),
        years: query.years.clone(),
        location_types: query.location_types.clone(),
        exclude_location_types: query.exclude_location_types.clone(),
        search_term: query.search_term.clone(),
        search_scope: MediaItemCatalogSearchScope::Name,
        has_subtitles,
        has_trailer,
        has_overview: query.has_overview,
        has_imdb_id: query.has_imdb_id,
        has_tmdb_id: query.has_tmdb_id,
        has_tvdb_id: query.has_tvdb_id,
        has_official_rating: query.has_official_rating,
        is_locked: query.is_locked,
        is_hd: query.is_hd,
        is_4k: query.is_4k,
        min_width: query.min_width,
        max_width: query.max_width,
        min_height: query.min_height,
        max_height: query.max_height,
        min_community_rating: query.min_community_rating,
        max_community_rating: query.max_community_rating,
        min_critic_rating: query.min_critic_rating,
        max_critic_rating: query.max_critic_rating,
        min_premiere_date: query
            .min_premiere_date
            .as_deref()
            .and_then(parse_item_query_date),
        max_premiere_date: query
            .max_premiere_date
            .as_deref()
            .and_then(parse_item_query_date),
        is_missing: query.is_missing,
        is_unaired: query.is_unaired,
        is_folder,
        min_date_created: query
            .min_date_created
            .as_deref()
            .and_then(parse_item_query_date),
        max_date_created: query
            .max_date_created
            .as_deref()
            .and_then(parse_item_query_date),
        min_date_last_saved: query
            .min_date_last_saved
            .as_deref()
            .and_then(parse_item_query_date),
        max_date_last_saved: query
            .max_date_last_saved
            .as_deref()
            .and_then(parse_item_query_date),
        name_starts_with: query.name_starts_with.clone(),
        name_starts_with_or_greater: query.name_starts_with_or_greater.clone(),
        name_less_than: query.name_less_than.clone(),
        user_id,
        is_played,
        favorite,
        is_resumable: resumable_filter_value(&filters),
        sort: sort
            .into_iter()
            .enumerate()
            .map(|(index, field)| {
                (
                    field,
                    sort_directions
                        .get(index)
                        .copied()
                        .unwrap_or(default_sort_direction),
                )
            })
            .collect(),
        ..MediaItemCatalogQuery::default()
    }))
}

/// Resolve a real virtual-folder parent before enabling SQL catalogue paging.
///
/// Other UUID-shaped parents can represent application-level Series/Season nodes, so they must
/// stay on the legacy path. Likewise, malformed parents are left to that path so it preserves its
/// existing validation error instead of silently returning an empty catalogue page.
async fn resolved_media_catalog_query_for_items(
    db: &Database,
    query: &ItemsQuery,
    user_id: Option<Uuid>,
) -> Result<Option<MediaItemCatalogQuery>, ApiError> {
    let genre_ids = normalized_genre_ids_for_catalog(query)?;
    let person_ids = normalized_catalog_filter_values(&query.person_ids, "PersonIds")?;
    let studio_ids = normalized_catalog_filter_values(&query.studio_ids, "StudioIds")?;
    let tags = normalized_catalog_filter_values(&query.tags, "Tags")?;
    let Some(parent_id) = query.parent_id.as_deref() else {
        return media_catalog_query_for_items(query, user_id);
    };

    // The legacy GenreIds path expands a real virtual-folder parent to all descendants even when
    // Recursive is absent/false. The existing SQL parent scope intentionally does not. Keep that
    // historical combination on the legacy matcher until parent traversal itself is unified.
    if (!genre_ids.is_empty()
        || !person_ids.is_empty()
        || !studio_ids.is_empty()
        || !tags.is_empty())
        && query.recursive != Some(true)
    {
        return Ok(None);
    }

    // The legacy response can synthesize physical/Series/Season folder nodes for this shape; the
    // media-item repository intentionally returns only persisted catalogue rows.
    if should_include_parent_virtual_items(query) {
        return Ok(None);
    }

    let Ok(parent_id) = parse_jellyfin_uuid(parent_id) else {
        return Ok(None);
    };
    let folders = db.virtual_folders().await?;
    let Some(parent) = folders.iter().find(|folder| folder.id == parent_id) else {
        return Ok(None);
    };

    // A plugin VOD library persists first-class Series anchors, while a physical TV library still
    // needs the legacy episode-to-Series projection. An unfiltered plugin does not populate
    // `allowed_plugin_tuner_ids`; use a temporary marker to pass the mapper's Series gate, then
    // restore the original no-filter visibility before executing SQL.
    let persisted_plugin_series = query.allowed_plugin_tuner_ids.is_none()
        && query_requests_only_item_type(query, "Series")
        && parent
            .locations
            .iter()
            .any(|location| location.trim().starts_with("plugin-vod://"));

    // First establish that every non-parent predicate is supported. This avoids enabling SQL for
    // UUID-shaped Series/Season parents and keeps unsupported request shapes on the legacy path.
    let mut scoped_query = query.clone();
    scoped_query.parent_id = None;
    if persisted_plugin_series {
        scoped_query.allowed_plugin_tuner_ids = Some(Vec::new());
    }
    let Some(mut db_query) = media_catalog_query_for_items(&scoped_query, user_id)? else {
        return Ok(None);
    };
    if persisted_plugin_series {
        db_query.allowed_plugin_tuner_ids = None;
    }

    db_query.virtual_folder_ids.push(parent.id);
    if query.recursive.unwrap_or(false) {
        db_query.virtual_folder_ids.extend(
            child_virtual_folders(parent, &folders)
                .into_iter()
                .map(|folder| folder.id),
        );
    }
    Ok(Some(db_query))
}

async fn media_catalog_items_result(
    db: &Database,
    query: &ItemsQuery,
    server_id: &str,
    user_id: Option<Uuid>,
) -> Result<Option<Json<serde_json::Value>>, ApiError> {
    let Some(db_query) = resolved_media_catalog_query_for_items(db, query, user_id).await? else {
        return Ok(None);
    };
    let page = MediaCatalogStore::media_item_catalog_page(db, &db_query).await?;
    let compact = should_use_compact_items_result(query);
    let items = page
        .items
        .iter()
        .map(|entry| {
            let item = if compact {
                compact_media_item_to_json(&entry.item, server_id, entry.playback_state.as_ref())
            } else {
                media_item_to_json_with_playback_and_metadata(
                    &entry.item,
                    server_id,
                    entry.playback_state.as_ref(),
                    Some(&entry.metadata),
                )
            };
            shape_catalog_item_for_query(item, query)
        })
        .collect();
    Ok(Some(Json(query_result_with_total(
        items,
        page.total_record_count,
        page.start_index,
    ))))
}

/// Resolve a plain `Ids=` lookup without materializing the complete media catalogue.
///
/// Jellyfin clients use this shape to hydrate the people attached to a detail page. Those people
/// are metadata facets rather than rows in `media_items`, so the ordinary SQL catalogue page is
/// not sufficient by itself. Keep the gate deliberately narrow, fetch real media rows in one
/// bounded query, and resolve only the missing stable metadata entity ids.
async fn exact_id_items_result(
    db: &Database,
    query: &ItemsQuery,
    server_id: &str,
    user_id: Option<Uuid>,
) -> Result<Option<Json<serde_json::Value>>, ApiError> {
    let Some(raw_ids) = query.ids.as_deref() else {
        return Ok(None);
    };

    let mut unsupported = query.clone();
    unsupported.user_id = None;
    unsupported.ids = None;
    unsupported.fields = None;
    unsupported._image_type_limit = None;
    unsupported._enable_images = None;
    unsupported._enable_user_data = None;
    unsupported._collapse_box_set_items = None;
    unsupported._image_types = None;
    unsupported._enable_image_types = None;
    unsupported._enable_total_record_count = None;
    unsupported.allowed_plugin_tuner_ids = None;
    if unsupported != ItemsQuery::default() {
        return Ok(None);
    }

    let ids = parse_uuid_list(raw_ids)?;
    if ids.is_empty() {
        return Ok(None);
    }
    if ids.len() > MEDIA_ITEM_CATALOG_MAX_PAGE_SIZE {
        return Err(ApiError::bad_request(format!(
            "Ids accepts at most {MEDIA_ITEM_CATALOG_MAX_PAGE_SIZE} values"
        )));
    }

    let media_items =
        filtered_media_items(db.media_items_by_ids(&ids).await?, query, user_id, db).await?;
    let media_values = items_to_json(db, media_items, server_id, user_id, false).await?;
    let mut values_by_id = media_values
        .into_iter()
        .filter_map(|value| {
            let id = value.get("Id")?.as_str()?.to_ascii_lowercase();
            Some((id, value))
        })
        .collect::<HashMap<_, _>>();

    let mut items = Vec::with_capacity(ids.len());
    for id in ids {
        let normalized_id = id.simple().to_string();
        let value = if let Some(value) = values_by_id.remove(&normalized_id) {
            value
        } else if let Some(entity) = recent_metadata_entity(&normalized_id) {
            metadata_entity_match_json(server_id, &entity)
        } else if let Some(entity) = metadata_entity_by_stable_id(db, &normalized_id).await? {
            metadata_entity_match_json(server_id, &entity)
        } else {
            // Series, seasons, channels and other synthetic ids retain their existing handlers.
            return Ok(None);
        };
        items.push(shape_catalog_item_for_query(value, query));
    }

    let total = if query_flag(&query._enable_total_record_count).unwrap_or(true) {
        items.len()
    } else {
        0
    };
    Ok(Some(Json(query_result_with_total(items, total, 0))))
}

/// Serve Jellyfin Web/Android's library search without loading every episode into memory.
///
/// The clients request synthetic `Series` and persisted `Episode` items together. A homogeneous
/// catalog page cannot represent that union, while the legacy fallback materializes the complete
/// TV library and its metadata. Query both bounded projections and merge only their result pages.
async fn mixed_series_episode_search_items_result(
    db: &Database,
    query: &ItemsQuery,
    server_id: &str,
    user_id: Option<Uuid>,
) -> Result<Option<Json<serde_json::Value>>, ApiError> {
    if query.allowed_plugin_tuner_ids.is_some() {
        return Ok(None);
    }
    let Some(search_term) = query
        .search_term
        .as_deref()
        .map(str::trim)
        .filter(|term| !term.is_empty())
    else {
        return Ok(None);
    };
    let mut include_types = csv_values_lowercase(&query.include_item_types).unwrap_or_default();
    include_types.sort_unstable();
    include_types.dedup();
    if include_types != ["episode", "series"] {
        return Ok(None);
    }

    // Normalize the harmless flags emitted by Jellyfin Web before reusing the deliberately narrow
    // simple-search contract. This keeps unsupported filters on the existing compatibility path.
    let mut supported_query = query.clone();
    supported_query.parent_id = None;
    supported_query.include_item_types = vec!["Episode".to_string()];
    if supported_query.is_missing == Some(false) {
        supported_query.is_missing = None;
    }
    if !fast_name_search_query_is_simple(&supported_query) {
        return Ok(None);
    }

    let start_index = query.start_index.unwrap_or(0);
    let limit = query
        .limit
        .unwrap_or(25)
        .min(MEDIA_ITEM_CATALOG_MAX_PAGE_SIZE);
    let fetch_limit = start_index
        .saturating_add(limit)
        .min(MEDIA_ITEM_CATALOG_MAX_PAGE_SIZE);

    let mut series_query = query.clone();
    series_query.include_item_types = vec!["Series".to_string()];
    series_query.search_term = Some(search_term.to_string());
    series_query.start_index = Some(0);
    series_query.limit = Some(fetch_limit);
    if series_query.is_missing == Some(false) {
        series_query.is_missing = None;
    }
    let series = tv_series_items_result(db, &series_query, user_id, server_id).await?;

    let mut episode_query = query.clone();
    episode_query.include_item_types = vec!["Episode".to_string()];
    episode_query.search_term = Some(search_term.to_string());
    episode_query.start_index = Some(0);
    episode_query.limit = Some(fetch_limit);
    let episodes = media_catalog_items_result(db, &episode_query, server_id, user_id)
        .await?
        .ok_or_else(|| ApiError::internal("bounded episode search unexpectedly unavailable"))?;

    let series_total = series
        .0
        .get("TotalRecordCount")
        .and_then(serde_json::Value::as_u64)
        .and_then(|value| usize::try_from(value).ok())
        .unwrap_or(0);
    let episode_total = episodes
        .0
        .get("TotalRecordCount")
        .and_then(serde_json::Value::as_u64)
        .and_then(|value| usize::try_from(value).ok())
        .unwrap_or(0);
    let mut items = series
        .0
        .get("Items")
        .and_then(serde_json::Value::as_array)
        .cloned()
        .unwrap_or_default();
    items.extend(
        episodes
            .0
            .get("Items")
            .and_then(serde_json::Value::as_array)
            .cloned()
            .unwrap_or_default(),
    );
    sort_json_items(&mut items, query);

    Ok(Some(Json(query_result_with_total(
        items.into_iter().skip(start_index).take(limit).collect(),
        series_total.saturating_add(episode_total),
        start_index,
    ))))
}

/// Serve Android TV's mixed random backdrop request without materializing the complete catalog.
///
/// Jellyfin Android TV asks for `Movie,Series` together. Movies are stored directly while Series
/// are projected from episodes, so the ordinary homogeneous catalog page cannot answer that shape.
/// Sample a bounded window from each projection and shuffle only that small result instead.
async fn random_movie_series_items_result(
    db: &Database,
    query: &ItemsQuery,
    server_id: &str,
    user_id: Option<Uuid>,
) -> Result<Option<Json<serde_json::Value>>, ApiError> {
    if query.allowed_plugin_tuner_ids.is_some() {
        return Ok(None);
    }
    let Some(limit) = query.limit.filter(|limit| *limit > 0) else {
        return Ok(None);
    };
    if query.start_index.unwrap_or(0) != 0
        || query.parent_id.is_some()
        || query.ids.is_some()
        || query.season_id.is_some()
        || query.series_id.is_some()
        || !query.exclude_item_types.is_empty()
        || query
            .sort_by
            .as_deref()
            .is_none_or(|sort| !sort.eq_ignore_ascii_case("Random"))
    {
        return Ok(None);
    }
    let mut include_types = csv_values_lowercase(&query.include_item_types).unwrap_or_default();
    include_types.sort_unstable();
    include_types.dedup();
    if include_types != ["movie", "series"] {
        return Ok(None);
    }

    let limit = limit.min(MEDIA_ITEM_CATALOG_MAX_PAGE_SIZE);
    let mut movie_query = query.clone();
    movie_query.include_item_types = vec!["Movie".to_string()];
    movie_query.start_index = Some(0);
    movie_query.limit = Some(0);
    movie_query.sort_by = Some("SortName".to_string());
    movie_query.sort_order = None;
    let Some(movie_count_result) =
        media_catalog_items_result(db, &movie_query, server_id, user_id).await?
    else {
        return Ok(None);
    };
    let movie_total = movie_count_result
        .0
        .get("TotalRecordCount")
        .and_then(serde_json::Value::as_u64)
        .and_then(|count| usize::try_from(count).ok())
        .unwrap_or(0);

    let Some(series_count_page) = MediaCatalogStore::tv_series_catalog_page(db, None, 0, 0).await?
    else {
        return Ok(None);
    };
    let series_total = series_count_page.total_record_count;
    let combined_total = movie_total.saturating_add(series_total);
    if combined_total == 0 {
        return Ok(Some(Json(query_result_with_total(Vec::new(), 0, 0))));
    }

    let mut movie_limit = limit.saturating_mul(movie_total) / combined_total;
    let mut series_limit = limit.saturating_sub(movie_limit);
    movie_limit = movie_limit.min(movie_total);
    series_limit = series_limit.min(series_total);
    let remaining = limit.saturating_sub(movie_limit.saturating_add(series_limit));
    let movie_room = movie_total.saturating_sub(movie_limit);
    let movie_fill = remaining.min(movie_room);
    movie_limit += movie_fill;
    series_limit += remaining
        .saturating_sub(movie_fill)
        .min(series_total - series_limit);

    let mut random = OsRng;
    let random_offset = |total: usize, page_size: usize, random: &mut OsRng| {
        let positions = total.saturating_sub(page_size).saturating_add(1);
        if positions <= 1 {
            0
        } else {
            usize::try_from(random.next_u64() % positions as u64).unwrap_or(0)
        }
    };

    movie_query.start_index = Some(random_offset(movie_total, movie_limit, &mut random));
    movie_query.limit = Some(movie_limit);
    let Some(movie_result) =
        media_catalog_items_result(db, &movie_query, server_id, user_id).await?
    else {
        return Ok(None);
    };
    let mut items = movie_result
        .0
        .get("Items")
        .and_then(serde_json::Value::as_array)
        .cloned()
        .unwrap_or_default();

    if series_limit > 0 {
        let mut series_query = query.clone();
        series_query.include_item_types = vec!["Series".to_string()];
        series_query.start_index = Some(random_offset(series_total, series_limit, &mut random));
        series_query.limit = Some(series_limit);
        series_query.sort_by = None;
        series_query.sort_order = None;
        let series_result = tv_series_items_result(db, &series_query, user_id, server_id).await?;
        items.extend(
            series_result
                .0
                .get("Items")
                .and_then(serde_json::Value::as_array)
                .cloned()
                .unwrap_or_default(),
        );
    }

    // Fisher-Yates over at most 500 entries; no catalog-sized in-memory sort is involved.
    for index in (1..items.len()).rev() {
        let swap_with = usize::try_from(random.next_u64() % (index as u64 + 1)).unwrap_or(0);
        items.swap(index, swap_with);
    }
    Ok(Some(Json(query_result_with_total(
        items,
        combined_total,
        0,
    ))))
}

/// Resolve the direct `Series -> Season` `/Items` shape used by Wholphin without loading the
/// complete media catalogue. Jellyfin's own clients normally use `/Shows/{id}/Seasons`, while
/// Wholphin asks for the same projection through `/Items?ParentId=...&IncludeItemTypes=Season`.
fn direct_parent_seasons_series_id(query: &ItemsQuery) -> Option<&str> {
    let include_types = csv_values_lowercase(&query.include_item_types)?;
    if include_types != ["season"]
        || query.recursive == Some(true)
        || query.ids.is_some()
        || query.season_id.is_some()
        || query.series_id.is_some()
        || !query.exclude_item_types.is_empty()
        || !query.media_types.is_empty()
        || !query.containers.is_empty()
        || !query.video_types.is_empty()
        || !query.audio_languages.is_empty()
        || !query.subtitle_languages.is_empty()
        || !query.person_ids.is_empty()
        || !query.genre_ids.is_empty()
        || !query.studio_ids.is_empty()
        || !query.official_ratings.is_empty()
        || !query.tags.is_empty()
        || !query.series_status.is_empty()
        || !query.years.is_empty()
        || !query.filters.is_empty()
        || query.search_term.is_some()
        || query.is_played.is_some()
        || query.is_favorite.is_some()
        || query.is_airing.is_some()
        || query.is_folder.is_some()
        || query.has_subtitles.is_some()
        || query.has_trailer.is_some()
        || query.has_overview.is_some()
        || query.has_imdb_id.is_some()
        || query.has_tmdb_id.is_some()
        || query.has_tvdb_id.is_some()
        || query.is_hd.is_some()
        || query.is_4k.is_some()
        || query.min_width.is_some()
        || query.max_width.is_some()
        || query.min_height.is_some()
        || query.max_height.is_some()
        || query.is_missing.is_some()
        || query.is_unaired.is_some()
        || query.has_official_rating.is_some()
        || query.is_locked.is_some()
        || query.min_community_rating.is_some()
        || query.max_community_rating.is_some()
        || query.min_critic_rating.is_some()
        || query.max_critic_rating.is_some()
        || query.min_premiere_date.is_some()
        || query.max_premiere_date.is_some()
        || query.min_date_created.is_some()
        || query.max_date_created.is_some()
        || query.min_date_last_saved.is_some()
        || query.max_date_last_saved.is_some()
        || query.name_starts_with.is_some()
        || query.name_starts_with_or_greater.is_some()
        || query.name_less_than.is_some()
        || !query.location_types.is_empty()
        || !query.exclude_location_types.is_empty()
    {
        return None;
    }
    query.parent_id.as_deref()
}

async fn parent_series_seasons_items_result(
    db: &Database,
    query: &ItemsQuery,
    user_id: Uuid,
    server_id: &str,
) -> Result<Option<Json<serde_json::Value>>, ApiError> {
    let Some(series_id) = direct_parent_seasons_series_id(query) else {
        return Ok(None);
    };
    Ok(Some(
        series_seasons_result(db, query, series_id, user_id, server_id).await?,
    ))
}

/// Resolve the direct `Series -> Episode` `/Items` shape used by Android TV without loading the
/// complete media catalogue. A UUID-shaped `ParentId` can also be a real virtual folder, so leave
/// those parents to the indexed catalogue path below and only project application-level series.
async fn parent_series_episodes_items_result(
    db: &Database,
    query: &ItemsQuery,
    user_id: Uuid,
    server_id: &str,
) -> Result<Option<Json<serde_json::Value>>, ApiError> {
    let include_types = csv_values_lowercase(&query.include_item_types).unwrap_or_default();
    if include_types != ["episode"]
        || query.recursive == Some(true)
        || query.ids.is_some()
        || query.series_id.is_some()
        || query.season_id.is_some()
    {
        return Ok(None);
    }
    let Some(series_id) = query.parent_id.as_deref() else {
        return Ok(None);
    };
    let Ok(parent_id) = parse_jellyfin_uuid(series_id) else {
        return Ok(None);
    };
    if db
        .virtual_folders()
        .await?
        .iter()
        .any(|folder| folder.id == parent_id)
    {
        return Ok(None);
    }

    let mut episode_query = query.clone();
    episode_query.parent_id = None;

    // Jellyfin Android TV also uses this exact shape with a Season id as ParentId while loading
    // sibling episodes on the episode-detail screen. Resolve that indexed scope before treating
    // the parent as a Series; otherwise a valid season falls through to the legacy synthetic-id
    // scan of the entire TV catalogue and can exceed PostgreSQL's statement timeout.
    let season_snapshot = match tv_episode_catalog_snapshot_for_season(db, series_id).await? {
        some @ Some(_) => some,
        None => {
            let fallback = tv_episode_catalog_snapshot_without_canonical_series_id(db).await?;
            fallback
                .items
                .iter()
                .any(|item| {
                    tv_episode_matches_season(
                        item,
                        fallback.metadata_by_item.get(&item.id),
                        series_id,
                    )
                })
                .then_some(fallback)
        }
    };
    if let Some(season_snapshot) = season_snapshot {
        let canonical_season_id = parent_id.simple().to_string();
        let canonical_series_id = season_snapshot
            .items
            .iter()
            .filter(|item| {
                tv_episode_matches_season(
                    item,
                    season_snapshot.metadata_by_item.get(&item.id),
                    series_id,
                )
            })
            .find_map(|item| {
                let metadata = season_snapshot.metadata_by_item.get(&item.id);
                metadata
                    .and_then(|metadata| canonical_metadata_uuid_from_json(metadata, &["SeriesId"]))
                    .or_else(|| {
                        tv_episode_info(item).map(|info| tv_series_id_for_episode(&info, metadata))
                    })
            });
        if let Some(canonical_series_id) = canonical_series_id {
            episode_query.season_id = Some(canonical_season_id);
            return Ok(Some(
                series_episodes_result(
                    db,
                    &episode_query,
                    &canonical_series_id,
                    user_id,
                    server_id,
                )
                .await?,
            ));
        }
    }
    Ok(Some(
        series_episodes_result(db, &episode_query, series_id, user_id, server_id).await?,
    ))
}

async fn items_result(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    RawQuery(raw_query): RawQuery,
) -> Result<Json<serde_json::Value>, ApiError> {
    let mut query = parse_items_query(raw_query.as_deref());
    let (auth_user, token) =
        require_user(&state.db, &headers, auth_query.api_key.as_deref()).await?;
    let requested_user_id = query.user_id.as_deref().map(resolve_user_id).transpose()?;
    if let Some(requested_user_id) = requested_user_id {
        ensure_user_access(&auth_user, requested_user_id)?;
    }
    scope_items_query_for_plugin_catalogs(
        &state.db,
        &mut query,
        &auth_user,
        &token,
        requested_user_id,
    )
    .await?;
    let server_id = state.db.server_state().await?.server_id.to_string();
    if let Some(parent_id) = query.parent_id.as_deref()
        && let Some(tuner) = live_tv_tuner_view_by_id(&state.db, parent_id).await?
    {
        return live_tv_channel_items_result(&state.db, &query, &server_id, Some(&tuner.tuner_id))
            .await;
    }
    if let Some(collection_type) =
        special_user_view_collection_type_for_parent(query.parent_id.as_deref())
    {
        return special_user_view_items_result(
            &state.db,
            &query,
            &auth_user,
            requested_user_id,
            &server_id,
            collection_type,
        )
        .await;
    }
    if query_requests_only_item_type(&query, "LiveTvChannel")
        || query_requests_only_item_type(&query, "TvChannel")
    {
        return live_tv_channel_items_result(&state.db, &query, &server_id, None).await;
    }
    if let Some(result) =
        random_movie_series_items_result(&state.db, &query, &server_id, requested_user_id).await?
    {
        return Ok(result);
    }
    if let Some(result) =
        mixed_series_episode_search_items_result(&state.db, &query, &server_id, requested_user_id)
            .await?
    {
        queue_plugin_vod_artwork_prefetch_from_page(&state, &result.0);
        return Ok(result);
    }
    if let Some(result) =
        exact_id_items_result(&state.db, &query, &server_id, requested_user_id).await?
    {
        return Ok(result);
    }
    if let Some(result) = parent_series_seasons_items_result(
        &state.db,
        &query,
        requested_user_id.unwrap_or(auth_user.id),
        &server_id,
    )
    .await?
    {
        return Ok(result);
    }
    if let Some(result) = parent_series_episodes_items_result(
        &state.db,
        &query,
        requested_user_id.unwrap_or(auth_user.id),
        &server_id,
    )
    .await?
    {
        return Ok(result);
    }
    if let Some(result) = media_catalog_items_result(
        &state.db,
        &query,
        &server_id,
        requested_user_id.or(Some(auth_user.id)),
    )
    .await?
    {
        queue_plugin_vod_artwork_prefetch_from_page(&state, &result.0);
        return Ok(result);
    }
    if let Some(result) =
        fast_name_search_items_result(&state.db, &query, &server_id, requested_user_id).await?
    {
        queue_plugin_vod_artwork_prefetch_from_page(&state, &result.0);
        return Ok(result);
    }
    if query_requests_only_item_type(&query, "Series") && query.allowed_plugin_tuner_ids.is_none() {
        return tv_series_items_result(&state.db, &query, requested_user_id, &server_id).await;
    }
    let filtered_items = filtered_media_items(
        state.db.media_items().await?,
        &query,
        requested_user_id,
        &state.db,
    )
    .await?;
    if should_include_parent_virtual_items(&query) {
        let mut items = items_to_json(
            &state.db,
            filtered_items,
            &server_id,
            requested_user_id,
            should_use_compact_items_result(&query),
        )
        .await?;
        items.extend(
            parent_virtual_items(
                &state.db,
                &query,
                requested_user_id,
                &server_id,
                items.len(),
            )
            .await?,
        );
        sort_json_items(&mut items, &query);
        let total_record_count = items.len();
        let start_index = query.start_index.unwrap_or(0);
        let limit = query.limit.unwrap_or(usize::MAX);
        return Ok(Json(query_result_with_total(
            items.into_iter().skip(start_index).take(limit).collect(),
            total_record_count,
            start_index,
        )));
    }
    let total_record_count = filtered_items.len();
    let page = paged_media_items(filtered_items, &query);
    queue_plugin_vod_artwork_prefetch_ids(
        &state,
        &page.iter().map(|item| item.id).collect::<Vec<_>>(),
    );
    let items = items_to_json(
        &state.db,
        page,
        &server_id,
        requested_user_id,
        should_use_compact_items_result(&query),
    )
    .await?;
    Ok(Json(query_result_with_total(
        items,
        total_record_count,
        query.start_index.unwrap_or(0),
    )))
}

async fn user_items_result(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    Path(user_id): Path<String>,
    RawQuery(raw_query): RawQuery,
) -> Result<Json<serde_json::Value>, ApiError> {
    let mut query = parse_items_query(raw_query.as_deref());
    let (auth_user, token) =
        require_user(&state.db, &headers, auth_query.api_key.as_deref()).await?;
    let requested_user_id = resolve_user_id(&user_id)?;
    ensure_user_access(&auth_user, requested_user_id)?;
    scope_items_query_for_plugin_catalogs(
        &state.db,
        &mut query,
        &auth_user,
        &token,
        Some(requested_user_id),
    )
    .await?;
    let server_id = state.db.server_state().await?.server_id.to_string();
    if let Some(parent_id) = query.parent_id.as_deref()
        && let Some(tuner) = live_tv_tuner_view_by_id(&state.db, parent_id).await?
    {
        return live_tv_channel_items_result(&state.db, &query, &server_id, Some(&tuner.tuner_id))
            .await;
    }
    if let Some(collection_type) =
        special_user_view_collection_type_for_parent(query.parent_id.as_deref())
    {
        return special_user_view_items_result(
            &state.db,
            &query,
            &auth_user,
            Some(requested_user_id),
            &server_id,
            collection_type,
        )
        .await;
    }
    if query_requests_only_item_type(&query, "LiveTvChannel")
        || query_requests_only_item_type(&query, "TvChannel")
    {
        return live_tv_channel_items_result(&state.db, &query, &server_id, None).await;
    }
    // Keep the bounded projections in the same order as `/Items`. This route is the one Android TV
    // and Jellyfin Web actually call, so a projection that exists only on the unscoped sibling
    // leaves the user-scoped request on the legacy application-level scan.
    if let Some(result) =
        exact_id_items_result(&state.db, &query, &server_id, Some(requested_user_id)).await?
    {
        return Ok(result);
    }
    if let Some(result) =
        parent_series_seasons_items_result(&state.db, &query, requested_user_id, &server_id).await?
    {
        return Ok(result);
    }
    if let Some(result) =
        parent_series_episodes_items_result(&state.db, &query, requested_user_id, &server_id)
            .await?
    {
        return Ok(result);
    }
    if let Some(result) =
        media_catalog_items_result(&state.db, &query, &server_id, Some(requested_user_id)).await?
    {
        queue_plugin_vod_artwork_prefetch_from_page(&state, &result.0);
        return Ok(result);
    }
    if let Some(result) = mixed_series_episode_search_items_result(
        &state.db,
        &query,
        &server_id,
        Some(requested_user_id),
    )
    .await?
    {
        queue_plugin_vod_artwork_prefetch_from_page(&state, &result.0);
        return Ok(result);
    }
    if let Some(result) =
        fast_name_search_items_result(&state.db, &query, &server_id, Some(requested_user_id))
            .await?
    {
        queue_plugin_vod_artwork_prefetch_from_page(&state, &result.0);
        return Ok(result);
    }
    if query_requests_only_item_type(&query, "Series") && query.allowed_plugin_tuner_ids.is_none() {
        return tv_series_items_result(&state.db, &query, Some(requested_user_id), &server_id)
            .await;
    }
    let filtered_items = filtered_media_items(
        state.db.media_items().await?,
        &query,
        Some(requested_user_id),
        &state.db,
    )
    .await?;
    if should_include_parent_virtual_items(&query) {
        let mut items = items_to_json(
            &state.db,
            filtered_items,
            &server_id,
            Some(requested_user_id),
            should_use_compact_items_result(&query),
        )
        .await?;
        items.extend(
            parent_virtual_items(
                &state.db,
                &query,
                Some(requested_user_id),
                &server_id,
                items.len(),
            )
            .await?,
        );
        sort_json_items(&mut items, &query);
        let total_record_count = items.len();
        let start_index = query.start_index.unwrap_or(0);
        let limit = query.limit.unwrap_or(usize::MAX);
        return Ok(Json(query_result_with_total(
            items.into_iter().skip(start_index).take(limit).collect(),
            total_record_count,
            start_index,
        )));
    }
    let total_record_count = filtered_items.len();
    let page = paged_media_items(filtered_items, &query);
    queue_plugin_vod_artwork_prefetch_ids(
        &state,
        &page.iter().map(|item| item.id).collect::<Vec<_>>(),
    );
    let items = items_to_json(
        &state.db,
        page,
        &server_id,
        Some(requested_user_id),
        should_use_compact_items_result(&query),
    )
    .await?;
    Ok(Json(query_result_with_total(
        items,
        total_record_count,
        query.start_index.unwrap_or(0),
    )))
}

async fn special_user_view_items_result(
    db: &Database,
    query: &ItemsQuery,
    auth_user: &User,
    requested_user_id: Option<Uuid>,
    server_id: &str,
    collection_type: &str,
) -> Result<Json<serde_json::Value>, ApiError> {
    let mut items = match collection_type {
        "boxsets" => special_collection_items(db, server_id).await?,
        "playlists" => special_playlist_items(db, auth_user, server_id).await?,
        "livetv" => channel_provider_items(db).await?,
        _ => Vec::new(),
    };
    let include_types = csv_values_lowercase(&query.include_item_types);
    let search_term = query
        .search_term
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_ascii_lowercase);
    items.retain(|item| {
        include_types.as_ref().is_none_or(|types| {
            json_string_field(item, "Type")
                .map(|item_type| item_type.to_ascii_lowercase())
                .is_some_and(|item_type| types.iter().any(|allowed| allowed == &item_type))
        }) && search_term.as_ref().is_none_or(|term| {
            json_string_field(item, "Name")
                .unwrap_or_default()
                .to_ascii_lowercase()
                .contains(term)
        })
    });
    if let Some(is_favorite) = query.is_favorite {
        items.retain(|item| {
            item.get("UserData")
                .and_then(|value| json_bool_field(value, "IsFavorite"))
                .unwrap_or(false)
                == is_favorite
        });
    }
    if let Some(user_id) = requested_user_id
        && let Some(is_played) = query.is_played
    {
        let item_ids = items
            .iter()
            .filter_map(|item| json_string_field(item, "Id"))
            .filter_map(|id| parse_jellyfin_uuid(&id).ok())
            .collect::<Vec<_>>();
        let playback_by_item = MediaCatalogStore::playback_states_for_items(db, user_id, &item_ids)
            .await?
            .into_iter()
            .map(|state| (state.item_id, state))
            .collect::<HashMap<_, _>>();
        items.retain(|item| {
            let played = json_string_field(item, "Id")
                .and_then(|id| parse_jellyfin_uuid(&id).ok())
                .and_then(|id| playback_by_item.get(&id))
                .is_some_and(|state| state.played);
            played == is_played
        });
    }
    sort_json_items(&mut items, query);
    let total_record_count = items.len();
    let start_index = query.start_index.unwrap_or(0);
    let limit = query.limit.unwrap_or(usize::MAX);
    Ok(Json(query_result_with_total(
        items.into_iter().skip(start_index).take(limit).collect(),
        total_record_count,
        start_index,
    )))
}

async fn special_collection_items(
    db: &Database,
    server_id: &str,
) -> Result<Vec<serde_json::Value>, ApiError> {
    let lists = db.media_lists("collection").await?;
    let counts = db
        .media_list_item_counts(&lists.iter().map(|list| list.id).collect::<Vec<_>>())
        .await?;
    let mut values = Vec::with_capacity(lists.len());
    for list in lists {
        let child_count = counts.get(&list.id).copied().unwrap_or(0);
        values.push(media_list_to_json(&list, server_id, child_count));
    }
    Ok(values)
}

async fn live_tv_channel_items_result(
    db: &Database,
    query: &ItemsQuery,
    server_id: &str,
    tuner_id: Option<&str>,
) -> Result<Json<serde_json::Value>, ApiError> {
    let requested_limit = query.limit.unwrap_or(25);
    let limit = requested_limit.min(500);
    let tuner_ids = match (&query.allowed_plugin_tuner_ids, tuner_id) {
        (Some(allowed), Some(requested)) => {
            let matching = allowed
                .iter()
                .find(|allowed| allowed.eq_ignore_ascii_case(requested))
                .cloned();
            let Some(matching) = matching else {
                return Ok(Json(query_result_with_total(Vec::new(), 0, 0)));
            };
            vec![matching]
        }
        (Some(allowed), None) if allowed.is_empty() => {
            return Ok(Json(query_result_with_total(Vec::new(), 0, 0)));
        }
        (Some(allowed), None) => allowed.clone(),
        (None, Some(requested)) => vec![requested.to_string()],
        (None, None) => Vec::new(),
    };
    let db_query = LiveTvChannelQuery {
        start_index: query.start_index.unwrap_or(0),
        limit: Some(limit),
        search_term: query.search_term.clone(),
        tuner_ids,
        category_ids: Vec::new(),
    };
    let page = LiveTvService::new(db).channel_page(db_query).await?;
    if page.total_record_count > 0 {
        let items = page
            .items
            .iter()
            .map(|record| live_tv_channel_record_to_json(record, server_id))
            .collect::<Vec<_>>();
        return Ok(Json(query_result_with_total(
            items,
            page.total_record_count,
            page.start_index,
        )));
    }

    let mut items = configured_live_tv_channel_items(db).await?;
    if let Some(allowed) = query.allowed_plugin_tuner_ids.as_ref() {
        items.retain(|item| {
            json_string_field(item, "TunerHostId").is_some_and(|id| {
                allowed
                    .iter()
                    .any(|allowed| allowed.eq_ignore_ascii_case(&id))
            })
        });
    }
    if let Some(tuner_id) = tuner_id {
        items.retain(|item| {
            json_string_field(item, "TunerHostId")
                .is_some_and(|id| id.eq_ignore_ascii_case(tuner_id))
        });
    }
    filter_channel_items_by_search(&mut items, query.search_term.as_deref());
    let total_record_count = items.len();
    let start_index = query.start_index.unwrap_or(0).min(total_record_count);
    Ok(Json(query_result_with_total(
        items.into_iter().skip(start_index).take(limit).collect(),
        total_record_count,
        start_index,
    )))
}

async fn fast_name_search_items_result(
    db: &Database,
    query: &ItemsQuery,
    server_id: &str,
    user_id: Option<Uuid>,
) -> Result<Option<Json<serde_json::Value>>, ApiError> {
    if query.allowed_plugin_tuner_ids.is_some() {
        return Ok(None);
    }
    let Some(search_term) = query
        .search_term
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    else {
        return Ok(None);
    };
    if !fast_name_search_query_is_simple(query) {
        return Ok(None);
    }

    let collection_types = if query_requests_only_item_type(query, "Movie") {
        &["movies"][..]
    } else if query_requests_only_item_type(query, "Episode") {
        &["tvshows"][..]
    } else if query_requests_only_item_type(query, "Audio") {
        &["music"][..]
    } else if query_requests_only_item_type(query, "MusicAlbum")
        || query_requests_only_item_type(query, "MusicArtist")
        || query_requests_only_item_type(query, "Person")
        || query_requests_only_item_type(query, "BoxSet")
        || query_requests_only_item_type(query, "Playlist")
        || query_requests_only_item_type(query, "Photo")
        || query_requests_only_item_type(query, "PhotoAlbum")
    {
        let start_index = query.start_index.unwrap_or(0);
        return Ok(Some(Json(query_result_with_total(
            Vec::new(),
            0,
            start_index,
        ))));
    } else {
        return Ok(None);
    };

    let start_index = query.start_index.unwrap_or(0);
    let limit = query.limit.unwrap_or(25).min(500);
    let fetch_limit = start_index.saturating_add(limit);
    let items = db
        .media_items_by_name_search(search_term, collection_types, fetch_limit)
        .await?;
    let total_record_count = items.len();
    let items = items_to_json(
        db,
        items.into_iter().skip(start_index).take(limit).collect(),
        server_id,
        user_id,
        should_use_compact_items_result(query),
    )
    .await?;
    Ok(Some(Json(query_result_with_total(
        items,
        total_record_count,
        start_index,
    ))))
}

fn fast_name_search_query_is_simple(query: &ItemsQuery) -> bool {
    if query.parent_id.is_some()
        || query.ids.is_some()
        || query.season_id.is_some()
        || query.series_id.is_some()
        || !query.exclude_item_types.is_empty()
        || !query.media_types.is_empty()
        || !query.containers.is_empty()
        || !query.video_types.is_empty()
        || !query.audio_languages.is_empty()
        || !query.subtitle_languages.is_empty()
        || !query.person_ids.is_empty()
        || !query.genre_ids.is_empty()
        || !query.studio_ids.is_empty()
        || !query.official_ratings.is_empty()
        || !query.tags.is_empty()
        || !query.series_status.is_empty()
        || !query.years.is_empty()
        || !query.filters.is_empty()
        || query.is_played.is_some()
        || query.is_favorite.is_some()
        || query.is_airing.is_some()
        || query.is_folder.is_some()
        || query.has_subtitles.is_some()
        || query.has_trailer.is_some()
        || query.has_overview.is_some()
        || query.has_imdb_id.is_some()
        || query.has_tmdb_id.is_some()
        || query.has_tvdb_id.is_some()
        || query.is_hd.is_some()
        || query.is_4k.is_some()
        || query.min_width.is_some()
        || query.max_width.is_some()
        || query.min_height.is_some()
        || query.max_height.is_some()
        || query.is_missing.is_some()
        || query.is_unaired.is_some()
        || query.has_official_rating.is_some()
        || query.is_locked.is_some()
        || query.min_community_rating.is_some()
        || query.max_community_rating.is_some()
        || query.min_critic_rating.is_some()
        || query.max_critic_rating.is_some()
        || query.min_premiere_date.is_some()
        || query.max_premiere_date.is_some()
        || query.min_date_created.is_some()
        || query.max_date_created.is_some()
        || query.min_date_last_saved.is_some()
        || query.max_date_last_saved.is_some()
        || query.name_starts_with.is_some()
        || query.name_starts_with_or_greater.is_some()
        || query.name_less_than.is_some()
        || !query.location_types.is_empty()
        || !query.exclude_location_types.is_empty()
        || query
            .sort_order
            .as_deref()
            .is_some_and(|order| order.eq_ignore_ascii_case("Descending"))
    {
        return false;
    }
    query.sort_by.as_deref().is_none_or(|sort_by| {
        sort_by.split(',').all(|field| {
            matches!(
                field.trim().to_ascii_lowercase().as_str(),
                "" | "sortname" | "name"
            )
        })
    })
}

async fn special_playlist_items(
    db: &Database,
    auth_user: &User,
    server_id: &str,
) -> Result<Vec<serde_json::Value>, ApiError> {
    let lists = db.media_lists("playlist").await?;
    let counts = db
        .media_list_item_counts(&lists.iter().map(|list| list.id).collect::<Vec<_>>())
        .await?;
    let permission_candidates = lists
        .iter()
        .filter(|list| !media_list_is_owner_or_admin(auth_user, list))
        .map(|list| list.id)
        .collect::<Vec<_>>();
    let permitted_list_ids = db
        .media_list_ids_with_user_permission(auth_user.id, &permission_candidates)
        .await?;
    let mut values = Vec::with_capacity(lists.len());
    for list in lists {
        if !media_list_is_owner_or_admin(auth_user, &list) && !permitted_list_ids.contains(&list.id)
        {
            continue;
        }
        let child_count = counts.get(&list.id).copied().unwrap_or(0);
        values.push(media_list_to_json(&list, server_id, child_count));
    }
    Ok(values)
}

fn should_include_parent_virtual_items(query: &ItemsQuery) -> bool {
    query.parent_id.is_some()
        && query.ids.is_none()
        && query.include_item_types.is_empty()
        && query.exclude_item_types.is_empty()
        && query.media_types.is_empty()
        && query.person_ids.is_empty()
        && query.genre_ids.is_empty()
        && query.studio_ids.is_empty()
        && query.filters.is_empty()
        && query.search_term.is_none()
        && query.is_folder.is_none()
        && query.is_played.is_none()
        && query.is_favorite.is_none()
}

async fn parent_virtual_items(
    db: &Database,
    query: &ItemsQuery,
    user_id: Option<Uuid>,
    server_id: &str,
    direct_child_count: usize,
) -> Result<Vec<serde_json::Value>, ApiError> {
    let Some(parent_id) = query.parent_id.as_deref() else {
        return Ok(Vec::new());
    };
    let parent_id = parse_jellyfin_uuid(parent_id)?;
    let folders = db.virtual_folders().await?;
    let Some(folder) = folders.iter().find(|folder| folder.id == parent_id) else {
        return Ok(Vec::new());
    };
    let mut values = vec![physical_folder_item_to_json(
        folder,
        server_id,
        direct_child_count,
    )];
    let child_folders = child_virtual_folders(folder, &folders);
    let folder_ids = std::iter::once(folder.id)
        .chain(child_folders.iter().map(|child| child.id))
        .collect::<Vec<_>>();
    let item_counts = db.media_item_counts_by_virtual_folder().await?;
    for child_folder in &child_folders {
        let child_count = item_counts.get(&child_folder.id).copied().unwrap_or(0);
        values.push(physical_folder_item_to_json(
            child_folder,
            server_id,
            child_count,
        ));
    }
    if folder.collection_type.as_deref() != Some("tvshows") {
        return Ok(values);
    }

    let episodes = db.media_items_for_virtual_folders(&folder_ids).await?;
    let episode_ids = episodes
        .iter()
        .map(|episode| episode.id)
        .collect::<Vec<_>>();
    let metadata_by_item =
        media_metadata_by_item_id(db, episode_ids.iter().copied().collect()).await?;
    let playback_by_item = if let Some(user_id) = user_id {
        MediaCatalogStore::playback_states_for_items(db, user_id, &episode_ids)
            .await?
            .into_iter()
            .map(|state| (state.item_id, state))
            .collect::<HashMap<_, _>>()
    } else {
        HashMap::new()
    };

    let mut series_by_name = BTreeMap::<String, TvSeriesSummary>::new();
    let mut seasons_by_series = BTreeMap::<String, BTreeMap<Option<i32>, TvSeasonSummary>>::new();
    for episode in &episodes {
        let metadata = metadata_by_item.get(&episode.id);
        let Some(info) = tv_episode_info_with_metadata(episode, metadata) else {
            continue;
        };
        let playback = playback_by_item.get(&episode.id);
        let series = series_by_name
            .entry(info.series_name.clone())
            .or_insert_with(|| TvSeriesSummary::new(info.series_name.clone()));
        series.add_episode(episode, &info, metadata, playback);

        let season = seasons_by_series
            .entry(info.series_name.clone())
            .or_default()
            .entry(info.season_number)
            .or_insert_with(|| TvSeasonSummary::new(info.season_number));
        season.episode_count += 1;
        if playback.is_none_or(|state| !state.played) {
            season.unplayed_count += 1;
        }
        if let Some(metadata) = metadata {
            season.merge_episode_metadata(metadata);
        }
    }

    for summary in series_by_name.into_values() {
        let series_id = summary.id();
        let series_name = summary.source_name.clone();
        values.push(tv_series_json(server_id, summary));
        if let Some(mut seasons) = seasons_by_series.remove(&series_name) {
            present_unnumbered_season_as_first(&mut seasons, &series_name);
            for season in seasons.into_values() {
                values.push(tv_season_json(server_id, &series_name, &series_id, season));
            }
        }
    }
    Ok(values)
}

fn child_virtual_folders<'a>(
    parent: &VirtualFolder,
    folders: &'a [VirtualFolder],
) -> Vec<&'a VirtualFolder> {
    let parent_locations = parent
        .locations
        .iter()
        .map(|location| normalized_folder_path(location))
        .filter(|location| !location.is_empty())
        .collect::<HashSet<_>>();
    if parent_locations.is_empty() {
        return Vec::new();
    }
    let mut children = folders
        .iter()
        .filter(|folder| folder.id != parent.id)
        .filter(|folder| {
            folder
                .locations
                .iter()
                .map(|location| normalized_folder_path(location))
                .any(|location| parent_locations.contains(&location))
        })
        .collect::<Vec<_>>();
    children.sort_by_key(|item| item.name.to_lowercase());
    children
}

fn normalized_folder_path(path: &str) -> String {
    path.trim().trim_end_matches('/').to_string()
}

async fn virtual_folder_detail_json(
    db: &Database,
    folder: &VirtualFolder,
    server_id: &str,
) -> Result<serde_json::Value, ApiError> {
    let folders = db.virtual_folders().await?;
    let item_counts = db.media_item_counts_by_virtual_folder().await?;
    let child_count = virtual_folder_recursive_count(folder, &folders, &item_counts);
    // A virtual folder is the root of a Jellyfin library and is advertised as a CollectionFolder
    // by `/UserViews`. Keep the same type when a client hydrates that id through `/Items/{id}`;
    // Wholphin rejects a mid-navigation type change to the physical-only `Folder` variant.
    Ok(user_view_to_json_with_count(folder, server_id, child_count))
}

fn physical_folder_item_to_json(
    folder: &VirtualFolder,
    server_id: &str,
    child_count: usize,
) -> serde_json::Value {
    let id = folder.id.simple().to_string();
    let name = folder.name.clone();
    serde_json::json!({
        "Name": name,
        "ServerId": server_id,
        "Id": id,
        "Etag": null,
        "DateCreated": format_time_for_json(folder.created_at),
        "CanDelete": false,
        "CanDownload": false,
        "SortName": folder.name,
        "ExternalUrls": [],
        "Path": folder.locations.first().cloned(),
        "EnableMediaSourceDisplay": true,
        "ChannelId": null,
        "Taglines": [],
        "Genres": [],
        "PlayAccess": "Full",
        "RemoteTrailers": [],
        "ProviderIds": {},
        "IsFolder": true,
        "ParentId": null,
        "Type": "Folder",
        "MediaType": null,
        "CollectionType": folder.collection_type,
        "ChildCount": child_count,
        "RecursiveItemCount": child_count,
        "UserData": default_user_data_json(&id),
        "ImageTags": { "Primary": generated_folder_primary_image_tag(&id) },
        "PrimaryImageAspectRatio": 0.6666667,
        "BackdropImageTags": [],
        "LocationType": "FileSystem",
    })
}

fn sort_json_items(items: &mut [serde_json::Value], query: &ItemsQuery) {
    let descending = query
        .sort_order
        .as_deref()
        .is_some_and(|order| order.eq_ignore_ascii_case("Descending"));
    items.sort_by(|left, right| {
        let left_key = json_string_field(left, "SortName")
            .or_else(|| json_string_field(left, "Name"))
            .unwrap_or_default()
            .to_ascii_lowercase();
        let right_key = json_string_field(right, "SortName")
            .or_else(|| json_string_field(right, "Name"))
            .unwrap_or_default()
            .to_ascii_lowercase();
        if descending {
            right_key.cmp(&left_key)
        } else {
            left_key.cmp(&right_key)
        }
    });
}

async fn item_counts(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    RawQuery(raw_query): RawQuery,
) -> Result<Json<serde_json::Value>, ApiError> {
    let mut query = parse_items_query(raw_query.as_deref());
    let (auth_user, token) =
        require_user(&state.db, &headers, auth_query.api_key.as_deref()).await?;
    let requested_user_id = query.user_id.as_deref().map(resolve_user_id).transpose()?;
    if let Some(requested_user_id) = requested_user_id {
        ensure_user_access(&auth_user, requested_user_id)?;
    }
    scope_items_query_for_plugin_catalogs(
        &state.db,
        &mut query,
        &auth_user,
        &token,
        requested_user_id,
    )
    .await?;
    if let Some(counts) = media_catalog_counts_result(&state.db, &query, requested_user_id).await? {
        return Ok(Json(counts));
    }
    let filtered_items = filtered_media_items(
        state.db.media_items().await?,
        &query,
        requested_user_id,
        &state.db,
    )
    .await?;
    Ok(Json(item_counts_json(&state.db, &filtered_items).await?))
}

