async fn media_catalog_counts_result(
    db: &Database,
    query: &ItemsQuery,
    user_id: Option<Uuid>,
) -> Result<Option<serde_json::Value>, ApiError> {
    if query
        .search_term
        .as_deref()
        .is_some_and(|term| !term.trim().is_empty())
        || query.name_starts_with_or_greater.is_some()
        || query.name_less_than.is_some()
        || query
            .name_starts_with
            .as_deref()
            .is_some_and(|prefix| !prefix.is_ascii())
    {
        return Ok(None);
    }
    // Counts ignore response paging and ordering. Supplying a one-row synthetic page lets the
    // existing exact-support gate and real/synthetic ParentId resolution remain the sole source
    // of truth for which predicates are safe to push down.
    let mut supported_query = query.clone();
    supported_query.start_index = None;
    supported_query.limit = Some(1);
    supported_query.sort_by = None;
    supported_query.sort_order = None;
    let Some(mut db_query) =
        resolved_media_catalog_query_for_items(db, &supported_query, user_id).await?
    else {
        return Ok(None);
    };
    db_query.start_index = 0;
    db_query.limit = 0;
    db_query.sort.clear();
    let counts = MediaCatalogStore::media_item_catalog_counts(db, &db_query).await?;
    Ok(Some(media_item_catalog_counts_json(&counts)))
}

fn media_item_catalog_counts_json(counts: &MediaItemCatalogCounts) -> serde_json::Value {
    serde_json::json!({
        "MovieCount": counts.movie_count,
        "SeriesCount": counts.series_count,
        "EpisodeCount": counts.episode_count,
        "ArtistCount": counts.artist_count,
        "ProgramCount": 0,
        "TrailerCount": counts.trailer_count,
        "SongCount": counts.song_count,
        "AlbumCount": counts.album_count,
        "MusicVideoCount": counts.music_video_count,
        "BoxSetCount": 0,
        "BookCount": counts.book_count,
        "ItemCount": counts.item_count,
    })
}

async fn latest_items(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    RawQuery(raw_query): RawQuery,
) -> Result<Json<Vec<serde_json::Value>>, ApiError> {
    let mut query = parse_items_query(raw_query.as_deref());
    let (auth_user, token) =
        require_user(&state.db, &headers, auth_query.api_key.as_deref()).await?;
    let requested_user_id = query.user_id.as_deref().map(resolve_user_id).transpose()?;
    if let Some(requested_user_id) = requested_user_id {
        ensure_user_access(&auth_user, requested_user_id)?;
    }
    scope_items_query_for_plugin_catalogs(
        &state.db,
        &mut query,
        &auth_user,
        &token,
        requested_user_id,
    )
    .await?;
    let server_id = state.db.server_state().await?.server_id.to_string();
    if let Some(result) = special_user_view_latest_items(&state.db, &query, &server_id).await? {
        return Ok(result);
    }
    if let Some(result) = live_tv_latest_items_for_parent(&state.db, &query, &server_id).await? {
        return Ok(result);
    }
    let mut filtered_items = latest_items_candidates(&state.db, &query, requested_user_id).await?;
    filtered_items =
        apply_latest_user_configuration(&state.db, filtered_items, &query, requested_user_id)
            .await?;
    filtered_items.sort_by(|left, right| {
        compare_media_items(
            right,
            left,
            &[SortField::DateLastMediaAdded, SortField::SortName],
        )
    });
    let limit = latest_items_limit(&query);
    let page = filtered_items.into_iter().take(limit).collect::<Vec<_>>();
    queue_plugin_vod_artwork_prefetch_ids(
        &state,
        &page.iter().map(|item| item.id).collect::<Vec<_>>(),
    );
    Ok(Json(
        items_to_json(&state.db, page, &server_id, requested_user_id, false).await?,
    ))
}

