async fn latest_items_candidates(
    db: &Database,
    query: &ItemsQuery,
    user_id: Option<Uuid>,
) -> Result<Vec<MediaItem>, ApiError> {
    if let Some(items) = exact_latest_items_page(db, query, user_id).await? {
        return Ok(items);
    }

    // Never fall back to loading the entire catalogue: a standard client can issue several
    // Latest calls concurrently and one unsupported predicate previously materialized ~1M rows,
    // exhausting the six-connection pool. Pull a newest-first safety window from SQL and retain
    // the legacy matcher only inside that bounded set.
    const LATEST_FALLBACK_CANDIDATES: usize = 2_000;
    let configuration = latest_user_configuration(db, query, user_id).await?;
    let folders = db.virtual_folders().await?;
    let mut folder_ids = if let Some(parent_id) = query
        .parent_id
        .as_deref()
        .map(parse_jellyfin_uuid)
        .transpose()?
    {
        let Some(parent) = folders.iter().find(|folder| folder.id == parent_id) else {
            return Ok(Vec::new());
        };
        let mut values = vec![parent.id];
        values.extend(
            child_virtual_folders(parent, &folders)
                .into_iter()
                .map(|folder| folder.id),
        );
        values
    } else {
        folders.iter().map(|folder| folder.id).collect()
    };
    folder_ids.retain(|id| !configuration.excluded_folder_ids.contains(id));
    if folder_ids.is_empty() {
        return Ok(Vec::new());
    }
    let page = MediaCatalogStore::media_item_catalog_page(
        db,
        &MediaItemCatalogQuery {
            limit: LATEST_FALLBACK_CANDIDATES,
            include_total_record_count: false,
            virtual_folder_ids: folder_ids,
            allowed_plugin_tuner_ids: query.allowed_plugin_tuner_ids.clone(),
            user_id,
            sort: vec![
                (
                    MediaItemCatalogSortField::DateLastMediaAdded,
                    SortDirection::Descending,
                ),
                (
                    MediaItemCatalogSortField::SortName,
                    SortDirection::Descending,
                ),
            ],
            ..MediaItemCatalogQuery::default()
        },
    )
    .await?;
    filtered_media_items(
        page.items.into_iter().map(|entry| entry.item).collect(),
        query,
        user_id,
        db,
    )
    .await
}

/// Special virtual views do not have persisted media rows. In particular, feeding their synthetic
/// collection folder through the generic Latest fallback serializes it as `BaseItem`, which strict
/// SDK clients reject. Return the real BoxSet-shaped collection entries instead.
async fn special_user_view_latest_items(
    db: &Database,
    query: &ItemsQuery,
    server_id: &str,
) -> Result<Option<Json<Vec<serde_json::Value>>>, ApiError> {
    if special_user_view_collection_type_for_parent(query.parent_id.as_deref()) != Some("boxsets") {
        return Ok(None);
    }
    let limit = latest_items_limit(query);
    let items = special_collection_items(db, server_id)
        .await?
        .into_iter()
        .take(limit)
        .collect();
    Ok(Some(Json(items)))
}

fn latest_items_limit(query: &ItemsQuery) -> usize {
    query.limit.unwrap_or(20).min(100)
}

/// Keep synthetic Live TV views on the bounded channel repository path.
///
/// Per-tuner views intentionally omit `CollectionType` so Jellyfin Web routes them through the
/// ordinary collection UI. That UI also asks `/Items/Latest` for the view. A synthetic parent is
/// not a media-library folder, so letting the generic Latest fallback handle it would load and
/// sort the complete media catalogue before discovering that no media item belongs to the view.
async fn live_tv_latest_items_for_parent(
    db: &Database,
    query: &ItemsQuery,
    server_id: &str,
) -> Result<Option<Json<Vec<serde_json::Value>>>, ApiError> {
    let Some(parent_id) = query.parent_id.as_deref() else {
        return Ok(None);
    };
    let tuner = live_tv_tuner_view_by_id(db, parent_id).await?;
    let tuner_id = if let Some(tuner) = tuner.as_ref() {
        Some(tuner.tuner_id.as_str())
    } else if special_user_view_collection_type_for_parent(Some(parent_id))
        .is_some_and(|collection_type| collection_type.eq_ignore_ascii_case("livetv"))
    {
        None
    } else {
        return Ok(None);
    };

    let mut bounded_query = query.clone();
    bounded_query.start_index = Some(0);
    bounded_query.limit = Some(latest_items_limit(query));
    let Json(mut page) =
        live_tv_channel_items_result(db, &bounded_query, server_id, tuner_id).await?;
    let items = page
        .get_mut("Items")
        .and_then(serde_json::Value::as_array_mut)
        .map(std::mem::take)
        .ok_or_else(|| ApiError::internal("Live TV latest page did not contain an item array"))?;
    Ok(Some(Json(items)))
}

/// Answer Latest from the media-item repository, which applies every filter before its `LIMIT`.
///
/// Returns `None` when the request carries a predicate the repository cannot express, so the caller
/// keeps the exact application-level path. Bounding a candidate window *before* the type, excluded
/// folder and hide-played filters would silently return fewer than the requested newest items, so
/// this is deliberately all-or-nothing rather than a best-effort truncation.
async fn exact_latest_items_page(
    db: &Database,
    query: &ItemsQuery,
    user_id: Option<Uuid>,
) -> Result<Option<Vec<MediaItem>>, ApiError> {
    // Latest imposes its own page size and ordering and ignores paging, so normalize those away
    // before asking whether the repository can answer the remaining predicates exactly.
    let limit = latest_items_limit(query);
    let mut scoped = query.clone();
    scoped.parent_id = None;
    scoped.limit = Some(limit);
    scoped.start_index = None;
    scoped.sort_by = None;
    scoped.sort_order = None;
    let Some(mut db_query) = media_catalog_query_for_items(&scoped, user_id)? else {
        return Ok(None);
    };

    let configuration = latest_user_configuration(db, query, user_id).await?;
    let folders = db.virtual_folders().await?;
    if let Some(parent_id) = query
        .parent_id
        .as_deref()
        .map(parse_jellyfin_uuid)
        .transpose()?
    {
        // Latest always includes a library's children, unlike the catalogue scope that expands them
        // only for `Recursive=true`.
        let Some(parent) = folders.iter().find(|folder| folder.id == parent_id) else {
            return Ok(None);
        };
        let mut scope = vec![parent.id];
        scope.extend(
            child_virtual_folders(parent, &folders)
                .into_iter()
                .map(|folder| folder.id),
        );
        scope.retain(|id| !configuration.excluded_folder_ids.contains(id));
        if scope.is_empty() {
            return Ok(Some(Vec::new()));
        }
        db_query.virtual_folder_ids = scope;
    } else if !configuration.excluded_folder_ids.is_empty() {
        // An empty scope means every folder, so the exclusions have to be materialized as the
        // complement instead.
        let scope = folders
            .iter()
            .map(|folder| folder.id)
            .filter(|id| !configuration.excluded_folder_ids.contains(id))
            .collect::<Vec<_>>();
        if scope.is_empty() {
            return Ok(Some(Vec::new()));
        }
        db_query.virtual_folder_ids = scope;
    }

    db_query.start_index = 0;
    db_query.limit = limit;
    db_query.include_total_record_count = false;
    // Mirror `compare_media_items(right, left, [DateLastMediaAdded, SortName])`: the repository
    // appends a descending id tie-break for a descending sort, which matters here because a library
    // sync stamps thousands of rows with the same `updated_at`.
    db_query.sort = vec![
        (
            MediaItemCatalogSortField::DateLastMediaAdded,
            SortDirection::Descending,
        ),
        (
            MediaItemCatalogSortField::SortName,
            SortDirection::Descending,
        ),
    ];
    if configuration.hide_played {
        db_query.is_played = Some(false);
    }
    if db_query.is_played.is_some() && db_query.user_id.is_none() {
        // The repository matches nothing for a user-data filter without a user; the legacy path
        // instead ignores the filter, so leave this shape to it.
        return Ok(None);
    }

    let page = MediaCatalogStore::media_item_catalog_page(db, &db_query).await?;
    Ok(Some(
        page.items.into_iter().map(|entry| entry.item).collect(),
    ))
}

struct LatestUserConfiguration {
    excluded_folder_ids: HashSet<Uuid>,
    hide_played: bool,
}

async fn latest_user_configuration(
    db: &Database,
    query: &ItemsQuery,
    user_id: Option<Uuid>,
) -> Result<LatestUserConfiguration, ApiError> {
    let Some(user_id) = user_id else {
        return Ok(LatestUserConfiguration {
            excluded_folder_ids: HashSet::new(),
            hide_played: false,
        });
    };
    let configuration = db
        .user_configuration(user_id)
        .await?
        .unwrap_or_else(default_user_configuration);
    let excluded_folder_ids = latest_items_excluded_folder_ids(db, &configuration).await?;
    let hide_played = configuration
        .get("HidePlayedInLatest")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(true)
        && query.is_played.is_none()
        && query_filters_played_value(&query.filters).is_none();
    Ok(LatestUserConfiguration {
        excluded_folder_ids,
        hide_played,
    })
}

async fn apply_latest_user_configuration(
    db: &Database,
    mut items: Vec<MediaItem>,
    query: &ItemsQuery,
    user_id: Option<Uuid>,
) -> Result<Vec<MediaItem>, ApiError> {
    let Some(user_id) = user_id else {
        return Ok(items);
    };
    let configuration = latest_user_configuration(db, query, Some(user_id)).await?;

    if !configuration.excluded_folder_ids.is_empty() {
        items.retain(|item| {
            !configuration
                .excluded_folder_ids
                .contains(&item.virtual_folder_id)
        });
    }

    if configuration.hide_played {
        let item_ids = items.iter().map(|item| item.id).collect::<Vec<_>>();
        let playback_by_item = MediaCatalogStore::playback_states_for_items(db, user_id, &item_ids)
            .await?
            .into_iter()
            .map(|state| (state.item_id, state))
            .collect::<HashMap<_, _>>();
        items.retain(|item| {
            !playback_by_item
                .get(&item.id)
                .is_some_and(|state| state.played)
        });
    }

    Ok(items)
}

async fn latest_items_excluded_folder_ids(
    db: &Database,
    configuration: &serde_json::Value,
) -> Result<HashSet<Uuid>, ApiError> {
    let excludes = configuration
        .get("LatestItemsExcludes")
        .and_then(serde_json::Value::as_array)
        .map(|values| {
            values
                .iter()
                .filter_map(serde_json::Value::as_str)
                .map(|value| value.trim().to_ascii_lowercase())
                .filter(|value| !value.is_empty())
                .collect::<HashSet<_>>()
        })
        .unwrap_or_default();
    if excludes.is_empty() {
        return Ok(HashSet::new());
    }

    let folders = db.virtual_folders().await?;
    Ok(folders
        .into_iter()
        .filter(|folder| {
            let id = folder.id.simple().to_string().to_ascii_lowercase();
            let name = folder.name.to_ascii_lowercase();
            let collection_type = folder
                .collection_type
                .as_deref()
                .unwrap_or_default()
                .to_ascii_lowercase();
            excludes.contains(&id)
                || excludes.contains(&name)
                || excludes.contains(&collection_type)
        })
        .map(|folder| folder.id)
        .collect())
}

async fn movie_recommendations(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    RawQuery(raw_query): RawQuery,
) -> Result<Json<Vec<serde_json::Value>>, ApiError> {
    let mut query = parse_items_query(raw_query.as_deref());
    let (auth_user, token) =
        require_user(&state.db, &headers, auth_query.api_key.as_deref()).await?;
    let requested_user_id = query
        .user_id
        .as_deref()
        .map(resolve_user_id)
        .transpose()?
        .unwrap_or(auth_user.id);
    ensure_user_access(&auth_user, requested_user_id)?;
    scope_items_query_for_plugin_catalogs(
        &state.db,
        &mut query,
        &auth_user,
        &token,
        Some(requested_user_id),
    )
    .await?;
    let category_limit =
        query_string_value(raw_query.as_deref(), &["CategoryLimit", "categoryLimit"])
            .and_then(|value| value.parse::<usize>().ok())
            .unwrap_or(5)
            .clamp(1, 20);
    let item_limit = query_string_value(raw_query.as_deref(), &["ItemLimit", "itemLimit"])
        .and_then(|value| value.parse::<usize>().ok())
        .or(query.limit)
        .unwrap_or(8)
        .clamp(1, 50);

    if query.include_item_types.is_empty() {
        query.include_item_types.push("Movie".to_string());
    }
    if query.sort_by.is_none() {
        query.sort_by = Some("DateCreated,SortName".to_string());
    }
    if query.sort_order.is_none() {
        query.sort_order = Some("Descending".to_string());
    }
    if query.limit.is_none() {
        query.limit = Some(20);
    }

    let mut all_query = query.clone();
    all_query.start_index = None;
    all_query.limit = None;
    all_query.is_played = None;
    all_query.filters = metadata_scope_filters(&all_query.filters);
    let all_movies = filtered_media_items(
        state.db.media_items_by_collection_type("movies").await?,
        &all_query,
        Some(requested_user_id),
        &state.db,
    )
    .await?;
    let metadata_by_item =
        media_metadata_by_item_id(&state.db, all_movies.iter().map(|item| item.id).collect())
            .await?;
    let mut recently_played = Vec::<(MediaItem, PlaybackState)>::new();
    let mut liked = Vec::<(MediaItem, PlaybackState)>::new();
    let playback_by_item = state
        .db
        .playback_states_for_user(requested_user_id)
        .await?
        .into_iter()
        .map(|playback| (playback.item_id, playback))
        .collect::<HashMap<_, _>>();
    for item in &all_movies {
        let Some(playback) = playback_by_item.get(&item.id) else {
            continue;
        };
        if playback.played {
            recently_played.push((item.clone(), playback.clone()));
        }
        if playback.is_favorite || playback.rating.is_some_and(|rating| rating > 0.0) {
            liked.push((item.clone(), playback.clone()));
        }
    }
    recently_played.sort_by_key(|(_, item)| std::cmp::Reverse(item.updated_at));
    liked.sort_by_key(|(_, item)| std::cmp::Reverse(item.updated_at));

    let server_id = state.db.server_state().await?.server_id.to_string();
    let recommendation_context = MovieRecommendationContext {
        state: &state,
        server_id: &server_id,
        user_id: requested_user_id,
        movies: &all_movies,
        metadata_by_item: &metadata_by_item,
        item_limit,
    };
    let mut categories = movie_recommendation_categories(
        &recommendation_context,
        recently_played.iter().map(|(item, _)| item).collect(),
        liked.iter().map(|(item, _)| item).collect(),
        category_limit,
    )
    .await?;
    if !categories.is_empty() {
        categories.sort_by(|left, right| {
            left["RecommendationType"]
                .as_str()
                .unwrap_or_default()
                .cmp(right["RecommendationType"].as_str().unwrap_or_default())
        });
        categories.truncate(category_limit);
        return Ok(Json(categories));
    }

    if query.is_played.is_none() && query_filters_played_value(&query.filters).is_none() {
        query.is_played = Some(false);
    }
    query.limit = Some(item_limit);
    let filtered_items = filtered_media_items(
        all_movies.clone(),
        &query,
        Some(requested_user_id),
        &state.db,
    )
    .await?;
    let items = items_to_json(
        &state.db,
        paged_media_items(filtered_items, &query),
        &server_id,
        Some(requested_user_id),
        false,
    )
    .await?;

    if items.is_empty() {
        return Ok(Json(Vec::new()));
    }

    Ok(Json(vec![serde_json::json!({
        "BaselineItemName": null,
        "CategoryId": "latest",
        "RecommendationType": "Latest",
        "Items": items,
    })]))
}

struct MovieRecommendationContext<'a> {
    state: &'a AppState,
    server_id: &'a str,
    user_id: Uuid,
    movies: &'a [MediaItem],
    metadata_by_item: &'a HashMap<Uuid, serde_json::Value>,
    item_limit: usize,
}

async fn movie_recommendation_categories(
    context: &MovieRecommendationContext<'_>,
    recently_played: Vec<&MediaItem>,
    liked: Vec<&MediaItem>,
    category_limit: usize,
) -> Result<Vec<serde_json::Value>, ApiError> {
    let mut categories = Vec::new();
    let mut seen_categories = HashSet::<String>::new();
    for (baseline, recommendation_type) in recently_played
        .iter()
        .take(6)
        .map(|item| (*item, "SimilarToRecentlyPlayed"))
        .chain(
            liked
                .iter()
                .take(10)
                .map(|item| (*item, "SimilarToLikedItem")),
        )
    {
        if categories.len() >= category_limit {
            break;
        }
        if let Some(category) =
            movie_similarity_recommendation_category(context, baseline, recommendation_type).await?
            && seen_categories.insert(movie_recommendation_category_key(&category))
        {
            categories.push(category);
        }
    }

    let recent_metadata = recently_played
        .iter()
        .take(6)
        .filter_map(|item| context.metadata_by_item.get(&item.id))
        .collect::<Vec<_>>();
    for (name, recommendation_type, person_type) in movie_recommendation_people(&recent_metadata) {
        if categories.len() >= category_limit {
            break;
        }
        if let Some(category) =
            movie_person_recommendation_category(context, &name, &person_type, &recommendation_type)
                .await?
            && seen_categories.insert(movie_recommendation_category_key(&category))
        {
            categories.push(category);
        }
    }

    Ok(categories)
}

async fn movie_similarity_recommendation_category(
    context: &MovieRecommendationContext<'_>,
    baseline: &MediaItem,
    recommendation_type: &str,
) -> Result<Option<serde_json::Value>, ApiError> {
    let Some(baseline_metadata) = context.metadata_by_item.get(&baseline.id) else {
        return Ok(None);
    };
    let baseline_terms = movie_recommendation_terms(baseline_metadata);
    if baseline_terms.is_empty() {
        return Ok(None);
    }
    let mut scored = context
        .movies
        .iter()
        .filter(|item| item.id != baseline.id)
        .filter_map(|item| {
            let metadata = context.metadata_by_item.get(&item.id)?;
            let score = movie_recommendation_terms(metadata)
                .intersection(&baseline_terms)
                .count();
            (score > 0).then_some((score, item.clone()))
        })
        .collect::<Vec<_>>();
    scored.sort_by(|(left_score, left), (right_score, right)| {
        right_score
            .cmp(left_score)
            .then_with(|| compare_media_items(left, right, &[SortField::SortName]))
    });
    let items = scored
        .into_iter()
        .take(context.item_limit)
        .map(|(_, item)| item)
        .collect::<Vec<_>>();
    if items.is_empty() {
        return Ok(None);
    }
    let items = items_to_json(
        &context.state.db,
        items,
        context.server_id,
        Some(context.user_id),
        false,
    )
    .await?;
    Ok(Some(serde_json::json!({
        "BaselineItemName": baseline.name,
        "CategoryId": baseline.id.simple().to_string(),
        "RecommendationType": recommendation_type,
        "Items": items,
    })))
}

async fn movie_person_recommendation_category(
    context: &MovieRecommendationContext<'_>,
    person_name: &str,
    person_type: &str,
    recommendation_type: &str,
) -> Result<Option<serde_json::Value>, ApiError> {
    let mut items = context
        .movies
        .iter()
        .filter(|item| {
            context
                .metadata_by_item
                .get(&item.id)
                .is_some_and(|metadata| {
                    metadata_people_by_type(metadata, person_type)
                        .iter()
                        .any(|name| name.eq_ignore_ascii_case(person_name))
                })
        })
        .cloned()
        .collect::<Vec<_>>();
    items.sort_by(|left, right| compare_media_items(left, right, &[SortField::SortName]));
    items.truncate(context.item_limit);
    if items.is_empty() {
        return Ok(None);
    }
    let items = items_to_json(
        &context.state.db,
        items,
        context.server_id,
        Some(context.user_id),
        false,
    )
    .await?;
    Ok(Some(serde_json::json!({
        "BaselineItemName": person_name,
        "CategoryId": stable_entity_id("Recommendation", &format!("{recommendation_type}:{person_name}")),
        "RecommendationType": recommendation_type,
        "Items": items,
    })))
}

fn movie_recommendation_terms(metadata: &serde_json::Value) -> HashSet<String> {
    metadata_values_from_json(metadata, &["Genres", "Studios", "Tags", "People", "Cast"])
        .into_iter()
        .map(|value| value.to_ascii_lowercase())
        .collect()
}

fn movie_recommendation_people(
    metadata_values: &[&serde_json::Value],
) -> Vec<(String, String, String)> {
    let mut people = BTreeMap::<String, (String, String, String)>::new();
    for metadata in metadata_values {
        for director in metadata_people_by_type(metadata, "Director") {
            people
                .entry(format!("director:{}", director.to_ascii_lowercase()))
                .or_insert((
                    director,
                    "HasDirectorFromRecentlyPlayed".to_string(),
                    "Director".to_string(),
                ));
        }
        for actor in metadata_people_by_type(metadata, "Actor") {
            people
                .entry(format!("actor:{}", actor.to_ascii_lowercase()))
                .or_insert((
                    actor,
                    "HasActorFromRecentlyPlayed".to_string(),
                    "Actor".to_string(),
                ));
        }
    }
    people.into_values().collect()
}

fn metadata_people_by_type(metadata: &serde_json::Value, person_type: &str) -> Vec<String> {
    let Some(people) = json_field_case_insensitive(metadata, "People")
        .or_else(|| json_field_case_insensitive(metadata, "Cast"))
        .and_then(serde_json::Value::as_array)
    else {
        return Vec::new();
    };
    let mut values = BTreeMap::<String, String>::new();
    for person in people {
        match person {
            serde_json::Value::String(name) if person_type.eq_ignore_ascii_case("Actor") => {
                insert_metadata_value(name, &mut values);
            }
            serde_json::Value::Object(object) => {
                let matches_type = object
                    .get("Type")
                    .or_else(|| object.get("PersonType"))
                    .and_then(serde_json::Value::as_str)
                    .map(|value| value.eq_ignore_ascii_case(person_type))
                    .unwrap_or_else(|| person_type.eq_ignore_ascii_case("Actor"));
                if matches_type
                    && let Some(name) = object.get("Name").and_then(serde_json::Value::as_str)
                {
                    insert_metadata_value(name, &mut values);
                }
            }
            _ => {}
        }
    }
    values.into_values().collect()
}

fn movie_recommendation_category_key(category: &serde_json::Value) -> String {
    format!(
        "{}:{}",
        category["RecommendationType"].as_str().unwrap_or_default(),
        category["CategoryId"].as_str().unwrap_or_default()
    )
}

async fn shows_next_up(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    RawQuery(raw_query): RawQuery,
) -> Result<Json<serde_json::Value>, ApiError> {
    let mut query = parse_items_query(raw_query.as_deref());
    let (auth_user, token) =
        require_user(&state.db, &headers, auth_query.api_key.as_deref()).await?;
    let requested_user_id = query
        .user_id
        .as_deref()
        .map(resolve_user_id)
        .transpose()?
        .unwrap_or(auth_user.id);
    ensure_user_access(&auth_user, requested_user_id)?;
    scope_items_query_for_plugin_catalogs(
        &state.db,
        &mut query,
        &auth_user,
        &token,
        Some(requested_user_id),
    )
    .await?;
    if query.include_item_types.is_empty() {
        query.include_item_types.push("Episode".to_string());
    }
    if query.is_played.is_none() && query_filters_played_value(&query.filters).is_none() {
        query.is_played = Some(false);
    }

    let next_up_virtual_folder_id = if let Some(parent_id) = query.parent_id.as_deref() {
        let Ok(parent_id) = parse_jellyfin_uuid(parent_id) else {
            return Err(ApiError::bad_request("invalid parent id"));
        };
        state
            .db
            .virtual_folders()
            .await?
            .into_iter()
            .find(|folder| folder.id == parent_id)
            .map(|folder| folder.id)
    } else {
        None
    };
    let common_next_up_query = is_common_next_up_query(&query)
        && (query.parent_id.is_none() || next_up_virtual_folder_id.is_some());
    if common_next_up_query
        && query.series_id.is_none()
        && let Some(limit) = query.limit
    {
        let start_index = query.start_index.unwrap_or(0);
        let candidate_page = MediaCatalogStore::tv_next_up_candidate_page(
            &state.db,
            requested_user_id,
            next_up_virtual_folder_id,
            start_index,
            limit,
            query_flag(&query._enable_total_record_count).unwrap_or(true),
        )
        .await?;
        let page_ids = candidate_page
            .items
            .iter()
            .map(|item| item.id)
            .collect::<Vec<_>>();
        let page = MediaCatalogStore::media_items_by_ids(&state.db, &page_ids).await?;
        let server_id = state.db.server_state().await?.server_id.to_string();
        let items =
            items_to_json(&state.db, page, &server_id, Some(requested_user_id), false).await?;
        return Ok(Json(query_result_with_total(
            items,
            candidate_page.total_record_count,
            candidate_page.start_index,
        )));
    }
    let mut prefetched_metadata = HashMap::new();
    let mut resolved_next_up_series_id = query.series_id.clone();
    // Only the SeriesId filter reads candidate metadata. Without it nothing downstream touches the
    // streams or metadata payloads before paging, so leave both unfetched and hydrate the retained
    // page below: one-per-series selection is derived from each episode's name and path.
    let hydrate_page = common_next_up_query && query.series_id.is_none();
    let mut episodes = if hydrate_page {
        MediaCatalogStore::tv_next_up_candidate_items(&state.db, requested_user_id).await?
    } else if common_next_up_query {
        let series_id = query
            .series_id
            .as_deref()
            .expect("common filtered NextUp query has a SeriesId");
        // Jellyfin Web requests NextUp for the series detail it has just opened. Loading every
        // unplayed episode in the library here makes that single-series request exceed
        // PostgreSQL's statement timeout at catalogue scale. Resolve the persisted series (or a
        // plugin's public series anchor) first and keep every subsequent filter bounded to it.
        let (snapshot, resolved_series_id) =
            tv_episode_catalog_snapshot_scoped_to_series(&state.db, series_id).await?;
        resolved_next_up_series_id = Some(resolved_series_id);
        prefetched_metadata = snapshot.metadata_by_item;
        let mut scoped_query = query.clone();
        scoped_query.series_id = None;
        filtered_media_items(
            snapshot.items,
            &scoped_query,
            Some(requested_user_id),
            &state.db,
        )
        .await?
    } else {
        filtered_media_items(
            state.db.media_items_by_collection_type("tvshows").await?,
            &query,
            Some(requested_user_id),
            &state.db,
        )
        .await?
    };
    if let Some(series_id) = resolved_next_up_series_id.as_deref() {
        let metadata_by_item = if prefetched_metadata.is_empty() {
            media_metadata_by_item_id(&state.db, episodes.iter().map(|item| item.id).collect())
                .await?
        } else {
            std::mem::take(&mut prefetched_metadata)
        };
        episodes.retain(|item| {
            tv_episode_matches_series(item, metadata_by_item.get(&item.id), series_id)
        });
    }
    let mut next_by_series = BTreeMap::<String, MediaItem>::new();
    for episode in episodes.into_iter().filter(is_tv_episode) {
        let key = tv_episode_series_key(&episode);
        match next_by_series.get(&key) {
            Some(existing) if compare_tv_episodes(existing, &episode) != Ordering::Greater => {}
            _ => {
                next_by_series.insert(key, episode);
            }
        }
    }
    let mut next_up = next_by_series.into_values().collect::<Vec<_>>();
    next_up.sort_by(compare_tv_episodes);
    let total_record_count = next_up.len();
    let mut page = paged_media_items(next_up, &query);
    if hydrate_page {
        // The candidates carry no `media_streams`, so reload exactly the retained page before it is
        // serialized. Items deleted since the candidate fetch simply drop out.
        let page_ids = page.iter().map(|item| item.id).collect::<Vec<_>>();
        page = MediaCatalogStore::media_items_by_ids(&state.db, &page_ids).await?;
    }
    let server_id = state.db.server_state().await?.server_id.to_string();
    let items = items_to_json(&state.db, page, &server_id, Some(requested_user_id), false).await?;
    Ok(Json(query_result_with_total(
        items,
        total_record_count,
        query.start_index.unwrap_or(0),
    )))
}

/// The native query deliberately covers only the dominant NextUp shape. Any predicate that is
/// not represented here stays on the established application-level filter path, which keeps the
/// optimization contract-preserving as new Jellyfin query fields are added.
fn is_common_next_up_query(query: &ItemsQuery) -> bool {
    let expected = ItemsQuery {
        user_id: query.user_id.clone(),
        parent_id: query.parent_id.clone(),
        series_id: query.series_id.clone(),
        include_item_types: query.include_item_types.clone(),
        is_played: query.is_played,
        start_index: query.start_index,
        limit: query.limit,
        sort_by: query.sort_by.clone(),
        sort_order: query.sort_order.clone(),
        fields: query.fields.clone(),
        _image_type_limit: query._image_type_limit.clone(),
        _enable_images: query._enable_images.clone(),
        _enable_user_data: query._enable_user_data.clone(),
        _collapse_box_set_items: query._collapse_box_set_items.clone(),
        _image_types: query._image_types.clone(),
        _enable_image_types: query._enable_image_types.clone(),
        _enable_total_record_count: query._enable_total_record_count.clone(),
        ..ItemsQuery::default()
    };
    query == &expected
        && query.is_played == Some(false)
        && csv_values_lowercase(&query.include_item_types).is_some_and(|types| types == ["episode"])
}

/// Keep the SQL-prefiltered Upcoming path restricted to fields that do not participate in item
/// selection. Date precedence/parsing, effective episode classification, total calculation and
/// final ordering intentionally remain in Rust below.
fn is_common_upcoming_query(query: &ItemsQuery) -> bool {
    let expected = ItemsQuery {
        user_id: query.user_id.clone(),
        include_item_types: query.include_item_types.clone(),
        start_index: query.start_index,
        limit: query.limit,
        sort_by: query.sort_by.clone(),
        sort_order: query.sort_order.clone(),
        fields: query.fields.clone(),
        _image_type_limit: query._image_type_limit.clone(),
        _enable_images: query._enable_images.clone(),
        _enable_user_data: query._enable_user_data.clone(),
        _collapse_box_set_items: query._collapse_box_set_items.clone(),
        _image_types: query._image_types.clone(),
        _enable_image_types: query._enable_image_types.clone(),
        _enable_total_record_count: query._enable_total_record_count.clone(),
        ..ItemsQuery::default()
    };
    query == &expected
        && csv_values_lowercase(&query.include_item_types).is_some_and(|types| types == ["episode"])
}

async fn shows_upcoming(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    RawQuery(raw_query): RawQuery,
) -> Result<Json<serde_json::Value>, ApiError> {
    let mut query = parse_items_query(raw_query.as_deref());
    let (auth_user, token) =
        require_user(&state.db, &headers, auth_query.api_key.as_deref()).await?;
    let requested_user_id = query
        .user_id
        .as_deref()
        .map(resolve_user_id)
        .transpose()?
        .unwrap_or(auth_user.id);
    ensure_user_access(&auth_user, requested_user_id)?;
    scope_items_query_for_plugin_catalogs(
        &state.db,
        &mut query,
        &auth_user,
        &token,
        Some(requested_user_id),
    )
    .await?;
    if query.include_item_types.is_empty() {
        query.include_item_types.push("Episode".to_string());
    }

    let now = OffsetDateTime::now_utc();
    let use_sql_candidates = is_common_upcoming_query(&query);
    let mut prefetched_metadata = HashMap::new();
    let candidates = if use_sql_candidates {
        let candidates = MediaCatalogStore::tv_upcoming_candidates(&state.db, now).await?;
        let mut items = Vec::with_capacity(candidates.len());
        prefetched_metadata.reserve(candidates.len());
        for candidate in candidates {
            prefetched_metadata.insert(candidate.item.id, candidate.metadata);
            items.push(candidate.item);
        }
        items
    } else {
        filtered_media_items(
            state.db.media_items_by_collection_type("tvshows").await?,
            &query,
            Some(requested_user_id),
            &state.db,
        )
        .await?
    };
    let metadata_by_id = if use_sql_candidates {
        prefetched_metadata
    } else {
        media_metadata_by_item_id(
            &state.db,
            candidates.iter().map(|episode| episode.id).collect(),
        )
        .await?
    };
    let mut upcoming = candidates
        .into_iter()
        .filter(is_tv_episode)
        .filter(|episode| {
            metadata_by_id
                .get(&episode.id)
                .and_then(upcoming_media_item_premiere_date)
                .is_some_and(|premiere_date| premiere_date > now)
        })
        .collect::<Vec<_>>();
    upcoming.sort_by(|left, right| {
        let left_date = metadata_by_id
            .get(&left.id)
            .and_then(upcoming_media_item_premiere_date)
            .unwrap_or(left.created_at);
        let right_date = metadata_by_id
            .get(&right.id)
            .and_then(upcoming_media_item_premiere_date)
            .unwrap_or(right.created_at);
        left_date
            .cmp(&right_date)
            .then_with(|| compare_tv_episodes(left, right))
    });
    let total_record_count = upcoming.len();
    let server_id = state.db.server_state().await?.server_id.to_string();
    let items = items_to_json(
        &state.db,
        paged_media_items(upcoming, &query),
        &server_id,
        Some(requested_user_id),
        false,
    )
    .await?;
    Ok(Json(query_result_with_total(
        items,
        total_record_count,
        query.start_index.unwrap_or(0),
    )))
}

async fn resume_items(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    RawQuery(raw_query): RawQuery,
) -> Result<Json<serde_json::Value>, ApiError> {
    let (auth_user, token) = require_user(&state.db, &headers, query.api_key.as_deref()).await?;
    let mut items_query = parse_items_query(raw_query.as_deref());
    let requested_user_id = items_query
        .user_id
        .as_deref()
        .map(resolve_user_id)
        .transpose()?
        .unwrap_or(auth_user.id);
    ensure_user_access(&auth_user, requested_user_id)?;
    scope_items_query_for_plugin_catalogs(
        &state.db,
        &mut items_query,
        &auth_user,
        &token,
        Some(requested_user_id),
    )
    .await?;
    resume_items_result(&state.db, requested_user_id, &items_query).await
}

