async fn resume_items_result(
    db: &Database,
    user_id: Uuid,
    query: &ItemsQuery,
) -> Result<Json<serde_json::Value>, ApiError> {
    let resume_policy = resume_policy(db).await?;
    if resume_query_supports_sql_page(query)
        && let Some(limit) = query.limit
    {
        let page = db
            .resume_items_page_for_user(
                user_id,
                ResumeItemsPageQuery {
                    start_index: query.start_index.unwrap_or(0),
                    limit,
                    min_pct: resume_policy.min_pct,
                    max_pct: resume_policy.max_pct,
                    min_duration_ticks: resume_policy.min_duration_ticks,
                },
            )
            .await?;
        let server_id = db.server_state().await?.server_id.to_string();
        let item_ids = page
            .items
            .iter()
            .map(|(item, _)| item.id)
            .collect::<HashSet<_>>();
        let metadata_by_item = media_metadata_by_item_id(db, item_ids).await?;
        let items = page
            .items
            .into_iter()
            .map(|(item, playback)| {
                media_item_to_json_with_playback_and_metadata(
                    &item,
                    &server_id,
                    Some(&playback),
                    metadata_by_item.get(&item.id),
                )
            })
            .collect();
        return Ok(Json(query_result_with_total(
            items,
            page.total_record_count,
            page.start_index,
        )));
    }
    let resume_items = db
        .resume_items_for_user(user_id, i64::MAX)
        .await?
        .into_iter()
        .filter(|(item, playback)| item_matches_resume_policy(item, playback, resume_policy))
        .collect::<Vec<_>>();
    let resume_order = resume_items
        .iter()
        .enumerate()
        .map(|(index, (item, _))| (item.id, index))
        .collect::<HashMap<_, _>>();
    let mut items = filtered_media_items(
        resume_items.into_iter().map(|(item, _)| item).collect(),
        query,
        Some(user_id),
        db,
    )
    .await?;
    if query.sort_by.is_none() {
        items.sort_by_key(|item| resume_order.get(&item.id).copied().unwrap_or(usize::MAX));
    }
    let total_record_count = items.len();
    let start_index = query.start_index.unwrap_or(0);
    let server_id = db.server_state().await?.server_id.to_string();
    let items = items_to_json(
        db,
        paged_media_items(items, query),
        &server_id,
        Some(user_id),
        false,
    )
    .await?;
    Ok(Json(query_result_with_total(
        items,
        total_record_count,
        start_index,
    )))
}

/// The resume repository currently owns policy filtering, recency ordering and pagination.
/// Preserve the exact legacy path whenever a request asks for any additional item predicate or
/// ordering. Presentation-only query fields are accepted because the legacy resume response does
/// not use them to select or order rows either.
fn resume_query_supports_sql_page(query: &ItemsQuery) -> bool {
    if query.limit.is_none() {
        return false;
    }
    let mut selection = query.clone();
    selection.user_id = None;
    selection.start_index = None;
    selection.limit = None;
    selection.fields = None;
    selection._image_type_limit = None;
    selection._enable_images = None;
    selection._enable_user_data = None;
    selection._collapse_box_set_items = None;
    selection._image_types = None;
    selection._enable_image_types = None;
    selection._enable_total_record_count = None;
    selection == ItemsQuery::default()
}

#[derive(Debug, Clone, Copy)]
struct ResumePolicy {
    min_pct: i64,
    max_pct: i64,
    min_duration_ticks: i64,
}

async fn resume_policy(db: &Database) -> Result<ResumePolicy, ApiError> {
    let mut server_options = default_server_configuration_options();
    if let serde_json::Value::Object(current) =
        db.system_configuration_payloads().await?.server_options
    {
        for (key, value) in current {
            server_options[key] = value;
        }
    }

    let min_pct = server_options_i64(&server_options, "MinResumePct", 5).clamp(0, 100);
    let max_pct = server_options_i64(&server_options, "MaxResumePct", 90).clamp(min_pct, 100);
    let min_duration_seconds =
        server_options_i64(&server_options, "MinResumeDurationSeconds", 300).max(0);

    Ok(ResumePolicy {
        min_pct,
        max_pct,
        min_duration_ticks: min_duration_seconds.saturating_mul(10_000_000),
    })
}

fn server_options_i64(options: &serde_json::Value, key: &str, default: i64) -> i64 {
    options
        .get(key)
        .and_then(serde_json::Value::as_i64)
        .unwrap_or(default)
}

fn item_matches_resume_policy(
    item: &MediaItem,
    playback: &PlaybackState,
    policy: ResumePolicy,
) -> bool {
    let Some(runtime_ticks) = item
        .runtime_ticks
        .filter(|runtime_ticks| *runtime_ticks > 0)
    else {
        return true;
    };
    if runtime_ticks < policy.min_duration_ticks {
        return false;
    }
    let played_pct = playback.position_ticks as f64 * 100.0 / runtime_ticks as f64;
    played_pct >= policy.min_pct as f64 && played_pct < policy.max_pct as f64
}

