async fn item_detail(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    Path(item_id): Path<String>,
) -> Result<Json<serde_json::Value>, ApiError> {
    let (user, token) = require_user(&state.db, &headers, query.api_key.as_deref()).await?;
    let user_context = plugin_user_context(&user, &token);
    if item_id.eq_ignore_ascii_case("livetv") {
        return Ok(Json(live_tv_root_item_json(&state.db).await?));
    }
    if looks_like_live_tv_program_id(&item_id)
        && let Some(program) = live_tv_program_by_id(&state.db, &item_id).await?
    {
        return Ok(Json(program));
    }
    if parse_jellyfin_uuid(&item_id).is_err() {
        if let Some(channel) = live_tv_channel_json_by_id(&state.db, &item_id).await? {
            return Ok(Json(channel));
        }
        if let Some(program) = live_tv_program_by_id(&state.db, &item_id).await? {
            return Ok(Json(program));
        }
    }
    let requested_id = parse_jellyfin_uuid(&item_id)?;
    let server_id = state.db.server_state().await?.server_id.to_string();
    if let Some(view) = special_user_view_by_id(&item_id, &server_id) {
        return Ok(Json(view));
    }
    if let Some(tuner) = live_tv_tuner_view_by_id(&state.db, &item_id).await? {
        return Ok(Json(live_tv_tuner_view_to_json(&tuner, &server_id)));
    }
    if let Some(folder) = state
        .db
        .virtual_folders()
        .await?
        .into_iter()
        .find(|folder| folder.id == requested_id)
    {
        return Ok(Json(
            virtual_folder_detail_json(&state.db, &folder, &server_id).await?,
        ));
    }
    if let Ok(list) = state.db.media_list_by_id(requested_id).await {
        ensure_media_list_read_access(&state.db, &user, &list).await?;
        let child_count = state.db.media_list_items(list.id).await?.len();
        return Ok(Json(media_list_to_json(&list, &server_id, child_count)));
    }
    if let Ok(mut item) = media_item_by_id(&state.db, &item_id).await {
        let mut metadata = metadata_payload_for_item(&state.db, item.id).await?;
        ensure_plugin_catalog_item_visible(&state.db, &metadata, &user_context).await?;
        // Xtream VOD/series items import with synthetic 1-video/1-audio streams;
        // probe the remote source on-demand so the detail page can expose real
        // audio languages and subtitle tracks for selection. Cached after first probe.
        if is_xtream_remote_media(Some(&metadata)) {
            item = ensure_xtream_remote_media_info(&state, item, &mut metadata)
                .await?
                .item;
        }
        enrich_plugin_vod_item_metadata(&state, &mut item, &mut metadata).await;
        enrich_plugin_vod_item_media_streams(&state, &mut item, &metadata, user_context).await;
        return Ok(Json(media_item_to_json_with_playback_and_metadata(
            &item,
            &server_id,
            None,
            Some(&metadata),
        )));
    }
    if let Some(channel) = live_tv_playback_channel_json_by_id(&state.db, &item_id).await? {
        return Ok(Json(channel));
    }
    if let Some(channel) = live_tv_channel_json_by_id(&state.db, &item_id).await? {
        return Ok(Json(channel));
    }
    if let Some((series_name, series_id, mut summary)) =
        tv_season_summary_by_id(&state.db, &item_id, None, false).await?
    {
        ensure_plugin_catalog_item_visible(&state.db, &summary.metadata, &user_context).await?;
        enrich_plugin_vod_virtual_metadata(&state, &item_id, true, &mut summary.metadata).await;
        return Ok(Json(tv_season_json(
            &server_id,
            &series_name,
            &series_id,
            summary,
        )));
    }
    // A season id is also a syntactically valid Jellyfin UUID. Resolve the indexed SeasonId
    // projection before trying the synthetic-series fallback; doing this in the opposite order
    // scans every legacy episode without a canonical SeriesId before a web season page can open.
    if let Some(mut summary) = tv_series_summary_by_id(&state.db, &item_id, None).await? {
        ensure_plugin_catalog_item_visible(&state.db, &summary.metadata, &user_context).await?;
        enrich_plugin_vod_virtual_metadata(&state, &item_id, false, &mut summary.metadata).await;
        return Ok(Json(tv_series_json(&server_id, summary)));
    }
    if let Some((series_name, series_id, mut summary)) =
        tv_season_summary_by_id(&state.db, &item_id, None, true).await?
    {
        ensure_plugin_catalog_item_visible(&state.db, &summary.metadata, &user_context).await?;
        enrich_plugin_vod_virtual_metadata(&state, &item_id, true, &mut summary.metadata).await;
        return Ok(Json(tv_season_json(
            &server_id,
            &series_name,
            &series_id,
            summary,
        )));
    }
    if let Some(entity) = metadata_entity_by_stable_id(&state.db, &item_id).await? {
        return Ok(Json(metadata_entity_match_json(&server_id, &entity)));
    }
    if let Some(program) = live_tv_program_by_id(&state.db, &item_id).await? {
        return Ok(Json(program));
    }

    Err(ApiError::not_found("Item not found"))
}

async fn current_user_item_detail(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    Path(item_id): Path<String>,
    RawQuery(raw_query): RawQuery,
) -> Result<Json<serde_json::Value>, ApiError> {
    let (auth_user, token) =
        require_user(&state.db, &headers, auth_query.api_key.as_deref()).await?;
    let user_context = plugin_user_context(&auth_user, &token);
    let query = parse_items_query(raw_query.as_deref());
    let requested_user_id = query
        .user_id
        .as_deref()
        .map(resolve_user_id)
        .transpose()?
        .unwrap_or(auth_user.id);
    ensure_user_access(&auth_user, requested_user_id)?;
    if item_id.eq_ignore_ascii_case("livetv") {
        return Ok(Json(live_tv_root_item_json(&state.db).await?));
    }
    if looks_like_live_tv_program_id(&item_id)
        && let Some(program) = live_tv_program_by_id(&state.db, &item_id).await?
    {
        return Ok(Json(program));
    }
    if parse_jellyfin_uuid(&item_id).is_err() {
        if let Some(channel) = live_tv_channel_json_by_id(&state.db, &item_id).await? {
            return Ok(Json(channel));
        }
        if let Some(program) = live_tv_program_by_id(&state.db, &item_id).await? {
            return Ok(Json(program));
        }
    }
    let requested_id = parse_jellyfin_uuid(&item_id)?;
    let server_id = state.db.server_state().await?.server_id.to_string();
    if let Some(view) = special_user_view_by_id(&item_id, &server_id) {
        return Ok(Json(view));
    }
    if let Some(tuner) = live_tv_tuner_view_by_id(&state.db, &item_id).await? {
        return Ok(Json(live_tv_tuner_view_to_json(&tuner, &server_id)));
    }
    if let Some(folder) = state
        .db
        .virtual_folders()
        .await?
        .into_iter()
        .find(|folder| folder.id == requested_id)
    {
        return Ok(Json(
            virtual_folder_detail_json(&state.db, &folder, &server_id).await?,
        ));
    }
    if let Ok(list) = state.db.media_list_by_id(requested_id).await {
        ensure_media_list_read_access(&state.db, &auth_user, &list).await?;
        let child_count = state.db.media_list_items(list.id).await?.len();
        return Ok(Json(media_list_to_json(&list, &server_id, child_count)));
    }
    if let Ok(mut item) = media_item_by_id(&state.db, &item_id).await {
        let playback = state
            .db
            .playback_state_for_item(requested_user_id, item.id)
            .await?;
        let mut metadata = metadata_payload_for_item(&state.db, item.id).await?;
        ensure_plugin_catalog_item_visible(&state.db, &metadata, &user_context).await?;
        // Android, Android TV and Jellyfin Web normally read the user-scoped detail route rather
        // than `/Items/{id}`. Keep its Xtream contract identical so episode detail pages receive
        // the real embedded audio/subtitle tracks instead of the two synthetic import streams.
        if is_xtream_remote_media(Some(&metadata)) {
            item = ensure_xtream_remote_media_info(&state, item, &mut metadata)
                .await?
                .item;
        }
        enrich_plugin_vod_item_metadata(&state, &mut item, &mut metadata).await;
        enrich_plugin_vod_item_media_streams(&state, &mut item, &metadata, user_context).await;
        return Ok(Json(media_item_to_json_with_playback_and_metadata(
            &item,
            &server_id,
            playback.as_ref(),
            Some(&metadata),
        )));
    }
    if let Some(channel) = live_tv_playback_channel_json_by_id(&state.db, &item_id).await? {
        return Ok(Json(channel));
    }
    if let Some(channel) = live_tv_channel_json_by_id(&state.db, &item_id).await? {
        return Ok(Json(channel));
    }
    if let Some((series_name, series_id, mut summary)) =
        tv_season_summary_by_id(&state.db, &item_id, Some(requested_user_id), false).await?
    {
        ensure_plugin_catalog_item_visible(&state.db, &summary.metadata, &user_context).await?;
        enrich_plugin_vod_virtual_metadata(&state, &item_id, true, &mut summary.metadata).await;
        return Ok(Json(tv_season_json(
            &server_id,
            &series_name,
            &series_id,
            summary,
        )));
    }
    if let Some(mut summary) =
        tv_series_summary_by_id(&state.db, &item_id, Some(requested_user_id)).await?
    {
        ensure_plugin_catalog_item_visible(&state.db, &summary.metadata, &user_context).await?;
        enrich_plugin_vod_virtual_metadata(&state, &item_id, false, &mut summary.metadata).await;
        return Ok(Json(tv_series_json(&server_id, summary)));
    }
    if let Some((series_name, series_id, mut summary)) =
        tv_season_summary_by_id(&state.db, &item_id, Some(requested_user_id), true).await?
    {
        ensure_plugin_catalog_item_visible(&state.db, &summary.metadata, &user_context).await?;
        enrich_plugin_vod_virtual_metadata(&state, &item_id, true, &mut summary.metadata).await;
        return Ok(Json(tv_season_json(
            &server_id,
            &series_name,
            &series_id,
            summary,
        )));
    }
    if let Some(entity) = metadata_entity_by_stable_id(&state.db, &item_id).await? {
        return Ok(Json(metadata_entity_match_json(&server_id, &entity)));
    }
    if let Some(program) = live_tv_program_by_id(&state.db, &item_id).await? {
        return Ok(Json(program));
    }

    Err(ApiError::not_found("Item not found"))
}

async fn user_item_detail(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    Path((user_id, item_id)): Path<(String, String)>,
) -> Result<Json<serde_json::Value>, ApiError> {
    let (auth_user, token) = require_user(&state.db, &headers, query.api_key.as_deref()).await?;
    let user_context = plugin_user_context(&auth_user, &token);
    let user_id = resolve_user_id(&user_id)?;
    ensure_user_access(&auth_user, user_id)?;
    if item_id.eq_ignore_ascii_case("livetv") {
        return Ok(Json(live_tv_root_item_json(&state.db).await?));
    }
    if looks_like_live_tv_program_id(&item_id)
        && let Some(program) = live_tv_program_by_id(&state.db, &item_id).await?
    {
        return Ok(Json(program));
    }
    if parse_jellyfin_uuid(&item_id).is_err() {
        if let Some(channel) = live_tv_channel_json_by_id(&state.db, &item_id).await? {
            return Ok(Json(channel));
        }
        if let Some(program) = live_tv_program_by_id(&state.db, &item_id).await? {
            return Ok(Json(program));
        }
    }
    let requested_id = parse_jellyfin_uuid(&item_id)?;
    let server_id = state.db.server_state().await?.server_id.to_string();
    if let Some(view) = special_user_view_by_id(&item_id, &server_id) {
        return Ok(Json(view));
    }
    if let Some(tuner) = live_tv_tuner_view_by_id(&state.db, &item_id).await? {
        return Ok(Json(live_tv_tuner_view_to_json(&tuner, &server_id)));
    }
    if let Some(folder) = state
        .db
        .virtual_folders()
        .await?
        .into_iter()
        .find(|folder| folder.id == requested_id)
    {
        return Ok(Json(
            virtual_folder_detail_json(&state.db, &folder, &server_id).await?,
        ));
    }
    if let Ok(list) = state.db.media_list_by_id(requested_id).await {
        ensure_media_list_read_access(&state.db, &auth_user, &list).await?;
        let child_count = state.db.media_list_items(list.id).await?.len();
        return Ok(Json(media_list_to_json(&list, &server_id, child_count)));
    }
    if let Ok(mut item) = media_item_by_id(&state.db, &item_id).await {
        let playback = state.db.playback_state_for_item(user_id, item.id).await?;
        let mut metadata = metadata_payload_for_item(&state.db, item.id).await?;
        ensure_plugin_catalog_item_visible(&state.db, &metadata, &user_context).await?;
        if is_xtream_remote_media(Some(&metadata)) {
            item = ensure_xtream_remote_media_info(&state, item, &mut metadata)
                .await?
                .item;
        }
        enrich_plugin_vod_item_metadata(&state, &mut item, &mut metadata).await;
        enrich_plugin_vod_item_media_streams(&state, &mut item, &metadata, user_context).await;
        return Ok(Json(media_item_to_json_with_playback_and_metadata(
            &item,
            &server_id,
            playback.as_ref(),
            Some(&metadata),
        )));
    }
    if let Some(channel) = live_tv_playback_channel_json_by_id(&state.db, &item_id).await? {
        return Ok(Json(channel));
    }
    if let Some(channel) = live_tv_channel_json_by_id(&state.db, &item_id).await? {
        return Ok(Json(channel));
    }
    if let Some((series_name, series_id, mut summary)) =
        tv_season_summary_by_id(&state.db, &item_id, Some(user_id), false).await?
    {
        ensure_plugin_catalog_item_visible(&state.db, &summary.metadata, &user_context).await?;
        enrich_plugin_vod_virtual_metadata(&state, &item_id, true, &mut summary.metadata).await;
        return Ok(Json(tv_season_json(
            &server_id,
            &series_name,
            &series_id,
            summary,
        )));
    }
    if let Some(mut summary) = tv_series_summary_by_id(&state.db, &item_id, Some(user_id)).await? {
        ensure_plugin_catalog_item_visible(&state.db, &summary.metadata, &user_context).await?;
        enrich_plugin_vod_virtual_metadata(&state, &item_id, false, &mut summary.metadata).await;
        return Ok(Json(tv_series_json(&server_id, summary)));
    }
    if let Some((series_name, series_id, mut summary)) =
        tv_season_summary_by_id(&state.db, &item_id, Some(user_id), true).await?
    {
        ensure_plugin_catalog_item_visible(&state.db, &summary.metadata, &user_context).await?;
        enrich_plugin_vod_virtual_metadata(&state, &item_id, true, &mut summary.metadata).await;
        return Ok(Json(tv_season_json(
            &server_id,
            &series_name,
            &series_id,
            summary,
        )));
    }
    if let Some(entity) = metadata_entity_by_stable_id(&state.db, &item_id).await? {
        return Ok(Json(metadata_entity_match_json(&server_id, &entity)));
    }
    if let Some(program) = live_tv_program_by_id(&state.db, &item_id).await? {
        return Ok(Json(program));
    }
    Err(ApiError::not_found("Item not found"))
}

async fn refresh_item(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    Path(item_id): Path<String>,
) -> Result<StatusCode, ApiError> {
    let user = require_admin(&state.db, &headers, query.api_key.as_deref()).await?;
    if let Some(series_name) = series_name_for_id(&state.db, &item_id).await? {
        refresh_tv_metadata_for_series(&state, &series_name).await?;
        state
            .db
            .add_activity_log_entry_with_item(
                "Item refreshed",
                Some(&format!("Series {series_name} metadata was refreshed.")),
                Some(&format!("Series {series_name} metadata was refreshed.")),
                "Library",
                Some(user.id),
                None,
            )
            .await?;
        return Ok(StatusCode::NO_CONTENT);
    }

    let item = media_item_by_id(&state.db, &item_id).await?;
    let scanned = LibraryService::new(&state.db)
        .scan_virtual_folder(item.virtual_folder_id)
        .await?;
    refresh_tv_metadata_for_folder(&state, item.virtual_folder_id).await?;
    state
        .db
        .add_activity_log_entry_with_item(
            "Item refreshed",
            Some(&format!(
                "Item {} was refreshed and {} media paths were scanned.",
                item.name, scanned
            )),
            Some(&format!("Item {} was refreshed.", item.name)),
            "Library",
            Some(user.id),
            Some(item.id),
        )
        .await?;
    Ok(StatusCode::NO_CONTENT)
}

async fn update_item_metadata(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    Path(item_id): Path<String>,
    body: Option<Json<serde_json::Value>>,
) -> Result<StatusCode, ApiError> {
    require_admin(&state.db, &headers, query.api_key.as_deref()).await?;
    if let Some(series_name) = series_name_for_id(&state.db, &item_id).await? {
        if let Some(Json(payload)) = body {
            apply_manual_series_metadata_update(&state, &series_name, payload).await?;
        }
        return Ok(StatusCode::NO_CONTENT);
    }
    let requested_id = parse_jellyfin_uuid(&item_id)?;
    if let Some(folder) = state
        .db
        .virtual_folders()
        .await?
        .into_iter()
        .find(|folder| folder.id == requested_id)
    {
        if let Some(Json(payload)) = body {
            update_virtual_folder_metadata(&state.db, folder, payload).await?;
        }
        return Ok(StatusCode::NO_CONTENT);
    }
    let item = media_item_by_id(&state.db, &item_id).await?;
    let mut metadata = metadata_payload_for_item(&state.db, item.id).await?;
    if let Some(Json(payload)) = body {
        merge_item_metadata_update(&mut metadata, payload)?;
    }
    state
        .db
        .update_media_item_metadata(item.id, metadata)
        .await?;
    Ok(StatusCode::NO_CONTENT)
}

async fn update_virtual_folder_metadata(
    db: &Database,
    folder: VirtualFolder,
    payload: serde_json::Value,
) -> Result<(), ApiError> {
    let requested_name = json_string_any_field(&payload, &["Name", "Title"])
        .map(|name| name.trim().to_string())
        .filter(|name| !name.is_empty());
    let final_name = requested_name.unwrap_or_else(|| folder.name.clone());
    if final_name != folder.name {
        LibraryService::new(db)
            .rename_virtual_folder(&folder.name, &final_name)
            .await?;
    }

    let content_type = json_string_any_field(
        &payload,
        &["ContentType", "CollectionType", "collectionType", "Type"],
    )
    .or(folder.collection_type);
    LibraryService::new(db)
        .upsert_virtual_folder(&final_name, content_type.as_deref(), folder.locations)
        .await?;
    Ok(())
}

#[derive(Debug, Deserialize)]
struct UpdateItemContentTypeQuery {
    #[serde(alias = "ContentType", alias = "contentType")]
    content_type: Option<String>,
}

async fn update_item_content_type(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    Query(query): Query<UpdateItemContentTypeQuery>,
    Path(item_id): Path<String>,
    body: Option<Json<serde_json::Value>>,
) -> Result<StatusCode, ApiError> {
    require_admin(&state.db, &headers, auth_query.api_key.as_deref()).await?;
    let content_type = query.content_type.or_else(|| {
        body.as_ref()
            .and_then(|Json(body)| json_string_field(body, "ContentType"))
    });
    let requested_id = parse_jellyfin_uuid(&item_id)?;
    if let Some(folder) = state
        .db
        .virtual_folders()
        .await?
        .into_iter()
        .find(|folder| folder.id == requested_id)
    {
        if let Some(content_type) = content_type.as_deref() {
            state
                .db
                .upsert_virtual_folder(&folder.name, Some(content_type), folder.locations)
                .await?;
        }
        return Ok(StatusCode::NO_CONTENT);
    }
    if let Some(series_name) = series_name_for_id(&state.db, &item_id).await? {
        if let Some(content_type) = content_type {
            apply_manual_series_metadata_update(
                &state,
                &series_name,
                serde_json::json!({ "ContentType": content_type }),
            )
            .await?;
        }
        return Ok(StatusCode::NO_CONTENT);
    }
    let item = media_item_by_id(&state.db, &item_id).await?;
    let mut metadata = metadata_payload_for_item(&state.db, item.id).await?;
    if let Some(content_type) = content_type {
        metadata["ContentType"] = serde_json::Value::String(content_type);
    }
    state
        .db
        .update_media_item_metadata(item.id, metadata)
        .await?;
    Ok(StatusCode::NO_CONTENT)
}

async fn item_metadata_editor(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    Path(item_id): Path<String>,
) -> Result<Json<serde_json::Value>, ApiError> {
    require_admin(&state.db, &headers, query.api_key.as_deref()).await?;
    let requested_id = parse_jellyfin_uuid(&item_id)?;
    let server_id = state.db.server_state().await?.server_id.to_string();
    if let Some(folder) = state
        .db
        .virtual_folders()
        .await?
        .into_iter()
        .find(|folder| folder.id == requested_id)
    {
        return Ok(Json(serde_json::json!({
            "Item": user_view_to_json(&folder, &server_id),
            "Metadata": {
                "Name": folder.name,
                "Path": folder.locations.first().cloned().unwrap_or_default(),
                "ContentType": folder.collection_type
            },
            "ExternalIdInfos": [],
            "ParentalRatingOptions": metadata_editor_parental_rating_options(),
            "ContentType": folder.collection_type,
            "ContentTypeOptions": metadata_editor_content_type_options(),
            "Cultures": load_cultures(),
            "Countries": load_countries()
        })));
    }
    if let Ok(list) = state.db.media_list_by_id(requested_id).await {
        let child_count = state.db.media_list_items(list.id).await?.len();
        let item = media_list_to_json(&list, &server_id, child_count);
        let content_type = list
            .collection_type
            .clone()
            .unwrap_or_else(|| list.kind.clone());
        return Ok(Json(serde_json::json!({
            "Item": item,
            "Metadata": {
                "Name": list.name,
                "ContentType": content_type
            },
            "ExternalIdInfos": external_id_infos_for_item_type(if list.kind == "collection" { "BoxSet" } else { "Playlist" }),
            "ParentalRatingOptions": metadata_editor_parental_rating_options(),
            "ContentType": content_type,
            "ContentTypeOptions": metadata_editor_content_type_options(),
            "Cultures": load_cultures(),
            "Countries": load_countries()
        })));
    }
    if let Some(summary) = tv_series_summary_by_id(&state.db, &item_id, None).await? {
        let item = tv_series_json(&server_id, summary);
        let content_type =
            json_string_field(&item, "ContentType").unwrap_or_else(|| "tvshows".to_string());
        return Ok(Json(serde_json::json!({
            "Item": item,
            "Metadata": item,
            "ExternalIdInfos": external_id_infos_for_item_type("Series"),
            "ParentalRatingOptions": metadata_editor_parental_rating_options(),
            "ContentType": content_type,
            "ContentTypeOptions": metadata_editor_content_type_options(),
            "Cultures": load_cultures(),
            "Countries": load_countries()
        })));
    }
    if let Some((series_name, series_id, summary)) =
        tv_season_summary_by_id(&state.db, &item_id, None, true).await?
    {
        let item = tv_season_json(&server_id, &series_name, &series_id, summary);
        return Ok(Json(serde_json::json!({
            "Item": item,
            "Metadata": item,
            "ExternalIdInfos": external_id_infos_for_item_type("Season"),
            "ParentalRatingOptions": metadata_editor_parental_rating_options(),
            "ContentType": "tvshows",
            "ContentTypeOptions": metadata_editor_content_type_options(),
            "Cultures": load_cultures(),
            "Countries": load_countries()
        })));
    }
    let item = media_item_by_id(&state.db, &item_id).await?;
    let metadata = metadata_payload_for_item(&state.db, item.id).await?;
    Ok(Json(serde_json::json!({
        "Item": media_item_to_json_with_playback_and_metadata(&item, &server_id, None, Some(&metadata)),
        "Metadata": metadata,
        "ExternalIdInfos": external_id_infos_for_item_type(media_item_type(&item)),
        "ParentalRatingOptions": metadata_editor_parental_rating_options(),
        "ContentType": item.collection_type,
        "ContentTypeOptions": metadata_editor_content_type_options(),
        "Cultures": load_cultures(),
        "Countries": load_countries()
    })))
}

async fn apply_manual_series_metadata_update(
    state: &AppState,
    series_name: &str,
    payload: serde_json::Value,
) -> Result<(), ApiError> {
    let series_metadata = series_metadata_from_item_update_payload(&payload);
    let TvEpisodeCatalogSnapshot {
        items,
        metadata_by_item,
    } = tv_episode_catalog_snapshot(&state.db).await?;
    let episodes = items
        .into_iter()
        .filter(|item| tv_episode_info(item).is_some_and(|info| info.series_name == series_name))
        .collect::<Vec<_>>();
    for episode in episodes {
        let mut metadata = metadata_by_item
            .get(&episode.id)
            .cloned()
            .unwrap_or_else(|| serde_json::json!({}));
        merge_tvmaze_series_metadata(&mut metadata, &series_metadata);
        state
            .db
            .update_media_item_metadata(episode.id, metadata)
            .await?;
    }
    Ok(())
}

fn series_metadata_from_item_update_payload(payload: &serde_json::Value) -> serde_json::Value {
    let provider_ids = json_field_case_insensitive(payload, "ProviderIds")
        .filter(|value| value.is_object())
        .cloned();
    serde_json::json!({
        "SeriesName": json_string_field(payload, "Name"),
        "SeriesOverview": json_string_field(payload, "Overview"),
        "SeriesOriginalTitle": json_string_field(payload, "OriginalTitle"),
        "SeriesOfficialRating": json_string_field(payload, "OfficialRating"),
        "SeriesStatus": json_string_field(payload, "Status"),
        "SeriesGenres": json_field_case_insensitive(payload, "Genres").cloned(),
        "SeriesStudios": json_field_case_insensitive(payload, "Studios").cloned(),
        "SeriesTags": json_field_case_insensitive(payload, "Tags").cloned(),
        "SeriesTaglines": json_field_case_insensitive(payload, "Taglines").cloned(),
        "SeriesAirDays": json_field_case_insensitive(payload, "AirDays").cloned(),
        "SeriesPeople": json_field_case_insensitive(payload, "People").cloned(),
        "SeriesProviderIds": provider_ids,
        "SeriesContentType": json_string_field(payload, "ContentType"),
        "SeriesProductionYear": json_i64_field(payload, "ProductionYear"),
        "SeriesPremiereDate": json_string_field(payload, "PremiereDate"),
        "EndDate": json_string_field(payload, "EndDate"),
        "SeriesCommunityRating": json_f64_field(payload, "CommunityRating"),
        "SeriesCriticRating": json_f64_field(payload, "CriticRating"),
        "PreferredMetadataLanguage": json_string_field(payload, "PreferredMetadataLanguage"),
        "PreferredMetadataCountryCode": json_string_field(payload, "PreferredMetadataCountryCode"),
        "LockData": json_field_case_insensitive(payload, "LockData").cloned(),
        "LockedFields": json_field_case_insensitive(payload, "LockedFields").cloned(),
    })
}

