async fn item_external_id_infos(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    Path(item_id): Path<String>,
) -> Result<Json<Vec<serde_json::Value>>, ApiError> {
    require_admin(&state.db, &headers, query.api_key.as_deref()).await?;
    if series_name_for_id(&state.db, &item_id).await?.is_some() {
        return Ok(Json(external_id_infos_for_item_type("Series")));
    }
    if tv_season_summary_by_id(&state.db, &item_id, None, true)
        .await?
        .is_some()
    {
        return Ok(Json(external_id_infos_for_item_type("Season")));
    }
    let requested_id = parse_jellyfin_uuid(&item_id)?;
    if let Ok(list) = state.db.media_list_by_id(requested_id).await {
        return Ok(Json(external_id_infos_for_item_type(
            if list.kind == "collection" {
                "BoxSet"
            } else {
                "Playlist"
            },
        )));
    }
    if state
        .db
        .virtual_folders()
        .await?
        .iter()
        .any(|folder| folder.id == requested_id)
    {
        return Ok(Json(external_id_infos_for_item_type("Folder")));
    }
    let item = media_item_by_id(&state.db, &item_id).await?;
    Ok(Json(external_id_infos_for_item_type(media_item_type(
        &item,
    ))))
}

async fn apply_remote_item_search(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    Path(item_id): Path<String>,
    body: Option<Json<serde_json::Value>>,
) -> Result<StatusCode, ApiError> {
    require_admin(&state.db, &headers, query.api_key.as_deref()).await?;
    let Some(Json(payload)) = body else {
        return Err(ApiError::not_found("Remote search result not found"));
    };
    if let Some(series_name) = series_name_for_id(&state.db, &item_id).await? {
        let payload = enrich_remote_search_result_from_builtin(&state.db, "Series", payload).await;
        apply_remote_series_search_result(&state, &series_name, payload).await?;
        return Ok(StatusCode::NO_CONTENT);
    }

    let item = media_item_by_id(&state.db, &item_id).await?;
    let payload =
        enrich_remote_search_result_from_builtin(&state.db, media_item_type(&item), payload).await;
    let mut metadata = metadata_payload_for_item(&state.db, item.id).await?;
    merge_remote_search_result_metadata(&mut metadata, payload)?;
    state
        .db
        .update_media_item_metadata(item.id, metadata)
        .await?;
    Ok(StatusCode::NO_CONTENT)
}

async fn enrich_remote_search_result_from_builtin(
    db: &Database,
    item_type: &str,
    payload: serde_json::Value,
) -> serde_json::Value {
    let candidate = remote_search_candidate_payload(payload);
    let tmdb_id = json_field_case_insensitive(&candidate, "ProviderIds")
        .and_then(|ids| json_string_any_field(ids, &["Tmdb", "TMDb", "TheMovieDb"]));
    let Some(tmdb_id) = tmdb_id else {
        return candidate;
    };
    let configuration = match db
        .named_configuration(builtin_metadata::CONFIGURATION_KEY)
        .await
    {
        Ok(configuration) => configuration.unwrap_or_else(builtin_metadata::default_configuration),
        Err(error) => {
            tracing::warn!(%error, "metadata provider configuration was unavailable during apply");
            return candidate;
        }
    };
    if !builtin_metadata::provider_is_ready(
        &configuration,
        "tmdb",
        builtin_metadata::ProviderSecretAvailability::from_environment(),
    ) {
        return candidate;
    }
    let provider_configuration = builtin_metadata::provider_configuration(&configuration, "tmdb")
        .unwrap_or_else(|| serde_json::json!({}));
    match tmdb::details(item_type, &tmdb_id, &provider_configuration).await {
        Ok(Some(details)) => {
            let mut enriched = candidate;
            if let Err(error) = merge_item_metadata_update(&mut enriched, details) {
                tracing::warn!(status = %error.status, "TheMovieDb details could not be merged");
            }
            enriched
        }
        Ok(None) => candidate,
        Err(error) => {
            tracing::warn!(
                status = %error.status,
                "TheMovieDb details were unavailable during apply"
            );
            candidate
        }
    }
}

async fn apply_remote_series_search_result(
    state: &AppState,
    series_name: &str,
    payload: serde_json::Value,
) -> Result<(), ApiError> {
    let candidate = remote_search_candidate_payload(payload);
    let series_metadata = series_metadata_from_remote_search_result(&candidate);
    let TvEpisodeCatalogSnapshot {
        items,
        metadata_by_item,
    } = tv_episode_catalog_snapshot(&state.db).await?;
    let episodes = items
        .into_iter()
        .filter(|item| tv_episode_info(item).is_some_and(|info| info.series_name == series_name))
        .collect::<Vec<_>>();
    for episode in episodes {
        let mut metadata = metadata_by_item
            .get(&episode.id)
            .cloned()
            .unwrap_or_else(|| serde_json::json!({}));
        merge_tvmaze_series_metadata(&mut metadata, &series_metadata);
        state
            .db
            .update_media_item_metadata(episode.id, metadata)
            .await?;
    }
    if let Some(image_url) = json_string_field(&candidate, "ImageUrl")
        && let Ok(bytes) = fetch_remote_image_bytes(&image_url).await
    {
        store_image_bytes(
            state,
            ImageOwner::Item(&tv_series_id(series_name)),
            "Primary",
            0,
            bytes,
        )
        .await?;
    }
    Ok(())
}

fn series_metadata_from_remote_search_result(candidate: &serde_json::Value) -> serde_json::Value {
    let provider_ids = json_field_case_insensitive(candidate, "ProviderIds")
        .filter(|value| value.is_object())
        .cloned()
        .unwrap_or_else(|| serde_json::json!({}));
    let primary_tag = provider_ids
        .get("TvMaze")
        .and_then(serde_json::Value::as_str)
        .map(|id| format!("tvmaze-primary-{id}"))
        .or_else(|| {
            json_string_field(candidate, "ImageUrl")
                .map(|url| format!("remote-primary-{}", stable_entity_id("RemoteImage", &url)))
        });
    let backdrop_tag = json_string_field(candidate, "BackdropImageUrl")
        .map(|url| format!("remote-backdrop-{}", stable_entity_id("RemoteImage", &url)));
    serde_json::json!({
        "SeriesName": json_string_field(candidate, "Name"),
        "SeriesOverview": json_string_field(candidate, "Overview"),
        "SeriesOriginalTitle": json_string_field(candidate, "OriginalTitle"),
        "SeriesOfficialRating": json_string_field(candidate, "OfficialRating"),
        "SeriesStatus": json_string_field(candidate, "Status"),
        "SeriesGenres": json_field_case_insensitive(candidate, "Genres").cloned(),
        "SeriesStudios": json_field_case_insensitive(candidate, "Studios").cloned(),
        "SeriesTags": json_field_case_insensitive(candidate, "Tags").cloned(),
        "SeriesTaglines": json_field_case_insensitive(candidate, "Taglines").cloned(),
        "SeriesPeople": json_field_case_insensitive(candidate, "People").cloned(),
        "SeriesProviderIds": provider_ids,
        "SeriesProductionYear": json_i64_field(candidate, "ProductionYear"),
        "SeriesPremiereDate": json_string_field(candidate, "PremiereDate"),
        "EndDate": json_string_field(candidate, "EndDate"),
        "SeriesCommunityRating": json_f64_field(candidate, "CommunityRating"),
        "SeriesCriticRating": json_f64_field(candidate, "CriticRating"),
        "SeriesPrimaryImageTag": primary_tag,
        "SeriesBackdropImageTag": backdrop_tag,
        "SeriesPrimaryImageUrl": json_string_field(candidate, "PrimaryImageUrl").or_else(|| json_string_field(candidate, "ImageUrl")),
        "SeriesBackdropImageUrl": json_string_field(candidate, "BackdropImageUrl"),
        "MetadataSource": json_string_field(candidate, "SearchProviderName").unwrap_or_else(|| "RemoteSearch".to_string())
    })
}

macro_rules! remote_search_handler {
    ($name:ident, $item_type:literal, $admin_only:literal) => {
        async fn $name(
            State(state): State<AppState>,
            headers: HeaderMap,
            Query(query): Query<AuthQuery>,
            body: Option<Json<serde_json::Value>>,
        ) -> Result<Json<Vec<serde_json::Value>>, ApiError> {
            if $admin_only {
                require_admin(&state.db, &headers, query.api_key.as_deref()).await?;
            } else {
                require_request_user(&state.db, &headers, query.api_key.as_deref()).await?;
            }
            remote_search_local_results(&state.db, $item_type, body.map(|Json(value)| value))
                .await
                .map(Json)
        }
    };
}

remote_search_handler!(remote_search_book, "Book", false);
remote_search_handler!(remote_search_box_set, "BoxSet", false);
remote_search_handler!(remote_search_movie, "Movie", false);
remote_search_handler!(remote_search_music_album, "MusicAlbum", false);
remote_search_handler!(remote_search_music_artist, "MusicArtist", false);
remote_search_handler!(remote_search_music_video, "MusicVideo", false);
remote_search_handler!(remote_search_person, "Person", true);
remote_search_handler!(remote_search_series, "Series", false);
remote_search_handler!(remote_search_trailer, "Trailer", false);

async fn remote_search_local_results(
    db: &Database,
    item_type: &str,
    payload: Option<serde_json::Value>,
) -> Result<Vec<serde_json::Value>, ApiError> {
    let request = RemoteSearchRequest::from_payload(payload.as_ref());
    let server_id = db.server_state().await?.server_id.to_string();
    let mut results = BTreeMap::<String, serde_json::Value>::new();

    match item_type {
        "Movie" | "MusicVideo" | "Book" => {
            let (items, metadata_by_item) =
                media_items_and_metadata_by_effective_types(db, &[item_type.to_string()]).await?;
            for item in items
                .iter()
                .filter(|item| media_item_type(item) == item_type)
            {
                let metadata = metadata_by_item.get(&item.id);
                if !request.matches_media_item(item, metadata) {
                    continue;
                }
                let result = remote_search_result_from_media_item(item, metadata);
                results.insert(remote_search_result_key(item_type, &item.name), result);
            }
        }
        "Series" => {
            let (items, _) =
                media_items_and_metadata_by_effective_types(db, &["Episode".to_string()]).await?;
            for item in items
                .iter()
                .filter(|item| media_item_type(item) == "Episode")
            {
                let Some(series) = tv_episode_info(item).map(|info| info.series_name) else {
                    continue;
                };
                if !request.matches_name(&series) {
                    continue;
                }
                results
                    .entry(remote_search_result_key(item_type, &series))
                    .or_insert_with(|| {
                        remote_search_result_from_name(&server_id, &series, item_type, None)
                    });
            }
            if let Ok(tvmaze_results) = tvmaze_remote_search_series_results(&request).await {
                for result in tvmaze_results {
                    let name = result
                        .get("Name")
                        .and_then(serde_json::Value::as_str)
                        .unwrap_or_default();
                    let provider_id = result
                        .get("ProviderIds")
                        .and_then(|ids| ids.get("TvMaze"))
                        .and_then(serde_json::Value::as_str)
                        .unwrap_or_default();
                    results.insert(
                        remote_search_result_key(
                            item_type,
                            &format!("TVMaze:{provider_id}:{name}"),
                        ),
                        result,
                    );
                }
            }
        }
        "MusicAlbum" => {
            let (items, metadata_by_item) =
                media_items_and_metadata_by_effective_types(db, &all_effective_media_item_types())
                    .await?;
            collect_remote_search_metadata_entities(
                &server_id,
                item_type,
                &["Album", "AlbumName", "Albums"],
                &items,
                &metadata_by_item,
                &request,
                &mut results,
            );
        }
        "MusicArtist" => {
            let (items, metadata_by_item) =
                media_items_and_metadata_by_effective_types(db, &all_effective_media_item_types())
                    .await?;
            collect_remote_search_metadata_entities(
                &server_id,
                item_type,
                &["Artists", "AlbumArtists", "ArtistItems"],
                &items,
                &metadata_by_item,
                &request,
                &mut results,
            );
        }
        "Person" => {
            let (items, metadata_by_item) =
                media_items_and_metadata_by_effective_types(db, &all_effective_media_item_types())
                    .await?;
            collect_remote_search_metadata_entities(
                &server_id,
                item_type,
                &["People", "Cast"],
                &items,
                &metadata_by_item,
                &request,
                &mut results,
            );
        }
        "Trailer" => {
            let (items, metadata_by_item) =
                media_items_and_metadata_by_effective_types(db, &all_effective_media_item_types())
                    .await?;
            for item in &items {
                let Some(metadata) = metadata_by_item.get(&item.id) else {
                    continue;
                };
                for trailer in metadata_remote_trailers(metadata, item, &server_id) {
                    let name = trailer["Name"].as_str().unwrap_or_default();
                    if !request.matches_name(name) {
                        continue;
                    }
                    let mut result =
                        remote_search_result_from_name(&server_id, name, item_type, None);
                    result["RemoteTrailers"] = trailer["RemoteTrailers"].clone();
                    result["ProviderIds"] = serde_json::json!({
                        "JellyrinLocal": trailer["Id"].clone()
                    });
                    results.insert(remote_search_result_key(item_type, name), result);
                }
            }
        }
        "BoxSet" => {
            for collection in db.media_lists("collection").await? {
                if !request.matches_name(&collection.name) {
                    continue;
                }
                let mut result =
                    remote_search_result_from_name(&server_id, &collection.name, item_type, None);
                result["ProviderIds"] = serde_json::json!({
                    "JellyrinLocal": collection.id.simple().to_string()
                });
                result["ItemId"] = serde_json::json!(collection.id.simple().to_string());
                results.insert(
                    remote_search_result_key(item_type, &collection.name),
                    result,
                );
            }
        }
        _ => {}
    }

    let builtin_configuration = db
        .named_configuration(builtin_metadata::CONFIGURATION_KEY)
        .await?
        .unwrap_or_else(builtin_metadata::default_configuration);
    let provider_policy = metadata_provider_policy(db, item_type, false).await?;
    let plugins = db.installed_plugins_json().await?;
    let mut provider_priorities = HashMap::new();
    for provider in builtin_metadata::registry_entries(
        &builtin_configuration,
        builtin_metadata::ProviderSecretAvailability::from_environment(),
    ) {
        if let Some(name) = json_string_field(&provider, "Name") {
            provider_priorities.insert(
                name.to_ascii_lowercase(),
                json_i64_field(&provider, "Priority").unwrap_or(1_000),
            );
        }
    }
    for plugin in &plugins {
        if let Some(name) = json_string_field(plugin, "Name") {
            provider_priorities.insert(
                name.to_ascii_lowercase(),
                json_i64_field(plugin, "Priority").unwrap_or(1_000),
            );
        }
    }
    let mut ordered_results = results.into_values().collect::<Vec<_>>();
    let mut provider_results = builtin_metadata_provider_remote_search_results(
        &builtin_configuration,
        &provider_policy,
        item_type,
        &request,
    )
    .await;
    provider_results.extend(
        plugin_metadata_provider_remote_search_results(
            db,
            &plugins,
            &provider_policy,
            item_type,
            &request,
        )
        .await?,
    );
    provider_results.sort_by(|left, right| {
        let left_name = json_string_field(left, "SearchProviderName").unwrap_or_default();
        let right_name = json_string_field(right, "SearchProviderName").unwrap_or_default();
        let left_priority = provider_priorities
            .get(&left_name.to_ascii_lowercase())
            .copied()
            .unwrap_or(1_000);
        let right_priority = provider_priorities
            .get(&right_name.to_ascii_lowercase())
            .copied()
            .unwrap_or(1_000);
        provider_policy.compare(&left_name, left_priority, &right_name, right_priority)
    });
    ordered_results.extend(provider_results);
    Ok(ordered_results)
}

async fn metadata_provider_policy(
    db: &Database,
    item_type: &str,
    image_provider: bool,
) -> Result<builtin_metadata::ProviderPolicy, ApiError> {
    let metadata_options =
        metadata_options_or_default(db.system_configuration_payloads().await?.metadata_options);
    Ok(builtin_metadata::ProviderPolicy::for_item_type(
        &metadata_options,
        item_type,
        image_provider,
    ))
}

async fn builtin_metadata_provider_remote_search_results(
    configuration: &serde_json::Value,
    policy: &builtin_metadata::ProviderPolicy,
    item_type: &str,
    request: &RemoteSearchRequest,
) -> Vec<serde_json::Value> {
    let secrets = builtin_metadata::ProviderSecretAvailability::from_environment();
    let mut providers = builtin_metadata::registry_entries(configuration, secrets)
        .into_iter()
        .filter(|provider| {
            let provider_id = json_string_field(provider, "Id").unwrap_or_default();
            let provider_name = json_string_field(provider, "Name").unwrap_or_default();
            provider["Ready"].as_bool() == Some(true)
                && policy.allows(&provider_id, &provider_name)
                && plugin_string_array(provider.get("Capabilities"))
                    .iter()
                    .any(|capability| capability.eq_ignore_ascii_case("MetadataProvider"))
                && plugin_string_array(provider.get("ItemTypes"))
                    .iter()
                    .any(|supported| supported.eq_ignore_ascii_case(item_type))
        })
        .collect::<Vec<_>>();
    providers.sort_by(|left, right| {
        policy.compare(
            &json_string_field(left, "Name").unwrap_or_default(),
            json_i64_field(left, "Priority").unwrap_or(1_000),
            &json_string_field(right, "Name").unwrap_or_default(),
            json_i64_field(right, "Priority").unwrap_or(1_000),
        )
    });

    let mut results = Vec::new();
    for provider in providers {
        let provider_id = json_string_field(&provider, "Id").unwrap_or_default();
        let provider_configuration =
            builtin_metadata::provider_configuration(configuration, &provider_id)
                .unwrap_or_else(|| serde_json::json!({}));
        let response = match provider_id.as_str() {
            "tmdb" => {
                tmdb::remote_search(
                    item_type,
                    request.name.as_deref(),
                    request.year,
                    &provider_configuration,
                )
                .await
            }
            "omdb" => {
                omdb::remote_search(
                    item_type,
                    request.name.as_deref(),
                    request.year,
                    &provider_configuration,
                )
                .await
            }
            "musicbrainz" => {
                musicbrainz::remote_search(
                    item_type,
                    request.name.as_deref(),
                    request.year,
                    &provider_configuration,
                )
                .await
            }
            _ => continue,
        };
        match response {
            Ok(provider_results) => results.extend(provider_results),
            Err(error) => tracing::warn!(
                provider = %provider_id,
                status = %error.status,
                "built-in metadata provider search was unavailable"
            ),
        }
    }
    results
}

fn all_effective_media_item_types() -> Vec<String> {
    [
        "Movie",
        "Episode",
        "MusicVideo",
        "Video",
        "Audio",
        "Photo",
        "Book",
        "BaseItem",
    ]
    .into_iter()
    .map(str::to_string)
    .collect()
}

async fn media_items_and_metadata_by_effective_types(
    db: &Database,
    item_types: &[String],
) -> Result<(Vec<MediaItem>, HashMap<Uuid, serde_json::Value>), ApiError> {
    let entries =
        MediaCatalogStore::media_items_with_metadata_by_effective_types(db, item_types).await?;
    let mut items = Vec::with_capacity(entries.len());
    let mut metadata_by_item = HashMap::with_capacity(entries.len());
    for entry in entries {
        metadata_by_item.insert(entry.item.id, entry.metadata);
        items.push(entry.item);
    }
    Ok((items, metadata_by_item))
}

async fn plugin_metadata_provider_remote_search_results(
    db: &Database,
    plugins: &[serde_json::Value],
    policy: &builtin_metadata::ProviderPolicy,
    item_type: &str,
    request: &RemoteSearchRequest,
) -> Result<Vec<serde_json::Value>, ApiError> {
    let mut results = Vec::new();
    let mut plugins = plugins.to_vec();
    plugins.sort_by(|left, right| {
        policy.compare(
            &json_string_field(left, "Name").unwrap_or_default(),
            json_i64_field(left, "Priority").unwrap_or(1_000),
            &json_string_field(right, "Name").unwrap_or_default(),
            json_i64_field(right, "Priority").unwrap_or(1_000),
        )
    });
    for plugin in plugins {
        if !plugin_is_active_metadata_provider(&plugin) {
            continue;
        }
        let provider_id = json_string_field(&plugin, "Id").unwrap_or_default();
        let provider_name = json_string_field(&plugin, "Name").unwrap_or_else(|| {
            if provider_id.is_empty() {
                "Plugin Metadata".to_string()
            } else {
                provider_id.clone()
            }
        });
        if !policy.allows(&provider_id, &provider_name) {
            continue;
        }
        let capability = invoke_installed_plugin_capability_via_runtime_host(
            db,
            &plugin,
            "MetadataProvider",
            serde_json::json!({
                "ItemType": item_type,
                "SearchInfo": {
                    "Name": request.name,
                    "Year": request.year
                }
            }),
        )
        .await;
        let capability = match capability {
            Ok(capability) => capability,
            Err(error) => {
                tracing::warn!(
                    plugin = %json_string_field(&plugin, "Id").unwrap_or_default(),
                    status = %error.status,
                    "external metadata provider search was unavailable"
                );
                continue;
            }
        };
        let Some(capability) = capability else {
            continue;
        };
        results.extend(plugin_metadata_provider_result_values(
            item_type,
            &provider_name,
            &capability.value,
        ));
    }
    Ok(results)
}

fn plugin_is_active_metadata_provider(plugin: &serde_json::Value) -> bool {
    json_string_field(plugin, "Status").as_deref() == Some("Active")
        && plugin_string_array(plugin.get("Capabilities"))
            .iter()
            .any(|capability| capability.eq_ignore_ascii_case("MetadataProvider"))
}

/// Enrich a media item's metadata by querying active MetadataProvider plugins.
/// Returns merged metadata JSON if any plugin provides enrichment, or None if no plugin matched.
pub async fn enrich_metadata_from_plugins(
    db: &Database,
    item_name: &str,
    item_type: &str,
    existing_metadata: &serde_json::Value,
) -> Option<serde_json::Value> {
    let policy = metadata_provider_policy(db, item_type, false).await.ok()?;
    let mut plugins = db.installed_plugins_json().await.ok()?;
    plugins.sort_by(|left, right| {
        policy.compare(
            &json_string_field(left, "Name").unwrap_or_default(),
            json_i64_field(left, "Priority").unwrap_or(1_000),
            &json_string_field(right, "Name").unwrap_or_default(),
            json_i64_field(right, "Priority").unwrap_or(1_000),
        )
    });
    for plugin in plugins {
        if !plugin_is_active_metadata_provider(&plugin) {
            continue;
        }
        let provider_id = json_string_field(&plugin, "Id").unwrap_or_default();
        let provider_name = json_string_field(&plugin, "Name").unwrap_or_else(|| {
            if provider_id.is_empty() {
                "Plugin Metadata".to_string()
            } else {
                provider_id.clone()
            }
        });
        if !policy.allows(&provider_id, &provider_name) {
            continue;
        }
        let request = serde_json::json!({
            "ItemType": item_type,
            "SearchInfo": {
                "Name": item_name,
                "Year": existing_metadata.get("ProductionYear")
            }
        });
        let Some(capability) = invoke_installed_plugin_capability_via_runtime_host(
            db,
            &plugin,
            "MetadataProvider",
            request,
        )
        .await
        .ok()
        .flatten() else {
            continue;
        };
        let values = capability
            .value
            .get("Items")
            .or_else(|| capability.value.get("Results"))
            .and_then(serde_json::Value::as_array)
            .cloned()
            .unwrap_or_else(|| vec![capability.value.clone()]);
        // Use the first result that has a name matching or any result if no exact match
        for value in values {
            let plugin_name = json_string_field(&value, "Name").unwrap_or_default();
            if plugin_name.is_empty() {
                continue;
            }
            // Merge plugin metadata into existing
            let mut merged = existing_metadata.clone();
            if let Some(overview) =
                json_string_field(&value, "Overview").or_else(|| json_string_field(&value, "Plot"))
                && (existing_metadata.get("Overview").is_none()
                    || existing_metadata
                        .get("Overview")
                        .and_then(|v| v.as_str())
                        .is_some_and(|s| s.is_empty()))
            {
                merged["Overview"] = serde_json::json!(overview);
            }
            if let Some(year) = value
                .get("ProductionYear")
                .or_else(|| value.get("Year"))
                .and_then(|v| v.as_i64())
                && existing_metadata.get("ProductionYear").is_none()
            {
                merged["ProductionYear"] = serde_json::json!(year);
            }
            if let Some(rating) = value.get("CommunityRating").and_then(|v| v.as_f64())
                && existing_metadata.get("CommunityRating").is_none()
            {
                merged["CommunityRating"] = serde_json::json!(rating);
            }
            if let Some(genres) = value.get("Genres").and_then(|v| v.as_array())
                && !genres.is_empty()
                && (existing_metadata.get("Genres").is_none()
                    || existing_metadata
                        .get("Genres")
                        .and_then(|v| v.as_array())
                        .is_some_and(|a| a.is_empty()))
            {
                merged["Genres"] = serde_json::json!(genres);
            }
            if let Some(image_url) = json_string_field(&value, "ImageUrl")
                .or_else(|| json_string_field(&value, "PrimaryImageUrl"))
                && existing_metadata.get("PrimaryImageUrl").is_none()
            {
                merged["PrimaryImageUrl"] = serde_json::json!(image_url);
                merged["ImageUrl"] = serde_json::json!(image_url);
            }
            if let Some(provider_ids) = value.get("ProviderIds")
                && provider_ids.is_object()
            {
                let mut existing_ids = existing_metadata
                    .get("ProviderIds")
                    .and_then(|v| v.as_object())
                    .cloned()
                    .unwrap_or_default();
                if let Some(obj) = provider_ids.as_object() {
                    for (k, v) in obj {
                        existing_ids.insert(k.clone(), v.clone());
                    }
                }
                merged["ProviderIds"] = serde_json::json!(existing_ids);
            }
            // Track which plugin provided the enrichment
            merged["MetadataProviderPlugin"] = serde_json::json!(provider_id);
            return Some(merged);
        }
    }
    None
}

fn plugin_metadata_provider_result_values(
    item_type: &str,
    provider_name: &str,
    value: &serde_json::Value,
) -> Vec<serde_json::Value> {
    let values = value
        .get("Items")
        .or_else(|| value.get("Results"))
        .and_then(serde_json::Value::as_array)
        .cloned()
        .unwrap_or_else(|| vec![value.clone()]);
    values
        .iter()
        .filter_map(|value| plugin_metadata_provider_result_value(item_type, provider_name, value))
        .collect()
}

fn plugin_metadata_provider_result_value(
    item_type: &str,
    provider_name: &str,
    value: &serde_json::Value,
) -> Option<serde_json::Value> {
    let name = json_string_field(value, "Name")?;
    let provider_ids = value
        .get("ProviderIds")
        .cloned()
        .filter(serde_json::Value::is_object)
        .unwrap_or_else(|| {
            serde_json::json!({
                provider_name: stable_entity_id(item_type, &name)
            })
        });
    Some(serde_json::json!({
        "Name": name,
        "ProviderIds": provider_ids,
        "ProductionYear": json_i64_field(value, "ProductionYear").or_else(|| json_i64_field(value, "Year")),
        "IndexNumber": value.get("IndexNumber").cloned().unwrap_or(serde_json::Value::Null),
        "IndexNumberEnd": value.get("IndexNumberEnd").cloned().unwrap_or(serde_json::Value::Null),
        "ParentIndexNumber": value.get("ParentIndexNumber").cloned().unwrap_or(serde_json::Value::Null),
        "PremiereDate": value.get("PremiereDate").cloned().unwrap_or(serde_json::Value::Null),
        "ImageUrl": value.get("ImageUrl").cloned().unwrap_or(serde_json::Value::Null),
        "SearchProviderName": provider_name,
        "Overview": json_string_field(value, "Overview").unwrap_or_default(),
        "Type": json_string_field(value, "Type").unwrap_or_else(|| item_type.to_string())
    }))
}

#[derive(Default)]
struct RemoteSearchRequest {
    name: Option<String>,
    year: Option<i32>,
}

impl RemoteSearchRequest {
    fn from_payload(payload: Option<&serde_json::Value>) -> Self {
        let Some(payload) = payload else {
            return Self::default();
        };
        let search_info = json_field_case_insensitive(payload, "SearchInfo");
        Self {
            name: json_string_field(payload, "Name")
                .or_else(|| json_string_field(payload, "SearchTerm"))
                .or_else(|| search_info.and_then(|value| json_string_field(value, "Name")))
                .or_else(|| search_info.and_then(|value| json_string_field(value, "SearchTerm"))),
            year: json_i64_field(payload, "Year")
                .or_else(|| json_i64_field(payload, "ProductionYear"))
                .or_else(|| search_info.and_then(|value| json_i64_field(value, "Year")))
                .or_else(|| search_info.and_then(|value| json_i64_field(value, "ProductionYear")))
                .and_then(|year| i32::try_from(year).ok()),
        }
    }

    fn matches_media_item(&self, item: &MediaItem, metadata: Option<&serde_json::Value>) -> bool {
        self.matches_name(&item.name)
            && self
                .year
                .is_none_or(|year| remote_search_metadata_year(metadata) == Some(year))
    }

    fn matches_name(&self, candidate: &str) -> bool {
        self.name.as_ref().is_none_or(|name| {
            candidate
                .to_ascii_lowercase()
                .contains(&name.to_ascii_lowercase())
        })
    }
}

fn collect_remote_search_metadata_entities(
    server_id: &str,
    item_type: &str,
    metadata_keys: &[&str],
    items: &[MediaItem],
    metadata_by_item: &HashMap<Uuid, serde_json::Value>,
    request: &RemoteSearchRequest,
    results: &mut BTreeMap<String, serde_json::Value>,
) {
    let item_ids = items.iter().map(|item| item.id).collect::<HashSet<_>>();
    let mut names = BTreeMap::<String, String>::new();
    for (item_id, metadata) in metadata_by_item {
        if !item_ids.contains(item_id) {
            continue;
        }
        for key in metadata_keys {
            if let Some(value) = json_field_case_insensitive(metadata, key) {
                collect_metadata_value(value, &mut names);
            }
        }
    }
    for name in names
        .into_values()
        .filter(|name| request.matches_name(name))
    {
        results.insert(
            remote_search_result_key(item_type, &name),
            remote_search_result_from_name(server_id, &name, item_type, None),
        );
    }
}

fn remote_search_result_from_media_item(
    item: &MediaItem,
    metadata: Option<&serde_json::Value>,
) -> serde_json::Value {
    let item_type = media_item_type(item);
    let overview = metadata
        .and_then(|metadata| first_metadata_value_from_json(metadata, &["Overview", "overview"]))
        .unwrap_or_default();
    let provider_ids = metadata
        .and_then(|metadata| {
            json_field_case_insensitive(metadata, "ProviderIds")
                .or_else(|| json_field_case_insensitive(metadata, "ProviderId"))
        })
        .filter(|value| value.is_object())
        .cloned()
        .unwrap_or_else(|| {
            serde_json::json!({
                "JellyrinLocal": item.id.simple().to_string()
            })
        });
    serde_json::json!({
        "Name": item.name,
        "ProviderIds": provider_ids,
        "ProductionYear": remote_search_metadata_year(metadata),
        "IndexNumber": null,
        "IndexNumberEnd": null,
        "ParentIndexNumber": null,
        "PremiereDate": metadata
            .and_then(|metadata| first_metadata_value_from_json(metadata, &["PremiereDate", "AirDate", "DateCreated"]))
            .map(|value| normalize_metadata_date_for_json(&value)),
        "ImageUrl": null,
        "SearchProviderName": "Jellyrin Local Library",
        "Overview": overview,
        "Type": item_type,
        "ItemId": item.id.simple().to_string()
    })
}

fn remote_search_result_from_name(
    server_id: &str,
    name: &str,
    item_type: &str,
    production_year: Option<i32>,
) -> serde_json::Value {
    serde_json::json!({
        "Name": name,
        "ProviderIds": {
            "JellyrinLocal": stable_entity_id(item_type, &format!("{server_id}:{name}"))
        },
        "ProductionYear": production_year,
        "IndexNumber": null,
        "IndexNumberEnd": null,
        "ParentIndexNumber": null,
        "PremiereDate": null,
        "ImageUrl": null,
        "SearchProviderName": "Jellyrin Local Library",
        "Overview": "",
        "Type": item_type
    })
}

fn remote_search_metadata_year(metadata: Option<&serde_json::Value>) -> Option<i32> {
    let metadata = metadata?;
    for key in ["ProductionYear", "Year"] {
        if let Some(value) = json_field_case_insensitive(metadata, key)
            && let Some(year) = remote_search_json_i32(value)
        {
            return Some(year);
        }
    }
    None
}

fn remote_search_json_i32(value: &serde_json::Value) -> Option<i32> {
    match value {
        serde_json::Value::Number(value) => {
            value.as_i64().and_then(|value| i32::try_from(value).ok())
        }
        serde_json::Value::String(value) => value.parse::<i32>().ok(),
        serde_json::Value::Array(values) => values.iter().find_map(remote_search_json_i32),
        _ => None,
    }
}

fn remote_search_result_key(item_type: &str, name: &str) -> String {
    format!("{item_type}:{}", name.trim().to_ascii_lowercase())
}

async fn metadata_payload_for_item(
    db: &Database,
    item_id: Uuid,
) -> Result<serde_json::Value, ApiError> {
    Ok(db
        .media_item_metadata_by_item_ids(&HashSet::from([item_id]))
        .await?
        .into_iter()
        .next()
        .map(|metadata| metadata.payload)
        .unwrap_or_else(|| serde_json::json!({})))
}

fn merge_item_metadata_update(
    metadata: &mut serde_json::Value,
    payload: serde_json::Value,
) -> Result<(), ApiError> {
    let serde_json::Value::Object(payload) = payload else {
        return Err(ApiError::bad_request("Item update body must be an object"));
    };
    if !metadata.is_object() {
        *metadata = serde_json::json!({});
    }
    let Some(target) = metadata.as_object_mut() else {
        return Err(ApiError::bad_request("Item metadata must be an object"));
    };
    for (key, value) in payload {
        if key.eq_ignore_ascii_case("Id") {
            continue;
        }
        target.insert(key, value);
    }
    Ok(())
}

fn merge_remote_search_result_metadata(
    metadata: &mut serde_json::Value,
    payload: serde_json::Value,
) -> Result<(), ApiError> {
    let mut candidate = remote_search_candidate_payload(payload);
    if !candidate.is_object() {
        return Err(ApiError::bad_request(
            "Remote search result must be an object",
        ));
    }

    for (target, keys) in [
        (
            "PrimaryImageUrl",
            &["PrimaryImageUrl", "ImageUrl", "PosterUrl", "PosterImageUrl"][..],
        ),
        (
            "BackdropImageUrl",
            &["BackdropImageUrl", "BackgroundImageUrl", "BackdropUrl"][..],
        ),
        (
            "ThumbImageUrl",
            &["ThumbImageUrl", "ThumbnailUrl", "BannerImageUrl"][..],
        ),
        ("LogoImageUrl", &["LogoImageUrl", "LogoUrl"][..]),
    ] {
        if json_field_case_insensitive(&candidate, target).is_none()
            && let Some(value) = keys
                .iter()
                .find_map(|key| json_field_case_insensitive(&candidate, key))
                .cloned()
            && value.as_str().is_some_and(remote_image_url_is_fetchable)
        {
            candidate[target] = value;
        }
    }

    if json_field_case_insensitive(&candidate, "MetadataSource").is_none()
        && let Some(provider) = json_string_field(&candidate, "SearchProviderName")
    {
        candidate["MetadataSource"] = serde_json::Value::String(provider);
    }

    merge_item_metadata_update(metadata, candidate)
}

fn remote_search_candidate_payload(payload: serde_json::Value) -> serde_json::Value {
    json_field_case_insensitive(&payload, "SearchResult")
        .or_else(|| json_field_case_insensitive(&payload, "Result"))
        .or_else(|| json_field_case_insensitive(&payload, "Item"))
        .cloned()
        .unwrap_or(payload)
}

fn external_id_infos_for_item_type(item_type: &str) -> Vec<serde_json::Value> {
    let mut infos = vec![serde_json::json!({
        "Name": "IMDb",
        "Key": "Imdb",
        "UrlFormatString": "https://www.imdb.com/title/{0}",
        "SupportsMultiple": false
    })];
    match item_type {
        "Movie" => {
            infos.push(serde_json::json!({
                "Name": "TheMovieDb",
                "Key": "Tmdb",
                "UrlFormatString": "https://www.themoviedb.org/{0}",
                "SupportsMultiple": false
            }));
            infos.push(serde_json::json!({
                "Name": "TheTVDB",
                "Key": "Tvdb",
                "UrlFormatString": "https://thetvdb.com/dereferrer/{0}",
                "SupportsMultiple": false
            }));
        }
        "Series" => {
            infos.push(serde_json::json!({
                "Name": "TheMovieDb",
                "Key": "Tmdb",
                "Type": "Series",
                "UrlFormatString": "https://www.themoviedb.org/tv/{0}",
                "SupportsMultiple": false
            }));
            infos.push(serde_json::json!({
                "Name": "TheTVDB",
                "Key": "Tvdb",
                "Type": "Series",
                "UrlFormatString": "https://thetvdb.com/dereferrer/series/{0}",
                "SupportsMultiple": false
            }));
            infos.push(serde_json::json!({
                "Name": "Zap2It",
                "Key": "Zap2It",
                "UrlFormatString": "",
                "SupportsMultiple": false
            }));
        }
        "Episode" | "Season" => {
            infos.push(serde_json::json!({
                "Name": "TheMovieDb",
                "Key": "Tmdb",
                "Type": item_type,
                "UrlFormatString": "https://www.themoviedb.org/tv/{0}",
                "SupportsMultiple": false
            }));
            infos.push(serde_json::json!({
                "Name": "TheTVDB",
                "Key": "Tvdb",
                "Type": item_type,
                "UrlFormatString": "https://thetvdb.com/dereferrer/{0}",
                "SupportsMultiple": false
            }));
        }
        "Audio" | "MusicAlbum" | "MusicArtist" => {
            infos.push(serde_json::json!({
                "Name": "MusicBrainz",
                "Key": "MusicBrainz",
                "UrlFormatString": "",
                "SupportsMultiple": false
            }));
        }
        _ => {}
    }
    infos
}

