async fn update_item_user_data_inner(
    db: &Database,
    user_id: Uuid,
    item_id: &str,
    body: Option<serde_json::Value>,
) -> Result<Json<serde_json::Value>, ApiError> {
    if live_tv_channel_optional_by_id(db, item_id).await?.is_some() {
        if let Some(is_favorite) =
            json_value_bool_field(body.as_ref(), &["IsFavorite", "isFavorite"])
        {
            let user_data =
                set_live_tv_channel_favorite_if_present(db, user_id, item_id, is_favorite)
                    .await?
                    .ok_or_else(|| ApiError::not_found("Live TV item not found"))?;
            return Ok(Json(user_data));
        }
        let user_data = live_tv_channel_user_data_if_present(db, user_id, item_id)
            .await?
            .ok_or_else(|| ApiError::not_found("Live TV item not found"))?;
        return Ok(Json(user_data));
    }
    let item = media_item_by_id(db, item_id).await?;
    let current = db.playback_state_for_item(user_id, item.id).await?;
    let played = json_value_bool_field(body.as_ref(), &["Played", "played"])
        .unwrap_or_else(|| current.as_ref().is_some_and(|state| state.played));
    let is_favorite = json_value_bool_field(body.as_ref(), &["IsFavorite", "isFavorite"]);
    let rating = json_value_f64_field(body.as_ref(), &["Rating", "rating"]).or_else(|| {
        json_value_bool_field(body.as_ref(), &["Likes", "likes"])
            .map(|likes| if likes { 1.0_f64 } else { 0.0_f64 })
    });
    let position_ticks = json_value_i64_field(
        body.as_ref(),
        &["PlaybackPositionTicks", "playbackPositionTicks"],
    )
    .unwrap_or_else(|| current.as_ref().map_or(0, |state| state.position_ticks));
    SessionService::new(db)
        .upsert_playback_state(UpsertPlaybackState {
            user_id,
            item_id: item.id,
            media_source_id: current
                .as_ref()
                .and_then(|state| state.media_source_id.clone()),
            audio_stream_index: current.as_ref().and_then(|state| state.audio_stream_index),
            subtitle_stream_index: current
                .as_ref()
                .and_then(|state| state.subtitle_stream_index),
            position_ticks,
            is_paused: current.as_ref().is_some_and(|state| state.is_paused),
            played,
        })
        .await?;
    if let Some(is_favorite) = is_favorite {
        SessionService::new(db)
            .set_item_favorite(user_id, item.id, is_favorite)
            .await?;
    }
    if let Some(rating) = rating {
        SessionService::new(db)
            .set_item_rating(user_id, item.id, Some(rating))
            .await?;
    }
    item_user_data_json(db, user_id, item_id).await.map(Json)
}

async fn item_user_data_json(
    db: &Database,
    user_id: Uuid,
    item_id: &str,
) -> Result<serde_json::Value, ApiError> {
    if let Some(user_data) = live_tv_channel_user_data_if_present(db, user_id, item_id).await? {
        return Ok(user_data);
    }
    let item = media_item_by_id(db, item_id).await?;
    let playback = db.playback_state_for_item(user_id, item.id).await?;
    let item_id = item.id.simple().to_string();
    let playback_position_ticks = playback.as_ref().map_or(0, |state| state.position_ticks);
    let played = playback.as_ref().is_some_and(|state| state.played);
    let play_count = i64::from(played);
    let is_favorite = playback.as_ref().is_some_and(|state| state.is_favorite);
    let rating = playback.as_ref().and_then(|state| state.rating);
    let likes = rating.map(|rating| rating > 0.0);
    Ok(serde_json::json!({
        "PlaybackPositionTicks": playback_position_ticks,
        "PlayCount": play_count,
        "IsFavorite": is_favorite,
        "Likes": likes,
        "Played": played,
        "Key": item_id,
        "ItemId": item_id,
        "PlayedPercentage": null,
        "LastPlayedDate": null,
        "UnplayedItemCount": null,
        "Rating": rating
    }))
}

fn json_value_bool_field(value: Option<&serde_json::Value>, names: &[&str]) -> Option<bool> {
    let object = value.and_then(|value| value.as_object())?;
    names
        .iter()
        .find_map(|name| object.get(*name).and_then(|value| value.as_bool()))
}

fn json_value_i64_field(value: Option<&serde_json::Value>, names: &[&str]) -> Option<i64> {
    let object = value.and_then(|value| value.as_object())?;
    names
        .iter()
        .find_map(|name| object.get(*name).and_then(|value| value.as_i64()))
}

fn json_value_f64_field(value: Option<&serde_json::Value>, names: &[&str]) -> Option<f64> {
    let object = value.and_then(|value| value.as_object())?;
    names
        .iter()
        .find_map(|name| object.get(*name).and_then(|value| value.as_f64()))
}

