async fn instant_mix_from_playlist(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    RawQuery(raw_query): RawQuery,
    Path(item_id): Path<String>,
) -> Result<Json<serde_json::Value>, ApiError> {
    let query = parse_items_query(raw_query.as_deref());
    let auth_user =
        require_request_user(&state.db, &headers, auth_query.api_key.as_deref()).await?;
    let requested_user_id = query.user_id.as_deref().map(resolve_user_id).transpose()?;
    if let Some(requested_user_id) = requested_user_id {
        ensure_user_access(&auth_user, requested_user_id)?;
    }

    if let Ok(playlist_id) = parse_jellyfin_uuid(&item_id)
        && let Ok(playlist) = ensure_media_list_kind(&state.db, playlist_id, "playlist").await
    {
        ensure_media_list_read_access(&state.db, &auth_user, &playlist).await?;
        let mix_items = state
            .db
            .media_list_items(playlist.id)
            .await?
            .into_iter()
            .map(|entry| entry.item)
            .filter(|item| item.media_type == "Audio")
            .collect::<Vec<_>>();
        return instant_mix_items_response(&state, &query, requested_user_id, mix_items).await;
    }

    let mix_items = audio_instant_mix_items(&state.db, &item_id).await?;
    instant_mix_items_response(&state, &query, requested_user_id, mix_items).await
}

async fn instant_mix_from_metadata_entity(
    state: AppState,
    headers: HeaderMap,
    auth_query: AuthQuery,
    raw_query: Option<String>,
    item_id: String,
    entity_type: &'static str,
    metadata_keys: &'static [&'static str],
) -> Result<Json<serde_json::Value>, ApiError> {
    let query = parse_items_query(raw_query.as_deref());
    let auth_user =
        require_request_user(&state.db, &headers, auth_query.api_key.as_deref()).await?;
    let requested_user_id = query.user_id.as_deref().map(resolve_user_id).transpose()?;
    if let Some(requested_user_id) = requested_user_id {
        ensure_user_access(&auth_user, requested_user_id)?;
    }

    let mut items_query = query.clone();
    items_query.include_item_types = vec!["Audio".to_string()];
    items_query.search_term = None;
    items_query.name_starts_with = None;
    items_query.name_starts_with_or_greater = None;
    items_query.name_less_than = None;
    items_query.start_index = None;
    items_query.limit = None;
    items_query.sort_by = Some("SortName".to_string());
    items_query.sort_order = None;
    let (candidate_items, metadata_by_item) =
        media_items_and_metadata_by_effective_types(&state.db, &["Audio".to_string()]).await?;
    let candidates =
        filtered_media_items(candidate_items, &items_query, requested_user_id, &state.db).await?;

    if let Some(source) = candidates.iter().find(|item| {
        parse_jellyfin_uuid(&item_id).is_ok_and(|requested_id| requested_id == item.id)
    }) {
        if let Some(entity_name) = metadata_by_item.get(&source.id).and_then(|metadata| {
            first_metadata_string_from_payload_in_key_order(metadata, metadata_keys)
        }) {
            let mix_items = metadata_entity_audio_items_from_payloads(
                candidates,
                &metadata_by_item,
                metadata_keys,
                &entity_name,
            );
            return instant_mix_items_response(&state, &query, requested_user_id, mix_items).await;
        }
        return instant_mix_items_response(
            &state,
            &query,
            requested_user_id,
            audio_instant_mix_items(&state.db, &item_id).await?,
        )
        .await;
    }

    let entity_name =
        metadata_values_for_keys_from_payloads(metadata_keys, &candidates, &metadata_by_item)
            .into_iter()
            .find(|name| stable_entity_id(entity_type, name).eq_ignore_ascii_case(&item_id))
            .ok_or_else(|| ApiError::not_found("Instant mix source not found"))?;
    let mix_items = metadata_entity_audio_items_from_payloads(
        candidates,
        &metadata_by_item,
        metadata_keys,
        &entity_name,
    );
    instant_mix_items_response(&state, &query, requested_user_id, mix_items).await
}

fn metadata_entity_audio_items_from_payloads(
    mut candidates: Vec<MediaItem>,
    metadata_by_item: &HashMap<Uuid, serde_json::Value>,
    metadata_keys: &[&str],
    entity_name: &str,
) -> Vec<MediaItem> {
    let entity_name = entity_name.trim().to_ascii_lowercase();
    candidates.retain(|item| {
        metadata_by_item.get(&item.id).is_some_and(|metadata| {
            metadata_strings_from_payload(metadata, metadata_keys)
                .into_iter()
                .any(|value| value.eq_ignore_ascii_case(&entity_name))
        })
    });
    candidates.sort_by(|left, right| compare_media_items(left, right, &[SortField::SortName]));
    candidates
}

fn first_metadata_string_from_payload_in_key_order(
    metadata: &serde_json::Value,
    metadata_keys: &[&str],
) -> Option<String> {
    metadata_keys.iter().find_map(|key| {
        metadata_strings_from_payload(metadata, &[*key])
            .into_iter()
            .next()
    })
}

fn metadata_values_for_keys_from_payloads(
    keys: &[&str],
    items: &[MediaItem],
    metadata_by_item: &HashMap<Uuid, serde_json::Value>,
) -> Vec<String> {
    let mut values = BTreeMap::<String, String>::new();
    for item in items {
        let Some(metadata) = metadata_by_item.get(&item.id) else {
            continue;
        };
        for key in keys {
            if let Some(value) = metadata.get(*key) {
                collect_metadata_value(value, &mut values);
            }
        }
    }
    values.into_values().collect()
}

async fn instant_mix_items_response(
    state: &AppState,
    query: &ItemsQuery,
    requested_user_id: Option<Uuid>,
    mix_items: Vec<MediaItem>,
) -> Result<Json<serde_json::Value>, ApiError> {
    if mix_items.is_empty() {
        return Ok(Json(query_result(Vec::new())));
    }

    let server_id = state.db.server_state().await?.server_id.to_string();
    let total_record_count = mix_items.len();
    let start_index = query.start_index.unwrap_or(0);
    let limit = query.limit.unwrap_or(usize::MAX);
    let items = items_to_json(
        &state.db,
        mix_items
            .into_iter()
            .skip(start_index)
            .take(limit)
            .collect(),
        &server_id,
        requested_user_id,
        false,
    )
    .await?;
    Ok(Json(query_result_with_total(
        items,
        total_record_count,
        start_index,
    )))
}

async fn audio_instant_mix_items(db: &Database, item_id: &str) -> Result<Vec<MediaItem>, ApiError> {
    let item = media_item_by_id(db, item_id).await?;
    if item.media_type != "Audio" {
        return Ok(Vec::new());
    }

    let mut mix_items = db
        .media_items_for_virtual_folders(&[item.virtual_folder_id])
        .await?
        .into_iter()
        .filter(|candidate| candidate.media_type == "Audio")
        .collect::<Vec<_>>();
    mix_items.sort_by(|left, right| compare_media_items(left, right, &[SortField::SortName]));
    mix_items.sort_by_key(|candidate| candidate.id != item.id);
    Ok(mix_items)
}

async fn instant_mix_from_music_genre(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    RawQuery(raw_query): RawQuery,
    Path(name): Path<String>,
) -> Result<Json<serde_json::Value>, ApiError> {
    let query = parse_items_query(raw_query.as_deref());
    let auth_user =
        require_request_user(&state.db, &headers, auth_query.api_key.as_deref()).await?;
    let requested_user_id = query.user_id.as_deref().map(resolve_user_id).transpose()?;
    if let Some(requested_user_id) = requested_user_id {
        ensure_user_access(&auth_user, requested_user_id)?;
    }

    music_genre_instant_mix_response(&state, &query, requested_user_id, name.trim()).await
}

async fn instant_mix_from_music_genre_by_id(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    RawQuery(raw_query): RawQuery,
) -> Result<Json<serde_json::Value>, ApiError> {
    let query = parse_items_query(raw_query.as_deref());
    let genre_id = query_string_values(raw_query.as_deref(), &["Id"])
        .into_iter()
        .find(|id| !id.trim().is_empty())
        .ok_or_else(|| ApiError::bad_request("Music genre Id is required"))?;
    let auth_user =
        require_request_user(&state.db, &headers, auth_query.api_key.as_deref()).await?;
    let requested_user_id = query.user_id.as_deref().map(resolve_user_id).transpose()?;
    if let Some(requested_user_id) = requested_user_id {
        ensure_user_access(&auth_user, requested_user_id)?;
    }
    let genre_name =
        music_genre_name_by_entity_id(&state, &query, requested_user_id, genre_id.trim()).await?;

    music_genre_instant_mix_response(&state, &query, requested_user_id, &genre_name).await
}

async fn music_genre_name_by_entity_id(
    state: &AppState,
    query: &ItemsQuery,
    requested_user_id: Option<Uuid>,
    genre_id: &str,
) -> Result<String, ApiError> {
    let mut scope_query = query.clone();
    scope_query.ids = None;
    scope_query.search_term = None;
    scope_query.name_starts_with = None;
    scope_query.name_starts_with_or_greater = None;
    scope_query.name_less_than = None;
    scope_query.start_index = None;
    scope_query.limit = None;
    scope_query.sort_by = Some("SortName".to_string());
    scope_query.sort_order = None;
    let effective_types = csv_values_lowercase(&scope_query.include_item_types)
        .unwrap_or_else(all_effective_media_item_types);
    let (candidate_items, metadata_by_item) =
        media_items_and_metadata_by_effective_types(&state.db, &effective_types).await?;
    let scoped_items =
        filtered_media_items(candidate_items, &scope_query, requested_user_id, &state.db).await?;
    metadata_values_for_keys_from_payloads(
        &["MusicGenres", "Genres"],
        &scoped_items,
        &metadata_by_item,
    )
    .into_iter()
    .find(|name| stable_entity_id("MusicGenre", name).eq_ignore_ascii_case(genre_id))
    .ok_or_else(|| ApiError::not_found("Music genre not found"))
}

async fn music_genre_instant_mix_response(
    state: &AppState,
    query: &ItemsQuery,
    requested_user_id: Option<Uuid>,
    name: &str,
) -> Result<Json<serde_json::Value>, ApiError> {
    let mut items_query = query.clone();
    if items_query.include_item_types.is_empty() {
        items_query.include_item_types.push("Audio".to_string());
    }
    items_query.search_term = None;
    items_query.name_starts_with = None;
    items_query.name_starts_with_or_greater = None;
    items_query.name_less_than = None;
    items_query.start_index = None;
    items_query.limit = None;
    items_query.sort_by = Some("SortName".to_string());
    items_query.sort_order = None;
    let effective_types = csv_values_lowercase(&items_query.include_item_types)
        .unwrap_or_else(all_effective_media_item_types);
    let (candidate_items, metadata_by_item) =
        media_items_and_metadata_by_effective_types(&state.db, &effective_types).await?;
    let candidates =
        filtered_media_items(candidate_items, &items_query, requested_user_id, &state.db).await?;
    let genre_name = name.trim().to_ascii_lowercase();
    let mut mix_items = candidates
        .into_iter()
        .filter(|item| {
            metadata_by_item.get(&item.id).is_some_and(|metadata| {
                metadata_strings_from_payload(metadata, &["MusicGenres", "Genres"])
                    .into_iter()
                    .any(|genre| genre.eq_ignore_ascii_case(&genre_name))
            })
        })
        .collect::<Vec<_>>();
    mix_items.sort_by(|left, right| compare_media_items(left, right, &[SortField::SortName]));

    let server_id = state.db.server_state().await?.server_id.to_string();
    let total_record_count = mix_items.len();
    let start_index = query.start_index.unwrap_or(0);
    let limit = query.limit.unwrap_or(usize::MAX);
    let items = mix_items
        .into_iter()
        .skip(start_index)
        .take(limit)
        .collect::<Vec<_>>();
    Ok(Json(query_result_with_total(
        items_to_json(&state.db, items, &server_id, requested_user_id, false).await?,
        total_record_count,
        start_index,
    )))
}

#[derive(Debug, Clone)]
struct PlaybackInfoOptions {
    enable_direct_play: bool,
    enable_direct_stream: bool,
    enable_transcoding: bool,
    max_streaming_bitrate: Option<u32>,
    media_source_id: Option<String>,
    audio_stream_index: Option<i64>,
    subtitle_stream_index: Option<i64>,
    burn_in_subtitle: bool,
    start_position_ticks: i64,
    start_position_ticks_provided: bool,
    direct_play_profiles: Option<Vec<DirectPlayProfileMatcher>>,
    transcoding_profiles: Option<Vec<TranscodingProfileMatcher>>,
    subtitle_profiles: Option<Vec<SubtitleProfileMatcher>>,
    hls_subtitles_as_embedded: bool,
    plugin_vod_selection_hls: bool,
    codec_profiles: Vec<CodecProfileMatcher>,
}

#[derive(Debug, Clone)]
struct DirectPlayProfileMatcher {
    profile_type: Option<String>,
    containers: Vec<String>,
    video_codecs: Vec<String>,
    audio_codecs: Vec<String>,
}

#[derive(Debug, Clone)]
struct TranscodingProfileMatcher {
    profile_type: Option<String>,
    context: Option<String>,
    containers: Vec<String>,
    protocols: Vec<String>,
    video_codecs: Vec<String>,
    audio_codecs: Vec<String>,
    max_width: Option<u32>,
    max_height: Option<u32>,
    video_bitrate: Option<u32>,
    audio_bitrate: Option<u32>,
}

#[derive(Debug, Clone)]
struct SubtitleProfileMatcher {
    format: Option<String>,
    method: Option<String>,
}

#[derive(Debug, Clone)]
struct CodecProfileMatcher {
    profile_type: Option<String>,
    codecs: Vec<String>,
    conditions: Vec<CodecCondition>,
    invalid_required_conditions: Vec<Option<CodecConditionProperty>>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CodecConditionProperty {
    Width,
    Height,
    VideoBitrate,
    AudioBitrate,
    VideoProfile,
    AudioProfile,
    VideoLevel,
    VideoBitDepth,
    VideoFrameRate,
    AudioChannels,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CodecConditionComparison {
    Equal,
    NotEqual,
    EqualAny,
    NotEqualAny,
    LessThan,
    LessThanEqual,
    GreaterThan,
    GreaterThanEqual,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum CodecConditionValue {
    Numeric(u32),
    Text(String),
}

#[derive(Debug, Clone)]
struct CodecCondition {
    property: CodecConditionProperty,
    comparison: CodecConditionComparison,
    values: Vec<CodecConditionValue>,
    is_required: bool,
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
struct PlaybackOutputConstraints {
    max_width: Option<u32>,
    max_height: Option<u32>,
    video_bitrate: Option<u32>,
    audio_bitrate: Option<u32>,
    video_profile: Option<H264Profile>,
    video_level: Option<u8>,
    video_bit_depth: Option<u8>,
    max_video_frame_rate_millihertz: Option<u32>,
    audio_profile: Option<AacProfile>,
    audio_channels: Option<u8>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DeliveryMode {
    DirectLocal,
    DirectProxy,
    HlsRemux,
    HlsTranscode,
    Unsupported,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum FfmpegMode {
    Enabled,
    RemuxOnly,
    Disabled,
}

fn parse_ffmpeg_mode(value: Option<&str>) -> Result<FfmpegMode, String> {
    match value.map(str::trim).map(str::to_ascii_lowercase).as_deref() {
        None | Some("remux-only") => Ok(FfmpegMode::RemuxOnly),
        Some("enabled") => Ok(FfmpegMode::Enabled),
        Some("disabled") => Ok(FfmpegMode::Disabled),
        Some(value) => Err(format!(
            "invalid JELLYRIN_FFMPEG_MODE={value:?}; expected enabled, remux-only, or disabled"
        )),
    }
}

fn configured_ffmpeg_mode() -> FfmpegMode {
    static MODE: OnceLock<FfmpegMode> = OnceLock::new();
    *MODE.get_or_init(|| {
        let configured = std::env::var("JELLYRIN_FFMPEG_MODE").ok();
        // Existing route tests deliberately exercise every encode path. Keep that test harness
        // explicit without weakening the production fallback verified by `parse_ffmpeg_mode`.
        #[cfg(test)]
        let configured = configured.or_else(|| Some("enabled".to_string()));
        parse_ffmpeg_mode(configured.as_deref()).unwrap_or_else(|error| {
            tracing::error!(%error, "blocking FFmpeg because its execution mode is invalid");
            FfmpegMode::Disabled
        })
    })
}

fn ffmpeg_mode_name(mode: FfmpegMode) -> &'static str {
    match mode {
        FfmpegMode::Enabled => "enabled",
        FfmpegMode::RemuxOnly => "remux-only",
        FfmpegMode::Disabled => "disabled",
    }
}

fn transcode_job_kind_name(kind: TranscodeJobKind) -> &'static str {
    match kind {
        TranscodeJobKind::VideoEncode => "video-encode",
        TranscodeJobKind::AudioEncode => "audio-encode",
        TranscodeJobKind::Remux => "remux",
        TranscodeJobKind::Auxiliary => "auxiliary",
        TranscodeJobKind::Probe => "probe",
    }
}

fn build_hls_transcode_plan(
    request: &HlsTranscodeRequest,
    from_stdin: bool,
    mode: FfmpegMode,
) -> HlsTranscodePlan {
    let build = |request: &HlsTranscodeRequest| {
        if from_stdin {
            build_hls_ffmpeg_command_from_stdin(request)
        } else {
            build_hls_ffmpeg_command(request)
        }
    };
    let primary = build(request);
    let fallback = (mode == FfmpegMode::Enabled
        && classify_transcode_command(&primary) == TranscodeJobKind::Remux)
        .then(|| {
            let mut fallback = request.clone();
            if fallback.video_mode == HlsStreamMode::Copy {
                fallback.video_mode = HlsStreamMode::Encode;
            }
            if fallback.audio_mode == HlsStreamMode::Copy {
                fallback.audio_mode = HlsStreamMode::Encode;
            }
            build(&fallback)
        });
    HlsTranscodePlan { primary, fallback }
}

fn hls_remux_fallback_eligible(
    attempt_count: u8,
    job_kind: TranscodeJobKind,
    first_segment_ready: bool,
    primary_failed: bool,
    fallback_available: bool,
) -> bool {
    attempt_count == 1
        && job_kind == TranscodeJobKind::Remux
        && !first_segment_ready
        && primary_failed
        && fallback_available
}

/// Applies the operator's CPU policy to Live TV before the FFmpeg command is classified.
///
/// Live sources do not currently expose trustworthy codec metadata. In the production default
/// (`remux-only`) copying both streams is the only admissible choice and avoids silently spending
/// a video encoder slot. Explicit `enabled` mode also starts with copy and may make one bounded
/// encode fallback if remux exits before producing the first segment.
fn apply_live_hls_ffmpeg_policy(request: &mut HlsTranscodeRequest, mode: FfmpegMode) {
    if mode != FfmpegMode::Disabled {
        request.video_mode = HlsStreamMode::Copy;
        request.audio_mode = HlsStreamMode::Copy;
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct TranscodeDecision {
    delivery: DeliveryMode,
    video: HlsStreamMode,
    audio: HlsStreamMode,
    reasons: Vec<&'static str>,
    output: PlaybackOutputConstraints,
}

struct PlaybackTranscodeInput<'a> {
    item: &'a MediaItem,
    metadata: Option<&'a serde_json::Value>,
    item_json: serde_json::Value,
    options: PlaybackInfoOptions,
    decision: TranscodeDecision,
}

impl Default for PlaybackInfoOptions {
    fn default() -> Self {
        Self {
            enable_direct_play: true,
            enable_direct_stream: true,
            enable_transcoding: true,
            max_streaming_bitrate: None,
            media_source_id: None,
            audio_stream_index: None,
            subtitle_stream_index: None,
            burn_in_subtitle: false,
            start_position_ticks: 0,
            start_position_ticks_provided: false,
            direct_play_profiles: None,
            transcoding_profiles: None,
            subtitle_profiles: None,
            hls_subtitles_as_embedded: false,
            plugin_vod_selection_hls: false,
            codec_profiles: Vec::new(),
        }
    }
}

fn parse_playback_info_options(
    raw_query: Option<&str>,
    body: Option<&serde_json::Value>,
) -> PlaybackInfoOptions {
    let mut options = body
        .map(playback_info_options_from_body)
        .unwrap_or_default();
    let Some(raw_query) = raw_query else {
        return options;
    };

    for part in raw_query.split('&').filter(|part| !part.is_empty()) {
        let (key, value) = part.split_once('=').unwrap_or((part, ""));
        let key = percent_decode_query_component(key).to_ascii_lowercase();
        let value = percent_decode_query_component(value);
        match key.as_str() {
            "enabledirectplay" => {
                if let Some(value) = parse_query_bool(&value) {
                    options.enable_direct_play = value;
                }
            }
            "enabledirectstream" => {
                if let Some(value) = parse_query_bool(&value) {
                    options.enable_direct_stream = value;
                }
            }
            "enabletranscoding" => {
                if let Some(value) = parse_query_bool(&value) {
                    options.enable_transcoding = value;
                }
            }
            "maxstreamingbitrate" => {
                if let Some(value) = value.parse::<u32>().ok().filter(|value| *value > 0) {
                    options.max_streaming_bitrate = Some(value);
                }
            }
            "mediasourceid" => {
                if !value.trim().is_empty() {
                    options.media_source_id = Some(value.trim().to_string());
                }
            }
            "audiostreamindex" => {
                if let Ok(value) = value.parse::<i64>() {
                    options.audio_stream_index = Some(value);
                }
            }
            "subtitlestreamindex" => {
                if let Ok(value) = value.parse::<i64>() {
                    options.subtitle_stream_index = Some(value);
                }
            }
            "starttimeticks" | "startpositionticks" => {
                if let Ok(value) = value.parse::<i64>() {
                    options.start_position_ticks = value.max(0);
                    options.start_position_ticks_provided = true;
                }
            }
            _ => {}
        }
    }

    options
}

fn playback_info_options_from_body(body: &serde_json::Value) -> PlaybackInfoOptions {
    let mut options = PlaybackInfoOptions::default();
    if let Some(value) = json_bool_field(body, "EnableDirectPlay") {
        options.enable_direct_play = value;
    }
    if let Some(value) = json_bool_field(body, "EnableDirectStream") {
        options.enable_direct_stream = value;
    }
    if let Some(value) = json_bool_field(body, "EnableTranscoding") {
        options.enable_transcoding = value;
    }
    options.max_streaming_bitrate =
        json_positive_u32_field(body, "MaxStreamingBitrate").or_else(|| {
            json_field_case_insensitive(body, "DeviceProfile")
                .and_then(|profile| json_positive_u32_field(profile, "MaxStreamingBitrate"))
        });
    options.media_source_id = json_string_field(body, "MediaSourceId");
    options.audio_stream_index = json_i64_field(body, "AudioStreamIndex");
    options.subtitle_stream_index = json_i64_field(body, "SubtitleStreamIndex");
    if let Some(value) = json_i64_field(body, "StartTimeTicks")
        .or_else(|| json_i64_field(body, "StartPositionTicks"))
    {
        options.start_position_ticks = value.max(0);
        options.start_position_ticks_provided = true;
    }
    options.direct_play_profiles = parse_direct_play_profiles(body);
    options.transcoding_profiles = parse_transcoding_profiles(body);
    options.subtitle_profiles = parse_subtitle_profiles(body);
    options.codec_profiles = parse_codec_profiles(body);
    options
}

fn json_bool_field(value: &serde_json::Value, field: &str) -> Option<bool> {
    value.as_object()?.iter().find_map(|(key, value)| {
        if key.eq_ignore_ascii_case(field) {
            value.as_bool()
        } else {
            None
        }
    })
}

fn json_field_case_insensitive<'a>(
    value: &'a serde_json::Value,
    field: &str,
) -> Option<&'a serde_json::Value> {
    value.as_object()?.iter().find_map(|(key, value)| {
        if key.eq_ignore_ascii_case(field) {
            Some(value)
        } else {
            None
        }
    })
}

fn json_string_field(value: &serde_json::Value, field: &str) -> Option<String> {
    json_field_case_insensitive(value, field).and_then(|value| match value {
        serde_json::Value::String(value) if !value.trim().is_empty() => {
            Some(value.trim().to_string())
        }
        _ => None,
    })
}

fn json_i64_field(value: &serde_json::Value, field: &str) -> Option<i64> {
    json_field_case_insensitive(value, field).and_then(json_value_i64)
}

fn json_positive_u32_field(value: &serde_json::Value, field: &str) -> Option<u32> {
    json_i64_field(value, field).and_then(positive_u32)
}

fn json_f64_field(value: &serde_json::Value, field: &str) -> Option<f64> {
    json_field_case_insensitive(value, field).and_then(|value| {
        value
            .as_f64()
            .or_else(|| value.as_str().and_then(|value| value.parse::<f64>().ok()))
    })
}

fn parse_direct_play_profiles(body: &serde_json::Value) -> Option<Vec<DirectPlayProfileMatcher>> {
    let device_profile = json_field_case_insensitive(body, "DeviceProfile")?;
    let profiles = json_field_case_insensitive(device_profile, "DirectPlayProfiles")?
        .as_array()?
        .iter()
        .filter_map(parse_direct_play_profile)
        .collect::<Vec<_>>();
    Some(profiles)
}

fn parse_direct_play_profile(profile: &serde_json::Value) -> Option<DirectPlayProfileMatcher> {
    if !profile.is_object() {
        return None;
    }

    Some(DirectPlayProfileMatcher {
        profile_type: json_string_field(profile, "Type"),
        containers: json_csv_field(profile, "Container"),
        video_codecs: json_csv_field(profile, "VideoCodec"),
        audio_codecs: json_csv_field(profile, "AudioCodec"),
    })
}

fn parse_transcoding_profiles(body: &serde_json::Value) -> Option<Vec<TranscodingProfileMatcher>> {
    let device_profile = json_field_case_insensitive(body, "DeviceProfile")?;
    let profiles = json_field_case_insensitive(device_profile, "TranscodingProfiles")?
        .as_array()?
        .iter()
        .filter_map(parse_transcoding_profile)
        .collect::<Vec<_>>();
    Some(profiles)
}

fn parse_subtitle_profiles(body: &serde_json::Value) -> Option<Vec<SubtitleProfileMatcher>> {
    let device_profile = json_field_case_insensitive(body, "DeviceProfile")?;
    let profiles = json_field_case_insensitive(device_profile, "SubtitleProfiles")?
        .as_array()?
        .iter()
        .filter(|profile| profile.is_object())
        .map(|profile| SubtitleProfileMatcher {
            format: json_string_field(profile, "Format").map(|value| value.to_ascii_lowercase()),
            method: json_string_field(profile, "Method").map(|value| value.to_ascii_lowercase()),
        })
        .collect();
    Some(profiles)
}

fn parse_transcoding_profile(profile: &serde_json::Value) -> Option<TranscodingProfileMatcher> {
    if !profile.is_object() {
        return None;
    }

    Some(TranscodingProfileMatcher {
        profile_type: json_string_field(profile, "Type"),
        context: json_string_field(profile, "Context"),
        containers: json_csv_field(profile, "Container"),
        protocols: json_csv_field(profile, "Protocol"),
        video_codecs: json_csv_field(profile, "VideoCodec"),
        audio_codecs: json_csv_field(profile, "AudioCodec"),
        max_width: json_positive_u32_field(profile, "MaxWidth"),
        max_height: json_positive_u32_field(profile, "MaxHeight"),
        video_bitrate: json_positive_u32_field(profile, "VideoBitrate")
            .or_else(|| json_positive_u32_field(profile, "MaxVideoBitrate")),
        audio_bitrate: json_positive_u32_field(profile, "AudioBitrate")
            .or_else(|| json_positive_u32_field(profile, "MaxAudioBitrate")),
    })
}

fn parse_codec_profiles(body: &serde_json::Value) -> Vec<CodecProfileMatcher> {
    let Some(device_profile) = json_field_case_insensitive(body, "DeviceProfile") else {
        return Vec::new();
    };
    let Some(profiles) = json_field_case_insensitive(device_profile, "CodecProfiles")
        .and_then(serde_json::Value::as_array)
    else {
        return Vec::new();
    };

    profiles.iter().filter_map(parse_codec_profile).collect()
}

fn parse_codec_profile(profile: &serde_json::Value) -> Option<CodecProfileMatcher> {
    if !profile.is_object() {
        return None;
    }
    let mut conditions = Vec::new();
    let mut invalid_required_conditions = Vec::new();
    for condition in json_field_case_insensitive(profile, "Conditions")
        .and_then(serde_json::Value::as_array)
        .into_iter()
        .flatten()
    {
        match parse_codec_condition(condition) {
            Ok(Some(condition)) => conditions.push(condition),
            Ok(None) => {}
            Err(property) => invalid_required_conditions.push(property),
        }
    }
    Some(CodecProfileMatcher {
        profile_type: json_string_field(profile, "Type"),
        codecs: json_csv_field(profile, "Codec"),
        conditions,
        invalid_required_conditions,
    })
}

fn parse_codec_condition(
    condition: &serde_json::Value,
) -> Result<Option<CodecCondition>, Option<CodecConditionProperty>> {
    let is_required = json_bool_field(condition, "IsRequired").unwrap_or(false);
    let property = json_string_field(condition, "Property")
        .and_then(|property| parse_codec_condition_property(&property));
    let Some(property) = property else {
        return if is_required { Err(None) } else { Ok(None) };
    };
    let comparison = json_string_field(condition, "Condition")
        .and_then(|comparison| parse_codec_condition_comparison(&comparison));
    let Some(comparison) = comparison else {
        return if is_required {
            Err(Some(property))
        } else {
            Ok(None)
        };
    };
    let raw_value =
        json_field_case_insensitive(condition, "Value").and_then(codec_condition_raw_value);
    let Some(raw_value) = raw_value else {
        return if is_required {
            Err(Some(property))
        } else {
            Ok(None)
        };
    };
    let raw_values = if matches!(
        comparison,
        CodecConditionComparison::EqualAny | CodecConditionComparison::NotEqualAny
    ) {
        raw_value
            .split(['|', ','])
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .collect::<Vec<_>>()
    } else {
        vec![raw_value.trim()]
    };
    let values = raw_values
        .into_iter()
        .map(|value| parse_codec_condition_value(property, value))
        .collect::<Option<Vec<_>>>();
    let Some(values) = values.filter(|values| !values.is_empty()) else {
        return if is_required {
            Err(Some(property))
        } else {
            Ok(None)
        };
    };
    Ok(Some(CodecCondition {
        property,
        comparison,
        values,
        is_required,
    }))
}

fn parse_codec_condition_property(value: &str) -> Option<CodecConditionProperty> {
    match value
        .replace(['_', '-', ' '], "")
        .to_ascii_lowercase()
        .as_str()
    {
        "width" => Some(CodecConditionProperty::Width),
        "height" => Some(CodecConditionProperty::Height),
        "videobitrate" => Some(CodecConditionProperty::VideoBitrate),
        "audiobitrate" => Some(CodecConditionProperty::AudioBitrate),
        "videoprofile" => Some(CodecConditionProperty::VideoProfile),
        "audioprofile" => Some(CodecConditionProperty::AudioProfile),
        "videolevel" => Some(CodecConditionProperty::VideoLevel),
        "videobitdepth" | "bitdepth" => Some(CodecConditionProperty::VideoBitDepth),
        "videoframerate" | "framerate" => Some(CodecConditionProperty::VideoFrameRate),
        "audiochannels" | "channels" => Some(CodecConditionProperty::AudioChannels),
        _ => None,
    }
}

fn parse_codec_condition_comparison(value: &str) -> Option<CodecConditionComparison> {
    match value
        .replace(['_', '-', ' '], "")
        .to_ascii_lowercase()
        .as_str()
    {
        "equals" | "equal" => Some(CodecConditionComparison::Equal),
        "notequals" | "notequal" => Some(CodecConditionComparison::NotEqual),
        "equalsany" | "equalany" => Some(CodecConditionComparison::EqualAny),
        "notequalsany" | "notequalany" => Some(CodecConditionComparison::NotEqualAny),
        "lessthan" => Some(CodecConditionComparison::LessThan),
        "lessthanequal" | "lessthanorequal" => Some(CodecConditionComparison::LessThanEqual),
        "greaterthan" => Some(CodecConditionComparison::GreaterThan),
        "greaterthanequal" | "greaterthanorequal" => {
            Some(CodecConditionComparison::GreaterThanEqual)
        }
        _ => None,
    }
}

fn codec_condition_raw_value(value: &serde_json::Value) -> Option<String> {
    match value {
        serde_json::Value::String(value) if !value.trim().is_empty() => {
            Some(value.trim().to_string())
        }
        serde_json::Value::Number(value) => Some(value.to_string()),
        _ => None,
    }
}

fn parse_codec_condition_value(
    property: CodecConditionProperty,
    value: &str,
) -> Option<CodecConditionValue> {
    match property {
        CodecConditionProperty::VideoProfile | CodecConditionProperty::AudioProfile => {
            normalize_codec_profile(property, value).map(CodecConditionValue::Text)
        }
        CodecConditionProperty::VideoLevel => {
            parse_codec_level(value).map(CodecConditionValue::Numeric)
        }
        CodecConditionProperty::VideoFrameRate => {
            parse_frame_rate_millihertz(value).map(CodecConditionValue::Numeric)
        }
        CodecConditionProperty::Width
        | CodecConditionProperty::Height
        | CodecConditionProperty::VideoBitrate
        | CodecConditionProperty::AudioBitrate
        | CodecConditionProperty::VideoBitDepth
        | CodecConditionProperty::AudioChannels => value
            .parse::<u32>()
            .ok()
            .filter(|value| *value > 0)
            .filter(|value| match property {
                CodecConditionProperty::VideoBitDepth => *value <= 32,
                CodecConditionProperty::AudioChannels => *value <= 32,
                _ => true,
            })
            .map(CodecConditionValue::Numeric),
    }
}

fn normalize_codec_profile(property: CodecConditionProperty, value: &str) -> Option<String> {
    let normalized = value
        .trim()
        .to_ascii_lowercase()
        .replace([' ', '_', '-', '.'], "");
    if normalized.is_empty() {
        return None;
    }
    Some(match property {
        CodecConditionProperty::AudioProfile => match normalized.as_str() {
            "aaclc" | "aaclow" | "lowcomplexity" => "lc".to_string(),
            _ => normalized,
        },
        _ => normalized,
    })
}

fn parse_codec_level(value: &str) -> Option<u32> {
    if value.contains('.') {
        let level = value.parse::<f64>().ok()?;
        if !level.is_finite() || level <= 0.0 || level > 25.5 {
            return None;
        }
        let tenths = (level * 10.0).round();
        ((tenths - (level * 10.0)).abs() < 0.001).then_some(tenths as u32)
    } else {
        value
            .parse::<u32>()
            .ok()
            .filter(|level| (1..=255).contains(level))
    }
}

fn parse_frame_rate_millihertz(value: &str) -> Option<u32> {
    let frame_rate = value.parse::<f64>().ok()?;
    if !frame_rate.is_finite() || frame_rate <= 0.0 || frame_rate > 1_000.0 {
        return None;
    }
    u32::try_from((frame_rate * 1_000.0).round() as u64)
        .ok()
        .filter(|value| *value > 0)
}

fn json_csv_field(value: &serde_json::Value, field: &str) -> Vec<String> {
    json_string_field(value, field)
        .map(|value| {
            value
                .split([',', '|'])
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(|value| value.to_ascii_lowercase())
                .collect()
        })
        .unwrap_or_default()
}

async fn playback_info_response(
    state: &AppState,
    user: &User,
    token: &DeviceToken,
    item_id: &str,
    mut options: PlaybackInfoOptions,
) -> Result<Json<serde_json::Value>, ApiError> {
    if let Some(channel) = live_tv_channel_json_for_playable_item(&state.db, item_id).await? {
        let channel = ensure_live_tv_stream_probe(state, channel).await?;
        return live_tv_playback_info_response(&channel, &token.access_token, options);
    }
    let requested_item = media_item_by_id(&state.db, item_id).await?;
    let play_session_id = Uuid::new_v4().simple().to_string();
    let Some(mut item) = resolve_media_source_item(
        &state.db,
        requested_item,
        options.media_source_id.as_deref(),
    )
    .await?
    else {
        return Ok(Json(serde_json::json!({
            "MediaSources": [],
            "PlaySessionId": play_session_id,
            "ErrorCode": "NoCompatibleStream",
        })));
    };
    let server_id = state.db.server_state().await?.server_id.to_string();
    let playback = state.db.playback_state_for_item(user.id, item.id).await?;
    let active_playback =
        active_playback_session_for_user_item(&state.db, user.id, item.id).await?;
    apply_playback_info_state_defaults(&mut options, playback.as_ref(), active_playback.as_ref());
    let mut metadata_by_item =
        media_metadata_by_item_id(&state.db, HashSet::from([item.id])).await?;
    let mut metadata = metadata_by_item.remove(&item.id);
    if is_xtream_remote_media(metadata.as_ref()) {
        let metadata = metadata
            .as_mut()
            .ok_or_else(|| ApiError::service_unavailable("remote media metadata unavailable"))?;
        let resolved = ensure_xtream_remote_media_info(state, item, metadata).await?;
        item = resolved.item;
    }
    if is_plugin_vod_virtual_item(&item) {
        let metadata = metadata.as_mut().ok_or_else(|| {
            ApiError::service_unavailable("VOD provider playback route is unavailable")
        })?;
        if let Some(target) = plugin_vod_item_metadata_target(&item, metadata) {
            match ensure_plugin_vod_metadata(state, &target).await {
                Ok(resolved) => item.runtime_ticks = resolved.runtime_ticks,
                Err(error) => tracing::warn!(
                    status = %error.status(),
                    "VOD metadata enrichment was unavailable before playback"
                ),
            }
            *metadata = metadata_payload_for_item(&state.db, item.id).await?;
        }
        item = ensure_plugin_vod_media_runtime(state, item, metadata).await?;
        let reference = plugin_vod_remote_reference(metadata).ok_or_else(|| {
            ApiError::service_unavailable("VOD provider playback route is unavailable")
        })?;
        // Resolve once per PlaybackInfo request. The signed URL remains inside `playback` and is
        // dropped without ever entering the JSON response; only the validated delivery evidence
        // and safe track descriptors are applied to this ephemeral MediaItem clone.
        let playback = resolve_plugin_vod_playback(
            &state.db,
            &reference.plugin_id,
            &reference.tuner_id,
            &reference.provider_reference,
            Some(plugin_user_context(user, token)),
        )
        .await?;
        apply_plugin_vod_playback_descriptor(&mut item, &playback)?;
    }
    let metadata = metadata.as_ref();
    normalize_completed_remote_resume_position(&item, metadata, &mut options);
    apply_android_remote_subtitle_hls_policy(&item, metadata, &token.client, &mut options);
    apply_plugin_vod_stream_selection_hls_policy(&item, metadata, &token.client, &mut options);
    let item_json = media_item_to_json_with_playback_and_metadata(
        &item,
        &server_id,
        playback.as_ref(),
        metadata,
    );
    if !playback_selection_supported(&item, &options) {
        return Ok(Json(serde_json::json!({
            "MediaSources": [],
            "PlaySessionId": play_session_id,
            "ErrorCode": "NoCompatibleStream",
        })));
    }
    let decision = playback_delivery_decision(&item, metadata, &options);
    tracing::info!(
        delivery_mode = ?decision.delivery,
        video_mode = ?decision.video,
        audio_mode = ?decision.audio,
        reasons = ?decision.reasons,
        media_type = %item.media_type,
        remote = is_xtream_remote_media(metadata) || is_plugin_vod_remote_media(metadata),
        video_codec = media_item_stream_codec(&item, "Video").as_deref(),
        audio_codec = options
            .audio_stream_index
            .or_else(|| default_audio_stream_index(&media_item_streams(&item)))
            .and_then(|index| media_item_stream_codec_by_index(&item, "Audio", index))
            .as_deref(),
        width = item.width,
        height = item.height,
        bitrate = item.bitrate,
        "selected playback delivery mode"
    );
    match decision.delivery {
        DeliveryMode::HlsRemux | DeliveryMode::HlsTranscode => {
            return playback_transcode_info_response(
                state,
                user,
                token,
                PlaybackTranscodeInput {
                    item: &item,
                    metadata,
                    item_json,
                    options,
                    decision,
                },
            )
            .await;
        }
        DeliveryMode::Unsupported => {
            return Ok(Json(serde_json::json!({
                "MediaSources": [],
                "PlaySessionId": play_session_id,
                "ErrorCode": "NoCompatibleStream",
            })));
        }
        DeliveryMode::DirectLocal | DeliveryMode::DirectProxy => {}
    }

    let direct_play_supported = decision.delivery == DeliveryMode::DirectLocal
        && playback_direct_play_supported(&item, &options);
    let direct_stream_supported = matches!(
        decision.delivery,
        DeliveryMode::DirectLocal | DeliveryMode::DirectProxy
    );

    let mut media_sources = item_json["MediaSources"].clone();
    if let Some(media_source) = media_sources
        .as_array_mut()
        .and_then(|sources| sources.first_mut())
        .and_then(serde_json::Value::as_object_mut)
    {
        media_source.insert(
            "SupportsDirectPlay".to_string(),
            serde_json::json!(direct_play_supported),
        );
        media_source.insert(
            "SupportsDirectStream".to_string(),
            serde_json::json!(direct_stream_supported),
        );
        media_source.insert("SupportsTranscoding".to_string(), serde_json::json!(false));
        if decision.delivery == DeliveryMode::DirectProxy {
            let direct_stream_url = remote_direct_stream_url(&item, &token.access_token);
            media_source.insert(
                "DirectStreamUrl".to_string(),
                serde_json::json!(direct_stream_url),
            );
            // Jellyfin Android TV 0.19.x implements DirectStream by reading the legacy
            // TranscodingUrl field even when SupportsTranscoding is false. Keep the opaque local
            // proxy in both URL slots: it is still a byte-for-byte direct stream, never an
            // upstream or signed provider URL.
            media_source.insert(
                "TranscodingUrl".to_string(),
                serde_json::json!(direct_stream_url),
            );
            if let Some(container) = media_item_container(&item) {
                media_source.insert(
                    "TranscodingContainer".to_string(),
                    serde_json::json!(container),
                );
            }
        } else {
            media_source.remove("DirectStreamUrl");
            media_source.remove("TranscodingUrl");
            media_source.remove("TranscodingContainer");
        }
        apply_playback_stream_selection(media_source, &options);
        if text_subtitle_profile_supports_external(&item, &options) {
            apply_direct_external_text_subtitle_contract(
                media_source,
                &token.access_token,
                &item.id.simple().to_string(),
                &play_session_id,
                is_plugin_vod_remote_media(metadata),
            );
        }
    }

    Ok(Json(serde_json::json!({
        "MediaSources": media_sources,
        "PlaySessionId": play_session_id,
    })))
}

/// Do not ask a remote origin to seek into the tiny tail of an item that Jellyfin already
/// considers completed. Remote Matroska sources may need several range requests to find that
/// final cluster; Android cancels the first HLS segment while the seek is still warming up and
/// appears to require several play attempts. This mirrors `playback_report_outcome`'s completion
/// threshold while preserving ordinary resume positions and explicit seeks below it.
fn normalize_completed_remote_resume_position(
    item: &MediaItem,
    metadata: Option<&serde_json::Value>,
    options: &mut PlaybackInfoOptions,
) {
    if !is_xtream_remote_media(metadata)
        || !playback_position_reached_played_threshold(
            item.runtime_ticks,
            options.start_position_ticks,
        )
    {
        return;
    }

    tracing::info!(
        item_id = %item.id,
        requested_start_position_ticks = options.start_position_ticks,
        runtime_ticks = item.runtime_ticks,
        "resetting completed remote playback resume position"
    );
    options.start_position_ticks = 0;
}

// Android Media3 downloads External WebVTT as one finite document. Some Xtream origins expose
// remote MKV files in bounded chunks, so a full-file subtitle extraction either truncates at the
// first chunk or delays playback while the server reads the entire episode. Prefer the existing
// synchronized HLS WebVTT sidecar for this client: A/V remain stream-copy whenever its HLS profile
// accepts their codecs.
fn apply_android_remote_subtitle_hls_policy(
    item: &MediaItem,
    metadata: Option<&serde_json::Value>,
    client: &str,
    options: &mut PlaybackInfoOptions,
) {
    if !is_xtream_remote_media(metadata)
        || !client.eq_ignore_ascii_case("Jellyfin for Android")
        || options.subtitle_stream_index.is_none_or(|index| index < 0)
    {
        return;
    }

    if playback_profile_video_codec_compatible(item, options)
        && let Some(codec) = media_item_stream_codec(item, "Video")
        && let Some(profiles) = options.transcoding_profiles.as_mut()
    {
        for profile in profiles.iter_mut().filter(|profile| {
            profile
                .protocols
                .iter()
                .any(|protocol| protocol.eq_ignore_ascii_case("hls"))
        }) {
            if !profile
                .video_codecs
                .iter()
                .any(|candidate| candidate.eq_ignore_ascii_case(&codec))
            {
                profile.video_codecs.push(codec.clone());
            }
        }
    }
    options.subtitle_profiles = Some(vec![SubtitleProfileMatcher {
        format: Some("webvtt".to_string()),
        method: Some("hls".to_string()),
    }]);
    // The Android client's track selector has no branch for Jellyfin's `Hls` subtitle delivery
    // method. The renditions are already part of our HLS master manifest, so expose them as
    // embedded tracks to make every rendition selectable without creating a second sidecar input.
    options.hls_subtitles_as_embedded = true;
}

/// A TV client that can decode the source video directly can keep that codec while HLS narrows a
/// plugin-VOD stream to the selected audio/subtitle tracks. Device profiles commonly list only
/// H264 in their transcoding profile even when their direct profile accepts HEVC; extending the
/// HLS profile here avoids needlessly re-encoding video merely to switch audio.
fn apply_plugin_vod_stream_selection_hls_policy(
    item: &MediaItem,
    metadata: Option<&serde_json::Value>,
    client: &str,
    options: &mut PlaybackInfoOptions,
) {
    if !is_plugin_vod_remote_media(metadata) || !plugin_vod_tv_client_requires_selected_hls(client)
    {
        return;
    }
    // Wholphin and Jellyfin Android TV both construct external Media3 subtitle sources before
    // playback starts. An HLS/Embed descriptor is instead matched against rendition groups in the
    // A/V manifest; MAGSTV subtitles are independent JIT resources and have no such embedded
    // group. Advertise every text track through Jellyfin's authenticated WebVTT contract from the
    // initial PlaybackInfo response, so changing subtitle selection can take effect in place.
    if item.media_streams.iter().any(|stream| {
        json_string_field(stream, "Type")
            .is_some_and(|stream_type| stream_type.eq_ignore_ascii_case("Subtitle"))
            && json_string_field(stream, "Codec")
                .is_some_and(|codec| is_text_subtitle_codec(&codec))
    }) {
        options.subtitle_profiles = Some(vec![SubtitleProfileMatcher {
            format: Some("webvtt".to_string()),
            method: Some("external".to_string()),
        }]);
        options.hls_subtitles_as_embedded = false;
    }
    if !plugin_vod_has_nondefault_stream_selection(item, options) {
        return;
    }
    options.plugin_vod_selection_hls = true;
    if !playback_profile_video_codec_compatible(item, options) {
        return;
    }
    let Some(codec) = media_item_stream_codec(item, "Video") else {
        return;
    };
    let Some(profiles) = options.transcoding_profiles.as_mut() else {
        return;
    };
    for profile in profiles.iter_mut().filter(|profile| {
        profile
            .protocols
            .iter()
            .any(|protocol| protocol.eq_ignore_ascii_case("hls"))
    }) {
        if !profile
            .video_codecs
            .iter()
            .any(|candidate| candidate.eq_ignore_ascii_case(&codec))
        {
            profile.video_codecs.push(codec.clone());
        }
    }
}

fn plugin_vod_tv_client_requires_selected_hls(client: &str) -> bool {
    let client = client.trim().to_ascii_lowercase();
    client == "wholphin"
        || client == "jellyfin android tv"
        || client.starts_with("jellyfin+android+tv+")
}

fn live_tv_playback_info_response(
    channel: &serde_json::Value,
    access_token: &str,
    mut options: PlaybackInfoOptions,
) -> Result<Json<serde_json::Value>, ApiError> {
    let public_channel_id = json_string_field(channel, "Id")
        .ok_or_else(|| ApiError::not_found("Live TV item not found"))?;
    let playback_channel_id =
        live_tv_channel_playback_id(channel).unwrap_or_else(|| public_channel_id.clone());
    let mut media_source = live_tv_channel_media_source(channel)?;
    let selected_subtitle_stream_index = options
        .subtitle_stream_index
        .filter(|index| *index >= 0)
        .filter(|index| {
            media_source["MediaStreams"]
                .as_array()
                .is_some_and(|streams| {
                    streams.iter().any(|stream| {
                        json_string_field(stream, "Type")
                            .is_some_and(|kind| kind.eq_ignore_ascii_case("Subtitle"))
                            && json_i64_field(stream, "Index") == Some(*index)
                    })
                })
        });
    let play_session_id = live_tv_channel_hls_play_session_id_for_selection(
        &playback_channel_id,
        selected_subtitle_stream_index,
    );
    if let Some(media_source) = media_source.as_object_mut() {
        let direct_play_supported = options.enable_direct_play
            && media_source
                .get("SupportsDirectPlay")
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(false);
        let transcode_supported = options.enable_transcoding
            && media_source
                .get("SupportsTranscoding")
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(false)
            && configured_ffmpeg_mode() != FfmpegMode::Disabled
            && live_tv_hls_transcoding_profile_supported(&options);
        // Jellyfin's "DirectStream" normally means that the server may remux the source into a
        // client-compatible container.  This endpoint is a CPU-free byte proxy and therefore
        // preserves the provider's MPEG-TS container.  Advertising it alongside HLS makes
        // Jellyfin Web choose the raw TS URL, which HTMLMediaElement cannot play and leaves the
        // UI loading forever.  Prefer the compatible HLS remux whenever the client offers an HLS
        // streaming profile; retain raw TS as a fallback for native clients that explicitly
        // disable (or do not advertise) HLS.
        let direct_stream_supported = options.enable_direct_stream
            && !transcode_supported
            && media_source
                .get("SupportsDirectStream")
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(false);
        media_source.insert(
            "SupportsDirectPlay".to_string(),
            serde_json::json!(direct_play_supported),
        );
        media_source.insert(
            "SupportsDirectStream".to_string(),
            serde_json::json!(direct_stream_supported),
        );
        media_source.insert(
            "SupportsTranscoding".to_string(),
            serde_json::json!(transcode_supported),
        );
        if transcode_supported {
            let mut url =
                hls_master_url("Video", &public_channel_id, &play_session_id, access_token);
            if let Some(index) = selected_subtitle_stream_index {
                url.push_str(&format!("&SubtitleStreamIndex={index}"));
            }
            media_source.insert("TranscodingUrl".to_string(), serde_json::json!(url));
        } else {
            media_source.remove("TranscodingUrl");
        }
        if !direct_stream_supported {
            media_source.remove("DirectStreamUrl");
        }
        tracing::info!(
            channel_id = %playback_channel_id,
            delivery_mode = if transcode_supported { "hls-remux" } else { "direct-ts-fallback" },
            supports_direct_stream = direct_stream_supported,
            supports_transcoding = transcode_supported,
            ffmpeg_mode = ffmpeg_mode_name(configured_ffmpeg_mode()),
            "selected live TV playback delivery mode"
        );
        options.subtitle_stream_index = selected_subtitle_stream_index.or_else(|| {
            options
                .subtitle_stream_index
                .filter(|subtitle_stream_index| *subtitle_stream_index < 0)
        });
        apply_playback_stream_selection(media_source, &options);
    }
    Ok(Json(serde_json::json!({
        "MediaSources": [media_source],
        "PlaySessionId": play_session_id,
    })))
}

fn live_tv_hls_transcoding_profile_supported(options: &PlaybackInfoOptions) -> bool {
    options
        .transcoding_profiles
        .as_ref()
        .is_none_or(|profiles| {
            profiles.iter().any(|profile| {
                profile
                    .profile_type
                    .as_deref()
                    .is_none_or(|profile_type| profile_type.eq_ignore_ascii_case("Video"))
                    && profile
                        .context
                        .as_deref()
                        .is_none_or(|context| context.eq_ignore_ascii_case("Streaming"))
                    && (profile.protocols.is_empty()
                        || profile
                            .protocols
                            .iter()
                            .any(|protocol| protocol.eq_ignore_ascii_case("hls")))
                    && (profile.containers.is_empty()
                        || profile
                            .containers
                            .iter()
                            .any(|container| matches!(container.as_str(), "ts" | "mpegts")))
            })
        })
}

async fn active_playback_session_for_user_item(
    db: &Database,
    user_id: Uuid,
    item_id: Uuid,
) -> Result<Option<ActivePlaybackSession>, ApiError> {
    Ok(db
        .active_playback_sessions()
        .await?
        .into_iter()
        .find(|session| session.user_id == user_id && session.item.id == item_id))
}

fn apply_playback_info_state_defaults(
    options: &mut PlaybackInfoOptions,
    playback: Option<&PlaybackState>,
    active_playback: Option<&ActivePlaybackSession>,
) {
    let explicit_stream_selection =
        options.audio_stream_index.is_some() || options.subtitle_stream_index.is_some();

    if options.audio_stream_index.is_none() {
        options.audio_stream_index = active_playback
            .and_then(|session| session.audio_stream_index)
            .or_else(|| playback.and_then(|state| state.audio_stream_index));
    }
    if options.subtitle_stream_index.is_none() {
        options.subtitle_stream_index = active_playback
            .and_then(|session| session.subtitle_stream_index)
            .or_else(|| playback.and_then(|state| state.subtitle_stream_index));
    }

    if options.start_position_ticks_provided {
        return;
    }

    if let Some(position_ticks) = active_playback
        .map(|session| session.position_ticks)
        .filter(|position_ticks| *position_ticks > 0)
    {
        options.start_position_ticks = position_ticks;
        return;
    }

    if explicit_stream_selection
        && let Some(position_ticks) = playback
            .filter(|state| !state.played)
            .map(|state| state.position_ticks)
            .filter(|position_ticks| *position_ticks > 0)
    {
        options.start_position_ticks = position_ticks;
    }
}

async fn playback_transcode_info_response(
    state: &AppState,
    user: &User,
    token: &DeviceToken,
    input: PlaybackTranscodeInput<'_>,
) -> Result<Json<serde_json::Value>, ApiError> {
    let PlaybackTranscodeInput {
        item,
        metadata,
        item_json,
        mut options,
        decision,
    } = input;
    let play_session_id = Uuid::new_v4().simple().to_string();
    let item_id = item.id.simple().to_string();

    let streams = media_item_streams(item);
    let include_video = item.media_type == "Video";
    options.burn_in_subtitle =
        include_video && selected_subtitle_stream_is_image(&streams, options.subtitle_stream_index);
    if include_video {
        options.start_position_ticks =
            hls_effective_start_position_ticks(options.start_position_ticks, item.runtime_ticks);
    }
    let selection = TranscodeStreamSelection {
        video_stream_index: if is_xtream_remote_media(metadata) {
            None
        } else {
            include_video
                .then(|| first_stream_index(&streams, "Video"))
                .flatten()
        },
        audio_stream_index: if is_xtream_remote_media(metadata) {
            options.audio_stream_index
        } else {
            options
                .audio_stream_index
                .or_else(|| default_audio_stream_index(&streams))
        },
        subtitle_stream_index: options.subtitle_stream_index,
    };
    let dedupe_key = playback_hls_transcode_dedupe_key_with_output(
        user.id,
        item,
        &selection,
        options.start_position_ticks,
        decision.video,
        decision.audio,
        decision.output,
    );
    let dedupe_lock = transcode_dedupe_lock(&dedupe_key).await;
    let _dedupe_guard = dedupe_lock.lock().await;
    // Different seek positions deliberately have different dedupe keys. Serialize the complete
    // claim/supersede/spawn transition for one user's device as well, otherwise two concurrent
    // seeks can each mark the other's not-yet-started session stopped and then both spawn FFmpeg.
    let device_lock = transcode_device_lock(user.id, &token.device_id).await;
    let _device_guard = device_lock.lock().await;

    if let Some(session) = reusable_hls_transcode_session(&state.db, &dedupe_key).await? {
        return playback_transcode_session_info_response(
            item_json,
            &item.media_type,
            &token.access_token,
            &item_id,
            &session.play_session_id,
            &options,
            &decision,
        );
    }

    let disk_reservation = reserve_transcode_disk_capacity().await?;
    let layout = HlsTranscodeLayout::new(transcode_temp_root(), &play_session_id);
    tokio::fs::create_dir_all(&layout.session_dir).await?;
    let input_relay = if is_xtream_remote_media(metadata) || is_plugin_vod_remote_media(metadata) {
        Some(register_internal_remote_relay(
            state,
            InternalRemoteRelayTarget::MediaItem {
                item_id: item.id,
                user_context: Some(plugin_user_context(user, token)),
            },
            INTERNAL_REMOTE_RELAY_TRANSCODE_TTL,
        )?)
    } else {
        None
    };
    let input_path = input_relay
        .as_ref()
        .map(InternalRemoteRelayLease::url)
        .unwrap_or(&item.path)
        .to_string();
    // Keep the initially selected text subtitle in the same FFmpeg input as A/V. FFmpeg publishes
    // it as the companion `main_vtt.m3u8` rendition, and subtitle_stream_response serves those
    // already-produced segments through the ordinary subtitle URLs. This is particularly
    // important for remote Xtream media: opening a second random-access reader while the video is
    // already consuming the provider can block until Media3 abandons the subtitle request during
    // resume. The HLS command's bounded interleave window prevents a sparse text track from holding
    // back A/V segments. Other languages remain independent renditions and are extracted only when
    // the user switches to them.
    let mut ffmpeg_selection = selection.clone();
    if is_plugin_vod_remote_media(metadata) {
        // Plugin VOD subtitles are separate, JIT-resolved resources rather than streams in the
        // provider's MPEG-TS payload. Keep the public selection on the transcode session (and in
        // PlaybackInfo), but never ask FFmpeg to map that public index from the media input.
        ffmpeg_selection.subtitle_stream_index = Some(-1);
    }
    let mut request = HlsTranscodeRequest::new(
        input_path,
        layout.media_playlist_path.to_string_lossy().to_string(),
        layout.segment_pattern_string(),
        ffmpeg_selection,
    );
    request.start_position_ticks = options.start_position_ticks;
    align_hls_request_segment_timeline(&mut request);
    request.include_video = include_video;
    // FFmpeg's `vod` HLS playlist is not published until the finite input reaches EOF. Most
    // library items have a duration, so Jellyrin can serve its synthetic seekable playlist while
    // FFmpeg fills segments in the background. Opaque provider items may legitimately have no
    // duration, though; in that case the media-playlist route has to serve FFmpeg's physical
    // playlist. Use the incrementally published `event` form so Web receives it after the first
    // segment instead of waiting for the entire movie to transcode.
    request.event_playlist = hls_event_playlist_required(item.runtime_ticks);
    request.burn_in_subtitle = options.burn_in_subtitle;
    request.video_mode = decision.video;
    request.audio_mode = decision.audio;
    apply_playback_output_constraints(&mut request, decision.output);
    if is_xtream_remote_media(metadata) || is_plugin_vod_remote_media(metadata) {
        let (readrate_percent, initial_burst_seconds) = remote_vod_readrate();
        request.input_readrate_percent = readrate_percent;
        request.input_readrate_initial_burst_seconds = initial_burst_seconds;
    }
    let plan = build_hls_transcode_plan(&request, false, configured_ffmpeg_mode());

    let (session, claimed_new_session) = state
        .db
        .claim_transcode_session(
            &dedupe_key,
            UpsertTranscodeSession {
                play_session_id: play_session_id.clone(),
                dedupe_key: Some(dedupe_key.clone()),
                device_id: Some(token.device_id.clone()),
                user_id: user.id,
                item_id: item.id,
                media_source_id: Some(item_id.clone()),
                audio_stream_index: selection.audio_stream_index,
                subtitle_stream_index: selection.subtitle_stream_index,
                video_stream_index: selection.video_stream_index,
                output_path: layout.media_playlist_path.to_string_lossy().to_string(),
                process_id: None,
                status: "starting".to_string(),
                progress_percent: None,
                position_ticks: options.start_position_ticks,
                start_position_ticks: options.start_position_ticks,
            },
        )
        .await?;
    let play_session_id = session.play_session_id;
    if claimed_new_session {
        stop_superseded_device_transcode_sessions(
            &state.db,
            user.id,
            &token.device_id,
            &play_session_id,
        )
        .await;
        spawn_hls_transcode_task(
            state.db.clone(),
            play_session_id.clone(),
            plan,
            input_relay,
            disk_reservation,
        )
        .await;
    } else {
        drop(disk_reservation);
        cleanup_hls_transcode_dir(&layout.session_dir).await;
    }

    playback_transcode_session_info_response(
        item_json,
        &item.media_type,
        &token.access_token,
        &item_id,
        &play_session_id,
        &options,
        &decision,
    )
}

fn hls_event_playlist_required(runtime_ticks: Option<i64>) -> bool {
    runtime_ticks.is_none_or(|runtime_ticks| runtime_ticks <= 0)
}

/// Stop a device's other in-flight transcodes before starting a new one.
///
/// The dedupe key includes the start position, so seeking always claims a new play session while
/// the
/// abandoned FFmpeg job keeps the single admission slot until its idle timeout. The new session
/// would
/// otherwise wait for capacity and fail, which a client shows as an endless spinner. A client plays
/// one stream per device, so superseding its previous job is the same contract Jellyfin applies
/// when
/// a device starts a new encode.
async fn stop_superseded_device_transcode_sessions(
    db: &Database,
    user_id: Uuid,
    device_id: &str,
    keep_play_session_id: &str,
) {
    let sessions = match db.active_transcode_sessions().await {
        Ok(sessions) => sessions,
        Err(error) => {
            tracing::warn!(%error, "failed to list active transcode sessions");
            return;
        }
    };
    for session in sessions {
        if !transcode_session_is_superseded(
            session.user_id,
            session.device_id.as_deref(),
            &session.play_session_id,
            user_id,
            device_id,
            keep_play_session_id,
        ) {
            continue;
        }
        let stop_sender = transcode_stop_registry()
            .lock()
            .await
            .remove(&session.play_session_id);
        if let Some(stop_sender) = stop_sender {
            if let Err(error) = db
                .update_transcode_session_status(&session.play_session_id, "stopping")
                .await
            {
                tracing::warn!(%error, "failed to mark a superseded transcode session stopping");
            }
            // The task itself records the terminal status, releases capacity and clears its files.
            let _ = stop_sender.send(());
        } else {
            if let Err(error) = db
                .update_transcode_session_status(&session.play_session_id, "stopped")
                .await
            {
                tracing::warn!(%error, "failed to mark a superseded transcode session stopped");
            }
            cleanup_hls_transcode_files(&session.output_path).await;
        }
    }
}

fn transcode_session_is_superseded(
    session_user_id: Uuid,
    session_device_id: Option<&str>,
    session_play_session_id: &str,
    user_id: Uuid,
    device_id: &str,
    keep_play_session_id: &str,
) -> bool {
    session_user_id == user_id
        && session_device_id == Some(device_id)
        && session_play_session_id != keep_play_session_id
}

fn playback_transcode_session_info_response(
    item_json: serde_json::Value,
    media_type: &str,
    access_token: &str,
    item_id: &str,
    play_session_id: &str,
    options: &PlaybackInfoOptions,
    decision: &TranscodeDecision,
) -> Result<Json<serde_json::Value>, ApiError> {
    let mut media_sources = item_json["MediaSources"].clone();
    if let Some(media_source) = media_sources
        .as_array_mut()
        .and_then(|sources| sources.first_mut())
        .and_then(serde_json::Value::as_object_mut)
    {
        media_source.insert("SupportsDirectPlay".to_string(), serde_json::json!(false));
        media_source.insert(
            "SupportsDirectStream".to_string(),
            serde_json::json!(
                decision.delivery == DeliveryMode::HlsRemux
                    && !selected_text_subtitle_prefers_hls(options)
            ),
        );
        media_source.insert("SupportsTranscoding".to_string(), serde_json::json!(true));
        media_source.insert(
            "TranscodingReasons".to_string(),
            serde_json::json!(decision.reasons),
        );
        media_source.insert(
            "TranscodingSubProtocol".to_string(),
            serde_json::json!("hls"),
        );
        media_source.insert("TranscodingContainer".to_string(), serde_json::json!("ts"));
        media_source.insert("Container".to_string(), serde_json::json!("ts"));
        media_source.insert(
            "TranscodingUrl".to_string(),
            serde_json::json!(hls_master_url(
                media_type,
                item_id,
                play_session_id,
                access_token
            )),
        );
        media_source.remove("DirectStreamUrl");
        apply_playback_stream_selection(media_source, options);
        apply_hls_transcode_stream_contract(
            media_source,
            media_type,
            access_token,
            item_id,
            play_session_id,
            options,
            decision,
        );
    }

    Ok(Json(serde_json::json!({
        "MediaSources": media_sources,
        "PlaySessionId": play_session_id,
    })))
}

fn encoded_audio_channel_layout(channels: u8) -> &'static str {
    match channels {
        1 => "mono",
        2 => "stereo",
        3 => "2.1",
        4 => "4.0",
        5 => "5.0",
        6 => "5.1",
        7 => "6.1",
        8 => "7.1",
        _ => "stereo",
    }
}

fn apply_direct_external_text_subtitle_contract(
    media_source: &mut serde_json::Map<String, serde_json::Value>,
    access_token: &str,
    item_id: &str,
    play_session_id: &str,
    preserve_external_flag: bool,
) {
    let Some(streams) = media_source
        .get_mut("MediaStreams")
        .and_then(serde_json::Value::as_array_mut)
    else {
        return;
    };
    for stream in streams {
        let Some(stream) = stream.as_object_mut() else {
            continue;
        };
        let is_text_subtitle = stream
            .get("Type")
            .and_then(serde_json::Value::as_str)
            .is_some_and(|stream_type| stream_type.eq_ignore_ascii_case("Subtitle"))
            && stream
                .get("Codec")
                .and_then(serde_json::Value::as_str)
                .is_some_and(is_text_subtitle_codec);
        if !is_text_subtitle {
            continue;
        }
        let Some(index) = stream.get("Index").and_then(json_value_i64) else {
            continue;
        };
        stream.insert("Codec".to_string(), serde_json::json!("webvtt"));
        stream.insert("IsTextSubtitleStream".to_string(), serde_json::json!(true));
        stream.insert("DeliveryMethod".to_string(), serde_json::json!("External"));
        stream.insert(
            "IsExternal".to_string(),
            serde_json::json!(preserve_external_flag),
        );
        stream.insert(
            "SupportsExternalStream".to_string(),
            serde_json::json!(true),
        );
        stream.insert(
            "DeliveryUrl".to_string(),
            serde_json::json!(format!(
                "/Videos/{item_id}/{item_id}/Subtitles/{index}/Stream.vtt?api_key={access_token}&PlaySessionId={play_session_id}&JellyrinSegmented=true&StartPositionTicks=0&EndPositionTicks={}",
                DIRECT_HLS_SUBTITLE_SEGMENT_SECONDS * 2 * 10_000_000
            )),
        );
    }
}

fn apply_hls_transcode_stream_contract(
    media_source: &mut serde_json::Map<String, serde_json::Value>,
    media_type: &str,
    access_token: &str,
    item_id: &str,
    play_session_id: &str,
    options: &PlaybackInfoOptions,
    decision: &TranscodeDecision,
) {
    let is_remote = media_source
        .get("IsRemote")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let selected_audio_stream_index = options.audio_stream_index.or_else(|| {
        media_source
            .get("MediaStreams")
            .and_then(serde_json::Value::as_array)
            .and_then(|streams| default_audio_stream_index(streams))
    });
    let selected_subtitle_stream_index = options
        .subtitle_stream_index
        .and_then(|index| (index >= 0).then_some(index));

    if let Some(streams) = media_source
        .get_mut("MediaStreams")
        .and_then(serde_json::Value::as_array_mut)
    {
        if options.hls_subtitles_as_embedded {
            mark_unselected_hls_audio_streams_external(streams, selected_audio_stream_index);
        }
        for stream in streams {
            let Some(stream) = stream.as_object_mut() else {
                continue;
            };
            let stream_type = stream
                .get("Type")
                .and_then(serde_json::Value::as_str)
                .unwrap_or_default()
                .to_ascii_lowercase();
            match stream_type.as_str() {
                "video" if media_type == "Video" && decision.video == HlsStreamMode::Encode => {
                    stream.insert("Codec".to_string(), serde_json::json!("h264"));
                    stream.insert(
                        "Profile".to_string(),
                        serde_json::json!(
                            decision
                                .output
                                .video_profile
                                .unwrap_or(H264Profile::Main)
                                .as_str()
                        ),
                    );
                    stream.insert("PixelFormat".to_string(), serde_json::json!("yuv420p"));
                    stream.insert(
                        "BitDepth".to_string(),
                        serde_json::json!(decision.output.video_bit_depth.unwrap_or(8)),
                    );
                    if let Some(level) = decision.output.video_level {
                        stream.insert("Level".to_string(), serde_json::json!(level));
                    }
                    if let Some(frame_rate) = decision.output.max_video_frame_rate_millihertz {
                        let frame_rate = f64::from(frame_rate) / 1_000.0;
                        stream.insert("RealFrameRate".to_string(), serde_json::json!(frame_rate));
                        stream.insert(
                            "ReferenceFrameRate".to_string(),
                            serde_json::json!(frame_rate),
                        );
                    }
                    stream.insert("VideoRange".to_string(), serde_json::json!("SDR"));
                    stream.insert("VideoRangeType".to_string(), serde_json::json!("SDR"));
                    if let Some(max_width) = decision.output.max_width {
                        let width = stream
                            .get("Width")
                            .and_then(json_value_i64)
                            .and_then(positive_u32)
                            .map_or(max_width, |width| width.min(max_width));
                        stream.insert("Width".to_string(), serde_json::json!(width));
                    }
                    if let Some(max_height) = decision.output.max_height {
                        let height = stream
                            .get("Height")
                            .and_then(json_value_i64)
                            .and_then(positive_u32)
                            .map_or(max_height, |height| height.min(max_height));
                        stream.insert("Height".to_string(), serde_json::json!(height));
                    }
                    if let Some(bitrate) = decision.output.video_bitrate {
                        stream.insert("BitRate".to_string(), serde_json::json!(bitrate));
                    }
                    let display_title = stream
                        .get("Height")
                        .and_then(json_value_i64)
                        .and_then(positive_u32)
                        .map_or_else(
                            || "H264 SDR".to_string(),
                            |height| format!("{height}p H264 SDR"),
                        );
                    stream.insert("DisplayTitle".to_string(), serde_json::json!(display_title));
                }
                "audio" if decision.audio == HlsStreamMode::Encode => {
                    let language = stream
                        .get("Language")
                        .and_then(serde_json::Value::as_str)
                        .map(str::to_owned);
                    let title = stream
                        .get("Title")
                        .and_then(serde_json::Value::as_str)
                        .map(str::to_owned);
                    let is_default = stream
                        .get("IsDefault")
                        .and_then(serde_json::Value::as_bool)
                        .unwrap_or(false);
                    let channels = decision.output.audio_channels.unwrap_or(2);
                    let channel_layout = encoded_audio_channel_layout(channels);
                    stream.insert("Codec".to_string(), serde_json::json!("aac"));
                    if let Some(profile) = decision.output.audio_profile {
                        stream.insert("Profile".to_string(), serde_json::json!(profile.as_str()));
                    }
                    stream.insert("Channels".to_string(), serde_json::json!(channels));
                    stream.insert(
                        "ChannelLayout".to_string(),
                        serde_json::json!(channel_layout),
                    );
                    stream.insert(
                        "BitRate".to_string(),
                        serde_json::json!(decision.output.audio_bitrate.unwrap_or(192_000)),
                    );
                    stream.insert(
                        "DisplayTitle".to_string(),
                        serde_json::json!(media_stream_display_title(
                            "Audio",
                            "aac",
                            language.as_deref(),
                            title.as_deref(),
                            Some(i64::from(channels)),
                            Some(channel_layout),
                            is_default,
                            false,
                        )),
                    );
                }
                "subtitle" => {
                    let index = stream.get("Index").and_then(json_value_i64);
                    let selected = selected_subtitle_stream_index
                        .is_some_and(|selected| index == Some(selected));
                    if selected && !options.burn_in_subtitle {
                        stream.insert("Codec".to_string(), serde_json::json!("webvtt"));
                        stream.insert("IsTextSubtitleStream".to_string(), serde_json::json!(true));
                    }
                    let codec = stream
                        .get("Codec")
                        .and_then(serde_json::Value::as_str)
                        .unwrap_or_default()
                        .to_string();
                    if media_type == "Video"
                        && !options.burn_in_subtitle
                        && index.is_some()
                        && is_text_subtitle_codec(&codec)
                    {
                        let index = index.unwrap_or_default();
                        stream.insert("Codec".to_string(), serde_json::json!("webvtt"));
                        stream.insert("IsTextSubtitleStream".to_string(), serde_json::json!(true));
                        let use_hls = !is_remote || selected_text_subtitle_prefers_hls(options);
                        let hls_as_embedded = use_hls && options.hls_subtitles_as_embedded;
                        stream.insert(
                            "DeliveryMethod".to_string(),
                            serde_json::json!(if hls_as_embedded {
                                "Embed"
                            } else if use_hls {
                                "Hls"
                            } else {
                                "External"
                            }),
                        );
                        stream.insert(
                            "IsExternal".to_string(),
                            serde_json::json!(is_remote && !use_hls),
                        );
                        stream.insert(
                            "SupportsExternalStream".to_string(),
                            serde_json::json!(!hls_as_embedded),
                        );
                        if hls_as_embedded {
                            stream.remove("DeliveryUrl");
                        } else {
                            let delivery_url = if !use_hls {
                                format!(
                                    "/Videos/{item_id}/{item_id}/Subtitles/{index}/Stream.vtt?PlaySessionId={play_session_id}&api_key={access_token}"
                                )
                            } else {
                                format!(
                                    "/Videos/{item_id}/{item_id}/Subtitles/{index}/subtitles.m3u8?api_key={access_token}&segmentLength={}",
                                    DEFAULT_HLS_SEGMENT_TIME_SECONDS
                                )
                            };
                            stream
                                .insert("DeliveryUrl".to_string(), serde_json::json!(delivery_url));
                        }
                    }
                }
                _ => {}
            }
        }
    }
}

// Jellyfin Android selects an embedded subtitle by counting every preceding MediaStream whose
// `IsExternal` flag is false. An HLS transcode contains only the selected audio track, even when
// the source advertises several audio streams. Leaving the omitted tracks marked as embedded
// shifts every following subtitle group (for example, source subtitle 4 selects HLS subtitle 5).
// Keep the selected audio embedded and describe the other source audio tracks as unavailable in
// the current HLS output. Audio changes already restart transcoded playback, so the newly selected
// source track becomes embedded in the replacement session.
fn mark_unselected_hls_audio_streams_external(
    streams: &mut [serde_json::Value],
    selected_audio_stream_index: Option<i64>,
) {
    let Some(selected_audio_stream_index) = selected_audio_stream_index else {
        return;
    };
    for stream in streams {
        let Some(stream) = stream.as_object_mut() else {
            continue;
        };
        let is_audio = stream
            .get("Type")
            .and_then(serde_json::Value::as_str)
            .is_some_and(|stream_type| stream_type.eq_ignore_ascii_case("Audio"));
        if !is_audio {
            continue;
        }
        let is_selected =
            stream.get("Index").and_then(json_value_i64) == Some(selected_audio_stream_index);
        stream.insert("IsExternal".to_string(), serde_json::json!(!is_selected));
    }
}

fn selected_subtitle_stream_is_image(
    streams: &[serde_json::Value],
    subtitle_stream_index: Option<i64>,
) -> bool {
    let Some(selected_index) =
        subtitle_stream_index.and_then(|index| (index >= 0).then_some(index))
    else {
        return false;
    };

    streams.iter().any(|stream| {
        let Some(stream) = stream.as_object() else {
            return false;
        };
        let is_selected_subtitle = stream
            .get("Type")
            .and_then(serde_json::Value::as_str)
            .is_some_and(|stream_type| stream_type.eq_ignore_ascii_case("Subtitle"))
            && stream.get("Index").and_then(json_value_i64) == Some(selected_index);
        if !is_selected_subtitle {
            return false;
        }

        stream
            .get("Codec")
            .and_then(serde_json::Value::as_str)
            .is_some_and(|codec| !is_text_subtitle_codec(codec))
    })
}

fn hls_transcode_dedupe_key(
    user_id: Uuid,
    item: &MediaItem,
    selection: &TranscodeStreamSelection,
    start_position_ticks: i64,
) -> String {
    format!(
        "hls:ts:{}:{}:{}:{}:{}:{}:{}",
        user_id.simple(),
        item.id.simple(),
        item.id.simple(),
        selection
            .video_stream_index
            .map_or_else(|| "-".to_string(), |index| index.to_string()),
        selection
            .audio_stream_index
            .map_or_else(|| "-".to_string(), |index| index.to_string()),
        selection
            .subtitle_stream_index
            .map_or_else(|| "-".to_string(), |index| index.to_string()),
        start_position_ticks.max(0)
    )
}

fn playback_hls_transcode_dedupe_key(
    user_id: Uuid,
    item: &MediaItem,
    selection: &TranscodeStreamSelection,
    start_position_ticks: i64,
    video_mode: HlsStreamMode,
    audio_mode: HlsStreamMode,
) -> String {
    let base = hls_transcode_dedupe_key(user_id, item, selection, start_position_ticks);
    if video_mode == HlsStreamMode::Encode && audio_mode == HlsStreamMode::Encode {
        return base;
    }

    format!(
        "{base}:video-{}:audio-{}",
        hls_stream_mode_key(video_mode),
        hls_stream_mode_key(audio_mode)
    )
}

fn playback_hls_transcode_dedupe_key_with_output(
    user_id: Uuid,
    item: &MediaItem,
    selection: &TranscodeStreamSelection,
    start_position_ticks: i64,
    video_mode: HlsStreamMode,
    audio_mode: HlsStreamMode,
    output: PlaybackOutputConstraints,
) -> String {
    let base = playback_hls_transcode_dedupe_key(
        user_id,
        item,
        selection,
        start_position_ticks,
        video_mode,
        audio_mode,
    );
    if output == PlaybackOutputConstraints::default() {
        return base;
    }
    format!(
        "{base}:limits:{}:{}:{}:{}:{}:{}:{}:{}:{}:{}",
        output_constraint_key(output.max_width),
        output_constraint_key(output.max_height),
        output_constraint_key(output.video_bitrate),
        output_constraint_key(output.audio_bitrate),
        output_text_constraint_key(output.video_profile.map(H264Profile::as_str)),
        output_constraint_key(output.video_level.map(u32::from)),
        output_constraint_key(output.video_bit_depth.map(u32::from)),
        output_constraint_key(output.max_video_frame_rate_millihertz),
        output_text_constraint_key(output.audio_profile.map(AacProfile::as_str)),
        output_constraint_key(output.audio_channels.map(u32::from)),
    )
}

fn apply_playback_output_constraints(
    request: &mut HlsTranscodeRequest,
    output: PlaybackOutputConstraints,
) {
    request.max_video_width = output.max_width;
    request.max_video_height = output.max_height;
    request.video_bitrate = output.video_bitrate;
    request.video_profile = output.video_profile;
    request.video_level = output.video_level;
    request.max_video_frame_rate_millihertz = output.max_video_frame_rate_millihertz;
    request.audio_bitrate = output.audio_bitrate;
    request.audio_profile = output.audio_profile;
    request.audio_channels = output.audio_channels;
}

fn output_constraint_key(value: Option<u32>) -> String {
    value.map_or_else(|| "-".to_string(), |value| value.to_string())
}

fn output_text_constraint_key(value: Option<&str>) -> &str {
    value.unwrap_or("-")
}

fn playback_output_constraints_from_dedupe_key(
    dedupe_key: Option<&str>,
) -> PlaybackOutputConstraints {
    let Some(parts) = dedupe_key.map(|key| key.split(':').collect::<Vec<_>>()) else {
        return PlaybackOutputConstraints::default();
    };
    let Some(index) = parts.iter().position(|part| *part == "limits") else {
        return PlaybackOutputConstraints::default();
    };
    PlaybackOutputConstraints {
        max_width: parts.get(index + 1).and_then(|value| value.parse().ok()),
        max_height: parts.get(index + 2).and_then(|value| value.parse().ok()),
        video_bitrate: parts.get(index + 3).and_then(|value| value.parse().ok()),
        audio_bitrate: parts.get(index + 4).and_then(|value| value.parse().ok()),
        video_profile: parts.get(index + 5).and_then(|value| match *value {
            "baseline" => Some(H264Profile::Baseline),
            "main" => Some(H264Profile::Main),
            "high" => Some(H264Profile::High),
            _ => None,
        }),
        video_level: parts
            .get(index + 6)
            .and_then(|value| value.parse::<u8>().ok()),
        video_bit_depth: parts
            .get(index + 7)
            .and_then(|value| value.parse::<u8>().ok()),
        max_video_frame_rate_millihertz: parts.get(index + 8).and_then(|value| value.parse().ok()),
        audio_profile: parts.get(index + 9).and_then(|value| match *value {
            "lc" => Some(AacProfile::LowComplexity),
            _ => None,
        }),
        audio_channels: parts
            .get(index + 10)
            .and_then(|value| value.parse::<u8>().ok()),
    }
}

fn playback_hls_modes_from_dedupe_key(
    dedupe_key: Option<&str>,
) -> Option<(HlsStreamMode, HlsStreamMode)> {
    let dedupe_key = dedupe_key?;
    let video = dedupe_key.split(':').find_map(|part| {
        part.strip_prefix("video-")
            .and_then(hls_stream_mode_from_key)
    });
    let audio = dedupe_key.split(':').find_map(|part| {
        part.strip_prefix("audio-")
            .and_then(hls_stream_mode_from_key)
    });
    match (video, audio) {
        (Some(video), Some(audio)) => Some((video, audio)),
        (None, None) => Some((HlsStreamMode::Encode, HlsStreamMode::Encode)),
        _ => None,
    }
}

fn hls_stream_mode_from_key(value: &str) -> Option<HlsStreamMode> {
    match value {
        "copy" => Some(HlsStreamMode::Copy),
        "encode" => Some(HlsStreamMode::Encode),
        "drop" => Some(HlsStreamMode::Drop),
        _ => None,
    }
}

fn hls_stream_mode_key(mode: HlsStreamMode) -> &'static str {
    match mode {
        HlsStreamMode::Copy => "copy",
        HlsStreamMode::Encode => "encode",
        HlsStreamMode::Drop => "drop",
    }
}

async fn transcode_dedupe_lock(key: &str) -> Arc<Mutex<()>> {
    let mut locks = transcode_dedupe_registry().lock().await;
    locks.lock_for(key.to_string())
}

async fn transcode_device_lock(user_id: Uuid, device_id: &str) -> Arc<Mutex<()>> {
    let mut locks = TRANSCODE_DEVICE_LOCKS
        .get_or_init(|| Mutex::new(WeakKeyedLockRegistry::new(KEYED_LOCK_REGISTRY_MAX_ENTRIES)))
        .lock()
        .await;
    locks.lock_for((user_id, device_id.to_owned()))
}

async fn hls_on_demand_generation_lock(play_session_id: &str) -> Arc<Mutex<()>> {
    let mut locks = HLS_ON_DEMAND_LOCKS
        .get_or_init(|| Mutex::new(WeakKeyedLockRegistry::new(KEYED_LOCK_REGISTRY_MAX_ENTRIES)))
        .lock()
        .await;
    locks.lock_for(play_session_id.to_string())
}

async fn hls_on_demand_generation_active(play_session_id: &str) -> bool {
    let lock = hls_on_demand_generation_lock(play_session_id).await;
    lock.try_lock().is_err()
}

fn transcode_dedupe_registry() -> &'static Mutex<WeakKeyedLockRegistry<String>> {
    TRANSCODE_DEDUPE_LOCKS
        .get_or_init(|| Mutex::new(WeakKeyedLockRegistry::new(KEYED_LOCK_REGISTRY_MAX_ENTRIES)))
}

async fn reusable_hls_transcode_session(
    db: &Database,
    dedupe_key: &str,
) -> Result<Option<TranscodeSession>, ApiError> {
    let sessions = db.transcode_sessions().await?;
    for session in sessions {
        if session.dedupe_key.as_deref() != Some(dedupe_key)
            || !matches!(
                session.status.as_str(),
                "starting" | "running" | "completed"
            )
        {
            continue;
        }
        if session.status == "completed"
            && !HlsTranscodeLayout::from_media_playlist_path(&session.output_path)
                .media_playlist_path
                .exists()
        {
            continue;
        }
        return Ok(Some(session));
    }
    Ok(None)
}

async fn spawn_hls_transcode_task(
    db: Database,
    play_session_id: String,
    plan: HlsTranscodePlan,
    input_relay: Option<InternalRemoteRelayLease>,
    disk_reservation: TranscodeDiskReservation,
) {
    let (stop_tx, mut stop_rx) = oneshot::channel();
    if let Some(previous_stop) = transcode_stop_registry()
        .lock()
        .await
        .insert(play_session_id.clone(), stop_tx)
    {
        let _ = previous_stop.send(());
    }
    touch_transcode_session(&play_session_id).await;
    register_transcode_execution(&play_session_id, configured_ffmpeg_mode(), &plan.primary).await;

    tokio::spawn(async move {
        let _input_relay = input_relay;
        let mut command = plan.primary;
        let mut fallback = plan.fallback;
        let mut attempt_count = 1u8;
        let final_status = loop {
            let kind = classify_transcode_command(&command);
            update_transcode_execution(
                &play_session_id,
                Some(kind),
                Some(attempt_count),
                if attempt_count == 1 {
                    "queued"
                } else {
                    "fallback-queued"
                },
                None,
                None,
            )
            .await;
            let outcome = run_vod_hls_attempt(
                &db,
                &play_session_id,
                &command,
                &mut stop_rx,
                &disk_reservation,
            )
            .await;
            let session = db
                .transcode_session_by_play_session_id(&play_session_id)
                .await
                .ok()
                .flatten();
            let first_segment_ready = if let Some(session) = &session {
                let layout = HlsTranscodeLayout::from_media_playlist_path(&session.output_path);
                hls_output_file_is_nonempty(
                    &layout.segment_path(hls_start_segment_number(session.start_position_ticks)),
                )
                .await
            } else {
                false
            };
            let retry_error = match &outcome {
                VodHlsAttemptOutcome::Process(exit) if !exit.success || !first_segment_ready => {
                    Some(("remux-exited-before-first-segment", exit.code))
                }
                VodHlsAttemptOutcome::WaitFailed => Some(("process-wait-failed", None)),
                _ => None,
            };
            if hls_remux_fallback_eligible(
                attempt_count,
                kind,
                first_segment_ready,
                retry_error.is_some(),
                fallback.is_some(),
            ) && let Some((error_code, exit_code)) = retry_error
                && let Some(next) = fallback.take()
            {
                update_transcode_execution(
                    &play_session_id,
                    None,
                    None,
                    "fallback-queued",
                    Some(error_code),
                    exit_code,
                )
                .await;
                let _ = db
                    .update_transcode_session_status(&play_session_id, "starting")
                    .await;
                if let Some(session) = &session {
                    let layout = HlsTranscodeLayout::from_media_playlist_path(&session.output_path);
                    cleanup_hls_transcode_dir(&layout.session_dir).await;
                    if let Err(error) = tokio::fs::create_dir_all(&layout.session_dir).await {
                        tracing::error!(%play_session_id, %error, "failed to prepare HLS fallback output");
                        break "failed";
                    }
                }
                tracing::warn!(%play_session_id, "remux produced no first segment; retrying once with encode");
                command = next;
                attempt_count = 2;
                continue;
            }
            break match outcome {
                VodHlsAttemptOutcome::Process(exit) if exit.success && first_segment_ready => {
                    "completed"
                }
                VodHlsAttemptOutcome::Stopped => "stopped",
                VodHlsAttemptOutcome::CapacityUnavailable => {
                    update_transcode_execution(
                        &play_session_id,
                        None,
                        None,
                        "failed",
                        Some("capacity-unavailable"),
                        None,
                    )
                    .await;
                    "failed"
                }
                VodHlsAttemptOutcome::SpawnFailed => {
                    update_transcode_execution(
                        &play_session_id,
                        None,
                        None,
                        "failed",
                        Some("spawn-failed"),
                        None,
                    )
                    .await;
                    "failed"
                }
                VodHlsAttemptOutcome::WaitFailed => {
                    update_transcode_execution(
                        &play_session_id,
                        None,
                        None,
                        "failed",
                        Some("process-wait-failed"),
                        None,
                    )
                    .await;
                    "failed"
                }
                VodHlsAttemptOutcome::Process(exit) => {
                    let error_code = if kind == TranscodeJobKind::Remux && !first_segment_ready {
                        "remux-exited-before-first-segment"
                    } else {
                        "process-exited"
                    };
                    update_transcode_execution(
                        &play_session_id,
                        None,
                        None,
                        "failed",
                        Some(error_code),
                        exit.code,
                    )
                    .await;
                    "failed"
                }
            };
        };
        update_transcode_execution(&play_session_id, None, None, final_status, None, None).await;
        let session = db
            .transcode_session_by_play_session_id(&play_session_id)
            .await
            .ok()
            .flatten();
        let _ = db
            .update_transcode_session_status(&play_session_id, final_status)
            .await;
        transcode_stop_registry()
            .lock()
            .await
            .remove(&play_session_id);
        forget_transcode_session_access(&play_session_id).await;
        if final_status != "completed"
            && let Some(session) = session
        {
            cleanup_hls_transcode_files(&session.output_path).await;
        }
    });
}

enum VodHlsAttemptOutcome {
    Process(jellyrin_transcode::TranscodeProcessExit),
    Stopped,
    CapacityUnavailable,
    SpawnFailed,
    WaitFailed,
}

async fn run_vod_hls_attempt(
    db: &Database,
    play_session_id: &str,
    command: &jellyrin_core::FfmpegCommandSpec,
    stop_rx: &mut oneshot::Receiver<()>,
    disk_reservation: &TranscodeDiskReservation,
) -> VodHlsAttemptOutcome {
    let permit = tokio::select! {
        permit = acquire_transcode_job(command) => match permit {
            Ok(permit) => permit,
            Err(error) => {
                tracing::error!(%play_session_id, %error, "failed to acquire FFmpeg capacity");
                return VodHlsAttemptOutcome::CapacityUnavailable;
            }
        },
        _ = &mut *stop_rx => return VodHlsAttemptOutcome::Stopped,
        _ = wait_for_transcode_idle(play_session_id, transcode_idle_timeout(false)) => {
            tracing::info!(%play_session_id, "stopped queued HLS transcode after idle timeout");
            return VodHlsAttemptOutcome::Stopped;
        },
        _ = disk_reservation.wait_until_exceeded() => {
            tracing::warn!(%play_session_id, "cancelled queued HLS transcode after storage quota was exceeded");
            return VodHlsAttemptOutcome::Stopped;
        }
    };
    let mut process = match spawn_transcode_process(command) {
        Ok(process) => process,
        Err(error) => {
            tracing::error!(%play_session_id, %error, "failed to spawn HLS transcode process");
            drop(permit);
            return VodHlsAttemptOutcome::SpawnFailed;
        }
    };
    let persistence_progress_rx = process.subscribe_progress();
    let observation_progress_rx = process.subscribe_progress();
    let resource_rx = process.subscribe_resources();
    let process_id = process.process_id();
    let mut runtime_ticks = None;
    if let Ok(Some(session)) = db
        .transcode_session_by_play_session_id(play_session_id)
        .await
    {
        runtime_ticks = session.item.runtime_ticks;
        let _ = db
            .upsert_transcode_session(UpsertTranscodeSession {
                play_session_id: play_session_id.to_string(),
                dedupe_key: session.dedupe_key,
                device_id: session.device_id,
                user_id: session.user_id,
                item_id: session.item.id,
                media_source_id: session.media_source_id,
                audio_stream_index: session.audio_stream_index,
                subtitle_stream_index: session.subtitle_stream_index,
                video_stream_index: session.video_stream_index,
                output_path: session.output_path,
                process_id: process_id.map(i64::from),
                status: "running".to_string(),
                progress_percent: session.progress_percent,
                position_ticks: session.position_ticks,
                start_position_ticks: session.start_position_ticks,
            })
            .await;
    }
    mark_transcode_process_started(play_session_id, process_id).await;
    update_transcode_execution(play_session_id, None, None, "running", None, None).await;
    let progress_task = spawn_transcode_progress_persistence_task(
        db.clone(),
        play_session_id.to_string(),
        persistence_progress_rx,
        runtime_ticks,
    );
    let observation_task = spawn_transcode_observation_task(
        play_session_id.to_string(),
        observation_progress_rx,
        resource_rx,
        runtime_ticks,
    );
    let mut stopped = false;
    let exit = tokio::select! {
        exit = process.wait() => exit,
        _ = &mut *stop_rx => { stopped = true; process.stop().await },
        _ = wait_for_transcode_idle(play_session_id, transcode_idle_timeout(false)) => {
            stopped = true;
            tracing::info!(%play_session_id, "stopped HLS transcode after idle timeout");
            process.stop().await
        },
        _ = disk_reservation.wait_until_exceeded() => {
            stopped = true;
            tracing::warn!(%play_session_id, "stopped HLS transcode after storage quota was exceeded");
            process.stop().await
        }
    };
    drop(process);
    let _ = progress_task.await;
    let _ = observation_task.await;
    drop(permit);
    if stopped {
        VodHlsAttemptOutcome::Stopped
    } else {
        match exit {
            Ok(exit) => VodHlsAttemptOutcome::Process(exit),
            Err(error) => {
                tracing::error!(%play_session_id, %error, "HLS transcode process wait failed");
                VodHlsAttemptOutcome::WaitFailed
            }
        }
    }
}

async fn hls_output_file_is_nonempty(path: &FsPath) -> bool {
    tokio::fs::metadata(path)
        .await
        .is_ok_and(|metadata| metadata.is_file() && metadata.len() > 0)
}

fn spawn_transcode_progress_persistence_task(
    db: Database,
    play_session_id: String,
    mut progress_rx: tokio::sync::broadcast::Receiver<jellyrin_core::FfmpegProgress>,
    runtime_ticks: Option<i64>,
) -> tokio::task::JoinHandle<()> {
    tokio::spawn(async move {
        let mut last_position_ticks = None;
        let mut last_persisted_at: Option<tokio::time::Instant> = None;
        let mut pending_position_ticks = None;
        while let Ok(progress) = progress_rx.recv().await {
            let Some(position_ticks) = progress.position_ticks() else {
                continue;
            };
            if last_position_ticks == Some(position_ticks) {
                continue;
            }
            last_position_ticks = Some(position_ticks);
            pending_position_ticks = Some(position_ticks);
            let should_persist = progress.is_complete()
                || last_persisted_at.is_none_or(|last_persisted_at| {
                    last_persisted_at.elapsed() >= TRANSCODE_PROGRESS_PERSIST_INTERVAL
                });
            if should_persist {
                persist_transcode_progress(&db, &play_session_id, position_ticks, runtime_ticks)
                    .await;
                last_persisted_at = Some(tokio::time::Instant::now());
                pending_position_ticks = None;
            }
        }
        if let Some(position_ticks) = pending_position_ticks {
            persist_transcode_progress(&db, &play_session_id, position_ticks, runtime_ticks).await;
        }
    })
}

async fn persist_transcode_progress(
    db: &Database,
    play_session_id: &str,
    position_ticks: i64,
    runtime_ticks: Option<i64>,
) {
    let progress_percent = transcode_progress_percent(position_ticks, runtime_ticks);
    if let Err(error) = db
        .update_transcode_session_progress(play_session_id, progress_percent, position_ticks)
        .await
    {
        tracing::warn!(%play_session_id, %error, "failed to persist HLS transcode progress");
    }
}

fn transcode_progress_percent(position_ticks: i64, runtime_ticks: Option<i64>) -> Option<f64> {
    let runtime_ticks = runtime_ticks?;
    if runtime_ticks <= 0 || position_ticks < 0 {
        return None;
    }
    Some(((position_ticks as f64 / runtime_ticks as f64) * 100.0).clamp(0.0, 100.0))
}

fn transcode_stop_registry() -> &'static Mutex<HashMap<String, oneshot::Sender<()>>> {
    TRANSCODE_STOPS.get_or_init(|| Mutex::new(HashMap::new()))
}

fn transcode_execution_registry() -> &'static Mutex<HashMap<String, TranscodeExecutionObservation>>
{
    TRANSCODE_EXECUTIONS.get_or_init(|| Mutex::new(HashMap::new()))
}

async fn register_transcode_execution(
    play_session_id: &str,
    policy_mode: FfmpegMode,
    command: &jellyrin_core::FfmpegCommandSpec,
) {
    let requested_mode = classify_transcode_command(command);
    let mut registry = transcode_execution_registry().lock().await;
    if registry.len() >= LIVE_HLS_SESSION_REGISTRY_MAX_ENTRIES
        && !registry.contains_key(play_session_id)
        && let Some(oldest) = registry
            .iter()
            .min_by_key(|(_, observation)| observation.updated_at)
            .map(|(id, _)| id.clone())
    {
        registry.remove(&oldest);
    }
    registry.insert(
        play_session_id.to_string(),
        TranscodeExecutionObservation {
            policy_mode: ffmpeg_mode_name(policy_mode),
            requested_mode,
            effective_mode: requested_mode,
            attempt_count: 1,
            fallback_used: false,
            phase: "queued",
            fallback_reason_code: None,
            last_error_code: None,
            last_exit_code: None,
            process_id: None,
            process_started_at: None,
            frame: None,
            fps: None,
            speed: None,
            position_ticks: None,
            progress_percent: None,
            cpu_time_millis: None,
            cpu_percent: None,
            rss_bytes: None,
            resource_updated_at: None,
            telemetry_updated_at: None,
            updated_at: OffsetDateTime::now_utc(),
        },
    );
}

async fn mark_transcode_process_started(play_session_id: &str, process_id: Option<u32>) {
    if let Some(observation) = transcode_execution_registry()
        .lock()
        .await
        .get_mut(play_session_id)
    {
        observation.process_id = process_id;
        observation.process_started_at = Some(OffsetDateTime::now_utc());
        // Never attribute a failed remux attempt's telemetry to its fallback.
        observation.frame = None;
        observation.fps = None;
        observation.speed = None;
        observation.position_ticks = None;
        observation.progress_percent = None;
        observation.cpu_time_millis = None;
        observation.cpu_percent = None;
        observation.rss_bytes = None;
        observation.resource_updated_at = None;
        observation.telemetry_updated_at = None;
        observation.updated_at = OffsetDateTime::now_utc();
    }
}

async fn update_transcode_execution_progress(
    play_session_id: &str,
    progress: &jellyrin_core::FfmpegProgress,
    runtime_ticks: Option<i64>,
) {
    if let Some(observation) = transcode_execution_registry()
        .lock()
        .await
        .get_mut(play_session_id)
    {
        observation.frame = progress.frame;
        observation.fps = progress.fps_value();
        observation.speed = progress.speed_ratio();
        observation.position_ticks = progress.position_ticks();
        observation.progress_percent = observation
            .position_ticks
            .and_then(|position| transcode_progress_percent(position, runtime_ticks));
        observation.telemetry_updated_at = Some(OffsetDateTime::now_utc());
        observation.updated_at = OffsetDateTime::now_utc();
    }
}

async fn update_transcode_execution_resources(
    play_session_id: &str,
    sample: jellyrin_transcode::TranscodeProcessResourceSample,
) {
    if let Some(observation) = transcode_execution_registry()
        .lock()
        .await
        .get_mut(play_session_id)
    {
        observation.cpu_time_millis = Some(sample.cpu_time_millis);
        observation.cpu_percent = sample.cpu_percent.filter(|value| value.is_finite());
        observation.rss_bytes = Some(sample.rss_bytes);
        let now = OffsetDateTime::now_utc();
        observation.resource_updated_at = Some(now);
        observation.telemetry_updated_at = Some(now);
        observation.updated_at = OffsetDateTime::now_utc();
    }
}

fn spawn_transcode_observation_task(
    play_session_id: String,
    mut progress_rx: tokio::sync::broadcast::Receiver<jellyrin_core::FfmpegProgress>,
    mut resource_rx: tokio::sync::watch::Receiver<
        Option<jellyrin_transcode::TranscodeProcessResourceSample>,
    >,
    runtime_ticks: Option<i64>,
) -> tokio::task::JoinHandle<()> {
    tokio::spawn(async move {
        let mut progress_open = true;
        let mut resources_open = true;
        while progress_open || resources_open {
            tokio::select! {
                progress = progress_rx.recv(), if progress_open => match progress {
                    Ok(progress) => {
                        update_transcode_execution_progress(
                            &play_session_id,
                            &progress,
                            runtime_ticks,
                        ).await;
                    }
                    Err(tokio::sync::broadcast::error::RecvError::Lagged(_)) => {}
                    Err(tokio::sync::broadcast::error::RecvError::Closed) => {
                        progress_open = false;
                    }
                },
                changed = resource_rx.changed(), if resources_open => match changed {
                    Ok(()) => {
                        let sample = *resource_rx.borrow_and_update();
                        if let Some(sample) = sample {
                            update_transcode_execution_resources(&play_session_id, sample).await;
                        }
                    }
                    Err(_) => resources_open = false,
                },
            }
        }
    })
}

async fn update_transcode_execution(
    play_session_id: &str,
    effective_mode: Option<TranscodeJobKind>,
    attempt_count: Option<u8>,
    phase: &'static str,
    error_code: Option<&'static str>,
    exit_code: Option<i32>,
) {
    if let Some(observation) = transcode_execution_registry()
        .lock()
        .await
        .get_mut(play_session_id)
    {
        if let Some(effective_mode) = effective_mode {
            observation.effective_mode = effective_mode;
        }
        if let Some(attempt_count) = attempt_count {
            observation.attempt_count = attempt_count.min(2);
            observation.fallback_used = observation.attempt_count > 1;
        }
        observation.phase = phase;
        if error_code.is_some() {
            if phase == "fallback-queued" && observation.fallback_reason_code.is_none() {
                observation.fallback_reason_code = error_code;
            }
            observation.last_error_code = error_code;
        }
        if exit_code.is_some() {
            observation.last_exit_code = exit_code;
        }
        observation.updated_at = OffsetDateTime::now_utc();
    }
}

fn apply_transcode_execution_json(
    value: &mut serde_json::Value,
    observation: &TranscodeExecutionObservation,
) {
    let Some(value) = value.as_object_mut() else {
        return;
    };
    value.insert(
        "PolicyMode".to_string(),
        serde_json::json!(observation.policy_mode),
    );
    value.insert(
        "RequestedExecutionMode".to_string(),
        serde_json::json!(transcode_job_kind_name(observation.requested_mode)),
    );
    value.insert(
        "EffectiveExecutionMode".to_string(),
        serde_json::json!(transcode_job_kind_name(observation.effective_mode)),
    );
    value.insert(
        "AttemptCount".to_string(),
        serde_json::json!(observation.attempt_count),
    );
    value.insert(
        "FallbackUsed".to_string(),
        serde_json::json!(observation.fallback_used),
    );
    value.insert(
        "ExecutionPhase".to_string(),
        serde_json::json!(observation.phase),
    );
    value.insert(
        "FallbackReasonCode".to_string(),
        serde_json::json!(observation.fallback_reason_code),
    );
    value.insert(
        "LastErrorCode".to_string(),
        serde_json::json!(observation.last_error_code),
    );
    value.insert(
        "LastExitCode".to_string(),
        serde_json::json!(observation.last_exit_code),
    );
    value.insert(
        "ProcessId".to_string(),
        serde_json::json!(observation.process_id),
    );
    value.insert(
        "ProcessStartedAt".to_string(),
        serde_json::json!(observation.process_started_at),
    );
    value.insert(
        "TranscodingFrame".to_string(),
        serde_json::json!(observation.frame),
    );
    value.insert(
        "TranscodingFramerate".to_string(),
        serde_json::json!(observation.fps),
    );
    value.insert(
        "TranscodingSpeed".to_string(),
        serde_json::json!(observation.speed),
    );
    if let Some(position_ticks) = observation.position_ticks {
        value.insert(
            "TranscodingPositionTicks".to_string(),
            serde_json::json!(position_ticks),
        );
    }
    if let Some(progress_percent) = observation.progress_percent {
        value.insert(
            "CompletionPercentage".to_string(),
            serde_json::json!(progress_percent),
        );
        value.insert(
            "ProgressPercentage".to_string(),
            serde_json::json!(progress_percent),
        );
    }
    value.insert(
        "ProcessCpuPercent".to_string(),
        serde_json::json!(observation.cpu_percent),
    );
    value.insert(
        "ProcessCpuTimeMilliseconds".to_string(),
        serde_json::json!(observation.cpu_time_millis),
    );
    value.insert(
        "ProcessRssBytes".to_string(),
        serde_json::json!(observation.rss_bytes),
    );
    value.insert(
        "ProcessTelemetryUpdatedAt".to_string(),
        serde_json::json!(observation.telemetry_updated_at),
    );
    value.insert(
        "ProcessResourceUpdatedAt".to_string(),
        serde_json::json!(observation.resource_updated_at),
    );
}

fn live_hls_session_registry() -> &'static Mutex<HashMap<String, LiveHlsSessionEntry>> {
    LIVE_HLS_SESSIONS.get_or_init(|| Mutex::new(HashMap::new()))
}

fn live_hls_session_is_active(entry: &LiveHlsSessionEntry) -> bool {
    matches!(entry.status.as_str(), "starting" | "running")
}

fn insert_bounded_live_hls_session(
    registry: &mut HashMap<String, LiveHlsSessionEntry>,
    entry: LiveHlsSessionEntry,
    max_entries: usize,
) -> Result<Vec<LiveHlsSessionEntry>, &'static str> {
    if max_entries == 0 {
        return Err("Live HLS session registry is disabled");
    }
    if let Some(existing) = registry.get(&entry.play_session_id) {
        if live_hls_session_is_active(existing) {
            return Err("Live HLS session id is already active");
        }
        // The caller has already recreated this session's output directory, so
        // replace a terminal entry in place without deleting the shared path.
        registry.insert(entry.play_session_id.clone(), entry);
        return Ok(Vec::new());
    }

    let required_evictions = registry.len().saturating_add(1).saturating_sub(max_entries);
    let mut terminal = registry
        .values()
        .filter(|candidate| !live_hls_session_is_active(candidate))
        .map(|candidate| (candidate.updated_at, candidate.play_session_id.clone()))
        .collect::<Vec<_>>();
    terminal.sort_by_key(|(updated_at, _)| *updated_at);
    if terminal.len() < required_evictions {
        return Err("Live HLS session registry is full");
    }

    let evicted = terminal
        .into_iter()
        .take(required_evictions)
        .filter_map(|(_, play_session_id)| registry.remove(&play_session_id))
        .collect::<Vec<_>>();
    registry.insert(entry.play_session_id.clone(), entry);
    Ok(evicted)
}

async fn register_live_hls_session(entry: LiveHlsSessionEntry) -> Result<(), ApiError> {
    let evicted = {
        let mut registry = live_hls_session_registry().lock().await;
        insert_bounded_live_hls_session(&mut registry, entry, LIVE_HLS_SESSION_REGISTRY_MAX_ENTRIES)
            .map_err(ApiError::service_unavailable)?
    };
    for entry in evicted {
        if let Some(output_path) = quarantine_live_hls_session_output(&entry).await {
            cleanup_hls_transcode_files(&output_path).await;
        }
        forget_transcode_session_access(&entry.play_session_id).await;
    }
    Ok(())
}

// Constructs a synthetic MediaItem for a live TV channel so it can be embedded inside a
// TranscodeSession without requiring a real media_items DB row.
fn live_tv_channel_synthetic_media_item(
    channel_id: &str,
    channel_url: &str,
    media_streams: &[serde_json::Value],
) -> MediaItem {
    let id = live_tv_channel_stable_uuid(channel_id).unwrap_or_else(Uuid::new_v4);
    let now = OffsetDateTime::now_utc();
    MediaItem {
        id,
        virtual_folder_id: Uuid::nil(),
        name: channel_id.to_string(),
        path: channel_url.to_string(),
        media_type: "Video".to_string(),
        collection_type: None,
        file_size: None,
        runtime_ticks: None,
        bitrate: None,
        width: None,
        height: None,
        media_streams: media_streams.to_vec(),
        created_at: now,
        updated_at: now,
    }
}

// Builds a synthetic TranscodeSession from a LiveHlsSessionEntry for handlers that need one.
fn live_hls_entry_to_transcode_session(entry: &LiveHlsSessionEntry) -> TranscodeSession {
    let item = live_tv_channel_synthetic_media_item(
        &entry.channel_id,
        &entry.channel_url,
        &entry.media_streams,
    );
    TranscodeSession {
        play_session_id: entry.play_session_id.clone(),
        dedupe_key: Some(entry.dedupe_key.clone()),
        device_id: entry.device_id.clone(),
        user_id: entry.user_id,
        item,
        media_source_id: Some(entry.channel_id.clone()),
        audio_stream_index: None,
        subtitle_stream_index: entry.subtitle_stream_index,
        video_stream_index: Some(0),
        output_path: entry.output_path.clone(),
        process_id: entry.process_id,
        status: entry.status.clone(),
        progress_percent: None,
        position_ticks: 0,
        start_position_ticks: 0,
        created_at: entry.created_at,
        updated_at: entry.updated_at,
    }
}

// Builds the ActiveEncodings JSON for a live TV HLS session. Mirrors transcode_session_json
// but uses channel_id as the item identifier instead of a UUID.
fn live_hls_session_json(entry: &LiveHlsSessionEntry) -> serde_json::Value {
    serde_json::json!({
        "PlaySessionId": entry.play_session_id,
        "UserId": entry.user_id.simple().to_string(),
        "ItemId": entry.channel_id,
        "MediaSourceId": entry.channel_id,
        "DeviceId": null,
        "Path": entry.output_path,
        "OutputPath": entry.output_path,
        "Status": entry.status,
        "ProcessId": entry.process_id,
        "ProgressPercentage": null,
        "CompletionPercentage": null,
        "TranscodingPositionTicks": 0,
        "TranscodingStartPositionTicks": 0,
        "Container": "ts",
        "VideoCodec": "ts",
        "AudioCodec": null,
        "Width": null,
        "Height": null,
        "Bitrate": null,
        "VideoStreamIndex": 0,
        "AudioStreamIndex": null,
        "SubtitleStreamIndex": entry.subtitle_stream_index,
        "TranscodeReasons": [],
        "IsAudioDirect": false,
        "IsVideoDirect": false,
        "UpdatedAt": format_time_for_json(entry.updated_at),
    })
}

// Starts a new live TV HLS ffmpeg transcode session for the given channel, registers stop_tx
// in TRANSCODE_STOPS, and inserts the entry into LIVE_HLS_SESSIONS. The session lifecycle
// mirrors spawn_hls_transcode_task but without DB calls.
struct LiveHlsTranscodeStart {
    play_session_id: String,
    channel_id: String,
    channel_url: String,
    media_streams: Vec<serde_json::Value>,
    subtitle_stream_index: Option<i64>,
    device_id: Option<String>,
    user_id: Uuid,
    plan: HlsTranscodePlan,
    output_path: String,
    tuner_lease: Option<LiveTunerLeaseGuard>,
    stdin_source: Option<LiveTvBroadcastConsumer>,
    input_relay: Option<InternalRemoteRelayLease>,
    disk_reservation: TranscodeDiskReservation,
}

async fn feed_live_hls_stdin_from_broadcast(
    mut stdin: tokio::process::ChildStdin,
    mut receiver: broadcast::Receiver<Bytes>,
    play_session_id: String,
) {
    loop {
        match receiver.recv().await {
            Ok(chunk) => {
                if let Err(error) = stdin.write_all(&chunk).await {
                    tracing::debug!(
                        %play_session_id,
                        %error,
                        "live HLS stdin feed stopped because ffmpeg stdin closed"
                    );
                    break;
                }
            }
            Err(broadcast::error::RecvError::Lagged(n)) => {
                tracing::warn!(
                    %play_session_id,
                    "live HLS stdin feed lagged, dropped {n} chunks"
                );
            }
            Err(broadcast::error::RecvError::Closed) => break,
        }
    }
    let _ = stdin.shutdown().await;
}

async fn spawn_live_hls_transcode_task(start: LiveHlsTranscodeStart) -> Result<(), ApiError> {
    let LiveHlsTranscodeStart {
        play_session_id,
        channel_id,
        channel_url,
        media_streams,
        subtitle_stream_index,
        device_id,
        user_id,
        plan,
        output_path,
        tuner_lease,
        stdin_source,
        input_relay,
        disk_reservation,
    } = start;

    let now = OffsetDateTime::now_utc();
    register_live_hls_session(LiveHlsSessionEntry {
        play_session_id: play_session_id.clone(),
        dedupe_key: live_tv_channel_hls_dedupe_key_for_selection(
            &channel_id,
            subtitle_stream_index,
        ),
        channel_id: channel_id.clone(),
        channel_url: channel_url.clone(),
        media_streams,
        subtitle_stream_index,
        output_path: output_path.clone(),
        user_id,
        device_id,
        status: "starting".to_string(),
        process_id: None,
        created_at: now,
        updated_at: now,
    })
    .await?;

    // Register the stop sender only after bounded session admission succeeds.
    let (stop_tx, mut stop_rx) = oneshot::channel();
    {
        let mut registry = transcode_stop_registry().lock().await;
        if let Some(prev) = registry.insert(play_session_id.clone(), stop_tx) {
            let _ = prev.send(());
        }
    }
    touch_transcode_session(&play_session_id).await;
    register_transcode_execution(&play_session_id, configured_ffmpeg_mode(), &plan.primary).await;

    tokio::spawn(async move {
        let _tuner_lease = tuner_lease;
        let _input_relay = input_relay;
        let mut command = plan.primary;
        let mut fallback = plan.fallback;
        let mut attempt_count = 1u8;
        let mut stopped = false;
        let final_status = loop {
            let kind = classify_transcode_command(&command);
            update_transcode_execution(
                &play_session_id,
                Some(kind),
                Some(attempt_count),
                if attempt_count == 1 {
                    "queued"
                } else {
                    "fallback-queued"
                },
                None,
                None,
            )
            .await;
            let outcome = run_live_hls_attempt(
                &play_session_id,
                &command,
                &mut stop_rx,
                &disk_reservation,
                stdin_source.as_ref(),
            )
            .await;
            let first_segment =
                HlsTranscodeLayout::from_media_playlist_path(&output_path).segment_path(0);
            let first_segment_ready = hls_output_file_is_nonempty(&first_segment).await;
            if hls_remux_fallback_eligible(
                attempt_count,
                kind,
                first_segment_ready,
                matches!(&outcome, LiveHlsAttemptOutcome::Process(exit) if !exit.success),
                fallback.is_some(),
            ) && let Some(next) = fallback.take()
            {
                let exit_code = match &outcome {
                    LiveHlsAttemptOutcome::Process(exit) => exit.code,
                    _ => None,
                };
                update_transcode_execution(
                    &play_session_id,
                    None,
                    None,
                    "fallback-queued",
                    Some("remux-exited-before-first-segment"),
                    exit_code,
                )
                .await;
                {
                    let mut registry = live_hls_session_registry().lock().await;
                    if let Some(entry) = registry.get_mut(&play_session_id) {
                        entry.status = "starting".to_string();
                        entry.process_id = None;
                        entry.updated_at = OffsetDateTime::now_utc();
                    }
                }
                let layout = HlsTranscodeLayout::from_media_playlist_path(&output_path);
                cleanup_hls_transcode_dir(&layout.session_dir).await;
                if let Err(error) = tokio::fs::create_dir_all(&layout.session_dir).await {
                    tracing::error!(%play_session_id, %error, "failed to prepare live HLS fallback output");
                    break "failed";
                }
                tracing::warn!(%play_session_id, "live HLS remux produced no first segment; retrying once with encode");
                command = next;
                attempt_count = 2;
                continue;
            }
            break match outcome {
                LiveHlsAttemptOutcome::Process(exit) if exit.success => "completed",
                LiveHlsAttemptOutcome::Stopped => {
                    stopped = true;
                    "stopped"
                }
                LiveHlsAttemptOutcome::CapacityUnavailable => {
                    update_transcode_execution(
                        &play_session_id,
                        None,
                        None,
                        "failed",
                        Some("capacity-unavailable"),
                        None,
                    )
                    .await;
                    "failed"
                }
                LiveHlsAttemptOutcome::SpawnFailed => {
                    update_transcode_execution(
                        &play_session_id,
                        None,
                        None,
                        "failed",
                        Some("spawn-failed"),
                        None,
                    )
                    .await;
                    "failed"
                }
                LiveHlsAttemptOutcome::WaitFailed => {
                    update_transcode_execution(
                        &play_session_id,
                        None,
                        None,
                        "failed",
                        Some("process-wait-failed"),
                        None,
                    )
                    .await;
                    "failed"
                }
                LiveHlsAttemptOutcome::Process(exit) => {
                    let error_code = if kind == TranscodeJobKind::Remux && !first_segment_ready {
                        "remux-exited-before-first-segment"
                    } else {
                        "process-exited"
                    };
                    update_transcode_execution(
                        &play_session_id,
                        None,
                        None,
                        "failed",
                        Some(error_code),
                        exit.code,
                    )
                    .await;
                    "failed"
                }
            };
        };
        update_transcode_execution(&play_session_id, None, None, final_status, None, None).await;
        transcode_stop_registry()
            .lock()
            .await
            .remove(&play_session_id);
        if final_status != "completed" {
            forget_transcode_session_access(&play_session_id).await;
        }

        {
            let mut registry = live_hls_session_registry().lock().await;
            if let Some(entry) = registry.get_mut(&play_session_id) {
                entry.status = final_status.to_string();
                entry.updated_at = OffsetDateTime::now_utc();
            }
        }

        if final_status != "completed" {
            cleanup_hls_transcode_files(&output_path).await;
        }
        if stopped {
            live_hls_session_registry()
                .lock()
                .await
                .remove(&play_session_id);
        }
    });
    Ok(())
}

enum LiveHlsAttemptOutcome {
    Process(jellyrin_transcode::TranscodeProcessExit),
    Stopped,
    CapacityUnavailable,
    SpawnFailed,
    WaitFailed,
}

async fn run_live_hls_attempt(
    play_session_id: &str,
    command: &jellyrin_core::FfmpegCommandSpec,
    stop_rx: &mut oneshot::Receiver<()>,
    disk_reservation: &TranscodeDiskReservation,
    stdin_source: Option<&LiveTvBroadcastConsumer>,
) -> LiveHlsAttemptOutcome {
    let permit = tokio::select! {
        permit = acquire_transcode_job(command) => match permit {
            Ok(permit) => permit,
            Err(error) => {
                tracing::error!(%play_session_id, %error, "failed to acquire live FFmpeg capacity");
                return LiveHlsAttemptOutcome::CapacityUnavailable;
            }
        },
        _ = &mut *stop_rx => return LiveHlsAttemptOutcome::Stopped,
        _ = wait_for_transcode_idle(play_session_id, transcode_idle_timeout(true)) => {
            tracing::info!(%play_session_id, "stopped queued live HLS transcode after idle timeout");
            return LiveHlsAttemptOutcome::Stopped;
        },
        _ = disk_reservation.wait_until_exceeded() => {
            tracing::warn!(%play_session_id, "cancelled queued live HLS transcode after storage quota was exceeded");
            return LiveHlsAttemptOutcome::Stopped;
        }
    };
    let spawn_result = if let Some(source) = stdin_source {
        spawn_transcode_process_with_stdin(command).map(|(process, stdin)| {
            let feed_task = tokio::spawn(feed_live_hls_stdin_from_broadcast(
                stdin,
                source.receiver.resubscribe(),
                play_session_id.to_string(),
            ));
            (process, Some(feed_task))
        })
    } else {
        spawn_transcode_process(command).map(|process| (process, None))
    };
    let (mut process, stdin_feed_task) = match spawn_result {
        Ok(spawned) => spawned,
        Err(error) => {
            tracing::error!(%play_session_id, %error, "failed to spawn live HLS transcode process");
            drop(permit);
            return LiveHlsAttemptOutcome::SpawnFailed;
        }
    };
    let progress_rx = process.subscribe_progress();
    let resource_rx = process.subscribe_resources();
    let process_id = process.process_id();
    {
        let mut registry = live_hls_session_registry().lock().await;
        if let Some(entry) = registry.get_mut(play_session_id) {
            entry.status = "running".to_string();
            entry.process_id = process_id.map(i64::from);
            entry.updated_at = OffsetDateTime::now_utc();
        }
    }
    mark_transcode_process_started(play_session_id, process_id).await;
    update_transcode_execution(play_session_id, None, None, "running", None, None).await;
    let observation_task = spawn_transcode_observation_task(
        play_session_id.to_string(),
        progress_rx,
        resource_rx,
        None,
    );
    let mut stopped = false;
    let exit = tokio::select! {
        exit = process.wait() => exit,
        _ = &mut *stop_rx => { stopped = true; process.stop().await },
        _ = wait_for_transcode_idle(play_session_id, transcode_idle_timeout(true)) => {
            stopped = true;
            tracing::info!(%play_session_id, "stopped live HLS transcode after idle timeout");
            process.stop().await
        },
        _ = disk_reservation.wait_until_exceeded() => {
            stopped = true;
            tracing::warn!(%play_session_id, "stopped live HLS transcode after storage quota was exceeded");
            process.stop().await
        }
    };
    drop(process);
    let _ = observation_task.await;
    if let Some(task) = stdin_feed_task {
        task.abort();
        let _ = task.await;
    }
    drop(permit);
    if stopped {
        LiveHlsAttemptOutcome::Stopped
    } else {
        match exit {
            Ok(exit) => LiveHlsAttemptOutcome::Process(exit),
            Err(error) => {
                tracing::error!(%play_session_id, %error, "live HLS transcode process wait failed");
                LiveHlsAttemptOutcome::WaitFailed
            }
        }
    }
}

async fn resolve_media_source_item(
    db: &Database,
    requested_item: MediaItem,
    media_source_id: Option<&str>,
) -> Result<Option<MediaItem>, ApiError> {
    let Some(media_source_id) = media_source_id
        .map(str::trim)
        .filter(|media_source_id| !media_source_id.is_empty())
    else {
        return Ok(Some(requested_item));
    };
    let Ok(media_source_id) = parse_jellyfin_uuid(media_source_id) else {
        return Ok(None);
    };
    if media_source_id == requested_item.id {
        return Ok(Some(requested_item));
    }
    if requested_item.media_type != "Video" {
        return Ok(None);
    }

    Ok(db
        .media_item_versions(requested_item.id)
        .await?
        .into_iter()
        .find(|item| item.id == media_source_id && item.media_type == requested_item.media_type))
}

fn playback_selection_supported(item: &MediaItem, options: &PlaybackInfoOptions) -> bool {
    if let Some(media_source_id) = options.media_source_id.as_deref()
        && parse_jellyfin_uuid(media_source_id).ok() != Some(item.id)
    {
        return false;
    }

    if let Some(audio_stream_index) = options.audio_stream_index
        && !media_item_has_stream_index(item, "Audio", audio_stream_index)
    {
        return false;
    }

    if let Some(subtitle_stream_index) = options.subtitle_stream_index {
        if subtitle_stream_index < 0 {
            return true;
        }
        if !media_item_has_stream_index(item, "Subtitle", subtitle_stream_index) {
            return false;
        }
    }

    true
}

fn apply_playback_stream_selection(
    media_source: &mut serde_json::Map<String, serde_json::Value>,
    options: &PlaybackInfoOptions,
) {
    if let Some(audio_stream_index) = options.audio_stream_index {
        media_source.insert(
            "DefaultAudioStreamIndex".to_string(),
            serde_json::json!(audio_stream_index),
        );
    }

    if options.burn_in_subtitle {
        media_source.insert(
            "DefaultSubtitleStreamIndex".to_string(),
            serde_json::Value::Null,
        );
        return;
    }

    if let Some(subtitle_stream_index) = options.subtitle_stream_index {
        let value = if subtitle_stream_index < 0 {
            serde_json::Value::Null
        } else {
            serde_json::json!(subtitle_stream_index)
        };
        media_source.insert("DefaultSubtitleStreamIndex".to_string(), value);
    }
}

fn media_item_has_stream_index(item: &MediaItem, stream_type: &str, index: i64) -> bool {
    media_item_streams(item).iter().any(|stream| {
        let Some(stream) = stream.as_object() else {
            return false;
        };
        let Some(type_name) = stream.get("Type").and_then(serde_json::Value::as_str) else {
            return false;
        };
        if !type_name.eq_ignore_ascii_case(stream_type) {
            return false;
        }

        stream
            .get("Index")
            .and_then(json_value_i64)
            .is_some_and(|stream_index| stream_index == index)
    })
}

fn playback_direct_play_supported(item: &MediaItem, options: &PlaybackInfoOptions) -> bool {
    if !options.enable_direct_play {
        return false;
    }

    let Some(profiles) = options.direct_play_profiles.as_ref() else {
        return true;
    };

    profiles
        .iter()
        .any(|profile| direct_play_profile_matches(item, profile))
}

fn playback_profile_compatible(item: &MediaItem, options: &PlaybackInfoOptions) -> bool {
    let Some(profiles) = options.direct_play_profiles.as_ref() else {
        return true;
    };
    profiles
        .iter()
        .any(|profile| direct_play_profile_matches(item, profile))
}

/// Plugin VOD has already passed the fail-closed `DirectProxy` + MPEG-TS delivery gate, but its
/// portal may not expose elementary codec names until a client opens the stream. A native client
/// that explicitly advertises the TS container may therefore discover/proxy it when the known
/// codecs match and unknown codecs remain absent. Browsers still fail the container check and use
/// HLS, while a known incompatible codec continues to reject direct delivery.
fn plugin_vod_direct_stream_profile_compatible(
    item: &MediaItem,
    options: &PlaybackInfoOptions,
) -> bool {
    if item.media_type.eq_ignore_ascii_case("Video") && !media_item_has_stream_type(item, "Video") {
        return false;
    }
    let Some(profiles) = options.direct_play_profiles.as_ref() else {
        return true;
    };
    profiles.iter().any(|profile| {
        if let Some(profile_type) = profile.profile_type.as_deref()
            && !profile_type.eq_ignore_ascii_case(&item.media_type)
        {
            return false;
        }
        let Some(container) = media_item_container(item) else {
            return false;
        };
        if !profile.containers.is_empty()
            && !profile
                .containers
                .iter()
                .any(|candidate| candidate.eq_ignore_ascii_case(&container))
        {
            return false;
        }
        if let Some(video_codec) = media_item_stream_codec(item, "Video")
            && !profile.video_codecs.is_empty()
            && !profile
                .video_codecs
                .iter()
                .any(|candidate| candidate.eq_ignore_ascii_case(&video_codec))
        {
            return false;
        }
        if let Some(audio_codec) = media_item_stream_codec(item, "Audio")
            && !profile.audio_codecs.is_empty()
            && !profile
                .audio_codecs
                .iter()
                .any(|candidate| candidate.eq_ignore_ascii_case(&audio_codec))
        {
            return false;
        }
        true
    })
}

fn playback_profile_codecs_compatible(item: &MediaItem, options: &PlaybackInfoOptions) -> bool {
    let Some(profiles) = options.direct_play_profiles.as_ref() else {
        return true;
    };
    profiles.iter().any(|profile| {
        if let Some(profile_type) = profile.profile_type.as_deref()
            && !profile_type.eq_ignore_ascii_case(item.media_type.as_str())
        {
            return false;
        }
        if !profile.video_codecs.is_empty()
            && media_item_stream_codec(item, "Video").is_none_or(|codec| {
                !profile
                    .video_codecs
                    .iter()
                    .any(|candidate| candidate.eq_ignore_ascii_case(&codec))
            })
        {
            return false;
        }
        let selected_audio_codec = options
            .audio_stream_index
            .or_else(|| default_audio_stream_index(&media_item_streams(item)))
            .and_then(|index| media_item_stream_codec_by_index(item, "Audio", index));
        profile.audio_codecs.is_empty()
            || selected_audio_codec.is_none_or(|codec| {
                profile
                    .audio_codecs
                    .iter()
                    .any(|candidate| candidate.eq_ignore_ascii_case(&codec))
            })
    })
}

fn playback_profile_video_codec_compatible(
    item: &MediaItem,
    options: &PlaybackInfoOptions,
) -> bool {
    let Some(profiles) = options.direct_play_profiles.as_ref() else {
        return true;
    };
    profiles.iter().any(|profile| {
        if let Some(profile_type) = profile.profile_type.as_deref()
            && !profile_type.eq_ignore_ascii_case(item.media_type.as_str())
        {
            return false;
        }
        profile.video_codecs.is_empty()
            || media_item_stream_codec(item, "Video").is_some_and(|codec| {
                profile
                    .video_codecs
                    .iter()
                    .any(|candidate| candidate.eq_ignore_ascii_case(&codec))
            })
    })
}

fn codec_profile_targets_stream(
    profile: &CodecProfileMatcher,
    item: &MediaItem,
    stream_type: &str,
    codec: Option<&str>,
) -> bool {
    let profile_type_matches = match profile
        .profile_type
        .as_deref()
        .map(str::to_ascii_lowercase)
        .as_deref()
    {
        None => true,
        Some("video") => stream_type.eq_ignore_ascii_case("Video"),
        Some("videoaudio") => {
            item.media_type.eq_ignore_ascii_case("Video")
                && stream_type.eq_ignore_ascii_case("Audio")
        }
        Some("audio") => {
            item.media_type.eq_ignore_ascii_case("Audio")
                && stream_type.eq_ignore_ascii_case("Audio")
        }
        _ => false,
    };
    profile_type_matches
        && (profile.codecs.is_empty()
            || codec.is_some_and(|codec| {
                profile
                    .codecs
                    .iter()
                    .any(|candidate| candidate.eq_ignore_ascii_case(codec))
            }))
}

fn codec_condition_property_value(
    item: &MediaItem,
    options: &PlaybackInfoOptions,
    property: CodecConditionProperty,
) -> Option<CodecConditionValue> {
    match property {
        CodecConditionProperty::Width => item
            .width
            .and_then(|value| positive_u32(i64::from(value)))
            .or_else(|| media_item_stream_u32(item, "Video", None, "Width"))
            .map(CodecConditionValue::Numeric),
        CodecConditionProperty::Height => item
            .height
            .and_then(|value| positive_u32(i64::from(value)))
            .or_else(|| media_item_stream_u32(item, "Video", None, "Height"))
            .map(CodecConditionValue::Numeric),
        CodecConditionProperty::VideoBitrate => {
            media_item_stream_u32(item, "Video", None, "BitRate")
                .or_else(|| item.bitrate.and_then(positive_u32))
                .map(CodecConditionValue::Numeric)
        }
        CodecConditionProperty::AudioBitrate => {
            let selected_index = options
                .audio_stream_index
                .or_else(|| default_audio_stream_index(&media_item_streams(item)));
            media_item_stream_u32(item, "Audio", selected_index, "BitRate")
                .or_else(|| {
                    item.media_type
                        .eq_ignore_ascii_case("Audio")
                        .then(|| item.bitrate.and_then(positive_u32))
                        .flatten()
                })
                .map(CodecConditionValue::Numeric)
        }
        CodecConditionProperty::VideoProfile => codec_condition_stream(item, options, "Video")
            .and_then(|stream| json_string_field(&stream, "Profile"))
            .and_then(|value| normalize_codec_profile(property, &value))
            .map(CodecConditionValue::Text),
        CodecConditionProperty::AudioProfile => codec_condition_stream(item, options, "Audio")
            .and_then(|stream| json_string_field(&stream, "Profile"))
            .and_then(|value| normalize_codec_profile(property, &value))
            .map(CodecConditionValue::Text),
        CodecConditionProperty::VideoLevel => codec_condition_stream(item, options, "Video")
            .and_then(|stream| json_field_case_insensitive(&stream, "Level").cloned())
            .and_then(|value| codec_condition_raw_value(&value))
            .and_then(|value| parse_codec_level(&value))
            .map(CodecConditionValue::Numeric),
        CodecConditionProperty::VideoBitDepth => codec_condition_stream(item, options, "Video")
            .and_then(|stream| json_i64_field(&stream, "BitDepth"))
            .and_then(positive_u32)
            .map(CodecConditionValue::Numeric),
        CodecConditionProperty::VideoFrameRate => codec_condition_stream(item, options, "Video")
            .and_then(|stream| {
                ["RealFrameRate", "ReferenceFrameRate", "AverageFrameRate"]
                    .into_iter()
                    .find_map(|field| {
                        json_field_case_insensitive(&stream, field)
                            .and_then(codec_condition_raw_value)
                    })
            })
            .and_then(|value| parse_frame_rate_millihertz(&value))
            .map(CodecConditionValue::Numeric),
        CodecConditionProperty::AudioChannels => codec_condition_stream(item, options, "Audio")
            .and_then(|stream| {
                json_i64_field(&stream, "Channels")
                    .and_then(positive_u32)
                    .or_else(|| {
                        json_string_field(&stream, "ChannelLayout")
                            .and_then(|layout| audio_channels_from_layout(&layout))
                    })
            })
            .map(CodecConditionValue::Numeric),
    }
}

fn codec_condition_stream(
    item: &MediaItem,
    options: &PlaybackInfoOptions,
    stream_type: &str,
) -> Option<serde_json::Value> {
    let selected_index = stream_type
        .eq_ignore_ascii_case("Audio")
        .then(|| {
            options
                .audio_stream_index
                .or_else(|| default_audio_stream_index(&media_item_streams(item)))
        })
        .flatten();
    media_item_streams(item).into_iter().find(|stream| {
        json_string_field(stream, "Type")
            .is_some_and(|value| value.eq_ignore_ascii_case(stream_type))
            && selected_index.is_none_or(|index| json_i64_field(stream, "Index") == Some(index))
    })
}

fn audio_channels_from_layout(value: &str) -> Option<u32> {
    let value = value.trim().to_ascii_lowercase();
    if value == "mono" {
        return Some(1);
    }
    if value == "stereo" {
        return Some(2);
    }
    let base = value
        .split_once('(')
        .map_or(value.as_str(), |(base, _)| base)
        .trim();
    match base {
        "1.0" => Some(1),
        "2.0" => Some(2),
        "2.1" => Some(3),
        "3.0" => Some(3),
        "4.0" => Some(4),
        "5.0" => Some(5),
        "5.1" => Some(6),
        "6.1" => Some(7),
        "7.1" => Some(8),
        _ => None,
    }
}

fn media_item_stream_u32(
    item: &MediaItem,
    stream_type: &str,
    selected_index: Option<i64>,
    field: &str,
) -> Option<u32> {
    media_item_streams(item).iter().find_map(|stream| {
        let stream = stream.as_object()?;
        if !stream
            .get("Type")
            .and_then(serde_json::Value::as_str)
            .is_some_and(|value| value.eq_ignore_ascii_case(stream_type))
        {
            return None;
        }
        if selected_index.is_some()
            && stream.get("Index").and_then(json_value_i64) != selected_index
        {
            return None;
        }
        stream
            .get(field)
            .and_then(json_value_i64)
            .and_then(positive_u32)
    })
}

fn codec_condition_matches(
    condition: &CodecCondition,
    actual: Option<CodecConditionValue>,
) -> bool {
    let Some(actual) = actual else {
        return !condition.is_required;
    };
    match condition.comparison {
        CodecConditionComparison::Equal => condition.values.first() == Some(&actual),
        CodecConditionComparison::NotEqual => condition.values.first() != Some(&actual),
        CodecConditionComparison::EqualAny => condition.values.contains(&actual),
        CodecConditionComparison::NotEqualAny => !condition.values.contains(&actual),
        CodecConditionComparison::LessThan
        | CodecConditionComparison::LessThanEqual
        | CodecConditionComparison::GreaterThan
        | CodecConditionComparison::GreaterThanEqual => {
            let (CodecConditionValue::Numeric(actual), Some(CodecConditionValue::Numeric(value))) =
                (&actual, condition.values.first())
            else {
                return false;
            };
            match condition.comparison {
                CodecConditionComparison::LessThan => actual < value,
                CodecConditionComparison::LessThanEqual => actual <= value,
                CodecConditionComparison::GreaterThan => actual > value,
                CodecConditionComparison::GreaterThanEqual => actual >= value,
                _ => unreachable!(),
            }
        }
    }
}

fn playback_codec_conditions_compatible(
    item: &MediaItem,
    options: &PlaybackInfoOptions,
    stream_type: &str,
) -> bool {
    let codec = if stream_type.eq_ignore_ascii_case("Audio") {
        let selected_index = options
            .audio_stream_index
            .or_else(|| default_audio_stream_index(&media_item_streams(item)));
        selected_index.and_then(|index| media_item_stream_codec_by_index(item, "Audio", index))
    } else {
        media_item_stream_codec(item, stream_type)
    };
    options
        .codec_profiles
        .iter()
        .filter(|profile| {
            codec_profile_targets_stream(profile, item, stream_type, codec.as_deref())
        })
        .all(|profile| {
            profile.invalid_required_conditions.is_empty()
                && profile.conditions.iter().all(|condition| {
                    codec_condition_matches(
                        condition,
                        codec_condition_property_value(item, options, condition.property),
                    )
                })
        })
}

fn codec_condition_property_compatible(
    item: &MediaItem,
    options: &PlaybackInfoOptions,
    stream_type: &str,
    property: CodecConditionProperty,
) -> bool {
    let codec = if stream_type.eq_ignore_ascii_case("Audio") {
        let selected_index = options
            .audio_stream_index
            .or_else(|| default_audio_stream_index(&media_item_streams(item)));
        selected_index.and_then(|index| media_item_stream_codec_by_index(item, "Audio", index))
    } else {
        media_item_stream_codec(item, stream_type)
    };
    let profiles = options
        .codec_profiles
        .iter()
        .filter(|profile| {
            codec_profile_targets_stream(profile, item, stream_type, codec.as_deref())
        })
        .collect::<Vec<_>>();
    if profiles.iter().any(|profile| {
        profile
            .invalid_required_conditions
            .contains(&Some(property))
    }) {
        return false;
    }
    profiles
        .into_iter()
        .flat_map(|profile| profile.conditions.iter())
        .filter(|condition| condition.property == property)
        .all(|condition| {
            codec_condition_matches(
                condition,
                codec_condition_property_value(item, options, condition.property),
            )
        })
}

fn codec_conditions_have_unknown_required_condition(
    item: &MediaItem,
    options: &PlaybackInfoOptions,
    stream_type: &str,
) -> bool {
    let codec = if stream_type.eq_ignore_ascii_case("Audio") {
        selected_audio_codec(item, options)
    } else {
        media_item_stream_codec(item, stream_type)
    };
    options.codec_profiles.iter().any(|profile| {
        codec_profile_targets_stream(profile, item, stream_type, codec.as_deref())
            && profile
                .invalid_required_conditions
                .iter()
                .any(Option::is_none)
    })
}

fn codec_output_upper_bound(
    item: &MediaItem,
    options: &PlaybackInfoOptions,
    stream_type: &str,
    codec: &str,
    property: CodecConditionProperty,
) -> Option<u32> {
    options
        .codec_profiles
        .iter()
        .filter(|profile| codec_profile_targets_stream(profile, item, stream_type, Some(codec)))
        .flat_map(|profile| profile.conditions.iter())
        .filter(|condition| condition.property == property)
        .filter_map(|condition| match condition.comparison {
            CodecConditionComparison::Equal | CodecConditionComparison::LessThanEqual => {
                condition.values.first().and_then(codec_numeric_value)
            }
            CodecConditionComparison::EqualAny => condition
                .values
                .iter()
                .filter_map(codec_numeric_value)
                .max(),
            CodecConditionComparison::LessThan => condition
                .values
                .first()
                .and_then(codec_numeric_value)
                .and_then(|value| value.checked_sub(1)),
            _ => None,
        })
        .min()
}

fn codec_numeric_value(value: &CodecConditionValue) -> Option<u32> {
    match value {
        CodecConditionValue::Numeric(value) => Some(*value),
        CodecConditionValue::Text(_) => None,
    }
}

fn selected_audio_codec(item: &MediaItem, options: &PlaybackInfoOptions) -> Option<String> {
    options
        .audio_stream_index
        .or_else(|| default_audio_stream_index(&media_item_streams(item)))
        .and_then(|index| media_item_stream_codec_by_index(item, "Audio", index))
}

fn selected_text_subtitle_can_use_external(
    item: &MediaItem,
    options: &PlaybackInfoOptions,
) -> bool {
    let Some(index) = options.subtitle_stream_index.filter(|index| *index >= 0) else {
        return false;
    };
    let selected_is_text = media_item_streams(item).iter().any(|stream| {
        stream
            .get("Type")
            .and_then(serde_json::Value::as_str)
            .is_some_and(|stream_type| stream_type.eq_ignore_ascii_case("Subtitle"))
            && stream.get("Index").and_then(json_value_i64) == Some(index)
            && stream
                .get("Codec")
                .and_then(serde_json::Value::as_str)
                .is_some_and(is_text_subtitle_codec)
    });
    selected_is_text && text_subtitle_profile_supports_external(item, options)
}

/// External text tracks have to be described on the initial PlaybackInfo response as well as
/// after a stream is selected. Android TV builds its Media3 subtitle sources only once; if the
/// initial response has no DeliveryUrl it later tries to select an absent track and drops it
/// without issuing a second PlaybackInfo request.
fn text_subtitle_profile_supports_external(
    item: &MediaItem,
    options: &PlaybackInfoOptions,
) -> bool {
    media_item_streams(item).iter().any(|stream| {
        stream
            .get("Type")
            .and_then(serde_json::Value::as_str)
            .is_some_and(|stream_type| stream_type.eq_ignore_ascii_case("Subtitle"))
            && stream
                .get("Codec")
                .and_then(serde_json::Value::as_str)
                .is_some_and(is_text_subtitle_codec)
    }) && options.subtitle_profiles.as_ref().is_some_and(|profiles| {
        profiles.iter().any(|profile| {
            profile.method.as_deref() == Some("external")
                && matches!(profile.format.as_deref(), Some("vtt" | "webvtt"))
        })
    })
}

fn selected_text_subtitle_prefers_hls(options: &PlaybackInfoOptions) -> bool {
    options.subtitle_profiles.as_ref().is_some_and(|profiles| {
        profiles.iter().any(|profile| {
            profile.method.as_deref() == Some("hls")
                && matches!(profile.format.as_deref(), Some("vtt" | "webvtt"))
        })
    })
}

fn hls_transcoding_profile_matches(
    item: &MediaItem,
    options: &PlaybackInfoOptions,
    profile: &TranscodingProfileMatcher,
    video_mode: HlsStreamMode,
    audio_mode: HlsStreamMode,
) -> bool {
    if let Some(profile_type) = profile.profile_type.as_deref()
        && !profile_type.eq_ignore_ascii_case(&item.media_type)
    {
        return false;
    }
    if let Some(context) = profile.context.as_deref()
        && !context.eq_ignore_ascii_case("Streaming")
    {
        return false;
    }
    if !profile.protocols.is_empty()
        && !profile
            .protocols
            .iter()
            .any(|protocol| protocol.eq_ignore_ascii_case("hls"))
    {
        return false;
    }
    if !profile.containers.is_empty()
        && !profile
            .containers
            .iter()
            .any(|container| matches!(container.as_str(), "ts" | "mpegts"))
    {
        return false;
    }

    let output_video_codec = match video_mode {
        HlsStreamMode::Encode => Some("h264".to_string()),
        HlsStreamMode::Copy => media_item_stream_codec(item, "Video"),
        HlsStreamMode::Drop => None,
    };
    if let Some(codec) = output_video_codec
        && !profile.video_codecs.is_empty()
        && !profile
            .video_codecs
            .iter()
            .any(|candidate| candidate.eq_ignore_ascii_case(&codec))
    {
        return false;
    }

    let output_audio_codec = match audio_mode {
        HlsStreamMode::Encode => Some("aac".to_string()),
        HlsStreamMode::Copy => selected_audio_codec(item, options),
        HlsStreamMode::Drop => None,
    };
    output_audio_codec.is_none_or(|codec| {
        profile.audio_codecs.is_empty()
            || profile
                .audio_codecs
                .iter()
                .any(|candidate| candidate.eq_ignore_ascii_case(&codec))
    })
}

fn selected_hls_transcoding_profile<'a>(
    item: &MediaItem,
    options: &'a PlaybackInfoOptions,
    video_mode: HlsStreamMode,
    audio_mode: HlsStreamMode,
) -> Option<&'a TranscodingProfileMatcher> {
    options
        .transcoding_profiles
        .as_ref()?
        .iter()
        .find(|profile| {
            hls_transcoding_profile_matches(item, options, profile, video_mode, audio_mode)
        })
}

fn hls_transcoding_profile_supported(
    item: &MediaItem,
    options: &PlaybackInfoOptions,
    video_mode: HlsStreamMode,
    audio_mode: HlsStreamMode,
) -> bool {
    options.transcoding_profiles.is_none()
        || selected_hls_transcoding_profile(item, options, video_mode, audio_mode).is_some()
}

fn min_optional_u32(left: Option<u32>, right: Option<u32>) -> Option<u32> {
    match (left, right) {
        (Some(left), Some(right)) => Some(left.min(right)),
        (Some(value), None) | (None, Some(value)) => Some(value),
        (None, None) => None,
    }
}

fn codec_output_conditions<'a>(
    item: &MediaItem,
    options: &'a PlaybackInfoOptions,
    stream_type: &str,
    codec: &str,
    property: CodecConditionProperty,
) -> Vec<&'a CodecCondition> {
    options
        .codec_profiles
        .iter()
        .filter(|profile| codec_profile_targets_stream(profile, item, stream_type, Some(codec)))
        .flat_map(|profile| profile.conditions.iter())
        .filter(|condition| condition.property == property)
        .collect()
}

fn codec_output_has_invalid_required_condition(
    item: &MediaItem,
    options: &PlaybackInfoOptions,
    stream_type: &str,
    codec: &str,
) -> bool {
    options.codec_profiles.iter().any(|profile| {
        codec_profile_targets_stream(profile, item, stream_type, Some(codec))
            && !profile.invalid_required_conditions.is_empty()
    })
}

fn codec_output_conditions_match(
    conditions: &[&CodecCondition],
    value: CodecConditionValue,
) -> bool {
    conditions
        .iter()
        .all(|condition| codec_condition_matches(condition, Some(value.clone())))
}

fn selected_h264_output_profile(
    item: &MediaItem,
    options: &PlaybackInfoOptions,
) -> Option<Option<H264Profile>> {
    let conditions = codec_output_conditions(
        item,
        options,
        "Video",
        "h264",
        CodecConditionProperty::VideoProfile,
    );
    if conditions.is_empty() {
        return Some(None);
    }
    [H264Profile::Main, H264Profile::Baseline, H264Profile::High]
        .into_iter()
        .find(|profile| {
            codec_output_conditions_match(
                &conditions,
                CodecConditionValue::Text(profile.as_str().to_string()),
            )
        })
        .map(Some)
}

fn selected_h264_output_level(
    item: &MediaItem,
    options: &PlaybackInfoOptions,
) -> Option<Option<u8>> {
    let conditions = codec_output_conditions(
        item,
        options,
        "Video",
        "h264",
        CodecConditionProperty::VideoLevel,
    );
    if conditions.is_empty() {
        return Some(None);
    }
    const LEVELS_DESCENDING: [u8; 19] = [
        62, 61, 60, 52, 51, 50, 42, 41, 40, 32, 31, 30, 22, 21, 20, 13, 12, 11, 10,
    ];
    LEVELS_DESCENDING
        .into_iter()
        .find(|level| {
            codec_output_conditions_match(
                &conditions,
                CodecConditionValue::Numeric(u32::from(*level)),
            )
        })
        .map(Some)
}

fn selected_video_bit_depth(item: &MediaItem, options: &PlaybackInfoOptions) -> Option<Option<u8>> {
    let conditions = codec_output_conditions(
        item,
        options,
        "Video",
        "h264",
        CodecConditionProperty::VideoBitDepth,
    );
    if conditions.is_empty() {
        return Some(None);
    }
    codec_output_conditions_match(&conditions, CodecConditionValue::Numeric(8)).then_some(Some(8))
}

fn selected_aac_output_profile(
    item: &MediaItem,
    options: &PlaybackInfoOptions,
) -> Option<Option<AacProfile>> {
    let conditions = codec_output_conditions(
        item,
        options,
        "Audio",
        "aac",
        CodecConditionProperty::AudioProfile,
    );
    if conditions.is_empty() {
        return Some(None);
    }
    codec_output_conditions_match(
        &conditions,
        CodecConditionValue::Text(AacProfile::LowComplexity.as_str().to_string()),
    )
    .then_some(Some(AacProfile::LowComplexity))
}

fn selected_aac_output_channels(
    item: &MediaItem,
    options: &PlaybackInfoOptions,
) -> Option<Option<u8>> {
    let conditions = codec_output_conditions(
        item,
        options,
        "Audio",
        "aac",
        CodecConditionProperty::AudioChannels,
    );
    if conditions.is_empty() {
        return Some(None);
    }
    let input_channels =
        codec_condition_property_value(item, options, CodecConditionProperty::AudioChannels)
            .and_then(|value| codec_numeric_value(&value))
            .and_then(|value| u8::try_from(value).ok());
    let preferred = input_channels.unwrap_or(2).min(8);
    std::iter::once(preferred)
        .chain((1_u8..=8).rev())
        .filter(|channels| *channels <= preferred)
        .find(|channels| {
            codec_output_conditions_match(
                &conditions,
                CodecConditionValue::Numeric(u32::from(*channels)),
            )
        })
        .map(Some)
}

fn selected_video_frame_rate_limit(
    item: &MediaItem,
    options: &PlaybackInfoOptions,
) -> Option<Option<u32>> {
    let conditions = codec_output_conditions(
        item,
        options,
        "Video",
        "h264",
        CodecConditionProperty::VideoFrameRate,
    );
    if conditions.is_empty() {
        return Some(None);
    }
    let input =
        codec_condition_property_value(item, options, CodecConditionProperty::VideoFrameRate)
            .and_then(|value| codec_numeric_value(&value));
    if input.is_some_and(|input| {
        codec_output_conditions_match(&conditions, CodecConditionValue::Numeric(input))
    }) {
        return Some(None);
    }
    let mut candidates = input.into_iter().collect::<Vec<_>>();
    for condition in &conditions {
        for value in condition.values.iter().filter_map(codec_numeric_value) {
            candidates.push(value);
            match condition.comparison {
                CodecConditionComparison::LessThan => {
                    if let Some(value) = value.checked_sub(1) {
                        candidates.push(value);
                    }
                }
                CodecConditionComparison::GreaterThan => {
                    if let Some(value) = value.checked_add(1) {
                        candidates.push(value);
                    }
                }
                _ => {}
            }
        }
    }
    candidates.sort_unstable_by(|left, right| right.cmp(left));
    candidates.dedup();
    let selected = candidates
        .into_iter()
        .filter(|candidate| input.is_none_or(|input| *candidate <= input))
        .find(|candidate| {
            codec_output_conditions_match(&conditions, CodecConditionValue::Numeric(*candidate))
        })?;
    Some((input != Some(selected)).then_some(selected))
}

fn encoded_output_codec_conditions_compatible(
    item: &MediaItem,
    options: &PlaybackInfoOptions,
    stream_type: &str,
    codec: &str,
    output: PlaybackOutputConstraints,
) -> bool {
    options
        .codec_profiles
        .iter()
        .filter(|profile| codec_profile_targets_stream(profile, item, stream_type, Some(codec)))
        .all(|profile| {
            profile.invalid_required_conditions.is_empty()
                && profile.conditions.iter().all(|condition| {
                    codec_condition_matches(
                        condition,
                        encoded_output_codec_property_value(
                            item,
                            options,
                            condition.property,
                            output,
                        ),
                    )
                })
        })
}

fn encoded_output_codec_property_value(
    item: &MediaItem,
    options: &PlaybackInfoOptions,
    property: CodecConditionProperty,
    output: PlaybackOutputConstraints,
) -> Option<CodecConditionValue> {
    let source_numeric = |property| {
        codec_condition_property_value(item, options, property)
            .and_then(|value| codec_numeric_value(&value))
    };
    match property {
        CodecConditionProperty::Width => source_numeric(property)
            .map(|value| output.max_width.map_or(value, |limit| value.min(limit)))
            .map(CodecConditionValue::Numeric),
        CodecConditionProperty::Height => source_numeric(property)
            .map(|value| output.max_height.map_or(value, |limit| value.min(limit)))
            .map(CodecConditionValue::Numeric),
        CodecConditionProperty::VideoBitrate => output
            .video_bitrate
            .or_else(|| source_numeric(property))
            .map(CodecConditionValue::Numeric),
        CodecConditionProperty::AudioBitrate => output
            .audio_bitrate
            .or_else(|| source_numeric(property))
            .map(CodecConditionValue::Numeric),
        CodecConditionProperty::VideoProfile => Some(CodecConditionValue::Text(
            output
                .video_profile
                .unwrap_or(H264Profile::Main)
                .as_str()
                .to_string(),
        )),
        CodecConditionProperty::AudioProfile => Some(CodecConditionValue::Text(
            output
                .audio_profile
                .unwrap_or(AacProfile::LowComplexity)
                .as_str()
                .to_string(),
        )),
        CodecConditionProperty::VideoLevel => output
            .video_level
            .map(u32::from)
            .map(CodecConditionValue::Numeric),
        CodecConditionProperty::VideoBitDepth => Some(CodecConditionValue::Numeric(u32::from(
            output.video_bit_depth.unwrap_or(8),
        ))),
        CodecConditionProperty::VideoFrameRate => output
            .max_video_frame_rate_millihertz
            .or_else(|| source_numeric(property))
            .map(CodecConditionValue::Numeric),
        CodecConditionProperty::AudioChannels => Some(CodecConditionValue::Numeric(u32::from(
            output.audio_channels.unwrap_or(2),
        ))),
    }
}

fn playback_output_constraints(
    item: &MediaItem,
    options: &PlaybackInfoOptions,
    profile: Option<&TranscodingProfileMatcher>,
    video_mode: HlsStreamMode,
    audio_mode: HlsStreamMode,
) -> Option<PlaybackOutputConstraints> {
    let mut output = PlaybackOutputConstraints {
        max_width: profile.and_then(|profile| profile.max_width),
        max_height: profile.and_then(|profile| profile.max_height),
        video_bitrate: profile.and_then(|profile| profile.video_bitrate),
        audio_bitrate: profile.and_then(|profile| profile.audio_bitrate),
        ..PlaybackOutputConstraints::default()
    };

    if video_mode == HlsStreamMode::Encode {
        if codec_output_has_invalid_required_condition(item, options, "Video", "h264") {
            return None;
        }
        output.max_width = min_optional_u32(
            output.max_width,
            codec_output_upper_bound(
                item,
                options,
                "Video",
                "h264",
                CodecConditionProperty::Width,
            ),
        );
        output.max_height = min_optional_u32(
            output.max_height,
            codec_output_upper_bound(
                item,
                options,
                "Video",
                "h264",
                CodecConditionProperty::Height,
            ),
        );
        output.video_bitrate = min_optional_u32(
            output.video_bitrate,
            codec_output_upper_bound(
                item,
                options,
                "Video",
                "h264",
                CodecConditionProperty::VideoBitrate,
            ),
        );
        output.video_profile = selected_h264_output_profile(item, options)?;
        output.video_level = selected_h264_output_level(item, options)?;
        output.video_bit_depth = selected_video_bit_depth(item, options)?;
        output.max_video_frame_rate_millihertz = selected_video_frame_rate_limit(item, options)?;
    } else {
        output.max_width = None;
        output.max_height = None;
        output.video_bitrate = None;
    }

    if audio_mode == HlsStreamMode::Encode {
        if codec_output_has_invalid_required_condition(item, options, "Audio", "aac") {
            return None;
        }
        output.audio_bitrate = min_optional_u32(
            output.audio_bitrate,
            codec_output_upper_bound(
                item,
                options,
                "Audio",
                "aac",
                CodecConditionProperty::AudioBitrate,
            ),
        );
        output.audio_profile = selected_aac_output_profile(item, options)?;
        output.audio_channels = selected_aac_output_channels(item, options)?;
    } else {
        output.audio_bitrate = None;
    }

    if let Some(max_total_bitrate) = options.max_streaming_bitrate {
        if item.media_type.eq_ignore_ascii_case("Audio") {
            if audio_mode == HlsStreamMode::Encode {
                output.audio_bitrate = Some(
                    output
                        .audio_bitrate
                        .unwrap_or(192_000)
                        .min(max_total_bitrate),
                );
            }
        } else {
            // Codec evidence and stream presence are separate concerns. Plugin VOD may expose
            // an ordered audio track before it knows the elementary codec; that track still
            // consumes output bandwidth when FFmpeg encodes it to AAC.
            let has_audio = options
                .audio_stream_index
                .or_else(|| default_audio_stream_index(&media_item_streams(item)))
                .is_some();
            let audio_budget = if has_audio {
                let suggested = max_total_bitrate
                    .saturating_div(5)
                    .clamp(16_000, 192_000)
                    .min(max_total_bitrate.saturating_div(2).max(1));
                if audio_mode == HlsStreamMode::Encode {
                    let constrained = output.audio_bitrate.unwrap_or(192_000).min(suggested);
                    output.audio_bitrate = Some(constrained);
                    constrained
                } else {
                    codec_condition_property_value(
                        item,
                        options,
                        CodecConditionProperty::AudioBitrate,
                    )
                    .and_then(|value| codec_numeric_value(&value))
                    .unwrap_or(suggested)
                    .min(max_total_bitrate.saturating_sub(1))
                }
            } else {
                0
            };
            if video_mode == HlsStreamMode::Encode {
                let video_budget = max_total_bitrate.saturating_sub(audio_budget).max(1);
                output.video_bitrate = Some(
                    output
                        .video_bitrate
                        .unwrap_or(video_budget)
                        .min(video_budget),
                );
            }
        }
    }
    if video_mode == HlsStreamMode::Encode {
        // MaxStreamingBitrate is a transport ceiling, not a desired encoder bitrate. Browsers
        // commonly advertise values around 140 Mbps; using that directly turned a 2.1 Mbps source
        // into 30-50 MiB HLS segments. Bound software H.264 relative to the source while retaining
        // enough headroom for HEVC-to-AVC efficiency differences. Remote plugin catalogues do not
        // necessarily know the source bitrate before JIT playback; the server ceiling remains the
        // safe bound in that case instead of inheriting the client's transport maximum.
        let source_relative_ceiling = item
            .bitrate
            .and_then(positive_u32)
            .map(|source_bitrate| {
                source_bitrate
                    .saturating_mul(2)
                    .clamp(MIN_VIDEO_TRANSCODE_BITRATE, MAX_VIDEO_TRANSCODE_BITRATE)
            })
            .unwrap_or(MAX_VIDEO_TRANSCODE_BITRATE);
        output.video_bitrate = Some(
            output
                .video_bitrate
                .unwrap_or(source_relative_ceiling)
                .min(source_relative_ceiling),
        );
    }
    if video_mode == HlsStreamMode::Encode
        && !encoded_output_codec_conditions_compatible(item, options, "Video", "h264", output)
    {
        return None;
    }
    if audio_mode == HlsStreamMode::Encode
        && !encoded_output_codec_conditions_compatible(item, options, "Audio", "aac", output)
    {
        return None;
    }
    Some(output)
}

fn push_transcode_reason(reasons: &mut Vec<&'static str>, reason: &'static str) {
    if !reasons.contains(&reason) {
        reasons.push(reason);
    }
}

fn codec_condition_incompatibility_reasons(
    item: &MediaItem,
    options: &PlaybackInfoOptions,
    stream_type: &str,
) -> Vec<&'static str> {
    let properties: &[CodecConditionProperty] = if stream_type.eq_ignore_ascii_case("Video") {
        &[
            CodecConditionProperty::VideoProfile,
            CodecConditionProperty::VideoLevel,
            CodecConditionProperty::VideoBitDepth,
            CodecConditionProperty::VideoFrameRate,
            CodecConditionProperty::Width,
            CodecConditionProperty::Height,
            CodecConditionProperty::VideoBitrate,
        ]
    } else {
        &[
            CodecConditionProperty::AudioProfile,
            CodecConditionProperty::AudioChannels,
            CodecConditionProperty::AudioBitrate,
        ]
    };
    let mut reasons = Vec::new();
    for property in properties {
        if codec_condition_property_compatible(item, options, stream_type, *property) {
            continue;
        }
        let reason = match property {
            CodecConditionProperty::VideoProfile => "VideoProfileNotSupported",
            CodecConditionProperty::VideoLevel => "VideoLevelNotSupported",
            CodecConditionProperty::VideoBitDepth => "VideoBitDepthNotSupported",
            CodecConditionProperty::VideoFrameRate => "VideoFramerateNotSupported",
            CodecConditionProperty::Width | CodecConditionProperty::Height => {
                "VideoResolutionNotSupported"
            }
            CodecConditionProperty::VideoBitrate => "ContainerBitrateExceedsLimit",
            CodecConditionProperty::AudioProfile => "AudioProfileNotSupported",
            CodecConditionProperty::AudioChannels => "AudioChannelsNotSupported",
            CodecConditionProperty::AudioBitrate => "AudioBitrateNotSupported",
        };
        push_transcode_reason(&mut reasons, reason);
    }
    if codec_conditions_have_unknown_required_condition(item, options, stream_type) {
        push_transcode_reason(&mut reasons, "NoCompatibleStream");
    }
    reasons
}

fn hls_video_stream_copy_supported(item: &MediaItem) -> bool {
    item.media_type != "Video"
        || media_item_stream_codec(item, "Video")
            .is_some_and(|codec| codec.eq_ignore_ascii_case("h264"))
}

fn hls_audio_stream_copy_supported(item: &MediaItem, options: &PlaybackInfoOptions) -> bool {
    let selected_index = options
        .audio_stream_index
        .or_else(|| default_audio_stream_index(&media_item_streams(item)));
    let Some(selected_index) = selected_index else {
        return true;
    };
    media_item_stream_codec_by_index(item, "Audio", selected_index)
        .is_some_and(|codec| matches!(codec.to_ascii_lowercase().as_str(), "aac" | "mp3"))
}

fn playback_delivery_decision(
    item: &MediaItem,
    metadata: Option<&serde_json::Value>,
    options: &PlaybackInfoOptions,
) -> TranscodeDecision {
    playback_delivery_decision_with_ffmpeg_mode(item, metadata, options, configured_ffmpeg_mode())
}

fn playback_delivery_decision_with_ffmpeg_mode(
    item: &MediaItem,
    metadata: Option<&serde_json::Value>,
    options: &PlaybackInfoOptions,
    ffmpeg_mode: FfmpegMode,
) -> TranscodeDecision {
    let plugin_vod_remote = is_plugin_vod_remote_media(metadata);
    let is_remote = is_xtream_remote_media(metadata) || plugin_vod_remote;
    let plugin_vod_stream_selection_requires_hls = options.plugin_vod_selection_hls
        && ffmpeg_mode != FfmpegMode::Disabled
        && plugin_vod_remote
        && plugin_vod_has_nondefault_stream_selection(item, options);
    // Plugin-VOD sources use the same compatibility decision as other remote media. A native
    // client whose profile accepts MPEG-TS may keep the cheap direct proxy. Browsers normally do
    // not advertise TS direct play, so they fall through to the existing HLS remux/transcode
    // planner. The signed provider URL still never enters this decision or an FFmpeg argv: the
    // transcode input is an unguessable loopback relay registered below.
    let selected_audio_needs_transcode = selected_audio_stream_needs_transcode(item, options);
    let selected_subtitle_requires_processing = options
        .subtitle_stream_index
        .is_some_and(|index| index >= 0)
        && !selected_text_subtitle_can_use_external(item, options);
    let profile_compatible = if plugin_vod_remote {
        plugin_vod_direct_stream_profile_compatible(item, options)
    } else {
        playback_profile_compatible(item, options)
    };
    let profile_codecs_compatible = playback_profile_codecs_compatible(item, options);
    let profile_video_codec_compatible = playback_profile_video_codec_compatible(item, options);
    let video_codec_conditions_compatible =
        item.media_type != "Video" || playback_codec_conditions_compatible(item, options, "Video");
    let audio_codec_conditions_compatible =
        playback_codec_conditions_compatible(item, options, "Audio");
    let max_streaming_bitrate_exceeded = options.max_streaming_bitrate.is_some_and(|limit| {
        item.bitrate
            .and_then(positive_u32)
            .is_some_and(|bitrate| bitrate > limit)
    });
    let direct_requested = options.enable_direct_play || options.enable_direct_stream;
    let direct_compatible = (profile_compatible || (!is_remote && options.enable_direct_stream))
        && video_codec_conditions_compatible
        && audio_codec_conditions_compatible
        && !max_streaming_bitrate_exceeded;
    let selected_subtitle_is_image =
        selected_subtitle_stream_is_image(&media_item_streams(item), options.subtitle_stream_index);

    if direct_requested
        && direct_compatible
        && !selected_audio_needs_transcode
        && !selected_subtitle_requires_processing
        && !plugin_vod_stream_selection_requires_hls
    {
        return TranscodeDecision {
            delivery: if is_remote {
                DeliveryMode::DirectProxy
            } else {
                DeliveryMode::DirectLocal
            },
            video: if item.media_type == "Video" {
                HlsStreamMode::Copy
            } else {
                HlsStreamMode::Drop
            },
            audio: HlsStreamMode::Copy,
            reasons: Vec::new(),
            output: PlaybackOutputConstraints::default(),
        };
    }

    let remux_video_mode = if item.media_type == "Video" {
        HlsStreamMode::Copy
    } else {
        HlsStreamMode::Drop
    };
    if ffmpeg_mode != FfmpegMode::Disabled
        && options.enable_direct_stream
        && profile_codecs_compatible
        && video_codec_conditions_compatible
        && audio_codec_conditions_compatible
        && !max_streaming_bitrate_exceeded
        && !selected_audio_needs_transcode
        && (!selected_subtitle_requires_processing || selected_text_subtitle_prefers_hls(options))
        && (hls_video_stream_copy_supported(item) || selected_text_subtitle_prefers_hls(options))
        && hls_audio_stream_copy_supported(item, options)
        && hls_transcoding_profile_supported(item, options, remux_video_mode, HlsStreamMode::Copy)
    {
        return TranscodeDecision {
            delivery: DeliveryMode::HlsRemux,
            video: remux_video_mode,
            audio: HlsStreamMode::Copy,
            reasons: vec!["ContainerNotSupported"],
            output: PlaybackOutputConstraints::default(),
        };
    }

    if ffmpeg_mode == FfmpegMode::Enabled
        && options.enable_transcoding
        && matches!(item.media_type.as_str(), "Audio" | "Video")
    {
        let mut reasons = Vec::new();
        if !profile_compatible {
            push_transcode_reason(&mut reasons, "ContainerOrCodecNotSupported");
        }
        if selected_audio_needs_transcode {
            push_transcode_reason(&mut reasons, "AudioCodecNotSupported");
        }
        if selected_subtitle_requires_processing {
            push_transcode_reason(&mut reasons, "SubtitleCodecNotSupported");
        }
        if !video_codec_conditions_compatible {
            for reason in codec_condition_incompatibility_reasons(item, options, "Video") {
                push_transcode_reason(&mut reasons, reason);
            }
        }
        if !audio_codec_conditions_compatible {
            for reason in codec_condition_incompatibility_reasons(item, options, "Audio") {
                push_transcode_reason(&mut reasons, reason);
            }
        }
        if max_streaming_bitrate_exceeded {
            push_transcode_reason(&mut reasons, "ContainerBitrateExceedsLimit");
        }
        if !direct_requested {
            push_transcode_reason(&mut reasons, "DirectPlayDisabled");
        }
        let video = if item.media_type != "Video" {
            HlsStreamMode::Drop
        } else if (plugin_vod_stream_selection_requires_hls
            || hls_video_stream_copy_supported(item))
            && profile_video_codec_compatible
            && video_codec_conditions_compatible
            && !max_streaming_bitrate_exceeded
            && !selected_subtitle_is_image
        {
            HlsStreamMode::Copy
        } else {
            HlsStreamMode::Encode
        };
        let audio = if hls_audio_stream_copy_supported(item, options)
            && !selected_audio_needs_transcode
            && audio_codec_conditions_compatible
            && !max_streaming_bitrate_exceeded
        {
            HlsStreamMode::Copy
        } else {
            HlsStreamMode::Encode
        };
        if !hls_transcoding_profile_supported(item, options, video, audio) {
            return TranscodeDecision {
                delivery: DeliveryMode::Unsupported,
                video: HlsStreamMode::Drop,
                audio: HlsStreamMode::Drop,
                reasons: vec!["NoCompatibleStream"],
                output: PlaybackOutputConstraints::default(),
            };
        }
        let profile = selected_hls_transcoding_profile(item, options, video, audio);
        let Some(output) = playback_output_constraints(item, options, profile, video, audio) else {
            push_transcode_reason(&mut reasons, "NoCompatibleStream");
            return TranscodeDecision {
                delivery: DeliveryMode::Unsupported,
                video: HlsStreamMode::Drop,
                audio: HlsStreamMode::Drop,
                reasons,
                output: PlaybackOutputConstraints::default(),
            };
        };
        return TranscodeDecision {
            delivery: DeliveryMode::HlsTranscode,
            video,
            audio,
            reasons,
            output,
        };
    }

    TranscodeDecision {
        delivery: DeliveryMode::Unsupported,
        video: HlsStreamMode::Drop,
        audio: HlsStreamMode::Drop,
        reasons: vec!["NoCompatibleStream"],
        output: PlaybackOutputConstraints::default(),
    }
}

/// Native TV clients restart `PlaybackInfo` when a user changes tracks, but their DirectStream
/// players are allowed to ignore Jellyfin's default stream indices and choose the first MPEG-TS
/// track again. Route only a non-default plugin-VOD choice through the existing HLS pipeline: its
/// FFmpeg input maps the requested audio index, while text subtitles remain authenticated HLS
/// renditions resolved just in time. Ordinary/default playback keeps the zero-CPU direct proxy.
fn plugin_vod_has_nondefault_stream_selection(
    item: &MediaItem,
    options: &PlaybackInfoOptions,
) -> bool {
    let streams = media_item_streams(item);
    let nondefault_audio = options.audio_stream_index.is_some_and(|selected| {
        default_audio_stream_index(&streams).is_some_and(|default| selected != default)
    });
    let selected_subtitle = options
        .subtitle_stream_index
        .is_some_and(|selected| selected >= 0);
    nondefault_audio || selected_subtitle
}

fn selected_audio_stream_needs_transcode(item: &MediaItem, options: &PlaybackInfoOptions) -> bool {
    if item.media_type != "Video" {
        return false;
    }
    let streams = media_item_streams(item);
    let selected_index = options
        .audio_stream_index
        .or_else(|| default_audio_stream_index(&streams));
    let Some(codec) = selected_index
        .and_then(|index| media_item_stream_codec_by_index(item, "Audio", index))
        .map(|codec| codec.to_ascii_lowercase())
    else {
        return false;
    };
    matches!(
        codec.as_str(),
        "ac3" | "eac3" | "dts" | "truehd" | "mlp" | "flac"
    )
}

fn direct_play_profile_matches(item: &MediaItem, profile: &DirectPlayProfileMatcher) -> bool {
    if let Some(profile_type) = profile.profile_type.as_deref()
        && !profile_type.eq_ignore_ascii_case(item.media_type.as_str())
    {
        return false;
    }

    let Some(container) = media_item_container(item) else {
        return false;
    };
    if !profile.containers.is_empty()
        && !profile
            .containers
            .iter()
            .any(|candidate| candidate.eq_ignore_ascii_case(&container))
    {
        return false;
    }

    if !profile.video_codecs.is_empty() {
        let Some(video_codec) = media_item_stream_codec(item, "Video") else {
            return false;
        };
        if !profile
            .video_codecs
            .iter()
            .any(|candidate| candidate.eq_ignore_ascii_case(&video_codec))
        {
            return false;
        }
    }

    if !profile.audio_codecs.is_empty()
        && let Some(audio_codec) = media_item_stream_codec(item, "Audio")
        && !profile
            .audio_codecs
            .iter()
            .any(|candidate| candidate.eq_ignore_ascii_case(&audio_codec))
    {
        return false;
    }

    true
}

fn media_item_stream_codec(item: &MediaItem, stream_type: &str) -> Option<String> {
    item.media_streams.iter().find_map(|stream| {
        let stream = stream.as_object()?;
        let type_matches = stream.get("Type").and_then(serde_json::Value::as_str)?;
        if !type_matches.eq_ignore_ascii_case(stream_type) {
            return None;
        }
        stream
            .get("Codec")
            .and_then(serde_json::Value::as_str)
            .filter(|codec| !codec.trim().is_empty())
            .map(|codec| codec.trim().to_string())
    })
}

fn media_item_stream_codec_by_index(
    item: &MediaItem,
    stream_type: &str,
    index: i64,
) -> Option<String> {
    item.media_streams.iter().find_map(|stream| {
        let stream = stream.as_object()?;
        let type_matches = stream.get("Type").and_then(serde_json::Value::as_str)?;
        if !type_matches.eq_ignore_ascii_case(stream_type) {
            return None;
        }
        if stream.get("Index").and_then(json_value_i64) != Some(index) {
            return None;
        }
        stream
            .get("Codec")
            .and_then(serde_json::Value::as_str)
            .filter(|codec| !codec.trim().is_empty())
            .map(|codec| codec.trim().to_string())
    })
}

