async fn channel_provider_items(db: &Database) -> Result<Vec<serde_json::Value>, ApiError> {
    let persisted_live_tv_count = db
        .live_tv_channel_count(&LiveTvChannelQuery::default())
        .await?;
    let live_tv_channels = if persisted_live_tv_count == 0 {
        configured_live_tv_channel_items(db).await?
    } else {
        Vec::new()
    };
    let mut providers = Vec::new();
    let live_tv_count = persisted_live_tv_count.max(live_tv_channels.len());
    if live_tv_count > 0 {
        let server_id = db.server_state().await?.server_id.to_string();
        providers.push(channel_provider_json(
            &server_id,
            "livetv",
            "Live TV",
            live_tv_count,
        ));
    }
    for provider in configured_channel_provider_descriptors(db).await? {
        if channel_provider_is_healthy(&provider)
            && let Some(provider_json) = configured_channel_provider_json(&provider)
        {
            providers.push(provider_json);
        }
    }
    for snapshot in plugin_channel_provider_snapshots(db).await? {
        if snapshot.included {
            providers.push(channel_provider_json(
                "",
                &snapshot.id,
                &snapshot.name,
                snapshot.items.len(),
            ));
        }
    }
    Ok(providers)
}

async fn channel_content_items(
    db: &Database,
    channel_id: Option<&str>,
) -> Result<Vec<serde_json::Value>, ApiError> {
    let mut items = Vec::new();
    let include_live_tv =
        channel_id.is_none_or(|channel_id| channel_id.eq_ignore_ascii_case("livetv"));
    if include_live_tv {
        let page = db
            .live_tv_channel_page(LiveTvChannelQuery {
                start_index: 0,
                limit: Some(100),
                search_term: None,
                tuner_ids: Vec::new(),
                category_ids: Vec::new(),
            })
            .await?;
        if page.total_record_count > 0 {
            let server_id = db.server_state().await?.server_id.to_string();
            items.extend(page.items.iter().map(|record| {
                let mut item = live_tv_channel_record_to_json(record, &server_id);
                item["ChannelId"] = serde_json::json!("livetv");
                item
            }));
        } else {
            items.extend(configured_live_tv_channel_items(db).await?);
            for item in &mut items {
                item["ChannelId"] = serde_json::json!("livetv");
            }
        }
    }

    for provider in configured_channel_provider_descriptors(db).await? {
        if !channel_provider_is_healthy(&provider) {
            continue;
        }
        let Some(provider_id) =
            json_string_field(&provider, "Id").or_else(|| json_string_field(&provider, "Name"))
        else {
            continue;
        };
        if channel_id.is_none_or(|channel_id| channel_id.eq_ignore_ascii_case(&provider_id)) {
            items.extend(configured_channel_content_items(&provider, &provider_id));
        }
    }

    for snapshot in plugin_channel_provider_snapshots(db).await? {
        if !snapshot.included {
            continue;
        }
        if channel_id.is_none_or(|channel_id| channel_id.eq_ignore_ascii_case(&snapshot.id)) {
            items.extend(snapshot.items);
        }
    }

    Ok(items)
}

async fn channel_content_item_by_id(
    db: &Database,
    item_id: &str,
) -> Result<Option<serde_json::Value>, ApiError> {
    Ok(channel_content_items(db, None)
        .await?
        .into_iter()
        .find(|item| json_string_field(item, "Id").is_some_and(|id| id == item_id)))
}

fn channel_content_item_media_source(
    item: &serde_json::Value,
) -> Result<serde_json::Value, ApiError> {
    if let Some(source) = item
        .get("MediaSources")
        .and_then(serde_json::Value::as_array)
        .and_then(|sources| sources.first())
        .cloned()
    {
        return Ok(source);
    }
    let item_id = json_string_field(item, "Id")
        .ok_or_else(|| ApiError::not_found("Channel item not found"))?;
    let name = json_string_field(item, "Name").unwrap_or_else(|| item_id.clone());
    let path = json_string_field(item, "Path")
        .or_else(|| json_string_field(item, "Url"))
        .or_else(|| json_string_field(item, "DirectStreamUrl"))
        .ok_or_else(|| ApiError::not_found("Channel media source not found"))?;
    let direct_stream_url =
        json_string_field(item, "DirectStreamUrl").unwrap_or_else(|| path.clone());
    let is_remote = path.starts_with("http://") || path.starts_with("https://");
    let protocol = if is_remote { "Http" } else { "File" };
    let container = std::path::Path::new(path.split('?').next().unwrap_or(&path))
        .extension()
        .and_then(|extension| extension.to_str())
        .map(str::to_ascii_lowercase)
        .filter(|extension| !extension.is_empty())
        .unwrap_or_else(|| {
            json_string_field(item, "Container").unwrap_or_else(|| "ts".to_string())
        });
    let media_type = json_string_field(item, "MediaType").unwrap_or_else(|| "Video".to_string());
    Ok(serde_json::json!({
        "Protocol": protocol,
        "Id": item_id,
        "Path": path,
        "Type": "Default",
        "Container": container.clone(),
        "Name": name,
        "IsRemote": is_remote,
        "DirectStreamUrl": direct_stream_url,
        "ETag": null,
        "RunTimeTicks": item.get("RunTimeTicks").cloned().unwrap_or(serde_json::Value::Null),
        "ReadAtNativeFramerate": false,
        "SupportsTranscoding": false,
        "SupportsDirectStream": true,
        "SupportsDirectPlay": true,
        "IsInfiniteStream": false,
        "RequiresOpening": false,
        "RequiresClosing": true,
        "RequiresLooping": false,
        "SupportsProbing": false,
        "VideoType": if media_type.eq_ignore_ascii_case("Video") { "VideoFile" } else { "Unknown" },
        "MediaStreams": item.get("MediaStreams").cloned().unwrap_or_else(|| serde_json::json!([{
            "Codec": container,
            "Type": media_type.clone(),
            "Index": 0,
            "IsInterlaced": false
        }])),
        "Formats": [],
        "Bitrate": item.get("Bitrate").cloned().unwrap_or(serde_json::Value::Null)
    }))
}

fn channel_item_image_infos(item: &serde_json::Value) -> Result<Vec<serde_json::Value>, ApiError> {
    let Some((bytes, mime_type)) = channel_item_primary_image_payload(item)? else {
        return Ok(Vec::new());
    };
    Ok(vec![serde_json::json!({
        "ImageType": "Primary",
        "ImageIndex": 0,
        "ImageTag": channel_item_image_tag(&bytes),
        "Size": bytes.len(),
        "MimeType": mime_type,
    })])
}

fn channel_item_image_response(
    item: &serde_json::Value,
    image_type: &str,
    image_index: usize,
) -> Result<Option<axum::response::Response>, ApiError> {
    if !image_type.eq_ignore_ascii_case("Primary") || image_index != 0 {
        return Ok(None);
    }
    let Some((bytes, mime_type)) = channel_item_primary_image_payload(item)? else {
        return Ok(None);
    };
    let mut headers = HeaderMap::new();
    headers.insert(header::CONTENT_TYPE, mime_type.parse().unwrap());
    headers.insert(
        header::CACHE_CONTROL,
        "public, max-age=3600".parse().unwrap(),
    );
    headers.insert(
        header::ETAG,
        channel_item_image_tag(&bytes).parse().unwrap(),
    );
    Ok(Some((headers, bytes).into_response()))
}

fn channel_item_primary_image_payload(
    item: &serde_json::Value,
) -> Result<Option<(Vec<u8>, String)>, ApiError> {
    if let Some(image_url) = json_string_field(item, "ImageUrl") {
        if let Some(payload) = data_uri_image_payload(&image_url)? {
            return Ok(Some(payload));
        }
        if let Some((bytes, mime_type)) = plugin_remote_image_payload_from_id(&image_url)? {
            return Ok(Some((bytes, mime_type)));
        }
    }
    let Some(base64_data) = json_string_any_field(
        item,
        &["ImageBase64Data", "ImageData", "Base64Data", "Data"],
    ) else {
        return Ok(None);
    };
    let bytes = general_purpose::STANDARD
        .decode(base64_data.as_bytes())
        .map_err(|error| {
            ApiError::bad_request(format!("Invalid channel image payload: {error}"))
        })?;
    if bytes.is_empty() {
        return Ok(None);
    }
    let mime_type = json_string_any_field(item, &["ImageMimeType", "MimeType", "ContentType"])
        .unwrap_or_else(|| image_format_from_bytes(&bytes).content_type.to_string());
    Ok(Some((bytes, mime_type)))
}

fn data_uri_image_payload(value: &str) -> Result<Option<(Vec<u8>, String)>, ApiError> {
    let Some(rest) = value.strip_prefix("data:") else {
        return Ok(None);
    };
    let Some((metadata, data)) = rest.split_once(',') else {
        return Ok(None);
    };
    let mut metadata_parts = metadata.split(';');
    let mime_type = metadata_parts
        .next()
        .filter(|part| !part.is_empty())
        .unwrap_or("application/octet-stream")
        .to_string();
    if !metadata_parts.any(|part| part.eq_ignore_ascii_case("base64")) {
        return Ok(None);
    }
    let bytes = general_purpose::STANDARD
        .decode(data.as_bytes())
        .map_err(|error| {
            ApiError::bad_request(format!("Invalid channel image data URI: {error}"))
        })?;
    if bytes.is_empty() {
        return Ok(None);
    }
    Ok(Some((bytes, mime_type)))
}

fn channel_item_primary_image_tag(item: &serde_json::Value) -> Option<String> {
    channel_item_primary_image_payload(item)
        .ok()
        .flatten()
        .map(|(bytes, _)| channel_item_image_tag(&bytes))
}

fn channel_item_image_tag(bytes: &[u8]) -> String {
    format!("{:x}-{:x}", bytes.len(), fnv1a64(bytes, 0x4f958f3c72a1d12b))
}

fn filter_channel_items_by_search(items: &mut Vec<serde_json::Value>, search_term: Option<&str>) {
    let Some(search_term) = search_term.map(str::trim).filter(|term| !term.is_empty()) else {
        return;
    };
    let search_term = search_term.to_ascii_lowercase();
    items.retain(|item| {
        ["Name", "SortName", "Id", "Number", "ChannelNumber"]
            .iter()
            .filter_map(|field| json_string_field(item, field))
            .any(|value| value.to_ascii_lowercase().contains(&search_term))
    });
}

async fn channel_feature_items(
    db: &Database,
    channel_id: Option<&str>,
) -> Result<Vec<serde_json::Value>, ApiError> {
    let mut features = Vec::new();
    let has_live_tv = db
        .live_tv_channel_count(&LiveTvChannelQuery::default())
        .await?
        > 0
        || !configured_live_tv_channel_items(db).await?.is_empty();
    if has_live_tv && channel_id.is_none_or(|channel_id| channel_id.eq_ignore_ascii_case("livetv"))
    {
        features.push(serde_json::json!({
            "Name": "Live TV",
            "Id": "livetv",
            "ChannelId": "livetv",
            "ContentType": "TvChannel",
            "MediaTypes": ["Video"],
            "SupportsLatestItems": true,
            "SupportsMediaDeletion": false,
            "SupportsSortOrderToggle": true,
            "SupportsFavoriteItems": false,
            "SupportsContentDownloading": false,
            "AutoRefreshLevels": 0,
            "DefaultSortFields": ["SortName"],
        }));
    }
    for provider in configured_channel_provider_descriptors(db).await? {
        if !channel_provider_is_healthy(&provider) {
            continue;
        }
        let Some(provider_id) =
            json_string_field(&provider, "Id").or_else(|| json_string_field(&provider, "Name"))
        else {
            continue;
        };
        if channel_id.is_none_or(|channel_id| channel_id.eq_ignore_ascii_case(&provider_id)) {
            features.push(channel_feature_json(
                &provider_id,
                &json_string_field(&provider, "Name").unwrap_or_else(|| provider_id.clone()),
            ));
        }
    }
    for snapshot in plugin_channel_provider_snapshots(db).await? {
        if snapshot.included
            && channel_id.is_none_or(|channel_id| channel_id.eq_ignore_ascii_case(&snapshot.id))
        {
            features.push(channel_feature_json(&snapshot.id, &snapshot.name));
        }
    }
    if features.is_empty()
        && channel_id.is_some_and(|channel_id| {
            !channel_id.eq_ignore_ascii_case("livetv") && !channel_id.trim().is_empty()
        })
        && let Some(channel_id) = channel_id
    {
        features.push(channel_feature_json(channel_id, channel_id));
    }
    Ok(features)
}

async fn configured_live_tv_channel_items(
    db: &Database,
) -> Result<Vec<serde_json::Value>, ApiError> {
    let config = db
        .named_configuration("livetv")
        .await?
        .unwrap_or_else(default_live_tv_configuration);
    let server_id = db.server_state().await?.server_id.to_string();
    Ok(live_tv_channel_items(&config, &server_id))
}

async fn configured_channel_provider_descriptors(
    db: &Database,
) -> Result<Vec<serde_json::Value>, ApiError> {
    Ok(db
        .named_configuration("channels")
        .await?
        .unwrap_or_else(default_channels_configuration)
        .get("Providers")
        .and_then(serde_json::Value::as_array)
        .cloned()
        .unwrap_or_default())
}

async fn channel_provider_diagnostics(db: &Database) -> Result<Vec<serde_json::Value>, ApiError> {
    let persisted_live_tv_count = db
        .live_tv_channel_count(&LiveTvChannelQuery::default())
        .await?;
    let live_tv_channels = if persisted_live_tv_count == 0 {
        configured_live_tv_channel_items(db).await?
    } else {
        Vec::new()
    };
    let live_tv_count = persisted_live_tv_count.max(live_tv_channels.len());
    let mut providers = Vec::new();
    providers.push(serde_json::json!({
        "Id": "livetv",
        "Name": "Live TV",
        "Enabled": true,
        "Status": if live_tv_count == 0 { "Unavailable" } else { "Healthy" },
        "FailureMode": null,
        "ChildCount": live_tv_count,
        "Included": live_tv_count > 0
    }));
    for provider in configured_channel_provider_descriptors(db).await? {
        let id = json_string_field(&provider, "Id")
            .or_else(|| json_string_field(&provider, "Name"))
            .unwrap_or_else(|| "provider".to_string());
        let name = json_string_field(&provider, "Name").unwrap_or_else(|| id.clone());
        let enabled = provider
            .get("Enabled")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(true);
        let failure_mode = json_string_field(&provider, "FailureMode");
        let healthy = enabled && channel_provider_is_healthy(&provider);
        providers.push(serde_json::json!({
            "Id": id,
            "Name": name,
            "Enabled": enabled,
            "Status": if healthy { "Healthy" } else { "Malfunctioned" },
            "FailureMode": failure_mode,
            "ChildCount": provider.get("Items").and_then(serde_json::Value::as_array).map(Vec::len).unwrap_or(0),
            "Included": healthy
        }));
    }
    for snapshot in plugin_channel_provider_snapshots(db).await? {
        providers.push(serde_json::json!({
            "Id": snapshot.id,
            "Name": snapshot.name,
            "Enabled": true,
            "Runtime": snapshot.runtime,
            "Status": snapshot.status,
            "FailureMode": snapshot.failure_mode,
            "ChildCount": snapshot.items.len(),
            "Included": snapshot.included
        }));
    }
    Ok(providers)
}

async fn refresh_channel_provider_cache(db: &Database) -> Result<serde_json::Value, ApiError> {
    let mut config = db
        .named_configuration("channels")
        .await?
        .unwrap_or_else(default_channels_configuration);
    let refreshed_at = format_time_for_json(OffsetDateTime::now_utc());
    let images_cached = hydrate_configured_channel_provider_remote_images(&mut config).await?;
    let mut provider_cache = Vec::new();
    let live_tv_channels = configured_live_tv_channel_items(db).await?;
    if !live_tv_channels.is_empty() {
        provider_cache.push(serde_json::json!({
            "Id": "livetv",
            "Name": "Live TV",
            "Source": "LiveTv",
            "Status": "Healthy",
            "ItemCount": live_tv_channels.len(),
            "ItemIds": live_tv_channels
                .iter()
                .filter_map(|item| json_string_field(item, "Id"))
                .collect::<Vec<_>>(),
            "RefreshedAtUtc": refreshed_at,
        }));
    }
    let configured_providers = config
        .get("Providers")
        .and_then(serde_json::Value::as_array)
        .cloned()
        .unwrap_or_default();
    for provider in configured_providers {
        let provider_id = json_string_field(&provider, "Id")
            .or_else(|| json_string_field(&provider, "Name"))
            .unwrap_or_else(|| "provider".to_string());
        let provider_name =
            json_string_field(&provider, "Name").unwrap_or_else(|| provider_id.clone());
        let items = configured_channel_content_items(&provider, &provider_id);
        let healthy = channel_provider_is_healthy(&provider);
        provider_cache.push(serde_json::json!({
            "Id": provider_id,
            "Name": provider_name,
            "Source": "Configured",
            "Status": if healthy { "Healthy" } else { "Malfunctioned" },
            "FailureMode": json_string_field(&provider, "FailureMode"),
            "ItemCount": if healthy { items.len() } else { 0 },
            "ImageCacheCount": if healthy { channel_items_with_embedded_images(&items) } else { 0 },
            "ItemIds": if healthy {
                serde_json::Value::Array(items
                    .iter()
                    .filter_map(|item| json_string_field(item, "Id").map(serde_json::Value::String))
                    .collect())
            } else {
                serde_json::json!([])
            },
            "RefreshedAtUtc": refreshed_at,
        }));
    }
    for snapshot in plugin_channel_provider_snapshots(db).await? {
        provider_cache.push(serde_json::json!({
            "Id": snapshot.id,
            "Name": snapshot.name,
            "Source": "Plugin",
            "Runtime": snapshot.runtime,
            "Status": snapshot.status,
            "FailureMode": snapshot.failure_mode,
            "ItemCount": if snapshot.included { snapshot.items.len() } else { 0 },
            "ItemIds": if snapshot.included {
                serde_json::Value::Array(snapshot.items
                    .iter()
                    .filter_map(|item| json_string_field(item, "Id").map(serde_json::Value::String))
                    .collect())
            } else {
                serde_json::json!([])
            },
            "RefreshedAtUtc": refreshed_at,
        }));
    }
    let provider_count = provider_cache.len();
    let item_count: usize = provider_cache
        .iter()
        .filter_map(|provider| {
            provider
                .get("ItemCount")
                .and_then(serde_json::Value::as_u64)
        })
        .map(|count| count as usize)
        .sum();
    let mut refresh_history = config
        .get("RefreshHistory")
        .and_then(serde_json::Value::as_array)
        .cloned()
        .unwrap_or_default();
    refresh_history.insert(
        0,
        serde_json::json!({
            "Status": "Completed",
            "RefreshedAtUtc": refreshed_at,
            "ProviderCount": provider_count,
            "ItemCount": item_count,
        }),
    );
    refresh_history.truncate(10);
    config["ProviderCache"] = serde_json::Value::Array(provider_cache);
    config["RefreshHistory"] = serde_json::Value::Array(refresh_history);
    config["LastRefreshUtc"] = serde_json::Value::String(refreshed_at);
    let normalized = channels_configuration_json(config);
    let cache_updated_at = normalized
        .get("LastRefreshUtc")
        .cloned()
        .unwrap_or(serde_json::Value::Null);
    ConfigurationService::new(db)
        .set("channels", normalized)
        .await?;
    Ok(serde_json::json!({
        "ProvidersRefreshed": provider_count,
        "ItemsCached": item_count,
        "ImagesCached": images_cached,
        "CacheUpdatedAtUtc": cache_updated_at,
    }))
}

async fn hydrate_configured_channel_provider_remote_images(
    config: &mut serde_json::Value,
) -> Result<usize, ApiError> {
    let refreshed_at = format_time_for_json(OffsetDateTime::now_utc());
    let Some(providers) = config
        .get_mut("Providers")
        .and_then(serde_json::Value::as_array_mut)
    else {
        return Ok(0);
    };
    let mut images_cached = 0;
    for provider in providers {
        if !channel_provider_is_healthy(provider) {
            continue;
        }
        let Some(items) = provider
            .get_mut("Items")
            .and_then(serde_json::Value::as_array_mut)
        else {
            continue;
        };
        for item in items {
            if channel_item_primary_image_payload(item)?.is_some() {
                continue;
            }
            let Some(image_url) = json_string_field(item, "ImageUrl") else {
                continue;
            };
            if !image_url.starts_with("http://") && !image_url.starts_with("https://") {
                continue;
            }
            let Some((bytes, mime_type)) = fetch_channel_remote_image_payload(&image_url).await?
            else {
                continue;
            };
            item["ImageBase64Data"] =
                serde_json::Value::String(general_purpose::STANDARD.encode(&bytes));
            item["ImageMimeType"] = serde_json::Value::String(mime_type);
            item["ImageCacheSourceUrl"] = serde_json::Value::String(image_url);
            item["ImageCacheUpdatedAtUtc"] = serde_json::Value::String(refreshed_at.clone());
            images_cached += 1;
        }
    }
    Ok(images_cached)
}

async fn fetch_channel_remote_image_payload(
    image_url: &str,
) -> Result<Option<(Vec<u8>, String)>, ApiError> {
    match fetch_remote_image_payload(image_url).await {
        Ok((bytes, mime_type)) => Ok(Some((
            bytes,
            mime_type.unwrap_or_else(|| "application/octet-stream".to_string()),
        ))),
        Err(error) if error.status() == StatusCode::NOT_FOUND => Ok(None),
        Err(error) => Err(error),
    }
}

fn channel_items_with_embedded_images(items: &[serde_json::Value]) -> usize {
    items
        .iter()
        .filter(|item| {
            channel_item_primary_image_payload(item)
                .ok()
                .flatten()
                .is_some()
        })
        .count()
}

fn channel_provider_is_healthy(provider: &serde_json::Value) -> bool {
    if provider
        .get("Enabled")
        .and_then(serde_json::Value::as_bool)
        .is_some_and(|enabled| !enabled)
    {
        return false;
    }
    if json_string_field(provider, "FailureMode").is_some_and(|mode| !mode.trim().is_empty()) {
        return false;
    }
    !json_string_field(provider, "Status").is_some_and(|status| {
        status.eq_ignore_ascii_case("failed")
            || status.eq_ignore_ascii_case("malfunctioned")
            || status.eq_ignore_ascii_case("timeout")
    })
}

fn configured_channel_provider_json(provider: &serde_json::Value) -> Option<serde_json::Value> {
    let id = json_string_field(provider, "Id").or_else(|| json_string_field(provider, "Name"))?;
    let name = json_string_field(provider, "Name").unwrap_or_else(|| id.clone());
    let child_count = provider
        .get("Items")
        .and_then(serde_json::Value::as_array)
        .map(Vec::len)
        .unwrap_or(0);
    Some(channel_provider_json("", &id, &name, child_count))
}

fn configured_channel_content_items(
    provider: &serde_json::Value,
    provider_id: &str,
) -> Vec<serde_json::Value> {
    provider
        .get("Items")
        .and_then(serde_json::Value::as_array)
        .into_iter()
        .flatten()
        .enumerate()
        .map(|(index, item)| channel_content_item_json(item, provider_id, index))
        .collect()
}

#[derive(Debug)]
struct PluginChannelProviderSnapshot {
    id: String,
    name: String,
    runtime: String,
    status: String,
    failure_mode: Option<String>,
    included: bool,
    items: Vec<serde_json::Value>,
}

async fn plugin_channel_provider_snapshots(
    db: &Database,
) -> Result<Vec<PluginChannelProviderSnapshot>, ApiError> {
    let mut snapshots = Vec::new();
    for plugin in db.installed_plugins_json().await? {
        if !plugin_is_active_channel_provider(&plugin) {
            continue;
        }
        snapshots.push(plugin_channel_provider_snapshot(db, &plugin).await);
    }
    Ok(snapshots)
}

async fn plugin_channel_provider_snapshot(
    db: &Database,
    plugin: &serde_json::Value,
) -> PluginChannelProviderSnapshot {
    let id =
        json_string_field(plugin, "Id").unwrap_or_else(|| "plugin-channel-provider".to_string());
    let name = json_string_field(plugin, "Name").unwrap_or_else(|| id.clone());
    let runtime = json_string_field(plugin, "Runtime").unwrap_or_else(|| "Unknown".to_string());
    match invoke_installed_plugin_capability_via_runtime_host(
        db,
        plugin,
        "ChannelProvider",
        serde_json::json!({ "Operation": "GetItems" }),
    )
    .await
    {
        Ok(Some(result)) => {
            let items = result
                .value
                .get("Items")
                .and_then(serde_json::Value::as_array)
                .into_iter()
                .flatten()
                .enumerate()
                .map(|(index, item)| channel_content_item_json(item, &id, index))
                .collect::<Vec<_>>();
            PluginChannelProviderSnapshot {
                id,
                name,
                runtime,
                status: "Healthy".to_string(),
                failure_mode: None,
                included: true,
                items,
            }
        }
        Ok(None) => PluginChannelProviderSnapshot {
            id,
            name,
            runtime,
            status: "Malfunctioned".to_string(),
            failure_mode: Some("runtime-unavailable".to_string()),
            included: false,
            items: Vec::new(),
        },
        Err(error) => PluginChannelProviderSnapshot {
            id,
            name,
            runtime,
            status: "Malfunctioned".to_string(),
            failure_mode: Some(format!("{error:?}")),
            included: false,
            items: Vec::new(),
        },
    }
}

fn plugin_is_active_channel_provider(plugin: &serde_json::Value) -> bool {
    json_string_field(plugin, "Status").as_deref() == Some("Active")
        && plugin_string_array(plugin.get("Capabilities"))
            .iter()
            .any(|capability| {
                capability.eq_ignore_ascii_case("ChannelProvider")
                    || capability.eq_ignore_ascii_case(CAPABILITY_LIVE_TV_PROVIDER)
            })
}

fn channel_content_item_json(
    item: &serde_json::Value,
    channel_id: &str,
    index: usize,
) -> serde_json::Value {
    let id = json_string_field(item, "Id").unwrap_or_else(|| format!("{channel_id}-item-{index}"));
    let name = json_string_field(item, "Name").unwrap_or_else(|| id.clone());
    let media_type = json_string_field(item, "MediaType").unwrap_or_else(|| "Video".to_string());
    let item_type =
        json_string_field(item, "Type").unwrap_or_else(|| "ChannelVideoItem".to_string());
    let path = json_string_field(item, "Path");
    let image_url = json_string_field(item, "ImageUrl");
    let image_tags = channel_item_primary_image_tag(item)
        .map(|tag| serde_json::json!({ "Primary": tag }))
        .unwrap_or_else(|| serde_json::json!({}));
    serde_json::json!({
        "Name": name,
        "ServerId": "",
        "Id": id,
        "Etag": null,
        "DateCreated": null,
        "CanDelete": false,
        "CanDownload": false,
        "SortName": json_string_field(item, "SortName").unwrap_or_else(|| name.clone()),
        "ExternalUrls": [],
        "Path": path,
        "Overview": json_string_field(item, "Overview").unwrap_or_default(),
        "ChannelId": channel_id,
        "ProviderIds": item.get("ProviderIds").cloned().unwrap_or_else(|| serde_json::json!({ "JellyrinChannelProvider": channel_id })),
        "UserData": {
            "PlaybackPositionTicks": 0,
            "PlayCount": 0,
            "IsFavorite": false,
            "Played": false,
            "Key": id,
            "ItemId": id
        },
        "IsFolder": false,
        "Type": item_type,
        "MediaType": media_type,
        "ImageTags": image_tags,
        "ImageUrl": image_url,
        "ImageBase64Data": json_string_any_field(item, &["ImageBase64Data", "ImageData", "Base64Data", "Data"]),
        "ImageMimeType": json_string_any_field(item, &["ImageMimeType", "MimeType", "ContentType"]),
        "ImageCacheSourceUrl": json_string_field(item, "ImageCacheSourceUrl"),
        "ImageCacheUpdatedAtUtc": json_string_field(item, "ImageCacheUpdatedAtUtc"),
        "BackdropImageTags": [],
        "LocationType": "Virtual"
    })
}

fn channel_feature_json(id: &str, name: &str) -> serde_json::Value {
    serde_json::json!({
        "Name": name,
        "Id": id,
        "ChannelId": id,
        "ContentType": "ChannelVideoItem",
        "MediaTypes": ["Video"],
        "SupportsLatestItems": true,
        "SupportsMediaDeletion": false,
        "SupportsSortOrderToggle": true,
        "SupportsFavoriteItems": false,
        "SupportsContentDownloading": false,
        "AutoRefreshLevels": 0,
        "DefaultSortFields": ["SortName"],
    })
}

fn channel_provider_json(
    server_id: &str,
    id: &str,
    name: &str,
    child_count: usize,
) -> serde_json::Value {
    serde_json::json!({
        "Name": name,
        "ServerId": server_id,
        "Id": id,
        "Etag": null,
        "DateCreated": null,
        "CanDelete": false,
        "CanDownload": false,
        "SortName": name,
        "ExternalUrls": [],
        "Path": null,
        "Overview": "",
        "EnableMediaSourceDisplay": true,
        "ChannelId": id,
        "Taglines": [],
        "Genres": [],
        "PlayAccess": "Full",
        "RemoteTrailers": [],
        "ProviderIds": { "JellyrinLocal": id },
        "UserData": {
            "PlaybackPositionTicks": 0,
            "PlayCount": 0,
            "IsFavorite": false,
            "Played": false,
            "Key": id,
            "ItemId": id
        },
        "IsFolder": true,
        "ParentId": null,
        "Type": "Channel",
        "MediaType": null,
        "ChildCount": child_count,
        "SupportsLatestItems": true,
        "SupportsMediaDeletion": false,
        "ImageTags": {},
        "BackdropImageTags": [],
        "LocationType": "Virtual"
    })
}

