async fn authenticated_item_theme_items(
    state: AppState,
    headers: HeaderMap,
    auth_query: AuthQuery,
    item_id: String,
    raw_query: Option<String>,
    media_type: &str,
) -> Result<Json<serde_json::Value>, ApiError> {
    let query = parse_items_query(raw_query.as_deref());
    let auth_user =
        require_request_user(&state.db, &headers, auth_query.api_key.as_deref()).await?;
    let requested_user_id = query
        .user_id
        .as_deref()
        .map(resolve_user_id)
        .transpose()?
        .unwrap_or(auth_user.id);
    ensure_user_access(&auth_user, requested_user_id)?;
    let source = match media_item_by_id(&state.db, &item_id).await {
        Ok(source) => source,
        Err(error)
            if error.status == StatusCode::NOT_FOUND
                && virtual_or_live_tv_item_exists(&state.db, &item_id).await? =>
        {
            return Ok(Json(theme_media_query_result(
                Vec::new(),
                0,
                query.start_index.unwrap_or(0),
                &item_id,
            )));
        }
        Err(error) => return Err(error),
    };
    Ok(Json(
        theme_items_result(&state.db, &source, requested_user_id, media_type, &query).await?,
    ))
}

async fn theme_items_result(
    db: &Database,
    source: &MediaItem,
    user_id: Uuid,
    media_type: &str,
    query: &ItemsQuery,
) -> Result<serde_json::Value, ApiError> {
    // Opaque remote VOD paths cannot own local theme media. Returning the canonical empty result
    // here keeps the detail-page fan-out bounded even for very large provider catalogues.
    if is_plugin_vod_virtual_item(source) {
        return Ok(theme_media_query_result(
            Vec::new(),
            0,
            query.start_index.unwrap_or(0),
            &source.id.simple().to_string(),
        ));
    }
    let server_id = db.server_state().await?.server_id.to_string();
    let mut theme_items = db
        .media_items_for_virtual_folders(&[source.virtual_folder_id])
        .await?
        .into_iter()
        .filter(|item| is_theme_item_for_source(source, item, media_type))
        .collect::<Vec<_>>();
    theme_items.sort_by(|left, right| compare_media_items(left, right, &[SortField::SortName]));
    let total_record_count = theme_items.len();
    Ok(theme_media_query_result(
        items_to_json(
            db,
            paged_media_items(theme_items, query),
            &server_id,
            Some(user_id),
            false,
        )
        .await?,
        total_record_count,
        query.start_index.unwrap_or(0),
        &source.id.simple().to_string(),
    ))
}

async fn soundtrack_items_result(
    db: &Database,
    source: &MediaItem,
    user_id: Uuid,
    query: &ItemsQuery,
) -> Result<serde_json::Value, ApiError> {
    if is_plugin_vod_virtual_item(source) {
        return Ok(theme_media_query_result(
            Vec::new(),
            0,
            query.start_index.unwrap_or(0),
            &source.id.simple().to_string(),
        ));
    }
    let entries =
        MediaCatalogStore::media_items_with_metadata_by_effective_types(db, &["Audio".to_string()])
            .await?;
    let mut audio_items = Vec::with_capacity(entries.len());
    let mut metadata_by_item = HashMap::with_capacity(entries.len() + 1);
    for entry in entries {
        metadata_by_item.insert(entry.item.id, entry.metadata);
        audio_items.push(entry.item);
    }
    if !metadata_by_item.contains_key(&source.id) {
        metadata_by_item.extend(media_metadata_by_item_id(db, HashSet::from([source.id])).await?);
    }
    let source_terms = soundtrack_match_terms(metadata_by_item.get(&source.id));
    if source_terms.is_empty() {
        return Ok(theme_media_query_result(
            Vec::new(),
            0,
            0,
            &source.id.simple().to_string(),
        ));
    }

    let mut scored = audio_items
        .into_iter()
        .filter(|item| item.id != source.id && item.media_type == "Audio")
        .filter_map(|item| {
            let terms = soundtrack_match_terms(metadata_by_item.get(&item.id));
            let score = terms.intersection(&source_terms).count();
            (score > 0).then_some((score, item))
        })
        .collect::<Vec<_>>();
    scored.sort_by(|(left_score, left_item), (right_score, right_item)| {
        right_score
            .cmp(left_score)
            .then_with(|| compare_media_items(left_item, right_item, &[SortField::SortName]))
    });

    let total_record_count = scored.len();
    let items = scored
        .into_iter()
        .map(|(_, item)| item)
        .skip(query.start_index.unwrap_or(0))
        .take(query.limit.unwrap_or(usize::MAX))
        .collect::<Vec<_>>();
    let server_id = db.server_state().await?.server_id.to_string();
    Ok(theme_media_query_result(
        items_to_json(db, items, &server_id, Some(user_id), false).await?,
        total_record_count,
        query.start_index.unwrap_or(0),
        &source.id.simple().to_string(),
    ))
}

fn soundtrack_match_terms(metadata: Option<&serde_json::Value>) -> BTreeSet<String> {
    let Some(metadata) = metadata else {
        return BTreeSet::new();
    };
    let mut values = BTreeMap::<String, String>::new();
    for key in [
        "Album",
        "AlbumName",
        "Albums",
        "Artists",
        "AlbumArtists",
        "Genres",
        "MusicGenres",
        "Tags",
    ] {
        if let Some(value) = json_field_case_insensitive(metadata, key) {
            collect_metadata_value(value, &mut values);
        }
    }
    values.into_keys().collect()
}

fn is_theme_item_for_source(source: &MediaItem, item: &MediaItem, media_type: &str) -> bool {
    if item.id == source.id || item.media_type != media_type {
        return false;
    }
    let source_parent = media_item_path(source).parent();
    let item_parent = media_item_path(item).parent();
    if source_parent != item_parent {
        return false;
    }
    media_item_path(item)
        .file_stem()
        .and_then(|stem| stem.to_str())
        .is_some_and(|stem| stem.eq_ignore_ascii_case("theme"))
}

async fn authenticated_similar_items(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    Path(item_id): Path<String>,
    RawQuery(raw_query): RawQuery,
) -> Result<Json<serde_json::Value>, ApiError> {
    let query = parse_items_query(raw_query.as_deref());
    let auth_user =
        require_request_user(&state.db, &headers, auth_query.api_key.as_deref()).await?;
    let requested_user_id = query
        .user_id
        .as_deref()
        .map(resolve_user_id)
        .transpose()?
        .unwrap_or(auth_user.id);
    ensure_user_access(&auth_user, requested_user_id)?;
    if live_tv_program_by_id(&state.db, &item_id).await?.is_some() {
        return Ok(Json(query_result(Vec::new())));
    }

    match similar_items_for_media_source(&state, &query, requested_user_id, &item_id).await {
        Ok(response) => Ok(response),
        Err(error)
            if error.status == StatusCode::NOT_FOUND
                && virtual_tv_item_exists(&state.db, &item_id).await? =>
        {
            Ok(Json(query_result(Vec::new())))
        }
        Err(error) => Err(error),
    }
}

