async fn authenticated_similar_show_items(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    Path(item_id): Path<String>,
    RawQuery(raw_query): RawQuery,
) -> Result<Json<serde_json::Value>, ApiError> {
    let query = parse_items_query(raw_query.as_deref());
    let auth_user =
        require_request_user(&state.db, &headers, auth_query.api_key.as_deref()).await?;
    let requested_user_id = query
        .user_id
        .as_deref()
        .map(resolve_user_id)
        .transpose()?
        .unwrap_or(auth_user.id);
    ensure_user_access(&auth_user, requested_user_id)?;

    match similar_items_for_media_source(&state, &query, requested_user_id, &item_id).await {
        Ok(response) => return Ok(response),
        Err(error) if error.status == StatusCode::NOT_FOUND => {}
        Err(error) => return Err(error),
    }

    let mut items_query = query.clone();
    if items_query.include_item_types.is_empty() {
        items_query.include_item_types.push("Episode".to_string());
    }
    items_query.ids = None;
    items_query.search_term = None;
    items_query.name_starts_with = None;
    items_query.name_starts_with_or_greater = None;
    items_query.name_less_than = None;
    items_query.start_index = None;
    items_query.limit = None;
    items_query.sort_by = None;
    items_query.sort_order = None;

    let (
        TvEpisodeCatalogSnapshot {
            items,
            metadata_by_item,
        },
        resolved_series_id,
    ) = tv_episode_catalog_snapshot_scoped_to_series(&state.db, &item_id).await?;
    let candidate_episodes =
        filtered_media_items(items, &items_query, Some(requested_user_id), &state.db).await?;
    let mut episodes = candidate_episodes
        .into_iter()
        .filter(|item| {
            tv_episode_matches_series(item, metadata_by_item.get(&item.id), &resolved_series_id)
        })
        .collect::<Vec<_>>();
    if episodes.is_empty() {
        return Err(ApiError::not_found("Similar source not found"));
    }
    episodes.sort_by(compare_tv_episodes);
    paged_similar_items_response(&state, &query, requested_user_id, episodes).await
}

async fn authenticated_similar_trailer_items(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    Path(item_id): Path<String>,
    RawQuery(raw_query): RawQuery,
) -> Result<Json<serde_json::Value>, ApiError> {
    let query = parse_items_query(raw_query.as_deref());
    let auth_user =
        require_request_user(&state.db, &headers, auth_query.api_key.as_deref()).await?;
    let requested_user_id = query
        .user_id
        .as_deref()
        .map(resolve_user_id)
        .transpose()?
        .unwrap_or(auth_user.id);
    ensure_user_access(&auth_user, requested_user_id)?;

    match similar_items_for_media_source(&state, &query, requested_user_id, &item_id).await {
        Ok(response) => return Ok(response),
        Err(error) if error.status == StatusCode::NOT_FOUND => {}
        Err(error) => return Err(error),
    }

    let mut scope_query = query.clone();
    scope_query.ids = None;
    scope_query.search_term = None;
    scope_query.name_starts_with = None;
    scope_query.name_starts_with_or_greater = None;
    scope_query.name_less_than = None;
    scope_query.is_folder = None;
    scope_query.filters = metadata_scope_filters(&query.filters);
    scope_query.start_index = None;
    scope_query.limit = None;
    scope_query.sort_by = None;
    scope_query.sort_order = None;
    // This path resolves one exact trailer id rather than serving a page, so the paging cap the
    // listing uses would make it wrong by construction: every trailer whose parent sorts past the
    // cap answered "Similar source not found". The predicate already restricts the read to items
    // that carry a trailer array, which is a small slice of a catalogue.
    let scoped_items = filtered_media_items(
        state
            .db
            .media_items_with_remote_trailers(usize::MAX)
            .await?,
        &scope_query,
        Some(requested_user_id),
        &state.db,
    )
    .await?;
    let item_by_id = scoped_items
        .iter()
        .map(|item| (item.id, item))
        .collect::<HashMap<_, _>>();
    let item_ids = item_by_id.keys().copied().collect::<HashSet<_>>();
    let server_id = state.db.server_state().await?.server_id.to_string();
    let mut trailers = Vec::new();
    for metadata in state.db.media_item_metadata_by_item_ids(&item_ids).await? {
        let Some(item) = item_by_id.get(&metadata.item_id) else {
            continue;
        };
        trailers.extend(metadata_remote_trailers(
            &metadata.payload,
            item,
            &server_id,
        ));
    }
    let parent_id = trailers
        .iter()
        .find(|trailer| {
            trailer["Id"]
                .as_str()
                .is_some_and(|id| id.eq_ignore_ascii_case(&item_id))
        })
        .and_then(|trailer| trailer["ParentId"].as_str())
        .map(str::to_string)
        .ok_or_else(|| ApiError::not_found("Similar source not found"))?;
    trailers.retain(|trailer| {
        trailer["ParentId"]
            .as_str()
            .is_some_and(|candidate_parent_id| candidate_parent_id == parent_id)
            && trailer["Id"]
                .as_str()
                .is_some_and(|candidate_id| !candidate_id.eq_ignore_ascii_case(&item_id))
            && remote_trailer_matches_query(trailer, &query)
    });
    trailers.sort_by(|left, right| {
        left["SortName"]
            .as_str()
            .unwrap_or_default()
            .to_ascii_lowercase()
            .cmp(
                &right["SortName"]
                    .as_str()
                    .unwrap_or_default()
                    .to_ascii_lowercase(),
            )
    });
    if metadata_sort_descending("Trailer", &query) {
        trailers.reverse();
    }
    let total_record_count = trailers.len();
    let start_index = query.start_index.unwrap_or(0);
    let limit = query.limit.unwrap_or(20).min(100);
    Ok(Json(query_result_with_total(
        trailers.into_iter().skip(start_index).take(limit).collect(),
        total_record_count,
        start_index,
    )))
}

async fn similar_items_from_metadata_entity(
    state: AppState,
    headers: HeaderMap,
    auth_query: AuthQuery,
    raw_query: Option<String>,
    item_id: String,
    entity_type: &'static str,
    metadata_keys: &'static [&'static str],
) -> Result<Json<serde_json::Value>, ApiError> {
    let query = parse_items_query(raw_query.as_deref());
    let auth_user =
        require_request_user(&state.db, &headers, auth_query.api_key.as_deref()).await?;
    let requested_user_id = query
        .user_id
        .as_deref()
        .map(resolve_user_id)
        .transpose()?
        .unwrap_or(auth_user.id);
    ensure_user_access(&auth_user, requested_user_id)?;

    match similar_items_for_media_source(&state, &query, requested_user_id, &item_id).await {
        Ok(response) => return Ok(response),
        Err(error) if error.status == StatusCode::NOT_FOUND => {}
        Err(error) => return Err(error),
    }

    let mut items_query = query.clone();
    if items_query.include_item_types.is_empty() {
        items_query.include_item_types.push("Audio".to_string());
    }
    items_query.ids = None;
    items_query.search_term = None;
    items_query.name_starts_with = None;
    items_query.name_starts_with_or_greater = None;
    items_query.name_less_than = None;
    items_query.start_index = None;
    items_query.limit = None;
    items_query.sort_by = Some("SortName".to_string());
    items_query.sort_order = None;

    let entries = MediaCatalogStore::media_items_with_metadata_by_effective_types(
        &state.db,
        &["Audio".to_string()],
    )
    .await?;
    let mut candidate_items = Vec::with_capacity(entries.len());
    let mut metadata_by_item = HashMap::with_capacity(entries.len());
    for entry in entries {
        metadata_by_item.insert(entry.item.id, entry.metadata);
        candidate_items.push(entry.item);
    }
    let candidates = filtered_media_items(
        candidate_items,
        &items_query,
        Some(requested_user_id),
        &state.db,
    )
    .await?;
    let entity_name =
        metadata_values_for_keys_from_payloads(metadata_keys, &candidates, &metadata_by_item)
            .into_iter()
            .find(|name| stable_entity_id(entity_type, name).eq_ignore_ascii_case(&item_id))
            .ok_or_else(|| ApiError::not_found("Similar source not found"))?;
    let items = metadata_entity_audio_items_from_payloads(
        candidates,
        &metadata_by_item,
        metadata_keys,
        &entity_name,
    );
    paged_similar_items_response(&state, &query, requested_user_id, items).await
}

async fn similar_items_for_media_source(
    state: &AppState,
    query: &ItemsQuery,
    requested_user_id: Uuid,
    item_id: &str,
) -> Result<Json<serde_json::Value>, ApiError> {
    let source = media_item_by_id(&state.db, item_id).await?;
    let server_id = state.db.server_state().await?.server_id.to_string();
    let source_type = media_item_type(&source).to_string();
    let source_metadata = metadata_payload_for_item(&state.db, source.id).await?;
    let source_terms = similar_item_terms(Some(&source_metadata));
    if source_terms.is_empty() {
        return Ok(Json(query_result_with_total(Vec::new(), 0, 0)));
    }
    let requested_start_index = query.start_index.unwrap_or(0);
    let requested_limit = query.limit.unwrap_or(20).min(100);
    let mut items_query = query.clone();
    items_query.parent_id = None;
    items_query.include_item_types = vec![source_type.clone()];
    items_query.start_index = Some(0);
    items_query.limit = Some(500);
    items_query.sort_by = Some("SortName".to_string());
    items_query.sort_order = Some("Ascending".to_string());
    let genres = metadata_values_from_json(&source_metadata, &["Genres", "SeriesGenres"]);
    let studios = metadata_values_from_json(&source_metadata, &["Studios", "SeriesStudios"]);
    let tags = metadata_values_from_json(&source_metadata, &["Tags"]);
    items_query.genre_ids = genres;
    items_query.studio_ids = if items_query.genre_ids.is_empty() {
        studios
    } else {
        Vec::new()
    };
    items_query.tags = if items_query.genre_ids.is_empty() && items_query.studio_ids.is_empty() {
        tags
    } else {
        Vec::new()
    };
    // The bounded catalogue page cannot express every shape: a persisted Series source is one, and
    // answering those with an empty page removed Similar for every series while leaving the
    // caller's fallback unreachable, because an empty page is still `Ok`. Score the type-scoped
    // candidate read instead -- Series rows are a small fraction of the episode catalogue.
    let candidates = match media_catalog_query_for_items(&items_query, Some(requested_user_id))? {
        Some(mut db_query) => {
            db_query.virtual_folder_ids = vec![source.virtual_folder_id];
            db_query.include_total_record_count = false;
            MediaCatalogStore::media_item_catalog_page(&state.db, &db_query)
                .await?
                .items
        }
        None => {
            MediaCatalogStore::media_items_with_metadata_by_effective_types(
                &state.db,
                std::slice::from_ref(&source_type),
            )
            .await?
        }
    };
    let mut scored = candidates
        .into_iter()
        .filter_map(|entry| {
            let item = entry.item;
            if item.id == source.id {
                return None;
            }
            if !media_item_type(&item).eq_ignore_ascii_case(&source_type) {
                return None;
            }
            let terms = similar_item_terms(Some(&entry.metadata));
            let shared_terms = terms.intersection(&source_terms).count();
            if shared_terms == 0 {
                return None;
            }
            Some((shared_terms, item))
        })
        .collect::<Vec<_>>();

    scored.sort_by(|(left_score, left_item), (right_score, right_item)| {
        right_score
            .cmp(left_score)
            .then_with(|| compare_media_items(left_item, right_item, &[SortField::SortName]))
    });

    let total_record_count = scored.len();
    let items = scored
        .into_iter()
        .skip(requested_start_index)
        .take(requested_limit)
        .map(|(_, item)| item)
        .collect::<Vec<_>>();
    Ok(Json(query_result_with_total(
        items_to_json(&state.db, items, &server_id, Some(requested_user_id), false).await?,
        total_record_count,
        requested_start_index,
    )))
}

async fn paged_similar_items_response(
    state: &AppState,
    query: &ItemsQuery,
    requested_user_id: Uuid,
    items: Vec<MediaItem>,
) -> Result<Json<serde_json::Value>, ApiError> {
    let server_id = state.db.server_state().await?.server_id.to_string();
    let total_record_count = items.len();
    let start_index = query.start_index.unwrap_or(0);
    let limit = query.limit.unwrap_or(20).min(100);
    Ok(Json(query_result_with_total(
        items_to_json(
            &state.db,
            items.into_iter().skip(start_index).take(limit).collect(),
            &server_id,
            Some(requested_user_id),
            false,
        )
        .await?,
        total_record_count,
        start_index,
    )))
}

fn similar_item_terms(metadata: Option<&serde_json::Value>) -> BTreeSet<String> {
    let mut terms = BTreeMap::<String, String>::new();
    if let Some(metadata) = metadata {
        for key in [
            "Genres",
            "MusicGenres",
            "Tags",
            "Studios",
            "Artists",
            "AlbumArtists",
            "OfficialRating",
            "ProductionYear",
            "Series",
            "SeriesName",
        ] {
            if let Some(value) = metadata.get(key) {
                collect_metadata_value(value, &mut terms);
            }
        }
    }
    terms.into_keys().collect()
}

async fn item_filters(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    RawQuery(raw_query): RawQuery,
) -> Result<Json<serde_json::Value>, ApiError> {
    let query = parse_items_query(raw_query.as_deref());
    let auth_user =
        require_request_user(&state.db, &headers, auth_query.api_key.as_deref()).await?;
    let requested_user_id = query.user_id.as_deref().map(resolve_user_id).transpose()?;
    if let Some(requested_user_id) = requested_user_id {
        ensure_user_access(&auth_user, requested_user_id)?;
    }
    if query_targets_live_tv(&state.db, &query).await? {
        return Ok(Json(live_tv_filter_response(&state.db).await?));
    }
    let mut filter_query = query.clone();
    normalize_series_filter_catalog_query(&mut filter_query);
    if let Some(values) = media_catalog_filter_values_result(
        &state.db,
        &filter_query,
        requested_user_id,
        MediaItemQueryFilterSelection::ITEMS_FILTERS,
    )
    .await?
    {
        return Ok(Json(item_filter_response(values)));
    }
    let items = filtered_items_for_query(
        &state,
        &headers,
        auth_query.api_key.as_deref(),
        &filter_query,
    )
    .await?;
    let media_types = items
        .iter()
        .map(|item| item.media_type.clone())
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let containers = items
        .iter()
        .filter_map(media_item_container)
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let video_types = items
        .iter()
        .filter(|item| item.media_type.eq_ignore_ascii_case("Video"))
        .map(|_| "VideoFile".to_string())
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let metadata_values = item_filter_metadata_values(&state.db, &items).await?;

    Ok(Json(serde_json::json!({
        "Genres": metadata_values.genres.into_values().collect::<Vec<_>>(),
        "Tags": metadata_values.tags.into_values().collect::<Vec<_>>(),
        "OfficialRatings": metadata_values.official_ratings.into_values().collect::<Vec<_>>(),
        "Years": item_filter_years(metadata_values.years.into_values()),
        "Containers": containers,
        "MediaTypes": media_types,
        "VideoTypes": video_types,
        "SeriesStatuses": metadata_values.series_statuses.into_values().collect::<Vec<_>>(),
        "Staff": metadata_values.staff.into_values().collect::<Vec<_>>(),
        "Artists": metadata_values.artists.into_values().collect::<Vec<_>>(),
        "Albums": metadata_values.albums.into_values().collect::<Vec<_>>(),
        "Studios": metadata_values.studios.into_values().collect::<Vec<_>>(),
        "Trailers": metadata_values.trailers.into_values().collect::<Vec<_>>(),
        "Features": metadata_values.features.into_values().collect::<Vec<_>>()
    })))
}

async fn query_filters(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(auth_query): Query<AuthQuery>,
    RawQuery(raw_query): RawQuery,
) -> Result<Json<serde_json::Value>, ApiError> {
    let query = parse_items_query(raw_query.as_deref());
    let auth_user =
        require_request_user(&state.db, &headers, auth_query.api_key.as_deref()).await?;
    let requested_user_id = query.user_id.as_deref().map(resolve_user_id).transpose()?;
    if let Some(requested_user_id) = requested_user_id {
        ensure_user_access(&auth_user, requested_user_id)?;
    }
    if query_targets_live_tv(&state.db, &query).await? {
        let values = live_tv_filter_metadata_items(&state.db).await?;
        return Ok(Json(serde_json::json!({
            "Genres": values,
            "Tags": [],
            "AudioLanguages": [],
            "SubtitleLanguages": []
        })));
    }
    let mut filter_query = query.clone();
    normalize_series_filter_catalog_query(&mut filter_query);
    if let Some(values) = media_catalog_filter_values_result(
        &state.db,
        &filter_query,
        requested_user_id,
        MediaItemQueryFilterSelection::FILTERS2,
    )
    .await?
    {
        return Ok(Json(query_filter_response(values)));
    }
    let items = filtered_items_for_query(
        &state,
        &headers,
        auth_query.api_key.as_deref(),
        &filter_query,
    )
    .await?;
    let metadata_values = item_filter_metadata_values(&state.db, &items).await?;
    Ok(Json(serde_json::json!({
        "Genres": query_filter_genres(metadata_values.genres.into_values()),
        "Tags": metadata_values.tags.into_values().collect::<Vec<_>>(),
        "AudioLanguages": query_filter_languages(metadata_values.audio_languages.into_values()),
        "SubtitleLanguages": query_filter_languages(metadata_values.subtitle_languages.into_values())
    })))
}

/// Series are synthesized from persisted episodes, so filter endpoints must query the episode
/// projection. Rewrite every Series token (including mixed Movie,Series requests), while keeping
/// the historical synthetic-series ID behavior for a Series-only query.
fn normalize_series_filter_catalog_query(query: &mut ItemsQuery) {
    let only_series = query_requests_only_item_type(query, "Series");
    for value in &mut query.include_item_types {
        *value = value
            .split(',')
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(|value| {
                if value.eq_ignore_ascii_case("Series") {
                    "Episode"
                } else {
                    value
                }
            })
            .collect::<Vec<_>>()
            .join(",");
    }
    if only_series {
        query.ids = None;
    }
}

fn item_filter_years(values: impl IntoIterator<Item = String>) -> Vec<i32> {
    values
        .into_iter()
        .filter_map(|value| value.trim().parse::<i32>().ok())
        .collect()
}

fn query_filter_genres(values: impl IntoIterator<Item = String>) -> Vec<serde_json::Value> {
    values
        .into_iter()
        .map(|name| {
            let id = stable_entity_id("Genre", &name);
            serde_json::json!({
                "Name": name,
                "Id": id,
            })
        })
        .collect()
}

fn query_filter_languages(values: impl IntoIterator<Item = String>) -> Vec<serde_json::Value> {
    values
        .into_iter()
        .map(|value| {
            let name = language_display_name(Some(&value)).unwrap_or_else(|| value.clone());
            serde_json::json!({
                "Name": name,
                "Value": value,
            })
        })
        .collect()
}

fn item_filter_response(values: MediaItemQueryFilterValues) -> serde_json::Value {
    let staff = values
        .staff_names
        .into_iter()
        .map(|name| {
            serde_json::json!({
                "Id": stable_entity_id("Person", &name),
                "Name": name,
            })
        })
        .collect::<Vec<_>>();
    let mut features = Vec::new();
    if values.has_subtitles {
        features.push("HasSubtitles");
    }
    if values.has_trailer {
        features.push("HasTrailer");
    }
    let trailers = values
        .has_trailer
        .then_some("Trailer")
        .into_iter()
        .collect::<Vec<_>>();
    serde_json::json!({
        "Genres": values.genres,
        "Tags": values.tags,
        "OfficialRatings": values.official_ratings,
        "Years": item_filter_years(values.years),
        "Containers": values.containers,
        "MediaTypes": values.media_types,
        "VideoTypes": values.video_types,
        "SeriesStatuses": values.series_statuses,
        "Staff": staff,
        "Artists": values.artists,
        "Albums": values.albums,
        "Studios": values.studios,
        "Trailers": trailers,
        "Features": features,
    })
}

fn query_filter_response(values: MediaItemQueryFilterValues) -> serde_json::Value {
    serde_json::json!({
        "Genres": query_filter_genres(values.genres),
        "Tags": values.tags,
        "AudioLanguages": query_filter_languages(values.audio_languages),
        "SubtitleLanguages": query_filter_languages(values.subtitle_languages),
    })
}

async fn media_catalog_filter_values_result(
    db: &Database,
    query: &ItemsQuery,
    user_id: Option<Uuid>,
    selection: MediaItemQueryFilterSelection,
) -> Result<Option<MediaItemQueryFilterValues>, ApiError> {
    let Some(db_query) = resolved_media_catalog_query_for_filter_values(db, query, user_id).await?
    else {
        return Ok(None);
    };
    Ok(Some(
        MediaCatalogStore::media_item_query_filter_values(db, &db_query, selection).await?,
    ))
}

async fn resolved_media_catalog_query_for_filter_values(
    db: &Database,
    query: &ItemsQuery,
    user_id: Option<Uuid>,
) -> Result<Option<MediaItemCatalogQuery>, ApiError> {
    if query.sort_by.is_some() || query.sort_order.is_some() {
        return Ok(None);
    }
    let mut supported_query = query.clone();
    supported_query.parent_id = None;
    supported_query.start_index = None;
    supported_query.limit = Some(1);
    supported_query.sort_by = None;
    supported_query.sort_order = None;
    let Some(mut db_query) = media_catalog_query_for_items(&supported_query, user_id)? else {
        return Ok(None);
    };
    db_query.start_index = 0;
    db_query.limit = 0;
    db_query.sort.clear();
    db_query.search_scope = MediaItemCatalogSearchScope::AllMetadataScalars;

    let Some(parent_id) = query.parent_id.as_deref() else {
        db_query.virtual_folder_ids = db
            .virtual_folders()
            .await?
            .into_iter()
            .map(|folder| folder.id)
            .collect();
        return Ok(Some(db_query));
    };
    if special_user_view_collection_type_for_parent(Some(parent_id)).is_some()
        || live_tv_tuner_view_by_id(db, parent_id).await?.is_some()
    {
        return Ok(None);
    }
    let Ok(parent_id) = parse_jellyfin_uuid(parent_id) else {
        return Ok(None);
    };
    let folders = db.virtual_folders().await?;
    let Some(parent) = folders.iter().find(|folder| folder.id == parent_id) else {
        return Ok(None);
    };
    db_query.virtual_folder_ids.push(parent.id);
    db_query.virtual_folder_ids.extend(
        child_virtual_folders(parent, &folders)
            .into_iter()
            .map(|folder| folder.id),
    );
    Ok(Some(db_query))
}

async fn query_targets_live_tv(db: &Database, query: &ItemsQuery) -> Result<bool, ApiError> {
    let targets_static_live_tv = query
        .parent_id
        .as_deref()
        .is_some_and(|parent_id| parent_id.eq_ignore_ascii_case("livetv"))
        || special_user_view_collection_type_for_parent(query.parent_id.as_deref())
            .is_some_and(|collection_type| collection_type.eq_ignore_ascii_case("livetv"))
        || query_requests_item_type(query, "Program")
        || query_requests_item_type(query, "TvChannel");
    if targets_static_live_tv {
        return Ok(true);
    }
    let Some(parent_id) = query.parent_id.as_deref() else {
        return Ok(false);
    };
    Ok(live_tv_tuner_view_by_id(db, parent_id).await?.is_some())
}

async fn live_tv_filter_response(db: &Database) -> Result<serde_json::Value, ApiError> {
    let values = live_tv_filter_metadata_values(db).await?;
    Ok(serde_json::json!({
        "Genres": values.genres.into_values().collect::<Vec<_>>(),
        "Tags": values.tags.into_values().collect::<Vec<_>>(),
        "OfficialRatings": [],
        "Years": [],
        "Containers": ["ts"],
        "MediaTypes": ["Video"],
        "VideoTypes": ["VideoFile"],
        "SeriesStatuses": [],
        "Staff": [],
        "Artists": [],
        "Albums": [],
        "Studios": [],
        "Trailers": [],
        "Features": []
    }))
}

async fn live_tv_filter_metadata_values(
    db: &Database,
) -> Result<ItemFilterMetadataValues, ApiError> {
    let persisted_categories = LiveTvService::new(db).categories().await?;
    if !persisted_categories.is_empty() {
        let mut values = ItemFilterMetadataValues::default();
        for category in persisted_categories {
            let key = category.name.to_ascii_lowercase();
            values
                .genres
                .entry(key.clone())
                .or_insert(category.name.clone());
            values.tags.entry(key).or_insert(category.name);
        }
        return Ok(values);
    }
    let config = db
        .named_configuration("livetv")
        .await?
        .unwrap_or_else(default_live_tv_configuration);
    let mut values = ItemFilterMetadataValues::default();
    let Some(tuner_hosts) = config
        .get("TunerHosts")
        .and_then(serde_json::Value::as_array)
    else {
        return Ok(values);
    };
    for tuner in tuner_hosts {
        if let Some(categories) = tuner
            .get("Categories")
            .and_then(serde_json::Value::as_array)
        {
            for category in categories {
                if let Some(name) = json_string_field(category, "Name") {
                    let key = name.to_ascii_lowercase();
                    values.genres.entry(key.clone()).or_insert(name.clone());
                    values.tags.entry(key).or_insert(name);
                }
            }
        }
        if let Some(channels) = tuner.get("Channels").and_then(serde_json::Value::as_array) {
            for channel in channels {
                collect_live_tv_filter_values(channel, "Genres", &mut values.genres);
                collect_live_tv_filter_values(channel, "Tags", &mut values.tags);
            }
        }
    }
    Ok(values)
}

async fn live_tv_filter_metadata_items(db: &Database) -> Result<Vec<serde_json::Value>, ApiError> {
    let persisted_categories = LiveTvService::new(db).categories().await?;
    if !persisted_categories.is_empty() {
        return Ok(persisted_categories
            .into_iter()
            .map(|category| {
                serde_json::json!({
                    "Name": category.name,
                    "Id": category.category_id,
                })
            })
            .collect());
    }

    let values = live_tv_filter_metadata_values(db).await?;
    Ok(values
        .genres
        .into_values()
        .map(|name| {
            serde_json::json!({
                "Name": name.clone(),
                "Id": stable_entity_id("LiveTvGenre", &name),
            })
        })
        .collect())
}

fn collect_live_tv_filter_values(
    value: &serde_json::Value,
    key: &str,
    values: &mut BTreeMap<String, String>,
) {
    let Some(field) = json_field_case_insensitive(value, key) else {
        return;
    };
    match field {
        serde_json::Value::Array(items) => {
            for item in items {
                collect_live_tv_filter_value(item, values);
            }
        }
        other => collect_live_tv_filter_value(other, values),
    }
}

fn collect_live_tv_filter_value(value: &serde_json::Value, values: &mut BTreeMap<String, String>) {
    let name = match value {
        serde_json::Value::String(value) => value.trim(),
        serde_json::Value::Object(object) => object
            .get("Name")
            .and_then(serde_json::Value::as_str)
            .map(str::trim)
            .unwrap_or_default(),
        _ => "",
    };
    if !name.is_empty() {
        values
            .entry(name.to_ascii_lowercase())
            .or_insert_with(|| name.to_string());
    }
}

#[derive(Default)]
struct ItemFilterMetadataValues {
    albums: BTreeMap<String, String>,
    audio_languages: BTreeMap<String, String>,
    artists: BTreeMap<String, String>,
    features: BTreeMap<String, String>,
    genres: BTreeMap<String, String>,
    official_ratings: BTreeMap<String, String>,
    series_statuses: BTreeMap<String, String>,
    staff: BTreeMap<String, serde_json::Value>,
    studios: BTreeMap<String, String>,
    subtitle_languages: BTreeMap<String, String>,
    tags: BTreeMap<String, String>,
    trailers: BTreeMap<String, String>,
    years: BTreeMap<String, String>,
}

async fn item_filter_metadata_values(
    db: &Database,
    items: &[MediaItem],
) -> Result<ItemFilterMetadataValues, ApiError> {
    if items.is_empty() {
        return Ok(ItemFilterMetadataValues::default());
    }
    let item_ids = items.iter().map(|item| item.id).collect::<HashSet<_>>();
    let mut values = ItemFilterMetadataValues::default();
    for item in items {
        collect_media_item_stream_languages(item, "Audio", &mut values.audio_languages);
        collect_media_item_stream_languages(item, "Subtitle", &mut values.subtitle_languages);
        if media_item_has_stream_type(item, "Subtitle") {
            values
                .features
                .entry("hassubtitles".to_string())
                .or_insert_with(|| "HasSubtitles".to_string());
        }
    }
    for metadata in db.media_item_metadata_by_item_ids(&item_ids).await? {
        collect_item_count_metadata_value(&metadata, "Album", &mut values.albums);
        collect_item_count_metadata_value(&metadata, "AlbumName", &mut values.albums);
        collect_item_count_metadata_value(&metadata, "Artists", &mut values.artists);
        collect_item_count_metadata_value(&metadata, "AlbumArtists", &mut values.artists);
        collect_item_count_metadata_value(&metadata, "Genres", &mut values.genres);
        collect_item_count_metadata_value(
            &metadata,
            "OfficialRating",
            &mut values.official_ratings,
        );
        collect_item_count_metadata_value(
            &metadata,
            "OfficialRatings",
            &mut values.official_ratings,
        );
        collect_item_count_metadata_value(&metadata, "Studios", &mut values.studios);
        collect_item_count_metadata_value(&metadata, "SeriesStatus", &mut values.series_statuses);
        collect_item_filter_staff_value(&metadata, "People", &mut values.staff);
        collect_item_filter_staff_value(&metadata, "SeriesPeople", &mut values.staff);
        if metadata_has_remote_trailer(&metadata.payload) {
            values
                .features
                .entry("hastrailer".to_string())
                .or_insert_with(|| "HasTrailer".to_string());
            values
                .trailers
                .entry("trailer".to_string())
                .or_insert_with(|| "Trailer".to_string());
        }
        collect_item_count_metadata_value(&metadata, "Tags", &mut values.tags);
        collect_item_count_metadata_value(&metadata, "ProductionYear", &mut values.years);
        collect_item_count_metadata_value(&metadata, "Years", &mut values.years);
    }
    Ok(values)
}

async fn filtered_items_for_query(
    state: &AppState,
    headers: &HeaderMap,
    api_key: Option<&str>,
    query: &ItemsQuery,
) -> Result<Vec<MediaItem>, ApiError> {
    filtered_items_for_query_from_source(state, headers, api_key, query, None).await
}

/// Same authorization and filtering as [`filtered_items_for_query`], but lets a caller supply an
/// already-narrowed candidate set. Plugin-catalog visibility is still enforced by
/// [`filtered_media_items`] over whatever source it receives, so overriding the source cannot
/// widen what a user is allowed to see.
async fn filtered_items_for_query_from_source(
    state: &AppState,
    headers: &HeaderMap,
    api_key: Option<&str>,
    query: &ItemsQuery,
    source_items: Option<Vec<MediaItem>>,
) -> Result<Vec<MediaItem>, ApiError> {
    let (auth_user, token) = require_user(&state.db, headers, api_key).await?;
    let requested_user_id = query.user_id.as_deref().map(resolve_user_id).transpose()?;
    if let Some(requested_user_id) = requested_user_id {
        ensure_user_access(&auth_user, requested_user_id)?;
    }
    let mut scoped_query = query.clone();
    scope_items_query_for_plugin_catalogs(
        &state.db,
        &mut scoped_query,
        &auth_user,
        &token,
        requested_user_id,
    )
    .await?;
    let source_items = match source_items {
        Some(source_items) => source_items,
        None => media_items_source_for_query(&state.db, &scoped_query).await?,
    };
    filtered_media_items(source_items, &scoped_query, requested_user_id, &state.db).await
}

async fn media_items_source_for_query(
    db: &Database,
    query: &ItemsQuery,
) -> Result<Vec<MediaItem>, ApiError> {
    if let Some(parent_id) = query.parent_id.as_deref() {
        if live_tv_tuner_view_by_id(db, parent_id).await?.is_some() {
            return Ok(Vec::new());
        }
        if let Some(collection_type) = special_user_view_collection_type_for_parent(Some(parent_id))
        {
            return Ok(db.media_items_by_collection_type(collection_type).await?);
        }
        if let Ok(parent_id) = parse_jellyfin_uuid(parent_id) {
            let folders = db.virtual_folders().await?;
            let mut folder_ids = Vec::new();
            folder_ids.push(parent_id);
            if let Some(parent) = folders.iter().find(|folder| folder.id == parent_id) {
                for child in child_virtual_folders(parent, &folders) {
                    folder_ids.push(child.id);
                }
            }
            return Ok(db.media_items_for_virtual_folders(&folder_ids).await?);
        }
    }
    Ok(db.media_items().await?)
}

fn query_result(items: Vec<serde_json::Value>) -> serde_json::Value {
    let total_record_count = items.len();
    query_result_with_total(items, total_record_count, 0)
}

fn query_result_with_total(
    items: Vec<serde_json::Value>,
    total_record_count: usize,
    start_index: usize,
) -> serde_json::Value {
    serde_json::json!({
        "TotalRecordCount": total_record_count,
        "StartIndex": start_index,
        "Items": items,
    })
}

async fn filtered_media_items(
    items: Vec<MediaItem>,
    query: &ItemsQuery,
    user_id: Option<Uuid>,
    db: &Database,
) -> Result<Vec<MediaItem>, ApiError> {
    let parent_id = query
        .parent_id
        .as_deref()
        .map(parse_jellyfin_uuid)
        .transpose()?;
    let ids = query.ids.as_deref().map(parse_uuid_list).transpose()?;
    let include_types = csv_values_lowercase(&query.include_item_types);
    let exclude_types = csv_values_lowercase(&query.exclude_item_types);
    let media_types = csv_values_lowercase(&query.media_types);
    let containers = csv_values_lowercase(&query.containers);
    let video_types = csv_values_lowercase(&query.video_types);
    let audio_languages = csv_values_lowercase(&query.audio_languages);
    let subtitle_languages = csv_values_lowercase(&query.subtitle_languages);
    let person_ids = normalized_catalog_filter_values(&query.person_ids, "PersonIds")?;
    let person_ids = (!person_ids.is_empty()).then_some(person_ids);
    let genre_ids = normalized_genre_ids_for_catalog(query)?;
    let genre_ids = (!genre_ids.is_empty()).then_some(genre_ids);
    let studio_ids = normalized_catalog_filter_values(&query.studio_ids, "StudioIds")?;
    let studio_ids = (!studio_ids.is_empty()).then_some(studio_ids);
    let official_ratings = csv_values_lowercase(&query.official_ratings);
    let tags = normalized_catalog_filter_values(&query.tags, "Tags")?;
    let tags = (!tags.is_empty()).then_some(tags);
    let series_status = csv_values_lowercase(&query.series_status);
    let years = csv_values_lowercase(&query.years);
    let filters = csv_values_lowercase(&query.filters);
    let location_types = csv_values_lowercase(&query.location_types);
    let exclude_location_types = csv_values_lowercase(&query.exclude_location_types);
    let search_term = query
        .search_term
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_ascii_lowercase);
    let metadata_by_item = if person_ids.is_some()
        || search_term.is_some()
        || genre_ids.is_some()
        || studio_ids.is_some()
        || official_ratings.is_some()
        || tags.is_some()
        || series_status.is_some()
        || query.has_trailer.is_some()
        || query.has_overview.is_some()
        || query.has_imdb_id.is_some()
        || query.has_tmdb_id.is_some()
        || query.has_tvdb_id.is_some()
        || query.has_official_rating.is_some()
        || query.is_locked.is_some()
        || filters
            .as_deref()
            .is_some_and(|filters| filters.iter().any(|filter| filter == "hastrailer"))
        || years.is_some()
        || query.min_community_rating.is_some()
        || query.max_community_rating.is_some()
        || query.min_critic_rating.is_some()
        || query.max_critic_rating.is_some()
        || query.min_premiere_date.is_some()
        || query.max_premiere_date.is_some()
    {
        Some(media_metadata_by_item_id(db, items.iter().map(|item| item.id).collect()).await?)
    } else {
        None
    };
    let name_starts_with = normalized_prefix(query.name_starts_with.as_deref());
    let name_starts_with_or_greater =
        normalized_prefix(query.name_starts_with_or_greater.as_deref());
    let name_less_than = normalized_prefix(query.name_less_than.as_deref());
    let is_folder_filter = query
        .is_folder
        .or_else(|| filters.as_deref().and_then(folder_filter_value));
    let is_played_filter = query
        .is_played
        .or_else(|| filters.as_deref().and_then(played_filter_value));
    let has_subtitles_filter = query.has_subtitles.or_else(|| {
        filters
            .as_deref()
            .is_some_and(|filters| filters.iter().any(|filter| filter == "hassubtitles"))
            .then_some(true)
    });
    let has_trailer_filter = query.has_trailer.or_else(|| {
        filters
            .as_deref()
            .is_some_and(|filters| filters.iter().any(|filter| filter == "hastrailer"))
            .then_some(true)
    });
    let min_premiere_date = query
        .min_premiere_date
        .as_deref()
        .and_then(parse_item_query_date);
    let max_premiere_date = query
        .max_premiere_date
        .as_deref()
        .and_then(parse_item_query_date);
    let min_date_created = query
        .min_date_created
        .as_deref()
        .and_then(parse_item_query_date);
    let max_date_created = query
        .max_date_created
        .as_deref()
        .and_then(parse_item_query_date);
    let min_date_last_saved = query
        .min_date_last_saved
        .as_deref()
        .and_then(parse_item_query_date);
    let max_date_last_saved = query
        .max_date_last_saved
        .as_deref()
        .and_then(parse_item_query_date);
    let parent_folder_ids = if let Some(parent_id) = parent_id {
        let folders = db.virtual_folders().await?;
        let mut ids = HashSet::from([parent_id]);
        if let Some(parent) = folders.iter().find(|folder| folder.id == parent_id) {
            for child in child_virtual_folders(parent, &folders) {
                ids.insert(child.id);
            }
        }
        Some(ids)
    } else {
        None
    };
    let plugin_visibility_metadata = if query.allowed_plugin_tuner_ids.is_some() {
        Some(
            media_metadata_by_item_id(
                db,
                items
                    .iter()
                    .filter(|item| is_plugin_vod_virtual_item(item))
                    .map(|item| item.id)
                    .collect(),
            )
            .await?,
        )
    } else {
        None
    };

    let mut items = items
        .into_iter()
        .filter(|item| {
            query
                .allowed_plugin_tuner_ids
                .as_ref()
                .is_none_or(|allowed| {
                    if !is_plugin_vod_virtual_item(item) {
                        return true;
                    }
                    plugin_visibility_metadata
                        .as_ref()
                        .and_then(|metadata| metadata.get(&item.id))
                        .and_then(|metadata| json_string_field(metadata, "TunerId"))
                        .is_some_and(|tuner_id| {
                            allowed
                                .iter()
                                .any(|allowed| allowed.eq_ignore_ascii_case(&tuner_id))
                        })
                })
        })
        .filter(|item| ids.as_ref().is_none_or(|ids| ids.contains(&item.id)))
        .filter(|item| {
            parent_folder_ids
                .as_ref()
                .is_some_and(|parent_ids| parent_ids.contains(&item.virtual_folder_id))
                || (parent_folder_ids.is_none()
                    && parent_id.is_none_or(|parent_id| item.virtual_folder_id == parent_id))
        })
        .filter(|item| {
            include_types.as_ref().is_none_or(|types| {
                let item_type = media_item_type(item).to_ascii_lowercase();
                types.iter().any(|allowed| allowed == &item_type)
            })
        })
        .filter(|item| {
            exclude_types.as_ref().is_none_or(|types| {
                let item_type = media_item_type(item).to_ascii_lowercase();
                !types.iter().any(|excluded| excluded == &item_type)
            })
        })
        .filter(|item| {
            media_types.as_ref().is_none_or(|types| {
                let media_type = item.media_type.to_ascii_lowercase();
                types.iter().any(|allowed| allowed == &media_type)
            })
        })
        .filter(|item| {
            location_types.as_ref().is_none_or(|types| {
                let location_type = media_item_location_type(item).to_ascii_lowercase();
                types.iter().any(|allowed| allowed == &location_type)
            })
        })
        .filter(|item| {
            exclude_location_types.as_ref().is_none_or(|types| {
                let location_type = media_item_location_type(item).to_ascii_lowercase();
                !types.iter().any(|excluded| excluded == &location_type)
            })
        })
        .filter(|item| {
            containers.as_ref().is_none_or(|containers| {
                media_item_container(item)
                    .map(|container| container.to_ascii_lowercase())
                    .is_some_and(|container| containers.iter().any(|allowed| allowed == &container))
            })
        })
        .filter(|item| {
            video_types.as_ref().is_none_or(|video_types| {
                let video_type = if item.media_type.eq_ignore_ascii_case("Video") {
                    "videofile"
                } else {
                    "unknown"
                };
                video_types.iter().any(|allowed| allowed == video_type)
            })
        })
        .filter(|item| {
            audio_languages
                .as_ref()
                .is_none_or(|languages| media_item_has_stream_language(item, "Audio", languages))
        })
        .filter(|item| {
            subtitle_languages
                .as_ref()
                .is_none_or(|languages| media_item_has_stream_language(item, "Subtitle", languages))
        })
        .filter(|item| {
            has_subtitles_filter
                .is_none_or(|expected| media_item_has_stream_type(item, "Subtitle") == expected)
        })
        .filter(|item| {
            has_trailer_filter.is_none_or(|expected| {
                metadata_by_item
                    .as_ref()
                    .and_then(|metadata| metadata.get(&item.id))
                    .is_some_and(metadata_has_remote_trailer)
                    == expected
            })
        })
        .filter(|item| {
            query.has_overview.is_none_or(|expected| {
                metadata_by_item
                    .as_ref()
                    .and_then(|metadata| metadata.get(&item.id))
                    .is_some_and(metadata_has_overview)
                    == expected
            })
        })
        .filter(|item| provider_filter_matches(item, metadata_by_item.as_ref(), query))
        .filter(|item| media_item_dimension_filters_match(item, query))
        .filter(|_| query.is_missing.is_none_or(|expected| !expected))
        .filter(|_| query.is_unaired.is_none_or(|expected| !expected))
        .filter(|item| {
            metadata_flag_filters_match(
                item,
                metadata_by_item.as_ref(),
                query.has_official_rating,
                query.is_locked,
            )
        })
        .filter(|item| {
            min_date_created.is_none_or(|min| item.created_at >= min)
                && max_date_created.is_none_or(|max| item.created_at <= max)
                && min_date_last_saved.is_none_or(|min| item.updated_at >= min)
                && max_date_last_saved.is_none_or(|max| item.updated_at <= max)
        })
        .filter(|_| is_folder_filter.is_none_or(|is_folder| !is_folder))
        .filter(|item| {
            search_term.as_ref().is_none_or(|term| {
                item.name.to_ascii_lowercase().contains(term)
                    || metadata_by_item
                        .as_ref()
                        .and_then(|metadata| metadata.get(&item.id))
                        .is_some_and(|metadata| metadata_value_matches_search(metadata, term))
            })
        })
        .filter(|item| {
            person_ids.as_ref().is_none_or(|person_ids| {
                metadata_by_item
                    .as_ref()
                    .and_then(|metadata| metadata.get(&item.id))
                    .is_some_and(|metadata| {
                        metadata_matches_entity_ids(
                            metadata,
                            "Person",
                            &["People", "Cast", "SeriesPeople"],
                            person_ids,
                        )
                    })
            })
        })
        .filter(|item| {
            genre_ids.as_ref().is_none_or(|genre_ids| {
                metadata_by_item
                    .as_ref()
                    .and_then(|metadata| metadata.get(&item.id))
                    .is_some_and(|metadata| {
                        metadata_matches_entity_ids(
                            metadata,
                            "Genre",
                            &["Genres", "SeriesGenres"],
                            genre_ids,
                        )
                    })
            })
        })
        .filter(|item| {
            studio_ids.as_ref().is_none_or(|studio_ids| {
                metadata_by_item
                    .as_ref()
                    .and_then(|metadata| metadata.get(&item.id))
                    .is_some_and(|metadata| {
                        metadata_matches_entity_ids(
                            metadata,
                            "Studio",
                            &["Studios", "SeriesStudios"],
                            studio_ids,
                        )
                    })
            })
        })
        .filter(|item| {
            official_ratings.as_ref().is_none_or(|official_ratings| {
                metadata_by_item
                    .as_ref()
                    .and_then(|metadata| metadata.get(&item.id))
                    .is_some_and(|metadata| {
                        metadata_matches_values(
                            metadata,
                            &["OfficialRating", "OfficialRatings", "SeriesOfficialRating"],
                            official_ratings,
                        )
                    })
            })
        })
        .filter(|item| {
            tags.as_ref().is_none_or(|tags| {
                metadata_by_item
                    .as_ref()
                    .and_then(|metadata| metadata.get(&item.id))
                    .is_some_and(|metadata| metadata_matches_values(metadata, &["Tags"], tags))
            })
        })
        .filter(|item| {
            series_status.as_ref().is_none_or(|series_status| {
                metadata_by_item
                    .as_ref()
                    .and_then(|metadata| metadata.get(&item.id))
                    .is_some_and(|metadata| {
                        metadata_matches_values(
                            metadata,
                            &["SeriesStatus", "Status"],
                            series_status,
                        )
                    })
            })
        })
        .filter(|item| {
            years.as_ref().is_none_or(|years| {
                metadata_by_item
                    .as_ref()
                    .and_then(|metadata| metadata.get(&item.id))
                    .is_some_and(|metadata| {
                        metadata_matches_values(metadata, &["ProductionYear", "Years"], years)
                    })
            })
        })
        .filter(|item| {
            metadata_by_item
                .as_ref()
                .and_then(|metadata| metadata.get(&item.id))
                .is_none_or(|metadata| metadata_matches_range_filters(metadata, query))
        })
        .filter(|item| {
            if min_premiere_date.is_none() && max_premiere_date.is_none() {
                return true;
            }
            metadata_by_item
                .as_ref()
                .and_then(|metadata| metadata.get(&item.id))
                .and_then(metadata_item_filter_premiere_date)
                .is_some_and(|premiere_date| {
                    min_premiere_date.is_none_or(|min| premiere_date >= min)
                        && max_premiere_date.is_none_or(|max| premiere_date <= max)
                })
        })
        .filter(|item| {
            name_starts_with
                .as_ref()
                .is_none_or(|prefix| item.name.to_ascii_lowercase().starts_with(prefix))
        })
        .filter(|item| {
            name_starts_with_or_greater
                .as_ref()
                .is_none_or(|prefix| item.name.to_ascii_lowercase().as_str() >= prefix.as_str())
        })
        .filter(|item| {
            name_less_than
                .as_ref()
                .is_none_or(|prefix| item.name.to_ascii_lowercase().as_str() < prefix.as_str())
        })
        .collect::<Vec<_>>();

    // Resolve every playback-dependent legacy predicate from one indexed query. These fallbacks
    // can still materialize catalog rows for metadata semantics, but must never add one database
    // round trip per item (or repeat that N+1 for combined filters).
    let favorite_filter: Option<(bool, FavoriteFilterMode)> = match query.is_favorite {
        Some(value) => Some((value, FavoriteFilterMode::FavoriteOnly)),
        None => filters
            .as_deref()
            .and_then(favorite_filter_value)
            .map(|mode| (true, mode)),
    };
    let resumable_filter = filters.as_deref().is_some_and(resumable_filter_value);
    let playback_by_item =
        if is_played_filter.is_some() || favorite_filter.is_some() || resumable_filter {
            let Some(user_id) = user_id else {
                items.clear();
                return Ok(items);
            };
            let item_ids = items.iter().map(|item| item.id).collect::<Vec<_>>();
            MediaCatalogStore::playback_states_for_items(db, user_id, &item_ids)
                .await?
                .into_iter()
                .map(|state| (state.item_id, state))
                .collect::<HashMap<_, _>>()
        } else {
            HashMap::new()
        };

    if let Some(is_played) = is_played_filter {
        items.retain(|item| {
            playback_by_item
                .get(&item.id)
                .is_some_and(|state| state.played)
                == is_played
        });
    }

    // Resolve the favorite filter from the explicit IsFavorite query param OR a
    // Filters= token. The token distinguishes favorite-only from favorite-or-likes.
    if let Some((want, mode)) = favorite_filter {
        items.retain(|item| {
            let matches = playback_by_item
                .get(&item.id)
                .is_some_and(|state| match mode {
                    FavoriteFilterMode::FavoriteOnly => state.is_favorite,
                    FavoriteFilterMode::FavoriteOrLikes => {
                        state.is_favorite || state.rating.is_some_and(|rating| rating > 0.0)
                    }
                });
            matches == want
        });
    }

    // Filters=IsResumable: keep only items with a saved playback position > 0.
    if resumable_filter {
        items.retain(|item| {
            playback_by_item
                .get(&item.id)
                .is_some_and(|state| state.position_ticks > 0 && !state.played)
        });
    }

    if query_should_sort_episode_person_results_by_index(query, include_types.as_deref()) {
        let empty_metadata = HashMap::new();
        let metadata = metadata_by_item.as_ref().unwrap_or(&empty_metadata);
        items.sort_by(|left, right| {
            compare_tv_episodes_with_metadata(
                left,
                metadata.get(&left.id),
                right,
                metadata.get(&right.id),
            )
        });
    } else {
        let sort_fields = sort_fields(query.sort_by.as_deref());
        if query
            .sort_order
            .as_deref()
            .is_some_and(|order| order.eq_ignore_ascii_case("Descending"))
        {
            items.sort_by(|left, right| compare_media_items(right, left, &sort_fields));
        } else {
            items.sort_by(|left, right| compare_media_items(left, right, &sort_fields));
        }
    }

    Ok(items)
}

fn query_should_sort_episode_person_results_by_index(
    query: &ItemsQuery,
    include_types: Option<&[String]>,
) -> bool {
    let Some(types) = include_types else {
        return false;
    };
    !query.person_ids.is_empty()
        && !types.is_empty()
        && types.iter().all(|item_type| item_type == "episode")
}

fn metadata_value_matches_search(value: &serde_json::Value, term: &str) -> bool {
    match value {
        serde_json::Value::String(value) => value.to_ascii_lowercase().contains(term),
        serde_json::Value::Number(value) => value.to_string().contains(term),
        serde_json::Value::Array(values) => values
            .iter()
            .any(|value| metadata_value_matches_search(value, term)),
        serde_json::Value::Object(values) => values
            .values()
            .any(|value| metadata_value_matches_search(value, term)),
        serde_json::Value::Bool(_) | serde_json::Value::Null => false,
    }
}

fn metadata_has_overview(metadata: &serde_json::Value) -> bool {
    first_metadata_value_from_json(metadata, &["Overview", "SeriesOverview"])
        .is_some_and(|value| !value.trim().is_empty())
}

fn provider_filter_matches(
    item: &MediaItem,
    metadata_by_item: Option<&HashMap<Uuid, serde_json::Value>>,
    query: &ItemsQuery,
) -> bool {
    for (expected, provider_key) in [
        (query.has_imdb_id, "Imdb"),
        (query.has_tmdb_id, "Tmdb"),
        (query.has_tvdb_id, "Tvdb"),
    ] {
        let Some(expected) = expected else {
            continue;
        };
        let has_provider = metadata_by_item
            .and_then(|metadata| metadata.get(&item.id))
            .is_some_and(|metadata| metadata_has_provider_id(metadata, provider_key));
        if has_provider != expected {
            return false;
        }
    }
    true
}

fn metadata_flag_filters_match(
    item: &MediaItem,
    metadata_by_item: Option<&HashMap<Uuid, serde_json::Value>>,
    has_official_rating: Option<bool>,
    is_locked: Option<bool>,
) -> bool {
    let metadata = metadata_by_item.and_then(|metadata| metadata.get(&item.id));
    if let Some(expected) = has_official_rating {
        let actual = metadata.is_some_and(metadata_has_official_rating);
        if actual != expected {
            return false;
        }
    }
    if let Some(expected) = is_locked {
        let actual = metadata.is_some_and(metadata_is_locked);
        if actual != expected {
            return false;
        }
    }
    true
}

fn metadata_has_official_rating(metadata: &serde_json::Value) -> bool {
    first_metadata_value_from_json(
        metadata,
        &["OfficialRating", "OfficialRatings", "SeriesOfficialRating"],
    )
    .is_some_and(|value| !value.trim().is_empty())
}

fn metadata_is_locked(metadata: &serde_json::Value) -> bool {
    json_field_case_insensitive(metadata, "LockData")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false)
}

fn metadata_has_provider_id(metadata: &serde_json::Value, provider_key: &str) -> bool {
    ["ProviderIds", "SeriesProviderIds"].iter().any(|key| {
        json_field_case_insensitive(metadata, key)
            .and_then(|provider_ids| json_field_case_insensitive(provider_ids, provider_key))
            .and_then(serde_json::Value::as_str)
            .is_some_and(|value| !value.trim().is_empty())
    })
}

fn media_item_dimension_filters_match(item: &MediaItem, query: &ItemsQuery) -> bool {
    let width = item.width.map(i64::from);
    let height = item.height.map(i64::from);
    if let Some(is_hd) = query.is_hd {
        let item_is_hd = height.is_some_and(|height| height >= 720);
        if item_is_hd != is_hd {
            return false;
        }
    }
    if let Some(is_4k) = query.is_4k {
        let item_is_4k =
            width.is_some_and(|width| width >= 3840) || height.is_some_and(|height| height >= 2160);
        if item_is_4k != is_4k {
            return false;
        }
    }
    if query
        .min_width
        .is_some_and(|min_width| width.is_none_or(|width| width < min_width))
        || query
            .max_width
            .is_some_and(|max_width| width.is_none_or(|width| width > max_width))
        || query
            .min_height
            .is_some_and(|min_height| height.is_none_or(|height| height < min_height))
        || query
            .max_height
            .is_some_and(|max_height| height.is_none_or(|height| height > max_height))
    {
        return false;
    }
    true
}

fn metadata_matches_entity_ids(
    metadata: &serde_json::Value,
    item_type: &str,
    metadata_keys: &[&str],
    entity_ids: &[String],
) -> bool {
    if entity_ids.is_empty() {
        return true;
    }
    let mut names = BTreeMap::<String, String>::new();
    let mut ids = HashSet::<String>::new();
    let effective_keys: Vec<&str> = if item_type.eq_ignore_ascii_case("Person")
        && metadata_keys
            .iter()
            .any(|key| key.eq_ignore_ascii_case("SeriesPeople"))
        && (json_field_case_insensitive(metadata, "People").is_some_and(metadata_value_has_items)
            || json_field_case_insensitive(metadata, "Cast").is_some_and(metadata_value_has_items))
    {
        metadata_keys
            .iter()
            .copied()
            .filter(|key| !key.eq_ignore_ascii_case("SeriesPeople"))
            .collect()
    } else {
        metadata_keys.to_vec()
    };
    for key in effective_keys {
        if let Some(value) = json_field_case_insensitive(metadata, key) {
            collect_metadata_value(value, &mut names);
            collect_metadata_entity_ids(value, item_type, &mut ids);
        }
    }
    for name in names.into_values() {
        ids.insert(name.to_ascii_lowercase());
        ids.insert(stable_entity_id(item_type, &name).to_ascii_lowercase());
    }
    ids.into_iter()
        .any(|id| entity_ids.iter().any(|entity_id| entity_id == &id))
}

fn metadata_value_has_items(value: &serde_json::Value) -> bool {
    match value {
        serde_json::Value::Array(values) => !values.is_empty(),
        serde_json::Value::String(value) => !value.trim().is_empty(),
        serde_json::Value::Object(object) => !object.is_empty(),
        _ => false,
    }
}

fn collect_metadata_entity_ids(
    value: &serde_json::Value,
    item_type: &str,
    ids: &mut HashSet<String>,
) {
    match value {
        serde_json::Value::Array(values) => {
            for value in values {
                collect_metadata_entity_ids(value, item_type, ids);
            }
        }
        serde_json::Value::Object(object) => {
            if let Some(id) = object
                .get("Id")
                .and_then(serde_json::Value::as_str)
                .map(str::trim)
                .filter(|id| !id.is_empty())
            {
                ids.insert(id.to_ascii_lowercase());
            }
            if let Some(name) = object
                .get("Name")
                .and_then(serde_json::Value::as_str)
                .map(str::trim)
                .filter(|name| !name.is_empty())
            {
                ids.insert(stable_entity_id(item_type, name).to_ascii_lowercase());
            }
        }
        serde_json::Value::String(name) => {
            let name = name.trim();
            if !name.is_empty() {
                ids.insert(stable_entity_id(item_type, name).to_ascii_lowercase());
            }
        }
        _ => {}
    }
}

fn metadata_matches_values(
    metadata: &serde_json::Value,
    metadata_keys: &[&str],
    expected_values: &[String],
) -> bool {
    if expected_values.is_empty() {
        return true;
    }
    let mut values = BTreeMap::<String, String>::new();
    for key in metadata_keys {
        if let Some(value) = json_field_case_insensitive(metadata, key) {
            collect_metadata_value(value, &mut values);
        }
    }
    values
        .into_values()
        .map(|value| value.to_ascii_lowercase())
        .any(|value| expected_values.iter().any(|expected| expected == &value))
}

fn metadata_matches_range_filters(metadata: &serde_json::Value, query: &ItemsQuery) -> bool {
    let community_rating =
        first_metadata_number_from_json(metadata, &["CommunityRating", "Rating"]);
    let critic_rating = first_metadata_number_from_json(metadata, &["CriticRating"]);
    query
        .min_community_rating
        .is_none_or(|min| community_rating.is_some_and(|rating| rating >= min))
        && query
            .max_community_rating
            .is_none_or(|max| community_rating.is_some_and(|rating| rating <= max))
        && query
            .min_critic_rating
            .is_none_or(|min| critic_rating.is_some_and(|rating| rating >= min))
        && query
            .max_critic_rating
            .is_none_or(|max| critic_rating.is_some_and(|rating| rating <= max))
}

fn metadata_item_filter_premiere_date(metadata: &serde_json::Value) -> Option<OffsetDateTime> {
    first_metadata_value_from_json(metadata, &["PremiereDate", "AirDate", "DateCreated"])
        .as_deref()
        .and_then(parse_item_query_date)
}

fn parse_item_query_date(value: &str) -> Option<OffsetDateTime> {
    let value = value.trim();
    OffsetDateTime::parse(value, &Rfc3339).ok().or_else(|| {
        let date = time::Date::parse(
            value.split('T').next().unwrap_or(value),
            &time::macros::format_description!("[year]-[month]-[day]"),
        )
        .ok()?;
        Some(date.midnight().assume_utc())
    })
}

fn paged_media_items(items: Vec<MediaItem>, query: &ItemsQuery) -> Vec<MediaItem> {
    let start_index = query.start_index.unwrap_or(0);
    let limit = query.limit.unwrap_or(usize::MAX);
    items.into_iter().skip(start_index).take(limit).collect()
}

async fn items_to_json(
    db: &Database,
    items: Vec<MediaItem>,
    server_id: &str,
    user_id: Option<Uuid>,
    compact: bool,
) -> Result<Vec<serde_json::Value>, ApiError> {
    let mut values = Vec::with_capacity(items.len());
    let item_ids = items.iter().map(|item| item.id).collect::<Vec<_>>();
    let metadata_by_item =
        media_metadata_by_item_id(db, item_ids.iter().copied().collect()).await?;
    let playback_by_item = if let Some(user_id) = user_id {
        MediaCatalogStore::playback_states_for_items(db, user_id, &item_ids)
            .await?
            .into_iter()
            .map(|state| (state.item_id, state))
            .collect::<HashMap<_, _>>()
    } else {
        HashMap::new()
    };
    for item in items {
        let playback = playback_by_item.get(&item.id);
        values.push(if compact {
            compact_media_item_to_json(&item, server_id, playback)
        } else {
            media_item_to_json_with_playback_and_metadata(
                &item,
                server_id,
                playback,
                metadata_by_item.get(&item.id),
            )
        });
    }
    Ok(values)
}

fn should_use_compact_items_result(query: &ItemsQuery) -> bool {
    query.parent_id.is_none()
        && query.ids.is_none()
        && query.fields.is_none()
        && query.start_index.is_some()
        && query.limit.is_some()
        && !query.include_item_types.is_empty()
        && query
            .include_item_types
            .iter()
            .all(|item_type| item_type.eq_ignore_ascii_case("Movie"))
        && query.filters.is_empty()
        && query.search_term.is_none()
        && query.name_starts_with.is_none()
        && query.name_starts_with_or_greater.is_none()
        && query.name_less_than.is_none()
}

fn compact_media_item_to_json(
    item: &MediaItem,
    server_id: &str,
    playback: Option<&PlaybackState>,
) -> serde_json::Value {
    let item_id = item.id.simple().to_string();
    let image_tag = default_primary_image_tag(&item_id);
    let playback_position_ticks = playback.map_or(0, |state| state.position_ticks);
    let played = playback.is_some_and(|state| state.played);
    serde_json::json!({
        "Name": item.name,
        "ServerId": server_id,
        "Id": item_id,
        "ChannelId": null,
        "CollectionType": item.collection_type,
        "Type": media_item_type(item),
        "MediaType": item.media_type,
        "IsFolder": false,
        "LocationType": "FileSystem",
        "UserData": {
            "PlaybackPositionTicks": playback_position_ticks,
            "PlayCount": i32::from(played),
            "IsFavorite": playback.is_some_and(|state| state.is_favorite),
            "Played": played,
            "Key": item_id,
            "ItemId": item_id,
        },
        "ImageTags": { "Primary": image_tag },
        "ImageBlurHashes": {
            "Primary": {
                image_tag: default_primary_blur_hash()
            }
        },
        "BackdropImageTags": [],
    })
}

fn default_primary_blur_hash() -> &'static str {
    "LKO2?U%2Tw=w]~RBVZRi};RPxuwH"
}

async fn media_metadata_by_item_id(
    db: &Database,
    item_ids: HashSet<Uuid>,
) -> Result<HashMap<Uuid, serde_json::Value>, ApiError> {
    if item_ids.is_empty() {
        return Ok(HashMap::new());
    }
    Ok(db
        .media_item_metadata_by_item_ids(&item_ids)
        .await?
        .into_iter()
        .map(|metadata| (metadata.item_id, metadata.payload))
        .collect())
}

fn csv_values_lowercase(values: &[String]) -> Option<Vec<String>> {
    let values = values
        .iter()
        .flat_map(|value| value.split(','))
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_ascii_lowercase)
        .collect::<Vec<_>>();
    if values.is_empty() {
        None
    } else {
        Some(values)
    }
}

#[derive(Debug, Deserialize)]
#[serde(untagged)]
enum QueryStringValues {
    One(String),
    Many(Vec<String>),
}

fn deserialize_csv_values<'de, D>(deserializer: D) -> Result<Vec<String>, D::Error>
where
    D: Deserializer<'de>,
{
    let values = Option::<QueryStringValues>::deserialize(deserializer)?;
    // Split comma-separated values so both repeated params (a&a=b) and a single
    // CSV param (a=b,c) yield individual values — Jellyfin clients use both forms.
    let split = |value: String| -> Vec<String> {
        value
            .split(',')
            .map(str::trim)
            .filter(|part| !part.is_empty())
            .map(ToOwned::to_owned)
            .collect()
    };
    Ok(match values {
        Some(QueryStringValues::One(value)) => split(value),
        Some(QueryStringValues::Many(values)) => values.into_iter().flat_map(split).collect(),
        None => Vec::new(),
    })
}

fn normalized_prefix(value: Option<&str>) -> Option<String> {
    value
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_ascii_lowercase)
}

fn folder_filter_value(filters: &[String]) -> Option<bool> {
    if filters.iter().any(|filter| filter == "isfolder") {
        Some(true)
    } else if filters.iter().any(|filter| filter == "isnotfolder") {
        Some(false)
    } else {
        None
    }
}

fn played_filter_value(filters: &[String]) -> Option<bool> {
    if filters.iter().any(|filter| filter == "isplayed") {
        Some(true)
    } else if filters.iter().any(|filter| filter == "isunplayed") {
        Some(false)
    } else {
        None
    }
}

/// How a `Filters=` favorite/likes token should match playback state.
#[derive(Clone, Copy, PartialEq, Eq)]
enum FavoriteFilterMode {
    /// `IsFavorite` — only items explicitly marked favorite.
    FavoriteOnly,
    /// `IsFavoriteOrLikes` / `Likes` — favorite OR positively rated (like).
    FavoriteOrLikes,
}

/// Resolve the favorite/likes CSV token (Jellyfin web funnel) into a match mode.
fn favorite_filter_value(filters: &[String]) -> Option<FavoriteFilterMode> {
    if filters
        .iter()
        .any(|filter| filter == "isfavoriteorlikes" || filter == "likes")
    {
        Some(FavoriteFilterMode::FavoriteOrLikes)
    } else if filters.iter().any(|filter| filter == "isfavorite") {
        Some(FavoriteFilterMode::FavoriteOnly)
    } else {
        None
    }
}

/// `Filters=IsResumable` CSV token — items with saved playback position.
fn resumable_filter_value(filters: &[String]) -> bool {
    filters.iter().any(|filter| filter == "isresumable")
}

fn query_filters_played_value(filters: &[String]) -> Option<bool> {
    let filters = filters
        .iter()
        .flat_map(|filter| filter.split(','))
        .map(str::trim)
        .filter(|filter| !filter.is_empty())
        .map(str::to_ascii_lowercase)
        .collect::<Vec<_>>();
    played_filter_value(&filters)
}

fn query_requests_only_item_type(query: &ItemsQuery, item_type: &str) -> bool {
    let Some(include_types) = csv_values_lowercase(&query.include_item_types) else {
        return false;
    };
    include_types.len() == 1 && include_types[0].eq_ignore_ascii_case(item_type)
}

fn query_requests_item_type(query: &ItemsQuery, item_type: &str) -> bool {
    let Some(include_types) = csv_values_lowercase(&query.include_item_types) else {
        return false;
    };
    include_types
        .iter()
        .any(|include_type| include_type.eq_ignore_ascii_case(item_type))
}

async fn tv_series_items_result(
    db: &Database,
    query: &ItemsQuery,
    user_id: Option<Uuid>,
    server_id: &str,
) -> Result<Json<serde_json::Value>, ApiError> {
    let catalog_virtual_folder_id = if let Some(parent_id) = query.parent_id.as_deref() {
        parse_jellyfin_uuid(parent_id).ok().map(Some)
    } else {
        Some(None)
    };
    let catalog_virtual_folder_id = if let Some(Some(parent_id)) = catalog_virtual_folder_id {
        let is_tv_library = db.virtual_folders().await?.iter().any(|folder| {
            folder.id == parent_id
                && folder
                    .collection_type
                    .as_deref()
                    .is_some_and(|kind| kind.eq_ignore_ascii_case("tvshows"))
        });
        is_tv_library.then_some(Some(parent_id))
    } else {
        catalog_virtual_folder_id
    };
    let mut catalog_query = query.clone();
    catalog_query.parent_id = None;
    let mut simple_catalog_query = catalog_query.clone();
    simple_catalog_query.name_starts_with = None;
    simple_catalog_query.name_starts_with_or_greater = None;
    simple_catalog_query.name_less_than = None;
    if query_requests_only_item_type(query, "Series")
        && fast_name_search_query_is_simple(&simple_catalog_query)
        && let Some(virtual_folder_id) = catalog_virtual_folder_id
        && let Some(page) = db
            .tv_series_catalog_search_page(
                virtual_folder_id,
                query.start_index.unwrap_or(0),
                query
                    .limit
                    .unwrap_or(25)
                    .min(MEDIA_ITEM_CATALOG_MAX_PAGE_SIZE),
                query_flag(&query._enable_total_record_count).unwrap_or(true),
                TvSeriesCatalogNameFilter {
                    search_term: query.search_term.clone(),
                    starts_with: query.name_starts_with.clone(),
                    starts_with_or_greater: query.name_starts_with_or_greater.clone(),
                    less_than: query.name_less_than.clone(),
                },
            )
            .await?
    {
        // The page above is served either from the durable projection or, while that is unpublished,
        // from the bounded live grouping. Publishing it costs seconds, so it happens in the background
        // and the request is never delayed by it; a folder that is already published makes this a
        // single indexed lookup.
        if let Some(virtual_folder_id) = virtual_folder_id {
            schedule_tv_series_projection_rebuild(db, virtual_folder_id);
        }
        let episode_ids = page
            .episodes
            .iter()
            .map(|entry| entry.item.id)
            .collect::<Vec<_>>();
        let playback_by_item = if let Some(user_id) = user_id {
            MediaCatalogStore::playback_states_for_items(db, user_id, &episode_ids)
                .await?
                .into_iter()
                .map(|state| (state.item_id, state))
                .collect::<HashMap<_, _>>()
        } else {
            HashMap::new()
        };
        let mut grouped = HashMap::<String, TvSeriesSummary>::new();
        for entry in &page.episodes {
            let Some(info) = tv_episode_info(&entry.item) else {
                continue;
            };
            let Some(series_id) = first_metadata_value_from_json(&entry.metadata, &["SeriesId"])
            else {
                continue;
            };
            let summary = grouped
                .entry(series_id.trim().to_string())
                .or_insert_with(|| TvSeriesSummary::new(info.series_name.clone()));
            summary.add_episode(
                &entry.item,
                &info,
                Some(&entry.metadata),
                playback_by_item.get(&entry.item.id),
            );
        }
        let items = page
            .series
            .iter()
            .map(|series| {
                let mut summary = grouped
                    .remove(&series.id)
                    .unwrap_or_else(|| TvSeriesSummary::new(series.name.clone()));
                summary.id.get_or_insert_with(|| series.id.clone());
                summary
            })
            .map(|summary| shape_catalog_item_for_query(tv_series_json(server_id, summary), query))
            .collect::<Vec<_>>();
        return Ok(Json(query_result_with_total(
            items,
            page.total_record_count,
            page.start_index,
        )));
    }

    let mut episode_query = query.clone();
    episode_query.include_item_types = vec!["Episode".to_string()];
    episode_query.is_folder = None;
    episode_query.filters.retain(|filter| {
        !filter
            .split(',')
            .any(|value| value.trim().eq_ignore_ascii_case("IsFolder"))
    });
    episode_query.ids = None;
    episode_query.search_term = None;
    episode_query.name_starts_with = None;
    episode_query.name_starts_with_or_greater = None;
    episode_query.name_less_than = None;
    episode_query.start_index = None;
    episode_query.limit = None;
    episode_query.sort_by = Some("SortName".to_string());
    episode_query.sort_order = None;

    let episodes = filtered_media_items(
        db.media_items_by_collection_type("tvshows").await?,
        &episode_query,
        user_id,
        db,
    )
    .await?;
    let mut grouped = BTreeMap::<String, TvSeriesSummary>::new();
    let episode_ids = episodes.iter().map(|item| item.id).collect::<Vec<_>>();
    let metadata_by_item =
        media_metadata_by_item_id(db, episode_ids.iter().copied().collect()).await?;
    let playback_by_item = if let Some(user_id) = user_id {
        MediaCatalogStore::playback_states_for_items(db, user_id, &episode_ids)
            .await?
            .into_iter()
            .map(|state| (state.item_id, state))
            .collect::<HashMap<_, _>>()
    } else {
        HashMap::new()
    };
    for episode in episodes {
        let Some(info) = tv_episode_info(&episode) else {
            continue;
        };
        let playback = playback_by_item.get(&episode.id);
        let summary = grouped
            .entry(info.series_name.clone())
            .or_insert_with(|| TvSeriesSummary::new(info.series_name.clone()));
        summary.add_episode(&episode, &info, metadata_by_item.get(&episode.id), playback);
    }

    let requested_ids = query.ids.as_deref().map(parse_uuid_list).transpose()?;
    let search_term = query
        .search_term
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_ascii_lowercase);
    let name_starts_with = normalized_prefix(query.name_starts_with.as_deref());
    let name_starts_with_or_greater =
        normalized_prefix(query.name_starts_with_or_greater.as_deref());
    let name_less_than = normalized_prefix(query.name_less_than.as_deref());

    let mut series = grouped
        .into_values()
        .filter(|summary| {
            requested_ids.as_ref().is_none_or(|ids| {
                parse_jellyfin_uuid(&summary.id()).is_ok_and(|series_id| ids.contains(&series_id))
            })
        })
        .filter(|summary| {
            search_term
                .as_ref()
                .is_none_or(|term| summary.name.to_ascii_lowercase().contains(term.as_str()))
        })
        .filter(|summary| {
            name_starts_with
                .as_ref()
                .is_none_or(|prefix| summary.name.to_ascii_lowercase().starts_with(prefix))
        })
        .filter(|summary| {
            name_starts_with_or_greater
                .as_ref()
                .is_none_or(|prefix| summary.name.to_ascii_lowercase().as_str() >= prefix.as_str())
        })
        .filter(|summary| {
            name_less_than
                .as_ref()
                .is_none_or(|prefix| summary.name.to_ascii_lowercase().as_str() < prefix.as_str())
        })
        .collect::<Vec<_>>();

    if query
        .sort_order
        .as_deref()
        .is_some_and(|order| order.eq_ignore_ascii_case("Descending"))
    {
        series.sort_by(|left, right| right.sort_name.cmp(&left.sort_name));
    } else {
        series.sort_by(|left, right| left.sort_name.cmp(&right.sort_name));
    }

    let total_record_count = series.len();
    let start_index = query.start_index.unwrap_or(0);
    let limit = query.limit.unwrap_or(usize::MAX);
    let items = series
        .into_iter()
        .skip(start_index)
        .take(limit)
        .map(|summary| tv_series_json(server_id, summary))
        .collect::<Vec<_>>();
    Ok(Json(query_result_with_total(
        items,
        total_record_count,
        start_index,
    )))
}

#[derive(Debug)]
struct TvSeriesSummary {
    source_name: String,
    id: Option<String>,
    name: String,
    sort_name: String,
    seasons: BTreeSet<i32>,
    episode_count: usize,
    unplayed_count: usize,
    path: Option<String>,
    date_created: Option<time::OffsetDateTime>,
    date_last_media_added: Option<time::OffsetDateTime>,
    runtime_ticks: i64,
    production_year: Option<i32>,
    premiere_date: Option<String>,
    end_date: Option<String>,
    metadata: serde_json::Value,
}

impl TvSeriesSummary {
    fn new(source_name: String) -> Self {
        let (name, production_year) = clean_tv_series_name_and_year(&source_name);
        let sort_name = name.to_ascii_lowercase();
        Self {
            source_name,
            id: None,
            name,
            sort_name,
            seasons: BTreeSet::new(),
            episode_count: 0,
            unplayed_count: 0,
            path: None,
            date_created: None,
            date_last_media_added: None,
            runtime_ticks: 0,
            production_year,
            premiere_date: None,
            end_date: None,
            metadata: serde_json::Value::Object(serde_json::Map::new()),
        }
    }

    fn add_episode(
        &mut self,
        item: &MediaItem,
        info: &TvEpisodeInfo,
        metadata: Option<&serde_json::Value>,
        playback: Option<&PlaybackState>,
    ) {
        self.episode_count += 1;
        if playback.is_none_or(|state| !state.played) {
            self.unplayed_count += 1;
        }
        if let Some(season_number) = info.season_number {
            self.seasons.insert(season_number);
        }
        if let Some(path) = tv_series_path_for_episode(item, info) {
            self.path.get_or_insert(path);
        }
        self.date_created = Some(
            self.date_created
                .map_or(item.created_at, |current| current.min(item.created_at)),
        );
        self.date_last_media_added = Some(
            self.date_last_media_added
                .map_or(item.updated_at, |current| current.max(item.updated_at)),
        );
        if let Some(runtime_ticks) = item.runtime_ticks {
            self.runtime_ticks += runtime_ticks;
        }
        if let Some(metadata) = metadata {
            self.merge_episode_metadata(metadata);
        }
    }

    fn add_series_anchor(&mut self, item: &MediaItem, metadata: &serde_json::Value) {
        self.date_created = Some(
            self.date_created
                .map_or(item.created_at, |current| current.min(item.created_at)),
        );
        self.date_last_media_added = Some(
            self.date_last_media_added
                .map_or(item.updated_at, |current| current.max(item.updated_at)),
        );
        self.merge_episode_metadata(metadata);
    }

    fn merge_episode_metadata(&mut self, metadata: &serde_json::Value) {
        if self.id.is_none() {
            self.id = canonical_metadata_uuid_from_json(metadata, &["SeriesId"]);
        }
        if let Some(series_name) = first_metadata_value_from_json(metadata, &["SeriesName"])
            && !series_name.trim().is_empty()
        {
            self.name = series_name.trim().to_string();
            self.sort_name = self.name.to_ascii_lowercase();
        }
        if self.premiere_date.is_none()
            && let Some(value) =
                first_metadata_value_from_json(metadata, &["SeriesPremiereDate", "PremiereDate"])
        {
            self.premiere_date = Some(normalize_metadata_date_for_json(&value));
        }
        if let Some(value) = first_metadata_value_from_json(metadata, &["EndDate"]) {
            self.end_date = Some(normalize_metadata_date_for_json(&value));
        }
        if self.production_year.is_none() {
            self.production_year = first_metadata_i32_from_json(
                metadata,
                &["SeriesProductionYear", "ProductionYear", "Year"],
            );
        }

        for (target, keys) in [
            ("Overview", &["SeriesOverview"][..]),
            ("OriginalTitle", &["SeriesOriginalTitle"][..]),
            ("OfficialRating", &["SeriesOfficialRating"][..]),
            ("Status", &["SeriesStatus", "Status"][..]),
            ("ContentType", &["SeriesContentType"][..]),
            ("OriginalLanguage", &["OriginalLanguage", "Language"][..]),
            ("SeriesPrimaryImageTag", &["SeriesPrimaryImageTag"][..]),
            ("SeriesBackdropImageTag", &["SeriesBackdropImageTag"][..]),
            ("SeriesThumbImageTag", &["SeriesThumbImageTag"][..]),
            ("SeriesLogoImageTag", &["SeriesLogoImageTag"][..]),
            ("SeriesPrimaryImageUrl", &["SeriesPrimaryImageUrl"][..]),
            ("SeriesBackdropImageUrl", &["SeriesBackdropImageUrl"][..]),
            ("SeriesThumbImageUrl", &["SeriesThumbImageUrl"][..]),
            ("SeriesLogoImageUrl", &["SeriesLogoImageUrl"][..]),
            ("SeriesPrimaryImagePath", &["SeriesPrimaryImagePath"][..]),
            ("SeriesBackdropImagePath", &["SeriesBackdropImagePath"][..]),
            ("SeriesThumbImagePath", &["SeriesThumbImagePath"][..]),
            ("SeriesLogoImagePath", &["SeriesLogoImagePath"][..]),
            ("MetadataSource", &["MetadataSource"][..]),
        ] {
            if self.metadata.get(target).is_none()
                && let Some(value) = first_metadata_value_from_json(metadata, keys)
            {
                self.metadata[target] = serde_json::Value::String(value);
            }
        }

        for (target, keys) in [
            ("CommunityRating", &["SeriesCommunityRating"][..]),
            ("CriticRating", &["SeriesCriticRating"][..]),
        ] {
            if self.metadata.get(target).is_none()
                && let Some(value) = first_metadata_number_from_json(metadata, keys)
            {
                self.metadata[target] = serde_json::json!(value);
            }
        }

        if self.metadata.get("People").is_none()
            && let Some(people) = json_field_case_insensitive(metadata, "SeriesPeople")
                .or_else(|| json_field_case_insensitive(metadata, "People"))
            && people.is_array()
        {
            self.metadata["People"] = people.clone();
        }

        for (target, keys) in [
            ("Genres", &["SeriesGenres"][..]),
            ("Studios", &["SeriesStudios"][..]),
            ("Tags", &["SeriesTags"][..]),
            ("Taglines", &["SeriesTaglines"][..]),
            ("AirDays", &["SeriesAirDays", "AirDays"][..]),
        ] {
            let mut values = metadata_values_from_json(&self.metadata, &[target]);
            values.extend(metadata_values_from_json(metadata, keys));
            values.sort();
            values.dedup();
            if !values.is_empty() {
                self.metadata[target] = serde_json::json!(values);
            }
        }

        if let Some(air_day) = episode_air_day_from_metadata(metadata) {
            let mut values = metadata_values_from_json(&self.metadata, &["AirDays"]);
            values.push(air_day);
            values.sort();
            values.dedup();
            self.metadata["AirDays"] = serde_json::json!(values);
        }

        if self.metadata.get("ProviderIds").is_none()
            && let Some(provider_ids) = json_field_case_insensitive(metadata, "SeriesProviderIds")
            && provider_ids.is_object()
        {
            self.metadata["ProviderIds"] = provider_ids.clone();
        }
        if self.metadata.get("RemoteTrailers").is_none()
            && let Some(trailers) = json_field_case_insensitive(metadata, "SeriesRemoteTrailers")
                .or_else(|| json_field_case_insensitive(metadata, "RemoteTrailers"))
            && trailers.is_array()
        {
            self.metadata["RemoteTrailers"] = trailers.clone();
        }
    }

    fn id(&self) -> String {
        self.id
            .clone()
            .unwrap_or_else(|| tv_series_id(&self.source_name))
    }
}

fn episode_air_day_from_metadata(metadata: &serde_json::Value) -> Option<String> {
    first_metadata_value_from_json(metadata, &["PremiereDate", "AirDate"])
        .as_deref()
        .and_then(parse_item_query_date)
        .map(|date| weekday_display_name(date.date().weekday()).to_string())
}

fn weekday_display_name(weekday: time::Weekday) -> &'static str {
    match weekday {
        time::Weekday::Monday => "Monday",
        time::Weekday::Tuesday => "Tuesday",
        time::Weekday::Wednesday => "Wednesday",
        time::Weekday::Thursday => "Thursday",
        time::Weekday::Friday => "Friday",
        time::Weekday::Saturday => "Saturday",
        time::Weekday::Sunday => "Sunday",
    }
}

fn tv_series_json(server_id: &str, summary: TvSeriesSummary) -> serde_json::Value {
    let series_id = summary.id();
    let season_count = summary.seasons.len();
    let image_tag = default_primary_image_tag(&series_id);
    let played = summary.episode_count > 0 && summary.unplayed_count == 0;
    let mut value = serde_json::json!({
        "Name": summary.name,
        "OriginalTitle": null,
        "ServerId": server_id,
        "Id": series_id,
        "Etag": null,
        "DateCreated": summary.date_created.map(format_time_for_json),
        "DateLastMediaAdded": summary.date_last_media_added.map(format_time_for_json),
        "CanDelete": false,
        "CanDownload": false,
        "SortName": summary.sort_name,
        "ForcedSortName": null,
        "ExternalUrls": [],
        "Path": summary.path,
        "PremiereDate": summary.premiere_date,
        "EndDate": summary.end_date,
        "ProductionYear": summary.production_year,
        "OfficialRating": null,
        "CommunityRating": null,
        "CriticRating": null,
        "Overview": "",
        "EnableMediaSourceDisplay": true,
        "ChannelId": null,
        "Taglines": [],
        "Genres": [],
        "GenreItems": [],
        "Studios": [],
        "People": [],
        "Tags": [],
        "TagItems": [],
        "PlayAccess": "Full",
        "RemoteTrailers": [],
        "ProviderIds": {},
        "ContentType": "tvshows",
        "IsFolder": true,
        "ParentId": null,
        "Type": "Series",
        "MediaType": null,
        "ChildCount": season_count,
        "RecursiveItemCount": summary.episode_count,
        "CumulativeRunTimeTicks": (summary.runtime_ticks > 0).then_some(summary.runtime_ticks),
        "RunTimeTicks": (summary.runtime_ticks > 0 && summary.episode_count > 0)
            .then(|| summary.runtime_ticks / summary.episode_count as i64),
        "SpecialFeatureCount": 0,
        "DisplayPreferencesId": stable_entity_id("DisplayPreferences", &series_id),
        "Status": null,
        "AirDays": [],
        "Chapters": [],
        "UserData": {
            "PlaybackPositionTicks": 0,
            "PlayCount": i32::from(played),
            "IsFavorite": false,
            "Played": played,
            "PlayedPercentage": if played { 100.0 } else { 0.0 },
            "UnplayedItemCount": summary.unplayed_count,
            "Key": series_id,
            "ItemId": series_id
        },
        "ImageTags": { "Primary": image_tag },
        "PrimaryImageAspectRatio": 0.6666667,
        "BackdropImageTags": [],
        "LocationType": "Virtual"
    });
    apply_tv_series_metadata(&mut value, &summary.metadata);
    value
}

fn apply_tv_series_metadata(value: &mut serde_json::Value, metadata: &serde_json::Value) {
    let Some(object) = value.as_object_mut() else {
        return;
    };

    for key in [
        "Overview",
        "OriginalTitle",
        "OfficialRating",
        "CommunityRating",
        "CriticRating",
        "Status",
        "ContentType",
        "OriginalLanguage",
    ] {
        if let Some(field_value) = metadata.get(key)
            && !field_value.is_null()
            && field_value.as_str() != Some("")
        {
            object.insert(key.to_string(), field_value.clone());
        }
    }

    for (target, item_type) in [
        ("Genres", "Genre"),
        ("Tags", "Tag"),
        ("Studios", "Studio"),
        ("Taglines", "Tagline"),
    ] {
        let values = metadata_values_from_json(metadata, &[target]);
        if values.is_empty() {
            continue;
        }
        object.insert(target.to_string(), serde_json::json!(values));
        match target {
            "Genres" => {
                object.insert(
                    "GenreItems".to_string(),
                    serde_json::json!(metadata_name_id_items(item_type, &values)),
                );
            }
            "Studios" => {
                object.insert(
                    "Studios".to_string(),
                    serde_json::json!(metadata_name_id_items(item_type, &values)),
                );
            }
            "Tags" => {
                object.insert(
                    "TagItems".to_string(),
                    serde_json::json!(metadata_name_id_items(item_type, &values)),
                );
            }
            _ => {}
        }
    }
    let air_days = metadata_values_from_json(metadata, &["AirDays", "SeriesAirDays"]);
    if !air_days.is_empty() {
        object.insert("AirDays".to_string(), serde_json::json!(air_days));
    }

    let people = metadata_people_items_from_json(metadata, &["People", "SeriesPeople"]);
    if !people.is_empty() {
        object.insert("People".to_string(), serde_json::json!(people));
    }
    if let Some(provider_ids) = metadata.get("ProviderIds")
        && provider_ids.is_object()
    {
        object.insert("ProviderIds".to_string(), provider_ids.clone());
        object.insert(
            "ExternalUrls".to_string(),
            serde_json::json!(external_urls_from_provider_ids(provider_ids)),
        );
    }
    if let Some(trailers) = json_field_case_insensitive(metadata, "RemoteTrailers")
        && trailers.is_array()
    {
        object.insert("RemoteTrailers".to_string(), trailers.clone());
    }
    let primary_tag = first_metadata_value_from_json(metadata, &["SeriesPrimaryImageTag"]);
    let thumb_tag = first_metadata_value_from_json(metadata, &["SeriesThumbImageTag"]);
    let logo_tag = first_metadata_value_from_json(metadata, &["SeriesLogoImageTag"]);
    if primary_tag.is_some() || thumb_tag.is_some() || logo_tag.is_some() {
        let mut image_tags = serde_json::Map::new();
        if let Some(primary_tag) = primary_tag {
            image_tags.insert(
                "Primary".to_string(),
                serde_json::Value::String(primary_tag),
            );
        }
        if let Some(thumb_tag) = thumb_tag {
            image_tags.insert("Thumb".to_string(), serde_json::Value::String(thumb_tag));
        }
        if let Some(logo_tag) = logo_tag {
            image_tags.insert("Logo".to_string(), serde_json::Value::String(logo_tag));
        }
        object.insert(
            "ImageTags".to_string(),
            serde_json::Value::Object(image_tags),
        );
    }
    if let Some(backdrop_tag) =
        first_metadata_value_from_json(metadata, &["SeriesBackdropImageTag", "BackdropImageTag"])
    {
        object.insert(
            "BackdropImageTags".to_string(),
            serde_json::json!([backdrop_tag]),
        );
    }
}

fn metadata_people_items_from_json(
    metadata: &serde_json::Value,
    keys: &[&str],
) -> Vec<serde_json::Value> {
    let mut people = Vec::<serde_json::Value>::new();
    let mut seen = HashSet::<String>::new();
    for key in keys {
        let Some(value) = json_field_case_insensitive(metadata, key) else {
            continue;
        };
        collect_metadata_people(value, &mut people, &mut seen);
    }
    remember_metadata_people(&people);
    people
}

fn collect_metadata_people(
    value: &serde_json::Value,
    people: &mut Vec<serde_json::Value>,
    seen: &mut HashSet<String>,
) {
    match value {
        serde_json::Value::Array(items) => {
            for item in items {
                collect_metadata_people(item, people, seen);
            }
        }
        serde_json::Value::String(name) => {
            if let Ok(parsed) = serde_json::from_str::<serde_json::Value>(name)
                && (parsed.is_array() || parsed.is_object())
            {
                collect_metadata_people(&parsed, people, seen);
                return;
            }
            let name = name.trim();
            if !name.is_empty() && seen.insert(name.to_ascii_lowercase()) {
                people.push(metadata_people_items(&[name.to_string()]).remove(0));
            }
        }
        serde_json::Value::Object(object) => {
            let Some(name) = object.get("Name").and_then(serde_json::Value::as_str) else {
                return;
            };
            let name = name.trim();
            if name.is_empty() {
                return;
            }
            if seen.insert(name.to_ascii_lowercase()) {
                people.push(serde_json::json!({
                    "Name": name,
                    "Id": stable_entity_id("Person", name),
                    "Role": object.get("Role").cloned().unwrap_or(serde_json::Value::Null),
                    "Type": object.get("Type").cloned().unwrap_or_else(|| serde_json::json!("Person")),
                    "PrimaryImageTag": object
                        .get("PrimaryImageTag")
                        .filter(|value| !value.is_null())
                        .cloned()
                        .unwrap_or_else(|| serde_json::json!(default_primary_image_tag(&stable_entity_id("Person", name))))
                }));
            }
        }
        _ => {}
    }
}

fn external_urls_from_provider_ids(provider_ids: &serde_json::Value) -> Vec<serde_json::Value> {
    let Some(provider_ids) = provider_ids.as_object() else {
        return Vec::new();
    };
    provider_ids
        .iter()
        .filter_map(|(name, value)| {
            let id = value.as_str()?.trim();
            if id.is_empty() {
                return None;
            }
            let url = match name.to_ascii_lowercase().as_str() {
                "imdb" => format!("https://www.imdb.com/title/{id}"),
                "tmdb" => format!("https://www.themoviedb.org/tv/{id}"),
                "tvdb" => format!("https://thetvdb.com/dereferrer/series/{id}"),
                _ => return None,
            };
            Some(serde_json::json!({ "Name": name, "Url": url }))
        })
        .collect()
}

fn clean_tv_series_name_and_year(source_name: &str) -> (String, Option<i32>) {
    let source_name = source_name.trim();
    if let Some((prefix, suffix)) = source_name.split_once(" (")
        && let Some(year) = suffix.get(..4)
        && year.bytes().all(|byte| byte.is_ascii_digit())
        && suffix.as_bytes().get(4) == Some(&b')')
    {
        return (prefix.trim().to_string(), year.parse::<i32>().ok());
    }
    (source_name.to_string(), None)
}

fn tv_series_path_for_episode(item: &MediaItem, info: &TvEpisodeInfo) -> Option<String> {
    let episode_path = media_item_path(item);
    let parent = episode_path.parent()?;
    if info.season_number.is_some() {
        parent
            .parent()
            .or(Some(parent))
            .map(|path| path.to_string_lossy().to_string())
    } else {
        Some(parent.to_string_lossy().to_string())
    }
}

const TVMAZE_API_ORIGIN: &str = "https://api.tvmaze.com/";
const TVMAZE_API_HOST: &str = "api.tvmaze.com";
const TVMAZE_API_PORT: u16 = 443;
const TVMAZE_DNS_TIMEOUT: StdDuration = StdDuration::from_secs(3);
const TVMAZE_CONNECT_TIMEOUT: StdDuration = StdDuration::from_secs(3);
const TVMAZE_REQUEST_TIMEOUT: StdDuration = StdDuration::from_secs(10);
const TVMAZE_CAPACITY_WAIT_TIMEOUT: StdDuration = StdDuration::from_secs(2);
const TVMAZE_MAX_CONCURRENT_REQUESTS: usize = 4;
const TVMAZE_MAX_QUEUED_REQUESTS: usize = 32;
const TVMAZE_SEARCH_MAX_BODY_BYTES: usize = 1024 * 1024;
const TVMAZE_SEARCH_MAX_ITEMS: usize = 64;
const TVMAZE_CAST_MAX_BODY_BYTES: usize = 2 * 1024 * 1024;
const TVMAZE_CAST_MAX_ITEMS: usize = 512;
const TVMAZE_IMAGES_MAX_BODY_BYTES: usize = 4 * 1024 * 1024;
const TVMAZE_IMAGES_MAX_ITEMS: usize = 1024;
const TVMAZE_SEASONS_MAX_BODY_BYTES: usize = 2 * 1024 * 1024;
const TVMAZE_SEASONS_MAX_ITEMS: usize = 512;
const TVMAZE_EPISODES_MAX_BODY_BYTES: usize = 8 * 1024 * 1024;
const TVMAZE_EPISODES_MAX_ITEMS: usize = 10_000;
static TVMAZE_HTTP_CLIENT: tokio::sync::OnceCell<HttpClient> = tokio::sync::OnceCell::const_new();
static TVMAZE_REQUEST_LIMITER: Semaphore = Semaphore::const_new(TVMAZE_MAX_CONCURRENT_REQUESTS);
static TVMAZE_REQUEST_WAIT_QUEUE: Semaphore = Semaphore::const_new(TVMAZE_MAX_QUEUED_REQUESTS);

