pub(crate) fn media_item_to_json(item: &MediaItem, server_id: &str) -> serde_json::Value {
    media_item_to_json_with_playback(item, server_id, None)
}

fn transcode_session_json(session: &TranscodeSession) -> serde_json::Value {
    let item_id = session.item.id.simple().to_string();
    serde_json::json!({
        "PlaySessionId": session.play_session_id,
        "UserId": session.user_id.simple().to_string(),
        "ItemId": item_id,
        "MediaSourceId": session.media_source_id.clone().unwrap_or(item_id),
        "DeviceId": null,
        "Path": session.output_path,
        "OutputPath": session.output_path,
        "Status": session.status,
        "ProcessId": session.process_id,
        "ProgressPercentage": session.progress_percent,
        "CompletionPercentage": session.progress_percent,
        "TranscodingPositionTicks": session.position_ticks,
        "TranscodingStartPositionTicks": 0,
        "Container": media_item_container(&session.item),
        "VideoCodec": media_item_stream_codec(&session.item, "Video"),
        "AudioCodec": media_item_stream_codec(&session.item, "Audio"),
        "Width": session.item.width,
        "Height": session.item.height,
        "Bitrate": session.item.bitrate,
        "VideoStreamIndex": session.video_stream_index,
        "AudioStreamIndex": session.audio_stream_index,
        "SubtitleStreamIndex": session.subtitle_stream_index,
        "TranscodeReasons": [],
        "IsAudioDirect": false,
        "IsVideoDirect": false,
        "UpdatedAt": format_time_for_json(session.updated_at),
    })
}

fn media_item_to_json_with_playback(
    item: &MediaItem,
    server_id: &str,
    playback: Option<&PlaybackState>,
) -> serde_json::Value {
    media_item_to_json_with_playback_and_metadata(item, server_id, playback, None)
}

fn media_item_to_json_with_playback_and_metadata(
    item: &MediaItem,
    server_id: &str,
    playback: Option<&PlaybackState>,
    metadata: Option<&serde_json::Value>,
) -> serde_json::Value {
    let item_type = media_item_type(item);
    let item_id = item.id.simple().to_string();
    let image_tag = primary_image_tag_for_metadata(&item_id, metadata);
    let container = media_item_container(item);
    let file_name = media_item_file_name(item);
    let file_size = media_item_file_size(item);
    let playback_position_ticks = playback.map_or(0, |state| state.position_ticks);
    let played = playback.is_some_and(|state| state.played);
    let play_count = i32::from(played);
    let is_favorite = playback.is_some_and(|state| state.is_favorite);
    let rating = playback.and_then(|state| state.rating);
    let likes = rating.map(|rating| rating > 0.0);
    let media_streams = media_item_streams(item);
    let default_audio_stream_index = default_audio_stream_index(&media_streams);
    let default_subtitle_stream_index = default_subtitle_stream_index(&media_streams);
    let selected_audio_stream_index = playback
        .and_then(|state| state.audio_stream_index)
        .or(default_audio_stream_index);
    let selected_subtitle_stream_index =
        selected_subtitle_stream_index(playback, default_subtitle_stream_index);
    let video_type = if item.media_type == "Video" {
        serde_json::json!("VideoFile")
    } else {
        serde_json::Value::Null
    };
    let episode_info = tv_episode_info(item);
    let series_name = episode_info
        .as_ref()
        .map(|info| serde_json::json!(info.series_name))
        .unwrap_or(serde_json::Value::Null);
    let series_id = episode_info
        .as_ref()
        .map(|info| serde_json::json!(tv_series_id(&info.series_name)))
        .unwrap_or(serde_json::Value::Null);
    let season_name = episode_info
        .as_ref()
        .and_then(|info| info.season_number.map(|season| format!("Season {season}")))
        .map(serde_json::Value::String)
        .unwrap_or(serde_json::Value::Null);
    let parent_index_number = episode_info
        .as_ref()
        .and_then(|info| info.season_number)
        .map(serde_json::Value::from)
        .unwrap_or(serde_json::Value::Null);
    let index_number = episode_info
        .as_ref()
        .and_then(|info| info.episode_number)
        .map(serde_json::Value::from)
        .unwrap_or(serde_json::Value::Null);

    let media_source = serde_json::json!({
        "Protocol": "File",
        "Id": playback.and_then(|state| state.media_source_id.clone()).unwrap_or_else(|| item_id.clone()),
        "Path": item.path,
        "Type": "Default",
        "Container": container,
        "Size": file_size,
        "Name": item.name,
        "IsRemote": false,
        "ETag": stable_entity_id("MediaSourceETag", &item_id),
        "RunTimeTicks": item.runtime_ticks,
        "ReadAtNativeFramerate": false,
        "IgnoreDts": false,
        "IgnoreIndex": false,
        "GenPtsInput": false,
        "SupportsTranscoding": item.media_type == "Video" || item.media_type == "Audio",
        "SupportsDirectStream": true,
        "SupportsDirectPlay": true,
        "IsInfiniteStream": false,
        "CanSeek": true,
        "UseMostCompatibleTranscodingProfile": false,
        "RequiresOpening": false,
        "RequiresClosing": false,
        "RequiresLooping": false,
        "SupportsProbing": true,
        "VideoType": video_type,
        "DefaultAudioStreamIndex": selected_audio_stream_index,
        "MediaStreams": media_streams.clone(),
        "MediaAttachments": [],
        "Formats": [],
        "RequiredHttpHeaders": {},
        "TranscodingSubProtocol": "http",
        "HasSegments": false,
        "Bitrate": item.bitrate,
    });
    let mut media_source = media_source;
    if (is_xtream_remote_media(metadata) || is_plugin_vod_remote_media(metadata))
        && let Some(object) = media_source.as_object_mut()
    {
        object.insert("Protocol".to_string(), serde_json::json!("Http"));
        object.insert("IsRemote".to_string(), serde_json::json!(true));
        object.insert("LocationType".to_string(), serde_json::json!("Remote"));
        object.insert("SupportsDirectPlay".to_string(), serde_json::json!(false));
        object.insert("SupportsDirectStream".to_string(), serde_json::json!(false));
        object.insert("SupportsTranscoding".to_string(), serde_json::json!(true));
        object.insert("IsInfiniteStream".to_string(), serde_json::json!(false));
        object.insert("CanSeek".to_string(), serde_json::json!(true));
        object.remove("DirectStreamUrl");
    }
    if !selected_subtitle_stream_index.is_null()
        && let Some(object) = media_source.as_object_mut()
    {
        object.insert(
            "DefaultSubtitleStreamIndex".to_string(),
            selected_subtitle_stream_index.clone(),
        );
    }

    let mut value = serde_json::json!({
        "Name": item.name,
        "OriginalTitle": null,
        "ServerId": server_id,
        "Id": item_id,
        "SeriesName": series_name,
        "SeriesId": series_id,
        "SeasonName": season_name,
        "ParentIndexNumber": parent_index_number,
        "IndexNumber": index_number,
        "Etag": null,
        "DateCreated": format_time_for_json(item.created_at),
        "DateLastMediaAdded": format_time_for_json(item.updated_at),
        "PremiereDate": null,
        "ProductionYear": null,
        "CommunityRating": null,
        "CriticRating": null,
        "OfficialRating": null,
        "Overview": "",
        "CanDelete": false,
        "CanDownload": true,
        "SortName": item.name,
        "ForcedSortName": null,
        "ExternalUrls": [],
        "Path": item.path,
        "FileName": file_name,
        "Container": container,
        "Size": file_size,
        "EnableMediaSourceDisplay": true,
        "ChannelId": null,
        "Taglines": [],
        "Genres": [],
        "GenreItems": [],
        "Studios": [],
        "People": [],
        "Tags": [],
        "TagItems": [],
        "Chapters": [],
        "MediaStreams": media_streams,
        "PlayAccess": "Full",
        "RemoteTrailers": [],
        "ProviderIds": {},
        "LockData": false,
        "LockedFields": [],
        "SpecialFeatureCount": 0,
        "DisplayPreferencesId": stable_entity_id("DisplayPreferences", &item_id),
        "IsFolder": false,
        "ParentId": item.virtual_folder_id.simple().to_string(),
        "Type": item_type,
        "MediaType": item.media_type,
        "RunTimeTicks": item.runtime_ticks,
        "UserData": { "PlaybackPositionTicks": playback_position_ticks, "PlayCount": play_count, "IsFavorite": is_favorite, "Likes": likes, "Played": played, "Key": item_id, "ItemId": item_id, "PlayedPercentage": null, "LastPlayedDate": null, "Rating": rating },
        "ImageTags": { "Primary": image_tag },
        "PrimaryImageAspectRatio": 0.6666667,
        "BackdropImageTags": [],
        "LocationType": "FileSystem",
        "MediaSources": [media_source],
    });
    if (is_xtream_remote_media(metadata) || is_plugin_vod_remote_media(metadata))
        && let Some(object) = value.as_object_mut()
    {
        object.insert("LocationType".to_string(), serde_json::json!("Remote"));
        object.insert("CanDownload".to_string(), serde_json::json!(false));
    }
    if item_type == "Series"
        && let Some(object) = value.as_object_mut()
    {
        object.insert("IsFolder".to_string(), serde_json::json!(true));
        object.insert("MediaType".to_string(), serde_json::json!("Video"));
        object.insert("CanDownload".to_string(), serde_json::json!(false));
        object.remove("MediaSources");
        object.remove("MediaStreams");
    }
    apply_media_item_metadata(&mut value, metadata, item, server_id);
    value
}

fn apply_media_item_metadata(
    value: &mut serde_json::Value,
    metadata: Option<&serde_json::Value>,
    item: &MediaItem,
    server_id: &str,
) {
    let Some(metadata) = metadata else {
        return;
    };
    let trailers = metadata_remote_trailers(metadata, item, server_id);
    let Some(object) = value.as_object_mut() else {
        return;
    };

    for (target, keys) in [
        ("Name", &["Name", "Title", "title"][..]),
        ("Overview", &["Overview", "overview"][..]),
        ("OriginalTitle", &["OriginalTitle", "originalTitle"][..]),
        ("OfficialRating", &["OfficialRating", "OfficialRatings"][..]),
        ("Album", &["Album", "AlbumName"][..]),
        ("AlbumArtist", &["AlbumArtist", "AlbumArtists"][..]),
    ] {
        if let Some(field_value) = first_metadata_value_from_json(metadata, keys) {
            object.insert(target.to_string(), serde_json::Value::String(field_value));
        }
    }

    for (target, keys) in [
        ("CommunityRating", &["CommunityRating", "Rating"][..]),
        ("CriticRating", &["CriticRating"][..]),
    ] {
        if let Some(field_value) = first_metadata_number_from_json(metadata, keys) {
            object.insert(target.to_string(), serde_json::json!(field_value));
        }
    }

    if let Some(year) = first_metadata_i32_from_json(metadata, &["ProductionYear", "Year"]) {
        object.insert("ProductionYear".to_string(), serde_json::json!(year));
    }
    if let Some(premiere_date) =
        first_metadata_value_from_json(metadata, &["PremiereDate", "AirDate", "DateCreated"])
    {
        object.insert(
            "PremiereDate".to_string(),
            serde_json::Value::String(normalize_metadata_date_for_json(&premiere_date)),
        );
    }
    if let Some(index_number) = first_metadata_i32_from_json(metadata, &["IndexNumber"]) {
        object.insert("IndexNumber".to_string(), serde_json::json!(index_number));
    }
    if let Some(parent_index_number) =
        first_metadata_i32_from_json(metadata, &["ParentIndexNumber"])
    {
        object.insert(
            "ParentIndexNumber".to_string(),
            serde_json::json!(parent_index_number),
        );
    }
    if media_item_type(item) == "Episode"
        && let Some(series_name) = first_metadata_value_from_json(metadata, &["SeriesName"])
    {
        object.insert(
            "SeriesName".to_string(),
            serde_json::Value::String(series_name),
        );
    }
    if media_item_type(item) == "Episode"
        && let Some(series_id) = canonical_metadata_uuid_from_json(metadata, &["SeriesId"])
    {
        object.insert(
            "SeriesId".to_string(),
            serde_json::Value::String(series_id.clone()),
        );
        if object.get("ParentBackdropItemId").is_some() {
            object.insert(
                "ParentBackdropItemId".to_string(),
                serde_json::Value::String(series_id.clone()),
            );
        }
        if object.get("ParentThumbItemId").is_some() {
            object.insert(
                "ParentThumbItemId".to_string(),
                serde_json::Value::String(series_id),
            );
        }
    }
    if media_item_type(item) == "Episode"
        && let Some(season_id) = canonical_metadata_uuid_from_json(metadata, &["SeasonId"])
    {
        object.insert(
            "SeasonId".to_string(),
            serde_json::Value::String(season_id.clone()),
        );
        object.insert("ParentId".to_string(), serde_json::Value::String(season_id));
    }
    if let Some(primary_tag) =
        first_metadata_value_from_json(metadata, &["PrimaryImageTag", "ImageTag"])
    {
        object.insert(
            "ImageTags".to_string(),
            serde_json::json!({ "Primary": primary_tag }),
        );
    }
    let series_primary_tag = first_metadata_value_from_json(metadata, &["SeriesPrimaryImageTag"])
        .or_else(|| {
            // Jellyfin Android TV deliberately uses the series poster for portrait episode cards.
            // Plugin catalogues persist that poster under the virtual Series owner, so advertise
            // its deterministic tag even when the provider did not supply an explicit tag field.
            // The authenticated image route resolves/caches the provider raster on first use.
            (media_item_type(item) == "Episode" && is_plugin_vod_remote_media(Some(metadata)))
                .then(|| {
                    object
                        .get("SeriesId")
                        .and_then(serde_json::Value::as_str)
                        .map(|series_id| primary_image_tag_for_metadata(series_id, Some(metadata)))
                })
                .flatten()
        });
    if let Some(series_primary_tag) = series_primary_tag {
        object.insert(
            "SeriesPrimaryImageTag".to_string(),
            serde_json::Value::String(series_primary_tag),
        );
    }
    if let Some(series_backdrop_tag) =
        first_metadata_value_from_json(metadata, &["SeriesBackdropImageTag"])
    {
        object.insert(
            "ParentBackdropImageTags".to_string(),
            serde_json::json!([series_backdrop_tag]),
        );
        if let Some(series_id) = object.get("SeriesId").cloned() {
            object.insert("ParentBackdropItemId".to_string(), series_id);
        }
    }
    if let Some(backdrop_tag) = first_metadata_value_from_json(metadata, &["BackdropImageTag"]) {
        object.insert(
            "BackdropImageTags".to_string(),
            serde_json::json!([backdrop_tag]),
        );
    }
    if let Some(series_thumb_tag) =
        first_metadata_value_from_json(metadata, &["SeriesThumbImageTag"])
    {
        object.insert(
            "ParentThumbImageTag".to_string(),
            serde_json::Value::String(series_thumb_tag),
        );
        if let Some(series_id) = object.get("SeriesId").cloned() {
            object.insert("ParentThumbItemId".to_string(), series_id);
        }
    }

    let taglines = metadata_values_from_json(metadata, &["Taglines"]);
    if !taglines.is_empty() {
        object.insert("Taglines".to_string(), serde_json::json!(taglines));
    }

    for (target, keys) in [
        ("LockData", &["LockData"][..]),
        ("LockedFields", &["LockedFields"][..]),
    ] {
        if let Some(field_value) = first_metadata_json_from_case_insensitive(metadata, keys) {
            object.insert(target.to_string(), field_value);
        }
    }

    let genres = metadata_values_from_json(metadata, &["Genres", "SeriesGenres", "MusicGenres"]);
    if !genres.is_empty() {
        object.insert("Genres".to_string(), serde_json::json!(genres));
        object.insert(
            "GenreItems".to_string(),
            serde_json::json!(metadata_name_id_items("Genre", &genres)),
        );
    }

    let studios = metadata_values_from_json(metadata, &["Studios", "SeriesStudios"]);
    if !studios.is_empty() {
        object.insert(
            "Studios".to_string(),
            serde_json::json!(metadata_name_id_items("Studio", &studios)),
        );
    }

    let people = metadata_people_items_from_json(metadata, &["People", "Cast", "SeriesPeople"]);
    if !people.is_empty() {
        object.insert("People".to_string(), serde_json::json!(people));
    }

    let tags = metadata_values_from_json(metadata, &["Tags"]);
    if !tags.is_empty() {
        object.insert("Tags".to_string(), serde_json::json!(tags));
        object.insert(
            "TagItems".to_string(),
            serde_json::json!(metadata_name_id_items("Tag", &tags)),
        );
    }

    let artists = metadata_values_from_json(metadata, &["Artists"]);
    if !artists.is_empty() {
        object.insert("Artists".to_string(), serde_json::json!(artists));
    }

    let provider_ids = merged_provider_ids_from_metadata(metadata);
    if !provider_ids.is_empty() {
        let provider_ids = serde_json::Value::Object(provider_ids);
        object.insert("ProviderIds".to_string(), provider_ids.clone());
        object.insert(
            "ExternalUrls".to_string(),
            serde_json::json!(external_urls_from_provider_ids(&provider_ids)),
        );
    }

    if !trailers.is_empty() {
        object.insert("RemoteTrailers".to_string(), serde_json::json!(trailers));
    }
    if let Some(chapters) = json_field_case_insensitive(metadata, "Chapters")
        && chapters.is_array()
    {
        object.insert("Chapters".to_string(), chapters.clone());
    }
}

fn first_metadata_json_from_case_insensitive(
    metadata: &serde_json::Value,
    keys: &[&str],
) -> Option<serde_json::Value> {
    for key in keys {
        if let Some(value) = json_field_case_insensitive(metadata, key) {
            return Some(value.clone());
        }
    }
    None
}

fn merged_provider_ids_from_metadata(
    metadata: &serde_json::Value,
) -> serde_json::Map<String, serde_json::Value> {
    let mut merged = serde_json::Map::new();
    for key in ["SeriesProviderIds", "ProviderIds", "ProviderId"] {
        let Some(value) = json_field_case_insensitive(metadata, key) else {
            continue;
        };
        let Some(object) = value.as_object() else {
            continue;
        };
        for (provider, id) in object {
            if id.is_null() || id.as_str().is_some_and(|id| id.trim().is_empty()) {
                continue;
            }
            merged.insert(provider.clone(), id.clone());
        }
    }
    merged
}

fn metadata_values_from_json(metadata: &serde_json::Value, keys: &[&str]) -> Vec<String> {
    let mut values = BTreeMap::<String, String>::new();
    for key in keys {
        if let Some(value) = json_field_case_insensitive(metadata, key) {
            collect_metadata_value(value, &mut values);
        }
    }
    values.into_values().collect()
}

fn first_metadata_value_from_json(metadata: &serde_json::Value, keys: &[&str]) -> Option<String> {
    metadata_values_from_json(metadata, keys).into_iter().next()
}

fn canonical_metadata_uuid_from_json(
    metadata: &serde_json::Value,
    keys: &[&str],
) -> Option<String> {
    first_metadata_value_from_json(metadata, keys).and_then(|value| {
        parse_jellyfin_uuid(&value)
            .ok()
            .map(|uuid| uuid.simple().to_string())
    })
}

fn normalize_metadata_date_for_json(value: &str) -> String {
    if OffsetDateTime::parse(value, &Rfc3339).is_ok() {
        return value.to_string();
    }
    if let Some((date, time)) = value.split_once(' ')
        && date.len() == 10
        && time.len() >= 8
        && date.chars().all(|ch| ch.is_ascii_digit() || ch == '-')
        && time
            .chars()
            .take(8)
            .all(|ch| ch.is_ascii_digit() || ch == ':')
    {
        return format!("{date}T{}Z", &time[..8]);
    }
    if let Some(value) = value.strip_suffix(" +00:00:00")
        && let Some((date, time)) = value.split_once(' ')
    {
        return format!("{date}T{time}Z");
    }
    value.to_string()
}

fn first_metadata_number_from_json(metadata: &serde_json::Value, keys: &[&str]) -> Option<f64> {
    for key in keys {
        if let Some(value) = json_field_case_insensitive(metadata, key) {
            if let Some(value) = value.as_f64() {
                return Some(value);
            }
            if let Some(value) = value.as_str().and_then(|value| value.parse::<f64>().ok()) {
                return Some(value);
            }
        }
    }
    None
}

fn first_metadata_i32_from_json(metadata: &serde_json::Value, keys: &[&str]) -> Option<i32> {
    for key in keys {
        if let Some(value) = json_field_case_insensitive(metadata, key) {
            if let Some(value) = value.as_i64().and_then(|value| i32::try_from(value).ok()) {
                return Some(value);
            }
            if let Some(value) = value.as_str().and_then(|value| value.parse::<i32>().ok()) {
                return Some(value);
            }
        }
    }
    None
}

fn metadata_name_id_items(item_type: &str, names: &[String]) -> Vec<serde_json::Value> {
    names
        .iter()
        .map(|name| {
            serde_json::json!({
                "Name": name,
                "Id": stable_entity_id(item_type, name)
            })
        })
        .collect()
}

fn metadata_people_items(names: &[String]) -> Vec<serde_json::Value> {
    names
        .iter()
        .map(|name| {
            serde_json::json!({
                "Name": name,
                "Id": stable_entity_id("Person", name),
                "Role": null,
                "Type": "Person",
                "PrimaryImageTag": null
            })
        })
        .collect()
}

fn selected_subtitle_stream_index(
    playback: Option<&PlaybackState>,
    default_subtitle_stream_index: Option<i64>,
) -> serde_json::Value {
    match playback.and_then(|state| state.subtitle_stream_index) {
        Some(index) if index < 0 => serde_json::Value::Null,
        Some(index) => serde_json::json!(index),
        None => serde_json::json!(default_subtitle_stream_index),
    }
}

fn transcode_temp_root() -> PathBuf {
    static TRANSCODE_ROOT: OnceLock<PathBuf> = OnceLock::new();
    TRANSCODE_ROOT
        .get_or_init(|| {
            std::env::var_os("JELLYRIN_TRANSCODE_DIR")
                .filter(|value| !value.is_empty())
                .map(PathBuf::from)
                .filter(|path| path.is_absolute())
                .unwrap_or_else(|| std::env::temp_dir().join("jellyrin").join("transcodes"))
        })
        .clone()
}

fn hls_master_url(
    media_type: &str,
    item_id: &str,
    play_session_id: &str,
    access_token: &str,
) -> String {
    if media_type == "Audio" {
        format!(
            "/Audio/{item_id}/master.m3u8?PlaySessionId={play_session_id}&api_key={access_token}"
        )
    } else {
        format!(
            "/Videos/{item_id}/master.m3u8?PlaySessionId={play_session_id}&api_key={access_token}"
        )
    }
}

async fn cleanup_hls_transcode_files(output_path: &str) -> bool {
    let session_dir = HlsTranscodeLayout::from_media_playlist_path(output_path).session_dir;
    cleanup_hls_transcode_dir(&session_dir).await
}

async fn cleanup_hls_transcode_dir(session_dir: &FsPath) -> bool {
    cleanup_hls_transcode_dir_in_root(&transcode_temp_root(), session_dir).await
}

async fn cleanup_hls_transcode_dir_in_root(root: &FsPath, session_dir: &FsPath) -> bool {
    let session_dir = match validate_hls_cleanup_dir(root, session_dir).await {
        HlsCleanupDirValidation::Safe(session_dir) => session_dir,
        HlsCleanupDirValidation::Missing => return false,
        HlsCleanupDirValidation::Unsafe => {
            tracing::warn!("refused unsafe HLS transcode directory cleanup");
            return false;
        }
    };
    match tokio::fs::remove_dir_all(&session_dir).await {
        Ok(()) => true,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => false,
        Err(error) => {
            tracing::warn!(
                path = %session_dir.display(),
                %error,
                "failed to remove HLS transcode directory"
            );
            false
        }
    }
}

#[derive(Debug, PartialEq, Eq)]
enum HlsCleanupDirValidation {
    Safe(PathBuf),
    Missing,
    Unsafe,
}

async fn validate_hls_cleanup_dir(root: &FsPath, candidate: &FsPath) -> HlsCleanupDirValidation {
    if root.as_os_str().is_empty()
        || candidate.as_os_str().is_empty()
        || candidate
            .components()
            .any(|component| matches!(component, std::path::Component::ParentDir))
    {
        return HlsCleanupDirValidation::Unsafe;
    }

    let Ok(relative) = candidate.strip_prefix(root) else {
        return HlsCleanupDirValidation::Unsafe;
    };
    let mut components = relative.components();
    let Some(component) = components.next() else {
        return HlsCleanupDirValidation::Unsafe;
    };
    if !matches!(component, std::path::Component::Normal(_)) || components.next().is_some() {
        return HlsCleanupDirValidation::Unsafe;
    }

    let root_metadata = match tokio::fs::symlink_metadata(root).await {
        Ok(metadata) => metadata,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            return HlsCleanupDirValidation::Missing;
        }
        Err(_) => return HlsCleanupDirValidation::Unsafe,
    };
    if root_metadata.file_type().is_symlink() || !root_metadata.is_dir() {
        return HlsCleanupDirValidation::Unsafe;
    }
    let candidate_metadata = match tokio::fs::symlink_metadata(candidate).await {
        Ok(metadata) => metadata,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            return HlsCleanupDirValidation::Missing;
        }
        Err(_) => return HlsCleanupDirValidation::Unsafe,
    };
    if candidate_metadata.file_type().is_symlink() || !candidate_metadata.is_dir() {
        return HlsCleanupDirValidation::Unsafe;
    }

    let Ok(canonical_root) = tokio::fs::canonicalize(root).await else {
        return HlsCleanupDirValidation::Unsafe;
    };
    let Ok(canonical_candidate) = tokio::fs::canonicalize(candidate).await else {
        return HlsCleanupDirValidation::Unsafe;
    };
    if canonical_candidate.parent() != Some(canonical_root.as_path()) {
        return HlsCleanupDirValidation::Unsafe;
    }
    HlsCleanupDirValidation::Safe(candidate.to_path_buf())
}

fn first_stream_index(media_streams: &[serde_json::Value], stream_type: &str) -> Option<i64> {
    media_streams.iter().find_map(|stream| {
        let stream = stream.as_object()?;
        let type_name = stream.get("Type").and_then(serde_json::Value::as_str)?;
        if !type_name.eq_ignore_ascii_case(stream_type) {
            return None;
        }
        stream.get("Index").and_then(json_value_i64)
    })
}

fn default_audio_stream_index(media_streams: &[serde_json::Value]) -> Option<i64> {
    let mut first_audio_index = None;
    for stream in media_streams {
        let Some(stream) = stream.as_object() else {
            continue;
        };
        let Some(type_name) = stream.get("Type").and_then(serde_json::Value::as_str) else {
            continue;
        };
        if !type_name.eq_ignore_ascii_case("Audio") {
            continue;
        }

        let Some(index) = stream.get("Index").and_then(json_value_i64) else {
            continue;
        };
        if first_audio_index.is_none() {
            first_audio_index = Some(index);
        }
        if stream
            .get("IsDefault")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false)
        {
            return Some(index);
        }
    }

    first_audio_index
}

fn default_subtitle_stream_index(media_streams: &[serde_json::Value]) -> Option<i64> {
    media_streams.iter().find_map(|stream| {
        let stream = stream.as_object()?;
        let type_name = stream.get("Type").and_then(serde_json::Value::as_str)?;
        if !type_name.eq_ignore_ascii_case("Subtitle") {
            return None;
        }
        if !stream
            .get("IsDefault")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false)
        {
            return None;
        }

        stream.get("Index").and_then(json_value_i64)
    })
}

fn json_value_i64(value: &serde_json::Value) -> Option<i64> {
    match value {
        serde_json::Value::Number(value) => value.as_i64(),
        serde_json::Value::String(value) => value.parse::<i64>().ok(),
        _ => None,
    }
}

async fn item_counts_json(
    db: &Database,
    items: &[MediaItem],
) -> Result<serde_json::Value, ApiError> {
    let mut movie_count = 0;
    let mut series_count = 0;
    let mut synthetic_series = BTreeSet::new();
    let mut episode_count = 0;
    let mut song_count = 0;
    let mut album_count = 0;
    let mut book_count = 0;
    let mut music_video_count = 0;

    for item in items {
        match media_item_type(item) {
            "Movie" => movie_count += 1,
            "Series" => series_count += 1,
            "Episode" => {
                episode_count += 1;
                synthetic_series.insert(tv_episode_series_key(item));
            }
            "Audio" => song_count += 1,
            "MusicAlbum" => album_count += 1,
            "Book" => book_count += 1,
            "MusicVideo" => music_video_count += 1,
            _ => {}
        }
    }
    series_count += synthetic_series.len();
    let metadata_counts = item_count_metadata_values(db, items).await?;
    let artist_count = metadata_counts.artist_values.len();
    album_count += metadata_counts.album_values.len();
    let trailer_count = metadata_counts.trailer_count;

    Ok(serde_json::json!({
        "MovieCount": movie_count,
        "SeriesCount": series_count,
        "EpisodeCount": episode_count,
        "ArtistCount": artist_count,
        "ProgramCount": 0,
        "TrailerCount": trailer_count,
        "SongCount": song_count,
        "AlbumCount": album_count,
        "MusicVideoCount": music_video_count,
        "BoxSetCount": 0,
        "BookCount": book_count,
        "ItemCount": items.len(),
    }))
}

#[derive(Default)]
struct ItemCountMetadataValues {
    album_values: BTreeMap<String, String>,
    artist_values: BTreeMap<String, String>,
    trailer_count: usize,
}

async fn item_count_metadata_values(
    db: &Database,
    items: &[MediaItem],
) -> Result<ItemCountMetadataValues, ApiError> {
    if items.is_empty() {
        return Ok(ItemCountMetadataValues::default());
    }
    let item_ids = items.iter().map(|item| item.id).collect::<HashSet<_>>();
    let mut values = ItemCountMetadataValues::default();
    for metadata in db.media_item_metadata_by_item_ids(&item_ids).await? {
        collect_item_count_metadata_value(&metadata, "Album", &mut values.album_values);
        collect_item_count_metadata_value(&metadata, "AlbumName", &mut values.album_values);
        collect_item_count_metadata_value(&metadata, "Artists", &mut values.artist_values);
        collect_item_count_metadata_value(&metadata, "AlbumArtists", &mut values.artist_values);
        values.trailer_count += metadata_remote_trailer_count(&metadata.payload);
    }
    Ok(values)
}

fn metadata_remote_trailer_count(metadata: &serde_json::Value) -> usize {
    ["RemoteTrailers", "Trailers"]
        .into_iter()
        .filter_map(|key| json_field_case_insensitive(metadata, key))
        .map(count_remote_trailer_values)
        .sum()
}

fn count_remote_trailer_values(value: &serde_json::Value) -> usize {
    match value {
        serde_json::Value::Array(values) => values.iter().map(count_remote_trailer_values).sum(),
        serde_json::Value::String(url) => usize::from(non_empty_json_string(url).is_some()),
        serde_json::Value::Object(object) => object
            .get("Url")
            .or_else(|| object.get("url"))
            .or_else(|| object.get("Path"))
            .or_else(|| object.get("path"))
            .and_then(serde_json::Value::as_str)
            .and_then(non_empty_json_string)
            .map(|_| 1)
            .unwrap_or(0),
        _ => 0,
    }
}

fn collect_item_count_metadata_value(
    metadata: &MediaItemMetadata,
    key: &str,
    values: &mut BTreeMap<String, String>,
) {
    if let Some(value) = metadata.payload.get(key) {
        collect_metadata_value(value, values);
    }
}

fn collect_item_filter_staff_value(
    metadata: &MediaItemMetadata,
    key: &str,
    values: &mut BTreeMap<String, serde_json::Value>,
) {
    let Some(value) = metadata.payload.get(key) else {
        return;
    };
    let mut names = BTreeMap::<String, String>::new();
    collect_metadata_value(value, &mut names);
    for name in names.into_values() {
        let id = stable_entity_id("Person", &name);
        values.entry(name.to_ascii_lowercase()).or_insert_with(|| {
            serde_json::json!({
                "Name": name,
                "Id": id
            })
        });
    }
}

fn media_item_path(item: &MediaItem) -> &FsPath {
    FsPath::new(&item.path)
}

fn is_xtream_remote_media(metadata: Option<&serde_json::Value>) -> bool {
    metadata
        .and_then(|metadata| json_string_field(metadata, "Provider"))
        .is_some_and(|provider| provider.eq_ignore_ascii_case("xtream"))
        && metadata.is_some_and(|metadata| {
            metadata
                .get("RemoteSourceRef")
                .and_then(live_tv_xtream::xtream_remote_source_ref)
                .is_some()
                || xtream_legacy_remote_source_url(Some(metadata)).is_some()
        })
}

/// Per-item async locks that serialize remote ffprobe so that concurrent detail
/// or playback-info opens of the same Xtream VOD item probe the network once,
/// instead of all racing (thundering herd) before the first probe persists.
static XTREAM_PROBE_LOCKS: std::sync::OnceLock<std::sync::Mutex<WeakKeyedLockRegistry<Uuid>>> =
    std::sync::OnceLock::new();
static PLUGIN_VOD_RUNTIME_PROBE_LOCKS: std::sync::OnceLock<
    std::sync::Mutex<WeakKeyedLockRegistry<Uuid>>,
> = std::sync::OnceLock::new();
#[cfg(test)]
struct PluginVodRuntimeProbeAfterPublishHook {
    reached: oneshot::Sender<()>,
    resume: oneshot::Receiver<()>,
}
#[cfg(test)]
static PLUGIN_VOD_RUNTIME_PROBE_AFTER_PUBLISH_HOOKS: OnceLock<
    StdMutex<HashMap<Uuid, PluginVodRuntimeProbeAfterPublishHook>>,
> = OnceLock::new();
static LIVE_TV_PROBE_LOCKS: std::sync::OnceLock<std::sync::Mutex<WeakKeyedLockRegistry<String>>> =
    std::sync::OnceLock::new();
static XTREAM_PROBE_LIMITER: OnceLock<Arc<tokio::sync::Semaphore>> = OnceLock::new();
static XTREAM_PROBE_WAIT_QUEUE: OnceLock<Arc<tokio::sync::Semaphore>> = OnceLock::new();
static REMOTE_PROBE_ADMISSION_METRICS: OnceLock<AdmissionMetrics> = OnceLock::new();

fn xtream_probe_lock_for(item_id: Uuid) -> std::sync::Arc<tokio::sync::Mutex<()>> {
    let registry = XTREAM_PROBE_LOCKS.get_or_init(|| {
        std::sync::Mutex::new(WeakKeyedLockRegistry::new(KEYED_LOCK_REGISTRY_MAX_ENTRIES))
    });
    let mut guard = registry
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    guard.lock_for(item_id)
}

fn plugin_vod_runtime_probe_lock_for(item_id: Uuid) -> std::sync::Arc<tokio::sync::Mutex<()>> {
    let registry = PLUGIN_VOD_RUNTIME_PROBE_LOCKS.get_or_init(|| {
        std::sync::Mutex::new(WeakKeyedLockRegistry::new(KEYED_LOCK_REGISTRY_MAX_ENTRIES))
    });
    registry
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .lock_for(item_id)
}

#[cfg(test)]
fn install_plugin_vod_runtime_probe_after_publish_hook(
    item_id: Uuid,
) -> (oneshot::Receiver<()>, oneshot::Sender<()>) {
    let (reached_tx, reached_rx) = oneshot::channel();
    let (resume_tx, resume_rx) = oneshot::channel();
    PLUGIN_VOD_RUNTIME_PROBE_AFTER_PUBLISH_HOOKS
        .get_or_init(|| StdMutex::new(HashMap::new()))
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .insert(
            item_id,
            PluginVodRuntimeProbeAfterPublishHook {
                reached: reached_tx,
                resume: resume_rx,
            },
        );
    (reached_rx, resume_tx)
}

#[cfg(test)]
async fn plugin_vod_runtime_probe_after_publish_hook(item_id: Uuid) {
    let hook = PLUGIN_VOD_RUNTIME_PROBE_AFTER_PUBLISH_HOOKS
        .get_or_init(|| StdMutex::new(HashMap::new()))
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .remove(&item_id);
    if let Some(hook) = hook {
        let _ = hook.reached.send(());
        let _ = hook.resume.await;
    }
}

fn live_tv_probe_lock_for(cache_key: String) -> std::sync::Arc<tokio::sync::Mutex<()>> {
    let registry = LIVE_TV_PROBE_LOCKS.get_or_init(|| {
        std::sync::Mutex::new(WeakKeyedLockRegistry::new(KEYED_LOCK_REGISTRY_MAX_ENTRIES))
    });
    registry
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .lock_for(cache_key)
}

fn xtream_probe_limiter() -> &'static Arc<tokio::sync::Semaphore> {
    XTREAM_PROBE_LIMITER.get_or_init(|| {
        let permits = max_remote_probes();
        tracing::info!(permits, "configured remote media probe concurrency");
        Arc::new(tokio::sync::Semaphore::new(permits))
    })
}

fn max_remote_probes_from_value(value: Option<&str>) -> usize {
    value
        .map(str::trim)
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| (1..=16).contains(value))
        .unwrap_or(2)
}

fn max_remote_probes() -> usize {
    static LIMIT: OnceLock<usize> = OnceLock::new();
    *LIMIT.get_or_init(|| {
        max_remote_probes_from_value(std::env::var("JELLYRIN_MAX_REMOTE_PROBES").ok().as_deref())
    })
}

fn max_queued_remote_probes_from_value(value: Option<&str>) -> usize {
    value
        .map(str::trim)
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value <= MAX_QUEUED_REMOTE_PROBES_LIMIT)
        .unwrap_or(DEFAULT_MAX_QUEUED_REMOTE_PROBES)
}

fn max_queued_remote_probes() -> usize {
    static LIMIT: OnceLock<usize> = OnceLock::new();
    *LIMIT.get_or_init(|| {
        let limit = max_queued_remote_probes_from_value(
            std::env::var("JELLYRIN_MAX_QUEUED_REMOTE_PROBES")
                .ok()
                .as_deref(),
        );
        tracing::info!(limit, "configured bounded remote media probe wait queue");
        limit
    })
}

fn xtream_probe_wait_queue() -> &'static Arc<tokio::sync::Semaphore> {
    XTREAM_PROBE_WAIT_QUEUE
        .get_or_init(|| Arc::new(tokio::sync::Semaphore::new(max_queued_remote_probes())))
}

fn xtream_probe_queue_timeout() -> StdDuration {
    static TIMEOUT: OnceLock<StdDuration> = OnceLock::new();
    *TIMEOUT.get_or_init(|| {
        let seconds = std::env::var("JELLYRIN_REMOTE_PROBE_QUEUE_TIMEOUT_SECONDS")
            .ok()
            .and_then(|value| value.parse::<u64>().ok())
            .filter(|value| (1..=120).contains(value))
            .unwrap_or(10);
        StdDuration::from_secs(seconds)
    })
}

fn remote_probe_admission_metrics() -> &'static AdmissionMetrics {
    REMOTE_PROBE_ADMISSION_METRICS.get_or_init(AdmissionMetrics::new)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RemoteProbeAdmissionError {
    CoordinatorClosed,
    WaitQueueClosed,
    WaitQueueFull,
    TimedOut,
}

async fn acquire_remote_probe_capacity_with_queue(
    limiter: Arc<tokio::sync::Semaphore>,
    wait_queue: Arc<tokio::sync::Semaphore>,
    timeout: StdDuration,
) -> Result<tokio::sync::OwnedSemaphorePermit, RemoteProbeAdmissionError> {
    let metrics = remote_probe_admission_metrics();
    match limiter.clone().try_acquire_owned() {
        Ok(permit) => {
            metrics.record_immediate();
            return Ok(permit);
        }
        Err(tokio::sync::TryAcquireError::Closed) => {
            metrics.record_rejected();
            return Err(RemoteProbeAdmissionError::CoordinatorClosed);
        }
        Err(tokio::sync::TryAcquireError::NoPermits) => {}
    }

    let queue_permit = match wait_queue.clone().try_acquire_owned() {
        Ok(permit) => permit,
        Err(tokio::sync::TryAcquireError::Closed) => {
            metrics.record_rejected();
            return Err(RemoteProbeAdmissionError::WaitQueueClosed);
        }
        Err(tokio::sync::TryAcquireError::NoPermits) => {
            // Do not reject a request that raced with a just-completed probe.
            return match limiter.try_acquire_owned() {
                Ok(permit) => {
                    metrics.record_immediate();
                    Ok(permit)
                }
                Err(tokio::sync::TryAcquireError::Closed) => {
                    metrics.record_rejected();
                    Err(RemoteProbeAdmissionError::CoordinatorClosed)
                }
                Err(tokio::sync::TryAcquireError::NoPermits) => {
                    metrics.record_rejected();
                    Err(RemoteProbeAdmissionError::WaitQueueFull)
                }
            };
        }
    };

    let started = StdInstant::now();
    let active_permit = match tokio::time::timeout(timeout, limiter.acquire_owned()).await {
        Ok(Ok(permit)) => {
            metrics.record_queued(started.elapsed());
            Ok(permit)
        }
        Ok(Err(_)) => {
            metrics.record_rejected();
            Err(RemoteProbeAdmissionError::CoordinatorClosed)
        }
        Err(_) => {
            metrics.record_timeout(started.elapsed());
            Err(RemoteProbeAdmissionError::TimedOut)
        }
    };
    // Queue admission accounts only for requests waiting on active capacity.
    // The returned active permit remains alive through ffprobe termination and
    // process reaping in `probe_remote_media_info`.
    drop(queue_permit);
    active_permit
}

