/// Keeps an unguessable loopback relay route alive for exactly as long as its
/// ffprobe/FFmpeg consumer. The registry stores only an internal identifier;
/// provider URLs and credentials are resolved from central configuration for
/// each admitted request and never appear in the child process arguments.
struct InternalRemoteRelayLease {
    token: String,
    url: String,
}

impl InternalRemoteRelayLease {
    fn url(&self) -> &str {
        &self.url
    }
}

impl Drop for InternalRemoteRelayLease {
    fn drop(&mut self) {
        let registry = INTERNAL_REMOTE_RELAYS.get_or_init(|| StdMutex::new(HashMap::new()));
        registry
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .remove(&self.token);
    }
}

fn internal_remote_relay_base(local_address: &str) -> Result<String, ApiError> {
    let address = reqwest::Url::parse(local_address)
        .map_err(|_| ApiError::internal("invalid internal Jellyrin address"))?;
    let port = address
        .port_or_known_default()
        .ok_or_else(|| ApiError::internal("internal Jellyrin address has no port"))?;
    let host = address
        .host_str()
        .ok_or_else(|| ApiError::internal("internal Jellyrin address has no host"))?;
    let loopback = if host.contains(':') {
        "[::1]"
    } else {
        "127.0.0.1"
    };
    Ok(format!("http://{loopback}:{port}"))
}

fn register_internal_remote_relay(
    state: &AppState,
    target: InternalRemoteRelayTarget,
    ttl: StdDuration,
) -> Result<InternalRemoteRelayLease, ApiError> {
    let base = internal_remote_relay_base(&state.local_address)?;
    let now = StdInstant::now();
    let registry = INTERNAL_REMOTE_RELAYS.get_or_init(|| StdMutex::new(HashMap::new()));
    let mut registry = registry
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    registry.retain(|_, entry| entry.expires_at > now);
    if registry.len() >= INTERNAL_REMOTE_RELAY_MAX_ENTRIES {
        return Err(ApiError::service_unavailable(
            "internal remote media relay capacity is exhausted",
        ));
    }

    let token = loop {
        let mut random = [0_u8; INTERNAL_REMOTE_RELAY_TOKEN_BYTES];
        OsRng.fill_bytes(&mut random);
        let token = general_purpose::URL_SAFE_NO_PAD.encode(random);
        if !registry.contains_key(&token) {
            break token;
        }
    };
    registry.insert(
        token.clone(),
        InternalRemoteRelayEntry {
            target,
            expires_at: now + ttl,
            plugin_vod_playback_cache: Arc::new(Mutex::new(None)),
        },
    );
    Ok(InternalRemoteRelayLease {
        url: format!("{base}/.jellyrin/internal/remote-media/{token}"),
        token,
    })
}

#[cfg(test)]
fn internal_remote_relay_target(token: &str) -> Option<InternalRemoteRelayTarget> {
    internal_remote_relay_lookup(token).map(|lookup| lookup.target)
}

fn internal_remote_relay_lookup(token: &str) -> Option<InternalRemoteRelayLookup> {
    if token.len() != 43
        || !token
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_'))
    {
        return None;
    }
    let now = StdInstant::now();
    let registry = INTERNAL_REMOTE_RELAYS.get_or_init(|| StdMutex::new(HashMap::new()));
    let mut registry = registry
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    registry.retain(|_, entry| entry.expires_at > now);
    registry.get(token).map(|entry| InternalRemoteRelayLookup {
        target: entry.target.clone(),
        plugin_vod_playback_cache: Arc::clone(&entry.plugin_vod_playback_cache),
    })
}

/// Recovers a finite runtime from the protected media only when catalogue and JIT metadata both
/// omitted it. FFprobe receives an unguessable loopback URL; the relay resolves the provider URL
/// inside Jellyrin for each bounded request, so signed addresses never enter argv, logs or the DB.
async fn ensure_plugin_vod_media_runtime(
    state: &AppState,
    item: MediaItem,
    metadata: &mut serde_json::Value,
) -> Result<MediaItem, ApiError> {
    if !matches!(media_item_type(&item), "Movie" | "Episode") {
        return Ok(item);
    }
    if bounded_plugin_vod_runtime_ticks(item.runtime_ticks).is_some()
        || plugin_vod_media_runtime_probe_is_fresh(metadata)
    {
        return Ok(item);
    }

    let lock = plugin_vod_runtime_probe_lock_for(item.id);
    let _guard = lock.lock().await;
    let mut current = state
        .db
        .media_item_by_id_visible(item.id)
        .await?
        .ok_or_else(|| ApiError::not_found("VOD metadata item is unavailable"))?;
    let current_metadata = metadata_payload_for_item(&state.db, item.id).await?;
    if bounded_plugin_vod_runtime_ticks(current.runtime_ticks).is_some()
        || plugin_vod_media_runtime_probe_is_fresh(&current_metadata)
    {
        *metadata = current_metadata;
        return Ok(current);
    }

    let remote_permit = match acquire_remote_probe_capacity_with_queue(
        xtream_probe_limiter().clone(),
        xtream_probe_wait_queue().clone(),
        xtream_probe_queue_timeout(),
    )
    .await
    {
        Ok(permit) => permit,
        Err(_) => {
            record_ffprobe_capacity_unavailable();
            return Ok(current);
        }
    };
    let process_permit = match acquire_multimedia_probe().await {
        Ok(permit) => permit,
        Err(_) => {
            record_ffprobe_capacity_unavailable();
            drop(remote_permit);
            return Ok(current);
        }
    };
    let relay = register_internal_remote_relay(
        state,
        InternalRemoteRelayTarget::MediaItem {
            item_id: item.id,
            user_context: None,
        },
        INTERNAL_REMOTE_RELAY_PROBE_TTL,
    )?;
    let media_info =
        probe_remote_media_info_admitted(relay.url(), &item.media_type, process_permit).await;
    drop(relay);
    drop(remote_permit);

    let runtime_ticks = bounded_plugin_vod_runtime_ticks(media_info.runtime_ticks);
    let outcome = if runtime_ticks.is_some() {
        "Complete"
    } else if media_info.bitrate.is_some()
        || media_info.width.is_some()
        || media_info.height.is_some()
        || !media_info.media_streams.is_empty()
    {
        "Missing"
    } else {
        "Failed"
    };
    let marker =
        plugin_vod_media_runtime_probe_marker(outcome, OffsetDateTime::now_utc().unix_timestamp());
    state
        .db
        .publish_plugin_vod_runtime_probe(current.id, runtime_ticks, marker)
        .await?;
    #[cfg(test)]
    plugin_vod_runtime_probe_after_publish_hook(current.id).await;
    let published = state
        .db
        .media_item_with_metadata_by_id_visible(current.id)
        .await?
        .ok_or_else(|| ApiError::not_found("VOD metadata item is unavailable"))?;
    current = published.item;
    *metadata = published.metadata;
    tracing::info!(outcome, "plugin VOD bounded media runtime probe completed");
    Ok(current)
}

fn xtream_remote_source_ref(metadata: &serde_json::Value) -> Option<&serde_json::Value> {
    metadata
        .get("RemoteSourceRef")
        .filter(|value| live_tv_xtream::xtream_remote_source_ref(value).is_some())
}

fn xtream_remote_source_revision(metadata: &serde_json::Value) -> Option<String> {
    let source_identity = if let Some(reference) = xtream_remote_source_ref(metadata) {
        serde_json::to_string(reference).ok()?
    } else {
        xtream_legacy_remote_source_url(Some(metadata))?
    };
    Some(stable_entity_id(
        "XtreamRemoteSourceRevision",
        &source_identity,
    ))
}

fn resolved_xtream_remote_source_revision(
    metadata: &serde_json::Value,
    tuner_config: &serde_json::Value,
    source_url: &str,
) -> Option<String> {
    let reference = xtream_remote_source_ref(metadata)?;
    let reference = serde_json::to_string(reference).ok()?;
    let configuration_revision = json_string_field(tuner_config, "JellyrinConfigurationRevision")
        .unwrap_or_else(|| {
            static PROCESS_NONCE: OnceLock<String> = OnceLock::new();
            let nonce = PROCESS_NONCE.get_or_init(|| Uuid::new_v4().simple().to_string());
            stable_entity_id(
                "XtreamUnversionedConfiguration",
                &format!("{nonce}:{source_url}"),
            )
        });
    Some(stable_entity_id(
        "XtreamRemoteSourceRevision",
        &format!("{reference}:{configuration_revision}"),
    ))
}

async fn resolve_xtream_remote_source_with_revision(
    db: &Database,
    metadata: &serde_json::Value,
) -> Result<Option<ResolvedXtreamSource>, ApiError> {
    if let Some(reference_value) = xtream_remote_source_ref(metadata) {
        let reference = live_tv_xtream::xtream_remote_source_ref(reference_value)
            .ok_or_else(|| ApiError::service_unavailable("remote media reference is invalid"))?;
        let persisted_tuner_config = db
            .live_tv_tuner_configuration_by_id(&reference.tuner_id)
            .await?
            .ok_or_else(|| ApiError::service_unavailable("remote media tuner is unavailable"))?;
        let tuner_config = db
            .resolve_provider_configuration(&persisted_tuner_config)
            .await
            .map_err(|_| {
                ApiError::service_unavailable("remote media tuner credentials are unavailable")
            })?;
        let source_url = live_tv_xtream::resolve_remote_source_ref(&tuner_config, reference_value)
            .ok_or_else(|| {
                ApiError::service_unavailable("remote media reference could not be resolved")
            })?;
        let source_revision =
            resolved_xtream_remote_source_revision(metadata, &tuner_config, &source_url)
                .ok_or_else(|| {
                    ApiError::service_unavailable("remote media reference is invalid")
                })?;
        return Ok(Some(ResolvedXtreamSource {
            source_url,
            source_revision,
        }));
    }
    let Some(source_url) = xtream_legacy_remote_source_url(Some(metadata)) else {
        return Ok(None);
    };
    let source_revision = xtream_remote_source_revision(metadata)
        .ok_or_else(|| ApiError::service_unavailable("remote media reference is invalid"))?;
    Ok(Some(ResolvedXtreamSource {
        source_url,
        source_revision,
    }))
}

async fn resolve_xtream_remote_source(
    db: &Database,
    metadata: &serde_json::Value,
) -> Result<Option<String>, ApiError> {
    Ok(resolve_xtream_remote_source_with_revision(db, metadata)
        .await?
        .map(|resolved| resolved.source_url))
}

const LIVE_TV_STREAM_PROBE_VERSION: i16 = 1;

fn live_tv_probe_source_revision(
    channel: &serde_json::Value,
    tuner_configuration: &serde_json::Value,
) -> Option<String> {
    let provider_reference = json_string_field(channel, "ProviderReference")
        .or_else(|| json_string_field(channel, "Path"))?;
    let configuration_revision =
        json_string_field(tuner_configuration, "JellyrinConfigurationRevision")
            .unwrap_or_else(|| "unversioned".to_string());
    let provider_type = json_string_field(channel, "ProviderType").unwrap_or_default();
    Some(stable_entity_id(
        "LiveTvStreamProbe",
        &format!(
            "v{LIVE_TV_STREAM_PROBE_VERSION}:{provider_type}:{provider_reference}:{configuration_revision}"
        ),
    ))
}

fn expand_live_tv_teletext_streams(streams: Vec<serde_json::Value>) -> Vec<serde_json::Value> {
    let mut next_index = streams
        .iter()
        .filter_map(|stream| json_i64_field(stream, "Index"))
        .max()
        .unwrap_or(-1)
        .saturating_add(1);
    let mut expanded = Vec::new();
    for stream in streams.into_iter().take(32) {
        let is_teletext = json_string_field(&stream, "Codec")
            .is_some_and(|codec| codec.eq_ignore_ascii_case("dvb_teletext"));
        let services = stream
            .get("TeletextServices")
            .and_then(serde_json::Value::as_array);
        if !is_teletext || services.is_none_or(Vec::is_empty) {
            expanded.push(stream);
            continue;
        }
        let source_index = json_i64_field(&stream, "Index").unwrap_or(-1);
        for service in services.into_iter().flatten().take(16) {
            let Some(page) =
                json_i64_field(service, "Page").filter(|page| (100..=899).contains(page))
            else {
                continue;
            };
            let language = json_string_field(service, "Language").unwrap_or_else(|| "und".into());
            let hearing_impaired = json_bool_field(service, "IsHearingImpaired").unwrap_or(false);
            expanded.push(normalize_media_stream(serde_json::json!({
                "Codec": "webvtt",
                "Language": language,
                "Title": format!("Teletext {page}"),
                "DisplayTitle": format!("{} - Teletext {page}", language_display_name(Some(&language)).unwrap_or(language)),
                "Type": "Subtitle",
                "Index": next_index,
                "JellyrinSourceStreamIndex": source_index,
                "JellyrinTeletextPage": page,
                "IsDefault": false,
                "IsForced": false,
                "IsHearingImpaired": hearing_impaired,
                "IsExternal": false,
                "IsTextSubtitleStream": true,
                "SupportsExternalStream": false
            })));
            next_index = next_index.saturating_add(1);
        }
    }
    expanded.truncate(32);
    expanded
}

#[cfg(test)]
mod live_tv_teletext_contract_tests {
    use super::*;

    #[test]
    fn expands_one_dvb_pid_into_selectable_language_pages() {
        let streams = expand_live_tv_teletext_streams(vec![
            serde_json::json!({"Type":"Video","Codec":"h264","Index":0}),
            serde_json::json!({"Type":"Audio","Codec":"aac","Index":1}),
            serde_json::json!({
                "Type":"Subtitle",
                "Codec":"dvb_teletext",
                "Index":2,
                "TeletextServices":[
                    {"Page":801,"Language":"spa","IsHearingImpaired":false},
                    {"Page":802,"Language":"eng","IsHearingImpaired":false}
                ]
            }),
        ]);
        let subtitles = streams
            .iter()
            .filter(|stream| json_string_field(stream, "Type").as_deref() == Some("Subtitle"))
            .collect::<Vec<_>>();
        assert_eq!(subtitles.len(), 2);
        assert_eq!(
            json_i64_field(subtitles[0], "JellyrinSourceStreamIndex"),
            Some(2)
        );
        assert_eq!(
            json_i64_field(subtitles[0], "JellyrinTeletextPage"),
            Some(801)
        );
        assert_eq!(live_tv_subtitle_source_index(&streams, Some(3)), Some(2));
        assert_eq!(live_tv_subtitle_teletext_page(&streams, Some(3)), Some(801));
        assert_eq!(live_tv_subtitle_teletext_page(&streams, Some(4)), Some(802));
    }
}

async fn ensure_live_tv_stream_probe(
    state: &AppState,
    mut channel: serde_json::Value,
) -> Result<serde_json::Value, ApiError> {
    if !live_tv_channel_uses_opaque_provider(&channel) {
        return Ok(channel);
    }
    let channel_id = live_tv_channel_playback_id(&channel)
        .or_else(|| json_string_field(&channel, "Id"))
        .ok_or_else(|| ApiError::not_found("Live TV item not found"))?;
    let tuner_id = json_string_field(&channel, "TunerHostId")
        .ok_or_else(|| ApiError::service_unavailable("Live TV tuner is unavailable"))?;
    let remote_id = json_string_field(&channel, "RemoteId").unwrap_or_else(|| channel_id.clone());
    let tuner_configuration = state
        .db
        .live_tv_tuner_configuration_by_id(&tuner_id)
        .await?
        .ok_or_else(|| ApiError::service_unavailable("Live TV tuner is unavailable"))?;
    let source_revision = live_tv_probe_source_revision(&channel, &tuner_configuration)
        .ok_or_else(|| ApiError::service_unavailable("Live TV source identity is unavailable"))?;
    let now = OffsetDateTime::now_utc();
    if let Some(probe) = state
        .db
        .live_tv_stream_probe(
            &channel_id,
            &source_revision,
            LIVE_TV_STREAM_PROBE_VERSION,
            now,
        )
        .await?
    {
        channel["MediaStreams"] = probe.streams;
        return Ok(channel);
    }

    let lock = live_tv_probe_lock_for(format!("{channel_id}:{source_revision}"));
    let _guard = lock.lock().await;
    let now = OffsetDateTime::now_utc();
    if let Some(probe) = state
        .db
        .live_tv_stream_probe(
            &channel_id,
            &source_revision,
            LIVE_TV_STREAM_PROBE_VERSION,
            now,
        )
        .await?
    {
        channel["MediaStreams"] = probe.streams;
        return Ok(channel);
    }

    let remote_permit = match acquire_remote_probe_capacity_with_queue(
        xtream_probe_limiter().clone(),
        xtream_probe_wait_queue().clone(),
        xtream_probe_queue_timeout(),
    )
    .await
    {
        Ok(permit) => permit,
        Err(_) => return Ok(channel),
    };
    let process_permit = match acquire_multimedia_probe().await {
        Ok(permit) => permit,
        Err(_) => return Ok(channel),
    };
    let relay = register_internal_remote_relay(
        state,
        InternalRemoteRelayTarget::LiveTvChannel {
            channel_id: channel_id.clone(),
            user_context: None,
        },
        INTERNAL_REMOTE_RELAY_PROBE_TTL,
    )?;
    let observed_at = OffsetDateTime::now_utc();
    let media_info = probe_remote_media_info_admitted(relay.url(), "Video", process_permit).await;
    drop(relay);
    drop(remote_permit);
    let completed_at = OffsetDateTime::now_utc();
    let streams = expand_live_tv_teletext_streams(media_info.media_streams);
    let has_probe_data = media_info.runtime_ticks.is_some()
        || media_info.bitrate.is_some()
        || media_info.width.is_some()
        || media_info.height.is_some()
        || !streams.is_empty();
    let outcome = if !has_probe_data {
        LiveTvStreamProbeOutcome::Failed
    } else if streams.iter().any(|stream| {
        json_string_field(stream, "Type").is_some_and(|kind| kind.eq_ignore_ascii_case("Subtitle"))
    }) {
        LiveTvStreamProbeOutcome::Tracks
    } else {
        LiveTvStreamProbeOutcome::Empty
    };
    let ttl = match outcome {
        LiveTvStreamProbeOutcome::Tracks => Duration::minutes(30),
        LiveTvStreamProbeOutcome::Empty => Duration::minutes(5),
        LiveTvStreamProbeOutcome::Failed | LiveTvStreamProbeOutcome::Unsupported => {
            Duration::minutes(1)
        }
    };
    state
        .db
        .upsert_live_tv_stream_probe(LiveTvStreamProbeUpsert {
            channel_id,
            tuner_id,
            remote_id,
            source_revision,
            probe_version: LIVE_TV_STREAM_PROBE_VERSION,
            outcome,
            streams: serde_json::Value::Array(streams.clone()),
            observed_at,
            completed_at,
            expires_at: completed_at + ttl,
        })
        .await?;
    channel["MediaStreams"] = serde_json::Value::Array(streams);
    Ok(channel)
}

async fn ensure_xtream_remote_media_info(
    state: &AppState,
    item: MediaItem,
    metadata: &mut serde_json::Value,
) -> Result<ResolvedXtreamMedia, ApiError> {
    let db = &state.db;
    ensure_xtream_vod_metadata(state, &item, metadata).await?;
    let mut resolved_source = resolve_xtream_remote_source_with_revision(db, metadata)
        .await?
        .ok_or_else(|| ApiError::service_unavailable("remote media source unavailable"))?;
    if xtream_remote_media_probe_current(metadata, &resolved_source.source_revision) {
        return Ok(ResolvedXtreamMedia { item });
    }

    // Serialize concurrent probes of the same item.
    let lock = xtream_probe_lock_for(item.id);
    let _probe_guard = lock.lock().await;

    // Double-checked locking: another caller may have completed the probe while
    // we waited for the lock. Re-read fresh metadata and re-check before probing.
    if let Some(fresh) = db
        .media_item_metadata_by_item_ids(&HashSet::from([item.id]))
        .await?
        .into_iter()
        .next()
        .map(|metadata| metadata.payload)
    {
        resolved_source = resolve_xtream_remote_source_with_revision(db, &fresh)
            .await?
            .ok_or_else(|| ApiError::service_unavailable("remote media source unavailable"))?;
        let probe_is_current =
            xtream_remote_media_probe_current(&fresh, &resolved_source.source_revision);
        *metadata = fresh;
        if probe_is_current {
            return Ok(ResolvedXtreamMedia {
                item: db.media_item_by_id(item.id).await?,
            });
        }
    }

    let remote_probe_permit = match acquire_remote_probe_capacity_with_queue(
        xtream_probe_limiter().clone(),
        xtream_probe_wait_queue().clone(),
        xtream_probe_queue_timeout(),
    )
    .await
    {
        Ok(permit) => permit,
        Err(
            RemoteProbeAdmissionError::CoordinatorClosed
            | RemoteProbeAdmissionError::WaitQueueClosed,
        ) => {
            record_ffprobe_capacity_unavailable();
            return Err(ApiError::service_unavailable(
                "remote media probe coordinator is closed",
            ));
        }
        Err(RemoteProbeAdmissionError::WaitQueueFull) => {
            record_ffprobe_capacity_unavailable();
            tracing::warn!(
                item_id = %item.id.simple(),
                queue_limit = max_queued_remote_probes(),
                "remote media probe wait queue is full"
            );
            return Ok(ResolvedXtreamMedia { item });
        }
        Err(RemoteProbeAdmissionError::TimedOut) => {
            record_ffprobe_capacity_unavailable();
            tracing::warn!(
                item_id = %item.id.simple(),
                timeout_seconds = xtream_probe_queue_timeout().as_secs(),
                "remote media probe queue timed out"
            );
            return Ok(ResolvedXtreamMedia { item });
        }
    };
    let process_probe_permit = match acquire_multimedia_probe().await {
        Ok(permit) => permit,
        Err(error) => {
            record_ffprobe_capacity_unavailable();
            tracing::warn!(%error, "remote media probe process capacity unavailable");
            drop(remote_probe_permit);
            return Ok(ResolvedXtreamMedia { item });
        }
    };
    let probe_relay = register_internal_remote_relay(
        state,
        InternalRemoteRelayTarget::MediaItem {
            item_id: item.id,
            user_context: None,
        },
        INTERNAL_REMOTE_RELAY_PROBE_TTL,
    )?;
    let media_info =
        probe_remote_media_info_admitted(probe_relay.url(), &item.media_type, process_probe_permit)
            .await;
    drop(probe_relay);
    drop(remote_probe_permit);
    let probe_succeeded = media_info.runtime_ticks.is_some()
        || media_info.bitrate.is_some()
        || media_info.width.is_some()
        || media_info.height.is_some()
        || !media_info.media_streams.is_empty();
    if !probe_succeeded {
        set_xtream_remote_media_probe_metadata(
            metadata,
            &resolved_source.source_revision,
            "Failed",
        );
        MediaService::new(db)
            .update_metadata(item.id, metadata.clone())
            .await?;
        return Ok(ResolvedXtreamMedia { item });
    }

    let streams = if media_info.media_streams.is_empty() {
        item.media_streams.clone()
    } else {
        media_info.media_streams
    };
    set_xtream_remote_media_probe_metadata(metadata, &resolved_source.source_revision, "Complete");
    MediaService::new(db)
        .update_media_info_and_metadata(
            item.id,
            media_info.runtime_ticks.or(item.runtime_ticks),
            media_info.bitrate.or(item.bitrate),
            media_info.width.or(item.width),
            media_info.height.or(item.height),
            streams,
            metadata.clone(),
        )
        .await?;
    Ok(ResolvedXtreamMedia {
        item: db.media_item_by_id(item.id).await?,
    })
}

fn xtream_vod_info_current(metadata: &serde_json::Value, source_revision: &str) -> bool {
    let Some(marker) = metadata
        .get("XtreamVodInfo")
        .and_then(serde_json::Value::as_object)
    else {
        return false;
    };
    if marker.get("Version").and_then(json_value_i64) != Some(XTREAM_VOD_INFO_VERSION)
        || marker
            .get("SourceRevision")
            .and_then(serde_json::Value::as_str)
            != Some(source_revision)
    {
        return false;
    }
    match marker
        .get("Status")
        .and_then(serde_json::Value::as_str)
        .unwrap_or_default()
    {
        "Complete" => true,
        "Failed" => marker
            .get("DateLastFetched")
            .and_then(serde_json::Value::as_str)
            .and_then(|value| OffsetDateTime::parse(value, &Rfc3339).ok())
            .is_some_and(|fetched| {
                OffsetDateTime::now_utc()
                    < fetched + Duration::seconds(XTREAM_VOD_INFO_FAILED_RETRY_AFTER_SECONDS)
            }),
        _ => false,
    }
}

fn set_xtream_vod_info_marker(
    metadata: &mut serde_json::Value,
    source_revision: &str,
    status: &str,
) {
    let Some(object) = metadata.as_object_mut() else {
        return;
    };
    object.insert(
        "XtreamVodInfo".to_string(),
        serde_json::json!({
            "Version": XTREAM_VOD_INFO_VERSION,
            "Status": status,
            "SourceRevision": source_revision,
            "DateLastFetched": format_time_for_json(OffsetDateTime::now_utc()),
        }),
    );
}

fn merge_xtream_vod_metadata(metadata: &mut serde_json::Value, enrichment: serde_json::Value) {
    let Some(target) = metadata.as_object_mut() else {
        return;
    };
    let Some(mut enrichment) = enrichment.as_object().cloned() else {
        return;
    };
    if let Some(provider_ids) = enrichment
        .remove("ProviderIds")
        .and_then(|value| value.as_object().cloned())
    {
        let target_ids = target
            .entry("ProviderIds".to_string())
            .or_insert_with(|| serde_json::json!({}));
        if let Some(target_ids) = target_ids.as_object_mut() {
            target_ids.extend(provider_ids);
        }
    }
    for (key, value) in enrichment {
        let meaningful = match &value {
            serde_json::Value::Null => false,
            serde_json::Value::String(value) => !value.trim().is_empty(),
            serde_json::Value::Array(values) => !values.is_empty(),
            serde_json::Value::Object(values) => !values.is_empty(),
            _ => true,
        };
        if meaningful {
            target.insert(key, value);
        }
    }
}

async fn ensure_xtream_vod_metadata(
    state: &AppState,
    item: &MediaItem,
    metadata: &mut serde_json::Value,
) -> Result<(), ApiError> {
    let Some(reference_value) = xtream_remote_source_ref(metadata) else {
        return Ok(());
    };
    let Some(reference) = live_tv_xtream::xtream_remote_source_ref(reference_value) else {
        return Ok(());
    };
    if reference.kind != "vod" {
        return Ok(());
    }

    let lock = xtream_probe_lock_for(item.id);
    let _guard = lock.lock().await;
    let mut fresh = state
        .db
        .media_item_metadata_by_item_ids(&HashSet::from([item.id]))
        .await?
        .into_iter()
        .next()
        .map(|metadata| metadata.payload)
        .unwrap_or_else(|| metadata.clone());
    let Some(fresh_reference_value) = xtream_remote_source_ref(&fresh) else {
        return Ok(());
    };
    let Some(fresh_reference) = live_tv_xtream::xtream_remote_source_ref(fresh_reference_value)
    else {
        return Ok(());
    };
    if fresh_reference.kind != "vod" {
        return Ok(());
    }
    let persisted_tuner_config = state
        .db
        .live_tv_tuner_configuration_by_id(&fresh_reference.tuner_id)
        .await?
        .ok_or_else(|| ApiError::service_unavailable("remote media tuner is unavailable"))?;
    let tuner_config = state
        .db
        .resolve_provider_configuration(&persisted_tuner_config)
        .await
        .map_err(|_| {
            ApiError::service_unavailable("remote media tuner credentials are unavailable")
        })?;
    let source_url =
        live_tv_xtream::resolve_remote_source_ref(&tuner_config, fresh_reference_value)
            .ok_or_else(|| {
                ApiError::service_unavailable("remote media reference could not be resolved")
            })?;
    let source_revision =
        resolved_xtream_remote_source_revision(&fresh, &tuner_config, &source_url)
            .ok_or_else(|| ApiError::service_unavailable("remote media reference is invalid"))?;
    if xtream_vod_info_current(&fresh, &source_revision) {
        *metadata = fresh;
        return Ok(());
    }

    match live_tv_xtream::fetch_vod_metadata_from_payload(&tuner_config, &fresh_reference.remote_id)
        .await
    {
        Ok(enrichment) => {
            merge_xtream_vod_metadata(&mut fresh, enrichment);
            set_xtream_vod_info_marker(&mut fresh, &source_revision, "Complete");
        }
        Err(error) => {
            tracing::warn!(
                item_id = %item.id.simple(),
                operation = error.operation(),
                "Xtream VOD metadata enrichment failed"
            );
            set_xtream_vod_info_marker(&mut fresh, &source_revision, "Failed");
        }
    }
    MediaService::new(&state.db)
        .update_metadata(item.id, fresh.clone())
        .await?;
    *metadata = fresh;
    Ok(())
}

fn xtream_remote_media_probe_current(metadata: &serde_json::Value, source_revision: &str) -> bool {
    let Some(probe) = metadata
        .get("RemoteMediaProbe")
        .and_then(serde_json::Value::as_object)
    else {
        return false;
    };
    let source_matches = probe
        .get("SourceRevision")
        .and_then(serde_json::Value::as_str)
        .is_some_and(|value| value == source_revision)
        || probe
            .get("SourceUrl")
            .and_then(serde_json::Value::as_str)
            .zip(xtream_legacy_remote_source_url(Some(metadata)).as_deref())
            .is_some_and(|(recorded, legacy)| {
                recorded == legacy
                    && xtream_remote_source_revision(metadata).as_deref() == Some(source_revision)
            });
    if !source_matches {
        return false;
    }

    let status = probe
        .get("Status")
        .and_then(serde_json::Value::as_str)
        .unwrap_or_default();
    if status == "Complete" {
        return true;
    }
    if status != "Failed" {
        return false;
    }

    let Some(date_last_probed) = probe
        .get("DateLastProbed")
        .and_then(serde_json::Value::as_str)
        .and_then(|value| OffsetDateTime::parse(value, &Rfc3339).ok())
    else {
        return false;
    };
    let retry_after = Duration::seconds(XTREAM_REMOTE_PROBE_FAILED_RETRY_AFTER_SECONDS);
    OffsetDateTime::now_utc() < date_last_probed + retry_after
}

fn set_xtream_remote_media_probe_metadata(
    metadata: &mut serde_json::Value,
    source_revision: &str,
    status: &str,
) {
    let Some(object) = metadata.as_object_mut() else {
        return;
    };
    object.insert(
        "RemoteMediaProbe".to_string(),
        serde_json::json!({
            "ProbeVersion": 1,
            "Status": status,
            "SourceRevision": source_revision,
            "DateLastProbed": format_time_for_json(OffsetDateTime::now_utc()),
        }),
    );
}

fn is_xtream_virtual_item(item: &MediaItem) -> bool {
    item.path.starts_with("xtream://")
}

fn xtream_legacy_remote_source_url(metadata: Option<&serde_json::Value>) -> Option<String> {
    metadata.and_then(|metadata| {
        json_string_field(metadata, "RemoteSourceUrl")
            .filter(|url| url.starts_with("http://") || url.starts_with("https://"))
    })
}

pub(crate) struct MediaProcessInput {
    path: String,
    _relay: Option<InternalRemoteRelayLease>,
}

impl MediaProcessInput {
    pub(crate) fn as_str(&self) -> &str {
        &self.path
    }
}

pub(crate) async fn media_process_input(
    state: &AppState,
    item: &MediaItem,
    relay_ttl: StdDuration,
) -> Result<MediaProcessInput, ApiError> {
    if !is_xtream_virtual_item(item) && !is_plugin_vod_virtual_item(item) {
        return Ok(MediaProcessInput {
            path: item.path.clone(),
            _relay: None,
        });
    }
    let metadata_by_item = media_metadata_by_item_id(&state.db, HashSet::from([item.id])).await?;
    let metadata = metadata_by_item
        .get(&item.id)
        .ok_or_else(|| ApiError::service_unavailable("remote media metadata unavailable"))?;
    if !is_xtream_remote_media(Some(metadata)) && !is_plugin_vod_remote_media(Some(metadata)) {
        return Err(ApiError::service_unavailable(
            "remote media reference unavailable",
        ));
    }
    let relay = register_internal_remote_relay(
        state,
        InternalRemoteRelayTarget::MediaItem {
            item_id: item.id,
            user_context: None,
        },
        relay_ttl,
    )?;
    Ok(MediaProcessInput {
        path: relay.url().to_string(),
        _relay: Some(relay),
    })
}

fn remote_direct_stream_url(item: &MediaItem, access_token: &str) -> String {
    let item_id = item.id.simple();
    let container = media_item_container(item).unwrap_or_else(|| {
        if item.media_type == "Audio" {
            "audio".to_string()
        } else {
            "video".to_string()
        }
    });
    let media_type = if item.media_type == "Audio" {
        "Audio"
    } else {
        "Videos"
    };
    format!(
        "/{media_type}/{item_id}/stream.{container}?Static=true&MediaSourceId={item_id}&api_key={access_token}"
    )
}

async fn hls_transcode_session_input_path(
    state: &AppState,
    item: &MediaItem,
) -> Result<MediaProcessInput, ApiError> {
    media_process_input(state, item, INTERNAL_REMOTE_RELAY_TRANSCODE_TTL).await
}

fn media_item_container(item: &MediaItem) -> Option<String> {
    media_item_path(item)
        .extension()
        .and_then(|extension| extension.to_str())
        .map(|extension| extension.to_ascii_lowercase())
}

fn media_item_location_type(_item: &MediaItem) -> &'static str {
    "FileSystem"
}

fn collect_media_item_stream_languages(
    item: &MediaItem,
    stream_type: &str,
    values: &mut BTreeMap<String, String>,
) {
    for language in media_item_stream_languages(item, stream_type) {
        values
            .entry(language.to_ascii_lowercase())
            .or_insert(language);
    }
}

fn media_item_has_stream_language(
    item: &MediaItem,
    stream_type: &str,
    languages: &[String],
) -> bool {
    media_item_stream_languages(item, stream_type)
        .into_iter()
        .map(|language| language.to_ascii_lowercase())
        .any(|language| languages.iter().any(|allowed| allowed == &language))
}

fn media_item_has_stream_type(item: &MediaItem, stream_type: &str) -> bool {
    media_item_streams(item).into_iter().any(|stream| {
        stream
            .get("Type")
            .and_then(serde_json::Value::as_str)
            .is_some_and(|value| value.eq_ignore_ascii_case(stream_type))
    })
}

fn media_item_stream_languages(item: &MediaItem, stream_type: &str) -> Vec<String> {
    media_item_streams(item)
        .into_iter()
        .filter(|stream| {
            stream
                .get("Type")
                .and_then(serde_json::Value::as_str)
                .is_some_and(|value| value.eq_ignore_ascii_case(stream_type))
        })
        .filter_map(|stream| {
            stream
                .get("Language")
                .and_then(serde_json::Value::as_str)
                .and_then(normalize_language_code)
                .map(ToOwned::to_owned)
        })
        .collect()
}

fn media_item_file_name(item: &MediaItem) -> Option<String> {
    media_item_path(item)
        .file_name()
        .and_then(|file_name| file_name.to_str())
        .map(ToOwned::to_owned)
}

fn media_item_file_size(item: &MediaItem) -> Option<u64> {
    item.file_size
        .and_then(|file_size| u64::try_from(file_size).ok())
}

fn media_item_content_type(item: &MediaItem) -> String {
    match media_item_container(item).as_deref() {
        Some("mp4" | "m4v") => "video/mp4",
        Some("webm") => "video/webm",
        Some("mkv") => "video/x-matroska",
        Some("mov") => "video/quicktime",
        Some("avi") => "video/x-msvideo",
        Some("mp3") => "audio/mpeg",
        Some("m4a") => "audio/mp4",
        Some("aac") => "audio/aac",
        Some("flac") => "audio/flac",
        Some("ogg") => "audio/ogg",
        Some("wav") => "audio/wav",
        Some("jpg" | "jpeg") => "image/jpeg",
        Some("png") => "image/png",
        Some("gif") => "image/gif",
        Some("webp") => "image/webp",
        Some("bmp") => "image/bmp",
        _ => "application/octet-stream",
    }
    .to_string()
}

fn hls_codecs(item: &MediaItem) -> Option<String> {
    let codecs = [
        media_item_stream_codec(item, "Video"),
        media_item_stream_codec(item, "Audio"),
    ]
    .into_iter()
    .flatten()
    .filter(|codec| !codec.trim().is_empty())
    .collect::<Vec<_>>();
    (!codecs.is_empty()).then(|| codecs.join(","))
}

fn transcoded_hls_codecs(media_type: &str) -> Option<String> {
    match media_type {
        "Video" => Some("avc1.4d401f,mp4a.40.2".to_string()),
        "Audio" => Some("mp4a.40.2".to_string()),
        _ => None,
    }
}

fn hls_transcode_session_codecs(session: &TranscodeSession, media_type: &str) -> Option<String> {
    if media_type == "Video"
        && playback_hls_modes_from_dedupe_key(session.dedupe_key.as_deref())
            .is_some_and(|(video, _)| video == HlsStreamMode::Copy)
        && media_item_stream_codec(&session.item, "Video")
            .is_some_and(|codec| !codec.eq_ignore_ascii_case("h264"))
    {
        // A copied HEVC/MPEG-2 stream must not be advertised as AVC. Omitting CODECS is safer than
        // inventing an RFC 6381 profile string without all constraint flags; Media3 probes the TS
        // PMT and initializes the correct hardware decoder from the actual stream.
        return None;
    }
    transcoded_hls_codecs(media_type)
}

fn rewrite_hls_media_playlist(
    playlist: &str,
    item_id: &str,
    raw_query: Option<&str>,
    route_media_type: &str,
) -> String {
    let mut rewritten = String::with_capacity(playlist.len());
    for line in playlist.lines() {
        if line.trim().is_empty() || line.starts_with('#') {
            rewritten.push_str(line);
        } else if let Some(segment_id) = hls_segment_id_from_uri(line) {
            rewritten.push_str(&append_query(
                &format!("/{route_media_type}/{item_id}/hls1/main/{segment_id}.ts"),
                raw_query,
            ));
        } else {
            rewritten.push_str(line);
        }
        rewritten.push('\n');
    }
    rewritten
}

fn render_seekable_hls_media_playlist(
    session: &TranscodeSession,
    item_id: &str,
    raw_query: Option<&str>,
    route_media_type: &str,
) -> Option<String> {
    let runtime_ticks = session.item.runtime_ticks?.max(0);
    render_seekable_hls_media_playlist_for(
        session.start_position_ticks,
        runtime_ticks,
        item_id,
        raw_query,
        route_media_type,
    )
}

fn render_seekable_hls_media_playlist_for(
    start_position_ticks: i64,
    runtime_ticks: i64,
    item_id: &str,
    raw_query: Option<&str>,
    route_media_type: &str,
) -> Option<String> {
    if runtime_ticks <= 0 {
        return None;
    }

    let segment_ticks = hls_segment_ticks();
    let segment_count = ((runtime_ticks + segment_ticks - 1) / segment_ticks).max(1);
    let mut playlist = String::new();
    playlist.push_str("#EXTM3U\n");
    playlist.push_str("#EXT-X-PLAYLIST-TYPE:VOD\n");
    playlist.push_str("#EXT-X-VERSION:3\n");
    playlist.push_str(&format!(
        "#EXT-X-TARGETDURATION:{}\n",
        DEFAULT_HLS_SEGMENT_TIME_SECONDS.max(1)
    ));
    let effective_start_ticks =
        hls_effective_start_position_ticks(start_position_ticks, Some(runtime_ticks));
    if effective_start_ticks > 0 {
        let start_seconds = effective_start_ticks as f64 / 10_000_000.0;
        // Media3 has to prepare an HLS source before the application-level seek is applied. Tell
        // it where this playback session starts so it does not probe segment zero first and then
        // discard the session as an unavailable source.
        playlist.push_str(&format!(
            "#EXT-X-START:TIME-OFFSET={start_seconds:.6},PRECISE=YES\n"
        ));
    }
    // Android preserves the absolute player position while replacing an HLS session after seek.
    // Expose the full timeline so 350 seconds resolves segment 116, not relative segment 116 plus
    // the session's initial segment 116 (which incorrectly seeks to roughly 698 seconds).
    playlist.push_str("#EXT-X-MEDIA-SEQUENCE:0\n");

    for relative_segment_id in 0..segment_count {
        let Ok(relative_segment_id_u32) = u32::try_from(relative_segment_id) else {
            break;
        };
        let segment_start_ticks = relative_segment_id * segment_ticks;
        let segment_length_ticks = (runtime_ticks - segment_start_ticks)
            .min(segment_ticks)
            .max(0);
        if segment_length_ticks <= 0 {
            continue;
        }
        let segment_duration_seconds = segment_length_ticks as f64 / 10_000_000.0;
        playlist.push_str(&format!("#EXTINF:{segment_duration_seconds:.6}, nodesc\n"));
        let path = format!("/{route_media_type}/{item_id}/hls1/main/{relative_segment_id_u32}.ts");
        let query =
            append_hls_segment_timing_query(raw_query, segment_start_ticks, segment_length_ticks);
        playlist.push_str(&append_query(&path, query.as_deref()));
        playlist.push('\n');
    }

    playlist.push_str("#EXT-X-ENDLIST\n");
    Some(playlist)
}

fn append_hls_segment_timing_query(
    raw_query: Option<&str>,
    runtime_ticks: i64,
    actual_segment_length_ticks: i64,
) -> Option<String> {
    let timing = format!(
        "runtimeTicks={}&actualSegmentLengthTicks={}",
        runtime_ticks.max(0),
        actual_segment_length_ticks.max(0)
    );
    Some(
        raw_query
            .filter(|query| !query.trim().is_empty())
            .map_or(timing.clone(), |query| format!("{query}&{timing}")),
    )
}

fn hls_segment_ticks() -> i64 {
    i64::from(DEFAULT_HLS_SEGMENT_TIME_SECONDS.max(1)) * 10_000_000
}

fn hls_start_segment_number(start_position_ticks: i64) -> u32 {
    u32::try_from(start_position_ticks.max(0) / hls_segment_ticks()).unwrap_or(u32::MAX)
}

fn hls_storage_segment_id(
    _start_position_ticks: i64,
    _runtime_ticks: Option<i64>,
    playlist_segment_id: u32,
) -> Option<u32> {
    Some(playlist_segment_id)
}

fn align_hls_request_segment_timeline(request: &mut HlsTranscodeRequest) {
    let initial_segment_id = hls_start_segment_number(request.start_position_ticks);
    if initial_segment_id == 0 {
        return;
    }
    let aligned_start_ticks = i64::from(initial_segment_id).saturating_mul(hls_segment_ticks());
    request.hls_start_number = Some(initial_segment_id);
    request.output_ts_offset_ticks = Some(aligned_start_ticks);
    // Start the source on the same absolute boundary advertised by the VOD playlist. Seeking the
    // input to an exact resume point but labelling it with the earlier segment boundary made A/V
    // lead WebVTT by the remainder of that segment (up to almost three seconds).
    request.start_position_ticks = aligned_start_ticks;
}

fn hls_segment_start_position_ticks(_start_position_ticks: i64, segment_id: u32) -> Option<i64> {
    // Every URI in the full VOD playlist is absolute. This also keeps on-demand A/V extraction on
    // the same timeline as independently extracted WebVTT renditions.
    Some(i64::from(segment_id).saturating_mul(hls_segment_ticks()))
}

fn hls_effective_start_position_ticks(
    start_position_ticks: i64,
    runtime_ticks: Option<i64>,
) -> i64 {
    let start_position_ticks = start_position_ticks.max(0);
    let Some(runtime_ticks) = runtime_ticks.map(|ticks| ticks.max(0)) else {
        return start_position_ticks;
    };
    if runtime_ticks <= 0 {
        return start_position_ticks;
    }

    let max_start = runtime_ticks.saturating_sub(hls_segment_ticks()).max(0);
    start_position_ticks.min(max_start)
}

fn hls_segment_id_from_uri(uri: &str) -> Option<u32> {
    let path = uri.split_once('?').map_or(uri, |(path, _)| path);
    let file_name = FsPath::new(path).file_name()?.to_str()?;
    let segment_id = file_name.strip_prefix("segment_")?.strip_suffix(".ts")?;
    segment_id.parse().ok()
}

fn parse_hls_segment_file(segment_file: &str) -> Result<(i64, &str), ApiError> {
    let (segment_id, container) = segment_file
        .rsplit_once('.')
        .ok_or_else(|| ApiError::not_found("HLS segment not found"))?;
    let segment_id = segment_id
        .parse()
        .map_err(|_| ApiError::not_found("HLS segment not found"))?;
    Ok((segment_id, container))
}

fn append_query(path: &str, raw_query: Option<&str>) -> String {
    raw_query
        .filter(|query| !query.trim().is_empty())
        .map_or_else(|| path.to_string(), |query| format!("{path}?{query}"))
}

fn positive_u32(value: i64) -> Option<u32> {
    u32::try_from(value).ok().filter(|value| *value > 0)
}

fn media_item_streams(item: &MediaItem) -> Vec<serde_json::Value> {
    if !item.media_streams.is_empty() {
        let mut streams = item
            .media_streams
            .iter()
            .cloned()
            .map(normalize_media_stream)
            .collect::<Vec<_>>();
        enrich_media_streams_with_context(&mut streams);
        return streams;
    }

    if item.media_type == "Audio" {
        return vec![normalize_media_stream(serde_json::json!({
            "Codec": media_item_container(item).unwrap_or_else(|| "unknown".to_string()),
            "Language": null,
            "DisplayTitle": "Audio",
            "IsInterlaced": false,
            "BitRate": item.bitrate,
            "BitDepth": null,
            "Channels": null,
            "SampleRate": null,
            "IsDefault": true,
            "IsForced": false,
            "Type": "Audio",
            "Index": 0,
            "IsExternal": false,
            "Path": null
        }))];
    }

    if item.media_type == "Video" {
        return vec![normalize_media_stream(serde_json::json!({
            "Codec": media_item_container(item).unwrap_or_else(|| "unknown".to_string()),
            "Language": null,
            "ColorTransfer": null,
            "ColorPrimaries": null,
            "ColorSpace": null,
            "TimeBase": null,
            "VideoRange": null,
            "DisplayTitle": "Video",
            "NalLengthSize": null,
            "IsInterlaced": false,
            "IsAVC": null,
            "BitRate": item.bitrate,
            "BitDepth": null,
            "RefFrames": null,
            "IsDefault": true,
            "IsForced": false,
            "Height": item.height,
            "Width": item.width,
            "AverageFrameRate": null,
            "RealFrameRate": null,
            "Profile": null,
            "Type": "Video",
            "AspectRatio": null,
            "Index": 0,
            "IsExternal": false,
            "IsTextSubtitleStream": false,
            "SupportsExternalStream": false,
            "Path": null,
            "PixelFormat": null,
            "Level": null,
            "IsAnamorphic": null
        }))];
    }

    Vec::new()
}

fn normalize_media_stream(mut stream: serde_json::Value) -> serde_json::Value {
    let Some(object) = stream.as_object_mut() else {
        return stream;
    };
    let stream_type = object
        .get("Type")
        .and_then(serde_json::Value::as_str)
        .unwrap_or_default()
        .to_string();
    let raw_codec = object
        .get("Codec")
        .and_then(serde_json::Value::as_str)
        .unwrap_or("unknown")
        .to_string();
    let api_codec = media_stream_api_codec(&stream_type, &raw_codec);
    if api_codec != raw_codec {
        object.insert("Codec".to_string(), serde_json::json!(api_codec));
    }
    let language = object
        .get("Language")
        .and_then(serde_json::Value::as_str)
        .and_then(normalize_language_code)
        .map(ToOwned::to_owned);
    if let Some(language) = language.as_deref() {
        object.insert("Language".to_string(), serde_json::json!(language));
    }
    let title = object
        .get("Title")
        .and_then(serde_json::Value::as_str)
        .map(ToOwned::to_owned);
    let channels = object.get("Channels").and_then(json_value_i64);
    let channel_layout = object
        .get("ChannelLayout")
        .and_then(serde_json::Value::as_str)
        .map(ToOwned::to_owned);
    let is_default = object
        .get("IsDefault")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let is_forced = object
        .get("IsForced")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let width = object.get("Width").and_then(json_value_i64);
    let height = object.get("Height").and_then(json_value_i64);
    let pixel_format = object
        .get("PixelFormat")
        .and_then(serde_json::Value::as_str)
        .map(ToOwned::to_owned);
    let bit_depth = object
        .get("BitDepth")
        .and_then(json_value_i64)
        .or_else(|| video_bit_depth_from_pixel_format(pixel_format.as_deref()));

    insert_if_missing_or_null(object, "TimeBase", serde_json::json!("1/1000"));
    insert_if_missing_or_null(object, "VideoRange", serde_json::json!("Unknown"));
    insert_if_missing_or_null(object, "VideoRangeType", serde_json::json!("Unknown"));
    insert_if_missing_or_null(object, "AudioSpatialFormat", serde_json::json!("None"));
    insert_if_missing_or_null(object, "IsHearingImpaired", serde_json::json!(false));
    insert_if_missing_or_null(object, "IsOriginal", serde_json::json!(false));
    insert_if_missing_or_null(object, "IsInterlaced", serde_json::json!(false));
    insert_if_missing_or_null(object, "IsTextSubtitleStream", serde_json::json!(false));

    if let Some(localized_language) = language_display_name(language.as_deref()) {
        object.insert(
            "LocalizedLanguage".to_string(),
            serde_json::json!(localized_language),
        );
    }
    object.insert("LocalizedDefault".to_string(), serde_json::json!("Default"));
    object.insert(
        "LocalizedExternal".to_string(),
        serde_json::json!("External"),
    );

    if stream_type == "Subtitle" {
        object.insert(
            "IsTextSubtitleStream".to_string(),
            serde_json::json!(is_text_subtitle_codec(&api_codec)),
        );
        object.insert(
            "SupportsExternalStream".to_string(),
            serde_json::json!(subtitle_supports_external_stream(&api_codec)),
        );
        object.insert(
            "LocalizedUndefined".to_string(),
            serde_json::json!("Undefined"),
        );
        object.insert("LocalizedForced".to_string(), serde_json::json!("Forced"));
        object.insert(
            "LocalizedHearingImpaired".to_string(),
            serde_json::json!("Hearing Impaired"),
        );
    }
    if stream_type == "Audio" {
        object.insert("IsTextSubtitleStream".to_string(), serde_json::json!(false));
        object.insert(
            "SupportsExternalStream".to_string(),
            serde_json::json!(false),
        );
        object.insert(
            "LocalizedOriginal".to_string(),
            serde_json::json!("Original"),
        );
        if let Some(channels) = audio_channel_display(channels, channel_layout.as_deref()) {
            object.insert("ChannelLayout".to_string(), serde_json::json!(channels));
        }
    }
    if stream_type == "Video" {
        if let Some(bit_depth) = bit_depth {
            object.insert("BitDepth".to_string(), serde_json::json!(bit_depth));
        }
        for key in [
            "ChannelLayout",
            "Channels",
            "CodecTag",
            "LocalizedDefault",
            "LocalizedExternal",
            "Path",
            "SampleRate",
            "Title",
        ] {
            object.remove(key);
        }
        let is_h264 = api_codec.eq_ignore_ascii_case("h264");
        insert_if_missing_or_null(object, "IsAVC", serde_json::json!(is_h264));
        insert_if_missing_or_null(object, "IsAnamorphic", serde_json::json!(false));
        insert_if_missing_or_null(object, "IsInterlaced", serde_json::json!(false));
        insert_if_missing_or_null(object, "SupportsExternalStream", serde_json::json!(false));
        if let Some(aspect_ratio) = video_aspect_ratio(width, height) {
            insert_if_missing_or_null(object, "AspectRatio", serde_json::json!(aspect_ratio));
        }
        if is_h264 {
            insert_if_missing_or_null(object, "NalLengthSize", serde_json::json!("4"));
            insert_if_missing_or_null(object, "Level", serde_json::json!(30));
            insert_if_missing_or_null(object, "RefFrames", serde_json::json!(1));
        }
        if let Some(frame_rate) = object
            .get("RealFrameRate")
            .cloned()
            .or_else(|| object.get("AverageFrameRate").cloned())
            .filter(|value| !value.is_null())
        {
            insert_if_missing_or_null(object, "ReferenceFrameRate", frame_rate);
        }
        let video_range = video_stream_range(object);
        object.insert("VideoRange".to_string(), serde_json::json!(video_range));
        object.insert("VideoRangeType".to_string(), serde_json::json!(video_range));
    }
    object.insert(
        "DisplayTitle".to_string(),
        serde_json::json!(if stream_type == "Video" {
            video_stream_display_title(
                &api_codec,
                width,
                height,
                object.get("VideoRange").and_then(serde_json::Value::as_str),
            )
        } else {
            media_stream_display_title(
                &stream_type,
                &api_codec,
                language.as_deref(),
                title.as_deref(),
                channels,
                channel_layout.as_deref(),
                is_default,
                is_forced,
            )
        }),
    );
    stream
}

fn enrich_media_streams_with_context(streams: &mut [serde_json::Value]) {
    let video_dimensions = streams.iter().find_map(|stream| {
        let object = stream.as_object()?;
        let stream_type = object.get("Type").and_then(serde_json::Value::as_str)?;
        if !stream_type.eq_ignore_ascii_case("Video") {
            return None;
        }
        Some((
            object
                .get("Width")
                .cloned()
                .unwrap_or(serde_json::Value::Null),
            object
                .get("Height")
                .cloned()
                .unwrap_or(serde_json::Value::Null),
        ))
    });

    let Some((video_width, video_height)) = video_dimensions else {
        return;
    };
    if video_width.is_null() && video_height.is_null() {
        return;
    }

    for stream in streams {
        let Some(object) = stream.as_object_mut() else {
            continue;
        };
        let stream_type = object
            .get("Type")
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default();
        if !stream_type.eq_ignore_ascii_case("Subtitle") {
            continue;
        }
        insert_if_missing_or_null(object, "Width", video_width.clone());
        insert_if_missing_or_null(object, "Height", video_height.clone());
    }
}

fn insert_if_missing_or_null(
    object: &mut serde_json::Map<String, serde_json::Value>,
    key: &str,
    value: serde_json::Value,
) {
    if object.get(key).is_none_or(serde_json::Value::is_null) {
        object.insert(key.to_string(), value);
    }
}

#[allow(clippy::too_many_arguments)]
fn media_stream_display_title(
    stream_type: &str,
    codec: &str,
    language: Option<&str>,
    title: Option<&str>,
    channels: Option<i64>,
    channel_layout: Option<&str>,
    is_default: bool,
    is_forced: bool,
) -> String {
    let mut parts = Vec::<String>::new();
    if let Some(title) = title.map(str::trim).filter(|title| !title.is_empty()) {
        parts.push(title.to_string());
    }
    if let Some(language) = language_display_name(language) {
        parts.push(language);
    }
    match stream_type {
        "Audio" => {
            parts.push(codec_display_name(codec));
            if let Some(channels) = audio_channel_display(channels, channel_layout) {
                parts.push(channels);
            }
        }
        "Subtitle" => {
            parts.push(codec_display_name(codec));
        }
        _ => parts.push(codec_display_name(codec)),
    }
    if is_default {
        parts.push("Default".to_string());
    }
    if is_forced {
        parts.push("Forced".to_string());
    }
    if parts.is_empty() {
        stream_type.to_string()
    } else {
        parts.join(" - ")
    }
}

fn video_stream_display_title(
    codec: &str,
    width: Option<i64>,
    height: Option<i64>,
    video_range: Option<&str>,
) -> String {
    let mut parts = Vec::<String>::new();
    if let Some(resolution) = video_resolution_display(width, height) {
        parts.push(resolution);
    }
    parts.push(codec_display_name(codec));
    if let Some(video_range) = video_range
        .map(str::trim)
        .filter(|value| !value.is_empty() && !value.eq_ignore_ascii_case("Unknown"))
    {
        parts.push(video_range.to_ascii_uppercase());
    }
    parts.join(" ")
}

fn video_resolution_display(width: Option<i64>, height: Option<i64>) -> Option<String> {
    let height = height.filter(|height| *height > 0)?;
    let label = match height {
        1..=479 => format!("{height}p"),
        480..=719 => "480p".to_string(),
        720..=1079 => "720p".to_string(),
        1080..=1439 => "1080p".to_string(),
        1440..=2159 => "1440p".to_string(),
        2160..=4319 => "4K".to_string(),
        _ => format!("{height}p"),
    };
    if width.is_some_and(|width| width >= 3800) && height >= 2000 {
        Some("4K".to_string())
    } else {
        Some(label)
    }
}

fn video_aspect_ratio(width: Option<i64>, height: Option<i64>) -> Option<String> {
    let width = width.filter(|value| *value > 0)?;
    let height = height.filter(|value| *value > 0)?;
    let divisor = gcd_i64(width, height);
    Some(format!("{}:{}", width / divisor, height / divisor))
}

fn gcd_i64(mut left: i64, mut right: i64) -> i64 {
    while right != 0 {
        let remainder = left % right;
        left = right;
        right = remainder;
    }
    left.abs().max(1)
}

fn video_stream_range(object: &serde_json::Map<String, serde_json::Value>) -> &'static str {
    let existing = object
        .get("VideoRange")
        .and_then(serde_json::Value::as_str)
        .unwrap_or_default();
    if existing.eq_ignore_ascii_case("HDR")
        || existing.eq_ignore_ascii_case("HDR10")
        || existing.eq_ignore_ascii_case("HLG")
        || existing.eq_ignore_ascii_case("DolbyVision")
    {
        return "HDR";
    }
    let transfer = object
        .get("ColorTransfer")
        .and_then(serde_json::Value::as_str)
        .unwrap_or_default()
        .to_ascii_lowercase();
    if matches!(transfer.as_str(), "smpte2084" | "arib-std-b67") {
        "HDR"
    } else {
        "SDR"
    }
}

fn video_bit_depth_from_pixel_format(pixel_format: Option<&str>) -> Option<i64> {
    let pixel_format = pixel_format?.to_ascii_lowercase();
    if pixel_format.contains("12") {
        Some(12)
    } else if pixel_format.contains("10") {
        Some(10)
    } else {
        None
    }
}

fn media_stream_api_codec(stream_type: &str, codec: &str) -> String {
    match (stream_type, codec.to_ascii_lowercase().as_str()) {
        ("Subtitle", "hdmv_pgs_subtitle") => "PGSSUB".to_string(),
        _ => codec.to_string(),
    }
}

fn codec_display_name(codec: &str) -> String {
    match codec.to_ascii_lowercase().as_str() {
        "ac3" => "Dolby Digital".to_string(),
        "eac3" => "Dolby Digital+".to_string(),
        "aac" => "AAC".to_string(),
        "dts" => "DTS".to_string(),
        "truehd" => "TrueHD".to_string(),
        "flac" => "FLAC".to_string(),
        "hevc" | "h265" => "HEVC".to_string(),
        "h264" => "H264".to_string(),
        "hdmv_pgs_subtitle" | "pgssub" => "PGSSUB".to_string(),
        "subrip" => "SRT".to_string(),
        "ass" | "ssa" => codec.to_ascii_uppercase(),
        _ => codec.to_string(),
    }
}

fn language_display_name(language: Option<&str>) -> Option<String> {
    let language = language?.trim();
    if language.is_empty() || language.eq_ignore_ascii_case("und") {
        return None;
    }
    Some(
        match language.to_ascii_lowercase().as_str() {
            "eng" | "en" => "English",
            "spa" | "es" => "Spanish; Castilian",
            "fre" | "fra" | "fr" => "French",
            "ger" | "deu" | "de" => "German",
            "dan" | "da" => "Danish",
            "fin" | "fi" => "Finnish",
            "nob" => "Norwegian (Bokmal)",
            "nor" | "no" => "Norwegian",
            "swe" | "sv" => "Swedish",
            _ => language,
        }
        .to_string(),
    )
}

fn normalize_language_code(language: &str) -> Option<&str> {
    let language = language.trim();
    if language.is_empty() || language.eq_ignore_ascii_case("und") {
        return None;
    }
    Some(match language.to_ascii_lowercase().as_str() {
        "fre" => "fra",
        "ger" => "deu",
        _ => language,
    })
}

fn audio_channel_display(channels: Option<i64>, channel_layout: Option<&str>) -> Option<String> {
    if let Some(layout) = channel_layout {
        let normalized = layout.trim().trim_end_matches("(side)").trim();
        if !normalized.is_empty() && normalized != "0" {
            return Some(normalized.to_string());
        }
    }
    match channels {
        Some(1) => Some("Mono".to_string()),
        Some(2) => Some("Stereo".to_string()),
        Some(6) => Some("5.1".to_string()),
        Some(8) => Some("7.1".to_string()),
        Some(value) if value > 0 => Some(format!("{value} ch")),
        _ => None,
    }
}

fn is_text_subtitle_codec(codec: &str) -> bool {
    matches!(
        codec.to_ascii_lowercase().as_str(),
        "subrip" | "srt" | "ass" | "ssa" | "webvtt" | "vtt" | "mov_text"
    )
}

fn subtitle_supports_external_stream(codec: &str) -> bool {
    !is_text_subtitle_codec(codec)
}

fn parse_range_header(headers: &HeaderMap, total_len: u64) -> Result<Option<(u64, u64)>, ()> {
    let Some(range) = headers.get(header::RANGE) else {
        return Ok(None);
    };
    if total_len == 0 {
        return Err(());
    }

    let range = range.to_str().map_err(|_| ())?;
    let range = range.strip_prefix("bytes=").ok_or(())?;
    let (start, end) = range.split_once('-').ok_or(())?;
    let (start, end) = if start.is_empty() {
        let suffix_len = end.parse::<u64>().map_err(|_| ())?.min(total_len);
        (total_len - suffix_len, total_len - 1)
    } else {
        let start = start.parse::<u64>().map_err(|_| ())?;
        let end = if end.is_empty() {
            total_len - 1
        } else {
            end.parse::<u64>().map_err(|_| ())?.min(total_len - 1)
        };
        (start, end)
    };

    if start <= end && start < total_len {
        Ok(Some((start, end)))
    } else {
        Err(())
    }
}

fn media_item_type(item: &MediaItem) -> &'static str {
    effective_media_item_type(item)
}

#[derive(Debug, Clone, Eq, PartialEq)]
struct TvEpisodeInfo {
    series_name: String,
    season_number: Option<i32>,
    episode_number: Option<i32>,
}

fn is_tv_episode(item: &MediaItem) -> bool {
    media_item_type(item) == "Episode"
}

fn tv_episode_info(item: &MediaItem) -> Option<TvEpisodeInfo> {
    if !is_tv_episode(item) {
        return None;
    }
    let info = tv_episode_path_info(&item.name, &item.path);
    Some(TvEpisodeInfo {
        series_name: info.series_name,
        season_number: info.season_number,
        episode_number: info.episode_number,
    })
}

/// Same as [`tv_episode_info`], but trusts explicit numbering from the item's metadata first.
///
/// Path parsing is the right fallback for scanned files, whose season and episode live in the
/// filename. It cannot work for an imported catalogue: those items carry an opaque path such as
/// `plugin-vod://<id>` and a display name with no `S01E02` pattern, so every episode parsed as
/// season `None` and collapsed into one "Season Unknown" folder even though the metadata already
/// held the correct `ParentIndexNumber`.
fn tv_episode_info_with_metadata(
    item: &MediaItem,
    metadata: Option<&serde_json::Value>,
) -> Option<TvEpisodeInfo> {
    let mut info = tv_episode_info(item)?;
    let Some(metadata) = metadata else {
        return Some(info);
    };
    if let Some(series_name) = first_metadata_value_from_json(metadata, &["SeriesName"])
        .filter(|name| !name.trim().is_empty())
    {
        info.series_name = series_name;
    }
    if let Some(season_number) = metadata_i32_field(metadata, &["ParentIndexNumber"]) {
        info.season_number = Some(season_number);
    }
    if let Some(episode_number) = metadata_i32_field(metadata, &["IndexNumber"]) {
        info.episode_number = Some(episode_number);
    }
    Some(info)
}

/// Reads a bounded integer from metadata, accepting the string form some importers persist.
fn metadata_i32_field(metadata: &serde_json::Value, keys: &[&str]) -> Option<i32> {
    for key in keys {
        let Some(value) = json_field_case_insensitive(metadata, key) else {
            continue;
        };
        if let Some(number) = value.as_i64() {
            return i32::try_from(number).ok();
        }
        if let Some(parsed) = value
            .as_str()
            .and_then(|value| value.trim().parse::<i32>().ok())
        {
            return Some(parsed);
        }
    }
    None
}

fn plugin_vod_series_anchor_info(
    item: &MediaItem,
    metadata: &serde_json::Value,
) -> Option<(String, String)> {
    if item.media_type != "Series"
        || !item.collection_type.as_deref().is_some_and(|value| {
            matches!(
                value.to_ascii_lowercase().as_str(),
                "tvshows" | "tvshow" | "series"
            )
        })
        || !first_metadata_value_from_json(metadata, &["PluginVodKind"])
            .is_some_and(|kind| kind.eq_ignore_ascii_case(VOD_ITEM_TYPE_SERIES))
    {
        return None;
    }
    let series_id = canonical_metadata_uuid_from_json(metadata, &["SeriesId"])?;
    let series_name = first_metadata_value_from_json(metadata, &["SeriesName"])
        .filter(|name| !name.trim().is_empty())
        .unwrap_or_else(|| item.name.clone());
    Some((series_id, series_name))
}

fn plugin_vod_series_anchor_matches(
    item: &MediaItem,
    metadata: &serde_json::Value,
    series_id: &str,
) -> bool {
    plugin_vod_series_anchor_info(item, metadata)
        .is_some_and(|(candidate_id, _)| jellyfin_id_matches(&candidate_id, series_id))
}

fn tv_episode_series_key(item: &MediaItem) -> String {
    core_tv_episode_series_key(item)
}

fn tv_series_id(series_name: &str) -> String {
    stable_entity_id("Series", series_name)
}

fn tv_season_id(series_name: &str, season_number: Option<i32>) -> String {
    let season_key = season_number
        .map(|season| season.to_string())
        .unwrap_or_else(|| "unknown".to_string());
    stable_entity_id("Season", &format!("{series_name}:{season_key}"))
}

fn tv_series_id_for_episode(info: &TvEpisodeInfo, metadata: Option<&serde_json::Value>) -> String {
    metadata
        .and_then(|metadata| canonical_metadata_uuid_from_json(metadata, &["SeriesId"]))
        .unwrap_or_else(|| tv_series_id(&info.series_name))
}

fn tv_season_id_for_episode(info: &TvEpisodeInfo, metadata: Option<&serde_json::Value>) -> String {
    metadata
        .and_then(|metadata| canonical_metadata_uuid_from_json(metadata, &["SeasonId"]))
        .unwrap_or_else(|| tv_season_id(&info.series_name, info.season_number))
}

fn jellyfin_id_matches(left: &str, right: &str) -> bool {
    match (parse_jellyfin_uuid(left), parse_jellyfin_uuid(right)) {
        (Ok(left), Ok(right)) => left == right,
        _ => left.eq_ignore_ascii_case(right),
    }
}

fn tv_episode_matches_series(
    item: &MediaItem,
    metadata: Option<&serde_json::Value>,
    series_id: &str,
) -> bool {
    tv_episode_info(item)
        .map(|info| jellyfin_id_matches(&tv_series_id_for_episode(&info, metadata), series_id))
        .unwrap_or(false)
}

fn tv_episode_matches_season(
    item: &MediaItem,
    metadata: Option<&serde_json::Value>,
    season_id: &str,
) -> bool {
    tv_episode_info_with_metadata(item, metadata)
        .map(|info| {
            jellyfin_id_matches(&tv_season_id_for_episode(&info, metadata), season_id)
                || jellyfin_id_matches(
                    &tv_season_id(&info.series_name, info.season_number),
                    season_id,
                )
        })
        .unwrap_or(false)
}

struct TvEpisodeCatalogSnapshot {
    items: Vec<MediaItem>,
    metadata_by_item: HashMap<Uuid, serde_json::Value>,
}

/// Publish a folder's TV series projection in the background.
///
/// While its coverage row is missing the Series listing answers from the bounded live page, which
/// costs seconds on a large library, and only a folder sync used to republish it. The guard keeps one
/// rebuild per folder in flight so a burst of page loads cannot queue one each, and a folder whose
/// data is not projectable is simply left alone until its contents change.
fn schedule_tv_series_projection_rebuild(db: &Database, virtual_folder_id: Uuid) {
    let db = db.clone();
    tokio::spawn(async move {
        let registry = TV_SERIES_REBUILDS.get_or_init(|| Mutex::new(HashSet::new()));
        if !registry.lock().await.insert(virtual_folder_id) {
            return;
        }
        let outcome =
            MediaCatalogStore::ensure_tv_series_catalog_projection(&db, virtual_folder_id).await;
        registry.lock().await.remove(&virtual_folder_id);
        match outcome {
            Ok(true) => {}
            Ok(false) => tracing::debug!(
                %virtual_folder_id,
                "tv series projection is not publishable for this folder"
            ),
            Err(error) => tracing::warn!(
                %error,
                %virtual_folder_id,
                "failed to publish the tv series projection"
            ),
        }
    });
}

async fn tv_episode_catalog_snapshot(db: &Database) -> Result<TvEpisodeCatalogSnapshot, ApiError> {
    let entries = MediaCatalogStore::tv_series_lookup_candidates(db).await?;
    Ok(tv_episode_catalog_snapshot_from_entries(entries))
}

fn tv_episode_catalog_snapshot_from_entries(
    entries: Vec<MediaItemCatalogEntry>,
) -> TvEpisodeCatalogSnapshot {
    let mut items = Vec::with_capacity(entries.len());
    let mut metadata_by_item = HashMap::with_capacity(entries.len());
    for entry in entries {
        metadata_by_item.insert(entry.item.id, entry.metadata);
        items.push(entry.item);
    }
    TvEpisodeCatalogSnapshot {
        items,
        metadata_by_item,
    }
}

/// Snapshot restricted to the episodes and optional provider anchor of one persisted series.
///
/// Resolving a single Series id otherwise materializes every episode in the library, which exceeds
/// the API statement timeout at library scale. Returns `None` when the id is not a canonical
/// persisted `SeriesId` — the name-derived synthetic ids are hashes that only the full snapshot can
/// resolve — and when no source row carries it, so both cases keep the caller's existing
/// behaviour.
async fn tv_episode_catalog_snapshot_for_series(
    db: &Database,
    series_id: &str,
) -> Result<Option<TvEpisodeCatalogSnapshot>, ApiError> {
    let Ok(canonical) = parse_jellyfin_uuid(series_id) else {
        return Ok(None);
    };
    let entries = MediaCatalogStore::tv_series_lookup_candidates_for_series(
        db,
        &canonical.simple().to_string(),
    )
    .await?;
    if entries.is_empty() {
        return Ok(None);
    }
    Ok(Some(tv_episode_catalog_snapshot_from_entries(entries)))
}

/// Snapshot restricted to the episodes that can carry a name-derived synthetic Series id.
///
/// An episode with a canonical persisted `SeriesId` is only ever addressed by it, so a canonical
/// lookup that finds nothing cannot be answered by those rows either. Narrowing the fallback to the
/// remainder keeps it exact while leaving a reconciled library with nothing to scan.
async fn tv_episode_catalog_snapshot_without_canonical_series_id(
    db: &Database,
) -> Result<TvEpisodeCatalogSnapshot, ApiError> {
    let entries =
        MediaCatalogStore::tv_series_lookup_candidates_without_canonical_series_id(db).await?;
    Ok(tv_episode_catalog_snapshot_from_entries(entries))
}

/// Snapshot restricted to the episodes of one persisted season, on the same terms as
/// `tv_episode_catalog_snapshot_for_series`.
async fn tv_episode_catalog_snapshot_for_season(
    db: &Database,
    season_id: &str,
) -> Result<Option<TvEpisodeCatalogSnapshot>, ApiError> {
    let Ok(canonical) = parse_jellyfin_uuid(season_id) else {
        return Ok(None);
    };
    let entries = MediaCatalogStore::tv_series_lookup_candidates_for_season(
        db,
        &canonical.simple().to_string(),
    )
    .await?;
    if entries.is_empty() {
        return Ok(None);
    }
    Ok(Some(tv_episode_catalog_snapshot_from_entries(entries)))
}

/// The scoped snapshot for an id that may name either a series or a season, falling back to the
/// episodes without a canonical series id when neither persisted id resolves. Those are the only
/// rows that can belong to a name-derived synthetic series.
async fn tv_episode_catalog_snapshot_scoped_to_series(
    db: &Database,
    series_id: &str,
) -> Result<(TvEpisodeCatalogSnapshot, String), ApiError> {
    if let Some(snapshot) = tv_episode_catalog_snapshot_for_series(db, series_id).await? {
        return Ok((snapshot, series_id.to_string()));
    }
    // Plugin VOD listings expose the persisted Series anchor's item id, while its episodes carry
    // the provider's canonical SeriesId. Resolve that public anchor id before trying legacy
    // synthetic ids so both `/Shows/{id}/Seasons` and Wholphin's generic `/Items` shape agree with
    // the id returned by the catalogue.
    if let Ok(anchor_item_id) = parse_jellyfin_uuid(series_id)
        && let Some(anchor) = db
            .media_item_with_metadata_by_id_visible(anchor_item_id)
            .await?
        && let Some((canonical_series_id, _)) =
            plugin_vod_series_anchor_info(&anchor.item, &anchor.metadata)
        && let Some(snapshot) =
            tv_episode_catalog_snapshot_for_series(db, &canonical_series_id).await?
    {
        return Ok((snapshot, canonical_series_id));
    }
    if let Some(snapshot) = tv_episode_catalog_snapshot_for_season(db, series_id).await? {
        return Ok((snapshot, series_id.to_string()));
    }
    Ok((
        tv_episode_catalog_snapshot_without_canonical_series_id(db).await?,
        series_id.to_string(),
    ))
}

fn tv_season_parent_from_snapshot(
    snapshot: &TvEpisodeCatalogSnapshot,
    season_id: &str,
) -> Option<(String, String)> {
    snapshot.items.iter().find_map(|item| {
        if !item
            .collection_type
            .as_deref()
            .is_some_and(|value| value.eq_ignore_ascii_case("tvshows"))
            || !tv_episode_matches_season(item, snapshot.metadata_by_item.get(&item.id), season_id)
        {
            return None;
        }
        let info = tv_episode_info_with_metadata(item, snapshot.metadata_by_item.get(&item.id))?;
        Some((
            info.series_name.clone(),
            tv_series_id_for_episode(&info, snapshot.metadata_by_item.get(&item.id)),
        ))
    })
}

fn series_name_for_id_from_snapshot(
    snapshot: &TvEpisodeCatalogSnapshot,
    series_id: &str,
) -> Option<String> {
    snapshot.items.iter().find_map(|item| {
        let metadata = snapshot.metadata_by_item.get(&item.id);
        if let Some((anchor_id, anchor_name)) =
            metadata.and_then(|metadata| plugin_vod_series_anchor_info(item, metadata))
            && jellyfin_id_matches(&anchor_id, series_id)
        {
            return Some(anchor_name);
        }
        let info = tv_episode_info(item)?;
        jellyfin_id_matches(&tv_series_id_for_episode(&info, metadata), series_id)
            .then_some(info.series_name)
    })
}

fn tv_series_summary_by_id_from_snapshot(
    snapshot: &TvEpisodeCatalogSnapshot,
    series_id: &str,
) -> Option<TvSeriesSummary> {
    let mut grouped = BTreeMap::<String, TvSeriesSummary>::new();
    for item in snapshot.items.iter().filter(|item| {
        item.collection_type
            .as_deref()
            .is_some_and(|value| value.eq_ignore_ascii_case("tvshows"))
            && tv_episode_matches_series(item, snapshot.metadata_by_item.get(&item.id), series_id)
    }) {
        let Some(info) = tv_episode_info(item) else {
            continue;
        };
        let summary = grouped
            .entry(info.series_name.clone())
            .or_insert_with(|| TvSeriesSummary::new(info.series_name.clone()));
        summary.add_episode(item, &info, snapshot.metadata_by_item.get(&item.id), None);
    }
    grouped.into_values().next()
}

async fn series_name_for_id(db: &Database, series_id: &str) -> Result<Option<String>, ApiError> {
    let snapshot = match tv_episode_catalog_snapshot_for_series(db, series_id).await? {
        Some(snapshot) => snapshot,
        None => tv_episode_catalog_snapshot_without_canonical_series_id(db).await?,
    };
    Ok(series_name_for_id_from_snapshot(&snapshot, series_id))
}

#[derive(Debug)]
struct TvSeasonSummary {
    id: Option<String>,
    season_number: Option<i32>,
    episode_count: usize,
    unplayed_count: usize,
    metadata: serde_json::Value,
}

impl TvSeasonSummary {
    fn new(season_number: Option<i32>) -> Self {
        Self {
            id: None,
            season_number,
            episode_count: 0,
            unplayed_count: 0,
            metadata: serde_json::Value::Object(serde_json::Map::new()),
        }
    }

    fn merge_episode_metadata(&mut self, metadata: &serde_json::Value) {
        if is_plugin_vod_remote_media(Some(metadata)) {
            // Internal presentation marker only. `tv_season_json` copies a fixed allowlist of
            // public fields, so this cannot expose the provider reference used to derive it.
            self.metadata["PluginVodImageCandidate"] = serde_json::json!(true);
        }
        if self.id.is_none() {
            self.id = canonical_metadata_uuid_from_json(metadata, &["SeasonId"]);
        }
        for (target, keys) in [
            ("Overview", &["SeasonOverview"][..]),
            ("PremiereDate", &["SeasonPremiereDate"][..]),
            ("EndDate", &["SeasonEndDate"][..]),
            ("CommunityRating", &["SeasonCommunityRating"][..]),
            ("ProductionYear", &["SeasonProductionYear"][..]),
            ("PrimaryImageTag", &["SeasonPrimaryImageTag"][..]),
            ("PrimaryImagePath", &["SeasonPrimaryImagePath"][..]),
        ] {
            if self.metadata.get(target).is_none()
                && let Some(value) = first_metadata_value_from_json(metadata, keys)
            {
                self.metadata[target] = serde_json::Value::String(value);
            }
        }
        for field in [
            "SeriesPluginVodImageAvailable",
            "SeasonPluginVodImageAvailable",
        ] {
            if json_field_case_insensitive(metadata, field).and_then(serde_json::Value::as_bool)
                == Some(true)
            {
                self.metadata[field] = serde_json::json!(true);
            }
        }
        if self.metadata.get("ProviderIds").is_none()
            && let Some(provider_ids) = json_field_case_insensitive(metadata, "SeasonProviderIds")
            && provider_ids.is_object()
        {
            self.metadata["ProviderIds"] = provider_ids.clone();
        }
        for (target, key) in [
            ("People", "SeasonPeople"),
            ("ExternalUrls", "SeasonExternalUrls"),
        ] {
            if self.metadata.get(target).is_none()
                && let Some(value) = json_field_case_insensitive(metadata, key)
                && value.is_array()
            {
                self.metadata[target] = value.clone();
            }
        }
    }
}

/// Presents a series whose provider ships no season numbering as a single season one.
///
/// An unnumbered episode is not the same as an episode in an unknown season. When a provider omits
/// numbering entirely — 3,610 of the series in a real imported catalogue — every episode parses as
/// unnumbered and the series showed one "Season Unknown" folder, which is wrong for the shape it
/// actually has: a flat run of episodes that is season one. A series that mixes numbered and
/// unnumbered episodes keeps its unknown bucket, because there the gap is real information.
fn present_unnumbered_season_as_first(
    seasons: &mut BTreeMap<Option<i32>, TvSeasonSummary>,
    series_name: &str,
) {
    if seasons.len() != 1 || !seasons.contains_key(&None) {
        return;
    }
    let Some(mut summary) = seasons.remove(&None) else {
        return;
    };
    // Relabel the presentation only. The episodes still parse as unnumbered and
    // `tv_episode_matches_season` derives their season id from that, so advertising the numbered id
    // would leave the season unreachable: its detail page would resolve no episode at all.
    if summary.id.is_none() {
        summary.id = Some(tv_season_id(series_name, None));
    }
    summary.season_number = Some(1);
    seasons.insert(Some(1), summary);
}

fn tv_season_json(
    server_id: &str,
    series_name: &str,
    series_id: &str,
    summary: TvSeasonSummary,
) -> serde_json::Value {
    let season_number = summary.season_number;
    let season_name = season_number
        .map(|season| format!("Season {season}"))
        .unwrap_or_else(|| "Season Unknown".to_string());
    let season_id = summary
        .id
        .clone()
        .unwrap_or_else(|| tv_season_id(series_name, season_number));
    let image_tag = primary_image_tag_for_metadata(&season_id, Some(&summary.metadata));
    let series_image_tag = primary_image_tag_for_metadata(series_id, Some(&summary.metadata));
    let (display_series_name, _) = clean_tv_series_name_and_year(series_name);
    let episode_count = summary.episode_count;
    let unplayed_count = summary.unplayed_count;
    let played = episode_count > 0 && unplayed_count == 0;
    let mut value = serde_json::json!({
        "Name": season_name,
        "OriginalTitle": null,
        "ServerId": server_id,
        "Id": season_id,
        "Etag": null,
        "DateCreated": null,
        "CanDelete": false,
        "CanDownload": false,
        "SortName": season_name,
        "ForcedSortName": null,
        "ExternalUrls": [],
        "Path": null,
        "Overview": "",
        "EnableMediaSourceDisplay": true,
        "ChannelId": null,
        "Taglines": [],
        "Genres": [],
        "PlayAccess": "Full",
        "RemoteTrailers": [],
        "ProviderIds": {},
        "IsFolder": true,
        "ParentId": series_id,
        "Type": "Season",
        "MediaType": null,
        "SeriesName": display_series_name,
        "SeriesId": series_id,
        "ParentLogoItemId": series_id,
        "ParentBackdropItemId": series_id,
        "ParentBackdropImageTags": [],
        "ParentThumbItemId": series_id,
        "ParentThumbImageTag": series_image_tag,
        "SeriesPrimaryImageTag": series_image_tag,
        "IndexNumber": season_number,
        "ChildCount": episode_count,
        "RecursiveItemCount": episode_count,
        "UserData": {
            "PlaybackPositionTicks": 0,
            "PlayCount": i32::from(played),
            "IsFavorite": false,
            "Played": played,
            "PlayedPercentage": if played { 100.0 } else { 0.0 },
            "UnplayedItemCount": unplayed_count,
            "Key": season_id,
            "ItemId": season_id
        },
        "ImageTags": { "Primary": image_tag },
        "PrimaryImageAspectRatio": 0.6666667,
        "BackdropImageTags": [],
        "LocationType": "Virtual"
    });
    apply_tv_season_metadata(&mut value, &summary.metadata);
    value
}

fn apply_tv_season_metadata(value: &mut serde_json::Value, metadata: &serde_json::Value) {
    let Some(object) = value.as_object_mut() else {
        return;
    };
    for key in ["Overview", "CommunityRating"] {
        if let Some(field_value) = metadata.get(key)
            && !field_value.is_null()
            && field_value.as_str() != Some("")
        {
            object.insert(key.to_string(), field_value.clone());
        }
    }
    for key in ["PremiereDate", "EndDate"] {
        if let Some(field_value) = first_metadata_value_from_json(metadata, &[key]) {
            object.insert(
                key.to_string(),
                serde_json::Value::String(normalize_metadata_date_for_json(&field_value)),
            );
        }
    }
    if let Some(year) = first_metadata_i32_from_json(metadata, &["ProductionYear"]) {
        object.insert("ProductionYear".to_string(), serde_json::json!(year));
    }
    if let Some(primary_tag) = first_metadata_value_from_json(metadata, &["PrimaryImageTag"]) {
        object.insert(
            "ImageTags".to_string(),
            serde_json::json!({ "Primary": primary_tag }),
        );
    }
    if let Some(provider_ids) = json_field_case_insensitive(metadata, "ProviderIds")
        && provider_ids.is_object()
    {
        object.insert("ProviderIds".to_string(), provider_ids.clone());
    }
    if let Some(external_urls) = json_field_case_insensitive(metadata, "ExternalUrls")
        && external_urls.is_array()
    {
        object.insert("ExternalUrls".to_string(), external_urls.clone());
    }
    let people = metadata_people_items_from_json(metadata, &["People"]);
    if !people.is_empty() {
        object.insert("People".to_string(), serde_json::json!(people));
    }
}

fn compare_tv_episodes(left: &MediaItem, right: &MediaItem) -> Ordering {
    compare_tv_episode_items(left, right)
}

fn compare_tv_episodes_with_metadata(
    left: &MediaItem,
    left_metadata: Option<&serde_json::Value>,
    right: &MediaItem,
    right_metadata: Option<&serde_json::Value>,
) -> Ordering {
    let left_info = tv_episode_info(left);
    let right_info = tv_episode_info(right);
    let left_series = left_metadata
        .and_then(|metadata| first_metadata_value_from_json(metadata, &["SeriesName"]))
        .or_else(|| left_info.as_ref().map(|info| info.series_name.clone()))
        .unwrap_or_else(|| left.name.clone())
        .to_ascii_lowercase();
    let right_series = right_metadata
        .and_then(|metadata| first_metadata_value_from_json(metadata, &["SeriesName"]))
        .or_else(|| right_info.as_ref().map(|info| info.series_name.clone()))
        .unwrap_or_else(|| right.name.clone())
        .to_ascii_lowercase();
    left_series
        .cmp(&right_series)
        .then_with(|| {
            first_metadata_i32_from_json(
                left_metadata.unwrap_or(&serde_json::Value::Null),
                &["ParentIndexNumber"],
            )
            .or_else(|| left_info.as_ref().and_then(|info| info.season_number))
            .unwrap_or(i32::MAX)
            .cmp(
                &first_metadata_i32_from_json(
                    right_metadata.unwrap_or(&serde_json::Value::Null),
                    &["ParentIndexNumber"],
                )
                .or_else(|| right_info.as_ref().and_then(|info| info.season_number))
                .unwrap_or(i32::MAX),
            )
        })
        .then_with(|| {
            first_metadata_i32_from_json(
                left_metadata.unwrap_or(&serde_json::Value::Null),
                &["IndexNumber"],
            )
            .or_else(|| left_info.as_ref().and_then(|info| info.episode_number))
            .unwrap_or(i32::MAX)
            .cmp(
                &first_metadata_i32_from_json(
                    right_metadata.unwrap_or(&serde_json::Value::Null),
                    &["IndexNumber"],
                )
                .or_else(|| right_info.as_ref().and_then(|info| info.episode_number))
                .unwrap_or(i32::MAX),
            )
        })
        .then_with(|| {
            left.name
                .to_ascii_lowercase()
                .cmp(&right.name.to_ascii_lowercase())
        })
        .then_with(|| left.id.cmp(&right.id))
}

#[derive(Debug, Deserialize)]
struct DisplayPreferencesQuery {
    #[serde(flatten)]
    auth: AuthQuery,
    #[serde(alias = "UserId", alias = "userId", alias = "user_id")]
    user_id: Option<String>,
    #[serde(alias = "Client", alias = "client")]
    client: Option<String>,
}

async fn display_preferences(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<DisplayPreferencesQuery>,
) -> Result<Json<serde_json::Value>, ApiError> {
    display_preferences_for_id(state, headers, query, "usersettings").await
}

async fn display_preferences_by_id(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<DisplayPreferencesQuery>,
    Path(display_preferences_id): Path<String>,
) -> Result<Json<serde_json::Value>, ApiError> {
    display_preferences_for_id(state, headers, query, &display_preferences_id).await
}

async fn display_preferences_for_id(
    state: AppState,
    headers: HeaderMap,
    query: DisplayPreferencesQuery,
    display_preferences_id: &str,
) -> Result<Json<serde_json::Value>, ApiError> {
    let auth_user =
        require_request_user(&state.db, &headers, query.auth.api_key.as_deref()).await?;
    let user_id = match query.user_id.as_deref() {
        Some(user_id) => resolve_user_id(user_id)?,
        None => auth_user.id,
    };
    ensure_user_access(&auth_user, user_id)?;
    let client = display_preferences_client(query.client.as_deref());
    let preferences = state
        .db
        .display_preferences(user_id, &client, display_preferences_id)
        .await?
        .unwrap_or_else(|| default_display_preferences(display_preferences_id));
    Ok(Json(complete_display_preferences(
        preferences,
        display_preferences_id,
    )?))
}

async fn update_display_preferences(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<DisplayPreferencesQuery>,
    Json(payload): Json<serde_json::Value>,
) -> Result<StatusCode, ApiError> {
    update_display_preferences_for_id_inner(state, headers, query, payload, "usersettings").await
}

async fn update_display_preferences_by_id(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<DisplayPreferencesQuery>,
    Path(display_preferences_id): Path<String>,
    Json(payload): Json<serde_json::Value>,
) -> Result<StatusCode, ApiError> {
    update_display_preferences_for_id_inner(state, headers, query, payload, &display_preferences_id)
        .await
}

async fn update_display_preferences_for_id_inner(
    state: AppState,
    headers: HeaderMap,
    query: DisplayPreferencesQuery,
    payload: serde_json::Value,
    display_preferences_id: &str,
) -> Result<StatusCode, ApiError> {
    let auth_user =
        require_request_user(&state.db, &headers, query.auth.api_key.as_deref()).await?;
    let user_id = match query.user_id.as_deref() {
        Some(user_id) => resolve_user_id(user_id)?,
        None => auth_user.id,
    };
    ensure_user_access(&auth_user, user_id)?;
    let client = display_preferences_client(query.client.as_deref());
    let preferences = normalize_display_preferences_payload(payload, display_preferences_id)?;
    state
        .db
        .update_display_preferences(
            user_id,
            &client,
            display_preferences_id,
            complete_display_preferences(preferences, display_preferences_id)?,
        )
        .await?;
    Ok(StatusCode::NO_CONTENT)
}

fn display_preferences_client(client: Option<&str>) -> String {
    client
        .filter(|client| !client.trim().is_empty())
        .unwrap_or("emby")
        .to_string()
}

fn normalize_display_preferences_payload(
    payload: serde_json::Value,
    id: &str,
) -> Result<serde_json::Value, ApiError> {
    let mut preferences = match payload {
        serde_json::Value::Object(map) => serde_json::Value::Object(map),
        _ => {
            return Err(ApiError::bad_request(
                "Display preferences body must be an object",
            ));
        }
    };
    preferences["Id"] = serde_json::Value::String(id.to_string());
    Ok(preferences)
}

fn complete_display_preferences(
    mut preferences: serde_json::Value,
    id: &str,
) -> Result<serde_json::Value, ApiError> {
    let Some(map) = preferences.as_object_mut() else {
        return Err(ApiError::bad_request(
            "Display preferences body must be an object",
        ));
    };

    map.entry("Id".to_string())
        .or_insert_with(|| serde_json::Value::String(id.to_string()));
    map.entry("ViewType".to_string())
        .or_insert_with(|| serde_json::Value::String(String::new()));
    map.entry("SortBy".to_string())
        .or_insert_with(|| serde_json::Value::String("SortName".to_string()));
    map.entry("IndexBy".to_string())
        .or_insert_with(|| serde_json::Value::String(String::new()));
    map.entry("RememberIndexing".to_string())
        .or_insert_with(|| serde_json::Value::Bool(false));
    map.entry("PrimaryImageHeight".to_string())
        .or_insert_with(|| serde_json::Value::Number(0.into()));
    map.entry("PrimaryImageWidth".to_string())
        .or_insert_with(|| serde_json::Value::Number(0.into()));
    map.entry("CustomPrefs".to_string())
        .or_insert_with(|| serde_json::Value::Object(Default::default()));
    map.entry("ScrollDirection".to_string())
        .or_insert_with(|| serde_json::Value::String("Vertical".to_string()));
    map.entry("ShowBackdrop".to_string())
        .or_insert_with(|| serde_json::Value::Bool(true));
    map.entry("RememberSorting".to_string())
        .or_insert_with(|| serde_json::Value::Bool(false));
    map.entry("SortOrder".to_string())
        .or_insert_with(|| serde_json::Value::String("Ascending".to_string()));
    map.entry("ShowSidebar".to_string())
        .or_insert_with(|| serde_json::Value::Bool(true));

    Ok(preferences)
}

fn default_display_preferences(id: &str) -> serde_json::Value {
    complete_display_preferences(
        serde_json::json!({
            "Id": id,
            "ViewType": "",
            "SortBy": "SortName",
            "IndexBy": "",
            "RememberIndexing": false,
            "PrimaryImageHeight": 0,
            "PrimaryImageWidth": 0,
            "CustomPrefs": {}
        }),
        id,
    )
    .expect("default display preferences are valid")
}

async fn system_endpoint() -> Json<serde_json::Value> {
    Json(serde_json::json!({
        "IsLocal": true,
        "IsInNetwork": true
    }))
}

#[derive(Debug, Deserialize)]
struct BitrateQuery {
    #[serde(flatten)]
    auth: AuthQuery,
    #[serde(alias = "Size")]
    size: Option<usize>,
}

async fn bitrate_test(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<BitrateQuery>,
) -> Result<impl IntoResponse, ApiError> {
    require_request_user(&state.db, &headers, query.auth.api_key.as_deref()).await?;
    let size = query.size.unwrap_or_default().min(1_000_000);
    Ok((
        [(header::CONTENT_TYPE, "application/octet-stream")],
        vec![0u8; size],
    ))
}

async fn item_placeholder_image(
    State(state): State<AppState>,
    method: axum::http::Method,
    headers: HeaderMap,
    Query(size): Query<ImageResizeQuery>,
    Path((item_id, image_type)): Path<(String, String)>,
) -> Result<axum::response::Response, ApiError> {
    let resize = size.normalized();
    let response = item_image_or_placeholder(
        &state,
        &item_id,
        &image_type,
        0,
        ItemImageRequest {
            resize,
            headers: &headers,
            query_token: size.api_key.as_deref(),
            allow_plugin_vod_fill: method == axum::http::Method::GET,
        },
    )
    .await?;
    Ok(conditional_image_response(&headers, response))
}

