async fn item_image_infos(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    Path(item_id): Path<String>,
) -> Result<Json<Vec<serde_json::Value>>, ApiError> {
    require_request_user(&state.db, &headers, query.api_key.as_deref()).await?;
    if let Some(item) = live_tv_item_for_image(&state.db, &item_id).await? {
        return Ok(Json(
            live_tv_item_primary_image_info(&item)
                .map(|info| vec![info])
                .unwrap_or_default(),
        ));
    }
    if let Some(channel_item) = channel_content_item_by_id(&state.db, &item_id).await? {
        return Ok(Json(channel_item_image_infos(&channel_item)?));
    }
    let metadata_entity = ensure_image_item_owner_exists(&state.db, &item_id).await?;
    let mut infos = stored_image_infos(&state, ImageOwner::Item(&item_id)).await?;
    if !image_infos_include(&infos, "Primary", 0)
        && let Some(info) = representative_item_primary_image_info(&state, &item_id).await?
    {
        infos.push(info);
    }
    if !image_infos_include(&infos, "Primary", 0)
        && let Some(entity) = metadata_entity.as_ref()
        && let Some(path) = metadata_entity_image_path(entity, "Primary", 0).await?
    {
        infos.push(item_image_info_from_path("Primary", 0, path).await?);
    }
    if !image_infos_include(&infos, "Primary", 0)
        && let Some(entity) = metadata_entity.as_ref()
        && let Some(path) =
            find_named_entity_representative_image(&state, &entity.name, "Primary", 0).await?
    {
        infos.push(item_image_info_from_path("Primary", 0, path).await?);
    }
    if infos.is_empty()
        && let Ok(requested_id) = parse_jellyfin_uuid(&item_id)
        && let Ok(list) = state.db.media_list_by_id(requested_id).await
    {
        if let Some(path) = metadata_image_path_from_json(&list.metadata, "Primary", 0)
            && let Ok(info) = item_image_info_from_path("Primary", 0, path).await
        {
            infos.push(info);
        }
        if infos.is_empty() {
            infos.push(virtual_primary_image_info(&item_id));
        }
    }
    Ok(Json(infos))
}

fn virtual_primary_image_info(item_id: &str) -> serde_json::Value {
    serde_json::json!({
        "ImageType": "Primary",
        "ImageIndex": 0,
        "ImageTag": default_primary_image_tag(item_id),
        "Size": 0,
        "MimeType": "image/png",
    })
}

async fn item_remote_images(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<RemoteImageQuery>,
    Path(item_id): Path<String>,
) -> Result<Json<serde_json::Value>, ApiError> {
    require_request_user(&state.db, &headers, query.auth.api_key.as_deref()).await?;
    let images = match media_item_by_id(&state.db, &item_id).await {
        Ok(item) => {
            let mut images =
                remote_image_candidates(&state.db, &item, query.image_type.as_deref()).await?;
            images.extend(
                stored_remote_image_candidates(&state, &item_id, query.image_type.as_deref())
                    .await?,
            );
            dedupe_remote_images(images)
        }
        Err(error) if error.status == StatusCode::NOT_FOUND => {
            ensure_image_item_owner_exists(&state.db, &item_id).await?;
            let mut images =
                if let Some(summary) = tv_series_summary_by_id(&state.db, &item_id, None).await? {
                    metadata_remote_image_candidates(
                        &item_id,
                        &summary.metadata,
                        query.image_type.as_deref(),
                    )
                } else {
                    Vec::new()
                };
            images.extend(
                stored_remote_image_candidates(&state, &item_id, query.image_type.as_deref())
                    .await?,
            );
            dedupe_remote_images(images)
        }
        Err(error) => return Err(error),
    };
    Ok(Json(remote_image_query_result(images)))
}

fn remote_image_query_result(images: Vec<serde_json::Value>) -> serde_json::Value {
    let providers = remote_image_provider_names(&images);
    let total_record_count = images.len();
    serde_json::json!({
        "TotalRecordCount": total_record_count,
        "StartIndex": 0,
        "Items": images,
        "Images": images,
        "Providers": providers,
    })
}

fn dedupe_remote_images(images: Vec<serde_json::Value>) -> Vec<serde_json::Value> {
    let mut seen = std::collections::HashSet::new();
    images
        .into_iter()
        .filter(|image| {
            let key = image
                .get("ImageUrl")
                .or_else(|| image.get("Url"))
                .and_then(serde_json::Value::as_str)
                .unwrap_or_default()
                .to_string();
            seen.insert(key)
        })
        .collect()
}

fn remote_image_provider_names(images: &[serde_json::Value]) -> Vec<String> {
    let mut providers = images
        .iter()
        .filter_map(|image| {
            image
                .get("ProviderName")
                .and_then(serde_json::Value::as_str)
                .map(str::to_string)
        })
        .collect::<Vec<_>>();
    providers.sort();
    providers.dedup();
    providers
}

async fn item_remote_image_providers(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    Path(item_id): Path<String>,
) -> Result<Json<Vec<serde_json::Value>>, ApiError> {
    require_request_user(&state.db, &headers, query.api_key.as_deref()).await?;
    ensure_image_item_owner_exists(&state.db, &item_id).await?;
    let mut providers = vec![serde_json::json!({
        "Name": "Local cache",
        "SupportedImages": ["Primary", "Backdrop", "Thumb", "Logo"],
    })];
    if let Some(provider_name) =
        metadata_remote_image_provider_for_item(&state.db, &item_id).await?
        && !providers.iter().any(|provider| {
            provider
                .get("Name")
                .and_then(serde_json::Value::as_str)
                .is_some_and(|name| name == provider_name)
        })
    {
        providers.push(serde_json::json!({
            "Name": provider_name,
            "SupportedImages": ["Primary", "Backdrop", "Thumb", "Logo"],
        }));
    }
    providers.extend(plugin_image_provider_infos(&state.db).await?);
    Ok(Json(providers))
}

async fn metadata_remote_image_provider_for_item(
    db: &Database,
    item_id: &str,
) -> Result<Option<String>, ApiError> {
    let metadata = match media_item_by_id(db, item_id).await {
        Ok(item) => metadata_payload_for_item(db, item.id).await?,
        Err(error) if error.status == StatusCode::NOT_FOUND => {
            let Some(summary) = tv_series_summary_by_id(db, item_id, None).await? else {
                return Ok(None);
            };
            summary.metadata
        }
        Err(error) => return Err(error),
    };
    if metadata_remote_image_candidates(item_id, &metadata, None).is_empty() {
        Ok(None)
    } else {
        Ok(Some(remote_image_provider_name(&metadata)))
    }
}

async fn download_remote_image(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<RemoteImageDownloadQuery>,
    Path(item_id): Path<String>,
    body: Option<Json<serde_json::Value>>,
) -> Result<StatusCode, ApiError> {
    require_admin(&state.db, &headers, query.auth.api_key.as_deref()).await?;
    ensure_image_item_owner_exists(&state.db, &item_id).await?;
    let payload = body.as_ref().map(|body| &body.0);
    let empty_payload = serde_json::Value::Null;
    let payload = payload.unwrap_or(&empty_payload);
    let body_image_url = json_string_any_field(payload, &["ImageUrl", "imageUrl", "Url", "url"]);
    let Some(image_id) = query.image_url.as_deref().or(body_image_url.as_deref()) else {
        return Ok(StatusCode::NO_CONTENT);
    };
    let image_id = remote_image_download_id_from_url(image_id);
    let body_image_type =
        json_string_any_field(payload, &["ImageType", "imageType", "Type", "type"]);
    let image_type = query
        .image_type
        .as_deref()
        .or(body_image_type.as_deref())
        .unwrap_or("Primary");
    if remote_image_url_is_existing_item_image(&image_id) {
        return Ok(StatusCode::NO_CONTENT);
    }
    if let Some((bytes, _mime_type)) = plugin_remote_image_payload_from_id(&image_id)? {
        install_remote_image_bytes(&state, &item_id, bytes, image_type).await?;
    } else if let Some((url, _mime_type)) = remote_url_image_payload_from_id(&image_id)? {
        let bytes = fetch_remote_image_bytes(&url).await?;
        install_remote_image_bytes(&state, &item_id, bytes, image_type).await?;
    } else {
        let remote_path = remote_image_path_from_id(&image_id).await?;
        install_remote_image(&state, &item_id, &remote_path, image_type).await?;
    }
    Ok(StatusCode::NO_CONTENT)
}

async fn remote_image_preview(
    State(state): State<AppState>,
    Query(query): Query<RemoteImagePreviewQuery>,
    Path(item_id): Path<String>,
) -> Result<axum::response::Response, ApiError> {
    ensure_image_item_owner_exists(&state.db, &item_id).await?;
    let image_id = remote_image_download_id_from_url(&query.image_url);
    if let Some((bytes, mime_type)) = plugin_remote_image_payload_from_id(&image_id)? {
        let mut headers = HeaderMap::new();
        headers.insert(header::CONTENT_TYPE, mime_type.parse().unwrap());
        headers.insert(
            header::CACHE_CONTROL,
            "public, max-age=3600".parse().unwrap(),
        );
        return Ok((headers, bytes).into_response());
    }
    if let Some((url, fallback_mime_type)) = remote_url_image_payload_from_id(&image_id)? {
        let (bytes, mime_type) = fetch_remote_image_payload(&url).await?;
        let mut headers = HeaderMap::new();
        headers.insert(
            header::CONTENT_TYPE,
            mime_type
                .unwrap_or(fallback_mime_type)
                .parse()
                .unwrap_or_else(|_| "application/octet-stream".parse().unwrap()),
        );
        headers.insert(
            header::CACHE_CONTROL,
            "public, max-age=3600".parse().unwrap(),
        );
        return Ok((headers, bytes).into_response());
    }
    let remote_path = remote_image_path_from_id(&image_id).await?;
    stored_image_response(remote_path).await
}

#[derive(Debug, Deserialize)]
struct RemoteImageQuery {
    #[serde(flatten)]
    auth: AuthQuery,
    #[serde(
        alias = "ImageType",
        alias = "imageType",
        alias = "Type",
        alias = "type"
    )]
    image_type: Option<String>,
}

#[derive(Debug, Deserialize)]
struct RemoteImageDownloadQuery {
    #[serde(flatten)]
    auth: AuthQuery,
    #[serde(alias = "ImageUrl", alias = "imageUrl", alias = "Url", alias = "url")]
    image_url: Option<String>,
    #[serde(
        alias = "ImageType",
        alias = "imageType",
        alias = "Type",
        alias = "type"
    )]
    image_type: Option<String>,
}

#[derive(Debug, Deserialize)]
struct RemoteImagePreviewQuery {
    #[serde(alias = "ImageUrl", alias = "imageUrl", alias = "Url", alias = "url")]
    image_url: String,
}

async fn remote_image_candidates(
    db: &Database,
    item: &MediaItem,
    requested_image_type: Option<&str>,
) -> Result<Vec<serde_json::Value>, ApiError> {
    let mut images = plugin_remote_image_candidates(db, item, requested_image_type).await?;
    let metadata = metadata_payload_for_item(db, item.id).await?;
    let policy = metadata_provider_policy(db, media_item_type(item), true).await?;
    if policy.allows("", &remote_image_provider_name(&metadata)) {
        images.extend(metadata_remote_image_candidates(
            &item.id.simple().to_string(),
            &metadata,
            requested_image_type,
        ));
    }
    let Some(item_dir) = media_item_path(item).parent() else {
        return Ok(images);
    };
    let remote_dir = item_dir.join(".jellyrin-remote-images");
    let mut entries = match tokio::fs::read_dir(&remote_dir).await {
        Ok(entries) => entries,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(images),
        Err(error) if error.kind() == std::io::ErrorKind::NotADirectory => return Ok(images),
        Err(error) => return Err(error.into()),
    };
    let requested_image_type = requested_image_type.map(normalize_image_type);
    while let Some(entry) = entries.next_entry().await? {
        let path = entry.path();
        if !is_supported_remote_image_path(&path) {
            continue;
        }
        let metadata = match entry.metadata().await {
            Ok(metadata) if metadata.is_file() => metadata,
            Ok(_) => continue,
            Err(_) => continue,
        };
        let canonical_path = tokio::fs::canonicalize(path).await?;
        let image_type = remote_image_type_from_path(&canonical_path);
        if requested_image_type
            .as_deref()
            .is_some_and(|requested| requested != image_type)
        {
            continue;
        }
        let name = entry.file_name().to_string_lossy().into_owned();
        let extension = canonical_path
            .extension()
            .and_then(|extension| extension.to_str())
            .unwrap_or_default();
        let item_id = item.id.simple().to_string();
        let image_id = remote_image_id_for_path(&canonical_path);
        let preview_url = remote_image_preview_url(&item_id, &image_id);
        images.push(serde_json::json!({
            "ProviderName": "Local cache",
            "ImageUrl": image_id,
            "Url": preview_url,
            "ThumbnailUrl": preview_url,
            "Name": name,
            "Type": canonical_image_type(&image_type),
            "Language": null,
            "RatingType": "Score",
            "CommunityRating": null,
            "VoteCount": null,
            "Width": null,
            "Height": null,
            "Size": metadata.len(),
            "MimeType": image_format_from_extension(extension).content_type,
        }));
    }
    images.sort_by_key(|image| {
        image
            .get("Name")
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default()
            .to_ascii_lowercase()
    });
    Ok(images)
}

fn metadata_remote_image_candidates(
    item_id: &str,
    metadata: &serde_json::Value,
    requested_image_type: Option<&str>,
) -> Vec<serde_json::Value> {
    let requested_image_type = requested_image_type.map(canonical_image_type);
    let mut images = Vec::new();
    for (image_type, keys) in [
        (
            "Primary",
            &[
                "PrimaryImageUrl",
                "SeriesPrimaryImageUrl",
                "ImageUrl",
                "SeriesImageUrl",
            ][..],
        ),
        (
            "Backdrop",
            &[
                "BackdropImageUrl",
                "SeriesBackdropImageUrl",
                "BackgroundImageUrl",
                "SeriesBackgroundImageUrl",
            ][..],
        ),
        (
            "Thumb",
            &["ThumbImageUrl", "SeriesThumbImageUrl", "BannerImageUrl"][..],
        ),
        ("Logo", &["LogoImageUrl", "SeriesLogoImageUrl"][..]),
    ] {
        if requested_image_type
            .as_deref()
            .is_some_and(|requested| requested != image_type)
        {
            continue;
        }
        for url in metadata_values_from_json(metadata, keys) {
            if !remote_image_url_is_fetchable(&url) {
                continue;
            }
            let image_id = remote_url_image_id(&url, None);
            let preview_url = remote_image_preview_url(item_id, &image_id);
            images.push(serde_json::json!({
                "ProviderName": remote_image_provider_name(metadata),
                "ImageUrl": image_id,
                "Url": preview_url,
                "ThumbnailUrl": preview_url,
                "Name": format!("{} {}", remote_image_provider_name(metadata), image_type),
                "Type": image_type,
                "Language": null,
                "RatingType": "Score",
                "CommunityRating": null,
                "VoteCount": null,
                "Width": null,
                "Height": null,
                "Size": null,
                "MimeType": null,
            }));
        }
    }
    images
}

fn remote_image_provider_name(metadata: &serde_json::Value) -> String {
    json_string_field(metadata, "MetadataSource")
        .or_else(|| json_string_field(metadata, "SearchProviderName"))
        .unwrap_or_else(|| "Remote metadata".to_string())
}

async fn stored_remote_image_candidates(
    state: &AppState,
    item_id: &str,
    requested_image_type: Option<&str>,
) -> Result<Vec<serde_json::Value>, ApiError> {
    let requested_image_type = requested_image_type.map(canonical_image_type);
    let infos = stored_image_infos(state, ImageOwner::Item(item_id)).await?;
    let mut images = Vec::new();
    for info in infos {
        let image_type = info
            .get("ImageType")
            .and_then(serde_json::Value::as_str)
            .unwrap_or("Primary")
            .to_string();
        if requested_image_type
            .as_deref()
            .is_some_and(|requested| requested != image_type)
        {
            continue;
        }
        let Some(path) = info.get("Path").and_then(serde_json::Value::as_str) else {
            continue;
        };
        let bytes = tokio::fs::read(path).await?;
        if bytes.is_empty() {
            continue;
        }
        let mime_type = info
            .get("MimeType")
            .and_then(serde_json::Value::as_str)
            .unwrap_or("application/octet-stream")
            .to_string();
        let preview_url = item_image_url(item_id, &image_type);
        images.push(serde_json::json!({
            "ProviderName": "Local cache",
            "ImageUrl": preview_url,
            "Url": preview_url,
            "ThumbnailUrl": preview_url,
            "Name": format!("Cached {image_type}"),
            "Type": image_type,
            "Language": null,
            "RatingType": "Score",
            "CommunityRating": null,
            "VoteCount": null,
            "Width": null,
            "Height": null,
            "Size": bytes.len(),
            "MimeType": mime_type,
        }));
    }
    Ok(images)
}

async fn plugin_image_provider_infos(db: &Database) -> Result<Vec<serde_json::Value>, ApiError> {
    Ok(db
        .installed_plugins_json()
        .await?
        .into_iter()
        .filter(plugin_is_active_image_provider)
        .map(|plugin| {
            serde_json::json!({
                "Name": json_string_field(&plugin, "Name").unwrap_or_else(|| "Plugin Image Provider".to_string()),
                "SupportedImages": ["Primary", "Backdrop", "Thumb", "Logo"],
            })
        })
        .collect())
}

async fn plugin_remote_image_candidates(
    db: &Database,
    item: &MediaItem,
    requested_image_type: Option<&str>,
) -> Result<Vec<serde_json::Value>, ApiError> {
    let mut images = Vec::new();
    let requested_image_type = requested_image_type.map(canonical_image_type);
    let item_type = media_item_type(item);
    let policy = metadata_provider_policy(db, item_type, true).await?;
    let mut plugins = db.installed_plugins_json().await?;
    plugins.sort_by(|left, right| {
        policy.compare(
            &json_string_field(left, "Name").unwrap_or_default(),
            json_i64_field(left, "Priority").unwrap_or(1_000),
            &json_string_field(right, "Name").unwrap_or_default(),
            json_i64_field(right, "Priority").unwrap_or(1_000),
        )
    });
    for plugin in plugins {
        if !plugin_is_active_image_provider(&plugin) {
            continue;
        }
        let provider_id = json_string_field(&plugin, "Id").unwrap_or_default();
        let provider_name = json_string_field(&plugin, "Name").unwrap_or_else(|| {
            if provider_id.is_empty() {
                "Plugin Image Provider".to_string()
            } else {
                provider_id.clone()
            }
        });
        if !policy.allows(&provider_id, &provider_name) {
            continue;
        }
        let capability = invoke_installed_plugin_capability_via_runtime_host(
            db,
            &plugin,
            "ImageProvider",
            serde_json::json!({
                "ItemId": item.id.simple().to_string(),
                "ItemName": item.name,
                "ItemType": item_type,
                "ImageType": requested_image_type.as_deref(),
            }),
        )
        .await?;
        let Some(capability) = capability else {
            continue;
        };
        images.extend(plugin_remote_image_candidate_values(
            &item.id.simple().to_string(),
            &provider_name,
            requested_image_type.as_deref(),
            &capability.value,
        )?);
    }
    Ok(images)
}

fn plugin_is_active_image_provider(plugin: &serde_json::Value) -> bool {
    json_string_field(plugin, "Status").as_deref() == Some("Active")
        && plugin_string_array(plugin.get("Capabilities"))
            .iter()
            .any(|capability| capability.eq_ignore_ascii_case("ImageProvider"))
}

fn plugin_remote_image_candidate_values(
    item_id: &str,
    provider_name: &str,
    requested_image_type: Option<&str>,
    value: &serde_json::Value,
) -> Result<Vec<serde_json::Value>, ApiError> {
    let values = value
        .get("Images")
        .or_else(|| value.get("Items"))
        .or_else(|| value.get("Results"))
        .and_then(serde_json::Value::as_array)
        .cloned()
        .unwrap_or_else(|| vec![value.clone()]);
    let mut images = Vec::new();
    for value in values {
        let image_type = json_string_any_field(&value, &["ImageType", "Type", "type"])
            .map(|value| canonical_image_type(&value))
            .unwrap_or_else(|| "Primary".to_string());
        if requested_image_type.is_some_and(|requested| requested != image_type.as_str()) {
            continue;
        }
        let Some(base64_data) =
            json_string_field(&value, "Base64Data").or_else(|| json_string_field(&value, "Data"))
        else {
            continue;
        };
        let mime_type = json_string_field(&value, "MimeType")
            .or_else(|| json_string_field(&value, "ContentType"))
            .unwrap_or_else(|| "application/octet-stream".to_string());
        let bytes = general_purpose::STANDARD
            .decode(base64_data.as_bytes())
            .map_err(|error| ApiError::internal(format!("Plugin image payload failed: {error}")))?;
        if bytes.is_empty() {
            continue;
        }
        let size = bytes.len();
        let image_id = plugin_remote_image_id(&bytes, &mime_type);
        let preview_url = remote_image_preview_url(item_id, &image_id);
        images.push(serde_json::json!({
            "ProviderName": provider_name,
            "ImageUrl": image_id,
            "Url": preview_url,
            "ThumbnailUrl": preview_url,
            "Name": json_string_field(&value, "Name").unwrap_or_else(|| format!("{provider_name} {image_type}")),
            "Type": image_type,
            "Language": null,
            "RatingType": "Score",
            "CommunityRating": value.get("CommunityRating").cloned().unwrap_or(serde_json::Value::Null),
            "VoteCount": value.get("VoteCount").cloned().unwrap_or(serde_json::Value::Null),
            "Width": value.get("Width").cloned().unwrap_or(serde_json::Value::Null),
            "Height": value.get("Height").cloned().unwrap_or(serde_json::Value::Null),
            "Size": size,
            "MimeType": mime_type,
        }));
    }
    Ok(images)
}

async fn install_remote_image(
    state: &AppState,
    item_id: &str,
    remote_path: &FsPath,
    image_type: &str,
) -> Result<(), ApiError> {
    let bytes = tokio::fs::read(remote_path).await?;
    if bytes.is_empty() {
        return Err(ApiError::bad_request("Remote image file is empty"));
    }
    if bytes.len() > IMAGE_UPLOAD_LIMIT_BYTES {
        return Err(ApiError::bad_request("Remote image file is too large"));
    }
    install_remote_image_bytes(state, item_id, bytes, image_type).await
}

async fn install_remote_image_bytes(
    state: &AppState,
    item_id: &str,
    bytes: Vec<u8>,
    image_type: &str,
) -> Result<(), ApiError> {
    if bytes.is_empty() {
        return Err(ApiError::bad_request("Remote image file is empty"));
    }
    if bytes.len() > IMAGE_UPLOAD_LIMIT_BYTES {
        return Err(ApiError::bad_request("Remote image file is too large"));
    }
    store_image_bytes(state, ImageOwner::Item(item_id), image_type, 0, bytes).await
}

fn plugin_remote_image_id(bytes: &[u8], mime_type: &str) -> String {
    let payload = serde_json::json!({
        "MimeType": mime_type,
        "Base64Data": general_purpose::STANDARD.encode(bytes),
    });
    format!(
        "plugin-image:{}",
        general_purpose::URL_SAFE_NO_PAD.encode(payload.to_string().as_bytes())
    )
}

fn plugin_remote_image_payload_from_id(
    image_id: &str,
) -> Result<Option<(Vec<u8>, String)>, ApiError> {
    let Some(encoded) = image_id.strip_prefix("plugin-image:") else {
        return Ok(None);
    };
    let payload = general_purpose::URL_SAFE_NO_PAD
        .decode(encoded)
        .map_err(|_| ApiError::not_found("Remote image not found"))?;
    let payload: serde_json::Value = serde_json::from_slice(&payload)
        .map_err(|_| ApiError::not_found("Remote image not found"))?;
    let Some(base64_data) = json_string_field(&payload, "Base64Data") else {
        return Err(ApiError::not_found("Remote image not found"));
    };
    let bytes = general_purpose::STANDARD
        .decode(base64_data.as_bytes())
        .map_err(|_| ApiError::not_found("Remote image not found"))?;
    let mime_type = json_string_field(&payload, "MimeType")
        .unwrap_or_else(|| "application/octet-stream".to_string());
    Ok(Some((bytes, mime_type)))
}

fn remote_url_image_id(url: &str, mime_type: Option<&str>) -> String {
    let payload = serde_json::json!({
        "Url": url,
        "MimeType": mime_type.unwrap_or("application/octet-stream"),
    });
    format!(
        "remote-url-image:{}",
        general_purpose::URL_SAFE_NO_PAD.encode(payload.to_string().as_bytes())
    )
}

fn remote_url_image_payload_from_id(image_id: &str) -> Result<Option<(String, String)>, ApiError> {
    let Some(encoded) = image_id.strip_prefix("remote-url-image:") else {
        return Ok(None);
    };
    let payload = general_purpose::URL_SAFE_NO_PAD
        .decode(encoded)
        .map_err(|_| ApiError::not_found("Remote image not found"))?;
    let payload: serde_json::Value = serde_json::from_slice(&payload)
        .map_err(|_| ApiError::not_found("Remote image not found"))?;
    let Some(url) = json_string_field(&payload, "Url") else {
        return Err(ApiError::not_found("Remote image not found"));
    };
    if !remote_image_url_is_fetchable(&url) {
        return Err(ApiError::not_found("Remote image not found"));
    }
    let mime_type = json_string_field(&payload, "MimeType")
        .unwrap_or_else(|| "application/octet-stream".to_string());
    Ok(Some((url, mime_type)))
}

fn remote_image_id_for_path(path: &FsPath) -> String {
    format!(
        "local-image:{}",
        general_purpose::URL_SAFE_NO_PAD.encode(path.to_string_lossy().as_bytes())
    )
}

fn remote_image_preview_url(item_id: &str, image_id: &str) -> String {
    format!(
        "/Items/{item_id}/RemoteImages/Preview?ImageUrl={}",
        query_percent_encode(image_id)
    )
}

fn item_image_url(item_id: &str, image_type: &str) -> String {
    format!(
        "/Items/{item_id}/Images/{}",
        query_path_segment_encode(image_type)
    )
}

fn remote_image_download_id_from_url(image_url: &str) -> String {
    if image_url.starts_with("plugin-image:")
        || image_url.starts_with("local-image:")
        || image_url.starts_with("remote-url-image:")
    {
        return image_url.to_string();
    }
    let parsed_url = if image_url.starts_with('/') {
        reqwest::Url::parse(&format!("http://127.0.0.1{image_url}")).ok()
    } else {
        reqwest::Url::parse(image_url).ok()
    };
    parsed_url
        .and_then(|url| {
            let path = url.path().to_ascii_lowercase();
            if !path.ends_with("/remoteimages/preview") {
                return None;
            }
            url.query_pairs().find_map(|(key, value)| {
                matches!(key.as_ref(), "ImageUrl" | "imageUrl" | "Url" | "url")
                    .then(|| value.into_owned())
            })
        })
        .unwrap_or_else(|| image_url.to_string())
}

fn remote_image_url_is_existing_item_image(image_url: &str) -> bool {
    let parsed_url = if image_url.starts_with('/') {
        reqwest::Url::parse(&format!("http://127.0.0.1{image_url}")).ok()
    } else {
        reqwest::Url::parse(image_url).ok()
    };
    parsed_url
        .map(|url| {
            let path = url.path().to_ascii_lowercase();
            path.contains("/items/") && path.contains("/images/")
        })
        .unwrap_or(false)
}

fn remote_image_url_is_fetchable(image_url: &str) -> bool {
    validated_remote_image_url(image_url).is_ok()
}

fn query_percent_encode(value: &str) -> String {
    let mut encoded = String::with_capacity(value.len());
    for byte in value.bytes() {
        match byte {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'.' | b'_' | b'~' => {
                encoded.push(byte as char);
            }
            _ => encoded.push_str(&format!("%{byte:02X}")),
        }
    }
    encoded
}

fn query_path_segment_encode(value: &str) -> String {
    query_percent_encode(value).replace("%2F", "%252F")
}

async fn remote_image_path_from_id(image_id: &str) -> Result<PathBuf, ApiError> {
    let encoded = image_id
        .strip_prefix("local-image:")
        .ok_or_else(|| ApiError::not_found("Remote image not found"))?;
    let bytes = general_purpose::URL_SAFE_NO_PAD
        .decode(encoded)
        .map_err(|_| ApiError::not_found("Remote image not found"))?;
    let path =
        String::from_utf8(bytes).map_err(|_| ApiError::not_found("Remote image not found"))?;
    let canonical_path = tokio::fs::canonicalize(PathBuf::from(path))
        .await
        .map_err(|_| ApiError::not_found("Remote image not found"))?;
    if !is_supported_remote_image_path(&canonical_path)
        || !path_contains_component(&canonical_path, ".jellyrin-remote-images")
    {
        return Err(ApiError::not_found("Remote image not found"));
    }
    Ok(canonical_path)
}

fn is_supported_remote_image_path(path: &FsPath) -> bool {
    path.extension()
        .and_then(|extension| extension.to_str())
        .map(|extension| {
            matches!(
                extension.to_ascii_lowercase().as_str(),
                "png" | "jpg" | "jpeg" | "webp" | "gif"
            )
        })
        .unwrap_or(false)
}

fn remote_image_type_from_path(path: &FsPath) -> String {
    let stem = path
        .file_stem()
        .and_then(|stem| stem.to_str())
        .unwrap_or_default()
        .to_ascii_lowercase();
    if stem.contains("backdrop") || stem.contains("fanart") || stem.contains("background") {
        "backdrop".to_string()
    } else if stem.contains("thumb") {
        "thumb".to_string()
    } else if stem.contains("logo") {
        "logo".to_string()
    } else {
        "primary".to_string()
    }
}

fn normalize_image_type(image_type: &str) -> String {
    sanitize_image_path_segment(image_type)
}

async fn user_exists(db: &Database, user_id: Uuid) -> Result<(), ApiError> {
    if db.users().await?.into_iter().any(|user| user.id == user_id) {
        Ok(())
    } else {
        Err(ApiError::not_found("User not found"))
    }
}

fn parse_image_index(image_index: &str) -> Result<usize, ApiError> {
    image_index
        .parse::<usize>()
        .map_err(|_| ApiError::bad_request("Invalid image index"))
}

async fn media_item_or_folder_by_id(db: &Database, item_id: &str) -> Result<(), ApiError> {
    let requested_id = parse_jellyfin_uuid(item_id)?;
    if MediaCatalogStore::media_item_exists(db, requested_id).await? {
        return Ok(());
    }
    if db
        .virtual_folders()
        .await?
        .into_iter()
        .any(|folder| folder.id == requested_id)
    {
        return Ok(());
    }
    if db.media_list_by_id(requested_id).await.is_ok() {
        return Ok(());
    }
    if virtual_tv_item_exists(db, item_id).await? {
        return Ok(());
    }
    Err(ApiError::not_found("Item not found"))
}

async fn ensure_image_item_owner_exists(
    db: &Database,
    item_id: &str,
) -> Result<Option<MetadataEntityMatch>, ApiError> {
    match media_item_or_folder_by_id(db, item_id).await {
        Ok(()) => Ok(None),
        Err(error) if error.status == StatusCode::NOT_FOUND => {
            if let Some(entity) = metadata_entity_by_stable_id(db, item_id).await? {
                Ok(Some(entity))
            } else {
                Err(error)
            }
        }
        Err(error) => Err(error),
    }
}

fn playback_event_sender() -> &'static broadcast::Sender<PlaybackEvent> {
    PLAYBACK_EVENTS.get_or_init(|| {
        let (sender, _) = broadcast::channel(256);
        sender
    })
}

fn subscribe_playback_events() -> broadcast::Receiver<PlaybackEvent> {
    playback_event_sender().subscribe()
}

fn broadcast_session_message(session_id: &str, mut message: serde_json::Value) {
    if let Some(object) = message.as_object_mut() {
        object
            .entry("MessageId".to_string())
            .or_insert_with(|| serde_json::Value::String(Uuid::new_v4().to_string()));
    }
    let _ = playback_event_sender().send(PlaybackEvent {
        session_id: session_id.to_string(),
        message,
    });
}

async fn broadcast_sessions_message(
    db: &Database,
    session_id: &str,
    user: &User,
) -> Result<(), ApiError> {
    let service = SessionService::new(db);
    broadcast_session_message(
        session_id,
        serde_json::json!({
            "MessageId": Uuid::new_v4().to_string(),
            "MessageType": "Sessions",
            "Data": session_list_json(&service, user).await?
        }),
    );
    Ok(())
}

async fn broadcast_sessions_message_to_user_owned_sessions(
    db: &Database,
    user: &User,
    exclude_session_id: Option<&str>,
) -> Result<(), ApiError> {
    let service = SessionService::new(db);
    let data = session_list_json(&service, user).await?;
    for session in service
        .devices()
        .await?
        .into_iter()
        .filter(|session| session.user_id == user.id)
    {
        if exclude_session_id.is_some_and(|excluded| excluded == session.access_token) {
            continue;
        }
        broadcast_session_message(
            &session.access_token,
            serde_json::json!({
                "MessageId": Uuid::new_v4().to_string(),
                "MessageType": "Sessions",
                "Data": data.clone()
            }),
        );
    }
    Ok(())
}

async fn websocket(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    ws: Result<WebSocketUpgrade, WebSocketUpgradeRejection>,
) -> axum::response::Response {
    let (user, session_id) = match require_user(&state.db, &headers, query.api_key.as_deref()).await
    {
        Ok((user, token)) => (user, token.access_token),
        Err(error) => return error.into_response(),
    };

    match ws {
        Ok(ws) => ws
            .on_upgrade(move |socket| handle_websocket(socket, state, user, session_id))
            .into_response(),
        Err(rejection) => rejection.into_response(),
    }
}

async fn handle_websocket(mut socket: WebSocket, state: AppState, user: User, session_id: String) {
    let _ = socket
        .send(Message::Text(
            serde_json::json!({
                "MessageId": Uuid::new_v4().to_string(),
                "MessageType": "ForceKeepAlive",
                "Data": 60
            })
            .to_string()
            .into(),
        ))
        .await;
    let mut receiver = subscribe_playback_events();
    let service = SessionService::new(&state.db);
    loop {
        tokio::select! {
            event = receiver.recv() => {
                match event {
                    Ok(event) if event.session_id == session_id => {
                        if socket
                            .send(Message::Text(event.message.to_string().into()))
                            .await
                            .is_err()
                        {
                            break;
                        }
                    }
                    Ok(_) => {}
                    Err(broadcast::error::RecvError::Lagged(_)) => {}
                    Err(broadcast::error::RecvError::Closed) => break,
                }
            }
            message = socket.recv() => {
                match message {
                    Some(Ok(Message::Text(text))) => {
                        if should_send_sessions_message(&text) {
                            let sessions = match session_list_json(&service, &user).await {
                                Ok(sessions) => sessions,
                                Err(_) => break,
                            };
                            let message = serde_json::json!({
                                "MessageId": Uuid::new_v4().to_string(),
                                "MessageType": "Sessions",
                                "Data": sessions
                            });
                            if socket
                                .send(Message::Text(message.to_string().into()))
                                .await
                                .is_err()
                            {
                                break;
                            }
                        }
                    }
                    Some(Ok(Message::Close(_))) | None => break,
                    Some(Ok(_)) => {}
                    Some(Err(_)) => break,
                }
            }
        }
    }
}

fn should_send_sessions_message(text: &str) -> bool {
    serde_json::from_str::<serde_json::Value>(text)
        .ok()
        .and_then(|value| {
            value
                .get("MessageType")
                .and_then(serde_json::Value::as_str)
                .map(str::to_string)
        })
        .is_some_and(|message_type| message_type.eq_ignore_ascii_case("SessionsStart"))
}

