    #[test]
    fn plugin_zip_preflight_rejects_entry_count_and_size_bombs() {
        let temp = tempfile::tempdir().unwrap();
        let mut count_bomb = stored_zip(&[("runtime", b"payload")]);
        let eocd = count_bomb
            .windows(4)
            .rposition(|window| window == b"PK\x05\x06")
            .unwrap();
        let excessive_count = (super::MAX_PLUGIN_PACKAGE_ENTRIES as u16 + 1).to_le_bytes();
        count_bomb[eocd + 8..eocd + 10].copy_from_slice(&excessive_count);
        count_bomb[eocd + 10..eocd + 12].copy_from_slice(&excessive_count);
        let count_path = temp.path().join("count-bomb.zip");
        std::fs::write(&count_path, count_bomb).unwrap();
        assert!(
            super::open_validated_plugin_zip_archive(&count_path, &super::AtomicBool::new(false))
                .is_err()
        );

        let mut size_bomb = stored_zip(&[("runtime", b"payload")]);
        let central = size_bomb
            .windows(4)
            .position(|window| window == b"PK\x01\x02")
            .unwrap();
        let excessive_size = (super::MAX_PLUGIN_PACKAGE_ENTRY_BYTES as u32 + 1).to_le_bytes();
        size_bomb[central + 24..central + 28].copy_from_slice(&excessive_size);
        let size_path = temp.path().join("size-bomb.zip");
        std::fs::write(&size_path, size_bomb).unwrap();
        assert!(
            super::open_validated_plugin_zip_archive(&size_path, &super::AtomicBool::new(false))
                .is_err()
        );
    }

