    #[test]
    fn live_tv_provider_catalog_pages_are_accumulated_backwards_compatibly() {
        let mut request = json!({
            "Action": "ImportChannels",
            "TunerConfig": { "SecretReference": "provider/test" },
            "Arguments": { "must": "be replaced" }
        });
        super::set_live_tv_provider_catalog_request_page(&mut request, None).unwrap();
        assert_eq!(request["Arguments"], json!({}));
        super::set_live_tv_provider_catalog_request_page(&mut request, Some("opaque-page-2"))
            .unwrap();
        assert_eq!(
            request["Arguments"],
            json!({ "ContinuationToken": "opaque-page-2" })
        );

        let mut pages = super::LiveTvPluginCatalogPages::default();
        assert_eq!(
            pages
                .push(json!({
                    "Channels": [{ "Id": "one" }],
                    "Categories": [{ "Id": "news" }],
                    "ContinuationToken": "opaque-page-2",
                    "HasMore": true
                }))
                .unwrap(),
            Some("opaque-page-2".to_string())
        );
        // A legacy final response may omit both continuation fields and use Items.
        assert_eq!(
            pages.push(json!({ "Items": [{ "Id": "two" }] })).unwrap(),
            None
        );
        let result = pages.into_capability_result();
        assert_eq!(result.value["Channels"].as_array().unwrap().len(), 2);
        assert_eq!(result.value["Categories"].as_array().unwrap().len(), 1);
    }

    #[test]
    fn live_tv_provider_catalog_accepts_the_exact_aggregate_byte_budget() {
        let first = json!({
            "Channels": [{ "Id": "one", "Name": "First channel" }],
            "ContinuationToken": "opaque-page-2",
            "HasMore": true
        });
        let second = json!({
            "Channels": [{ "Id": "two", "Name": "Second channel" }]
        });
        let first_bytes = super::live_tv_plugin_catalog_encoded_size(&first, usize::MAX).unwrap();
        let second_bytes = super::live_tv_plugin_catalog_encoded_size(&second, usize::MAX).unwrap();
        let budget = first_bytes.checked_add(second_bytes).unwrap();
        let mut pages = super::LiveTvPluginCatalogPages::with_max_accumulated_bytes(budget);

        assert_eq!(
            pages.push(first).unwrap(),
            Some("opaque-page-2".to_string())
        );
        assert_eq!(pages.push(second).unwrap(), None);
        assert_eq!(pages.accumulated_bytes, budget);
        assert_eq!(pages.channels.len(), 2);
    }

    #[test]
    fn live_tv_provider_catalog_rejects_aggregate_bytes_without_partial_accumulation() {
        let first = json!({
            "Channels": [{ "Id": "one", "Name": "First channel" }],
            "ContinuationToken": "opaque-page-2",
            "HasMore": true
        });
        let second = json!({
            "Channels": [{ "Id": "two", "Name": "Second channel" }]
        });
        let first_bytes = super::live_tv_plugin_catalog_encoded_size(&first, usize::MAX).unwrap();
        let second_bytes = super::live_tv_plugin_catalog_encoded_size(&second, usize::MAX).unwrap();
        let budget = first_bytes
            .checked_add(second_bytes)
            .unwrap()
            .saturating_sub(1);
        let mut pages = super::LiveTvPluginCatalogPages::with_max_accumulated_bytes(budget);

        pages.push(first).unwrap();
        let error = pages.push(second).unwrap_err();
        assert!(error.error.to_string().contains("accumulated byte limit"));
        assert_eq!(pages.page_count, 1);
        assert_eq!(pages.accumulated_bytes, first_bytes);
        assert_eq!(pages.channels.len(), 1);
    }

