    #[test]
    fn vod_library_media_item_from_plugin_accepts_contract_items() {
        let movie = super::vod_library_media_item_from_plugin(
            "plugin-a",
            "tuner-a",
            0,
            &json!({
                "ItemType": "Movie",
                "ProviderReference": "provider:v1:movie-1",
                "Name": "Movie One",
                "Overview": "A movie.",
                "ImageUrl": "https://images.example.invalid/movie-1.jpg",
                "ProductionYear": 2024,
                "RuntimeTicks": 5_400_000_000i64,
                "CommunityRating": 7.5,
                "Genres": ["Drama"],
                "UnexpectedProviderField": "dropped"
            }),
        )
        .unwrap();
        assert_eq!(movie.item_type, "Movie");
        assert_eq!(movie.provider_reference, "provider:v1:movie-1");
        assert_eq!(movie.name, "Movie One");
        assert_eq!(movie.overview.as_deref(), Some("A movie."));
        assert_eq!(movie.production_year, Some(2024));
        assert_eq!(movie.runtime_ticks, Some(5_400_000_000));
        assert_eq!(movie.community_rating, Some(7.5));
        assert_eq!(movie.genres, vec!["Drama".to_string()]);
        assert!(movie.series_reference.is_none());

        let series = super::vod_library_media_item_from_plugin(
            "plugin-a",
            "tuner-a",
            1,
            &json!({
                "ItemType": "series",
                "ProviderReference": "provider:v1:series-1",
                "Name": "Show One"
            }),
        )
        .unwrap();
        assert_eq!(series.item_type, "Series");

        let episode = super::vod_library_media_item_from_plugin(
            "plugin-a",
            "tuner-a",
            2,
            &json!({
                "ItemType": "Episode",
                "ProviderReference": "provider:v1:episode-1",
                "Name": "Pilot",
                "SeriesReference": "provider:v1:series-1",
                "SeriesName": "Show One",
                "SeasonNumber": 1,
                "EpisodeNumber": 1
            }),
        )
        .unwrap();
        assert_eq!(episode.item_type, "Episode");
        assert_eq!(
            episode.series_reference.as_deref(),
            Some("provider:v1:series-1")
        );
        assert_eq!(episode.series_name.as_deref(), Some("Show One"));
        assert_eq!(episode.season_number, Some(1));
        assert_eq!(episode.episode_number, Some(1));
    }

    #[test]
    fn vod_library_media_item_from_plugin_rejects_unsafe_items() {
        let reject = |item: serde_json::Value| {
            super::vod_library_media_item_from_plugin("plugin-a", "tuner-a", 0, &item).is_none()
        };
        // Credential-shaped fields anywhere in the item drop it entirely.
        assert!(reject(json!({
            "ItemType": "Movie",
            "ProviderReference": "provider:v1:movie-1",
            "Name": "Movie One",
            "Password": "hunter2"
        })));
        assert!(reject(json!({
            "ItemType": "Movie",
            "ProviderReference": "provider:v1:movie-1",
            "Name": "Movie One",
            "ImageUrl": "https://user:pass@images.example.invalid/movie.jpg"
        })));
        // Provider references must stay opaque tokens, never URLs.
        assert!(reject(json!({
            "ItemType": "Movie",
            "ProviderReference": "https://provider.invalid/movie?token=abc",
            "Name": "Movie One"
        })));
        // Unknown item types, missing names and episode grouping violations are rejected.
        assert!(reject(json!({
            "ItemType": "Season",
            "ProviderReference": "provider:v1:season-1",
            "Name": "Season One"
        })));
        assert!(reject(json!({
            "ItemType": "Movie",
            "ProviderReference": "provider:v1:movie-1"
        })));
        assert!(reject(json!({
            "ItemType": "Episode",
            "ProviderReference": "provider:v1:episode-1",
            "Name": "Pilot"
        })));
        assert!(reject(json!({
            "ItemType": "Episode",
            "ProviderReference": "provider:v1:episode-1",
            "Name": "Pilot",
            "SeriesReference": "https://provider.invalid/series/1"
        })));
    }

    #[test]
    fn vod_library_catalog_pages_validate_without_accumulating_media_items() {
        let mut pages = super::VodPluginCatalogPages::default();
        let first = pages
            .push(json!({
                "MediaItems": [{ "ItemType": "Movie" }],
                "MovieCount": 2,
                "ContinuationToken": "vod-page-2",
                "HasMore": true
            }))
            .unwrap();
        assert_eq!(first.media_items.len(), 1);
        assert_eq!(first.continuation_token.as_deref(), Some("vod-page-2"));
        drop(first);

        let second = pages
            .push(json!({
                "MediaItems": [{ "ItemType": "Episode" }],
                "EpisodeCount": 1
            }))
            .unwrap();
        assert_eq!(second.media_items.len(), 1);
        assert!(second.continuation_token.is_none());
        assert_eq!(pages.media_item_count, 2);
        assert_eq!(pages.movie_count, Some(2));
        assert_eq!(pages.episode_count, Some(1));
        assert_eq!(pages.series_count, None);
    }

    #[test]
    fn vod_library_catalog_pages_reject_invalid_continuations_and_limits() {
        let mut repeated = super::VodPluginCatalogPages::default();
        repeated
            .push(json!({ "ContinuationToken": "same", "HasMore": true }))
            .unwrap();
        assert!(
            repeated
                .push(json!({ "ContinuationToken": "same", "HasMore": true }))
                .is_err()
        );

        let mut missing = super::VodPluginCatalogPages::default();
        assert!(missing.push(json!({ "HasMore": true })).is_err());
        let mut contradictory = super::VodPluginCatalogPages::default();
        assert!(
            contradictory
                .push(json!({ "ContinuationToken": "next", "HasMore": false }))
                .is_err()
        );
        let mut invalid_count = super::VodPluginCatalogPages::default();
        assert!(invalid_count.push(json!({ "MovieCount": -1 })).is_err());
        assert!(
            invalid_count
                .push(json!({
                    "MovieCount": super::VOD_LIBRARY_PROVIDER_CATALOG_MAX_ITEMS as u64 + 1
                }))
                .is_err()
        );

        let mut item_limited = super::VodPluginCatalogPages {
            media_item_count: super::VOD_LIBRARY_PROVIDER_CATALOG_MAX_ITEMS,
            ..Default::default()
        };
        assert!(
            item_limited
                .push(json!({ "MediaItems": [{ "ItemType": "Movie" }] }))
                .is_err()
        );

        let mut limited = super::VodPluginCatalogPages::default();
        for page in 0..super::VOD_LIBRARY_PROVIDER_CATALOG_MAX_PAGES - 1 {
            limited
                .push(json!({
                    "ContinuationToken": format!("token-{page}"),
                    "HasMore": true
                }))
                .unwrap();
        }
        limited.push(json!({ "MediaItems": [] })).unwrap();
        assert!(limited.push(json!({ "MediaItems": [] })).is_err());
    }

    #[test]
    fn vod_catalogue_has_independent_scalable_limits() {
        assert_eq!(super::VOD_LIBRARY_PROVIDER_CATALOG_MAX_PAGES, 2_048);
        assert_eq!(super::VOD_LIBRARY_PROVIDER_CATALOG_MAX_ITEMS, 1_000_000);
        assert_eq!(
            super::DEFAULT_VOD_LIBRARY_PROVIDER_CATALOG_TIMEOUT_SECONDS,
            2 * 60 * 60
        );
        assert_eq!(
            super::MAX_VOD_LIBRARY_PROVIDER_CATALOG_TIMEOUT_SECONDS,
            6 * 60 * 60
        );
        // Live TV retains its independent in-memory safety boundary.
        assert_eq!(
            super::LIVE_TV_PROVIDER_CATALOG_MAX_ACCUMULATED_BYTES,
            64 * 1024 * 1024
        );
    }

    #[test]
    fn vod_catalogue_timeout_configuration_is_bounded() {
        let configured = super::vod_library_provider_catalog_timeout_seconds_from_value;
        assert_eq!(configured(None), 2 * 60 * 60);
        assert_eq!(configured(Some("")), 2 * 60 * 60);
        assert_eq!(configured(Some("not-a-number")), 2 * 60 * 60);
        assert_eq!(configured(Some("0")), 2 * 60 * 60);
        assert_eq!(configured(Some(" 10800 ")), 3 * 60 * 60);
        assert_eq!(configured(Some("1")), 60);
        assert_eq!(configured(Some("999999")), 6 * 60 * 60);
    }

    #[tokio::test]
    async fn vod_catalogue_pages_stage_in_bounded_batches_and_publish_atomically() {
        let db = Database::connect("sqlite::memory:").await.unwrap();
        let plugin_id = "77777777-8888-4999-8aaa-bbbbbbbbbbbb";
        let specs = super::vod_library_plugin_stage_specs("Staged VOD", plugin_id);
        let stage = db.begin_remote_media_catalog_stage(specs).await.unwrap();
        let mut writer =
            super::VodPluginCatalogStageWriter::new(&db, &stage, plugin_id, "vod-tuner");
        let mut page = (0..=super::REMOTE_MEDIA_CATALOG_STAGE_MAX_APPEND_ITEMS)
            .map(|index| {
                json!({
                    "ItemType": "Movie",
                    "ProviderReference": format!("provider:v1:movie-{index}"),
                    "Name": format!("Movie {index}")
                })
            })
            .collect::<Vec<_>>();
        page.push(json!({
            "ItemType": "Series",
            "ProviderReference": "provider:v1:series-1",
            "Name": "Show One",
            "Overview": "A staged series overview.",
            "ImageUrl": "https://images.example.invalid/show.jpg"
        }));
        page.push(json!({
            "ItemType": "Series",
            "ProviderReference": "provider:v1:series-empty",
            "Name": "Show Empty",
            "Overview": "A series whose provider has not published any episodes.",
            "ImageUrl": "https://images.example.invalid/empty.jpg",
            "ProductionYear": 2026,
            "CommunityRating": 8.5,
            "Genres": ["Drama"]
        }));
        writer.append_page(page).await.unwrap();
        // MAGSTV's episodes follow its series pages. The compact series index must therefore
        // enrich an episode received by a later RPC page.
        writer
            .append_page(vec![
                // Providers may repeat a series at a page boundary. Its durable anchor must remain
                // unique and the first validated catalogue row remains authoritative.
                json!({
                    "ItemType": "Series",
                    "ProviderReference": "provider:v1:series-1",
                    "Name": "Show One Repeated"
                }),
                json!({
                    "ItemType": "Episode",
                    "ProviderReference": "provider:v1:episode-1",
                    "Name": "Pilot",
                    "SeriesReference": "provider:v1:series-1",
                    "SeasonNumber": 1,
                    "EpisodeNumber": 1
                }),
            ])
            .await
            .unwrap();
        assert_eq!(
            writer.counts(),
            super::VodLibraryPluginImportCounts {
                movie_count: super::REMOTE_MEDIA_CATALOG_STAGE_MAX_APPEND_ITEMS + 1,
                series_count: 2,
                episode_count: 1,
            }
        );
        assert!(db.virtual_folders().await.unwrap().is_empty());

        db.complete_remote_media_catalog_stage(&stage)
            .await
            .unwrap();
        db.publish_remote_media_catalog_stage(&stage).await.unwrap();
        let folders = db.virtual_folders().await.unwrap();
        let movies = folders
            .iter()
            .find(|folder| folder.name == "Staged VOD Movies")
            .unwrap();
        let series = folders
            .iter()
            .find(|folder| folder.name == "Staged VOD Series")
            .unwrap();
        assert_eq!(
            db.media_items_for_virtual_folders(&[movies.id])
                .await
                .unwrap()
                .len(),
            super::REMOTE_MEDIA_CATALOG_STAGE_MAX_APPEND_ITEMS + 1
        );
        let episode_items = db
            .media_items_for_virtual_folders(&[series.id])
            .await
            .unwrap();
        assert_eq!(episode_items.len(), 3);
        let episode = episode_items
            .iter()
            .find(|item| item.name == "Pilot")
            .unwrap();
        let episode_metadata = super::metadata_payload_for_item(&db, episode.id)
            .await
            .unwrap();
        let page = db
            .tv_series_catalog_page(Some(series.id), 0, 20)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(page.total_record_count, 2);
        assert_eq!(page.series.len(), 2);
        assert_eq!(page.episodes.len(), 1);
        assert_eq!(
            page.series
                .iter()
                .find(|entry| entry.name == "Show One")
                .unwrap()
                .id,
            super::plugin_vod_series_id(plugin_id, "vod-tuner", "provider:v1:series-1")
        );
        assert!(page.series.iter().any(|entry| entry.name == "Show Empty"));

        let query = super::ItemsQuery {
            parent_id: Some(series.id.simple().to_string()),
            include_item_types: vec!["Series".to_string()],
            limit: Some(20),
            ..Default::default()
        };
        let response = super::tv_series_items_result(&db, &query, None, "server")
            .await
            .unwrap()
            .0;
        assert_eq!(response["TotalRecordCount"], 2);
        let empty = response["Items"]
            .as_array()
            .unwrap()
            .iter()
            .find(|item| item["Name"] == "Show Empty")
            .unwrap();
        assert_eq!(empty["RecursiveItemCount"], 0);

        let empty_series_id =
            super::plugin_vod_series_id(plugin_id, "vod-tuner", "provider:v1:series-empty");
        let empty_summary = super::tv_series_summary_by_id(&db, &empty_series_id, None)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(empty_summary.id(), empty_series_id);
        assert_eq!(empty_summary.episode_count, 0);
        assert_eq!(empty_summary.name, "Show Empty");
        assert_eq!(
            empty_summary.metadata["SeriesPrimaryImageUrl"],
            "https://images.example.invalid/empty.jpg"
        );
        let metadata_target =
            super::plugin_vod_virtual_metadata_target(&db, &empty_series_id, false)
                .await
                .unwrap()
                .expect("the empty series anchor must resolve provider metadata directly");
        assert_eq!(metadata_target.owner_id, empty_series_id);
        let anchor_metadata = super::metadata_payload_for_item(&db, metadata_target.source_item_id)
            .await
            .unwrap();
        assert_eq!(
            super::plugin_vod_remote_reference(&anchor_metadata)
                .as_ref()
                .map(|reference| reference.provider_reference.as_str()),
            Some("provider:v1:series-empty")
        );
        assert_eq!(
            episode_metadata["SeriesOverview"],
            "A staged series overview."
        );
        assert_eq!(
            episode_metadata["SeasonOverview"],
            "A staged series overview."
        );
        assert_eq!(
            episode_metadata["SeriesImageUrl"],
            "https://images.example.invalid/show.jpg"
        );
    }

    #[tokio::test]
    async fn dropping_vod_catalogue_guard_aborts_an_unpublished_stage() {
        let db = Database::connect("sqlite::memory:").await.unwrap();
        let plugin_id = "88888888-9999-4aaa-8bbb-cccccccccccc";
        let stage = db
            .begin_remote_media_catalog_stage(super::vod_library_plugin_stage_specs(
                "Cancelled VOD",
                plugin_id,
            ))
            .await
            .unwrap();
        {
            let mut writer =
                super::VodPluginCatalogStageWriter::new(&db, &stage, plugin_id, "vod-tuner");
            writer
                .append_page(vec![json!({
                    "ItemType": "Movie",
                    "ProviderReference": "provider:v1:partial-movie",
                    "Name": "Partial Movie"
                })])
                .await
                .unwrap();
            let _guard = super::VodPluginCatalogStageAbortGuard::new(db.clone(), stage.clone());
        }

        let mut removed = false;
        for attempt in 0..50 {
            let item = super::vod_library_media_item_upsert(
                plugin_id,
                "vod-tuner",
                &super::VodMediaItem::movie(
                    format!("provider:v1:probe-{attempt}"),
                    format!("Probe {attempt}"),
                ),
                None,
                None,
                None,
            );
            match db
                .append_remote_media_catalog_stage(&stage, "movies", vec![item])
                .await
            {
                Ok(()) => tokio::time::sleep(std::time::Duration::from_millis(10)).await,
                Err(error) => {
                    assert!(error.to_string().contains("stage not found"));
                    removed = true;
                    break;
                }
            }
        }
        assert!(removed, "cancelled VOD stage was not aborted");
        assert!(db.virtual_folders().await.unwrap().is_empty());
    }

