    #[tokio::test]
    async fn external_process_manifest_page_serves_admin_html_and_public_controller_module() {
        let db = Database::connect("sqlite::memory:").await.unwrap();
        let user = db
            .update_first_user("admin".to_string(), "secret")
            .await
            .unwrap();
        let api_key = db
            .issue_api_key_for_user(user.id, "test-key")
            .await
            .unwrap();
        let plugin_id = "7a7a8541-29f8-4c35-99b1-66df55f8399e";
        let tmp = tempfile::tempdir().unwrap();
        let plugin_dir = tmp.path().join("plugin");
        let bin_dir = plugin_dir.join("bin");
        tokio::fs::create_dir_all(&bin_dir).await.unwrap();
        let entrypoint = bin_dir.join("magstv-runtime");
        tokio::fs::write(&entrypoint, b"#!/bin/sh\nexit 0\n")
            .await
            .unwrap();
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt as _;
            std::fs::set_permissions(&entrypoint, std::fs::Permissions::from_mode(0o700)).unwrap();
        }
        let html = b"<div data-role=\"page\"><script>window.magstvLoaded=true;</script></div>";
        let controller = b"export default class MagstvController {}";
        tokio::fs::write(plugin_dir.join("configuration.html"), html)
            .await
            .unwrap();
        tokio::fs::write(plugin_dir.join("configuration.js"), controller)
            .await
            .unwrap();
        tokio::fs::write(plugin_dir.join("undeclared.html"), b"secret")
            .await
            .unwrap();

        db.install_plugin_package(
            InstallPluginPackage {
                plugin_id: plugin_id.to_string(),
                name: "Jellyrin MAGSTV".to_string(),
                version: "0.1.0".to_string(),
                runtime: "ExternalProcess".to_string(),
                target_abi: "jellyrin-plugin-rpc-v1".to_string(),
                package: json!({ "Guid": plugin_id, "Name": "Jellyrin MAGSTV" }),
                manifest: json!({
                    "Guid": plugin_id,
                    "Name": "Jellyrin MAGSTV",
                    "Version": "0.1.0",
                    "Runtime": "ExternalProcess",
                    "TargetAbi": "jellyrin-plugin-rpc-v1",
                    "Entrypoint": "bin/magstv-runtime",
                    "Installation": { "InstallPath": plugin_dir.to_string_lossy() },
                    "Capabilities": ["LiveTvProvider"],
                    "WebPages": [
                        {
                            "Name": "magstv-config",
                            "Path": "configuration.html",
                            "DisplayName": "MAGSTV Configuration",
                            "EnableInMainMenu": false
                        },
                        {
                            "Name": "magstv-controller",
                            "Path": "configuration.js",
                            "DisplayName": "MAGSTV Controller",
                            "EnableInMainMenu": false
                        },
                        {
                            "Name": "unsafe-config",
                            "Path": "../undeclared.html"
                        }
                    ]
                }),
            },
            Some(user.id),
        )
        .await
        .unwrap();
        db.set_installed_plugin_status(plugin_id, "Active", None, Some(user.id))
            .await
            .unwrap();

        let app = router(AppState {
            db,
            web_dir: tmp.path().join("web"),
            log_dir: tmp.path().join("logs"),
            local_address: "http://127.0.0.1:8097".to_string(),
        });

        let unauthorized = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri("/web/ConfigurationPage?name=magstv-config")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(unauthorized.status(), StatusCode::UNAUTHORIZED);

        let public_controller = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri("/web/ConfigurationPage?name=magstv-controller")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(public_controller.status(), StatusCode::OK);
        assert_eq!(
            public_controller
                .headers()
                .get(header::CONTENT_TYPE)
                .unwrap(),
            "text/javascript; charset=utf-8"
        );
        assert_eq!(
            &public_controller
                .into_body()
                .collect()
                .await
                .unwrap()
                .to_bytes()[..],
            controller
        );

        let pages = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri("/Dashboard/web/ConfigurationPages")
                    .header("X-Emby-Token", &api_key)
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(pages.status(), StatusCode::OK);
        let pages: Value =
            serde_json::from_slice(&pages.into_body().collect().await.unwrap().to_bytes()).unwrap();
        let page = pages
            .as_array()
            .unwrap()
            .iter()
            .find(|page| page["Name"] == "magstv-config")
            .unwrap();
        assert_eq!(page["PluginId"], plugin_id);
        assert_eq!(page["DisplayName"], "MAGSTV Configuration");
        assert_eq!(
            page["EmbeddedResourcePath"],
            format!("/Plugins/{plugin_id}/WebPages/configuration.html")
        );
        assert!(
            !pages
                .as_array()
                .unwrap()
                .iter()
                .any(|page| page["Name"] == "unsafe-config")
        );

        for uri in [
            "/web/ConfigurationPage?name=magstv-config".to_string(),
            format!("/Plugins/{plugin_id}/WebPages/configuration.html"),
        ] {
            let response = app
                .clone()
                .oneshot(
                    Request::builder()
                        .uri(uri)
                        .header("X-Emby-Token", &api_key)
                        .body(Body::empty())
                        .unwrap(),
                )
                .await
                .unwrap();
            assert_eq!(response.status(), StatusCode::OK);
            assert_eq!(
                response.headers().get(header::CONTENT_TYPE).unwrap(),
                "text/html; charset=utf-8"
            );
            assert_eq!(
                response.headers().get("x-content-type-options").unwrap(),
                "nosniff"
            );
            assert_eq!(
                &response.into_body().collect().await.unwrap().to_bytes()[..],
                html
            );
        }

        for uri in [
            "/web/ConfigurationPage?name=magstv-controller".to_string(),
            format!("/Plugins/{plugin_id}/WebPages/configuration.js"),
        ] {
            let response = app
                .clone()
                .oneshot(
                    Request::builder()
                        .uri(uri)
                        .header("X-Emby-Token", &api_key)
                        .body(Body::empty())
                        .unwrap(),
                )
                .await
                .unwrap();
            assert_eq!(response.status(), StatusCode::OK);
            assert_eq!(
                response.headers().get(header::CONTENT_TYPE).unwrap(),
                "text/javascript; charset=utf-8"
            );
            assert_eq!(
                response.headers().get("x-content-type-options").unwrap(),
                "nosniff"
            );
            assert_eq!(
                &response.into_body().collect().await.unwrap().to_bytes()[..],
                controller
            );
        }

        let undeclared = app
            .oneshot(
                Request::builder()
                    .uri(format!("/Plugins/{plugin_id}/WebPages/undeclared.html"))
                    .header("X-Emby-Token", api_key)
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(undeclared.status(), StatusCode::NOT_FOUND);
    }

