    async fn spawn_single_http_request_recorder() -> (String, tokio::sync::oneshot::Receiver<String>)
    {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let addr = listener.local_addr().unwrap();
        let (tx, rx) = tokio::sync::oneshot::channel();
        tokio::spawn(async move {
            let (mut stream, _) = listener.accept().await.unwrap();
            let mut buffer = Vec::new();
            let mut scratch = [0_u8; 1024];
            let header_end = loop {
                let read = stream.read(&mut scratch).await.unwrap();
                if read == 0 {
                    return;
                }
                buffer.extend_from_slice(&scratch[..read]);
                if let Some(end) = http_header_end(&buffer) {
                    break end;
                }
            };
            let headers = String::from_utf8_lossy(&buffer[..header_end]);
            let content_length = headers
                .lines()
                .find_map(|line| {
                    let (name, value) = line.split_once(':')?;
                    name.eq_ignore_ascii_case("content-length")
                        .then(|| value.trim().parse::<usize>().ok())?
                })
                .unwrap_or(0);
            while buffer.len() < header_end + content_length {
                let read = stream.read(&mut scratch).await.unwrap();
                if read == 0 {
                    break;
                }
                buffer.extend_from_slice(&scratch[..read]);
            }
            stream
                .write_all(b"HTTP/1.1 200 OK\r\nContent-Length: 0\r\n\r\n")
                .await
                .unwrap();
            let request =
                String::from_utf8_lossy(&buffer[..buffer.len().min(header_end + content_length)])
                    .to_string();
            let _ = tx.send(request);
        });
        (format!("http://{addr}/events"), rx)
    }

    async fn spawn_single_http_image_response(
        bytes: Vec<u8>,
        content_type: &str,
    ) -> (String, tokio::sync::oneshot::Receiver<String>) {
        let (url, mut rx) = spawn_http_image_response(bytes, content_type, 1).await;
        let (tx, single_rx) = tokio::sync::oneshot::channel();
        tokio::spawn(async move {
            if let Some(request) = rx.recv().await {
                let _ = tx.send(request);
            }
        });
        (url, single_rx)
    }

    async fn spawn_single_raw_http_response(
        response: Vec<u8>,
    ) -> (String, tokio::sync::oneshot::Receiver<String>) {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let addr = listener.local_addr().unwrap();
        let (tx, rx) = tokio::sync::oneshot::channel();
        tokio::spawn(async move {
            let Ok((mut stream, _)) = listener.accept().await else {
                return;
            };
            let mut buffer = Vec::new();
            let mut scratch = [0_u8; 1024];
            loop {
                let read = stream.read(&mut scratch).await.unwrap();
                if read == 0 {
                    return;
                }
                buffer.extend_from_slice(&scratch[..read]);
                if http_header_end(&buffer).is_some() {
                    break;
                }
            }
            stream.write_all(&response).await.unwrap();
            let _ = tx.send(String::from_utf8_lossy(&buffer).to_string());
        });
        (format!("http://{addr}/image"), rx)
    }

    #[tokio::test]
    async fn opaque_live_tv_provider_egress_uses_configured_proxy_without_origin_dns() {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let proxy_address = listener.local_addr().unwrap();
        let (request_tx, request_rx) = tokio::sync::oneshot::channel();
        tokio::spawn(async move {
            let (mut stream, _) = listener.accept().await.unwrap();
            let mut request = Vec::new();
            let mut scratch = [0_u8; 1024];
            loop {
                let read = stream.read(&mut scratch).await.unwrap();
                if read == 0 {
                    return;
                }
                request.extend_from_slice(&scratch[..read]);
                if request.windows(4).any(|window| window == b"\r\n\r\n") {
                    break;
                }
            }
            stream
                .write_all(
                    b"HTTP/1.1 200 OK\r\nContent-Type: video/mp2t\r\nContent-Length: 4\r\n\r\nDATA",
                )
                .await
                .unwrap();
            let _ = request_tx.send(String::from_utf8_lossy(&request).to_string());
        });

        // `.invalid` must not be resolved locally: the explicitly configured egress owns the
        // origin trust boundary and receives the absolute-form HTTP target.
        let source = "http://origin-does-not-resolve.invalid/live?token=sensitive";
        let proxy = format!("http://localhost:{}", proxy_address.port());
        let response = super::send_sensitive_remote_live_request_with_proxy(
            source,
            true,
            Some(&proxy),
            StdDuration::from_secs(1),
        )
        .await
        .expect("configured provider egress proxy must be used");
        assert_eq!(response.status(), reqwest::StatusCode::OK);
        assert_eq!(response.bytes().await.unwrap().as_ref(), b"DATA");
        let request = request_rx.await.unwrap();
        assert!(request.starts_with(&format!("GET {source} HTTP/1.1\r\n")));
    }

    #[tokio::test]
    async fn opaque_live_tv_follows_only_supported_redirect_statuses() {
        for (code, reason) in [
            (301, "Moved Permanently"),
            (302, "Found"),
            (303, "See Other"),
            (307, "Temporary Redirect"),
            (308, "Permanent Redirect"),
        ] {
            let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
            let address = listener.local_addr().unwrap();
            let upstream = tokio::spawn(async move {
                let mut requests = Vec::new();
                for response in [
                    format!(
                        "HTTP/1.1 {code} {reason}\r\nLocation: /redirected?token=second-secret\r\nContent-Length: 0\r\nConnection: close\r\n\r\n"
                    )
                    .into_bytes(),
                    b"HTTP/1.1 200 OK\r\nContent-Type: video/mp2t\r\nContent-Length: 4\r\nConnection: close\r\n\r\nDATA".to_vec(),
                ] {
                    let (mut socket, _) = listener.accept().await.unwrap();
                    let mut request = Vec::new();
                    let mut scratch = [0_u8; 1024];
                    loop {
                        let read = socket.read(&mut scratch).await.unwrap();
                        if read == 0 {
                            break;
                        }
                        request.extend_from_slice(&scratch[..read]);
                        if request.windows(4).any(|window| window == b"\r\n\r\n") {
                            break;
                        }
                    }
                    requests.push(String::from_utf8_lossy(&request).to_string());
                    socket.write_all(&response).await.unwrap();
                }
                requests
            });

            let response = super::send_sensitive_remote_live_request_with_proxy(
                &format!("http://{address}/live?token=first-secret"),
                false,
                None,
                StdDuration::from_secs(2),
            )
            .await
            .expect("supported redirect must be followed");
            assert_eq!(response.status(), reqwest::StatusCode::OK);
            assert_eq!(response.bytes().await.unwrap().as_ref(), b"DATA");
            let requests = upstream.await.unwrap();
            assert!(requests[0].starts_with("GET /live?token=first-secret HTTP/1.1\r\n"));
            assert!(requests[1].starts_with("GET /redirected?token=second-secret HTTP/1.1\r\n"));
        }
    }

    #[tokio::test]
    async fn opaque_live_tv_provider_egress_follows_redirect_through_pinned_proxy() {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let proxy_address = listener.local_addr().unwrap();
        let proxy = tokio::spawn(async move {
            let mut requests = Vec::new();
            for response in [
                b"HTTP/1.1 302 Found\r\nLocation: http://redirected.invalid/live?token=second-secret\r\nContent-Length: 0\r\nConnection: close\r\n\r\n".to_vec(),
                b"HTTP/1.1 200 OK\r\nContent-Type: video/mp2t\r\nContent-Length: 4\r\nConnection: close\r\n\r\nDATA".to_vec(),
            ] {
                let (mut socket, _) = listener.accept().await.unwrap();
                let mut request = Vec::new();
                let mut scratch = [0_u8; 1024];
                loop {
                    let read = socket.read(&mut scratch).await.unwrap();
                    if read == 0 {
                        break;
                    }
                    request.extend_from_slice(&scratch[..read]);
                    if request.windows(4).any(|window| window == b"\r\n\r\n") {
                        break;
                    }
                }
                requests.push(String::from_utf8_lossy(&request).to_string());
                socket.write_all(&response).await.unwrap();
            }
            requests
        });

        let response = super::send_sensitive_remote_live_request_with_proxy(
            "http://origin.invalid/live?token=first-secret",
            true,
            Some(&format!("http://localhost:{}", proxy_address.port())),
            StdDuration::from_secs(2),
        )
        .await
        .expect("provider egress redirect must remain inside the configured boundary");
        assert_eq!(response.status(), reqwest::StatusCode::OK);
        assert_eq!(response.bytes().await.unwrap().as_ref(), b"DATA");
        let requests = proxy.await.unwrap();
        assert!(
            requests[0]
                .starts_with("GET http://origin.invalid/live?token=first-secret HTTP/1.1\r\n")
        );
        assert!(
            requests[1]
                .starts_with("GET http://redirected.invalid/live?token=second-secret HTTP/1.1\r\n")
        );
    }

    #[tokio::test]
    async fn opaque_live_tv_redirect_revalidates_destination_and_hides_secrets() {
        let redirect = b"HTTP/1.1 302 Found\r\nLocation: http://169.254.169.254/private?token=redirect-secret\r\nContent-Length: 0\r\nConnection: close\r\n\r\n".to_vec();
        let (source_url, source_request) = spawn_single_raw_http_response(redirect).await;
        let error = super::send_sensitive_remote_live_request_with_proxy(
            &format!("{source_url}?token=initial-secret"),
            false,
            None,
            StdDuration::from_secs(2),
        )
        .await
        .expect_err("redirect into link-local metadata must be rejected");
        assert_eq!(error.status(), StatusCode::FORBIDDEN);
        let message = error.error.to_string();
        assert!(!message.contains("initial-secret"));
        assert!(!message.contains("redirect-secret"));
        assert!(
            source_request
                .await
                .unwrap()
                .starts_with("GET /image?token=initial-secret ")
        );

        let current = reqwest::Url::parse("https://provider.invalid/live").unwrap();
        let error = super::validated_sensitive_remote_live_redirect(
            &current,
            "http://cdn.invalid/live?token=downgrade-secret",
        )
        .expect_err("HTTPS to HTTP redirect must be rejected before DNS");
        assert_eq!(error.status(), StatusCode::SERVICE_UNAVAILABLE);
        assert!(!error.error.to_string().contains("downgrade-secret"));
    }

    #[tokio::test]
    async fn opaque_live_tv_redirect_chain_is_limited_to_five_hops() {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let address = listener.local_addr().unwrap();
        let upstream = tokio::spawn(async move {
            let mut requests = Vec::new();
            for hop in 0..=super::SENSITIVE_REMOTE_LIVE_MAX_REDIRECTS {
                let (mut socket, _) = listener.accept().await.unwrap();
                let mut request = Vec::new();
                let mut scratch = [0_u8; 1024];
                loop {
                    let read = socket.read(&mut scratch).await.unwrap();
                    if read == 0 {
                        break;
                    }
                    request.extend_from_slice(&scratch[..read]);
                    if request.windows(4).any(|window| window == b"\r\n\r\n") {
                        break;
                    }
                }
                requests.push(String::from_utf8_lossy(&request).to_string());
                let response = format!(
                    "HTTP/1.1 302 Found\r\nLocation: /hop/{}?token=chain-secret\r\nContent-Length: 0\r\nConnection: close\r\n\r\n",
                    hop + 1
                );
                socket.write_all(response.as_bytes()).await.unwrap();
            }
            requests
        });

        let error = super::send_sensitive_remote_live_request_with_proxy(
            &format!("http://{address}/hop/0?token=chain-secret"),
            false,
            None,
            StdDuration::from_secs(2),
        )
        .await
        .expect_err("sixth redirect response must exceed the five-hop limit");
        assert_eq!(error.status(), StatusCode::SERVICE_UNAVAILABLE);
        assert!(!error.error.to_string().contains("chain-secret"));
        let requests = upstream.await.unwrap();
        assert_eq!(
            requests.len(),
            super::SENSITIVE_REMOTE_LIVE_MAX_REDIRECTS + 1
        );
    }

    #[tokio::test]
    async fn opaque_live_tv_resolution_and_headers_share_one_timeout() {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let address = listener.local_addr().unwrap();
        tokio::spawn(async move {
            let (_stream, _) = listener.accept().await.unwrap();
            futures_util::future::pending::<()>().await;
        });

        let error = super::send_sensitive_remote_live_request_with_proxy(
            &format!("http://{address}/live?token=sensitive"),
            false,
            None,
            StdDuration::from_millis(20),
        )
        .await
        .expect_err("resolution plus response headers must share a bounded deadline");
        assert_eq!(error.status(), StatusCode::SERVICE_UNAVAILABLE);
        assert!(!error.error.to_string().contains("token=sensitive"));
    }

    #[tokio::test]
    async fn opaque_live_tv_stream_enforces_per_chunk_idle_timeout() {
        let pending = futures_util::stream::pending::<Result<bytes::Bytes, std::io::Error>>();
        let mut stream = Box::pin(super::live_tv_chunk_idle_timeout_stream(
            pending,
            StdDuration::from_millis(10),
        ));
        let error = tokio::time::timeout(StdDuration::from_millis(100), stream.next())
            .await
            .expect("idle wrapper must resolve")
            .expect("idle wrapper must emit one terminal error")
            .expect_err("idle wrapper must reject a stalled chunk");
        assert_eq!(error.kind(), std::io::ErrorKind::TimedOut);
        assert!(stream.next().await.is_none());
    }

    #[test]
    fn resource_caps_remote_images_preserve_https_and_reject_unsafe_networks() {
        let https =
            super::validated_remote_image_url("https://images.example/poster.png?size=2").unwrap();
        assert_eq!(https.scheme(), "https");
        for invalid in [
            "ftp://images.example/poster.png",
            "https://user:secret@images.example/poster.png",
            "https://images.example/poster.png#private",
            "https://images.example/poster.png\nInjected: value",
        ] {
            assert!(
                super::validated_remote_image_url(invalid).is_err(),
                "{invalid}"
            );
        }
        assert!(!super::remote_provider_address_allowed(
            "127.0.0.1".parse().unwrap(),
            false
        ));
        assert!(!super::remote_provider_address_allowed(
            "169.254.169.254".parse().unwrap(),
            false
        ));
        for address in [
            "0.0.0.1",
            "100.64.0.1",
            "192.88.99.1",
            "198.18.0.1",
            "240.0.0.1",
        ] {
            for allow_private in [false, true] {
                assert!(
                    !super::remote_provider_address_allowed(
                        address.parse().unwrap(),
                        allow_private
                    ),
                    "technical address must always be blocked: {address}"
                );
            }
        }
        assert!(!super::remote_provider_address_allowed(
            "::ffff:127.0.0.1".parse().unwrap(),
            false
        ));
        assert!(!super::remote_provider_address_allowed(
            "::ffff:169.254.169.254".parse().unwrap(),
            false
        ));
        assert!(!super::remote_provider_address_allowed(
            "203.0.113.10".parse().unwrap(),
            false
        ));
        assert!(!super::remote_provider_address_allowed(
            "::ffff:203.0.113.10".parse().unwrap(),
            false
        ));
        assert!(!super::remote_provider_address_allowed(
            "::ffff:224.0.0.1".parse().unwrap(),
            false
        ));
        assert!(super::remote_provider_address_allowed(
            "::ffff:8.8.8.8".parse().unwrap(),
            false
        ));
        assert!(!super::remote_provider_address_allowed(
            "::ffff:100.64.0.1".parse().unwrap(),
            true
        ));
        assert!(super::remote_provider_address_allowed(
            "::ffff:10.0.0.10".parse().unwrap(),
            true
        ));
        assert!(!super::remote_provider_address_allowed(
            "::ffff:10.0.0.10".parse().unwrap(),
            false
        ));
        assert!(super::remote_provider_address_allowed(
            "10.0.0.10".parse().unwrap(),
            true
        ));
        assert!(!super::remote_provider_address_allowed(
            "10.0.0.10".parse().unwrap(),
            false
        ));
        assert!(super::remote_provider_address_allowed(
            "127.0.0.1".parse().unwrap(),
            true
        ));
        assert!(!super::remote_provider_address_allowed(
            "169.254.169.254".parse().unwrap(),
            true
        ));
        for address in [
            "::c0a8:1",
            "64:ff9b:1::1",
            "100::1",
            "100:0:0:1::1",
            "2001::1",
            "2001:2::1",
            "2001:10::1",
            "2001:20::1",
            "2001:db8::1",
            "2002::1",
            "3fff::1",
            "4000::1",
            "5f00::1",
            "fec0::1",
            "fe80::1",
            "ff02::1",
        ] {
            for allow_private in [false, true] {
                assert!(
                    !super::remote_provider_address_allowed(
                        address.parse().unwrap(),
                        allow_private
                    ),
                    "technical IPv6 range must always be blocked: {address}"
                );
            }
        }
        assert!(!super::remote_provider_address_allowed(
            "::1".parse().unwrap(),
            false
        ));
        assert!(super::remote_provider_address_allowed(
            "::1".parse().unwrap(),
            true
        ));
        assert!(!super::remote_provider_address_allowed(
            "fd00::1".parse().unwrap(),
            false
        ));
        assert!(super::remote_provider_address_allowed(
            "fd00::1".parse().unwrap(),
            true
        ));
        assert!(super::remote_provider_address_allowed(
            "2001:4860:4860::8888".parse().unwrap(),
            false
        ));
        assert!(super::remote_provider_address_allowed(
            "64:ff9b::808:808".parse().unwrap(),
            false
        ));
        assert!(!super::remote_provider_address_allowed(
            "64:ff9b::a00:1".parse().unwrap(),
            false
        ));
        assert!(super::remote_provider_address_allowed(
            "64:ff9b::a00:1".parse().unwrap(),
            true
        ));
    }

    #[test]
    fn resource_caps_remote_image_client_cache_is_lru_and_hard_bounded() {
        let now = std::time::Instant::now();
        let mut cache = super::RemoteImageClientCache::new(2, StdDuration::from_secs(600));
        let client = reqwest::Client::builder().no_proxy().build().unwrap();
        let key = |host: &str, octet: u8| super::RemoteImageClientKey {
            scheme: "https".to_string(),
            host: host.to_string(),
            port: 443,
            resolved: vec![std::net::SocketAddr::from(([203, 0, 113, octet], 443))],
        };
        cache.insert(key("one.example", 1), client.clone(), now);
        cache.insert(key("two.example", 2), client.clone(), now);
        assert!(cache.get("https", "one.example", 443, now).is_some());
        cache.insert(key("three.example", 3), client, now);

        assert_eq!(cache.len(now), 2);
        assert!(cache.get("https", "one.example", 443, now).is_some());
        assert!(cache.get("https", "two.example", 443, now).is_none());
        assert!(cache.get("https", "three.example", 443, now).is_some());
    }

