        assert!(body.is_empty());
        assert!(source_request.await.unwrap().starts_with("GET /image "));
        assert!(
            tokio::time::timeout(StdDuration::from_millis(150), target_request)
                .await
                .is_err(),
            "validated Live TV fetch must not follow redirects"
        );

        let oversized = b"HTTP/1.1 200 OK\r\nContent-Length: 33\r\n\r\n".to_vec();
