    async fn spawn_http_image_response(
        bytes: Vec<u8>,
        content_type: &str,
        expected_requests: usize,
    ) -> (String, tokio::sync::mpsc::Receiver<String>) {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let addr = listener.local_addr().unwrap();
        let content_type = content_type.to_string();
        let (tx, rx) = tokio::sync::mpsc::channel(expected_requests.max(1));
        tokio::spawn(async move {
            for _ in 0..expected_requests {
                let Ok((mut stream, _)) = listener.accept().await else {
                    return;
                };
                let mut buffer = Vec::new();
                let mut scratch = [0_u8; 1024];
                let header_end = loop {
                    let read = stream.read(&mut scratch).await.unwrap();
                    if read == 0 {
                        return;
                    }
                    buffer.extend_from_slice(&scratch[..read]);
                    if let Some(end) = http_header_end(&buffer) {
                        break end;
                    }
                };
                let request = String::from_utf8_lossy(&buffer[..header_end]).to_string();
                let response_headers = format!(
                    "HTTP/1.1 200 OK\r\nContent-Type: {content_type}\r\nContent-Length: {}\r\n\r\n",
                    bytes.len()
                );
                stream.write_all(response_headers.as_bytes()).await.unwrap();
                stream.write_all(&bytes).await.unwrap();
                if tx.send(request).await.is_err() {
                    return;
                }
            }
        });
        (format!("http://{addr}/channel-image.png"), rx)
    }

    async fn spawn_http_request_recorder(
        expected_requests: usize,
    ) -> (String, tokio::sync::mpsc::Receiver<String>) {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let addr = listener.local_addr().unwrap();
        let (tx, rx) = tokio::sync::mpsc::channel(expected_requests.max(1));
        tokio::spawn(async move {
            for _ in 0..expected_requests {
                let Ok((mut stream, _)) = listener.accept().await else {
                    return;
                };
                let mut buffer = Vec::new();
                let mut scratch = [0_u8; 1024];
                let header_end = loop {
                    let Ok(read) = stream.read(&mut scratch).await else {
                        return;
                    };
                    if read == 0 {
                        return;
                    }
                    buffer.extend_from_slice(&scratch[..read]);
                    if let Some(end) = http_header_end(&buffer) {
                        break end;
                    }
                };
                let headers = String::from_utf8_lossy(&buffer[..header_end]);
                let content_length = headers
                    .lines()
                    .find_map(|line| {
                        let (name, value) = line.split_once(':')?;
                        name.eq_ignore_ascii_case("content-length")
                            .then(|| value.trim().parse::<usize>().ok())?
                    })
                    .unwrap_or(0);
                while buffer.len() < header_end + content_length {
                    let Ok(read) = stream.read(&mut scratch).await else {
                        break;
                    };
                    if read == 0 {
                        break;
                    }
                    buffer.extend_from_slice(&scratch[..read]);
                }
                let _ = stream
                    .write_all(b"HTTP/1.1 200 OK\r\nContent-Length: 0\r\n\r\n")
                    .await;
                let request = String::from_utf8_lossy(
                    &buffer[..buffer.len().min(header_end + content_length)],
                )
                .to_string();
                if tx.send(request).await.is_err() {
                    return;
                }
            }
        });
        (format!("http://{addr}/events"), rx)
    }

    fn http_header_end(buffer: &[u8]) -> Option<usize> {
        buffer
            .windows(4)
            .position(|window| window == b"\r\n\r\n")
            .map(|position| position + 4)
    }

    fn assert_hls_transcode_playback_info(info: &Value, item_id: &str, api_key: &str) -> String {
        assert_eq!(info["ErrorCode"], Value::Null);
        assert!(
            info["PlaySessionId"]
                .as_str()
                .is_some_and(|id| !id.is_empty())
        );
        let media_source = &info["MediaSources"][0];
        assert_eq!(media_source["SupportsDirectPlay"], false);
        assert_eq!(media_source["SupportsDirectStream"], false);
        assert_eq!(media_source["SupportsTranscoding"], true);
        assert_eq!(media_source["TranscodingSubProtocol"], "hls");
        assert_eq!(media_source["TranscodingContainer"], "ts");
        assert_eq!(media_source["Container"], "ts");
        assert_eq!(media_source["MediaStreams"][0]["Codec"], "h264");
        assert_eq!(media_source["MediaStreams"][1]["Codec"], "aac");
        assert_eq!(media_source["MediaStreams"][1]["Channels"], 2);
        assert!(
            !media_source
                .as_object()
                .unwrap()
                .contains_key("DirectStreamUrl")
        );
        let play_session_id = info["PlaySessionId"].as_str().unwrap();
        assert_eq!(
            media_source["TranscodingUrl"],
            format!(
                "/Videos/{item_id}/master.m3u8?PlaySessionId={play_session_id}&api_key={api_key}"
            )
        );
        play_session_id.to_string()
    }

