    #[test]
    fn opaque_live_tv_secret_policy_allows_references_only() {
        assert!(!super::contains_plaintext_provider_secret(&json!({
            "SecretReference": "provider/account-a",
            "TokenRef": "vault:provider/token",
            "CredentialsConfigured": true,
            "Nested": {"CredentialsReference": "vault:provider/account-a"}
        })));
        assert!(super::contains_plaintext_provider_secret(&json!({
            "SecretReference": "provider/account-a",
            "Password": "must-not-persist"
        })));
        assert!(super::contains_plaintext_provider_secret(&json!({
            "Nested": [{"AccessToken": "must-not-persist"}]
        })));
        for forbidden in [
            json!({ "ClientSecret": "must-not-persist" }),
            json!({ "ApiKey": "must-not-persist" }),
            json!({ "DeviceToken": "must-not-persist" }),
            json!({ "AuthHeader": "must-not-persist" }),
            json!({ "BootstrapUrl": "https://provider.invalid/start?token=must-not-persist" }),
        ] {
            assert!(super::contains_plaintext_provider_secret(&forbidden));
        }
        let canaries = ["one-use-password"];
        assert!(super::json_contains_sensitive_canary(
            &json!({ "Name": "reflected one-use-password value" }),
            &canaries
        ));
        assert!(!super::json_contains_sensitive_canary(
            &json!({ "Name": "ordinary channel" }),
            &canaries
        ));
        assert!(super::json_contains_sensitive_canary(
            &json!({ "one-use-password": "value" }),
            &canaries
        ));
        assert!(super::json_contains_sensitive_canary(
            &json!({ "Name": "test" }),
            &["test"]
        ));
        assert!(!super::json_contains_sensitive_canary(
            &json!({ "Name": "latest channel" }),
            &["test"]
        ));
        let request = json!({
            "SecretGrant": {
                "Username": "provider-user",
                "Password": "one-use-password",
                "Fields": { "DeviceSecret": "device-secret" }
            }
        });
        assert_eq!(
            super::live_tv_provider_secret_canaries(&request),
            vec!["provider-user", "one-use-password", "device-secret"]
        );
    }

