    #[test]
    fn tvmaze_hardening_urls_are_fixed_https_and_encode_queries() {
        let mut url = super::tvmaze_api_url("/search/shows").unwrap();
        url.query_pairs_mut().append_pair("q", "A&B / 2026");

        assert_eq!(url.scheme(), "https");
        assert_eq!(url.host_str(), Some(super::TVMAZE_API_HOST));
        assert_eq!(url.port_or_known_default(), Some(super::TVMAZE_API_PORT));
        assert_eq!(
            url.query_pairs()
                .next()
                .map(|(key, value)| (key.into_owned(), value.into_owned())),
            Some(("q".to_string(), "A&B / 2026".to_string()))
        );
        for invalid in [
            "http://api.tvmaze.com/search/shows",
            "https://example.com/search/shows",
            "https://user:secret@api.tvmaze.com/search/shows",
            "https://api.tvmaze.com:444/search/shows",
            "https://api.tvmaze.com/search/shows#fragment",
        ] {
            assert!(
                super::validate_tvmaze_api_url(&reqwest::Url::parse(invalid).unwrap()).is_err(),
                "accepted invalid TVMaze URL shape"
            );
        }
    }

