    #[test]
    fn tv_refresh_grouping_preserves_cross_folder_series_scope() {
        let folder_a = Uuid::from_u128(100);
        let folder_b = Uuid::from_u128(200);
        let groups = super::tv_episode_groups_for_folder_refresh(
            vec![
                tv_refresh_test_item(
                    1,
                    folder_a,
                    "Show One S01E01",
                    "/a/Show One/Season 01/Show One S01E01.mkv",
                    "Video",
                    Some("tvshows"),
                ),
                tv_refresh_test_item(
                    2,
                    folder_b,
                    "Show One S01E02",
                    "/b/Show One/Season 01/Show One S01E02.mkv",
                    "Video",
                    Some("tvshows"),
                ),
                tv_refresh_test_item(
                    3,
                    folder_a,
                    "Show Two S01E01",
                    "/a/Show Two/Season 01/Show Two S01E01.mkv",
                    "Video",
                    Some("series"),
                ),
            ],
            folder_a,
        );

        assert_eq!(
            groups.keys().map(String::as_str).collect::<Vec<_>>(),
            vec!["Show One", "Show Two"]
        );
        assert_eq!(
            groups["Show One"]
                .iter()
                .map(|episode| episode.virtual_folder_id)
                .collect::<Vec<_>>(),
            vec![folder_a, folder_b]
        );
        assert_eq!(groups["Show Two"].len(), 1);
    }

