    #[tokio::test]
    async fn dlna_browse_folder_items_and_streams_media_resource() {
        let media_root = tempfile::tempdir().unwrap();
        let log_root = tempfile::tempdir().unwrap();
        let primary_bytes = b"fake video bytes for dlna range";
        tokio::fs::write(media_root.path().join("DLNA & Movie.mp4"), primary_bytes)
            .await
            .unwrap();
        tokio::fs::write(
            media_root.path().join("Second Movie.mp4"),
            b"second video bytes",
        )
        .await
        .unwrap();

        let db = Database::connect("sqlite::memory:").await.unwrap();
        db.update_named_configuration("network", json!({ "EnableUPnP": true }))
            .await
            .unwrap();
        let folder = db
            .upsert_virtual_folder(
                "DLNA Movies",
                Some("movies"),
                vec![media_root.path().to_string_lossy().to_string()],
            )
            .await
            .unwrap();
        assert_eq!(db.scan_virtual_folder_items(folder.id).await.unwrap(), 2);
        let item = db
            .media_items()
            .await
            .unwrap()
            .into_iter()
            .find(|item| item.name == "DLNA & Movie")
            .unwrap();
        let subtitle_path = log_root.path().join("dlna-subtitle.vtt");
        tokio::fs::write(
            &subtitle_path,
            b"WEBVTT\n\n00:00:00.000 --> 00:00:01.000\nDLNA subtitle text\n",
        )
        .await
        .unwrap();
        db.update_media_item_media_info(
            item.id,
            Some(90_000_000),
            Some(1_500_000),
            Some(1920),
            Some(1080),
            vec![
                json!({
                    "Type": "Video",
                    "Index": 0,
                    "Codec": "h264",
                    "Width": 1920,
                    "Height": 1080
                }),
                json!({
                    "Type": "Audio",
                    "Index": 1,
                    "Codec": "aac"
                }),
                json!({
                    "Type": "Subtitle",
                    "Index": 2,
                    "Codec": "webvtt",
                    "Language": "eng",
                    "IsTextSubtitleStream": true,
                    "Path": subtitle_path.to_string_lossy().to_string()
                }),
            ],
        )
        .await
        .unwrap();
        let server_id = db.server_state().await.unwrap().server_id;
        let test_db = db.clone();
        let app = router(AppState {
            db,
            web_dir: ".".into(),
            log_dir: log_root.path().join("logs"),
            local_address: "http://127.0.0.1:8097".to_string(),
        });

        let browse_folder = format!(
            r#"<?xml version="1.0"?>
<s:Envelope xmlns:s="http://schemas.xmlsoap.org/soap/envelope/">
  <s:Body>
    <u:Browse xmlns:u="urn:schemas-upnp-org:service:ContentDirectory:1">
      <ObjectID>folder:{}</ObjectID>
      <BrowseFlag>BrowseDirectChildren</BrowseFlag>
      <Filter>*</Filter>
      <StartingIndex>0</StartingIndex>
      <RequestedCount>1</RequestedCount>
      <SortCriteria></SortCriteria>
    </u:Browse>
  </s:Body>
</s:Envelope>"#,
            folder.id
        );
        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .method(Method::POST)
                    .uri(format!("/Dlna/{server_id}/ContentDirectory/Control"))
                    .header(header::HOST, "media.example.test:8097")
                    .header(header::CONTENT_TYPE, "text/xml; charset=utf-8")
                    .body(Body::from(browse_folder.clone()))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body = response.into_body().collect().await.unwrap().to_bytes();
        let browse_response = String::from_utf8(body.to_vec()).unwrap();
        assert!(browse_response.contains("<u:BrowseResponse"));
        assert!(browse_response.contains("<NumberReturned>1</NumberReturned>"));
        assert!(browse_response.contains("<TotalMatches>2</TotalMatches>"));
        assert!(browse_response.contains(&format!("&lt;item id=&quot;item:{}&quot;", item.id)));
        assert!(browse_response.contains("DLNA &amp;amp; Movie"));
        assert!(browse_response.contains("object.item.videoItem.movie"));
        assert!(browse_response.contains(
            "protocolInfo=&quot;http-get:*:video/mp4:DLNA.ORG_OP=01;DLNA.ORG_CI=0;DLNA.ORG_FLAGS="
        ));
        assert!(!browse_response.contains("DLNA.ORG_PN=AVC_MP4"));
        assert!(browse_response.contains(&format!("size=&quot;{}&quot;", primary_bytes.len())));
        assert!(browse_response.contains("upnp:albumArtURI dlna:profileID=&quot;PNG_TN&quot;"));
        let thumbnail_url = format!(
            "http://media.example.test:8097/dlna/{server_id}/items/{}/thumbnail.png",
            item.id
        );
        assert!(browse_response.contains(&thumbnail_url));
        let subtitle_url = format!(
            "http://media.example.test:8097/dlna/{server_id}/items/{}/subtitles/2/stream.vtt",
            item.id
        );
        assert!(browse_response.contains("sec:CaptionInfoEx"));
        assert!(browse_response.contains("protocolInfo=&quot;http-get:*:text/vtt:*&quot;"));
        assert!(browse_response.contains(&subtitle_url));
        let resource_url = format!(
            "http://media.example.test:8097/dlna/{server_id}/items/{}/stream.mp4",
            item.id
        );
        assert!(browse_response.contains(&resource_url));
        let transcode_url = format!(
            "http://media.example.test:8097/dlna/{server_id}/items/{}/transcode.m3u8",
            item.id
        );
        assert!(browse_response.contains(&transcode_url));
        assert!(browse_response.contains(
            "protocolInfo=&quot;http-get:*:application/vnd.apple.mpegurl:DLNA.ORG_OP=01"
        ));
        assert!(!browse_response.contains("Second Movie"));
        assert!(
            browse_response.find(&resource_url).unwrap()
                < browse_response.find(&transcode_url).unwrap(),
            "generic DIDL should expose direct stream before HLS fallback"
        );

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .method(Method::POST)
                    .uri(format!("/Dlna/{server_id}/ContentDirectory/Control"))
                    .header(header::HOST, "media.example.test:8097")
                    .header(header::CONTENT_TYPE, "text/xml; charset=utf-8")
                    .header(header::USER_AGENT, "Samsung DLNADOC/1.50")
                    .body(Body::from(browse_folder.clone()))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body = response.into_body().collect().await.unwrap().to_bytes();
        let samsung_browse_response = String::from_utf8(body.to_vec()).unwrap();
        assert!(
            samsung_browse_response.contains("DLNA.ORG_PN=AVC_MP4_MP_HD_1080i_AAC;DLNA.ORG_OP=01")
        );
        assert!(samsung_browse_response.contains("sec:CaptionInfoEx"));
        assert!(
            samsung_browse_response.find(&resource_url).unwrap()
                < samsung_browse_response.find(&transcode_url).unwrap(),
            "Samsung DIDL should keep direct-play MP4 before HLS fallback"
        );

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .method(Method::POST)
                    .uri(format!("/Dlna/{server_id}/ContentDirectory/Control"))
                    .header(header::HOST, "media.example.test:8097")
                    .header(header::CONTENT_TYPE, "text/xml; charset=utf-8")
                    .header(header::USER_AGENT, "VLC/3.0.20 LibVLC")
                    .body(Body::from(browse_folder.clone()))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body = response.into_body().collect().await.unwrap().to_bytes();
        let vlc_browse_response = String::from_utf8(body.to_vec()).unwrap();
        assert!(
            vlc_browse_response.find(&transcode_url).unwrap()
                < vlc_browse_response.find(&resource_url).unwrap(),
            "VLC DIDL should prefer HLS resource before direct stream"
        );
        assert!(!vlc_browse_response.contains("sec:CaptionInfoEx"));

        let browse_item_metadata = format!(
            r#"<?xml version="1.0"?>
<s:Envelope xmlns:s="http://schemas.xmlsoap.org/soap/envelope/">
  <s:Body>
    <u:Browse xmlns:u="urn:schemas-upnp-org:service:ContentDirectory:1">
      <ObjectID>item:{}</ObjectID>
      <BrowseFlag>BrowseMetadata</BrowseFlag>
      <Filter>*</Filter>
      <StartingIndex>0</StartingIndex>
      <RequestedCount>0</RequestedCount>
      <SortCriteria></SortCriteria>
    </u:Browse>
  </s:Body>
</s:Envelope>"#,
            item.id
        );
        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .method(Method::POST)
                    .uri(format!("/dlna/{server_id}/contentdirectory/control"))
                    .header(header::HOST, "media.example.test:8097")
                    .header(header::CONTENT_TYPE, "text/xml; charset=utf-8")
                    .body(Body::from(browse_item_metadata))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body = response.into_body().collect().await.unwrap().to_bytes();
        let item_metadata_response = String::from_utf8(body.to_vec()).unwrap();
        assert!(item_metadata_response.contains("<NumberReturned>1</NumberReturned>"));
        assert!(item_metadata_response.contains("<TotalMatches>1</TotalMatches>"));
        assert!(item_metadata_response.contains(&resource_url));

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!("/dlna/{server_id}/items/{}/stream.mp4", item.id))
                    .header(header::RANGE, "bytes=0-3")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::PARTIAL_CONTENT);
        assert_eq!(
            response
                .headers()
                .get(header::CONTENT_TYPE)
                .and_then(|value| value.to_str().ok()),
            Some("video/mp4")
        );
        let expected_content_range = format!("bytes 0-3/{}", primary_bytes.len());
        assert_eq!(
            response
                .headers()
                .get(header::CONTENT_RANGE)
                .and_then(|value| value.to_str().ok()),
            Some(expected_content_range.as_str())
        );
        let body = response.into_body().collect().await.unwrap().to_bytes();
        assert_eq!(&body[..], &primary_bytes[..4]);

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!(
                        "/dlna/{server_id}/items/{}/subtitles/2/stream.vtt",
                        item.id
                    ))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        assert_eq!(
            response
                .headers()
                .get(header::CONTENT_TYPE)
                .and_then(|value| value.to_str().ok()),
            Some("text/vtt; charset=utf-8")
        );
        let body = response.into_body().collect().await.unwrap().to_bytes();
        let subtitle = String::from_utf8(body.to_vec()).unwrap();
        assert!(subtitle.contains("DLNA subtitle text"));

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .method(Method::HEAD)
                    .uri(format!("/Dlna/{server_id}/Items/{}/stream.mp4", item.id))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let expected_content_length = primary_bytes.len().to_string();
        assert_eq!(
            response
                .headers()
                .get(header::CONTENT_LENGTH)
                .and_then(|value| value.to_str().ok()),
            Some(expected_content_length.as_str())
        );
        let body = response.into_body().collect().await.unwrap().to_bytes();
        assert!(body.is_empty());

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!(
                        "/dlna/{server_id}/items/{}/transcode.m3u8",
                        item.id
                    ))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        assert_eq!(
            response
                .headers()
                .get(header::CONTENT_TYPE)
                .and_then(|value| value.to_str().ok()),
            Some("application/vnd.apple.mpegurl")
        );
        let body = response.into_body().collect().await.unwrap().to_bytes();
        let master_playlist = String::from_utf8(body.to_vec()).unwrap();
        assert!(master_playlist.starts_with("#EXTM3U\n"));
        let dlna_session = test_db
            .transcode_sessions()
            .await
            .unwrap()
            .into_iter()
            .find(|session| {
                session.item.id == item.id
                    && session.device_id.as_deref() == Some("dlna-upnp")
                    && session
                        .dedupe_key
                        .as_deref()
                        .is_some_and(|key| key.starts_with("dlna:hls:ts:"))
            })
            .expect("DLNA HLS transcode session was not created");
        assert!(
            master_playlist.contains(&format!("hls/{}/main.m3u8", dlna_session.play_session_id))
        );

        let ready_transcode_root = tempfile::tempdir().unwrap();
        let ready_transcode_dir = ready_transcode_root.path().join("dlna-ready-session");
        tokio::fs::create_dir_all(&ready_transcode_dir)
            .await
            .unwrap();
        let ready_playlist = ready_transcode_dir.join("main.m3u8");
        let ready_segment = ready_transcode_dir.join("segment_00000.ts");
        tokio::fs::write(
            &ready_playlist,
            "#EXTM3U\n#EXT-X-VERSION:3\n#EXT-X-TARGETDURATION:2\n#EXT-X-MEDIA-SEQUENCE:0\n#EXTINF:2.000,\nsegment_00000.ts\n",
        )
        .await
        .unwrap();
        tokio::fs::write(&ready_segment, b"ts segment bytes")
            .await
            .unwrap();
        let dlna_user = test_db.first_user().await.unwrap();
        test_db
            .upsert_transcode_session(UpsertTranscodeSession {
                play_session_id: "dlna-ready-session".to_string(),
                dedupe_key: Some("dlna:test-ready".to_string()),
                device_id: Some("dlna-upnp".to_string()),
                user_id: dlna_user.id,
                item_id: item.id,
                media_source_id: Some(item.id.simple().to_string()),
                audio_stream_index: None,
                subtitle_stream_index: Some(-1),
                video_stream_index: Some(0),
                output_path: ready_playlist.to_string_lossy().to_string(),
                process_id: None,
                status: "running".to_string(),
                progress_percent: None,
                position_ticks: 0,
                start_position_ticks: 0,
            })
            .await
            .unwrap();

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!(
                        "/dlna/{server_id}/items/{}/hls/dlna-ready-session/main.m3u8",
                        item.id
                    ))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body = response.into_body().collect().await.unwrap().to_bytes();
        let media_playlist = String::from_utf8(body.to_vec()).unwrap();
        assert!(media_playlist.contains(&format!(
            "/dlna/{server_id}/items/{}/hls/dlna-ready-session/0.ts",
            item.id
        )));

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!(
                        "/dlna/{server_id}/items/{}/hls/dlna-ready-session/0.ts",
                        item.id
                    ))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        assert_eq!(
            response
                .headers()
                .get(header::CONTENT_TYPE)
                .and_then(|value| value.to_str().ok()),
            Some("video/mp2t")
        );
        let body = response.into_body().collect().await.unwrap().to_bytes();
        assert_eq!(&body[..], b"ts segment bytes");

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!("/dlna/{server_id}/items/{}/thumbnail.png", item.id))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        assert_eq!(
            response
                .headers()
                .get(header::CONTENT_TYPE)
                .and_then(|value| value.to_str().ok()),
            Some("image/png")
        );
        assert_eq!(
            response
                .headers()
                .get("transfermode.dlna.org")
                .and_then(|value| value.to_str().ok()),
            Some("Interactive")
        );
        assert_eq!(
            response
                .headers()
                .get("realtimeinfo.dlna.org")
                .and_then(|value| value.to_str().ok()),
            Some("DLNA.ORG_TLAG=*")
        );
        let body = response.into_body().collect().await.unwrap().to_bytes();
        assert!(body.starts_with(b"\x89PNG"));
    }

    #[tokio::test]
    async fn dlna_thumbnail_resolver_matches_jellyfin_local_artwork_rules() {
        let media_root = tempfile::tempdir().unwrap();
        let log_root = tempfile::tempdir().unwrap();
        let tv_dir = media_root.path().join("tv").join("Show").join("Season 01");
        let movie_dir = media_root.path().join("movies");
        let music_dir = media_root.path().join("music");
        let photo_dir = media_root.path().join("photos");
        tokio::fs::create_dir_all(tv_dir.join("metadata"))
            .await
            .unwrap();
        tokio::fs::create_dir_all(&movie_dir).await.unwrap();
        tokio::fs::create_dir_all(&music_dir).await.unwrap();
        tokio::fs::create_dir_all(&photo_dir).await.unwrap();

        let episode_jpeg = b"\xff\xd8\xff\xe0episode-thumb\xff\xd9";
        let movie_webp = b"RIFF\x10\x00\x00\x00WEBPmovie-poster";
        let album_png = b"\x89PNG\r\n\x1a\nalbumart";
        let photo_jpeg = b"\xff\xd8\xff\xe0photo-primary\xff\xd9";
        tokio::fs::write(tv_dir.join("Pilot.mp4"), b"fake episode")
            .await
            .unwrap();
        tokio::fs::write(movie_dir.join("Mixed Movie.mp4"), b"fake movie")
            .await
            .unwrap();
        tokio::fs::write(music_dir.join("Track One.mp3"), b"fake audio")
            .await
            .unwrap();
        tokio::fs::write(photo_dir.join("Photo Sample.jpg"), photo_jpeg)
            .await
            .unwrap();

        let db = Database::connect("sqlite::memory:").await.unwrap();
        db.update_named_configuration("network", json!({ "EnableUPnP": true }))
            .await
            .unwrap();
        for (name, collection_type, dir) in [
            ("TV", "tvshows", media_root.path().join("tv")),
            ("Movies", "movies", movie_dir.clone()),
            ("Music", "music", music_dir.clone()),
            ("Photos", "photos", photo_dir.clone()),
        ] {
            let folder = db
                .upsert_virtual_folder(
                    name,
                    Some(collection_type),
                    vec![dir.to_string_lossy().to_string()],
                )
                .await
                .unwrap();
            assert_eq!(db.scan_virtual_folder_items(folder.id).await.unwrap(), 1);
        }
        tokio::fs::write(
            tv_dir.join("metadata").join("Pilot-thumb.jpg"),
            episode_jpeg,
        )
        .await
        .unwrap();
        tokio::fs::write(movie_dir.join("Mixed Movie-poster.webp"), movie_webp)
            .await
            .unwrap();
        tokio::fs::write(music_dir.join("albumart.png"), album_png)
            .await
            .unwrap();
        let items = db.media_items().await.unwrap();
        let item_id = |name: &str| {
            items
                .iter()
                .find(|item| item.name == name)
                .unwrap_or_else(|| panic!("missing {name}; items={items:?}"))
                .id
        };
        let episode_id = item_id("Pilot");
        let movie_id = item_id("Mixed Movie");
        let track_id = item_id("Track One");
        let photo_id = item_id("Photo Sample");
        let server_id = db.server_state().await.unwrap().server_id;
        let app = router(AppState {
            db,
            web_dir: ".".into(),
            log_dir: log_root.path().join("logs"),
            local_address: "http://127.0.0.1:8097".to_string(),
        });

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!(
                        "/dlna/{server_id}/items/{episode_id}/thumbnail.png"
                    ))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        assert_eq!(
            response
                .headers()
                .get(header::CONTENT_TYPE)
                .and_then(|value| value.to_str().ok()),
            Some("image/jpeg")
        );
        assert_eq!(
            response
                .headers()
                .get("contentfeatures.dlna.org")
                .and_then(|value| value.to_str().ok()),
            Some(
                "DLNA.ORG_PN=JPEG_TN;DLNA.ORG_OP=01;DLNA.ORG_CI=0;DLNA.ORG_FLAGS=01500000000000000000000000000000"
            )
        );
        let body = response.into_body().collect().await.unwrap().to_bytes();
        assert_eq!(&body[..], episode_jpeg);

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!("/dlna/{server_id}/items/{movie_id}/thumbnail.png"))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        assert_eq!(
            response
                .headers()
                .get(header::CONTENT_TYPE)
                .and_then(|value| value.to_str().ok()),
            Some("image/webp")
        );
        let body = response.into_body().collect().await.unwrap().to_bytes();
        assert_eq!(&body[..], movie_webp);

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!("/dlna/{server_id}/items/{track_id}/thumbnail.png"))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        assert_eq!(
            response
                .headers()
                .get(header::CONTENT_TYPE)
                .and_then(|value| value.to_str().ok()),
            Some("image/png")
        );
        assert_eq!(
            response
                .headers()
                .get("contentfeatures.dlna.org")
                .and_then(|value| value.to_str().ok()),
            Some(
                "DLNA.ORG_PN=PNG_TN;DLNA.ORG_OP=01;DLNA.ORG_CI=0;DLNA.ORG_FLAGS=01500000000000000000000000000000"
            )
        );
        let body = response.into_body().collect().await.unwrap().to_bytes();
        assert_eq!(&body[..], album_png);

        let response = app
            .oneshot(
                Request::builder()
                    .uri(format!("/dlna/{server_id}/items/{photo_id}/thumbnail.png"))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        assert_eq!(
            response
                .headers()
                .get(header::CONTENT_TYPE)
                .and_then(|value| value.to_str().ok()),
            Some("image/jpeg")
        );
        assert_eq!(
            response
                .headers()
                .get("transfermode.dlna.org")
                .and_then(|value| value.to_str().ok()),
            Some("Interactive")
        );
        let body = response.into_body().collect().await.unwrap().to_bytes();
        assert_eq!(&body[..], photo_jpeg);
    }

    #[tokio::test]
    async fn dlna_video_thumbnail_generates_real_frame_with_ffmpeg() {
        let media_root = tempfile::tempdir().unwrap();
        let log_root = tempfile::tempdir().unwrap();
        let video_path = media_root.path().join("Thumbnail Source.mp4");
        let ffmpeg_output = tokio::process::Command::new("ffmpeg")
            .arg("-hide_banner")
            .arg("-nostdin")
            .arg("-y")
            .arg("-f")
            .arg("lavfi")
            .arg("-i")
            .arg("testsrc=size=160x90:rate=24")
            .arg("-t")
            .arg("2")
            .arg("-an")
            .arg("-c:v")
            .arg("libx264")
            .arg("-preset")
            .arg("ultrafast")
            .arg("-pix_fmt")
            .arg("yuv420p")
            .arg("-movflags")
            .arg("+faststart")
            .arg(&video_path)
            .stdin(std::process::Stdio::null())
            .output()
            .await
            .unwrap();
        assert!(
            ffmpeg_output.status.success(),
            "ffmpeg failed to generate thumbnail source fixture: {}",
            String::from_utf8_lossy(&ffmpeg_output.stderr)
        );

        let db = Database::connect("sqlite::memory:").await.unwrap();
        db.update_named_configuration("network", json!({ "EnableUPnP": true }))
            .await
            .unwrap();
        let folder = db
            .upsert_virtual_folder(
                "Thumbnail Movies",
                Some("movies"),
                vec![media_root.path().to_string_lossy().to_string()],
            )
            .await
            .unwrap();
        assert_eq!(db.scan_virtual_folder_items(folder.id).await.unwrap(), 1);
        let item = db
            .media_items()
            .await
            .unwrap()
            .into_iter()
            .find(|item| item.name == "Thumbnail Source")
            .unwrap();
        db.update_media_item_media_info(
            item.id,
            Some(20_000_000),
            Some(250_000),
            Some(160),
            Some(90),
            vec![json!({
                "Type": "Video",
                "Index": 0,
                "Codec": "h264",
                "Width": 160,
                "Height": 90
            })],
        )
        .await
        .unwrap();
        let server_id = db.server_state().await.unwrap().server_id;
        let app = router(AppState {
            db,
            web_dir: ".".into(),
            log_dir: log_root.path().join("logs"),
            local_address: "http://127.0.0.1:8097".to_string(),
        });

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!("/dlna/{server_id}/items/{}/thumbnail.png", item.id))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        assert_eq!(
            response
                .headers()
                .get(header::CONTENT_TYPE)
                .and_then(|value| value.to_str().ok()),
            Some("image/jpeg")
        );
        let generated_bytes = response.into_body().collect().await.unwrap().to_bytes();
        assert!(generated_bytes.starts_with(&[0xff, 0xd8]));
        assert!(
            generated_bytes.len() > 100,
            "generated thumbnail should be larger than the placeholder"
        );

        let response = app
            .oneshot(
                Request::builder()
                    .uri(format!("/dlna/{server_id}/items/{}/thumbnail.png", item.id))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        assert_eq!(
            response
                .headers()
                .get(header::CONTENT_TYPE)
                .and_then(|value| value.to_str().ok()),
            Some("image/jpeg")
        );
        let cached_bytes = response.into_body().collect().await.unwrap().to_bytes();
        assert_eq!(cached_bytes, generated_bytes);
    }

    #[tokio::test]
    async fn dlna_thumbnail_sizing_negotiates_max_dimensions_with_ffmpeg() {
        let media_root = tempfile::tempdir().unwrap();
        let log_root = tempfile::tempdir().unwrap();
        let movie_path = media_root.path().join("Sized Thumbnail Movie.mp4");
        let poster_path = media_root.path().join("Sized Thumbnail Movie-poster.jpg");
        tokio::fs::write(&movie_path, b"fake movie").await.unwrap();

        let db = Database::connect("sqlite::memory:").await.unwrap();
        db.update_named_configuration("network", json!({ "EnableUPnP": true }))
            .await
            .unwrap();
        let folder = db
            .upsert_virtual_folder(
                "Sized Thumbnail Movies",
                Some("movies"),
                vec![media_root.path().to_string_lossy().to_string()],
            )
            .await
            .unwrap();
        assert_eq!(db.scan_virtual_folder_items(folder.id).await.unwrap(), 1);
        let ffmpeg_output = tokio::process::Command::new("ffmpeg")
            .arg("-hide_banner")
            .arg("-nostdin")
            .arg("-y")
            .arg("-f")
            .arg("lavfi")
            .arg("-i")
            .arg("testsrc=size=96x54:rate=1")
            .arg("-frames:v")
            .arg("1")
            .arg("-q:v")
            .arg("2")
            .arg(&poster_path)
            .stdin(std::process::Stdio::null())
            .output()
            .await
            .unwrap();
        assert!(
            ffmpeg_output.status.success(),
            "ffmpeg failed to generate DLNA thumbnail sizing fixture: {}",
            String::from_utf8_lossy(&ffmpeg_output.stderr)
        );
        let item = db
            .media_items()
            .await
            .unwrap()
            .into_iter()
            .find(|item| item.name == "Sized Thumbnail Movie")
            .unwrap();
        let server_id = db.server_state().await.unwrap().server_id;
        let app = router(AppState {
            db,
            web_dir: ".".into(),
            log_dir: log_root.path().join("logs"),
            local_address: "http://127.0.0.1:8097".to_string(),
        });

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!(
                        "/dlna/{server_id}/items/{}/thumbnail.png?MaxWidth=32&MaxHeight=32",
                        item.id
                    ))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        assert_eq!(
            response
                .headers()
                .get(header::CONTENT_TYPE)
                .and_then(|value| value.to_str().ok()),
            Some("image/jpeg")
        );
        assert_eq!(
            response
                .headers()
                .get("contentfeatures.dlna.org")
                .and_then(|value| value.to_str().ok()),
            Some(
                "DLNA.ORG_PN=JPEG_TN;DLNA.ORG_OP=01;DLNA.ORG_CI=0;DLNA.ORG_FLAGS=01500000000000000000000000000000"
            )
        );
        let resized_bytes = response.into_body().collect().await.unwrap().to_bytes();
        assert!(resized_bytes.starts_with(&[0xff, 0xd8]));
        let resized_path = log_root.path().join("resized-thumb.jpg");
        tokio::fs::write(&resized_path, &resized_bytes)
            .await
            .unwrap();
        let ffprobe_output = tokio::process::Command::new("ffprobe")
            .arg("-v")
            .arg("error")
            .arg("-select_streams")
            .arg("v:0")
            .arg("-show_entries")
            .arg("stream=width,height")
            .arg("-of")
            .arg("csv=s=x:p=0")
            .arg(&resized_path)
            .stdin(std::process::Stdio::null())
            .output()
            .await
            .unwrap();
        assert!(
            ffprobe_output.status.success(),
            "ffprobe failed to inspect resized DLNA thumbnail: {}",
            String::from_utf8_lossy(&ffprobe_output.stderr)
        );
        let dimensions = String::from_utf8_lossy(&ffprobe_output.stdout);
        let (width, height) = dimensions.trim().split_once('x').unwrap();
        assert_eq!(width.parse::<u32>().unwrap(), 32);
        assert!(
            height.parse::<u32>().unwrap() <= 32,
            "resized dimensions should fit max bounds, got {}",
            dimensions.trim()
        );

        let response = app
            .oneshot(
                Request::builder()
                    .method(Method::HEAD)
                    .uri(format!(
                        "/dlna/{server_id}/items/{}/thumbnail.png?width=32&height=32",
                        item.id
                    ))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        assert_eq!(
            response
                .headers()
                .get(header::CONTENT_TYPE)
                .and_then(|value| value.to_str().ok()),
            Some("image/jpeg")
        );
        assert_eq!(
            response
                .headers()
                .get(header::CONTENT_LENGTH)
                .and_then(|value| value.to_str().ok())
                .and_then(|value| value.parse::<usize>().ok()),
            Some(resized_bytes.len())
        );
        let body = response.into_body().collect().await.unwrap().to_bytes();
        assert!(body.is_empty());
    }

    #[tokio::test]
    async fn dlna_control_point_golden_direct_stream_and_real_hls_transcode() {
        let media_root = tempfile::tempdir().unwrap();
        let video_path = media_root.path().join("Golden DLNA Movie.mp4");
        let ffmpeg_output = tokio::process::Command::new("ffmpeg")
            .arg("-hide_banner")
            .arg("-nostdin")
            .arg("-y")
            .arg("-f")
            .arg("lavfi")
            .arg("-i")
            .arg("testsrc=size=160x90:rate=24")
            .arg("-t")
            .arg("2")
            .arg("-an")
            .arg("-c:v")
            .arg("libx264")
            .arg("-preset")
            .arg("ultrafast")
            .arg("-pix_fmt")
            .arg("yuv420p")
            .arg("-movflags")
            .arg("+faststart")
            .arg(&video_path)
            .stdin(std::process::Stdio::null())
            .output()
            .await
            .unwrap();
        assert!(
            ffmpeg_output.status.success(),
            "ffmpeg failed to generate DLNA golden fixture: {}",
            String::from_utf8_lossy(&ffmpeg_output.stderr)
        );

        let db = Database::connect("sqlite::memory:").await.unwrap();
        let user = db
            .update_first_user("dlna-golden-user".to_string(), "secret")
            .await
            .unwrap();
        db.issue_api_key_for_user(user.id, "dlna-golden-key")
            .await
            .unwrap();
        db.update_named_configuration("network", json!({ "EnableUPnP": true }))
            .await
            .unwrap();
        let folder = db
            .upsert_virtual_folder(
                "Golden DLNA",
                Some("movies"),
                vec![media_root.path().to_string_lossy().to_string()],
            )
            .await
            .unwrap();
        assert_eq!(db.scan_virtual_folder_items(folder.id).await.unwrap(), 1);
        let item = db
            .media_items()
            .await
            .unwrap()
            .into_iter()
            .find(|item| item.name == "Golden DLNA Movie")
            .unwrap();
        db.update_media_item_media_info(
            item.id,
            Some(20_000_000),
            Some(250_000),
            Some(160),
            Some(90),
            vec![json!({
                "Type": "Video",
                "Index": 0,
                "Codec": "h264",
                "Width": 160,
                "Height": 90
            })],
        )
        .await
        .unwrap();
        let server_id = db.server_state().await.unwrap().server_id;
        let test_db = db.clone();
        let app = router(AppState {
            db,
            web_dir: ".".into(),
            log_dir: ".".into(),
            local_address: "http://127.0.0.1:8097".to_string(),
        });

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!("/dlna/{server_id}/description.xml"))
                    .header(header::HOST, "127.0.0.1:8097")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body = response.into_body().collect().await.unwrap().to_bytes();
        let description = String::from_utf8(body.to_vec()).unwrap();
        assert!(description.contains("urn:schemas-upnp-org:device:MediaServer:1"));
        assert!(description.contains("ContentDirectory"));
        assert!(description.contains("ConnectionManager"));
        assert!(description.contains("X_MS_MediaReceiverRegistrar"));

        let browse_folder = format!(
            r#"<?xml version="1.0"?>
<s:Envelope xmlns:s="http://schemas.xmlsoap.org/soap/envelope/">
  <s:Body>
    <u:Browse xmlns:u="urn:schemas-upnp-org:service:ContentDirectory:1">
      <ObjectID>folder:{}</ObjectID>
      <BrowseFlag>BrowseDirectChildren</BrowseFlag>
      <Filter>*</Filter>
      <StartingIndex>0</StartingIndex>
      <RequestedCount>0</RequestedCount>
      <SortCriteria></SortCriteria>
    </u:Browse>
  </s:Body>
</s:Envelope>"#,
            folder.id
        );
        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .method(Method::POST)
                    .uri(format!("/dlna/{server_id}/contentdirectory/control"))
                    .header(header::HOST, "127.0.0.1:8097")
                    .header(header::CONTENT_TYPE, "text/xml; charset=utf-8")
                    .body(Body::from(browse_folder))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body = response.into_body().collect().await.unwrap().to_bytes();
        let browse_response = String::from_utf8(body.to_vec()).unwrap();
        assert!(browse_response.contains("<NumberReturned>1</NumberReturned>"));
        assert!(browse_response.contains("Golden DLNA Movie"));
        assert!(
            browse_response.contains(&format!("/dlna/{server_id}/items/{}/stream.mp4", item.id))
        );
        assert!(browse_response.contains(&format!(
            "/dlna/{server_id}/items/{}/transcode.m3u8",
            item.id
        )));

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!("/dlna/{server_id}/items/{}/stream.mp4", item.id))
                    .header(header::RANGE, "bytes=0-15")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::PARTIAL_CONTENT);
        assert_eq!(
            response
                .headers()
                .get(header::CONTENT_TYPE)
                .and_then(|value| value.to_str().ok()),
            Some("video/mp4")
        );
        let direct_bytes = response.into_body().collect().await.unwrap().to_bytes();
        assert_eq!(&direct_bytes[4..8], b"ftyp");

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!(
                        "/dlna/{server_id}/items/{}/transcode.m3u8",
                        item.id
                    ))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body = response.into_body().collect().await.unwrap().to_bytes();
        let master_playlist = String::from_utf8(body.to_vec()).unwrap();
        let play_session_id = master_playlist
            .lines()
            .find_map(|line| {
                line.strip_prefix("hls/")
                    .and_then(|value| value.strip_suffix("/main.m3u8"))
            })
            .expect("DLNA master playlist must contain media playlist URI")
            .to_string();

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!(
                        "/dlna/{server_id}/items/{}/hls/{play_session_id}/main.m3u8",
                        item.id
                    ))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body = response.into_body().collect().await.unwrap().to_bytes();
        let media_playlist = String::from_utf8(body.to_vec()).unwrap();
        assert!(media_playlist.contains("#EXTINF"));
        let segment_path = media_playlist
            .lines()
            .find(|line| line.starts_with("/dlna/") && line.ends_with(".ts"))
            .expect("DLNA media playlist must contain rewritten TS segment path");

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(segment_path)
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        assert_eq!(
            response
                .headers()
                .get(header::CONTENT_TYPE)
                .and_then(|value| value.to_str().ok()),
            Some("video/mp2t")
        );
        let segment_bytes = response.into_body().collect().await.unwrap().to_bytes();
        assert!(
            segment_bytes.len() >= 188,
            "DLNA HLS segment should contain at least one TS packet"
        );
        assert_eq!(segment_bytes[0], 0x47);

        for _ in 0..50 {
            let session = test_db
                .transcode_session_by_play_session_id(&play_session_id)
                .await
                .unwrap()
                .expect("DLNA HLS session should exist");
            if matches!(session.status.as_str(), "completed" | "failed" | "stopped") {
                let _ = cleanup_hls_transcode_files(&session.output_path).await;
                break;
            }
            tokio::time::sleep(std::time::Duration::from_millis(100)).await;
        }
    }

    #[tokio::test]
    async fn dlna_browse_physical_directory_hierarchy() {
        use base64::{Engine as _, engine::general_purpose::URL_SAFE_NO_PAD};

        let media_root = tempfile::tempdir().unwrap();
        let season_one = media_root.path().join("Example Show").join("Season 01");
        let season_two = media_root.path().join("Example Show").join("Season 02");
        let other_show = media_root.path().join("Second Show").join("Season 01");
        tokio::fs::create_dir_all(&season_one).await.unwrap();
        tokio::fs::create_dir_all(&season_two).await.unwrap();
        tokio::fs::create_dir_all(&other_show).await.unwrap();
        tokio::fs::write(season_one.join("S01E01 Pilot.mp4"), b"pilot")
            .await
            .unwrap();
        tokio::fs::write(season_one.join("S01E02 Next.mp4"), b"next")
            .await
            .unwrap();
        tokio::fs::write(season_two.join("S02E01 Return.mp4"), b"return")
            .await
            .unwrap();
        tokio::fs::write(other_show.join("S01E01 Start.mp4"), b"start-show")
            .await
            .unwrap();

        let db_path = media_root.path().join("dlna-hierarchy.sqlite");
        let db_url = format!("sqlite://{}?mode=rwc", db_path.to_string_lossy());
        let db = Database::connect(&db_url).await.unwrap();
        db.update_named_configuration("network", json!({ "EnableUPnP": true }))
            .await
            .unwrap();
        let folder = db
            .upsert_virtual_folder(
                "TV",
                Some("tvshows"),
                vec![media_root.path().to_string_lossy().to_string()],
            )
            .await
            .unwrap();
        assert_eq!(db.scan_virtual_folder_items(folder.id).await.unwrap(), 4);
        let scanned_names = db
            .media_items()
            .await
            .unwrap()
            .into_iter()
            .map(|item| item.name)
            .collect::<Vec<_>>();
        assert_eq!(
            scanned_names,
            vec![
                "S01E01 Pilot".to_string(),
                "S01E01 Start".to_string(),
                "S01E02 Next".to_string(),
                "S02E01 Return".to_string()
            ]
        );
        let server_id = db.server_state().await.unwrap().server_id;
        let app = router(AppState {
            db,
            web_dir: ".".into(),
            log_dir: ".".into(),
            local_address: "http://127.0.0.1:8097".to_string(),
        });

        let dir_id = |relative_path: &str| {
            format!(
                "dir:{}:{}",
                folder.id,
                URL_SAFE_NO_PAD.encode(relative_path.as_bytes())
            )
        };
        let browse_body = |object_id: &str| {
            format!(
                r#"<?xml version="1.0"?>
<s:Envelope xmlns:s="http://schemas.xmlsoap.org/soap/envelope/">
  <s:Body>
    <u:Browse xmlns:u="urn:schemas-upnp-org:service:ContentDirectory:1">
      <ObjectID>{object_id}</ObjectID>
      <BrowseFlag>BrowseDirectChildren</BrowseFlag>
      <Filter>*</Filter>
      <StartingIndex>0</StartingIndex>
      <RequestedCount>0</RequestedCount>
      <SortCriteria></SortCriteria>
    </u:Browse>
  </s:Body>
</s:Envelope>"#
            )
        };
        let browse = |app: axum::Router, object_id: String| async move {
            let response = app
                .oneshot(
                    Request::builder()
                        .method(Method::POST)
                        .uri(format!("/Dlna/{server_id}/ContentDirectory/Control"))
                        .header(header::HOST, "media.example.test:8097")
                        .header(header::CONTENT_TYPE, "text/xml; charset=utf-8")
                        .body(Body::from(browse_body(&object_id)))
                        .unwrap(),
                )
                .await
                .unwrap();
            assert_eq!(response.status(), StatusCode::OK);
            let body = response.into_body().collect().await.unwrap().to_bytes();
            String::from_utf8(body.to_vec()).unwrap()
        };

        let root_response = browse(app.clone(), format!("folder:{}", folder.id)).await;
        assert!(root_response.contains("<NumberReturned>2</NumberReturned>"));
        assert!(root_response.contains("<TotalMatches>2</TotalMatches>"));
        assert!(root_response.contains("Example Show"));
        assert!(root_response.contains("Second Show"));
        assert!(root_response.contains("object.container.videoContainer"));
        assert!(!root_response.contains("S01E01 Pilot"));

        let show_id = dir_id("Example Show");
        let show_response = browse(app.clone(), show_id.clone()).await;
        assert!(show_response.contains("<NumberReturned>2</NumberReturned>"));
        assert!(show_response.contains("Season 01"));
        assert!(show_response.contains("Season 02"));
        assert!(!show_response.contains("S01E01 Pilot"));

        let season_id = dir_id("Example Show/Season 01");
        let season_response = browse(app, season_id.clone()).await;
        assert!(
            season_response.contains("<NumberReturned>2</NumberReturned>"),
            "{season_response}"
        );
        assert!(
            season_response.contains("<TotalMatches>2</TotalMatches>"),
            "{season_response}"
        );
        assert!(season_response.contains("S01E01 Pilot"));
        assert!(season_response.contains("S01E02 Next"));
        assert!(season_response.contains(&format!("parentID=&quot;{}&quot;", season_id)));
        assert!(season_response.contains("object.item.videoItem"));
    }

