    #[test]
    fn hls_fallback_gate_is_single_attempt_and_requires_failed_empty_remux() {
        assert!(super::hls_remux_fallback_eligible(
            1,
            TranscodeJobKind::Remux,
            false,
            true,
            true,
        ));
        for (attempt, kind, segment_ready, failed, available) in [
            (2, TranscodeJobKind::Remux, false, true, true),
            (1, TranscodeJobKind::VideoEncode, false, true, true),
            (1, TranscodeJobKind::Remux, true, true, true),
            (1, TranscodeJobKind::Remux, false, false, true),
            (1, TranscodeJobKind::Remux, false, true, false),
        ] {
            assert!(!super::hls_remux_fallback_eligible(
                attempt,
                kind,
                segment_ready,
                failed,
                available,
            ));
        }
    }

    #[test]
    fn hls_seek_deadline_configuration_and_duration_are_bounded() {
        assert_eq!(
            super::hls_seek_generation_timeout_cap_seconds_from_value(None),
            180
        );
        assert_eq!(
            super::hls_seek_generation_timeout_cap_seconds_from_value(Some(" 30 ")),
            30
        );
        assert_eq!(
            super::hls_seek_generation_timeout_cap_seconds_from_value(Some("900")),
            900
        );
        for invalid in ["0", "29", "901", "invalid"] {
            assert_eq!(
                super::hls_seek_generation_timeout_cap_seconds_from_value(Some(invalid)),
                180
            );
        }

        assert_eq!(
            super::hls_seek_generation_timeout_with_cap(0, 180),
            StdDuration::from_secs(30)
        );
        assert_eq!(
            super::hls_seek_generation_timeout_with_cap(10_000_000, 180),
            StdDuration::from_secs(30)
        );
        assert_eq!(
            super::hls_seek_generation_timeout_with_cap(540_000_000, 180),
            StdDuration::from_secs(123)
        );
        assert_eq!(
            super::hls_seek_generation_timeout_with_cap(i64::MAX, 90),
            StdDuration::from_secs(90)
        );
    }

    #[tokio::test]
    async fn hls_seek_deadline_fast_exit_remains_a_normal_exit() {
        let command = jellyrin_core::FfmpegCommandSpec::new(
            "sh",
            vec!["-c".to_string(), "exit 0".to_string()],
        );
        let mut process = super::spawn_transcode_process(&command).unwrap();
        let outcome = super::wait_for_hls_seek_process(
            &mut process,
            std::future::pending(),
            StdDuration::from_secs(2),
        )
        .await;
        assert!(matches!(
            outcome,
            super::HlsSeekProcessOutcome::Exited(Ok(exit)) if exit.success
        ));
    }

    #[cfg(unix)]
    #[tokio::test]
    async fn hls_seek_deadline_timeout_stops_and_reaps_process() {
        let command = jellyrin_core::FfmpegCommandSpec::new(
            "sh",
            vec!["-c".to_string(), "sleep 30".to_string()],
        );
        let mut process = super::spawn_transcode_process(&command).unwrap();
        let process_id = process.process_id().unwrap();
        let outcome = super::wait_for_hls_seek_process(
            &mut process,
            std::future::pending(),
            StdDuration::from_millis(25),
        )
        .await;
        assert!(matches!(
            outcome,
            super::HlsSeekProcessOutcome::TimedOut(Ok(_))
        ));
        #[cfg(target_os = "linux")]
        assert!(
            !tokio::fs::try_exists(format!("/proc/{process_id}"))
                .await
                .unwrap()
        );
    }

    // Spec: live_tv_channel_media_source of a remote (HDHomeRun) channel includes
    // SupportsTranscoding:true, TranscodingSubProtocol:"hls", and TranscodingUrl pointing to
    // master.m3u8 (or live.m3u8) with a stable PlaySessionId embedded.
    #[test]
    fn live_tv_remote_channel_media_source_exposes_hls_transcode_fields() {
        let channel = json!({
            "Id": "hdhr_4.1",
            "Name": "NBC HD",
            "Path": "http://192.168.1.100:5004/auto/v4.1",
        });
        let ms = live_tv_channel_media_source(&channel).unwrap();
        assert_eq!(
            ms["SupportsTranscoding"], true,
            "remote channel must support transcoding"
        );
        assert_eq!(ms["TranscodingSubProtocol"], "hls");
        assert_eq!(ms["TranscodingContainer"], "ts");
        // TranscodingUrl must include master.m3u8 or live.m3u8 and a PlaySessionId.
        let url = ms["TranscodingUrl"].as_str().unwrap_or("");
        assert!(
            url.contains("master.m3u8") || url.contains("live.m3u8"),
            "TranscodingUrl must reference master.m3u8 or live.m3u8: {url}"
        );
        assert!(
            url.contains("PlaySessionId="),
            "TranscodingUrl must include PlaySessionId: {url}"
        );
        assert_eq!(
            ms["SupportsDirectStream"], true,
            "remote live TV should prefer the CPU-free direct proxy when the client accepts TS"
        );
        assert_eq!(ms["SupportsDirectPlay"], false);
        assert_eq!(ms["DefaultAudioStreamIndex"], 1);
        assert_eq!(ms["MediaStreams"][1]["Type"], "Audio");
        assert_eq!(ms["MediaStreams"][1]["Codec"], "aac");
    }

