    #[tokio::test]
    #[serial(live_tv_timing, playback_events)]
    async fn live_tv_startup_reconciliation_restarts_in_window_timer() {
        use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
        use tokio::net::TcpListener;

        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let port = listener.local_addr().unwrap().port();
        let ts_payload: Vec<u8> = (0u8..188).cycle().take(1880).collect();
        let ts_clone = ts_payload.clone();
        tokio::spawn(async move {
            if let Ok((mut stream, _)) = listener.accept().await {
                let (reader, mut writer) = stream.split();
                let mut reader = BufReader::new(reader);
                let mut line = String::new();
                loop {
                    line.clear();
                    if reader.read_line(&mut line).await.unwrap_or(0) == 0 {
                        break;
                    }
                    if line == "\r\n" {
                        break;
                    }
                }
                let header = format!(
                    "HTTP/1.1 200 OK\r\nContent-Type: video/mp2t\r\nContent-Length: {}\r\n\r\n",
                    ts_clone.len()
                );
                let _ = writer.write_all(header.as_bytes()).await;
                let _ = writer.write_all(&ts_clone).await;
            }
        });

        let dir = tempfile::tempdir().unwrap();
        let log_dir = dir.path().join("logs");
        tokio::fs::create_dir_all(&log_dir).await.unwrap();
        let stale_file = dir.path().join("livetv/recordings/restart.ts");
        tokio::fs::create_dir_all(stale_file.parent().unwrap())
            .await
            .unwrap();
        tokio::fs::write(&stale_file, b"partial").await.unwrap();

        let db = Database::connect("sqlite::memory:").await.unwrap();
        let now = OffsetDateTime::now_utc();
        // Recording tasks are process-global, while the test databases are isolated. Keep every
        // registry key unique so another concurrent Live TV test cannot replace this task.
        let test_suffix = Uuid::new_v4().simple().to_string();
        let tuner_id = format!("hdhr-restart-{test_suffix}");
        let channel_id = format!("hdhr_restart_{test_suffix}");
        let recording_id = format!("stale-recording-{test_suffix}");
        let timer_id = format!("restart-timer-{test_suffix}");
        let mut config = default_live_tv_configuration();
        config["TunerHosts"] = serde_json::json!([{
            "Id": tuner_id,
            "FriendlyName": "HDHomeRun Test",
            "Channels": [{
                "Id": channel_id.clone(),
                "Name": "Channel 4.1",
                "Number": "4.1",
                "Path": format!("http://127.0.0.1:{port}/auto/v4.1"),
            }]
        }]);
        config["Recordings"] = serde_json::json!([{
            "Id": recording_id,
            "TimerId": timer_id.clone(),
            "Name": "Restart Show",
            "ChannelId": channel_id.clone(),
            "Path": stale_file.to_string_lossy().to_string(),
            "Status": "InProgress",
            "StartDate": format_time_for_json(now - Duration::seconds(5)),
            "EndDate": format_time_for_json(now + Duration::seconds(30)),
            "DateCreated": format_time_for_json(now - Duration::seconds(5)),
        }]);
        config["Timers"] = serde_json::json!([{
            "Id": timer_id.clone(),
            "Name": "Restart Show",
            "ChannelId": channel_id,
            "StartDate": format_time_for_json(now - Duration::seconds(5)),
            "EndDate": format_time_for_json(now + Duration::seconds(30)),
            "PostPaddingSeconds": 0,
            "Status": "InProgress",
            "IsSeries": false,
        }]);
        db.update_named_configuration("livetv", live_tv_configuration_json(config))
            .await
            .unwrap();

        let recovery = reconcile_live_tv_recordings_on_startup(&db, &log_dir)
            .await
            .unwrap();
        assert_eq!(recovery.removed_stale_recordings, 1);
        assert_eq!(recovery.removed_expired_timers, 0);
        assert_eq!(recovery.restarted_recordings, 1);
        assert!(
            !stale_file.exists(),
            "stale file should not block restarted recording"
        );

        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(30);
        loop {
            let config = db.named_configuration("livetv").await.unwrap().unwrap();
            let recordings = config["Recordings"].as_array().cloned().unwrap_or_default();
            if let Some(completed) = recordings
                .iter()
                .find(|r| r["Status"].as_str() == Some("Completed"))
            {
                assert_eq!(completed["TimerId"], timer_id);
                let path = completed["Path"].as_str().unwrap();
                assert!(tokio::fs::metadata(path).await.unwrap().len() > 0);
                let timers = config["Timers"].as_array().cloned().unwrap_or_default();
                let timer = timers
                    .iter()
                    .find(|timer| timer["Id"].as_str() == Some(timer_id.as_str()))
                    .unwrap();
                assert_eq!(timer["Status"], "Completed");
                assert_eq!(timer["RecordingPath"], path);
                break;
            }
            assert!(
                std::time::Instant::now() < deadline,
                "recording did not complete"
            );
            tokio::time::sleep(std::time::Duration::from_millis(25)).await;
        }

        let second = reconcile_live_tv_recordings_on_startup(&db, &log_dir)
            .await
            .unwrap();
        assert_eq!(
            second,
            Default::default(),
            "completed recovery must be idempotent"
        );
    }

    #[tokio::test]
    #[serial(live_tv_timing, playback_events)]
    async fn live_tv_timer_scheduler_starts_future_timer_when_due() {
        use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
        use tokio::net::TcpListener;

        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let port = listener.local_addr().unwrap().port();
        let ts_payload: Vec<u8> = (0u8..188).cycle().take(1880).collect();
        let ts_clone = ts_payload.clone();
        let upstream_task = tokio::spawn(async move {
            let (mut stream, _) = listener.accept().await.unwrap();
            let (reader, mut writer) = stream.split();
            let mut reader = BufReader::new(reader);
            let mut line = String::new();
            loop {
                line.clear();
                if reader.read_line(&mut line).await.unwrap_or(0) == 0 {
                    break;
                }
                if line == "\r\n" {
                    break;
                }
            }
            let header = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: video/mp2t\r\nContent-Length: {}\r\n\r\n",
                ts_clone.len()
            );
            writer.write_all(header.as_bytes()).await.unwrap();
            writer.write_all(&ts_clone).await.unwrap();
            writer.shutdown().await.unwrap();
        });

        let dir = tempfile::tempdir().unwrap();
        let log_dir = dir.path().join("logs");
        tokio::fs::create_dir_all(&log_dir).await.unwrap();
        let db = Database::connect("sqlite::memory:").await.unwrap();
        let now = OffsetDateTime::now_utc();
        let mut config = default_live_tv_configuration();
        config["TunerHosts"] = serde_json::json!([{
            "Id": "hdhr-scheduler",
            "FriendlyName": "HDHomeRun Scheduler",
            "Channels": [{
                "Id": "hdhr_4.1",
                "Name": "Channel 4.1",
                "Number": "4.1",
                "Path": format!("http://127.0.0.1:{port}/auto/v4.1"),
            }]
        }]);
        config["Timers"] = serde_json::json!([{
            "Id": "future-timer",
            "Name": "Future Show",
            "ChannelId": "hdhr_4.1",
            "StartDate": format_time_for_json(now + Duration::milliseconds(120)),
            // The recording runs in a detached task. Keep its validity window at least as long
            // as this test's completion deadline so CPU-starved CI cannot expire the timer after
            // the scheduler accepts it but before the child task gets its first poll.
            "EndDate": format_time_for_json(now + Duration::seconds(30)),
            "PostPaddingSeconds": 0,
            "IsSeries": false,
        }]);
        db.update_named_configuration("livetv", live_tv_configuration_json(config))
            .await
            .unwrap();
        let state = AppState {
            db: db.clone(),
            web_dir: ".".into(),
            log_dir,
            local_address: "http://127.0.0.1:8097".to_string(),
        };

        let early = run_due_live_tv_timers(&state).await.unwrap();
        assert_eq!(
            early,
            LiveTvTimerSchedulerRun::default(),
            "future timer must not start before StartDate"
        );

        tokio::time::sleep(std::time::Duration::from_millis(160)).await;
        let due = run_due_live_tv_timers(&state).await.unwrap();
        assert_eq!(due.started_recordings, 1);
        assert_eq!(due.removed_expired_timers, 0);

        tokio::time::timeout(std::time::Duration::from_secs(10), upstream_task)
            .await
            .expect("scheduled recording did not open the upstream source")
            .expect("mock upstream task failed");

        // This test owns scheduler timing and handoff. Byte-for-byte recording completion is
        // covered by `live_tv_recording_copy_writes_bytes_to_file`; here we only wait for the
        // detached lifecycle to settle so it cannot leak into another test.
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
        loop {
            let config = db.named_configuration("livetv").await.unwrap().unwrap();
            let recordings = config["Recordings"].as_array().cloned().unwrap_or_default();
            let timer_settled = config["Timers"].as_array().is_none_or(|timers| {
                timers.iter().all(|timer| {
                    timer["Id"].as_str() != Some("future-timer")
                        || timer["Status"].as_str() == Some("Completed")
                })
            });
            let recording_settled = recordings.iter().all(|recording| {
                recording["TimerId"].as_str() != Some("future-timer")
                    || recording["Status"].as_str() != Some("InProgress")
            });
            if timer_settled && recording_settled {
                break;
            }
            assert!(
                std::time::Instant::now() < deadline,
                "scheduled future recording lifecycle did not settle"
            );
            tokio::time::sleep(std::time::Duration::from_millis(25)).await;
        }
    }

