    #[tokio::test]
    async fn tv_show_next_up_and_upcoming_use_scanned_episode_items() {
        let tmp = tempfile::tempdir().unwrap();
        let season_dir = tmp.path().join("Example Show").join("Season 01");
        tokio::fs::create_dir_all(&season_dir).await.unwrap();
        tokio::fs::write(season_dir.join("Example Show S01E01.mp4"), b"episode 1")
            .await
            .unwrap();
        tokio::fs::write(season_dir.join("Example Show S01E02.mp4"), b"episode 22")
            .await
            .unwrap();
        tokio::fs::write(season_dir.join("Example Show S01E03.mp4"), b"episode 333")
            .await
            .unwrap();
        let other_season_dir = tmp.path().join("Other Show").join("Season 01");
        tokio::fs::create_dir_all(&other_season_dir).await.unwrap();
        tokio::fs::write(
            other_season_dir.join("Other Show S01E01.mp4"),
            b"other episode",
        )
        .await
        .unwrap();

        let db = Database::connect("sqlite::memory:").await.unwrap();
        let user = db
            .update_first_user("admin".to_string(), "secret")
            .await
            .unwrap();
        let api_key = db
            .issue_api_key_for_user(user.id, "shows-test-key")
            .await
            .unwrap();
        let folder = db
            .upsert_virtual_folder(
                "Shows",
                Some("tvshows"),
                vec![tmp.path().to_string_lossy().to_string()],
            )
            .await
            .unwrap();
        db.scan_virtual_folder_items(folder.id).await.unwrap();
        let episodes = db.media_items().await.unwrap();
        assert_eq!(episodes.len(), 4);
        let first = episodes
            .iter()
            .find(|episode| episode.name.contains("Example Show S01E01"))
            .unwrap();
        let second = episodes
            .iter()
            .find(|episode| episode.name.contains("S01E02"))
            .unwrap();
        let third = episodes
            .iter()
            .find(|episode| episode.name.contains("S01E03"))
            .unwrap();
        let other = episodes
            .iter()
            .find(|episode| episode.name.contains("Other Show S01E01"))
            .unwrap();
        db.upsert_playback_state(UpsertPlaybackState {
            user_id: user.id,
            item_id: first.id,
            media_source_id: None,
            audio_stream_index: None,
            subtitle_stream_index: None,
            position_ticks: 0,
            is_paused: false,
            played: true,
        })
        .await
        .unwrap();
        let upcoming_reference = time::OffsetDateTime::now_utc();
        for (item_id, metadata) in [
            (
                first.id,
                json!({
                    "PremiereDate": super::format_time_for_json(
                        upcoming_reference + time::Duration::days(21)
                    )
                }),
            ),
            (
                second.id,
                json!({
                    "AirDate": super::format_time_for_json(
                        upcoming_reference + time::Duration::days(7)
                    )
                }),
            ),
            (
                third.id,
                json!({
                    "DateCreated": super::format_time_for_json(
                        upcoming_reference + time::Duration::days(14)
                    )
                }),
            ),
            (
                other.id,
                json!({
                    "PremiereDate": "not-an-rfc3339-date",
                    "AirDate": super::format_time_for_json(
                        upcoming_reference + time::Duration::days(1)
                    )
                }),
            ),
        ] {
            db.update_media_item_metadata(item_id, metadata)
                .await
                .unwrap();
        }
        // NextUp selects its one-per-series winner from rows fetched without `media_streams`, so
        // the retained page must be hydrated before serialization or these streams go missing.
        db.update_media_item_media_info(
            second.id,
            Some(12_345_000_000),
            Some(3_000_000),
            Some(1920),
            Some(1080),
            vec![json!({
                "Type": "Video",
                "Index": 0,
                "Codec": "h264",
                "Width": 1920,
                "Height": 1080
            })],
        )
        .await
        .unwrap();

        let app = router(AppState {
            db,
            web_dir: ".".into(),
            log_dir: ".".into(),
            local_address: "http://127.0.0.1:8097".to_string(),
        });

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri("/Shows/NextUp")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::UNAUTHORIZED);

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!("/shows/nextup?UserId={}&Limit=1", user.id))
                    .header("X-Emby-Token", &api_key)
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body = response.into_body().collect().await.unwrap().to_bytes();
        let next_up: Value = serde_json::from_slice(&body).unwrap();
        assert_eq!(next_up["TotalRecordCount"], 2);
        assert_eq!(next_up["Items"].as_array().unwrap().len(), 1);
        assert_eq!(next_up["Items"][0]["Id"], second.id.simple().to_string());
        assert_eq!(next_up["Items"][0]["Type"], "Episode");
        assert_eq!(next_up["Items"][0]["SeriesName"], "Example Show");
        assert_eq!(next_up["Items"][0]["ParentIndexNumber"], 1);
        assert_eq!(next_up["Items"][0]["IndexNumber"], 2);
        assert_eq!(next_up["Items"][0]["UserData"]["Played"], false);
        assert_eq!(next_up["Items"][0]["MediaStreams"][0]["Codec"], "h264");
        assert_eq!(next_up["Items"][0]["MediaStreams"][0]["Width"], 1920);
        assert_eq!(next_up["Items"][0]["RunTimeTicks"], 12_345_000_000_i64);
        let series_id = next_up["Items"][0]["SeriesId"].as_str().unwrap();

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!(
                        "/shows/nextup?UserId={}&Limit=1&EnableTotalRecordCount=false",
                        user.id
                    ))
                    .header("X-Emby-Token", &api_key)
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body = response.into_body().collect().await.unwrap().to_bytes();
        let next_up_without_total: Value = serde_json::from_slice(&body).unwrap();
        assert_eq!(next_up_without_total["TotalRecordCount"], 0);
        assert_eq!(next_up_without_total["Items"].as_array().unwrap().len(), 1);

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!(
                        "/shows/nextup?UserId={}&SeriesId={series_id}&Limit=10",
                        user.id
                    ))
                    .header("X-Emby-Token", &api_key)
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body = response.into_body().collect().await.unwrap().to_bytes();
        let filtered_next_up: Value = serde_json::from_slice(&body).unwrap();
        assert_eq!(filtered_next_up["TotalRecordCount"], 1);
        assert_eq!(
            filtered_next_up["Items"][0]["SeriesId"],
            next_up["Items"][0]["SeriesId"]
        );
        assert_eq!(
            filtered_next_up["Items"][0]["Id"],
            second.id.simple().to_string()
        );

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!("/Items/Counts?UserId={}", user.id))
                    .header("X-Emby-Token", &api_key)
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body = response.into_body().collect().await.unwrap().to_bytes();
        let counts: Value = serde_json::from_slice(&body).unwrap();
        assert_eq!(counts["SeriesCount"], 2);
        assert_eq!(counts["EpisodeCount"], 4);
        assert_eq!(counts["ItemCount"], 4);

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!(
                        "/Users/{}/Items/Counts?Filters=IsUnplayed",
                        user.id
                    ))
                    .header("X-Emby-Token", &api_key)
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body = response.into_body().collect().await.unwrap().to_bytes();
        let unplayed_counts: Value = serde_json::from_slice(&body).unwrap();
        assert_eq!(unplayed_counts["SeriesCount"], 2);
        assert_eq!(unplayed_counts["EpisodeCount"], 3);
        assert_eq!(unplayed_counts["ItemCount"], 3);

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!("/Shows/{series_id}/Seasons?UserId={}", user.id))
                    .header("X-Emby-Token", &api_key)
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body = response.into_body().collect().await.unwrap().to_bytes();
        let seasons: Value = serde_json::from_slice(&body).unwrap();
        assert_eq!(seasons["TotalRecordCount"], 1);
        assert_eq!(seasons["Items"][0]["Type"], "Season");
        assert_eq!(seasons["Items"][0]["SeriesName"], "Example Show");
        assert_eq!(seasons["Items"][0]["SeriesId"], series_id);
        assert_eq!(seasons["Items"][0]["IndexNumber"], 1);
        assert_eq!(seasons["Items"][0]["ChildCount"], 3);
        let season_id = seasons["Items"][0]["Id"].as_str().unwrap();

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!(
                        "/Items?ParentId={series_id}&Recursive=false&IncludeItemTypes=Season&StartIndex=0&Limit=20&SortBy=IndexNumber&EnableUserData=false&EnableTotalRecordCount=true&EnableImages=true"
                    ))
                    .header("X-Emby-Token", &api_key)
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body = response.into_body().collect().await.unwrap().to_bytes();
        let item_seasons: Value = serde_json::from_slice(&body).unwrap();
        assert_eq!(item_seasons["TotalRecordCount"], 1);
        assert_eq!(item_seasons["Items"][0]["Id"], season_id);
        assert_eq!(item_seasons["Items"][0]["Type"], "Season");
        assert_eq!(item_seasons["Items"][0]["ChildCount"], 3);

        let hyphenated_series_id = parse_jellyfin_uuid(series_id)
            .unwrap()
            .hyphenated()
            .to_string();
        let hyphenated_season_id = parse_jellyfin_uuid(season_id)
            .unwrap()
            .hyphenated()
            .to_string();
        for endpoint in [
            format!("/Items/{hyphenated_series_id}/ThemeSongs?InheritFromParent=false"),
            format!("/Items/{hyphenated_season_id}/SpecialFeatures"),
        ] {
            let response = app
                .clone()
                .oneshot(
                    Request::builder()
                        .uri(&endpoint)
                        .header("X-Emby-Token", &api_key)
                        .body(Body::empty())
                        .unwrap(),
                )
                .await
                .unwrap();
            assert_eq!(response.status(), StatusCode::OK, "{endpoint}");
            let body = response.into_body().collect().await.unwrap().to_bytes();
            let empty: Value = serde_json::from_slice(&body).unwrap();
            if let Some(items) = empty.as_array() {
                assert!(items.is_empty(), "{endpoint}");
            } else {
                assert_eq!(empty["TotalRecordCount"], 0, "{endpoint}");
                assert!(empty["Items"].as_array().unwrap().is_empty(), "{endpoint}");
            }
        }

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!(
                        "/shows/{series_id}/episodes?UserId={}&SeasonId={season_id}",
                        user.id
                    ))
                    .header("X-Emby-Token", &api_key)
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body = response.into_body().collect().await.unwrap().to_bytes();
        let episodes_result: Value = serde_json::from_slice(&body).unwrap();
        assert_eq!(episodes_result["TotalRecordCount"], 3);
        assert_eq!(
            episodes_result["Items"][0]["Id"],
            first.id.simple().to_string()
        );
        assert_eq!(
            episodes_result["Items"][1]["Id"],
            second.id.simple().to_string()
        );
        assert_eq!(
            episodes_result["Items"][2]["Id"],
            third.id.simple().to_string()
        );

        // Android TV loads additional series-detail rows through generic `/Items` pagination.
        // This must stay scoped to the one series rather than falling back to the full catalogue.
        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!(
                        "/Items?StartIndex=1&Limit=1&ParentId={series_id}&Fields=MediaSources&Fields=MediaStreams&Fields=Overview&IncludeItemTypes=Episode&EnableTotalRecordCount=true&EnableImages=true"
                    ))
                    .header("X-Emby-Token", &api_key)
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let generic_episodes: Value =
            serde_json::from_slice(&response.into_body().collect().await.unwrap().to_bytes())
                .unwrap();
        assert_eq!(generic_episodes["TotalRecordCount"], 3);
        assert_eq!(generic_episodes["StartIndex"], 1);
        assert_eq!(generic_episodes["Items"].as_array().unwrap().len(), 1);
        assert_eq!(
            generic_episodes["Items"][0]["Id"],
            second.id.simple().to_string()
        );
        assert_eq!(generic_episodes["Items"][0]["Type"], "Episode");

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!(
                        "/Items?StartIndex=1&Limit=1&ParentId={season_id}&Fields=MediaSources&Fields=MediaStreams&Fields=Overview&IncludeItemTypes=Episode&EnableTotalRecordCount=true&EnableImages=true"
                    ))
                    .header("X-Emby-Token", &api_key)
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let season_episodes: Value =
            serde_json::from_slice(&response.into_body().collect().await.unwrap().to_bytes())
                .unwrap();
        assert_eq!(season_episodes["TotalRecordCount"], 3);
        assert_eq!(season_episodes["StartIndex"], 1);
        assert_eq!(season_episodes["Items"].as_array().unwrap().len(), 1);
        assert_eq!(
            season_episodes["Items"][0]["Id"],
            second.id.simple().to_string()
        );

        for (endpoint, expected_id, expected_start_index) in [
            (
                format!(
                    "/Library/Shows/{series_id}/Similar?UserId={}&Limit=1",
                    user.id
                ),
                first.id.simple().to_string(),
                0,
            ),
            (
                format!("/library/shows/{series_id}/similar?StartIndex=1&Limit=1"),
                second.id.simple().to_string(),
                1,
            ),
        ] {
            let endpoint = endpoint.as_str();
            let response = app
                .clone()
                .oneshot(
                    Request::builder()
                        .uri(endpoint)
                        .header("X-Emby-Token", &api_key)
                        .body(Body::empty())
                        .unwrap(),
                )
                .await
                .unwrap();
            assert_eq!(response.status(), StatusCode::OK, "{endpoint}");
            let body = response.into_body().collect().await.unwrap().to_bytes();
            let similar_show: Value = serde_json::from_slice(&body).unwrap();
            assert_eq!(similar_show["TotalRecordCount"], 3, "{endpoint}");
            assert_eq!(
                similar_show["StartIndex"], expected_start_index,
                "{endpoint}"
            );
            assert_eq!(similar_show["Items"][0]["Id"], expected_id, "{endpoint}");
            assert_eq!(similar_show["Items"][0]["Type"], "Episode", "{endpoint}");
            assert_eq!(
                similar_show["Items"][0]["SeriesId"], series_id,
                "{endpoint}"
            );
        }

        let response = app
            .oneshot(
                Request::builder()
                    .uri(format!(
                        "/Shows/Upcoming?UserId={}&StartIndex=1&Limit=1",
                        user.id
                    ))
                    .header("X-Emby-Token", &api_key)
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body = response.into_body().collect().await.unwrap().to_bytes();
        let upcoming: Value = serde_json::from_slice(&body).unwrap();
        assert_eq!(upcoming["TotalRecordCount"], 3);
        assert_eq!(upcoming["StartIndex"], 1);
        assert_eq!(upcoming["Items"].as_array().unwrap().len(), 1);
        assert_eq!(upcoming["Items"][0]["Id"], third.id.simple().to_string());
        assert_eq!(upcoming["Items"][0]["Type"], "Episode");
        assert_eq!(upcoming["Items"][0]["IndexNumber"], 3);
    }

    #[tokio::test]
    async fn plugin_series_anchor_id_resolves_to_its_canonical_series_for_seasons() {
        let storage = tempfile::tempdir().unwrap();
        let db = Database::connect("sqlite::memory:").await.unwrap();
        let user = db
            .update_first_user("admin".to_string(), "secret")
            .await
            .unwrap();
        let api_key = db
            .issue_api_key_for_user(user.id, "plugin-series-anchor-seasons-key")
            .await
            .unwrap();
        let anchor_id = stable_entity_id("plugin-series-anchor", "public-item");
        let canonical_series_id = stable_entity_id("plugin-series-anchor", "provider-series");
        let season_id = stable_entity_id("plugin-series-anchor", "provider-season-1");
        let mut items = vec![RemoteMediaItemUpsert {
            id: anchor_id.clone(),
            name: "Anchored Show".to_string(),
            path: "plugin-vod://anchor-test/series".to_string(),
            media_type: "Series".to_string(),
            collection_type: "tvshows".to_string(),
            runtime_ticks: None,
            bitrate: None,
            width: None,
            height: None,
            media_streams: Vec::new(),
            metadata: json!({
                "PluginVodKind": "series",
                "SeriesId": canonical_series_id,
                "SeriesName": "Anchored Show"
            }),
        }];
        for episode_number in 1..=2 {
            items.push(RemoteMediaItemUpsert {
                id: stable_entity_id("plugin-series-anchor", &format!("episode-{episode_number}")),
                name: format!("Anchored Show S01E{episode_number:02}"),
                path: format!("plugin-vod://anchor-test/series/episode-{episode_number}"),
                media_type: "Video".to_string(),
                collection_type: "tvshows".to_string(),
                runtime_ticks: Some(600_000_000),
                bitrate: Some(1_000_000),
                width: Some(1280),
                height: Some(720),
                media_streams: Vec::new(),
                metadata: json!({
                    "PluginVodKind": "episode",
                    "SeriesId": canonical_series_id,
                    "SeriesName": "Anchored Show",
                    "SeasonId": season_id,
                    "ParentIndexNumber": 1,
                    "IndexNumber": episode_number
                }),
            });
        }
        db.replace_remote_media_library_snapshot(
            "Anchor Test",
            "tvshows",
            "plugin-vod://anchor-test",
            items,
        )
        .await
        .unwrap();
        let state = AppState {
            db: db.clone(),
            web_dir: ".".into(),
            log_dir: storage.path().join("logs"),
            local_address: "http://127.0.0.1:8097".to_string(),
        };
        let expected_image = test_distinct_png_bytes();
        super::store_image_bytes(
            &state,
            super::ImageOwner::Item(&anchor_id),
            "Primary",
            0,
            expected_image.clone(),
        )
        .await
        .unwrap();
        let app = router(state);

        for endpoint in [
            format!(
                "/Items?ParentId={anchor_id}&Recursive=false&IncludeItemTypes=Season&StartIndex=0&Limit=20&SortBy=IndexNumber&EnableUserData=true&EnableTotalRecordCount=true&EnableImages=true"
            ),
            format!("/Shows/{anchor_id}/Seasons?UserId={}", user.id),
        ] {
            let response = app
                .clone()
                .oneshot(
                    Request::builder()
                        .uri(&endpoint)
                        .header("X-Emby-Token", &api_key)
                        .body(Body::empty())
                        .unwrap(),
                )
                .await
                .unwrap();
            assert_eq!(response.status(), StatusCode::OK, "{endpoint}");
            let seasons: Value =
                serde_json::from_slice(&response.into_body().collect().await.unwrap().to_bytes())
                    .unwrap();
            assert_eq!(seasons["TotalRecordCount"], 1, "{endpoint}");
            assert_eq!(seasons["Items"][0]["Type"], "Season", "{endpoint}");
            assert_eq!(seasons["Items"][0]["ChildCount"], 2, "{endpoint}");
            assert_eq!(
                seasons["Items"][0]["SeriesName"], "Anchored Show",
                "{endpoint}"
            );
            assert_eq!(
                seasons["Items"][0]["SeriesId"], canonical_series_id,
                "{endpoint}"
            );
        }

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!(
                        "/Shows/NextUp?UserId={}&SeriesId={anchor_id}&Limit=10",
                        user.id
                    ))
                    .header("X-Emby-Token", &api_key)
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let next_up: Value =
            serde_json::from_slice(&response.into_body().collect().await.unwrap().to_bytes())
                .unwrap();
        assert_eq!(next_up["TotalRecordCount"], 1);
        assert_eq!(next_up["Items"][0]["Type"], "Episode");
        assert_eq!(next_up["Items"][0]["SeriesId"], canonical_series_id);

        for endpoint in [
            format!("/Items/{anchor_id}/SpecialFeatures"),
            format!("/Items/{anchor_id}/ThemeSongs?InheritFromParent=false"),
        ] {
            let response = app
                .clone()
                .oneshot(
                    Request::builder()
                        .uri(&endpoint)
                        .header("X-Emby-Token", &api_key)
                        .body(Body::empty())
                        .unwrap(),
                )
                .await
                .unwrap();
            assert_eq!(response.status(), StatusCode::OK, "{endpoint}");
            let body: Value =
                serde_json::from_slice(&response.into_body().collect().await.unwrap().to_bytes())
                    .unwrap();
            if let Some(items) = body.as_array() {
                assert!(items.is_empty(), "{endpoint}");
            } else {
                assert_eq!(body["TotalRecordCount"], 0, "{endpoint}");
                assert!(body["Items"].as_array().unwrap().is_empty(), "{endpoint}");
            }
        }

        // Jellyfin Web opens a season through its item-detail routes after loading the season
        // list. A canonical SeasonId must be classified as a season before the synthetic-series
        // fallback and must trust the imported numbering instead of parsing the opaque path.
        for endpoint in [
            format!("/Items/{season_id}"),
            format!("/Users/{}/Items/{season_id}", user.id),
        ] {
            let response = app
                .clone()
                .oneshot(
                    Request::builder()
                        .uri(&endpoint)
                        .header("X-Emby-Token", &api_key)
                        .body(Body::empty())
                        .unwrap(),
                )
                .await
                .unwrap();
            assert_eq!(response.status(), StatusCode::OK, "{endpoint}");
            let detail: Value =
                serde_json::from_slice(&response.into_body().collect().await.unwrap().to_bytes())
                    .unwrap();
            assert_eq!(detail["Type"], "Season", "{endpoint}");
            assert_eq!(detail["Name"], "Season 1", "{endpoint}");
            assert_eq!(detail["IndexNumber"], 1, "{endpoint}");
            assert_eq!(detail["ChildCount"], 2, "{endpoint}");
            assert_eq!(detail["SeriesName"], "Anchored Show", "{endpoint}");
        }

        let image_response = app
            .oneshot(
                Request::builder()
                    .uri(format!("/Items/{season_id}/Images/Primary"))
                    .header("X-Emby-Token", &api_key)
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(image_response.status(), StatusCode::OK);
        let image_body = image_response
            .into_body()
            .collect()
            .await
            .unwrap()
            .to_bytes();
        assert_eq!(image_body.as_ref(), expected_image.as_slice());
    }

    #[tokio::test]
    async fn tv_fallbacks_ignore_512_movies_and_preserve_cross_folder_series_semantics() {
        let storage = tempfile::tempdir().unwrap();
        let movies_root = storage.path().join("movies");
        fs::create_dir_all(&movies_root).unwrap();
        for index in 0..512 {
            fs::write(movies_root.join(format!("Movie {index:03}.mp4")), b"movie").unwrap();
        }

        let shows_a = storage.path().join("shows-a");
        let scoped_a = shows_a.join("Scoped Show").join("Season 01");
        let other = shows_a.join("Other Show").join("Season 01");
        fs::create_dir_all(&scoped_a).unwrap();
        fs::create_dir_all(&other).unwrap();
        fs::write(scoped_a.join("Scoped Show S01E02.mp4"), b"episode two").unwrap();
        fs::write(other.join("Other Show S01E01.mp4"), b"other episode").unwrap();

        let shows_b = storage.path().join("shows-b");
        let scoped_b = shows_b.join("Scoped Show").join("Season 01");
        fs::create_dir_all(&scoped_b).unwrap();
        fs::write(scoped_b.join("Scoped Show S01E01.mp4"), b"episode one").unwrap();

        let db = Database::connect("sqlite::memory:").await.unwrap();
        let user = db
            .update_first_user("admin".to_string(), "secret")
            .await
            .unwrap();
        let api_key = db
            .issue_api_key_for_user(user.id, "tv-scoped-fallbacks-key")
            .await
            .unwrap();
        let mut folder_ids = BTreeMap::<&str, Uuid>::new();
        for (name, collection_type, path) in [
            ("Movies", "movies", &movies_root),
            ("Shows A", "tvshows", &shows_a),
            ("Shows B", "tvshows", &shows_b),
        ] {
            let folder = db
                .upsert_virtual_folder(
                    name,
                    Some(collection_type),
                    vec![path.to_string_lossy().to_string()],
                )
                .await
                .unwrap();
            db.scan_virtual_folder_items(folder.id).await.unwrap();
            folder_ids.insert(name, folder.id);
        }

        let initial_snapshot = super::tv_episode_catalog_snapshot(&db).await.unwrap();
        assert_eq!(initial_snapshot.items.len(), 3);
        assert_eq!(initial_snapshot.metadata_by_item.len(), 3);
        assert!(initial_snapshot.items.iter().all(|item| {
            item.collection_type
                .as_deref()
                .is_some_and(|value| value.eq_ignore_ascii_case("tvshows"))
        }));

        let scoped_episode_ids = initial_snapshot
            .items
            .iter()
            .filter_map(|item| {
                let info = super::tv_episode_info(item)?;
                (info.series_name == "Scoped Show").then_some((info.episode_number, item.id))
            })
            .collect::<BTreeMap<_, _>>();
        assert_eq!(scoped_episode_ids.len(), 2);
        let first_id = scoped_episode_ids[&Some(1)];
        let second_id = scoped_episode_ids[&Some(2)];
        let normal_item = db
            .media_items_by_collection_type("movies")
            .await
            .unwrap()
            .into_iter()
            .next()
            .unwrap();
        db.update_media_item_metadata(normal_item.id, json!({ "Genres": ["Owner Metadata"] }))
            .await
            .unwrap();
        db.update_media_item_metadata(second_id, json!({ "SeasonOverview": "Inline metadata" }))
            .await
            .unwrap();
        db.upsert_playback_state(UpsertPlaybackState {
            user_id: user.id,
            item_id: first_id,
            media_source_id: None,
            audio_stream_index: None,
            subtitle_stream_index: None,
            position_ticks: 0,
            is_paused: false,
            played: true,
        })
        .await
        .unwrap();

        let series_id = super::tv_series_id("Scoped Show");
        let season_id = super::tv_season_id("Scoped Show", Some(1));
        let metadata_id = super::stable_entity_id("Genre", "Owner Metadata");
        let list = db
            .create_media_list(
                "playlist",
                "Owner List",
                Some("playlists"),
                Some(user.id),
                vec![normal_item.id],
            )
            .await
            .unwrap();

        for owner_id in [
            normal_item.id.simple().to_string(),
            folder_ids["Movies"].simple().to_string(),
            list.id.simple().to_string(),
            series_id.clone(),
            season_id.clone(),
        ] {
            super::media_item_or_folder_by_id(&db, &owner_id)
                .await
                .unwrap_or_else(|error| panic!("owner {owner_id} failed: {error:?}"));
        }
        assert!(
            super::ensure_image_item_owner_exists(&db, &metadata_id)
                .await
                .unwrap()
                .is_some(),
            "metadata entities remain valid image owners"
        );
        assert_eq!(
            super::media_item_or_folder_by_id(&db, "not-a-uuid")
                .await
                .unwrap_err()
                .status,
            StatusCode::BAD_REQUEST
        );
        assert_eq!(
            super::media_item_or_folder_by_id(&db, &Uuid::new_v4().simple().to_string())
                .await
                .unwrap_err()
                .status,
            StatusCode::NOT_FOUND
        );

        let app = router(AppState {
            db,
            web_dir: ".".into(),
            log_dir: storage.path().join("logs"),
            local_address: "http://127.0.0.1:8097".to_string(),
        });

        for (item_id, expected_types, expected_folder_id) in [
            (
                normal_item.id.simple().to_string(),
                vec!["CollectionFolder", "Folder"],
                Some(folder_ids["Movies"]),
            ),
            (
                folder_ids["Movies"].simple().to_string(),
                vec!["Folder"],
                None,
            ),
            (
                series_id.clone(),
                vec!["CollectionFolder", "Folder"],
                Some(folder_ids["Shows B"]),
            ),
            (
                season_id.clone(),
                vec!["Series", "CollectionFolder", "Folder"],
                Some(folder_ids["Shows B"]),
            ),
            (metadata_id.clone(), vec![], None),
        ] {
            let response = app
                .clone()
                .oneshot(
                    Request::builder()
                        .uri(format!("/Library/Items/{item_id}/Ancestors"))
                        .header("X-Emby-Token", &api_key)
                        .body(Body::empty())
                        .unwrap(),
                )
                .await
                .unwrap();
            assert_eq!(response.status(), StatusCode::OK, "ancestor {item_id}");
            let ancestors: Value =
                serde_json::from_slice(&response.into_body().collect().await.unwrap().to_bytes())
                    .unwrap();
            let ancestors = ancestors.as_array().unwrap();
            assert_eq!(
                ancestors
                    .iter()
                    .map(|ancestor| ancestor["Type"].as_str().unwrap())
                    .collect::<Vec<_>>(),
                expected_types,
                "ancestor order for {item_id}"
            );
            if let Some(folder_id) = expected_folder_id {
                let folder = ancestors
                    .iter()
                    .find(|ancestor| ancestor["Type"] == "CollectionFolder")
                    .unwrap();
                assert_eq!(folder["Id"], folder_id.simple().to_string(), "{item_id}");
            }
        }

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!(
                        "/Shows/{series_id}/Episodes?UserId={}&StartIndex=1&Limit=1",
                        user.id
                    ))
                    .header("X-Emby-Token", &api_key)
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let episodes: Value =
            serde_json::from_slice(&response.into_body().collect().await.unwrap().to_bytes())
                .unwrap();
        assert_eq!(episodes["TotalRecordCount"], 2);
        assert_eq!(episodes["StartIndex"], 1);
        assert_eq!(episodes["Items"][0]["Id"], second_id.simple().to_string());
        assert_eq!(episodes["Items"][0]["SeriesName"], "Scoped Show");

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!("/Shows/{series_id}/Seasons?UserId={}", user.id))
                    .header("X-Emby-Token", &api_key)
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let seasons: Value =
            serde_json::from_slice(&response.into_body().collect().await.unwrap().to_bytes())
                .unwrap();
        assert_eq!(seasons["TotalRecordCount"], 1);
        assert_eq!(seasons["Items"][0]["ChildCount"], 2);
        assert_eq!(seasons["Items"][0]["UserData"]["UnplayedItemCount"], 1);
        assert_eq!(seasons["Items"][0]["Overview"], "Inline metadata");

        // Wholphin loads a series' seasons through the generic Items endpoint. Synthetic series
        // ids must use the bounded no-canonical-SeriesId fallback instead of scanning all TV rows.
        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!(
                        "/Items?StartIndex=0&Limit=20&Recursive=false&ParentId={series_id}&Fields=PrimaryImageAspectRatio&Fields=CanDelete&IncludeItemTypes=Season&SortBy=IndexNumber&EnableUserData=true&EnableTotalRecordCount=true&EnableImages=true"
                    ))
                    .header("X-Emby-Token", &api_key)
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let wholphin_seasons: Value =
            serde_json::from_slice(&response.into_body().collect().await.unwrap().to_bytes())
                .unwrap();
        assert_eq!(wholphin_seasons["TotalRecordCount"], 1);
        assert_eq!(wholphin_seasons["Items"][0]["Type"], "Season");
        assert_eq!(wholphin_seasons["Items"][0]["ChildCount"], 2);
        assert_eq!(
            wholphin_seasons["Items"][0]["UserData"]["ItemId"],
            wholphin_seasons["Items"][0]["Id"]
        );

        let response = app
            .oneshot(
                Request::builder()
                    .uri(format!(
                        "/Library/Shows/{series_id}/Similar?UserId={}&Limit=1",
                        user.id
                    ))
                    .header("X-Emby-Token", &api_key)
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let similar: Value =
            serde_json::from_slice(&response.into_body().collect().await.unwrap().to_bytes())
                .unwrap();
        assert_eq!(similar["TotalRecordCount"], 2);
        assert_eq!(similar["Items"][0]["Id"], first_id.simple().to_string());
    }

    #[tokio::test]
    async fn item_counts_fast_path_handles_more_than_one_page_and_complex_shapes_fallback_exactly()
    {
        let db = Database::connect("sqlite::memory:").await.unwrap();
        let user = db
            .update_first_user("admin".to_string(), "secret")
            .await
            .unwrap();
        let api_key = db
            .issue_api_key_for_user(user.id, "count-fast-path-key")
            .await
            .unwrap();
        let items = (0..513)
            .map(|index| RemoteMediaItemUpsert {
                id: Uuid::new_v4().to_string(),
                name: format!("Count Movie {index:03}"),
                path: format!("provider://count-fast/{index:03}.mkv"),
                media_type: "Video".to_string(),
                collection_type: "movies".to_string(),
                runtime_ticks: None,
                bitrate: None,
                width: None,
                height: None,
                media_streams: Vec::new(),
                metadata: if index == 512 {
                    json!({
                        "Overview": "MetadataOnlyNeedle",
                        "Genres": ["RareGenre"]
                    })
                } else {
                    json!({})
                },
            })
            .collect();
        db.replace_remote_media_library_snapshot(
            "Count Fast Path",
            "movies",
            "provider://count-fast",
            items,
        )
        .await
        .unwrap();
        let app = router(AppState {
            db,
            web_dir: ".".into(),
            log_dir: ".".into(),
            local_address: "http://127.0.0.1:8097".to_string(),
        });

        for (uri, expected) in [
            ("/Items/Counts", 513),
            ("/Items/Counts?SearchTerm=MetadataOnlyNeedle", 1),
            ("/Items/Counts?Genres=RareGenre", 1),
        ] {
            let response = app
                .clone()
                .oneshot(
                    Request::builder()
                        .uri(uri)
                        .header("X-Emby-Token", &api_key)
                        .body(Body::empty())
                        .unwrap(),
                )
                .await
                .unwrap();
            assert_eq!(response.status(), StatusCode::OK, "{uri}");
            let counts: Value =
                serde_json::from_slice(&response.into_body().collect().await.unwrap().to_bytes())
                    .unwrap();
            assert_eq!(counts["ItemCount"], expected, "{uri}");
            assert_eq!(counts["MovieCount"], expected, "{uri}");
        }
    }

