    #[tokio::test]
    async fn subtitle_routes_generate_hls_playlist_and_vtt_stream() {
        let tmp = tempfile::tempdir().unwrap();
        let subtitle = tmp.path().join("captions.srt");
        tokio::fs::write(
            &subtitle,
            b"1\n00:00:00,000 --> 00:00:01,500\nHello from Jellyrin\n\n",
        )
        .await
        .unwrap();
        let movie = tmp.path().join("Subtitle Source.mkv");
        let ffmpeg = tokio::process::Command::new("ffmpeg")
            .arg("-hide_banner")
            .arg("-nostdin")
            .arg("-y")
            .arg("-f")
            .arg("lavfi")
            .arg("-i")
            .arg("testsrc=size=160x90:rate=1")
            .arg("-f")
            .arg("lavfi")
            .arg("-i")
            .arg("anullsrc=channel_layout=stereo:sample_rate=44100")
            .arg("-i")
            .arg(&subtitle)
            .arg("-t")
            .arg("3")
            .arg("-map")
            .arg("0:v:0")
            .arg("-map")
            .arg("1:a:0")
            .arg("-map")
            .arg("2:s:0")
            .arg("-c:v")
            .arg("mpeg4")
            .arg("-c:a")
            .arg("aac")
            .arg("-c:s")
            .arg("srt")
            .arg(&movie)
            .output()
            .await
            .unwrap();
        assert!(
            ffmpeg.status.success(),
            "ffmpeg failed to create subtitle test video: {}",
            String::from_utf8_lossy(&ffmpeg.stderr)
        );

        let db = Database::connect("sqlite::memory:").await.unwrap();
        let user = db
            .update_first_user("admin".to_string(), "secret")
            .await
            .unwrap();
        let api_key = db
            .issue_api_key_for_user(user.id, "subtitle-test-key")
            .await
            .unwrap();
        let test_db = db.clone();
        let app = router(AppState {
            db,
            web_dir: ".".into(),
            log_dir: ".".into(),
            local_address: "http://127.0.0.1:8097".to_string(),
        });

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .method(Method::POST)
                    .uri(format!(
                        "/Library/VirtualFolders?name=SubtitleMovies&collectionType=movies&paths={}",
                        tmp.path().to_string_lossy()
                    ))
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from("{}"))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::NO_CONTENT);

        let item = test_db.media_items().await.unwrap().remove(0);
        let item_id = item.id.simple().to_string();
        let subtitle_index = media_item_streams(&item)
            .into_iter()
            .find(|stream| stream["Type"] == "Subtitle")
            .and_then(|stream| stream.get("Index").and_then(json_value_i64))
            .expect("subtitle stream index");

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!(
                        "/Videos/{item_id}/{item_id}/Subtitles/{subtitle_index}/subtitles.m3u8?segmentLength=2"
                    ))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::UNAUTHORIZED);

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!(
                        "/Videos/{item_id}/{item_id}/Subtitles/{subtitle_index}/subtitles.m3u8?segmentLength=2&apiKey={api_key}&PlaySessionId=subtitle-test-session"
                    ))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        assert_eq!(
            response.headers().get(header::CONTENT_TYPE).unwrap(),
            "application/vnd.apple.mpegurl"
        );
        let body = response.into_body().collect().await.unwrap().to_bytes();
        let playlist = String::from_utf8(body.to_vec()).unwrap();
        assert!(playlist.contains("#EXT-X-TARGETDURATION:2"));
        assert!(playlist.contains("stream.vtt?CopyTimestamps=true&AddVttTimeMap=true"));
        assert!(playlist.contains(&format!("ApiKey={api_key}")));
        assert!(playlist.contains("PlaySessionId=subtitle-test-session"));

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!(
                        "/Videos/{item_id}/{item_id}/Subtitles/{subtitle_index}/Stream.vtt?AddVttTimeMap=true"
                    ))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        assert_eq!(
            response.headers().get(header::CONTENT_TYPE).unwrap(),
            "text/vtt; charset=utf-8"
        );
        let body = response.into_body().collect().await.unwrap().to_bytes();
        let vtt = String::from_utf8(body.to_vec()).unwrap();
        assert!(vtt.starts_with("WEBVTT"));
        assert!(vtt.contains("X-TIMESTAMP-MAP=MPEGTS:0,LOCAL:00:00:00.000"));
        assert!(vtt.contains("Hello from Jellyrin"));

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!(
                        "/Videos/{item_id}/{item_id}/Subtitles/{subtitle_index}/Stream.js?apiKey={api_key}"
                    ))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        assert_eq!(
            response.headers().get(header::CONTENT_TYPE).unwrap(),
            "application/json; charset=utf-8"
        );
        let body = response.into_body().collect().await.unwrap().to_bytes();
        let events: Value = serde_json::from_slice(&body).unwrap();
        let start_ticks = events["TrackEvents"][0]["StartPositionTicks"]
            .as_i64()
            .unwrap();
        let end_ticks = events["TrackEvents"][0]["EndPositionTicks"]
            .as_i64()
            .unwrap();
        assert!(start_ticks < 1_000_000);
        assert!(end_ticks > start_ticks);
        assert_eq!(events["TrackEvents"][0]["Text"], "Hello from Jellyrin");

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!(
                        "/Subtitle/Videos/{item_id}/{item_id}/Subtitles/{subtitle_index}/Stream.vtt?AddVttTimeMap=true"
                    ))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);

        let response = app
            .oneshot(
                Request::builder()
                    .uri(format!(
                        "/subtitle/videos/{item_id}/{item_id}/subtitles/{subtitle_index}/10000000/stream.vtt?addVttTimeMap=true"
                    ))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
    }

    #[test]
    fn subtitle_vtt_events_json_parses_ffmpeg_timestamps() {
        let output = subtitle_vtt_to_track_events_json(
            b"WEBVTT\n\n00:09.844 --> 00:13.597\n<b>WALT DISNEY\nPRESENTA</b>\n\n",
        )
        .unwrap();
        let events: Value = serde_json::from_slice(&output).unwrap();
        assert_eq!(events["TrackEvents"][0]["StartPositionTicks"], 98_440_000);
        assert_eq!(events["TrackEvents"][0]["EndPositionTicks"], 135_970_000);
        assert_eq!(
            events["TrackEvents"][0]["Text"],
            "<b>WALT DISNEY\nPRESENTA</b>"
        );
    }

    #[test]
    fn subtitle_switch_falls_back_when_active_transcode_maps_another_track() {
        assert!(super::transcode_session_supplies_subtitle(Some(6), 6));
        assert!(!super::transcode_session_supplies_subtitle(Some(-1), 6));
        assert!(!super::transcode_session_supplies_subtitle(Some(5), 6));
        assert!(!super::transcode_session_supplies_subtitle(None, 6));
    }

