    #[tokio::test]
    #[serial(playback_events)]
    async fn transcode_process_observation_is_numeric_and_resets_for_fallback() {
        let play_session_id = "process-observation-reset";
        super::transcode_execution_registry().lock().await.clear();
        let command = jellyrin_core::FfmpegCommandSpec::new(
            "do-not-expose-this-program",
            vec![
                "secret-input-url".to_string(),
                "-c:v".to_string(),
                "libx264".to_string(),
            ],
        );
        super::register_transcode_execution(play_session_id, FfmpegMode::Enabled, &command).await;
        super::mark_transcode_process_started(play_session_id, Some(123)).await;
        super::update_transcode_execution_progress(
            play_session_id,
            &jellyrin_core::FfmpegProgress {
                frame: Some(42),
                fps: Some("25.0".to_string()),
                out_time_us: Some(2_500_000),
                speed: Some("1.5x".to_string()),
                ..jellyrin_core::FfmpegProgress::default()
            },
            Some(50_000_000),
        )
        .await;
        super::update_transcode_execution_resources(
            play_session_id,
            jellyrin_transcode::TranscodeProcessResourceSample {
                cpu_time_millis: 900,
                cpu_percent: Some(175.0),
                rss_bytes: 64 * 1024 * 1024,
                sampled_after_millis: 2_000,
            },
        )
        .await;

        let observation = super::transcode_execution_registry()
            .lock()
            .await
            .get(play_session_id)
            .cloned()
            .unwrap();
        let mut value = json!({});
        super::apply_transcode_execution_json(&mut value, &observation);
        assert_eq!(value["ProcessId"], 123);
        assert_eq!(value["TranscodingFrame"], 42);
        assert_eq!(value["TranscodingFramerate"], 25.0);
        assert_eq!(value["TranscodingSpeed"], 1.5);
        assert_eq!(value["CompletionPercentage"], 50.0);
        assert_eq!(value["ProcessCpuPercent"], 175.0);
        assert_eq!(value["ProcessRssBytes"], 64 * 1024 * 1024);
        let serialized = value.to_string();
        assert!(!serialized.contains("secret-input-url"));
        assert!(!serialized.contains("do-not-expose-this-program"));

        super::mark_transcode_process_started(play_session_id, Some(456)).await;
        let observation = super::transcode_execution_registry()
            .lock()
            .await
            .remove(play_session_id)
            .unwrap();
        assert_eq!(observation.process_id, Some(456));
        assert_eq!(observation.frame, None);
        assert_eq!(observation.speed, None);
        assert_eq!(observation.cpu_percent, None);
        assert_eq!(observation.rss_bytes, None);
    }

