    #[tokio::test]
    #[serial(live_tv_timing)]
    async fn resource_caps_terminal_live_hls_cleanup_honors_recent_access() {
        let stale_dir = isolated_transcode_test_dir("live-stale").await;
        let retained_dir = isolated_transcode_test_dir("live-retained").await;
        for dir in [&stale_dir, &retained_dir] {
            tokio::fs::write(dir.join("main.m3u8"), b"#EXTM3U\n")
                .await
                .unwrap();
        }
        let now = OffsetDateTime::now_utc();
        let user_id = Uuid::new_v4();
        for (id, dir) in [
            ("resource-cap-live-stale", &stale_dir),
            ("resource-cap-live-retained", &retained_dir),
        ] {
            live_hls_session_registry().lock().await.insert(
                id.to_string(),
                LiveHlsSessionEntry {
                    play_session_id: id.to_string(),
                    dedupe_key: format!("livetv:hls:{id}"),
                    channel_id: format!("channel-{id}"),
                    channel_url: "http://example.invalid/live.ts".to_string(),
                    media_streams: Vec::new(),
                    subtitle_stream_index: None,
                    output_path: dir.join("main.m3u8").to_string_lossy().to_string(),
                    user_id,
                    device_id: None,
                    status: "completed".to_string(),
                    process_id: None,
                    created_at: now - Duration::hours(2),
                    updated_at: now - Duration::hours(2),
                },
            );
        }

        super::touch_transcode_session("resource-cap-live-retained").await;
        let cleaned = super::cleanup_terminal_live_hls_sessions(Duration::minutes(30)).await;
        assert_eq!(cleaned, 1);
        assert!(!stale_dir.exists());
        assert!(retained_dir.exists());
        let registry = live_hls_session_registry().lock().await;
        assert!(!registry.contains_key("resource-cap-live-stale"));
        assert!(registry.contains_key("resource-cap-live-retained"));
        drop(registry);

        live_hls_session_registry()
            .lock()
            .await
            .remove("resource-cap-live-retained");
        super::forget_transcode_session_access("resource-cap-live-retained").await;
        assert!(super::cleanup_hls_transcode_dir(&retained_dir).await);
    }

