    fn resource_caps_live_hls_registry_only_evicts_terminal_entries() {
        let now = OffsetDateTime::now_utc();
        let entry = |id: &str, status: &str, age_minutes: i64| LiveHlsSessionEntry {
            play_session_id: id.to_string(),
            dedupe_key: format!("livetv:hls:{id}"),
            channel_id: format!("channel-{id}"),
            channel_url: "http://example.invalid/live.ts".to_string(),
            media_streams: Vec::new(),
            subtitle_stream_index: None,
            output_path: format!("/tmp/{id}/main.m3u8"),
            user_id: Uuid::nil(),
            device_id: None,
            status: status.to_string(),
            process_id: None,
            created_at: now - Duration::minutes(age_minutes),
            updated_at: now - Duration::minutes(age_minutes),
        };

        let mut registry = std::collections::HashMap::from([
            ("active".to_string(), entry("active", "running", 30)),
            ("terminal".to_string(), entry("terminal", "completed", 60)),
        ]);
        let evicted = super::insert_bounded_live_hls_session(
            &mut registry,
            entry("replacement", "starting", 0),
            2,
        )
        .unwrap();
        assert_eq!(evicted.len(), 1);
        assert_eq!(evicted[0].play_session_id, "terminal");
        assert!(registry.contains_key("active"));
        assert!(registry.contains_key("replacement"));

        let before = registry.len();
        let error = super::insert_bounded_live_hls_session(
            &mut registry,
            entry("rejected", "starting", 0),
            2,
        )
        .unwrap_err();
        assert!(error.contains("full"));
        assert_eq!(registry.len(), before);
        assert!(!registry.contains_key("rejected"));
    }

    #[tokio::test]
    async fn resource_caps_ffmpeg_wait_queue_rejects_excess_waiters() {
        let coordinator =
            jellyrin_transcode::TranscodeCoordinator::new(jellyrin_transcode::TranscodeLimits {
                max_total_jobs: 4,
                max_video_encodes: 1,
                max_audio_encodes: 1,
                max_remuxes: 1,
                max_auxiliary: 1,
                max_probes: 1,
            });
        let active = coordinator.acquire(TranscodeJobKind::Remux).await.unwrap();
        let wait_queue = Arc::new(tokio::sync::Semaphore::new(1));
        let waiting_coordinator = coordinator.clone();
        let waiting_queue = wait_queue.clone();
        let waiter = tokio::spawn(async move {
            super::acquire_ffmpeg_capacity_with_queue(
                &waiting_coordinator,
                waiting_queue,
                1,
                StdDuration::from_secs(2),
                TranscodeJobKind::Remux,
            )
            .await
        });
        for _ in 0..100 {
            if wait_queue.available_permits() == 0 {
                break;
            }
            tokio::task::yield_now().await;
        }
        assert_eq!(wait_queue.available_permits(), 0);

        let error = super::acquire_ffmpeg_capacity_with_queue(
            &coordinator,
            wait_queue.clone(),
            1,
            StdDuration::from_secs(2),
            TranscodeJobKind::Remux,
        )
        .await
        .unwrap_err();
        assert!(error.contains("wait queue is full"), "{error}");

        drop(active);
        let waiting_active = waiter.await.unwrap().unwrap();
        assert_eq!(wait_queue.available_permits(), 1);
        assert_eq!(waiting_active.kind(), TranscodeJobKind::Remux);
    }

    #[test]
