    #[tokio::test]
    async fn runtime_shutdown_drains_signals_and_aborts_retained_recording_starts() {
        let (cancellation, mut cancellation_rx) = tokio::sync::watch::channel(false);
        let (retained, retained_dropped) = tokio::sync::oneshot::channel::<()>();
        let task = tokio::spawn(async move {
            let _retained = retained;
            futures_util::future::pending::<()>().await;
        });
        let mut starts = std::collections::HashMap::from([(
            "starting-recording".to_string(),
            super::LiveTvRecordingStartEntry {
                generation: 1,
                cancellation,
                task: Some(task),
            },
        )]);

        let (count, tasks) = super::drain_recording_start_tasks(&mut starts);
        assert_eq!(count, 1);
        assert!(starts.is_empty());
        assert!(*cancellation_rx.borrow_and_update());
        assert_eq!(tasks.len(), 1);
        for task in &tasks {
            task.abort();
        }
        for task in tasks {
            assert!(task.await.unwrap_err().is_cancelled());
        }
        assert!(retained_dropped.await.is_err());
    }

    #[tokio::test]
    async fn runtime_shutdown_helpers_cancel_without_global_state() {
        let (transcode_stop, transcode_stopped) = tokio::sync::oneshot::channel();
        let transcodes =
            std::collections::HashMap::from([("shutdown-transcode".to_string(), transcode_stop)]);
        assert_eq!(super::signal_transcode_stops(transcodes), 1);
        assert!(transcode_stopped.await.is_ok());

        let (stream_cancel, stream_cancelled) = tokio::sync::oneshot::channel();
        let (stream_sender, _stream_receiver) = tokio::sync::broadcast::channel(1);
        let mut streams = std::collections::HashMap::from([(
            "shutdown-stream".to_string(),
            super::SharedLiveStreamHandle {
                refcount: 1,
                generation: 1,
                sender: stream_sender,
                _cancel: stream_cancel,
                _tuner_lease: None,
            },
        )]);
        let stream_handles = super::drain_live_stream_handles(&mut streams);
        assert!(streams.is_empty());
        assert_eq!(stream_handles.len(), 1);
        drop(stream_handles);
        assert!(stream_cancelled.await.is_err());

        let (recording_cancel, recording_cancelled) = tokio::sync::oneshot::channel();
        let mut recordings = std::collections::HashMap::from([(
            "shutdown-recording".to_string(),
            super::LiveTvRecordingHandle {
                _cancel: recording_cancel,
                path: "/tmp/shutdown-recording.ts".to_string(),
            },
        )]);
        let recording_handles = super::drain_recording_handles(&mut recordings);
        assert!(recordings.is_empty());
        assert_eq!(recording_handles.len(), 1);
        drop(recording_handles);
        assert!(recording_cancelled.await.is_err());

        let empty_host_slots = vec![Arc::new(tokio::sync::Mutex::new(None))];
        tokio::time::timeout(
            StdDuration::from_millis(100),
            super::shutdown_external_plugin_host_slots(empty_host_slots),
        )
        .await
        .unwrap();
    }

    #[tokio::test]
    async fn runtime_shutdown_signal_closes_guarded_stream_body() {
        let (shutdown, shutdown_rx) = tokio::sync::watch::channel(false);
        let (retained, retained_dropped) = tokio::sync::oneshot::channel::<()>();
        let stream = futures_util::stream::pending::<Result<bytes::Bytes, std::io::Error>>();
        let body = super::runtime_guarded_stream_body(stream, retained, shutdown_rx);
        shutdown.send_replace(true);

        let collected = tokio::time::timeout(StdDuration::from_millis(100), body.collect())
            .await
            .expect("guarded body must stop promptly")
            .unwrap()
            .to_bytes();
        assert!(collected.is_empty());
        assert!(retained_dropped.await.is_err());
    }

    #[test]
    fn xtream_remote_media_probe_marker_is_source_specific() {
        let mut metadata = json!({
            "Provider": "xtream",
            "RemoteSourceRef": {
                "Version": 1,
                "Provider": "xtream",
                "TunerId": "tuner-a",
                "Kind": "vod",
                "RemoteId": "42",
                "Extension": "mkv"
            }
        });
        let source_revision = xtream_remote_source_revision(&metadata).unwrap();
        set_xtream_remote_media_probe_metadata(&mut metadata, &source_revision, "Complete");

        assert!(xtream_remote_media_probe_current(
            &metadata,
            &source_revision
        ));
        assert!(!xtream_remote_media_probe_current(
            &metadata,
            "another-revision"
        ));
        assert_eq!(metadata["RemoteMediaProbe"]["ProbeVersion"], 1);
        assert!(metadata["RemoteMediaProbe"].get("SourceUrl").is_none());

        let recent_failed = json!({
            "RemoteMediaProbe": {
                "Status": "Failed",
                "SourceRevision": "revision-a",
                "DateLastProbed": format_time_for_json(OffsetDateTime::now_utc())
            }
        });
        assert!(xtream_remote_media_probe_current(
            &recent_failed,
            "revision-a"
        ));

        let stale_failed = json!({
            "RemoteMediaProbe": {
                "Status": "Failed",
                "SourceRevision": "revision-a",
                "DateLastProbed": format_time_for_json(
                    OffsetDateTime::now_utc() - Duration::minutes(2)
                )
            }
        });
        assert!(!xtream_remote_media_probe_current(
            &stale_failed,
            "revision-a"
        ));
    }

    #[test]
    fn plugin_vod_retries_consumed_or_expired_playback_grants_only() {
        for status in [
            reqwest::StatusCode::BAD_REQUEST,
            reqwest::StatusCode::UNAUTHORIZED,
            reqwest::StatusCode::FORBIDDEN,
        ] {
            assert!(super::plugin_vod_playback_grant_was_rejected(status));
        }
        for status in [
            reqwest::StatusCode::NOT_FOUND,
            reqwest::StatusCode::RANGE_NOT_SATISFIABLE,
            reqwest::StatusCode::INTERNAL_SERVER_ERROR,
        ] {
            assert!(!super::plugin_vod_playback_grant_was_rejected(status));
        }
    }

    #[test]
    fn xtream_probe_revision_changes_with_central_tuner_configuration() {
        let metadata = json!({
            "Provider": "xtream",
            "RemoteSourceRef": {
                "Version": 1,
                "Provider": "xtream",
                "TunerId": "tuner-a",
                "Kind": "vod",
                "RemoteId": "42",
                "Extension": "mkv"
            }
        });
        let first_config = json!({ "JellyrinConfigurationRevision": "config-a" });
        let rotated_config = json!({ "JellyrinConfigurationRevision": "config-b" });
        let first = resolved_xtream_remote_source_revision(
            &metadata,
            &first_config,
            "https://provider.invalid/movie/user/old-secret/42.mkv",
        )
        .unwrap();
        let unchanged = resolved_xtream_remote_source_revision(
            &metadata,
            &first_config,
            "https://provider.invalid/movie/user/old-secret/42.mkv",
        )
        .unwrap();
        let rotated = resolved_xtream_remote_source_revision(
            &metadata,
            &rotated_config,
            "https://provider.invalid/movie/user/new-secret/42.mkv",
        )
        .unwrap();

        assert_eq!(first, unchanged);
        assert_ne!(first, rotated);
        assert!(!first.contains("old-secret"));
        assert!(!rotated.contains("new-secret"));
    }

