    #[tokio::test]
    async fn xtream_compatible_vod_uses_range_direct_proxy_without_exposing_upstream() {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let upstream_address = listener.local_addr().unwrap();
        let upstream = tokio::spawn(async move {
            let (mut socket, _) = listener.accept().await.unwrap();
            let mut request = vec![0_u8; 4096];
            let read = socket.read(&mut request).await.unwrap();
            let request = String::from_utf8_lossy(&request[..read]).to_ascii_lowercase();
            assert!(request.starts_with("get /movie/user/pass/42.mkv"));
            assert!(request.contains("range: bytes=2-5"));
            socket
                .write_all(
                    b"HTTP/1.1 302 Found\r\nLocation: /cdn/42.mkv?opaque=redirect-token\r\nContent-Length: 0\r\nConnection: close\r\n\r\n",
                )
                .await
                .unwrap();

            let (mut socket, _) = listener.accept().await.unwrap();
            let mut redirected_request = vec![0_u8; 4096];
            let read = socket.read(&mut redirected_request).await.unwrap();
            let request = String::from_utf8_lossy(&redirected_request[..read]).to_ascii_lowercase();
            assert!(request.starts_with("get /cdn/42.mkv?opaque=redirect-token"));
            assert!(request.contains("range: bytes=2-5"));
            socket
                .write_all(
                    b"HTTP/1.1 206 Partial Content\r\nContent-Type: video/mp4\r\nAccept-Ranges: bytes\r\nContent-Range: bytes 2-5/10\r\nContent-Length: 4\r\nConnection: close\r\n\r\ncdef",
                )
                .await
                .unwrap();
        });

        let db = Database::connect("sqlite::memory:").await.unwrap();
        let user = db
            .update_first_user("admin".to_string(), "secret")
            .await
            .unwrap();
        let api_key = db
            .issue_api_key_for_user(user.id, "xtream-direct-proxy")
            .await
            .unwrap();
        let item_id = stable_entity_id("xtream-vod", "direct-42");
        let source_url = format!("http://{upstream_address}/movie/user/pass/42.mkv");
        db.replace_remote_media_library_snapshot(
            "Xtream Movies",
            "movies",
            "xtream://movies",
            vec![RemoteMediaItemUpsert {
                id: item_id.clone(),
                name: "Remote Direct Movie".to_string(),
                path: "xtream://movies/Remote Direct Movie [42].mkv".to_string(),
                media_type: "Video".to_string(),
                collection_type: "movies".to_string(),
                runtime_ticks: Some(600_000_000),
                bitrate: Some(1_000_000),
                width: Some(1280),
                height: Some(720),
                media_streams: vec![
                    json!({ "Type": "Video", "Index": 0, "Codec": "h264" }),
                    json!({ "Type": "Audio", "Index": 1, "Codec": "aac", "IsDefault": true }),
                ],
                metadata: json!({
                    "Provider": "xtream",
                    "RemoteSourceUrl": source_url.clone(),
                    "XtreamKind": "vod",
                    "RemoteMediaProbe": {
                        "Status": "Complete",
                        "SourceUrl": source_url
                    }
                }),
            }],
        )
        .await
        .unwrap();
        let test_db = db.clone();
        let app = router(AppState {
            db,
            web_dir: ".".into(),
            log_dir: ".".into(),
            local_address: "http://127.0.0.1:8097".to_string(),
        });

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!("/Items/{item_id}/PlaybackInfo"))
                    .header("X-Emby-Token", &api_key)
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body = response.into_body().collect().await.unwrap().to_bytes();
        let playback_info: Value = serde_json::from_slice(&body).unwrap();
        let media_source = &playback_info["MediaSources"][0];
        assert_eq!(media_source["SupportsDirectPlay"], false);
        assert_eq!(media_source["SupportsDirectStream"], true);
        assert_eq!(media_source["SupportsTranscoding"], false);
        let direct_stream_url = media_source["DirectStreamUrl"].as_str().unwrap();
        assert!(direct_stream_url.starts_with(&format!("/Videos/{item_id}/stream.mkv?")));
        assert!(!direct_stream_url.contains("user/pass"));
        assert!(!direct_stream_url.contains(&upstream_address.to_string()));
        assert_eq!(media_source["TranscodingUrl"], direct_stream_url);
        assert_eq!(media_source["TranscodingContainer"], "mkv");
        assert!(test_db.transcode_sessions().await.unwrap().is_empty());

        let response = app
            .oneshot(
                Request::builder()
                    .uri(direct_stream_url)
                    .header(header::RANGE, "bytes=2-5")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::PARTIAL_CONTENT);
        assert_eq!(response.headers()[header::CONTENT_RANGE], "bytes 2-5/10");
        assert_eq!(response.headers()[header::CONTENT_TYPE], "video/mp4");
        let body = response.into_body().collect().await.unwrap().to_bytes();
        assert_eq!(body.as_ref(), b"cdef");
        upstream.await.unwrap();
    }

