    #[test]
    fn codec_profile_common_operators_use_normalized_stream_values() {
        let item = playback_profile_test_item();
        let options = PlaybackInfoOptions::default();
        let cases = [
            (
                json!({ "Condition": "Equals", "Property": "Width", "Value": 3840, "IsRequired": true }),
                CodecConditionProperty::Width,
            ),
            (
                json!({ "Condition": "NotEquals", "Property": "VideoProfile", "Value": "main", "IsRequired": true }),
                CodecConditionProperty::VideoProfile,
            ),
            (
                json!({ "Condition": "EqualsAny", "Property": "AudioProfile", "Value": "AAC-LC|HE-AAC", "IsRequired": true }),
                CodecConditionProperty::AudioProfile,
            ),
            (
                json!({ "Condition": "NotEqualsAny", "Property": "VideoLevel", "Value": "4.0,4.1", "IsRequired": true }),
                CodecConditionProperty::VideoLevel,
            ),
            (
                json!({ "Condition": "LessThan", "Property": "VideoFramerate", "Value": "60", "IsRequired": true }),
                CodecConditionProperty::VideoFrameRate,
            ),
            (
                json!({ "Condition": "LessThanEqual", "Property": "AudioChannels", "Value": 6, "IsRequired": true }),
                CodecConditionProperty::AudioChannels,
            ),
            (
                json!({ "Condition": "GreaterThan", "Property": "VideoBitrate", "Value": 4_000_000, "IsRequired": true }),
                CodecConditionProperty::VideoBitrate,
            ),
            (
                json!({ "Condition": "GreaterThanEqual", "Property": "VideoBitDepth", "Value": 10, "IsRequired": true }),
                CodecConditionProperty::VideoBitDepth,
            ),
        ];

        for (raw_condition, property) in cases {
            let condition = parse_codec_condition(&raw_condition).unwrap().unwrap();
            assert_eq!(condition.property, property);
            assert!(codec_condition_matches(
                &condition,
                codec_condition_property_value(&item, &options, property),
            ));
        }
    }

