    #[test]
    fn playback_profile_codec_and_transcoding_limits_bound_ffmpeg() {
        let item = playback_profile_test_item();
        let options = playback_info_options_from_body(&json!({
            "DeviceProfile": {
                "TranscodingProfiles": [{
                    "Type": "Video",
                    "Context": "Streaming",
                    "Protocol": "hls",
                    "Container": "ts",
                    "VideoCodec": "h264",
                    "AudioCodec": "aac",
                    "MaxWidth": 1280,
                    "MaxHeight": 720,
                    "VideoBitrate": 2_000_000,
                    "AudioBitrate": 128_000
                }],
                "CodecProfiles": [
                    {
                        "Type": "Video",
                        "Codec": "h264",
                        "Conditions": [
                            { "Condition": "LessThanEqual", "Property": "Width", "Value": "1920", "IsRequired": true },
                            { "Condition": "LessThanEqual", "Property": "Height", "Value": "1080", "IsRequired": true },
                            { "Condition": "LessThanEqual", "Property": "VideoBitrate", "Value": "4000000" }
                        ]
                    },
                    {
                        "Type": "VideoAudio",
                        "Codec": "aac",
                        "Conditions": [
                            { "Condition": "LessThanEqual", "Property": "AudioBitrate", "Value": "256000" }
                        ]
                    }
                ]
            }
        }));

        let decision =
            playback_delivery_decision_with_ffmpeg_mode(&item, None, &options, FfmpegMode::Enabled);
        assert_eq!(decision.delivery, DeliveryMode::HlsTranscode);
        assert_eq!(decision.video, HlsStreamMode::Encode);
        assert_eq!(decision.audio, HlsStreamMode::Encode);
        assert_eq!(decision.output.max_width, Some(1280));
        assert_eq!(decision.output.max_height, Some(720));
        assert_eq!(decision.output.video_bitrate, Some(2_000_000));
        assert_eq!(decision.output.audio_bitrate, Some(128_000));

        let mut request = HlsTranscodeRequest::new(
            "/tmp/input.mkv",
            "/tmp/main.m3u8",
            "/tmp/segment_%05d.ts",
            TranscodeStreamSelection::default(),
        );
        request.video_mode = decision.video;
        request.audio_mode = decision.audio;
        apply_playback_output_constraints(&mut request, decision.output);
        let command = build_hls_ffmpeg_command(&request);
        assert!(
            command
                .args()
                .windows(2)
                .any(|pair| pair == ["-b:v", "2000000"])
        );
        assert!(
            command
                .args()
                .windows(2)
                .any(|pair| pair == ["-b:a", "128000"])
        );
        assert!(command.args().windows(2).any(|pair| {
            pair[0] == "-vf" && pair[1].contains("min(1280,iw)") && pair[1].contains("min(720,ih)")
        }));
    }

