    #[test]
    fn playback_profile_ffmpeg_mode_blocks_expensive_delivery_modes() {
        assert_eq!(parse_ffmpeg_mode(None), Ok(FfmpegMode::RemuxOnly));
        assert_eq!(
            parse_ffmpeg_mode(Some("REMUX-ONLY")),
            Ok(FfmpegMode::RemuxOnly)
        );
        assert_eq!(
            parse_ffmpeg_mode(Some("disabled")),
            Ok(FfmpegMode::Disabled)
        );
        assert!(parse_ffmpeg_mode(Some("invalid")).is_err());

        let item = playback_profile_test_item();
        let metadata = json!({
            "Provider": "xtream",
            "RemoteSourceUrl": "https://provider.example/movie/account/secret/42.mkv"
        });
        let remux_options = PlaybackInfoOptions {
            direct_play_profiles: Some(vec![DirectPlayProfileMatcher {
                profile_type: Some("Video".to_string()),
                containers: vec!["mp4".to_string()],
                video_codecs: vec!["h264".to_string()],
                audio_codecs: vec!["aac".to_string()],
            }]),
            ..PlaybackInfoOptions::default()
        };
        assert_eq!(
            playback_delivery_decision_with_ffmpeg_mode(
                &item,
                Some(&metadata),
                &remux_options,
                FfmpegMode::RemuxOnly,
            )
            .delivery,
            DeliveryMode::HlsRemux
        );
        assert_eq!(
            playback_delivery_decision_with_ffmpeg_mode(
                &item,
                Some(&metadata),
                &remux_options,
                FfmpegMode::Disabled,
            )
            .delivery,
            DeliveryMode::Unsupported
        );

        let capped_options = PlaybackInfoOptions {
            max_streaming_bitrate: Some(4_000_000),
            ..PlaybackInfoOptions::default()
        };
        assert_eq!(
            playback_delivery_decision_with_ffmpeg_mode(
                &item,
                None,
                &capped_options,
                FfmpegMode::RemuxOnly,
            )
            .delivery,
            DeliveryMode::Unsupported
        );
    }

    #[test]
    fn ffmpeg_capability_listing_reads_names_without_accepting_descriptions() {
        let listed = ffmpeg_listing_components(
            "-demuxers",
            " D   mov,mp4,m4a QuickTime / MOV\n D   mpegts MPEG-TS\n D. = Demuxing supported\n",
        );
        for expected in ["mov", "mp4", "m4a", "mpegts"] {
            assert!(listed.contains(expected), "missing {expected}");
        }
        assert!(!listed.contains("QuickTime"));
        assert!(!listed.contains("MPEG-TS"));

        let protocols = ffmpeg_listing_components(
            "-protocols",
            "Supported file protocols:\nInput:\n  https\n  file\nOutput:\n  file\n",
        );
        assert_eq!(protocols, HashSet::from(["https", "file"]));
    }

    #[test]
    fn ffmpeg_guard_policy_covers_every_coordinator_job_kind() {
        for kind in [
            TranscodeJobKind::VideoEncode,
            TranscodeJobKind::AudioEncode,
            TranscodeJobKind::Remux,
            TranscodeJobKind::Auxiliary,
        ] {
            assert!(ffmpeg_job_allowed_for_mode(FfmpegMode::Enabled, kind).is_ok());
            assert!(ffmpeg_job_allowed_for_mode(FfmpegMode::Disabled, kind).is_err());
        }

        assert!(
            ffmpeg_job_allowed_for_mode(FfmpegMode::RemuxOnly, TranscodeJobKind::Remux).is_ok()
        );
        for kind in [
            TranscodeJobKind::VideoEncode,
            TranscodeJobKind::AudioEncode,
            TranscodeJobKind::Auxiliary,
        ] {
            let error = ffmpeg_job_allowed_for_mode(FfmpegMode::RemuxOnly, kind).unwrap_err();
            assert!(error.contains("remux-only"));
        }
    }

    #[cfg(target_os = "linux")]
    #[tokio::test]
    async fn ffmpeg_guard_startup_timeout_reaps_the_child_process() {
        let temp = tempfile::tempdir().unwrap();
        let pid_path = temp.path().join("startup-tool.pid");
        let mut command = tokio::process::Command::new("sh");
        command
            .args([
                "-c",
                "echo $$ > \"$1\"; exec sleep 30",
                "jellyrin-startup-tool",
            ])
            .arg(&pid_path);

        let error = run_startup_command_output(
            command,
            StdDuration::from_millis(200),
            "startup tool timed out",
        )
        .await
        .unwrap_err();
        assert!(error.to_string().contains("startup tool timed out"));
        let pid = tokio::fs::read_to_string(&pid_path)
            .await
            .unwrap()
            .trim()
            .parse::<u32>()
            .unwrap();
        let process_path = PathBuf::from(format!("/proc/{pid}"));
        for _ in 0..100 {
            if !process_path.exists() {
                return;
            }
            tokio::time::sleep(StdDuration::from_millis(10)).await;
        }
        panic!("timed out startup tool process {pid} was not reaped");
    }

