    #[test]
    fn remote_playback_chooses_the_cheapest_hls_mode_per_stream() {
        let now = OffsetDateTime::now_utc();
        let mut item = MediaItem {
            id: Uuid::new_v4(),
            virtual_folder_id: Uuid::new_v4(),
            name: "Remote fixture".to_string(),
            path: "xtream://movies/Remote fixture.mkv".to_string(),
            media_type: "Video".to_string(),
            collection_type: Some("movies".to_string()),
            file_size: None,
            runtime_ticks: Some(600_000_000),
            bitrate: Some(4_000_000),
            width: Some(1920),
            height: Some(1080),
            media_streams: vec![
                json!({ "Type": "Video", "Index": 0, "Codec": "h264" }),
                json!({ "Type": "Audio", "Index": 1, "Codec": "aac", "IsDefault": true }),
            ],
            created_at: now,
            updated_at: now,
        };
        let metadata = json!({
            "Provider": "xtream",
            "RemoteSourceUrl": "https://provider.example/movie/account/secret/42.mkv"
        });
        let options = PlaybackInfoOptions {
            direct_play_profiles: Some(vec![DirectPlayProfileMatcher {
                profile_type: Some("Video".to_string()),
                containers: vec!["mp4".to_string()],
                video_codecs: vec!["h264".to_string()],
                audio_codecs: vec!["aac".to_string()],
            }]),
            ..PlaybackInfoOptions::default()
        };

        let remux = playback_delivery_decision(&item, Some(&metadata), &options);
        assert_eq!(remux.delivery, DeliveryMode::HlsRemux);
        assert_eq!(remux.video, HlsStreamMode::Copy);
        assert_eq!(remux.audio, HlsStreamMode::Copy);

        item.media_streams[1]["Codec"] = json!("ac3");
        let audio_only = playback_delivery_decision(&item, Some(&metadata), &options);
        assert_eq!(audio_only.delivery, DeliveryMode::HlsTranscode);
        assert_eq!(audio_only.video, HlsStreamMode::Copy);
        assert_eq!(audio_only.audio, HlsStreamMode::Encode);

        item.media_streams[0]["Codec"] = json!("hevc");
        item.media_streams[1]["Codec"] = json!("aac");
        let video_only = playback_delivery_decision(&item, Some(&metadata), &options);
        assert_eq!(video_only.delivery, DeliveryMode::HlsTranscode);
        assert_eq!(video_only.video, HlsStreamMode::Encode);
        assert_eq!(video_only.audio, HlsStreamMode::Copy);

        item.media_streams.push(json!({
            "Type": "Subtitle",
            "Index": 2,
            "Codec": "subrip",
            "DisplayTitle": "English - SRT - Default"
        }));
        let hevc_subtitle_options = playback_info_options_from_body(&json!({
            "EnableDirectPlay": true,
            "EnableDirectStream": true,
            "EnableTranscoding": true,
            "SubtitleStreamIndex": 2,
            "DeviceProfile": {
                "DirectPlayProfiles": [{
                    "Type": "Video",
                    "Container": "mkv",
                    "VideoCodec": "hevc",
                    "AudioCodec": "aac"
                }],
                "TranscodingProfiles": [{
                    "Type": "Video",
                    "Context": "Streaming",
                    "Protocol": "hls",
                    "Container": "ts",
                    "VideoCodec": "h264",
                    "AudioCodec": "aac"
                }],
                "SubtitleProfiles": [{
                    "Format": "vtt",
                    "Method": "External"
                }]
            }
        }));
        let subtitle_only =
            playback_delivery_decision(&item, Some(&metadata), &hevc_subtitle_options);
        assert_eq!(subtitle_only.delivery, DeliveryMode::DirectProxy);
        assert_eq!(subtitle_only.video, HlsStreamMode::Copy);
        assert_eq!(subtitle_only.audio, HlsStreamMode::Copy);
        assert!(subtitle_only.reasons.is_empty());

        let mut media_source = json!({
            "MediaStreams": item.media_streams.clone()
        });
        apply_direct_external_text_subtitle_contract(
            media_source.as_object_mut().unwrap(),
            "secret-token",
            "episode-id",
            "play-session",
            false,
        );
        let subtitle = &media_source["MediaStreams"][2];
        assert_eq!(subtitle["Codec"], "webvtt");
        assert_eq!(subtitle["DeliveryMethod"], "External");
        assert_eq!(subtitle["SupportsExternalStream"], true);
        assert_eq!(
            subtitle["DeliveryUrl"],
            "/Videos/episode-id/episode-id/Subtitles/2/Stream.vtt?api_key=secret-token&PlaySessionId=play-session&JellyrinSegmented=true&StartPositionTicks=0&EndPositionTicks=300000000"
        );

        let mut android_options = hevc_subtitle_options.clone();
        apply_android_remote_subtitle_hls_policy(
            &item,
            Some(&metadata),
            "Jellyfin for Android",
            &mut android_options,
        );
        let android = playback_delivery_decision(&item, Some(&metadata), &android_options);
        assert_eq!(android.delivery, DeliveryMode::HlsRemux);
        assert_eq!(android.video, HlsStreamMode::Copy);
        assert_eq!(android.audio, HlsStreamMode::Copy);
        assert!(selected_text_subtitle_prefers_hls(&android_options));
        assert!(android_options.hls_subtitles_as_embedded);
        assert!(
            android_options
                .transcoding_profiles
                .as_ref()
                .unwrap()
                .iter()
                .any(|profile| profile.video_codecs.iter().any(|codec| codec == "hevc"))
        );

        let mut android_media_source = json!({
            "IsRemote": true,
            "MediaStreams": item.media_streams.clone()
        });
        apply_hls_transcode_stream_contract(
            android_media_source.as_object_mut().unwrap(),
            "Video",
            "secret-token",
            "episode-id",
            "play-session",
            &android_options,
            &android,
        );
        let android_subtitle = &android_media_source["MediaStreams"][2];
        assert_eq!(android_subtitle["DisplayTitle"], "English - SRT - Default");
        assert_eq!(android_subtitle["DeliveryMethod"], "Embed");
        assert_eq!(android_subtitle["IsExternal"], false);
        assert_eq!(android_subtitle["SupportsExternalStream"], false);
        assert!(android_subtitle.get("DeliveryUrl").is_none());
        let android_response = super::playback_transcode_session_info_response(
            json!({
                "MediaSources": [{
                    "IsRemote": true,
                    "MediaStreams": item.media_streams.clone()
                }]
            }),
            "Video",
            "secret-token",
            "episode-id",
            "play-session",
            &android_options,
            &android,
        )
        .unwrap()
        .0;
        assert_eq!(
            android_response["MediaSources"][0]["SupportsDirectStream"],
            false
        );
        assert!(
            android_response["MediaSources"][0]["TranscodingUrl"]
                .as_str()
                .unwrap()
                .contains("/master.m3u8?")
        );

        let selection_two = TranscodeStreamSelection {
            video_stream_index: Some(0),
            audio_stream_index: Some(1),
            subtitle_stream_index: Some(2),
        };
        let selection_three = TranscodeStreamSelection {
            subtitle_stream_index: Some(3),
            ..selection_two.clone()
        };
        assert_ne!(
            playback_hls_transcode_dedupe_key(
                Uuid::nil(),
                &item,
                &selection_two,
                0,
                android.video,
                android.audio,
            ),
            playback_hls_transcode_dedupe_key(
                Uuid::nil(),
                &item,
                &selection_three,
                0,
                android.video,
                android.audio,
            )
        );

        let no_hls_subtitles = PlaybackInfoOptions {
            subtitle_profiles: None,
            ..hevc_subtitle_options
        };
        let fallback = playback_delivery_decision(&item, Some(&metadata), &no_hls_subtitles);
        assert_eq!(fallback.delivery, DeliveryMode::HlsTranscode);
        assert_eq!(fallback.video, HlsStreamMode::Encode);
        assert_eq!(fallback.output.video_bitrate, Some(8_000_000));
    }

