    #[tokio::test]
    async fn public_users_hides_configured_users_after_startup() {
        let db = Database::connect("sqlite::memory:").await.unwrap();
        let admin = db
            .update_first_user("admin".to_string(), "admin-secret")
            .await
            .unwrap();
        let api_key = db
            .issue_api_key_for_user(admin.id, "test-key")
            .await
            .unwrap();
        db.upsert_admin_user("jellyrin-e2e-admin", "e2e-secret")
            .await
            .unwrap();
        let _ = db.server_state().await.unwrap();
        let app_before_startup_complete = router(AppState {
            db: db.clone(),
            web_dir: ".".into(),
            log_dir: ".".into(),
            local_address: "http://127.0.0.1:8097".to_string(),
        });

        let response = app_before_startup_complete
            .oneshot(
                Request::builder()
                    .uri("/Users/Public")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body = response.into_body().collect().await.unwrap().to_bytes();
        let users: Value = serde_json::from_slice(&body).unwrap();
        assert_eq!(users.as_array().unwrap().len(), 0);

        db.complete_startup_wizard().await.unwrap();
        let app = router(AppState {
            db,
            web_dir: ".".into(),
            log_dir: ".".into(),
            local_address: "http://127.0.0.1:8097".to_string(),
        });

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri("/Users/Public")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body = response.into_body().collect().await.unwrap().to_bytes();
        let users: Value = serde_json::from_slice(&body).unwrap();
        assert_eq!(users.as_array().unwrap().len(), 0);

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri("/Users")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::UNAUTHORIZED);

        for endpoint in ["/Users", "/users"] {
            let response = app
                .clone()
                .oneshot(
                    Request::builder()
                        .uri(endpoint)
                        .header("X-Emby-Token", &api_key)
                        .body(Body::empty())
                        .unwrap(),
                )
                .await
                .unwrap();
            assert_eq!(response.status(), StatusCode::OK, "{endpoint}");
            let body = response.into_body().collect().await.unwrap().to_bytes();
            let users: Value = serde_json::from_slice(&body).unwrap();
            assert_eq!(users.as_array().unwrap().len(), 2);
            assert!(
                users
                    .as_array()
                    .unwrap()
                    .iter()
                    .all(|user| user["Policy"]["IsAdministrator"] == true)
            );
            assert_eq!(
                users[0]["Policy"]["AuthenticationProviderId"],
                DEFAULT_AUTHENTICATION_PROVIDER_ID
            );
            assert_eq!(
                users[0]["Policy"]["PasswordResetProviderId"],
                DEFAULT_PASSWORD_RESET_PROVIDER_ID
            );
        }
    }

