        // (c) After dropping the first channel's guard (refcount -> 0 removes handle),
        //     the second distinct channel must open successfully (recovery).
        #[tokio::test]
        async fn live_tv_tuner_limit_recovery_after_close() {
            use crate::{live_stream_registry, proxy_live_tv_channel_url};

            let (base_url, _counter, _close) = start_stream_server().await;
            let url_a = format!("{base_url}/auto/v4.1_recovery_a");
            let url_b = format!("{base_url}/auto/v5.1_recovery_b");

            live_stream_registry().lock().await.remove(&url_a);
            live_stream_registry().lock().await.remove(&url_b);

            let tuner_host_id = Some("tuner-host-recover".to_string());
            let tuner_count = Some(1u64);

            // Open channel A (limit=1, slot consumed).
            let resp_a =
                proxy_live_tv_channel_url(url_a.clone(), tuner_host_id.clone(), tuner_count)
                    .await
                    .expect("channel A open must succeed");

            // Drop channel A body -> guard fires -> refcount reaches 0 -> handle removed.
            drop(resp_a.into_body());
            tokio::time::sleep(tokio::time::Duration::from_millis(150)).await;

            // Verify channel A handle is gone from the registry.
            assert!(
                live_stream_registry().lock().await.get(&url_a).is_none(),
                "channel A handle must be removed after refcount reaches 0"
            );

            // Open channel B now: the tuner slot was released, so this must succeed.
            let resp_b =
                proxy_live_tv_channel_url(url_b.clone(), tuner_host_id.clone(), tuner_count)
                    .await
                    .expect(
                        "channel B must open successfully after channel A is closed (recovery)",
                    );
            assert_eq!(resp_b.status(), axum::http::StatusCode::OK);

            drop(resp_b.into_body());
            tokio::time::sleep(tokio::time::Duration::from_millis(100)).await;
            live_stream_registry().lock().await.remove(&url_a);
            live_stream_registry().lock().await.remove(&url_b);
        }

        #[tokio::test]
        async fn live_tv_direct_consumer_lease_survives_shared_handle_removal() {
            use crate::{live_stream_registry, proxy_live_tv_channel_url};

            let (base_url, _counter, _close) = start_stream_server().await;
            let url_a = format!("{base_url}/auto/v4.1_consumer_lease_a");
            let url_b = format!("{base_url}/auto/v5.1_consumer_lease_b");
            let tuner_host_id = Some("tuner-host-consumer-lease".to_string());
            let tuner_count = Some(1u64);

            live_stream_registry().lock().await.remove(&url_a);
            live_stream_registry().lock().await.remove(&url_b);
            crate::live_tuner_lease_registry()
                .lock()
                .expect("live tuner lease registry")
                .retain(|key, _| {
                    !key.tuner_host_id.eq_ignore_ascii_case(
                        tuner_host_id.as_deref().expect("host id must be present"),
                    )
                });

            let resp_a =
                proxy_live_tv_channel_url(url_a.clone(), tuner_host_id.clone(), tuner_count)
                    .await
                    .expect("channel A open must succeed");

            // Simulate producer/handle cleanup racing ahead of the HTTP response body lifetime.
            // The per-consumer guard must keep the tuner slot occupied until resp_a is dropped.
            live_stream_registry().lock().await.remove(&url_a);
            assert!(
                crate::acquire_live_tuner_lease(tuner_host_id.clone(), &url_b, tuner_count)
                    .is_err(),
                "channel B must still conflict while the direct response body is alive"
            );

            drop(resp_a.into_body());
            tokio::time::sleep(tokio::time::Duration::from_millis(100)).await;

            let lease_b =
                crate::acquire_live_tuner_lease(tuner_host_id.clone(), &url_b, tuner_count)
                    .expect("channel B must acquire after the direct response body is dropped");
            assert!(lease_b.is_some());
            drop(lease_b);

            live_stream_registry().lock().await.remove(&url_a);
            live_stream_registry().lock().await.remove(&url_b);
            crate::live_tuner_lease_registry()
                .lock()
                .expect("live tuner lease registry")
                .retain(|key, _| {
                    !key.tuner_host_id.eq_ignore_ascii_case(
                        tuner_host_id.as_deref().expect("host id must be present"),
                    )
                });
        }

        #[tokio::test]
        async fn provider_boundary_opaque_same_channel_counts_each_live_response() {
            let host = "opaque-unshared-tuner";
            let channel_id = "opaque-channel-one";
            crate::live_tuner_lease_registry()
                .lock()
                .expect("live tuner lease registry")
                .retain(|key, _| !key.tuner_host_id.eq_ignore_ascii_case(host));
            let (base_url, connection_count, close_server) = start_stream_server().await;
            let source_url = format!("{base_url}/opaque/same-channel");

            let first_lease = crate::acquire_unshared_live_tuner_lease(
                Some(host.to_string()),
                channel_id,
                Some(1),
            )
            .expect("first opaque response must acquire its tuner slot");
            let first_response = crate::stream_sensitive_remote_live(
                jellyrin_plugin_sdk::SensitiveUrl::new(source_url.clone()),
                &axum::http::HeaderMap::new(),
                false,
                first_lease,
            )
            .await
            .expect("first opaque response must open its upstream");
            assert_eq!(first_response.status(), axum::http::StatusCode::OK);
            assert_eq!(connection_count.load(AtomicOrdering::SeqCst), 1);

            // A second request for the same channel would open another provider connection, so it
            // must consume another slot rather than sharing the first response's lease identity.
            let second_response = async {
                let lease = crate::acquire_unshared_live_tuner_lease(
                    Some(host.to_string()),
                    channel_id,
                    Some(1),
                )?;
                crate::stream_sensitive_remote_live(
                    jellyrin_plugin_sdk::SensitiveUrl::new(source_url.clone()),
                    &axum::http::HeaderMap::new(),
                    false,
                    lease,
                )
                .await
            }
            .await;
            assert!(
                second_response.is_err(),
                "same-channel opaque response must honor TunerCount=1"
            );
            assert_eq!(
                connection_count.load(AtomicOrdering::SeqCst),
                1,
                "rejected response must not reach the provider"
            );

            drop(first_response.into_body());
            let recovered_lease = crate::acquire_unshared_live_tuner_lease(
                Some(host.to_string()),
                channel_id,
                Some(1),
            )
            .expect("dropping the response body must release its tuner slot");
            assert!(recovered_lease.is_some());
            drop(recovered_lease);

            crate::live_tuner_lease_registry()
                .lock()
                .expect("live tuner lease registry")
                .retain(|key, _| !key.tuner_host_id.eq_ignore_ascii_case(host));
            close_server();
        }

        #[tokio::test]
        async fn live_tuner_lease_same_channel_across_modes_shares_slot() {
            let host = "lease-host-same";
            let url = "http://127.0.0.1:19001/auto/v4.1";
            crate::live_tuner_lease_registry()
                .lock()
                .expect("live tuner lease registry")
                .retain(|key, _| !key.tuner_host_id.eq_ignore_ascii_case(host));

            let lease_a = crate::acquire_live_tuner_lease(Some(host.to_string()), url, Some(1))
                .expect("first lease must succeed");
            let lease_b =
                crate::acquire_live_tuner_lease(Some(host.to_ascii_uppercase()), url, Some(1))
                    .expect("same channel must share the tuner slot despite host-id casing");
            assert!(lease_a.is_some());
            assert!(lease_b.is_some());

            {
                let registry = crate::live_tuner_lease_registry()
                    .lock()
                    .expect("live tuner lease registry");
                let key = crate::LiveTunerLeaseKey {
                    tuner_host_id: host.to_string(),
                    channel_url: url.to_string(),
                };
                assert_eq!(
                    registry.get(&key).map(|lease| lease.refcount),
                    Some(2),
                    "same channel across modes should increment the shared lease refcount"
                );
            }

            let other_channel = crate::acquire_live_tuner_lease(
                Some(host.to_string()),
                "http://127.0.0.1:19001/auto/v5.1",
                Some(1),
            );
            assert!(
                other_channel.is_err(),
                "different channel must conflict while the shared same-channel slot is active"
            );

            drop(lease_a);
            drop(lease_b);
            crate::live_tuner_lease_registry()
                .lock()
                .expect("live tuner lease registry")
                .retain(|key, _| !key.tuner_host_id.eq_ignore_ascii_case(host));
        }

