        #[test]
        fn resource_caps_global_tuner_registry_rejects_new_active_key() {
            let mut leases = std::collections::HashMap::new();
            for index in 0..crate::LIVE_TV_MAX_DISTINCT_PRODUCERS {
                leases.insert(
                    crate::LiveTunerLeaseKey {
                        tuner_host_id: format!("global-cap-host-{index}"),
                        channel_url: format!("http://example.invalid/{index}"),
                    },
                    crate::LiveTunerLease { refcount: 1 },
                );
            }
            let overflow = crate::LiveTunerLeaseKey {
                tuner_host_id: "global-cap-overflow".to_string(),
                channel_url: "http://example.invalid/overflow".to_string(),
            };
            let error = crate::ensure_live_tuner_lease_capacity(&leases, &overflow, None)
                .expect_err("all-active global lease registry must fail closed");
            assert_eq!(error.status(), crate::StatusCode::SERVICE_UNAVAILABLE);
            assert_eq!(leases.len(), crate::LIVE_TV_MAX_DISTINCT_PRODUCERS);

            let existing = leases.keys().next().unwrap();
            assert!(crate::ensure_live_tuner_lease_capacity(&leases, existing, None).is_ok());
        }

        #[test]
        fn resource_caps_global_shared_stream_registry_rejects_new_producer() {
            let mut registry = std::collections::HashMap::new();
            for index in 0..crate::LIVE_TV_MAX_DISTINCT_PRODUCERS {
                let (sender, _) = tokio::sync::broadcast::channel(1);
                let (cancel, _) = tokio::sync::oneshot::channel();
                registry.insert(
                    format!("stream-{index}"),
                    crate::SharedLiveStreamHandle {
                        refcount: 1,
                        generation: index as u64,
                        sender,
                        _cancel: cancel,
                        _tuner_lease: None,
                    },
                );
            }
            let error = crate::ensure_live_stream_producer_capacity(&registry, "overflow")
                .expect_err("all-active shared producer registry must fail closed");
            assert_eq!(error.status(), crate::StatusCode::SERVICE_UNAVAILABLE);
            assert!(crate::ensure_live_stream_producer_capacity(&registry, "stream-0").is_ok());
        }

